ist(): VNode {\n\tconst allSessions = sessionStore.sessions.value;\n\tconst activeKey = sessionStore.activeSessionKey.value;\n\tconst refreshingKey = sessionStore.refreshInProgressKey.value;\n\tconst filterId = projectStore.projectFilterId.value;\n\tconst tab = sessionStore.sessionListTab.value;\n\tconst showArchived = sessionStore.showArchivedSessions.value;\n\n\t// Spinner animation via setInterval\n\tconst spinnersRef = useRef<HTMLDivElement>(null);\n\tuseEffect(() => {\n\t\tlet idx = 0;\n\t\tconst timer = setInterval(() => {\n\t\t\tidx = (idx + 1) % spinnerFrames.length;\n\t\t\tif (!spinnersRef.current) return;\n\t\t\tconst els = spinnersRef.current.querySelectorAll(\n\t\t\t\t\".session-item.replying .session-spinner, .session-item.loading .session-spinner\",\n\t\t\t);\n\t\t\tfor (const el of els) el.textContent = spinnerFrames[idx];\n\t\t}, 80);\n\t\treturn () => clearInterval(timer);\n\t}, []);\n\n\tlet filtered = filterId ? allSessions.filter((s) => s.projectId === filterId) : allSessions;\n\tif (tab === \"sessions\") {\n\t\tfiltered = filtered.filter((s) => !(s.key || \"\").startsWith(\"cron:\") && (showArchived || !s.archived));\n\t} else if (tab === \"cron\") {\n\t\tfiltered = filtered.filter((s) => (s.key || \"\").startsWith(\"cron:\"));\n\t}\n\n\t// Build parent→children map for tree rendering\n\tconst childrenMap: Record<string, Session[]> = {};\n\tconst keyMap: KeyMap = {};\n\tfiltered.forEach((s) => {\n\t\tkeyMap[s.key] = s;\n\t\tif (s.parentSessionKey) {\n\t\t\tif (!childrenMap[s.parentSessionKey]) childrenMap[s.parentSessionKey] = [];\n\t\t\tchildrenMap[s.parentSessionKey].push(s);\n\t\t}\n\t});\n\tconst roots = filtered.filter((s) => !(s.parentSessionKey && keyMap[s.parentSessionKey]));\n\n\tfunction renderTree(session: Session, depth: number): VNode {\n\t\tconst children = childrenMap[session.key] || [];\n\t\treturn (\n\t\t\t<>\n\t\t\t\t<SessionItem\n\t\t\t\t\tkey={session.key}\n\t\t\t\t\tsession={session}\n\t\t\t\t\tactiveKey={activeKey}\n\t\t\t\t\tdepth={depth}\n\t\t\t\t\tkeyMap={keyMap}\n\t\t\t\t\trefreshing={session.key === refreshingKey}\n\t\t\t\t/>\n\t\t\t\t{children.map((child) => renderTree(child, depth + 1))}\n\t\t\t</>\n\t\t);\n\t}\n\n\treturn (\n\t\t<div ref={spinnersRef}>\n\t\t\t{roots.map((s) => renderTree(s, 0))}\n\t\t</div>\n\t);\n}\n","// Mobile navigation and panel handling\n\nlet navPanel: HTMLElement | null = null;\nlet navOverlay: HTMLElement | null = null;\nlet sessionsPanel: HTMLElement | null = null;\nlet sessionsOverlay: HTMLElement | null = null;\nlet sessionsToggle: HTMLElement | null = null;\nlet burgerBtn: HTMLElement | null = null;\n\n// Check if we're in mobile view\nfunction isMobile(): boolean {\n\treturn window.innerWidth < 768;\n}\n\n// Open navigation panel\nfunction openNav(): void {\n\tif (!(navPanel && navOverlay)) return;\n\tnavPanel.classList.add(\"open\");\n\tnavOverlay.classList.add(\"visible\");\n\tdocument.body.style.overflow = \"hidden\";\n}\n\n// Close navigation panel\nfunction closeNav(): void {\n\tif (!(navPanel && navOverlay)) return;\n\tnavPanel.classList.remove(\"open\");\n\tnavOverlay.classList.remove(\"visible\");\n\tif (!sessionsPanel?.classList.contains(\"open\")) {\n\t\tdocument.body.style.overflow = \"\";\n\t}\n}\n\n// Toggle navigation panel\nfunction toggleNav(): void {\n\tif (navPanel?.classList.contains(\"open\")) {\n\t\tcloseNav();\n\t} else {\n\t\topenNav();\n\t}\n}\n\n// Open sessions panel\nfunction openSessions(): void {\n\tif (!(sessionsPanel && sessionsOverlay)) return;\n\tsessionsPanel.classList.add(\"open\");\n\tsessionsPanel.classList.remove(\"hidden\");\n\tsessionsOverlay.classList.add(\"visible\");\n\tif (sessionsToggle) sessionsToggle.classList.add(\"hidden\");\n\tdocument.body.style.overflow = \"hidden\";\n}\n\n// Close sessions panel\nfunction closeSessions(): void {\n\tif (!(sessionsPanel && sessionsOverlay)) return;\n\tsessionsPanel.classList.remove(\"open\");\n\tsessionsOverlay.classList.remove(\"visible\");\n\tif (sessionsToggle) sessionsToggle.classList.remove(\"hidden\");\n\tif (!navPanel?.classList.contains(\"open\")) {\n\t\tdocument.body.style.overflow = \"\";\n\t}\n\t// On mobile, also add hidden after transition\n\tif (isMobile()) {\n\t\tsetTimeout(() => {\n\t\t\tif (!sessionsPanel?.classList.contains(\"open\")) {\n\t\t\t\tsessionsPanel?.classList.add(\"hidden\");\n\t\t\t}\n\t\t}, 300);\n\t}\n}\n\n// Toggle sessions panel\nfunction toggleSessions(): void {\n\tif (sessionsPanel?.classList.contains(\"open\")) {\n\t\tcloseSessions();\n\t} else {\n\t\topenSessions();\n\t}\n}\n\n// Handle nav link clicks - close nav on mobile after navigation\nfunction handleNavClick(e: Event): void {\n\tif (isMobile() && (e.target as HTMLElement).closest(\".nav-link\")) {\n\t\tcloseNav();\n\t}\n}\n\n// Handle session item clicks - close sessions on mobile after selection\nfunction handleSessionClick(e: Event): void {\n\tif (isMobile() && (e.target as HTMLElement).closest(\".session-item\")) {\n\t\tsetTimeout(closeSessions, 100);\n\t}\n}\n\n// Handle resize - reset states when switching between mobile/desktop\nfunction handleResize(): void {\n\tif (isMobile()) {\n\t\t// Mobile view - show toggle button if sessions panel is not open\n\t\tif (!sessionsPanel?.classList.contains(\"open\")) {\n\t\t\tsessionsToggle?.classList.remove(\"hidden\");\n\t\t}\n\t} else {\n\t\t// Desktop view - reset mobile-specific states\n\t\tnavPanel?.classList.remove(\"open\");\n\t\tnavOverlay?.classList.remove(\"visible\");\n\t\tsessionsOverlay?.classList.remove(\"visible\");\n\t\tsessionsToggle?.classList.add(\"hidden\");\n\t\tdocument.body.style.overflow = \"\";\n\n\t\t// On desktop, sessions panel visibility is controlled differently\n\t\t// Remove open class but don't add hidden (let desktop CSS handle it)\n\t\tsessionsPanel?.classList.remove(\"open\");\n\t}\n}\n\n// Initialize mobile interactions\nexport function initMobile(): void {\n\tnavPanel = document.getElementById(\"navPanel\");\n\tnavOverlay = document.getElementById(\"navOverlay\");\n\tsessionsPanel = document.getElementById(\"sessionsPanel\");\n\tsessionsOverlay = document.getElementById(\"sessionsOverlay\");\n\tsessionsToggle = document.getElementById(\"sessionsToggle\");\n\tburgerBtn = document.getElementById(\"burgerBtn\");\n\n\t// Burger button toggles nav\n\tif (burgerBtn) {\n\t\tburgerBtn.addEventListener(\"click\", toggleNav);\n\t}\n\n\t// Overlay clicks close their respective panels\n\tif (navOverlay) {\n\t\tnavOverlay.addEventListener(\"click\", closeNav);\n\t}\n\n\tif (sessionsOverlay) {\n\t\tsessionsOverlay.addEventListener(\"click\", closeSessions);\n\t}\n\n\t// Sessions toggle FAB\n\tif (sessionsToggle) {\n\t\tsessionsToggle.addEventListener(\"click\", toggleSessions);\n\t\t// Initially hide on desktop\n\t\tif (!isMobile()) {\n\t\t\tsessionsToggle.classList.add(\"hidden\");\n\t\t}\n\t}\n\n\t// Close nav when clicking nav links on mobile\n\tif (navPanel) {\n\t\tnavPanel.addEventListener(\"click\", handleNavClick);\n\t}\n\n\t// Close sessions when clicking session items on mobile\n\tif (sessionsPanel) {\n\t\tsessionsPanel.addEventListener(\"click\", handleSessionClick);\n\t}\n\n\t// Handle resize events\n\twindow.addEventListener(\"resize\", handleResize);\n\n\t// Escape key closes panels\n\tdocument.addEventListener(\"keydown\", (e: KeyboardEvent) => {\n\t\tif (e.key === \"Escape\") {\n\t\t\tif (navPanel?.classList.contains(\"open\")) {\n\t\t\t\tcloseNav();\n\t\t\t}\n\t\t\tif (sessionsPanel?.classList.contains(\"open\") && isMobile()) {\n\t\t\t\tcloseSessions();\n\t\t\t}\n\t\t}\n\t});\n\n\t// Touch gestures for bottom sheet (sessions panel)\n\tif (sessionsPanel) {\n\t\tsetupBottomSheetGestures(sessionsPanel);\n\t}\n}\n\n// Simple swipe-down gesture to close bottom sheet\nfunction setupBottomSheetGestures(panel: HTMLElement): void {\n\tlet startY = 0;\n\tlet currentY = 0;\n\tlet isDragging = false;\n\n\tpanel.addEventListener(\n\t\t\"touchstart\",\n\t\t(e: TouchEvent) => {\n\t\t\t// Only initiate drag from the top area (drag handle region)\n\t\t\tconst touch = e.touches[0];\n\t\t\tconst panelRect = panel.getBoundingClientRect();\n\t\t\tif (touch.clientY - panelRect.top < 40) {\n\t\t\t\tstartY = touch.clientY;\n\t\t\t\tisDragging = true;\n\t\t\t}\n\t\t},\n\t\t{ passive: true },\n\t);\n\n\tpanel.addEventListener(\n\t\t\"touchmove\",\n\t\t(e: TouchEvent) => {\n\t\t\tif (!isDragging) return;\n\t\t\tcurrentY = e.touches[0].clientY;\n\t\t\tconst deltaY = currentY - startY;\n\n\t\t\t// Only allow dragging down\n\t\t\tif (deltaY > 0) {\n\t\t\t\tpanel.style.transform = `translateY(${deltaY}px)`;\n\t\t\t}\n\t\t},\n\t\t{ passive: true },\n\t);\n\n\tpanel.addEventListener(\n\t\t\"touchend\",\n\t\t() => {\n\t\t\tif (!isDragging) return;\n\t\t\tisDragging = false;\n\n\t\t\tconst deltaY = currentY - startY;\n\t\t\tpanel.style.transform = \"\";\n\n\t\t\t// Close if dragged more than 100px down\n\t\t\tif (deltaY > 100) {\n\t\t\t\tcloseSessions();\n\t\t\t}\n\t\t},\n\t\t{ passive: true },\n\t);\n}\n\n// Export functions for external use\nexport { closeNav, closeSessions, isMobile, openNav, openSessions, toggleNav, toggleSessions };\n","// ── SessionHeader Preact component ───────────────────────────\n//\n// Replaces the imperative updateChatSessionHeader() with a reactive\n// Preact component reading sessionStore.activeSession.\n\nimport type { VNode } from \"preact\";\nimport { useCallback, useEffect, useRef, useState } from \"preact/hooks\";\nimport { onEvent } from \"../events\";\nimport * as gon from \"../gon\";\nimport { parseAgentsListPayload, sendRpc } from \"../helpers\";\nimport {\n\tclearActiveSession,\n\tfetchSessions,\n\tisArchivableSession,\n\tremoveSessionFromClientState,\n\tsetSessionActiveRunId,\n\tsetSessionReplying,\n\tswitchSession,\n} from \"../sessions\";\nimport { sessionStore } from \"../stores/session-store\";\nimport type { SessionMeta } from \"../types\";\nimport { ComboSelect, confirmDialog, shareLinkDialog, shareVisibilityDialog, showToast } from \"../ui\";\n\n// ── Types ────────────────────────────────────────────────────\n\ninterface NodeInfo {\n\tnodeId: string;\n\tdisplayName?: string;\n\tplatform?: string;\n\t[key: string]: unknown;\n}\n\ninterface AgentOption {\n\tid: string;\n\tname: string;\n\temoji?: string;\n\tis_default?: boolean;\n\t[key: string]: unknown;\n}\n\ninterface SelectOption {\n\tvalue: string;\n\tlabel: string;\n}\n\ninterface SharePayload {\n\tpath?: string;\n\taccessKey?: string;\n}\n\nexport interface SessionHeaderProps {\n\tshowSelectors?: boolean;\n\tshowName?: boolean;\n\tshowShare?: boolean;\n\tshowFork?: boolean;\n\tshowStop?: boolean;\n\tshowClear?: boolean;\n\tshowDelete?: boolean;\n\tshowArchive?: boolean;\n\tnameOwnLine?: boolean;\n\tshowRenameButton?: boolean;\n\tactionButtonClass?: string;\n\tonBeforeShare?: (() => void) | null;\n\tonBeforeArchive?: (() => void) | null;\n\tonBeforeDelete?: (() => void) | null;\n}\n\n// ── Helpers ──────────────────────────────────────────────────\n\nfunction nextSessionKey(currentKey: string): string {\n\tconst allSessions = sessionStore.sessions.value;\n\tconst s = allSessions.find((x) => x.key === currentKey);\n\tif (s?.parentSessionKey) return s.parentSessionKey;\n\tconst idx = allSessions.findIndex((x) => x.key === currentKey);\n\tif (idx >= 0 && idx + 1 < allSessions.length) return allSessions[idx + 1].key;\n\tif (idx > 0) return allSessions[idx - 1].key;\n\treturn \"main\";\n}\n\nfunction buildShareUrl(payload: SharePayload): string {\n\tlet url = `${window.location.origin}${payload.path}`;\n\tif (payload.accessKey) {\n\t\turl += `?k=${encodeURIComponent(payload.accessKey)}`;\n\t}\n\treturn url;\n}\n\nfunction isSshTargetNode(node: NodeInfo | null): boolean {\n\treturn node?.platform === \"ssh\" || String(node?.nodeId || \"\").startsWith(\"ssh:\");\n}\n\nfunction nodeOptionLabel(node: NodeInfo | null): string {\n\tif (!node) return \"Local\";\n\tif (node.displayName) return node.displayName;\n\tif (isSshTargetNode(node)) {\n\t\tconst target = String(node.nodeId || \"\").replace(/^ssh:/, \"\");\n\t\treturn `SSH: ${target}`;\n\t}\n\treturn node.nodeId;\n}\n\nasync function copyShareUrl(url: string, visibility: string): Promise<void> {\n\ttry {\n\t\tif (navigator.clipboard?.writeText) {\n\t\t\tawait navigator.clipboard.writeText(url);\n\t\t\tshowToast(\"Share link copied\", \"success\");\n\t\t\treturn;\n\t\t}\n\t} catch (_err) {\n\t\t// Clipboard APIs can fail on some browsers/permissions.\n\t}\n\tawait shareLinkDialog(url, visibility);\n}\n\n// ── Component ────────────────────────────────────────────────\n\nexport function SessionHeader({\n\tshowSelectors = true,\n\tshowName = true,\n\tshowShare = true,\n\tshowFork = true,\n\tshowStop = true,\n\tshowClear = true,\n\tshowDelete = true,\n\tshowArchive = true,\n\tnameOwnLine = false,\n\tshowRenameButton = false,\n\tactionButtonClass = \"chat-session-btn\",\n\tonBeforeShare = null,\n\tonBeforeArchive = null,\n\tonBeforeDelete = null,\n}: SessionHeaderProps = {}): VNode {\n\tconst session = sessionStore.activeSession.value;\n\tconst sessionDataVersion = session?.dataVersion.value || 0;\n\tconst currentKey = sessionStore.activeSessionKey.value;\n\tconst gonAgentsPayload = parseAgentsListPayload(gon.get(\"agents\") as never);\n\tconst initialAgentOptions: AgentOption[] = Array.isArray(gonAgentsPayload?.agents) ? (gonAgentsPayload.agents as AgentOption[]) : [];\n\tconst initialDefaultAgentId = typeof gonAgentsPayload?.defaultId === \"string\" ? gonAgentsPayload.defaultId : \"main\";\n\n\tconst [renaming, setRenaming] = useState(false);\n\tconst [clearing, setClearing] = useState(false);\n\tconst [stopping, setStopping] = useState(false);\n\tconst [switchingAgent, setSwitchingAgent] = useState(false);\n\tconst [agentOptions, setAgentOptions] = useState<AgentOption[]>(initialAgentOptions);\n\tconst [defaultAgentId, setDefaultAgentId] = useState(initialDefaultAgentId);\n\tconst [agentOptionsLoaded, setAgentOptionsLoaded] = useState(initialAgentOptions.length > 0);\n\tconst [nodeOptions, setNodeOptions] = useState<NodeInfo[]>([]);\n\tconst [switchingNode, setSwitchingNode] = useState(false);\n\tconst inputRef = useRef<HTMLInputElement>(null);\n\n\tconst fullName = session ? session.label || session.key : currentKey;\n\tconst displayName = nameOwnLine ? fullName : fullName.length > 20 ? `${fullName.slice(0, 20)}\\u2026` : fullName;\n\tconst replying = session?.replying.value;\n\tconst activeRunId = session?.activeRunId.value || null;\n\n\tconst isMain = currentKey === \"main\";\n\tconst isCron = currentKey.startsWith(\"cron:\");\n\tconst canRename = !(isMain || isCron);\n\tconst canStop = !isCron && replying;\n\tconst canArchive = !!session && isArchivableSession(session as unknown as SessionMeta);\n\tconst showArchivedSessions = sessionStore.showArchivedSessions.value;\n\tconst currentAgentId = session?.agent_id || defaultAgentId || \"main\";\n\tconst currentNodeId = session?.node_id || \"\";\n\n\tuseEffect(() => {\n\t\tlet cancelled = false;\n\t\tsendRpc(\"agents.list\", {}).then((res) => {\n\t\t\tif (cancelled) return;\n\t\t\tif (!res?.ok) {\n\t\t\t\tsetAgentOptionsLoaded(true);\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tconst parsed = parseAgentsListPayload(res.payload as never);\n\t\t\tsetDefaultAgentId(parsed.defaultId);\n\t\t\tsetAgentOptions(parsed.agents as AgentOption[]);\n\t\t\tsetAgentOptionsLoaded(true);\n\t\t});\n\t\treturn () => {\n\t\t\tcancelled = true;\n\t\t};\n\t}, [currentKey]);\n\n\t// Fetch connected nodes and subscribe to presence updates.\n\tuseEffect(() => {\n\t\tlet cancelled = false;\n\t\tconst fetchNodes = (): void => {\n\t\t\tsendRpc<NodeInfo[]>(\"node.list\", {}).then((res) => {\n\t\t\t\tif (cancelled || !res?.ok) return;\n\t\t\t\tsetNodeOptions(Array.isArray(res.payload) ? res.payload : []);\n\t\t\t});\n\t\t};\n\t\tfetchNodes();\n\t\tconst unsub = onEvent(\"presence\", () => {\n\t\t\tif (!cancelled) fetchNodes();\n\t\t});\n\t\treturn () => {\n\t\t\tcancelled = true;\n\t\t\tunsub();\n\t\t};\n\t}, [currentKey]);\n\n\tc