(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tclearPendingToolCallEndsForSession(eventSession);\n\tsetSessionReplying(eventSession, false);\n\tsetSessionActiveRunId(eventSession, null);\n\tconst partialState = getAbortedPartialState(p);\n\tconst abortSession = sessionStore.getByKey(eventSession);\n\tcacheAbortedPartial(eventSession, p, abortSession, partialState);\n\tif (abortSession) abortSession.resetStreamState();\n\tif (partialState.hasVisiblePartial && !isActive) {\n\t\tsetSessionUnread(eventSession, true);\n\t}\n\tif (!(isActive && isChatPage)) {\n\t\tS.setVoicePending(false);\n\t\treturn;\n\t}\n\tremoveThinking();\n\tclearStaleRunningToolCards();\n\trenderAbortedPartialInDom(eventSession, p, partialState);\n\tS.setStreamEl(null);\n\tS.setStreamText(\"\");\n\tS.setVoicePending(false);\n\tmoveFirstQueuedToChat();\n}\n\nfunction handleChatNotice(p: ChatPayload, isActive: boolean, isChatPage: boolean): void {\n\tif (!(isActive && isChatPage)) return;\n\t// Render titled notices as markdown so emphasis is visible.\n\tconst msg = p.title ? `**${p.title}:** ${p.message}` : (p.message || \"\");\n\tconst noticeEl = p.title ? chatAddMsg(\"system\", renderMarkdown(msg), true) : chatAddMsg(\"system\", msg);\n\tif (!(noticeEl && p.title)) return;\n\tnoticeEl.classList.add(\"system-notice\");\n\tif (String(p.title).toLowerCase() !== \"sandbox\") return;\n\tnoticeEl.classList.add(\"system-notice-sandbox\");\n\tconst normalizedMessage = String(p.message || \"\").toLowerCase();\n\tif (normalizedMessage.indexOf(\"enabled\") !== -1) {\n\t\tnoticeEl.classList.add(\"is-enabled\");\n\t} else if (normalizedMessage.indexOf(\"disabled\") !== -1) {\n\t\tnoticeEl.classList.add(\"is-disabled\");\n\t}\n}\n\nfunction handleChatQueueCleared(_p: ChatPayload, isActive: boolean, isChatPage: boolean): void {\n\tif (!(isActive && isChatPage)) return;\n\tconst tray = document.getElementById(\"queuedMessages\");\n\tif (tray) {\n\t\tconst count = tray.querySelectorAll(\".msg\").length;\n\t\tconsole.debug(\"[queued] queue_cleared: removing all from tray\", { count });\n\t\twhile (tray.firstChild) tray.removeChild(tray.firstChild);\n\t\ttray.classList.add(\"hidden\");\n\t}\n}\n\nfunction handleChatSessionCleared(_p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tclearPendingToolCallEndsForSession(eventSession);\n\tsetSessionActiveRunId(eventSession, null);\n\tclearSessionHistoryCache(eventSession);\n\t// Reset badge, unread state, and history index for every client.\n\tmarkSessionLocallyCleared(eventSession);\n\tif (isActive) {\n\t\tS.setLastHistoryIndex(-1);\n\t\tS.setChatSeq(0);\n\t}\n\tif (!(isActive && isChatPage)) return;\n\t// Active viewer: clear the chat box and token bar.\n\tif (S.chatMsgBox) S.chatMsgBox.textContent = \"\";\n\tS.setSessionTokens({ input: 0, output: 0 });\n\tS.setSessionCurrentInputTokens(0);\n\tupdateTokenBar();\n}\n\nconst chatHandlers: Record<string, ChatHandler> = {\n\tthinking: handleChatThinking,\n\tthinking_text: handleChatThinkingText,\n\tthinking_done: handleChatThinkingDone,\n\tvoice_pending: handleChatVoicePending,\n\ttool_call_start: handleChatToolCallStart,\n\ttool_call_end: handleChatToolCallEnd,\n\tchannel_user: handleChatChannelUser,\n\tuser_message: handleChatUserMessage,\n\tdelta: handleChatDelta,\n\tfinal: handleChatFinal,\n\tauto_compact: handleChatAutoCompact,\n\tcompact: handleChatCompact,\n\tretrying: handleChatRetrying,\n\terror: handleChatError,\n\taborted: handleChatAborted,\n\tnotice: handleChatNotice,\n\tqueue_cleared: handleChatQueueCleared,\n\tsession_cleared: handleChatSessionCleared,\n};\n\nfunction handleChatEvent(p: ChatPayload): void {\n\tconst eventSession = p.sessionKey || sessionStore.activeSessionKey.value;\n\tconst isActive = eventSession === sessionStore.activeSessionKey.value;\n\tconst isChatPage = currentPrefix === \"/chats\";\n\n\tif (isActive && sessionStore.switchInProgress.value) {\n\t\t// If session switching got stuck (e.g. lost RPC response), do not drop\n\t\t// terminal frames. Unstick and process final/error so replies still show\n\t\t// without requiring a full page reload.\n\t\tconst allowDuringSwitch =\n\t\t\tp.state === \"final\" ||\n\t\t\tp.state === \"error\" ||\n\t\t\tp.state === \"aborted\" ||\n\t\t\tp.state === \"notice\" ||\n\t\t\tp.state === \"session_cleared\" ||\n\t\t\tp.state === \"queue_cleared\";\n\t\tif (!allowDuringSwitch) {\n\t\t\treturn;\n\t\t}\n\t\tif (p.state === \"final\" || p.state === \"error\" || p.state === \"aborted\") {\n\t\t\tsessionStore.switchInProgress.value = false;\n\t\t\tS.setSessionSwitchInProgress(false);\n\t\t}\n\t}\n\n\tif (p.sessionKey && !sessionStore.getByKey(p.sessionKey)) {\n\t\tfetchSessions();\n\t}\n\n\tconst handler = chatHandlers[p.state || \"\"];\n\tif (handler) handler(p, isActive, isChatPage, eventSession);\n}\n\nfunction handleApprovalEvent(payload: ApprovalPayload): void {\n\trenderApprovalCard(payload.requestId, payload.command);\n}\n\nfunction handleLogEntry(payload: LogEntryPayload): void {\n\tif (S.logsEventHandler) S.logsEventHandler(payload);\n\tif (currentPage !== \"/logs\") {\n\t\tconst ll = (payload.level || \"\").toUpperCase();\n\t\tif (ll === \"ERROR\") {\n\t\t\tS.setUnseenErrors(S.unseenErrors + 1);\n\t\t\tupdateLogsAlert();\n\t\t} else if (ll === \"WARN\") {\n\t\t\tS.setUnseenWarns(S.unseenWarns + 1);\n\t\t\tupdateLogsAlert();\n\t\t}\n\t}\n}\n\nfunction updateSandboxBuildingFlag(building: boolean): void {\n\tconst info = S.sandboxInfo as Record<string, unknown> | null;\n\tif (info) S.setSandboxInfo({ ...info, image_building: building });\n}\n\nlet sandboxPrepareIndicatorEl: HTMLElement | null = null;\nfunction handleSandboxPrepare(payload: SandboxPhasePayload): void {\n\tconst isChatPage = currentPrefix === \"/chats\";\n\tif (!isChatPage) return;\n\n\tif (payload.phase === \"start\") {\n\t\tif (sandboxPrepareIndicatorEl) {\n\t\t\tsandboxPrepareIndicatorEl.remove();\n\t\t\tsandboxPrepareIndicatorEl = null;\n\t\t}\n\t\tsandboxPrepareIndicatorEl = chatAddMsg(\n\t\t\t\"system\",\n\t\t\t\"Preparing sandbox environment (first run may take a minute)\\u2026\",\n\t\t);\n\t\treturn;\n\t}\n\n\tif (sandboxPrepareIndicatorEl) {\n\t\tsandboxPrepareIndicatorEl.remove();\n\t\tsandboxPrepareIndicatorEl = null;\n\t}\n\n\tif (payload.phase === \"error\") {\n\t\tchatAddMsg(\"error\", `Sandbox setup failed: ${payload.error || \"unknown\"}`);\n\t}\n}\n\nfunction handleSandboxImageBuild(payload: SandboxPhasePayload): void {\n\tconst phase = payload.phase;\n\t// Update the sandboxInfo signal so all pages (chat, settings) reflect the build state.\n\tupdateSandboxBuildingFlag(phase === \"start\");\n\n\tconst isChatPage = currentPrefix === \"/chats\";\n\tif (!isChatPage) return;\n\tif (phase === \"start\") {\n\t\tchatAddMsg(\"system\", \"Building sandbox image (installing packages)\\u2026\");\n\t} else if (phase === \"done\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tconst msg = payload.built ? `Sandbox image ready: ${payload.tag}` : `Sandbox image already cached: ${payload.tag}`;\n\t\tchatAddMsg(\"system\", msg);\n\t} else if (phase === \"error\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tchatAddMsg(\"error\", `Sandbox image build failed: ${payload.error || \"unknown\"}`);\n\t}\n}\n\nfunction handleSandboxImageProvision(payload: SandboxPhasePayload): void {\n\tconst isChatPage = currentPrefix === \"/chats\";\n\tif (!isChatPage) return;\n\tif (payload.phase === \"start\") {\n\t\tchatAddMsg(\"system\", \"Provisioning sandbox packages\\u2026\");\n\t} else if (payload.phase === \"done\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tchatAddMsg(\"system\", \"Sandbox packages provisioned\");\n\t} else if (payload.phase === \"error\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tchatAddMsg(\"error\", `Sandbox provisioning failed: ${payload.error || \"unknown\"}`);\n\t}\n}\n\n// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Provisioning UI with multiple phases\nfunction handleSandboxHostProvision(payload: SandboxPhasePayload): void {\n\tconst isChatPage = currentPrefix === \"/chats\";\n\tif (!isChatPage) return;\n\tif (payload.phase === \"start\") {\n\t\tconst msg = `Installing ${payload.count || \"\"} package${payload.count === 1 ? \"\" : \"s\"} on host\\u2026`;\n\t\tchatAddMsg(\"system\", msg);\n\t} else if (payload.phase === \"done\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tconst parts: string[] = [];\n\t\tif ((payload.installed || 0) > 0) parts.push(`${payload.installed} installed`);\n\t\tif ((payload.skipped || 0) > 0) parts.push(`${payload.skipped} already present`);\n\t\tchatAddMsg(\"system\", `Host packages ready (${parts.join(\", \") || \"done\"})`);\n\t} else if (payload.phase === \"error\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tchatAddMsg(\"error\", `Host package install failed: ${payload.error || \"unknown\"}`);\n\t}\n}\n\nfunction handleBrowserImagePull(payload: SandboxPhasePayload): void {\n\tconst isChatPage = currentPrefix === \"/chats\";\n\tif (!isChatPage) return;\n\tconst image = payload.image || \"browser container\";\n\tif (payload.phase === \"start\") {\n\t\tchatAddMsg(\"system\", `Pulling browser container image (${image})\\u2026 This may take a few minutes on first run.`);\n\t} else if (payload.phase === \"done\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tchatAddMsg(\"system\", `Browser container image ready: ${image}`);\n\t} else if (payload.phase === \"error\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tchatAddMsg(\"error\", `Browser container image pull failed: ${payload.error || \"unknown\"}`);\n\t}\n}\n\n// Track download indicator element\nlet downloadIndicatorEl: HTMLElement | null = null;\n\n// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Download progress UI with multiple states\nfunction handleLocalLlmDownload(payload: LocalLlmDownloadPayload): void {\n\tconst isChatPage = currentPrefix === \"/chats\";\n\tif (!isChatPage) return;\n\n\tconst modelName = payload.displayName || payload.modelId || \"model\";\n\n\tif (payload.error) {\n\t\t// Download error\n\t\tif (downloadIndicatorEl) {\n\t\t\tdownloadIndicatorEl.remove();\n\t\t\tdownloadIndicatorEl = null;\n\t\t}\n\t\tchatAddMsg(\"error\", `Failed to download ${modelName}: ${payload.error}`);\n\t\treturn;\n\t}\n\n\tif (payload.complete) {\n\t\t// Download complete\n\t\tif (downloadIndicatorEl) {\n\t\t\tdownloadIndicatorEl.remove();\n\t\t\tdownloadIndicatorEl = null;\n\t\t}\n\t\tchatAddMsg(\"system\", `${modelName} ready`);\n\t\treturn;\n\t}\n\n\t// Download in progress - show/update progress indicator\n\tif (!downloadIndicatorEl) {\n\t\tdownloadIndicatorEl = document.createElement(\"div\");\n\t\tdownloadIndicatorEl.className = \"msg system download-indicator\";\n\n\t\tconst status = document.createElement(\"div\");\n\t\tstatus.className = \"download-status\";\n\t\tstatus.textContent = `Downloading ${modelName}\\u2026`;\n\t\tdownloadIndicatorEl.appendChild(status);\n\n\t\tconst progressContainer = document.createElement(\"div\");\n\t\tprogressContainer.className = \"download-progress\";\n\t\tconst progressBar = document.createElement(\"div\");\n\t\tprogressBar.className = \"download-progress-bar\";\n\t\tprogressContainer.appendChild(progressBar);\n\t\tdownloadIndicatorEl.appendChild(progressContainer);\n\n\t\tconst progressText = document.createElement(\"div\");\n\t\tprogressText.className = \"download-progress-text\";\n\t\tdownloadIndicatorEl.appendChild(progressText);\n\n\t\tif (S.chatMsgBox) {\n\t\t\tclearChatEmptyState();\n\t\t\tS.chatMsgBox.appendChild(downloadIndicatorEl);\n\t\t\tS.chatMsgBox.scrollTop = S.chatMsgBox.scrollHeight;\n\t\t}\n\t}\n\n\t// Update progress bar\n\tconst barEl = downloadIndicatorEl.querySelector(\".download-progress-bar\") as HTMLElement | null;\n\tconst textEl = downloadIndicatorEl.querySelector(\".download-progress-text\") as HTMLElement | null;\n\tconst containerEl = downloadIndicatorEl.querySelector(\".download-progress\") as HTMLElement | null;\n\n\tif (barEl && containerEl) {\n\t\tif (payload.progress != null) {\n\t\t\t// Determinate progress - show actual percentage\n\t\t\tcontainerEl.classList.remove(\"indeterminate\");\n\t\t\tbarEl.style.width = `${payload.progress.toFixed(1)}%`;\n\t\t} else if (payload.total == null && payload.downloaded != null) {\n\t\t\t// Indeterminate progress - CSS handles the animation\n\t\t\tcontainerEl.classList.add(\"indeterminate\");\n\t\t\tbarEl.style.width = \"\"; // Let CSS control width\n\t\t}\n\t}\n\n\tif (payload.downloaded != null && textEl) {\n\t\tconst downloadedMb = (payload.downloaded / (1024 * 1024)).toFixed(1);\n\t\tif (payload.total != null) {\n\t\t\tconst totalMb = (payload.total / (1024 * 1024)).toFixed(1);\n\t\t\ttextEl.textContent = `${downloadedMb} / ${totalMb} MB`;\n\t\t} else {\n\t\t\ttextEl.textContent = `${downloadedMb} MB`;\n\t\t}\n\t}\n}\n\nlet modelsUpdatedTimer: ReturnType<typeof setTimeout> | null = null;\nfunction handleModelsUpdated(payload: ModelsUpdatedPayload): void {\n\t// Progress/status frames are consumed directly by the Providers page.\n\t// Avoid spamming model refresh requests while a probe is running.\n\tif (payload?.phase === \"start\" || payload?.phase === \"progress\") return;\n\tif (modelsUpdatedTimer) return;\n\tmodelsUpdatedTimer = setTimeout(() => {\n\t\tmodelsUpdatedTimer = null;\n\t\t// fetchModels() delegates to modelStore.fetch() internally\n\t\tfetchModels();\n\t\tif (S.refreshProvidersPage) S.refreshProvidersPage();\n\t}, 150);\n}\n\n// ── Location request handler ─────────────────────────────────\n\nfunction handleWsError(payload: WsErrorPayload): void {\n\tconst isChatPage = currentPrefix === \"/chats\";\n\tif (!isChatPage) return;\n\tchatAddErrorMsg(payload.message || \"Unknown error\");\n}\n\nfunction handleLocationRequest(payload: LocationRequestPayload): void {\n\tconst requestId = payload.requestId;\n\tif (!requestId) return;\n\n\tif (!navigator.geolocation) {\n\t\tsendRpc(\"location.result\", {\n\t\t\trequestId,\n\t\t\terror: { code: 0, message: \"Geolocation not supported\" },\n\t\t});\n\t\treturn;\n\t}\n\n\t// Coarse: city-level, fast, longer cache. Precise: GPS-level, fresh.\n\tconst coarse = payload.precision === \"coarse\";\n\tconst geoOpts: PositionOptions = coarse\n\t\t? { enableHighAccuracy: false, timeout: 10000, maximumAge: 1800000 }\n\t\t: { enableHighAccuracy: true, timeout: 15000, maximumAge: 60000 };\n\n\tnavigator.geolocation.getCurrentPosition(\n\t\t(pos: GeolocationPosition) => {\n\t\t\tsendRpc(\"location.result\", {\n\t\t\t\trequestId,\n\t\t\t\tlocation: {\n\t\t\t\t\tlatitude: pos.coords.latitude,\n\t\t\t\t\tlongitude: pos.coords.longitude,\n\t\t\t\t\taccuracy: pos.coords.accuracy,\n\t\t\t\t},\n\t\t\t});\n\t\t},\n\t\t(err: GeolocationPositionError) => {\n\t\t\tsendRpc(\"location.result\", {\n\t\t\t\trequestId,\n\t\t\t\terror: { code: err.code, message: err.message },\n\t\t\t});\n\t\t},\n\t\tgeoOpts,\n\t);\n}\n\nfunction handleNetworkAuditEntry(payload: Record<string, unknown>): void {\n\tif (S.networkAuditEventHandler) S.networkAuditEventHandler(payload);\n}\n\nfunction handleAuthCredentialsChanged(payload: AuthCredentialsPayload): void {\n\tif (payload?.reason === \"password_changed\" && window.__moltisSuppressNextPasswordChangedRedirect === true) {\n\t\twindow.__moltisSuppressNextPasswordChangedRedirect = false;\n\t\tconsole.info(\"Deferring redirect for password_changed to show recovery key first\");\n\t\treturn;\n\t}\n\tconsole.warn(\"Auth credentials changed:\", payload.reason);\n\twindow.location.href = \"/login\";\n}\n\nconst eventHandlers: Record<string, (payload: Record<string, unknown>, streamMeta?: StreamMeta | null) => void> = {\n\tchat: handleChatEvent as (payload: Record<string, unknown>) => void,\n\terror: handleWsError as (payload: Record<string, unknown>) => void,\n\t\"auth.credentials_changed\": handleAuthCredentialsChanged as (payload: Record<string, unknown>) => void,\n\t\"exec.approval.requested\": handleApprovalEvent as unknown as (payload: Record<string, unknown>) => void,\n\t\"logs.entry\": handleLogEntry as (payload: Record<string, unknown>) => void,\n\t\"sandbox.prepare\": handleSandboxPrepare as (payload: Record<string, unknown>) => void,\n\t\"sandbox.image.build\": handleSandboxImageBuild as (payload: Record<string, unknown>) => void,\n\t\"sandbox.image.provision\": handleSandboxImageProvision as (payload: Record<string, unknown>) => void,\n\t\"sandbox.host.provision\": handleSandboxHostProvision as (payload: Record<string, unknown>) => void,\n\t\"browser.image.pull\": handleBrowserImagePull as (payload: Record<string, unknown>) => void,\n\t\"local-llm.download\": handleLocalLlmDownload as (payload: Record<string, unknown>) => void,\n\t\"models.updated\": handleModelsUpdated as (payload: Record<string, unknown>) => void,\n\t\"location.request\": handleLocationRequest as (payload: Record<string, unknown>) => void,\n\t\"network.audit.entry\": handleNetworkAuditEntry as (payload: Record<string, unknown>) => void,\n};\n\nfunction dispatchFrame(frame: WsFrame): void {\n\tif (frame.type !== \"event\") return;\n\tconst streamMeta: StreamMeta | null =\n\t\tframe.stream != null || frame.done != null\n\t\t\t? { stream: frame.stream, done: frame.done, channel: frame.channel }\n\t\t\t: null;\n\tconst listeners = eventListeners[frame.event || \"\"] || [];\n\tlisteners.forEach((h) => {\n\t\th(frame.payload || {});\n\t});\n\tconst handler = eventHandlers[frame.event || \"\"];\n\tif (handler) handler(frame.payload || {}, streamMeta);\n}\n\nconst connectOpts: ConnectOptions = {\n\tonFrame: dispatchFrame as ConnectOptions[\"onFrame\"],\n\tonConnected: async (hello) => {\n\t\tconst isReconnect = hasConnectedOnce;\n\t\thasConnectedOnce = true;\n\t\tsetStatus(\"connected\", \"\");\n\t\tconst now = new Date();\n\t\tconst ts = now.toLocaleTimeString([], {\n\t\t\thour: \"2-digit\",\n\t\t\tminute: \"2-digit\",\n\t\t\tsecond: \"2-digit\",\n\t\t});\n\t\tchatAddMsg(\"system\", `Connected to moltis gateway v${hello.server.version} at ${ts}`);\n\t\tif ((S.sandboxInfo as Record<string, unknown> | null)?.image_building) {\n\t\t\tchatAddMsg(\"system\", \"Building sandbox image (installing packages)\\u2026\");\n\t\t}\n\t\t// Subscribe to all needed events (v4 protocol).\n\t\t// Await so that events are not lost to a race between subscribe and\n\t\t// the first broadcast after connect.\n\t\tS.setSubscribed(false);\n\t\tawait subscribeEvents(\n\t\t\tObject.keys(eventHandlers).concat([\n\t\t\t\t\"tick\",\n\t\t\t\t\"shutdown\",\n\t\t\t\t\"auth.credentials_changed\",\n\t\t\t\t\"exec.approval.requested\",\n\t\t\t\t\"exec.approval.resolved\",\n\t\t\t\t\"device.pair.requested\",\n\t\t\t\t\"device.pair.resolved\",\n\t\t\t\t\"node.pair.requested\",\n\t\t\t\t\"node.pair.resolved\",\n\t\t\t\t\"node.invoke.request\",\n\t\t\t\t\"session\",\n\t\t\t\t\"update.available\",\n\t\t\t\t\"hooks.status\",\n\t\t\t\t\"push.subscriptions\",\n\t\t\t\t\"channel\",\n\t\t\t\t\"metrics.update\",\n\t\t\t\t\"skills.install.progress\",\n\t\t\t\t\"mcp.status\",\n\t\t\t]),\n\t\t);\n\t\tS.setSubscribed(true);\n\t\t// Keep initial hydration authoritative via app bootstrap/gon.\n\t\t// On reconnect, force a fresh snapshot in case realtime events were missed.\n\t\tif (isReconnect) {\n\t\t\tfetchModels();\n\t\t\tfetchSessions();\n\t\t\tfetchProjects();\n\t\t\tprefetchChannels();\n\t\t}\n\t\tsendRpc(\"logs.status\", {}).then((res) => {\n\t\t\tif (res?.ok) {\n\t\t\t\tconst p = (res.payload || {}) as Record<string, unknown>;\n\t\t\t\tS.setUnseenErrors((p.unseen_errors as number) || 0);\n\t\t\t\tS.setUnseenWarns((p.unseen_warns as number) || 0);\n\t\t\t\tif (currentPage === \"/logs\") clearLogsAlert();\n\t\t\t\telse updateLogsAlert();\n\t\t\t}\n\t\t});\n\t\tif (currentPage === \"/chats\" || currentPrefix === \"/chats\") mount(currentPage || \"\");\n\t},\n\tonHandshakeFailed: (frame) => {\n\t\tsetStatus(\"\", \"handshake failed\");\n\t\tconst reason = frame.error?.message || \"unknown error\";\n\t\tchatAddMsg(\"error\", `Handshake failed: ${reason}`);\n\t},\n\tonDisconnected: (wasConnected: boolean) => {\n\t\tif (wasConnected) {\n\t\t\tsetStatus(\"\", \"disconnected \\u2014 reconnecting\\u2026\");\n\t\t}\n\t\t// Reset active session's stream state\n\t\tconst activeS = sessionStore.activeSession.value;\n\t\tif (activeS) activeS.resetStreamState();\n\t\tS.setStreamEl(null);\n\t\tS.setStreamText(\"\");\n\t},\n};\n\nexport function connect(): void {\n\tsetStatus(\"connecting\", \"connecting...\");\n\tconnectWs(connectOpts);\n}\n\nfunction setStatus(state: string, text: string): void {\n\tconst dot = S.$(\"statusDot\");\n\tconst sText = S.$(\"statusText\");\n\tif (dot) dot.className = `status-dot ${state}`;\n\tif (sText) {\n\t\tsText.textContent = text;\n\t\tsText.classList.toggle(\"status-text-live\", state === \"connected\");\n\t}\n\tconst sendBtn = S.$(\"sendBtn\") as HTMLButtonElement | null;\n\tif (sendBtn) sendBtn.disabled = state !== \"connected\";\n}\n\ndocument.addEventListener(\"visibilitychange\", () => {\n\tif (!(document.hidden || S.connected)) {\n\t\tforceReconnect(connectOpts);\n\t}\n});\n","// ── Crons page (Preact + Signals) ──────────────────────────\n\nimport { signal, useSignal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect } from \"preact/hooks\";\nimport { fetchChannelStatus } from \"../channel-utils\";\nimport * as gon from \"../gon\";\nimport { refresh as refreshGon } from \"../gon\";\nimport { sendRpc } from \"../helpers\";\nimport { updateNavCount } from \"../nav-counts\";\nimport { models as modelsSig } from \"../stores/model-store\";\nimport { ComboSelect, ConfirmDialog, Modal, ModelSelect, requestConfirm } from \"../ui\";\n\n// ── Types ────────────────────────────────────────────────────\n\ninterface CronJob {\n\tid: string;\n\tname: string;\n\tenabled: boolean;\n\tsystem?: boolean;\n\tschedule: CronSchedule;\n\tpayload: CronPayload;\n\tsessionTarget?: string;\n\tdeleteAfterRun?: boolean;\n\tstate?: { lastStatus?: string; nextRunAtMs?: number };\n\tsandbox?: { enabled?: boolean; image?: string };\n}\n\ninterface CronSchedule {\n\tkind: string;\n\texpr?: string;\n\ttz?: string;\n\tat_ms?: number;\n\tevery_ms?: number;\n}\n\ninterface CronPayload {\n\tkind: string;\n\ttext?: string;\n\tmessage?: string;\n\tmodel?: string;\n\tdeliver?: boolean;\n\tchannel?: string;\n\tto?: string;\n}\n\ninterface CronStatusInfo {\n\trunning: boolean;\n\tjobCount: number;\n\tenabledCount: number;\n\tnextRunAtMs?: number;\n}\n\ninterface HeartbeatConfig {\n\tenabled?: boolean;\n\tevery?: string;\n\tmodel?: string;\n\tprompt?: string;\n\tack_max_chars?: number;\n\tdeliver?: boolean;\n\tchannel?: string;\n\tto?: string;\n\tactive_hours?: { start?: string; end?: string; timezone?: string };\n\tsandbox_enabled?: boolean;\n\tsandbox_image?: string;\n}\n\ninterface HeartbeatStatusInfo {\n\tpromptSource?: string;\n\tjob?: CronJob;\n}\n\ninterface CronRun {\n\tstartedAtMs: number;\n\tstatus: string;\n\tdurationMs: number;\n\terror?: string;\n\tinputTokens?: number;\n\toutputTokens?: number;\n}\n\ninterface RunsHistory {\n\tjobId: string;\n\tjobName: string;\n\truns: CronRun[] | null;\n}\n\ninterface SandboxImage {\n\ttag: string;\n}\n\ninterface ChannelAccount {\n\taccount_id: string;\n\tname?: string;\n\tstatus: string;\n}\n\n// ── Signals ──────────────────────────────────────────────────\n\nconst initialCrons = (gon.get(\"crons\") as CronJob[] | null) || [];\nconst cronJobs = signal<CronJob[]>(initialCrons);\nconst cronStatus = signal<CronStatusInfo | null>(gon.get(\"cron_status\") as CronStatusInfo | null);\nif (initialCrons.length) updateNavCount(\"crons\", initialCrons.filter((j) => j.enabled).length);\nconst runsHistory = signal<RunsHistory | null>(null);\nconst showModal = signal(false);\nconst editingJob = signal<CronJob | null>(null);\nconst activeSection = signal<\"jobs\" | \"heartbeat\">(\"jobs\");\nlet _cronsContainer: HTMLElement | null = null;\n\n// Heartbeat state\nconst heartbeatStatus = signal<HeartbeatStatusInfo | null>(null);\nconst heartbeatRuns = signal<CronRun[] | null>((gon.get(\"heartbeat_runs\") as CronRun[] | null) || []);\nconst heartbeatSaving = signal(false);\nconst heartbeatRunning = signal(false);\nconst heartbeatConfig = signal<HeartbeatConfig>((gon.get(\"heartbeat_config\") as HeartbeatConfig | null) || {});\nconst sandboxImages = signal<SandboxImage[]>([]);\nconst channelAccounts = signal<ChannelAccount[]>([]);\nconst heartbeatModel = signal((gon.get(\"heartbeat_config\") as HeartbeatConfig | null)?.model || \"\");\nconst heartbeatSandboxImage = signal((gon.get(\"heartbeat_config\") as HeartbeatConfig | null)?.sandbox_image || \"\");\n\nfunction loadSandboxImages(): void { fetch(\"/api/images/cached\").then((r) => r.json()).then((d) => { sandboxImages.value = d?.images || []; }).catch(() => { /* optional */ }); }\nfunction loadChannelAccounts(): void { fetchChannelStatus().then((res: unknown) => { const r = res as { ok?: boolean; payload?: { channels?: ChannelAccount[] } } | null; if (r?.ok) channelAccounts.value = (r.payload?.channels || []).filter((c) => c.status === \"connected\"); }); }\nfunction loadHeartbeatStatus(): void { sendRpc(\"heartbeat.status\", {}).then((res) => { if (res?.ok) heartbeatStatus.value = res.payload as HeartbeatStatusInfo; }); }\nfunction findHeartbeatJob(): CronJob | null { return cronJobs.value.find((j) => j.name === \"__heartbeat__\") || (heartbeatStatus.value?.job as CronJob) || null; }\nfunction loadHeartbeatRuns(): void { if (!findHeartbeatJob()) { heartbeatRuns.value = heartbeatRuns.value || []; return; } heartbeatRuns.value = null; sendRpc(\"heartbeat.runs\", { limit: 10 }).then((res) => { heartbeatRuns.value = res?.ok ? (res.payload as CronRun[]) || [] : []; }); }\nfunction heartbeatRunBlockedReason(cfg: HeartbeatConfig, promptSource: string, job: CronJob | null): string | null {\n\tif (cfg.enabled === false) return \"Heartbeat is disabled. Enable it to allow manual runs.\";\n\tif (promptSource === \"default\") return \"Heartbeat is inactive because no prompt is configured. Add a custom prompt or write actionable content in HEARTBEAT.md.\";\n\tif (!job) return \"Heartbeat has no active cron job yet. Save the heartbeat settings to recreate it.\";\n\treturn null;\n}\nfunction loadStatus(): void { sendRpc(\"cron.status\", {}).then((res) => { if (res?.ok) cronStatus.value = res.payload as CronStatusInfo; }); }\nfunction loadJobs(): void { sendRpc(\"cron.list\", {}).then((res) => { if (res?.ok) { cronJobs.value = (res.payload as CronJob[]) || []; updateNavCount(\"crons\", cronJobs.value.filter((j) => j.enabled).length); } }); }\n\nfunction formatSchedule(sched: CronSchedule): string {\n\tif (sched.kind === \"at\") return `At ${new Date(sched.at_ms!).toLocaleString()}`;\n\tif (sched.kind === \"every\") { const ms = sched.every_ms!; if (ms >= 3600000) return `Every ${ms / 3600000}h`; if (ms >= 60000) return `Every ${ms / 60000}m`; return `Every ${ms / 1000}s`; }\n\tif (sched.kind === \"cron\") return sched.expr! + (sched.tz ? ` (${sched.tz})` : \"\");\n\treturn JSON.stringify(sched);\n}\n\nfunction formatTokens(n: number | null | undefined): string | null {\n\tif (n == null) return null;\n\tif (n >= 1000) return `${(n / 1000).toFixed(1).replace(/\\.0$/, \"\")}K`;\n\treturn String(n);\n}\n\nfunction TokenBadge({ run }: { run: CronRun }): VNode | null {\n\tif (run.inputTokens == null && run.outputTokens == null) return null;\n\tconst parts: string[] = [];\n\tif (run.inputTokens != null) parts.push(`${formatTokens(run.inputTokens)} in`);\n\tif (run.outputTokens != null) parts.push(`${formatTokens(run.outputTokens)} out`);\n\treturn <span className=\"text-xs text-[var(--muted)] font-mono\">{parts.join(\" / \")}</span>;\n}\n\nfunction HeartbeatRunsList({ runs }: { runs: CronRun[] | null }): VNode {\n\tif (runs === null) return <div className=\"text-xs text-[var(--muted)]\">Loading&hellip;</div>;\n\tif (runs.length === 0) return <div className=\"text-xs text-[var(--muted)]\">No runs yet.</div>;\n\treturn (\n\t\t<div className=\"flex flex-col\">\n\t\t\t{runs.map((run) => (\n\t\t\t\t<div key={run.startedAtMs} className=\"flex items-center gap-3 py-2 border-b border-[var(--border)]\" style={{ minHeight: \"36px\" }}>\n\t\t\t\t\t<span className={`status-dot ${run.status === \"ok\" ? \"connected\" : \"\"}`} />\n\t\t\t\t\t<span className={`cron-badge ${run.status}`}>{run.status}</span>\n\t\t\t\t\t<span className=\"text-xs text-[var(--muted)] font-mono\">{run.durationMs}ms</span>\n\t\t\t\t\t<TokenBadge run={run} />\n\t\t\t\t\t{run.error && <span className=\"text-xs text-[var(--error)] truncate\">{run.error}</span>}\n\t\t\t\t\t<span className=\"flex-1\" />\n\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\"><time data-epoch-ms={run.startedAtMs}>{new Date(run.startedAtMs).toISOString()}</time></span>\n\t\t\t\t</div>\n\t\t\t))}\n\t\t</div>\n\t);\n}\n\nfunction HeartbeatJobStatus({ job }: { job: CronJob | null }): VNode | null {\n\tif (!job) return null;\n\tconst statusDotClass = job.enabled ? \"connected\" : \"\";\n\treturn (\n\t\t<div className=\"info-bar\" style={{ marginTop: \"16px\", marginBottom: \"16px\" }}>\n\t\t\t<span className=\"info-field\"><span className={`status-dot ${statusDotClass}`} /><span className=\"info-label\">{job.enabled ? \"Enabled\" : \"Disabled\"}</span></span>\n\t\t\t{job.state?.lastStatus && <span className=\"info-field\"><span className=\"info-label\">Last:</span><span className={`cron-badge ${job.state.lastStatus}`}>{job.state.lastStatus}</span></span>}\n\t\t\t{job.state?.nextRunAtMs && <span className=\"info-field\"><span className=\"info-label\">Next:</span><span className=\"info-value\"><time data-epoch-ms={job.state.nextRunAtMs}>{new Date(job.state.nextRunAtMs).toLocaleString()}</time></span></span>}\n\t\t</div>\n\t);\n}\n\nfunction defaultModelPlaceholder(): string { if (!modelsSig.value.length) return \"(server default)\"; const m = modelsSig.value[0] as unknown as { displayName?: string; id: string }; return `(default: ${m.displayName || m.id})`; }\n\nconst systemTimezone = Intl.DateTimeFormat().resolvedOptions().timeZone;\nfunction cronTimezoneHelpText(): string { return systemTimezone ? `Leave blank to use UTC. Enter ${systemTimezone} to use your local timezone.` : \"Leave blank to use UTC. Enter a timezone like Europe/Paris to use your local timezone.\"; }\n\nfunction collectHeartbeatForm(form: Element): HeartbeatConfig {\n\treturn {\n\t\tenabled: (form.querySelector(\"[data-hb=enabled]\") as HTMLInputElement).checked,\n\t\tevery: (form.querySelector(\"[data-hb=every]\") as HTMLInputElement).value.trim() || \"30m\",\n\t\tmodel: heartbeatModel.value || undefined,\n\t\tprompt: (form.querySelector(\"[data-hb=prompt]\") as HTMLTextAreaElement).value.trim() || undefined,\n\t\tack_max_chars: parseInt((form.querySelector(\"[data-hb=ackMax]\") as HTMLInputElement).value, 10) || 300,\n\t\tdeliver: (form.querySelector(\"[data-hb=deliver]\") as HTMLInputElement).checked,\n\t\tchannel: (form.querySelector(\"[data-hb=channel]\") as HTMLInputElement).value.trim() || undefined,\n\t\tto: (form.querySelector(\"[data-hb=to]\") as HTMLInputElement).value.trim() || undefined,\n\t\tactive_hours: {\n\t\t\tstart: (form.querySelector(\"[data-hb=ahStart]\") as HTMLInputElement).value.trim() || \"08:00\",\n\t\t\tend: (form.querySelector(\"[data-hb=ahEnd]\") as HTMLInputElement).value.trim() || \"24:00\",\n\t\t\ttimezone: (form.querySelector(\"[data-hb=ahTz]\") as HTMLSelectElement).value.trim() || \"local\",\n\t\t},\n\t\tsandbox_enabled: (form.querySelector(\"[data-hb=sandboxEnabled]\") as HTMLInputElement).checked,\n\t\tsandbox_image: heartbeatSandboxImage.value || undefined,\n\t};\n}\n\nfunction HeartbeatSection(): VNode {\n\tconst cfg = heartbeatConfig.value;\n\tconst saving = heartbeatSaving.value;\n\tconst promptSource = heartbeatStatus.value?.promptSource || \"default\";\n\tconst job = findHeartbeatJob();\n\tconst runBlockedReason = heartbeatRunBlockedReason(cfg, promptSource, job);\n\n\tfunction onSave(e: Event): void {\n\t\te.preventDefault();\n\t\tconst updated = collectHeartbeatForm((e.target as HTMLElement).closest(\".heartbeat-form\")!);\n\t\theartbeatSaving.value = true;\n\t\tsendRpc(\"heartbeat.update\", updated).then((res) => {\n\t\t\theartbeatSaving.value = false;\n\t\t\tif (res?.ok) { heartbeatConfig.value = updated; heartbeatModel.value = updated.model || \"\"; heartbeatSandboxImage.value = updated.sandbox_image || \"\"; refreshGon(); loadHeartbeatStatus(); loadJobs(); loadStatus(); }\n\t\t});\n\t}\n\n\tfunction onRunNow(): void {\n\t\tif (runBlockedReason) return;\n\t\theartbeatRunning.value = true;\n\t\tsendRpc(\"heartbeat.run\", {}).then(() => { heartbeatRunning.value = false; loadHeartbeatStatus(); loadHeartbeatRuns(); loadJobs(); loadStatus(); });\n\t}\n\n\tfunction onToggleEnabled(e: Event): void {\n\t\tconst newEnabled = (e.target as HTMLInputElement).checked;\n\t\tconst updated = { ...cfg, enabled: newEnabled };\n\t\tsendRpc(\"heartbeat.update\", updated).then((res) => { if (res?.ok) { heartbeatConfig.value = updated; refreshGon(); loadHeartbeatStatus(); loadJobs(); loadStatus(); } });\n\t}\n\n\tconst running = heartbeatRunning.value;\n\tconst runNowDisabled = running || !!runBlockedReason;\n\tconst promptSourceText = promptSource === \"config\" ? \"config custom prompt\" : promptSource === \"heartbeat_md\" ? \"HEARTBEAT.md\" : \"none (heartbeat inactive)\";\n\n\treturn (\n\t\t<div className=\"heartbeat-form\" style={{ maxWidth: \"600px\" }}>\n\t\t\t<div className=\"flex items-center justify-between mb-2\">\n\t\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Heartbeat</h2>\n\t\t\t\t\t<label className=\"cron-toggle\"><input data-hb=\"enabled\" type=\"checkbox\" checked={cfg.enabled !== false} onChange={onToggleEnabled} /><span className=\"cron-slider\" /></label>\n\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">Enable</span>\n\t\t\t\t</div>\n\t\t\t\t<button className=\"provider-btn provider-btn-secondary\" onClick={onRunNow} disabled={runNowDisabled} title={runBlockedReason || undefined}>{running ? \"Running\\u2026\" : \"Run Now\"}</button>\n\t\t\t</div>\n\t\t\t<p className=\"text-sm text-[var(--muted)] mb-4\">Periodic AI check-in that monitors your environment and reports status.</p>\n\t\t\t{runBlockedReason && <div className=\"alert-info-text max-w-form mb-4\"><span className=\"alert-label-info\">Heartbeat inactive:</span> {runBlockedReason}</div>}\n\t\t\t<HeartbeatJobStatus job={job} />\n\n\t\t\t{/* Schedule */}\n\t\t\t<div style={{ marginTop: \"24px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Schedule</h3>\n\t\t\t\t<div className=\"grid gap-4\" style={{ gridTemplateColumns: \"1fr 1fr\" }}>\n\t\t\t\t\t<div><label className=\"block text-xs text-[var(--muted)] mb-1\">Interval</label><input data-hb=\"every\" className=\"provider-key-input\" placeholder=\"30m\" value={cfg.every || \"30m\"} /></div>\n\t\t\t\t\t<div><label className=\"block text-xs text-[var(--muted)] mb-1\">Model</label><ModelSelect models={modelsSig.value} value={heartbeatModel.value} onChange={(v: string) => { heartbeatModel.value = v; }} placeholder={defaultModelPlaceholder()} /></div>\n\t\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t{/* Prompt */}\n\t\t\t<div style={{ marginTop: \"24px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Prompt</h3>\n\t\t\t\t<label className=\"block text-xs text-[var(--muted)] mb-1\">Custom Prompt (optional)</label>\n\t\t\t\t<textarea data-hb=\"prompt\" className=\"provider-key-input textarea-sm\" placeholder=\"Leave blank to use default heartbeat prompt\">{cfg.prompt || \"\"}</textarea>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] mt-2\">Leave this empty to use <code>HEARTBEAT.md</code> in your workspace root. If that file exists but is empty/comments-only, heartbeat LLM runs are skipped to save tokens.</p>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] mt-1\">Effective prompt source: <span className=\"text-[var(--text)]\">{promptSourceText}</span></p>\n\t\t\t\t<div className=\"grid gap-4 mt-3\" style={{ gridTemplateColumns: \"1fr\" }}>\n\t\t\t\t\t<div><label className=\"block text-xs text-[var(--muted)] mb-1\">Max Response Characters</label><input data-hb=\"ackMax\" className=\"provider-key-input\" type=\"number\" min=\"50\" value={cfg.ack_max_chars || 300} /></div>\n\t\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t{/* Delivery */}\n\t\t\t<div style={{ marginTop: \"24px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Delivery</h3>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] mb-3\">Send heartbeat replies to a channel/chat destination.</p>\n\t\t\t\t<div className=\"flex items-center gap-3 mb-3\"><label className=\"cron-toggle\"><input data-hb=\"deliver\" type=\"checkbox\" checked={cfg.deliver === true} /><span className=\"cron-slider\" /></label><span className=\"text-sm text-[var(--text)]\">Deliver to channel</span></div>\n\t\t\t\t<div className=\"grid gap-4\" style={{ gridTemplateColumns: \"1fr 1fr\" }}>\n\t\t\t\t\t<div><label className=\"block text-xs text-[var(--muted)] mb-1\">Channel Account</label><input data-hb=\"channel\" className=\"provider-key-input\" placeholder=\"my-bot\" value={cfg.channel || \"\"} /></div>\n\t\t\t\t\t<div><label className=\"block text-xs text-[var(--muted)] mb-1\">Chat ID</label><input data-hb=\"to\" className=\"provider-key-input\" placeholder=\"123456789\" value={cfg.to || \"\"} /></div>\n\t\t\t\t</div>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] mt-2\">Required when delivery is enabled. Account is your configured channel account id, chat ID is the destination recipient/group id.</p>\n\t\t\t</div>\n\n\t\t\t{/* Active Hours */}\n\t\t\t<div style={{ marginTop: \"24px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Active Hours</h3>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] mb-3\">Only run heartbeat during these hours.</p>\n\t\t\t\t<div className=\"grid gap-4\" style={{ gridTemplateColumns: \"1fr 1fr\" }}>\n\t\t\t\t\t<div><label className=\"block text-xs text-[var(--muted)] mb-1\">Start</label><input data-hb=\"ahStart\" type=\"time\" className=\"provider-key-input\" value={cfg.active_hours?.start || \"08:00\"} /></div>\n\t\t\t\t\t<div><label className=\"block text-xs text-[var(--muted)] mb-1\">End</label><input data-hb=\"ahEnd\" type=\"time\" className=\"provider-key-input\" value={cfg.active_hours?.end === \"24:00\" ? \"23:59\" : cfg.active_hours?.end || \"23:59\"} /></div>\n\t\t\t\t</div>\n\t\t\t\t<div className=\"mt-3\">\n\t\t\t\t\t<label className=\"block text-xs text-[var(--muted)] mb-1\">Timezone</label>\n\t\t\t\t\t<select data-hb=\"ahTz\" className=\"provider-key-input\">\n\t\t\t\t\t\t<option value=\"local\" selected={!cfg.active_hours?.timezone || cfg.active_hours?.timezone === \"local\"}>Local ({systemTimezone})</option>\n\t\t\t\t\t\t<option value=\"UTC\" selected={cfg.active_hours?.timezone === \"UTC\"}>UTC</option>\n\t\t\t\t\t\t<option value=\"America/New_York\" selected={cfg.active_hours?.timezone === \"America/New_York\"}>America/New_York (EST/EDT)</option>\n\t\t\t\t\t\t<option value=\"America/Chicago\" selected={cfg.active_hours?.timezone === \"America/Chicago\"}>America/Chicago (CST/CDT)</option>\n\t\t\t\t\t\t<option value=\"America/Denver\" selected={cfg.active_hours?.timezone === \"America/Denver\"}>America/Denver (MST/MDT)</option>\n\t\t\t\t\t\t<option value=\"America/Los_Angeles\" selected={cfg.active_hours?.timezone === \"America/Los_Angeles\"}>America/Los_Angeles (PST/PDT)</option>\n\t\t\t\t\t\t<option value=\"Europe/London\" selected={cfg.active_hours?.timezone === \"Europe/London\"}>Europe/London (GMT/BST)</option>\n\t\t\t\t\t\t<option value=\"Europe/Paris\" selected={cfg.active_hours?.timezone === \"Europe/Paris\"}>Europe/Paris (CET/CEST)</option>\n\t\t\t\t\t\t<option value=\"Europe/Berlin\" selected={cfg.active_hours?.timezone === \"Europe/Berlin\"}>Europe/Berlin (CET/CEST)</option>\n\t\t\t\t\t\t<option value=\"Asia/Tokyo\" selected={cfg.active_hours?.timezone === \"Asia/Tokyo\"}>Asia/Tokyo (JST)</option>\n\t\t\t\t\t\t<option value=\"Asia/Shanghai\" selected={cfg.active_hours?.timezone === \"Asia/Shanghai\"}>Asia/Shanghai (CST)</option>\n\t\t\t\t\t\t<option value=\"Asia/Singapore\" selected={cfg.active_hours?.timezone === \"Asia/Singapore\"}>Asia/Singapore (SGT)</option>\n\t\t\t\t\t\t<option value=\"Australia/Sydney\" selected={cfg.active_hours?.timezone === \"Australia/Sydney\"}>Australia/Sydney (AEST/AEDT)</option>\n\t\t\t\t\t</select>\n\t\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t{/* Sandbox */}\n\t\t\t<div style={{ marginTop: \"24px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Sandbox</h3>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] mb-3\">Run heartbeat commands in an isolated container.</p>\n\t\t\t\t<div className=\"flex items-center gap-3 mb-3\"><label className=\"cron-toggle\"><input data-hb=\"sandboxEnabled\" type=\"checkbox\" checked={cfg.sandbox_enabled !== false} /><span className=\"cron-slider\" /></label><span className=\"text-sm text-[var(--text)]\">Enable sandbox</span></div>\n\t\t\t\t<div><label className=\"block text-xs text-[var(--muted)] mb-1\">Sandbox Image</label><ComboSelect options={sandboxImages.value.map((img) => ({ value: img.tag, label: img.tag }))} value={heartbeatSandboxImage.value} onChange={(v: string) => { heartbeatSandboxImage.value = v; }} placeholder=\"Default image\" searchPlaceholder=\"Search images\\u2026\" /></div>\n\t\t\t</div>\n\n\t\t\t{/* Recent Runs */}\n\t\t\t<div style={{ marginTop: \"24px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Recent Runs</h3>\n\t\t\t\t<HeartbeatRunsList runs={heartbeatRuns.value} />\n\t\t\t</div>\n\n\t\t\t{/* Save */}\n\t\t\t<div style={{ marginTop: \"24px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<button className=\"provider-btn\" onClick={onSave} disabled={saving}>{saving ? \"Saving\\u2026\" : \"Save\"}</button>\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// ── Cron Jobs ────────────────────────────────────────────────\n\nfunction StatusBar(): VNode {\n\tconst s = cronStatus.value;\n\tif (!s) return <div className=\"cron-status-bar\">Loading&hellip;</div>;\n\tconst parts = [s.running ? \"Running\" : \"Stopped\", `${s.jobCount} job${s.jobCount === 1 ? \"\" : \"s\"}`, `${s.enabledCount} enabled`];\n\tif (s.nextRunAtMs) parts.push(`next: ${new Date(s.nextRunAtMs).toLocaleString()}`);\n\treturn <div className=\"cron-status-bar\">{parts.join(\" \\u2022 \")}</div>;\n}\n\nfunction CronJobRow({ job }: { job: CronJob }): VNode {\n\tconst modelLabel = job.payload?.kind === \"agentTurn\" ? job.payload.model || \"default\" : \"\\u2014\";\n\tconst deliveryLabel = job.payload?.deliver && job.payload?.channel ? `\\u2192 ${job.payload.channel}` : null;\n\tconst executionLabel = job.sandbox?.enabled === false ? \"host\" : job.sandbox?.image ? `sandbox (${job.sandbox.image})` : \"sandbox (default)\";\n\tfunction onToggle(e: Event): void { sendRpc(\"cron.update\", { id: job.id, patch: { enabled: (e.target as HTMLInputElement).checked } }).then(() => { loadJobs(); loadStatus(); }); }\n\tfunction onRun(): void { sendRpc(\"cron.run\", { id: job.id, force: true }).then(() => { loadJobs(); loadStatus(); }); }\n\tfunction onDelete(): void { requestConfirm(`Delete job '${job.name}'?`).then((yes) => { if (yes) sendRpc(\"cron.remove\", { id: job.id }).then(() => { loadJobs(); loadStatus(); }); }); }\n\tfunction onHistory(): void { runsHistory.value = { jobId: job.id, jobName: job.name, runs: null }; sendRpc(\"cron.runs\", { id: job.id }).then((res) => { if (res?.ok) runsHistory.value = { jobId: job.id, jobName: job.name, runs: (res.payload as CronRun[]) || [] }; }); }\n\n\treturn (\n\t\t<tr>\n\t\t\t<td>{job.name}</td>\n\t\t\t<td className=\"cron-mono\">{formatSchedule(job.schedule)}</td>\n\t\t\t<td className=\"cron-mono\">{modelLabel}</td>\n\t\t\t<td className=\"cron-mono\">{deliveryLabel ? <span className=\"text-xs\">{deliveryLabel}</span> : \"\\u2014\"}</td>\n\t\t\t<td className=\"cron-mono\">{executionLabel}</td>\n\t\t\t<td className=\"cron-mono\">{job.state?.nextRunAtMs ? <time data-epoch-ms={job.state.nextRunAtMs}>{new Date(job.state.nextRunAtMs).toISOString()}</time> : \"\\u2014\"}</td>\n\t\t\t<td>{job.state?.lastStatus ? <span className={`cron-badge ${job.state.lastStatus}`}>{job.state.lastStatus}</span> : \"\\u2014\"}</td>\n\t\t\t<td className=\"cron-actions\">\n\t\t\t\t<button className=\"cron-action-btn\" onClick={() => { editingJob.value = job; showModal.value = true; }}>Edit</button>\n\t\t\t\t<button className=\"cron-action-btn\" onClick={onRun}>Run</button>\n\t\t\t\t<button className=\"cron-action-btn\" onClick={onHistory}>History</button>\n\t\t\t\t<button className=\"cron-action-btn cron-action-danger\" onClick={onDelete}>Delete</button>\n\t\t\t</td>\n\t\t\t<td><label className=\"cron-toggle\"><input type=\"checkbox\" checked={job.enabled} onChange={onToggle} /><span className=\"cron-slider\" /></label></td>\n\t\t</tr>\n\t);\n}\n\nfunction CronJobTable(): VNode {\n\tconst jobs = cronJobs.value.filter((j) => !j.system);\n\tif (jobs.length === 0) return <div className=\"text-sm text-[var(--muted)]\">No cron jobs configured.</div>;\n\treturn (\n\t\t<table className=\"cron-table\">\n\t\t\t<thead><tr><th>Name</th><th>Schedule</th><th>Model</th><th>Delivery</th><th>Execution</th><th>Next Run</th><th>Last Status</th><th>Actions</th><th>Enabled</th></tr></thead>\n\t\t\t<tbody>{jobs.map((job) => <CronJobRow key={job.id} job={job} />)}</tbody>\n\t\t</table>\n\t);\n}\n\nfunction RunHistoryPanel(): VNode | null {\n\tconst h = runsHistory.value;\n\tif (!h) return null;\n\treturn (\n\t\t<div className=\"mb-md\">\n\t\t\t<div className=\"flex items-center justify-between mb-md\">\n\t\t\t\t<span className=\"text-sm font-medium text-[var(--text-strong)]\">Run History: {h.jobName}</span>\n\t\t\t\t<button className=\"text-xs text-[var(--muted)] cursor-pointer bg-transparent border-none hover:text-[var(--text)]\" onClick={() => { runsHistory.value = null; }}>&times; Close</button>\n\t\t\t</div>\n\t\t\t{h.runs === null && <div className=\"text-sm text-[var(--muted)]\">Loading&hellip;</div>}\n\t\t\t{h.runs !== null && h.runs.length === 0 && <div className=\"text-xs text-[var(--muted)]\">No runs yet.</div>}\n\t\t\t{h.runs?.map((run) => (\n\t\t\t\t<div className=\"cron-run-item\" key={run.startedAtMs}>\n\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\"><time data-epoch-ms={run.startedAtMs}>{new Date(run.startedAtMs).toISOString()}</time></span>\n\t\t\t\t\t<span className={`cron-badge ${run.status}`}>{run.status}</span>\n\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">{run.durationMs}ms</span>\n\t\t\t\t\t<TokenBadge run={run} />\n\t\t\t\t\t{run.error && <span className=\"text-xs text-[var(--error)]\">{run.error}</span>}\n\t\t\t\t</div>\n\t\t\t))}\n\t\t</div>\n\t);\n}\n\nfunction parseScheduleFromForm(kind: string, signals: Record<string, string>): { schedule?: CronSchedule; error?: string } {\n\tif (kind === \"at\") { const ts = new Date(signals.schedAtTimestamp).getTime(); if (Number.isNaN(ts)) return { error: \"at\" }; return { schedule: { kind: \"at\", at_ms: ts } }; }\n\tif (kind === \"every\") { const secs = parseInt(signals.schedEverySecs, 10); if (Number.isNaN(secs) || secs <= 0) return { error: \"every\" }; return { schedule: { kind: \"every\", every_ms: secs * 1000 } }; }\n\tconst expr = signals.schedCronExpr.trim(); if (!expr) return { error: \"cron\" };\n\tconst schedule: CronSchedule = { kind: \"cron\", expr }; const tz = signals.schedCronTz.trim(); if (tz) schedule.tz = tz;\n\treturn { schedule };\n}\n\nfunction CronModal(): VNode {\n\tconst isEdit = !!editingJob.value;\n\tconst job = editingJob.value;\n\tconst saving = useSignal(false);\n\tconst schedKind = useSignal(\"cron\");\n\tconst errorField = useSignal<string | null>(null);\n\tconst jobModel = useSignal(\"\"); const jobSandboxImage = useSignal(\"\"); const jobName = useSignal(\"\");\n\tconst payloadKind = useSignal(\"systemEvent\"); const sessionTarget = useSignal(\"main\");\n\tconst messageText = useSignal(\"\"); const executionTarget = useSignal(\"sandbox\");\n\tconst deleteAfterRun = useSignal(false); const jobEnabled = useSignal(true);\n\tconst deliverToChannel = useSignal(false); const deliverChannel = useSignal(\"\"); const deliverTo = useSignal(\"\");\n\tconst schedCronExpr = useSignal(\"\"); const schedCronTz = useSignal(\"\");\n\tconst schedEverySecs = useSignal(\"\"); const schedAtTimestamp = useSignal(\"\");\n\n\tuseEffect(() => {\n\t\tif (editingJob.value) {\n\t\t\tconst j = editingJob.value;\n\t\t\tsaving.value = false; errorField.value = null; schedKind.value = j.schedule.kind;\n\t\t\tjobModel.value = j.payload.kind === \"agentTurn\" ? j.payload.model || \"\" : \"\";\n\t\t\tjobSandboxImage.value = j.sandbox?.image || \"\"; jobName.value = j.name;\n\t\t\tpayloadKind.value = j.payload.kind; sessionTarget.value = j.sessionTarget || \"main\";\n\t\t\tmessageText.value = j.payload.text || j.payload.message || \"\";\n\t\t\texecutionTarget.value = j.sandbox?.enabled === false ? \"host\" : \"sandbox\";\n\t\t\tdeleteAfterRun.value = !!j.deleteAfterRun; jobEnabled.value = j.enabled;\n\t\t\tdeliverToChannel.value = j.payload?.deliver === true;\n\t\t\tdeliverChannel.value = j.payload?.channel || \"\"; deliverTo.value = j.payload?.to || \"\";\n\t\t\tschedCronExpr.value = j.schedule.kind === \"cron\" ? j.schedule.expr || \"\" : \"\";\n\t\t\tschedCronTz.value = j.schedule.kind === \"cron\" ? j.schedule.tz || \"\" : \"\";\n\t\t\tschedEverySecs.value = j.schedule.kind === \"every\" ? String(Math.round(j.schedule.every_ms! / 1000)) : \"\";\n\t\t\tschedAtTimestamp.value = j.schedule.kind === \"at\" ? new Date(j.schedule.at_ms!).toISOString().slice(0, 16) : \"\";\n\t\t} else {\n\t\t\tsaving.value = false; errorField.value = null; schedKind.value = \"cron\";\n\t\t\tjobModel.value = \"\"; jobSandboxImage.value = \"\"; jobName.value = \"\";\n\t\t\tpayloadKind.value = \"systemEvent\"; sessionTarget.value = \"main\"; messageText.value = \"\";\n\t\t\texecutionTarget.value = \"sandbox\"; deleteAfterRun.value = false; jobEnabled.value = true;\n\t\t\tdeliverToChannel.value = false; deliverChannel.value = \"\"; deliverTo.value = \"\";\n\t\t\tschedCronExpr.value = \"\"; schedCronTz.value = \"\"; schedEverySecs.value = \"\"; schedAtTimestamp.value = \"\";\n\t\t}\n\t}, [editingJob.value]);\n\n\tfunction onSave(e: Event): void {\n\t\te.preventDefault();\n\t\tconst name = jobName.value.trim(); if (!name) { errorField.value = \"name\"; return; }\n\t\tconst parsed = parseScheduleFromForm(schedKind.value, { schedCronExpr: schedCronExpr.value, schedCronTz: schedCronTz.value, schedEverySecs: schedEverySecs.value, schedAtTimestamp: schedAtTimestamp.value });\n\t\tif (parsed.error) { errorField.value = parsed.error; return; }\n\t\tconst msgText = messageText.value.trim(); if (!msgText) { errorField.value = \"message\"; return; }\n\t\tconst pk = payloadKind.value;\n\t\tconst payload: Record<string, unknown> = pk === \"systemEvent\" ? { kind: \"systemEvent\", text: msgText } : { kind: \"agentTurn\", message: msgText, deliver: deliverToChannel.value, ...(deliverToChannel.value && deliverChannel.value ? { channel: deliverChannel.value } : {}), ...(deliverToChannel.value && deliverTo.value.trim() ? { to: deliverTo.value.trim() } : {}) };\n\t\tif (pk === \"agentTurn\" && jobModel.value) payload.model = jobModel.value;\n\t\tconst sandboxEnabled = executionTarget.value === \"sandbox\";\n\t\tconst fields = { name, schedule: parsed.schedule, payload, sessionTarget: sessionTarget.value, deleteAfterRun: deleteAfterRun.value, enabled: jobEnabled.value, sandbox: { enabled: sandboxEnabled, image: sandboxEnabled ? jobSandboxImage.value || null : null } };\n\t\tsaving.value = true;\n\t\tconst rpcMethod = isEdit ? \"cron.update\" : \"cron.add\";\n\t\tconst rpcParams = isEdit ? { id: job!.id, patch: fields } : fields;\n\t\tsendRpc(rpcMethod, rpcParams).then((res) => { saving.value = false; if (res?.ok) { showModal.value = false; editingJob.value = null; loadJobs(); loadStatus(); } });\n\t}\n\n\tfunction schedParams(): VNode {\n\t\tif (schedKind.value === \"at\") return <input data-field=\"at\" className={`provider-key-input ${errorField.value === \"at\" ? \"field-error\" : \"\"}`} type=\"datetime-local\" value={schedAtTimestamp.value} onInput={(e) => { schedAtTimestamp.value = (e.target as HTMLInputElement).value; }} />;\n\t\tif (schedKind.value === \"every\") return <input data-field=\"every\" className={`provider-key-input ${errorField.value === \"every\" ? \"field-error\" : \"\"}`} type=\"number\" placeholder=\"Interval in seconds\" min=\"1\" value={schedEverySecs.value} onInput={(e) => { schedEverySecs.value = (e.target as HTMLInputElement).value; }} />;\n\t\treturn (<>\n\t\t\t<input data-field=\"cron\" className={`provider-key-input ${errorField.value === \"cron\" ? \"field-error\" : \"\"}`} placeholder=\"*/5 * * * *\" value={schedCronExpr.value} onInput={(e) => { schedCronExpr.value = (e.tar