=> {\n\t\t\tcachedImages.value = [];\n\t\t});\n}\n\nfunction ProjectEditForm(props: ProjectEditFormProps): VNode {\n\tconst p = props.project;\n\tconst labelRef = useRef<HTMLInputElement>(null);\n\tconst dirRef = useRef<HTMLInputElement>(null);\n\tconst promptRef = useRef<HTMLTextAreaElement>(null);\n\tconst setupRef = useRef<HTMLInputElement>(null);\n\tconst teardownRef = useRef<HTMLInputElement>(null);\n\tconst prefixRef = useRef<HTMLInputElement>(null);\n\tconst wtRef = useRef<HTMLInputElement>(null);\n\tconst imageRef = useRef<HTMLInputElement>(null);\n\n\tuseEffect(() => {\n\t\tfetchCachedImages();\n\t}, []);\n\n\tfunction onSave(): void {\n\t\tconst updated: Project = JSON.parse(JSON.stringify(p));\n\t\tupdated.label = labelRef.current?.value.trim() || p.label;\n\t\tupdated.directory = dirRef.current?.value.trim() || p.directory;\n\t\tupdated.system_prompt = promptRef.current?.value.trim() || null;\n\t\tupdated.setup_command = setupRef.current?.value.trim() || null;\n\t\tupdated.teardown_command = teardownRef.current?.value.trim() || null;\n\t\tupdated.branch_prefix = prefixRef.current?.value.trim() || null;\n\t\tupdated.auto_worktree = wtRef.current?.checked;\n\t\tupdated.sandbox_image = imageRef.current?.value.trim() || null;\n\t\tupdated.updated_at = Date.now();\n\t\tsendRpc(\"projects.upsert\", updated).then(() => {\n\t\t\teditingProject.value = null;\n\t\t\tfetchProjects();\n\t\t});\n\t}\n\n\tfunction field(\n\t\tlabel: string,\n\t\tref: { current: HTMLInputElement | null },\n\t\tvalue: string | null | undefined,\n\t\tplaceholder: string,\n\t\tmono?: boolean,\n\t): VNode {\n\t\treturn (\n\t\t\t<div className=\"project-edit-group\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)] project-edit-label\">{label}</div>\n\t\t\t\t<input\n\t\t\t\t\tref={ref}\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={value || \"\"}\n\t\t\t\t\tplaceholder={placeholder || \"\"}\n\t\t\t\t\tstyle={mono ? { fontFamily: \"var(--font-mono)\", width: \"100%\" } : { width: \"100%\" }}\n\t\t\t\t/>\n\t\t\t</div>\n\t\t);\n\t}\n\n\treturn (\n\t\t<div className=\"project-edit-form\">\n\t\t\t{field(t(\"projects:editForm.label\"), labelRef, p.label, t(\"projects:editForm.labelPlaceholder\"))}\n\t\t\t{field(t(\"projects:editForm.directory\"), dirRef, p.directory, t(\"projects:editForm.directoryPlaceholder\"), true)}\n\t\t\t<div className=\"project-edit-group\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)] project-edit-label\">{t(\"projects:editForm.systemPrompt\")}</div>\n\t\t\t\t<textarea\n\t\t\t\t\tref={promptRef}\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tplaceholder={t(\"projects:editForm.systemPromptPlaceholder\")}\n\t\t\t\t\tstyle={{ width: \"100%\", minHeight: \"60px\", resize: \"vertical\", fontSize: \".8rem\" }}\n\t\t\t\t>\n\t\t\t\t\t{p.system_prompt || \"\"}\n\t\t\t\t</textarea>\n\t\t\t</div>\n\t\t\t{field(\n\t\t\t\tt(\"projects:editForm.setupCommand\"),\n\t\t\t\tsetupRef,\n\t\t\t\tp.setup_command,\n\t\t\t\tt(\"projects:editForm.setupCommandPlaceholder\"),\n\t\t\t\ttrue,\n\t\t\t)}\n\t\t\t{field(\n\t\t\t\tt(\"projects:editForm.teardownCommand\"),\n\t\t\t\tteardownRef,\n\t\t\t\tp.teardown_command,\n\t\t\t\tt(\"projects:editForm.teardownCommandPlaceholder\"),\n\t\t\t\ttrue,\n\t\t\t)}\n\t\t\t{field(\n\t\t\t\tt(\"projects:editForm.branchPrefix\"),\n\t\t\t\tprefixRef,\n\t\t\t\tp.branch_prefix,\n\t\t\t\tt(\"projects:editForm.branchPrefixPlaceholder\"),\n\t\t\t\ttrue,\n\t\t\t)}\n\t\t\t<div className=\"project-edit-group\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)] project-edit-label\">{t(\"projects:editForm.sandboxImage\")}</div>\n\t\t\t\t<input\n\t\t\t\t\tref={imageRef}\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tlist=\"project-image-list\"\n\t\t\t\t\tvalue={p.sandbox_image || \"\"}\n\t\t\t\t\tplaceholder={t(\"projects:editForm.sandboxImagePlaceholder\")}\n\t\t\t\t\tstyle={{ width: \"100%\", fontFamily: \"var(--font-mono)\", fontSize: \".8rem\" }}\n\t\t\t\t/>\n\t\t\t\t<datalist id=\"project-image-list\">\n\t\t\t\t\t{cachedImages.value.map((img) => (\n\t\t\t\t\t\t<option key={img.tag} value={img.tag} />\n\t\t\t\t\t))}\n\t\t\t\t</datalist>\n\t\t\t</div>\n\t\t\t<div style={{ marginBottom: \"10px\", display: \"flex\", alignItems: \"center\", gap: \"8px\" }}>\n\t\t\t\t<input ref={wtRef} type=\"checkbox\" checked={p.auto_worktree} />\n\t\t\t\t<span className=\"text-xs text-[var(--text)]\">{t(\"projects:editForm.autoWorktree\")}</span>\n\t\t\t</div>\n\t\t\t<div style={{ display: \"flex\", gap: \"8px\" }}>\n\t\t\t\t<button className=\"provider-btn\" onClick={onSave}>\n\t\t\t\t\t{t(\"common:actions.save\")}\n\t\t\t\t</button>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\teditingProject.value = null;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{t(\"common:actions.cancel\")}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nfunction ProjectCard(props: ProjectCardProps): VNode {\n\tconst p = props.project;\n\n\tfunction onDelete(): void {\n\t\tsendRpc(\"projects.delete\", { id: p.id }).then(() => fetchProjects());\n\t}\n\n\treturn (\n\t\t<div className=\"provider-item\" style={{ marginBottom: \"6px\" }}>\n\t\t\t<div style={{ flex: 1, minWidth: 0 }}>\n\t\t\t\t<div className=\"flex items-center gap-2\">\n\t\t\t\t\t<div className=\"provider-item-name\">{p.label || p.id}</div>\n\t\t\t\t\t{p.detected && <span className=\"provider-item-badge api-key\">{t(\"projects:badges.auto\")}</span>}\n\t\t\t\t\t{p.auto_worktree && <span className=\"provider-item-badge oauth\">{t(\"projects:badges.worktree\")}</span>}\n\t\t\t\t\t{p.setup_command && <span className=\"provider-item-badge api-key\">{t(\"projects:badges.setup\")}</span>}\n\t\t\t\t\t{p.teardown_command && (\n\t\t\t\t\t\t<span className=\"provider-item-badge api-key\">{t(\"projects:badges.teardown\")}</span>\n\t\t\t\t\t)}\n\t\t\t\t\t{p.branch_prefix && <span className=\"provider-item-badge oauth\">{p.branch_prefix}/*</span>}\n\t\t\t\t\t{p.sandbox_image && (\n\t\t\t\t\t\t<span className=\"provider-item-badge api-key\" title={p.sandbox_image}>\n\t\t\t\t\t\t\t{t(\"projects:badges.image\")}\n\t\t\t\t\t\t</span>\n\t\t\t\t\t)}\n\t\t\t\t</div>\n\t\t\t\t<div\n\t\t\t\t\tstyle={{\n\t\t\t\t\t\tfontSize: \".72rem\",\n\t\t\t\t\t\tcolor: \"var(--muted)\",\n\t\t\t\t\t\tfontFamily: \"var(--font-mono)\",\n\t\t\t\t\t\twhiteSpace: \"nowrap\",\n\t\t\t\t\t\toverflow: \"hidden\",\n\t\t\t\t\t\ttextOverflow: \"ellipsis\",\n\t\t\t\t\t\tmarginTop: \"2px\",\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{p.directory}\n\t\t\t\t</div>\n\t\t\t\t{p.system_prompt && (\n\t\t\t\t\t<div style={{ fontSize: \".7rem\", color: \"var(--muted)\", marginTop: \"2px\", fontStyle: \"italic\" }}>\n\t\t\t\t\t\t{t(\"projects:card.systemPromptPrefix\")}\n\t\t\t\t\t\t{p.system_prompt.substring(0, 80)}\n\t\t\t\t\t\t{p.system_prompt.length > 80 ? \"...\" : \"\"}\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t</div>\n\t\t\t<div style={{ display: \"flex\", gap: \"4px\", flexShrink: 0 }}>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"session-action-btn\"\n\t\t\t\t\ttitle={t(\"projects:card.editProject\")}\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\teditingProject.value = p.id;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{t(\"projects:card.edit\")}\n\t\t\t\t</button>\n\t\t\t\t<button className=\"session-action-btn session-delete\" title={t(\"projects:card.removeProject\")} onClick={onDelete}>\n\t\t\t\t\tx\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nfunction ProjectsPageComponent(): VNode {\n\tuseEffect(() => {\n\t\tsendRpc(\"projects.list\", {}).then((res) => {\n\t\t\tif (res?.ok) S.setProjects((res.payload as Project[]) || []);\n\t\t});\n\t}, []);\n\n\tfunction onAdd(dir: string): Promise<void> {\n\t\treturn sendRpc(\"projects.detect\", { directories: [dir] }).then((res) => {\n\t\t\tif (res?.ok) {\n\t\t\t\tconst detected = (res.payload as Project[]) || [];\n\t\t\t\tif (detected.length === 0) {\n\t\t\t\t\tconst slug = dir.split(\"/\").filter(Boolean).pop() || \"project\";\n\t\t\t\t\tconst now = Date.now();\n\t\t\t\t\treturn sendRpc(\"projects.upsert\", {\n\t\t\t\t\t\tid: slug.toLowerCase().replace(/[^a-z0-9-]/g, \"-\"),\n\t\t\t\t\t\tlabel: slug,\n\t\t\t\t\t\tdirectory: dir,\n\t\t\t\t\t\tauto_worktree: false,\n\t\t\t\t\t\tdetected: false,\n\t\t\t\t\t\tcreated_at: now,\n\t\t\t\t\t\tupdated_at: now,\n\t\t\t\t\t}).then(() => fetchProjects()) as Promise<void>;\n\t\t\t\t}\n\t\t\t\tfetchProjects();\n\t\t\t}\n\t\t});\n\t}\n\n\tfunction onDetect(): void {\n\t\tdetecting.value = true;\n\t\tsendRpc(\"projects.detect\", { directories: [] }).then(() => {\n\t\t\tdetecting.value = false;\n\t\t\tfetchProjects();\n\t\t});\n\t}\n\n\tfunction onClearAll(): void {\n\t\tif (clearing.value) return;\n\t\trequestConfirm(t(\"projects:confirmClearAll\"), {\n\t\t\tconfirmLabel: t(\"projects:confirmClearAllButton\"),\n\t\t\tdanger: true,\n\t\t}).then((yes) => {\n\t\t\tif (!yes) return;\n\t\t\tconst ids = (projectsSig.value as unknown as Project[]).map((p) => p.id);\n\t\t\tif (ids.length === 0) return;\n\t\t\tclearing.value = true;\n\t\t\tlet chain = Promise.resolve();\n\t\t\tfor (const id of ids) {\n\t\t\t\tchain = chain.then(() => sendRpc(\"projects.delete\", { id: id }) as unknown as Promise<void>);\n\t\t\t}\n\t\t\tchain\n\t\t\t\t.then(() => fetchProjects())\n\t\t\t\t.finally(() => {\n\t\t\t\t\tclearing.value = false;\n\t\t\t\t});\n\t\t});\n\t}\n\n\tconst list = projectsSig.value as unknown as Project[];\n\tconst clearDisabled = clearing.value || detecting.value || list.length === 0;\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">{t(\"projects:title\")}</h2>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\tonClick={onDetect}\n\t\t\t\t\tdisabled={detecting.value}\n\t\t\t\t\ttitle={t(\"projects:autoDetectTooltip\")}\n\t\t\t\t>\n\t\t\t\t\t{detecting.value ? t(\"projects:detecting\") : t(\"projects:autoDetect\")}\n\t\t\t\t</button>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-danger\"\n\t\t\t\t\tonClick={onClearAll}\n\t\t\t\t\tdisabled={clearDisabled}\n\t\t\t\t\ttitle={t(\"projects:clearAllTooltip\")}\n\t\t\t\t>\n\t\t\t\t\t{clearing.value ? t(\"projects:clearing\") : t(\"projects:clearAll\")}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<p className=\"text-xs text-[var(--muted)] max-w-form\">\n\t\t\t\tClear All only removes repository entries from Moltis, it does not delete anything from disk.\n\t\t\t</p>\n\t\t\t<p className=\"text-sm text-[var(--muted)]\" style={{ maxWidth: \"600px\", margin: 0 }}>\n\t\t\t\tProjects bind sessions to a codebase directory. When a session is linked to a project, context files\n\t\t\t\t(CLAUDE.md, AGENTS.md, .cursorrules, and rule directories) are loaded automatically, scanned for risky\n\t\t\t\tprompt-injection patterns, and injected into the system prompt. Enable auto-worktree to give each session\n\t\t\t\tits own git branch for isolated work.\n\t\t\t</p>\n\t\t\t<p className=\"text-sm text-[var(--muted)]\" style={{ maxWidth: \"600px\", margin: 0 }}>\n\t\t\t\t<strong className=\"text-[var(--text)]\">Auto-detect</strong> scans common directories under your home\n\t\t\t\tfolder (<code className=\"font-mono text-xs\">~/Projects</code>,{\" \"}\n\t\t\t\t<code className=\"font-mono text-xs\">~/Developer</code>,{\" \"}\n\t\t\t\t<code className=\"font-mono text-xs\">~/src</code>,{\" \"}\n\t\t\t\t<code className=\"font-mono text-xs\">~/code</code>,{\" \"}\n\t\t\t\t<code className=\"font-mono text-xs\">~/repos</code>,{\" \"}\n\t\t\t\t<code className=\"font-mono text-xs\">~/workspace</code>,{\" \"}\n\t\t\t\t<code className=\"font-mono text-xs\">~/dev</code>,{\" \"}\n\t\t\t\t<code className=\"font-mono text-xs\">~/git</code>) and Superset worktrees (\n\t\t\t\t<code className=\"font-mono text-xs\">~/.superset/worktrees</code>) for git repositories and adds them as\n\t\t\t\tprojects.\n\t\t\t</p>\n\t\t\t<div className=\"project-form-row\">\n\t\t\t\t<PathInput onAdd={onAdd} />\n\t\t\t</div>\n\t\t\t<div style={{ maxWidth: \"600px\", marginTop: \"8px\" }}>\n\t\t\t\t{list.length === 0 && (\n\t\t\t\t\t<div className=\"text-sm text-[var(--muted)]\" style={{ padding: \"12px 0\" }}>\n\t\t\t\t\t\tNo projects configured. Add a directory above or use auto-detect.\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t{list.map((p) =>\n\t\t\t\t\teditingProject.value === p.id ? (\n\t\t\t\t\t\t<ProjectEditForm key={p.id} project={p} />\n\t\t\t\t\t) : (\n\t\t\t\t\t\t<ProjectCard key={p.id} project={p} />\n\t\t\t\t\t),\n\t\t\t\t)}\n\t\t\t</div>\n\t\t\t<ConfirmDialog />\n\t\t</div>\n\t);\n}\n\nexport function initProjects(container: HTMLElement): void {\n\t_projectsContainer = container;\n\tcontainer.style.cssText = \"flex-direction:column;padding:0;overflow:hidden;\";\n\teditingProject.value = null;\n\tcompletions.value = [];\n\tdetecting.value = false;\n\tclearing.value = false;\n\trender(<ProjectsPageComponent />, container);\n}\n\nexport function teardownProjects(): void {\n\tif (_projectsContainer) render(null, _projectsContainer);\n\t_projectsContainer = null;\n}\n\nregisterPage(routes.projects!, initProjects, teardownProjects);\n","// ── Skills page (Preact + Signals) ───────────────────────────\n// Note: body_html is server-rendered trusted content from SKILL.md\n// processed by pulldown-cmark on the Rust gateway side.\n\nimport { computed, signal, useSignal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect, useRef } from \"preact/hooks\";\nimport { onEvent } from \"../events\";\nimport { sendRpc } from \"../helpers\";\nimport { updateNavCount } from \"../nav-counts\";\nimport { registerPage } from \"../router\";\nimport { routes } from \"../routes\";\nimport * as S from \"../state\";\nimport { ConfirmDialog, requestConfirm } from \"../ui\";\n\n// ── Types ────────────────────────────────────────────────────\n\ninterface SkillSummary { name: string; description?: string; source?: string; enabled?: boolean; protected?: boolean; display_name?: string; quarantined?: boolean; trusted?: boolean; drifted?: boolean; eligible?: boolean; }\ninterface SkillDetail extends SkillSummary { body?: string; body_html?: string; author?: string; version?: string; homepage?: string; source_url?: string; commit_sha?: string; commit_url?: string; commit_age_days?: number; compatibility?: string; allowed_tools?: string[]; license?: string; license_url?: string; missing_bins?: string[]; install_options?: { label?: string; kind?: string }[]; requires?: { bins?: string[]; any_bins?: string[] }; provenance?: { original_source?: string; original_commit_sha?: string; imported_from?: string }; quarantine_reason?: string; }\ninterface RepoSummary { source: string; skill_count: number; enabled_count: number; commit_sha?: string; quarantined?: boolean; drifted?: boolean; orphaned?: boolean; repo_name?: string; provenance?: { original_source?: string; original_commit_sha?: string; imported_from?: string }; quarantine_reason?: string; }\ninterface ToastItem { id: number; message: string; type: string; }\ninterface InstallProgress { id: string; source: string; state: string; }\n\nconst repos = signal<RepoSummary[]>([]);\nconst enabledSkills = signal<SkillSummary[]>([]);\nconst loading = signal(false);\nconst toasts = signal<ToastItem[]>([]);\nlet toastId = 0;\nconst installProgresses = signal<InstallProgress[]>([]);\nlet installProgressId = 0;\n\nlet prefetchPromise: Promise<unknown> | null = null;\nfunction ensurePrefetch(): Promise<unknown> {\n\tif (!prefetchPromise) prefetchPromise = fetch(\"/api/skills\").then((r) => r.json()).then((data) => { if (data.skills) enabledSkills.value = data.skills; if (data.repos) repos.value = data.repos; return data; }).catch(() => null);\n\treturn prefetchPromise;\n}\n\nconst skillRepoMap = computed<Record<string, string>>(() => { const map: Record<string, string> = {}; enabledSkills.value.forEach((s) => { if (s.source) map[s.name] = s.source; }); return map; });\n\nfunction showToast(message: string, type: string): void { const id = ++toastId; toasts.value = toasts.value.concat([{ id, message, type }]); setTimeout(() => { toasts.value = toasts.value.filter((t) => t.id !== id); }, 4000); }\nfunction shortSha(sha: string | null | undefined): string { return sha?.slice(0, 12) || \"\"; }\nfunction startInstallProgress(source: string, id?: string): string { const pid = id || `install-${++installProgressId}`; if (installProgresses.value.some((p) => p.id === pid)) return pid; installProgresses.value = [...installProgresses.value, { id: pid, source: source || \"repository\", state: \"running\" }]; return pid; }\nfunction stopInstallProgress(id: string, _ok: boolean): void { installProgresses.value = installProgresses.value.filter((p) => p.id !== id); }\n\nfunction emergencyDisableAllSkills(): void { requestConfirm(\"Disable all third-party skills now?\", { confirmLabel: \"Disable All\", danger: true }).then((yes) => { if (!yes) return; sendRpc(\"skills.emergency_disable\", {}).then((res) => { if (!res?.ok) { showToast(`Emergency disable failed: ${res?.error || \"unknown\"}`, \"error\"); return; } showToast(`Disabled ${(res.payload as Record<string,number>)?.skills_disabled || 0} skills`, \"success\"); fetchAll(); }); }); }\n\nfunction fetchAll(): void { loading.value = true; fetch(\"/api/skills\").then((r) => r.json()).then((data) => { if (data.skills) enabledSkills.value = data.skills; if (data.repos) repos.value = data.repos; loading.value = false; updateNavCount(\"skills\", (data.skills || []).length); }).catch(() => { loading.value = false; }); }\n\nfunction doInstall(source: string): Promise<void> { if (!(source && S.connected)) { if (!S.connected) showToast(\"Not connected to gateway.\", \"error\"); return Promise.resolve(); } const opId = `skills-install-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`; const pid = startInstallProgress(source, opId); return sendRpc(\"skills.install\", { source, op_id: opId }).then((res) => { if (res?.ok) { const p = (res.payload || {}) as Record<string, unknown[]>; showToast(`Installed ${source} (${(p.installed || []).length} skills)`, \"success\"); fetchAll(); stopInstallProgress(pid, true); } else { showToast(`Failed: ${res?.error || \"unknown error\"}`, \"error\"); stopInstallProgress(pid, false); } }); }\nfunction doImportBundle(path: string): Promise<void> { if (!(path && S.connected)) { if (!S.connected) showToast(\"Not connected.\", \"error\"); return Promise.resolve(); } return sendRpc(\"skills.repos.import\", { path }).then((res) => { if (res?.ok) { const p = (res.payload || {}) as Record<string, unknown>; showToast(`Imported ${p.repo_name || \"bundle\"} (${p.skill_count || 0} skills)`, \"success\"); fetchAll(); } else showToast(`Failed: ${res?.error || \"unknown\"}`, \"error\"); }); }\nfunction doExportBundle(source: string, path: string | null): Promise<void> { if (!(source && S.connected)) return Promise.resolve(); const params: Record<string, string> = { source }; if (path) params.path = path; return sendRpc(\"skills.repos.export\", params).then((res) => { if (res?.ok) showToast(`Exported ${source}`, \"success\"); else showToast(`Failed: ${res?.error || \"unknown\"}`, \"error\"); }); }\nexport function doUnquarantine(source: string): Promise<void> { if (!(source && S.connected)) return Promise.resolve(); return sendRpc(\"skills.repos.unquarantine\", { source }).then((res) => { if (res?.ok) { showToast(`Cleared quarantine for ${source}`, \"success\"); fetchAll(); } else showToast(`Failed: ${res?.error || \"unknown\"}`, \"error\"); }); }\nfunction searchSkills(source: string, query: string): Promise<SkillSummary[]> { return fetch(`/api/skills/search?source=${encodeURIComponent(source)}&q=${encodeURIComponent(query)}`).then((r) => r.json()).then((d) => d.skills || []); }\n\nfunction Toasts(): VNode { return (<div className=\"skills-toast-container\">{toasts.value.map((t) => { const bg = t.type === \"error\" ? \"var(--error, #e55)\" : \"var(--accent)\"; return <div key={t.id} style={{ pointerEvents: \"auto\", maxWidth: \"420px\", padding: \"10px 16px\", borderRadius: \"6px\", fontSize: \".8rem\", fontWeight: 500, color: \"#fff\", background: bg, boxShadow: \"0 4px 12px rgba(0,0,0,.15)\" }}>{t.message}</div>; })}</div>); }\nfunction InstallProgressBar(): VNode | null { const items = installProgresses.value; if (!items.length) return null; return (<div style={{ display: \"flex\", flexDirection: \"column\", gap: \"8px\" }}>{items.map((p) => <div key={p.id} style={{ border: \"1px solid var(--border)\", borderRadius: \"var(--radius-sm)\", padding: \"8px 10px\", background: \"var(--surface)\", fontSize: \".78rem\", color: \"var(--muted)\" }}><strong style={{ color: \"var(--text-strong)\" }}>Installing {p.source}...</strong><div style={{ marginTop: \"3px\" }}>This may take a while.</div></div>)}</div>); }\n\nfunction SecurityWarning(): VNode | null { const dismissed = useSignal(!!localStorage.getItem(\"moltis-skills-warning-dismissed\")); if (dismissed.value) return null; return (<div className=\"skills-warn\"><div className=\"skills-warn-title\">{\"\\u26a0\\ufe0f\"} Skills run code on your machine</div><div>Skills are community-authored instructions the agent follows <strong>with your full system privileges</strong>.</div><div style={{ marginTop: \"6px\", color: \"var(--success, #4a4)\" }}>With sandbox mode enabled, execution is isolated.</div><div style={{ display: \"flex\", gap: \"8px\", marginTop: \"8px\" }}><button onClick={() => { localStorage.setItem(\"moltis-skills-warning-dismissed\", \"1\"); dismissed.value = true; }} style={{ background: \"none\", border: \"1px solid var(--border)\", borderRadius: \"var(--radius-sm)\", fontSize: \".72rem\", padding: \"3px 10px\", cursor: \"pointer\", color: \"var(--muted)\" }}>Dismiss</button><button className=\"provider-btn provider-btn-danger provider-btn-sm\" onClick={emergencyDisableAllSkills}>Disable all</button></div></div>); }\n\nfunction InstallBox(): VNode { const ref = useRef<HTMLInputElement>(null); const installing = useSignal(false); function go(): void { const v = ref.current?.value.trim(); if (!v) return; installing.value = true; doInstall(v).then(() => { installing.value = false; if (ref.current) ref.current.value = \"\"; }); } return (<div className=\"skills-install-box\"><input ref={ref} type=\"text\" placeholder=\"owner/repo or full URL\" className=\"skills-install-input\" onKeyDown={(e) => { if ((e as KeyboardEvent).key === \"Enter\") go(); }} /><button className=\"provider-btn\" onClick={go} disabled={installing.value}>{installing.value ? \"Installing\\u2026\" : \"Install\"}</button></div>); }\nfunction BundleTransferBox(): VNode { const ref = useRef<HTMLInputElement>(null); const importing = useSignal(false); function go(): void { const p = ref.current?.value.trim(); if (!p) return; importing.value = true; doImportBundle(p).finally(() => { importing.value = false; }); } return (<div className=\"skills-install-box\"><input ref={ref} type=\"text\" placeholder=\"/path/to/skill-bundle.tar.gz\" className=\"skills-install-input\" onKeyDown={(e) => { if ((e as KeyboardEvent).key === \"Enter\") go(); }} /><button className=\"provider-btn provider-btn-secondary\" onClick={go} disabled={importing.value}>{importing.value ? \"Importing\\u2026\" : \"Import Bundle\"}</button></div>); }\n\nconst featuredSkills = [{ repo: \"openclaw/skills\", desc: \"Community skills from ClawdHub\" }, { repo: \"anthropics/skills\", desc: \"Official Anthropic agent skills\" }, { repo: \"vercel-labs/agent-skills\", desc: \"Vercel agent skills collection\" }, { repo: \"vercel-labs/skills\", desc: \"Vercel skills toolkit\" }];\nfunction FeaturedCard({ skill: f }: { skill: { repo: string; desc: string } }): VNode { const installing = useSignal(false); const href = /^https?:\\/\\//.test(f.repo) ? f.repo : `https://github.com/${f.repo}`; return (<div className=\"skills-featured-card\"><div><a href={href} target=\"_blank\" rel=\"noopener noreferrer\" style={{ fontFamily: \"var(--font-mono)\", fontSize: \".82rem\", fontWeight: 500, color: \"var(--text-strong)\", textDecoration: \"none\" }}>{f.repo}</a><div style={{ fontSize: \".75rem\", color: \"var(--muted)\" }}>{f.desc}</div></div><button onClick={() => { installing.value = true; doInstall(f.repo).then(() => { installing.value = false; }); }} disabled={installing.value} style={{ background: \"var(--surface2)\", border: \"1px solid var(--border)\", color: \"var(--text)\", borderRadius: \"var(--radius-sm)\", fontSize: \".72rem\", padding: \"4px 10px\", cursor: \"pointer\", whiteSpace: \"nowrap\" }}>{installing.value ? \"Installing\\u2026\" : \"Install\"}</button></div>); }\nfunction FeaturedSection(): VNode { return (<div className=\"skills-section\"><h3 className=\"skills-section-title\">Featured Repositories</h3><div className=\"skills-featured-grid\">{featuredSkills.map((f) => <FeaturedCard key={f.repo} skill={f} />)}</div></div>); }\n\nfunction SkillMetadata({ detail: d }: { detail: SkillDetail }): VNode | null { if (!(d.author || d.version || d.homepage || d.source_url || d.commit_sha)) return null; return (<div style={{ display: \"flex\", alignItems: \"center\", gap: \"12px\", marginBottom: \"8px\", fontSize: \".75rem\", color: \"var(--muted)\", flexWrap: \"wrap\" }}>{d.author && <span>Author: {d.author}</span>}{d.version && <span>v{d.version}</span>}{d.commit_sha && <span>Commit: <code>{shortSha(d.commit_sha)}</code></span>}{d.homepage && <a href={d.homepage} target=\"_blank\" rel=\"noopener noreferrer\" style={{ color: \"var(--accent)\", textDecoration: \"none\" }}>{d.homepage.replace(/^https?:\\/\\//, \"\")}</a>}</div>); }\n\nfunction SkillDetailPanel({ detail: d, repoSource, onClose, onReload }: { detail: SkillDetail; repoSource?: string; onClose: () => void; onReload?: () => void }): VNode | null {\n\tconst actionBusy = useSignal(false);\n\tconst bodyRef = useRef<HTMLDivElement>(null);\n\tuseEffect(() => {\n\t\tif (bodyRef.current && d?.body_html) {\n\t\t\tbodyRef.current.textContent = \"\";\n\t\t\t// Safe: body_html is server-rendered trusted HTML from SKILL.md via pulldown-cmark\n\t\t\tconst tpl = document.createElement(\"template\");\n\t\t\ttpl.innerHTML = d.body_html;\n\t\t\tbodyRef.current.appendChild(tpl.content);\n\t\t\tbodyRef.current.querySelectorAll(\"a\").forEach((a) => { a.setAttribute(\"target\", \"_blank\"); a.setAttribute(\"rel\", \"noopener\"); });\n\t\t}\n\t}, [d?.body_html]);\n\tif (!d) return null;\n\tconst isDisc = d.source === \"personal\" || d.source === \"project\";\n\tfunction doToggle(): void { actionBusy.value = true; sendRpc(d.enabled ? \"skills.skill.disable\" : \"skills.skill.enable\", { source: repoSource, skill: d.name }).then((r) => { actionBusy.value = false; if (r?.ok) { if (isDisc) onClose(); fetchAll(); onReload?.(); } else showToast(`Failed: ${r?.error || \"unknown\"}`, \"error\"); }); }\n\tfunction onToggle(): void { if (!S.connected || actionBusy.value) return; if (isDisc && d.protected) { showToast(`Protected`, \"error\"); return; } if (isDisc && d.enabled) { requestConfirm(`Delete \"${d.name}\"?`, { confirmLabel: \"Delete\", danger: true }).then((y) => { if (y) doToggle(); }); return; } doToggle(); }\n\treturn (<div className=\"skills-detail-panel\" style={{ display: \"block\" }}><div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", marginBottom: \"8px\" }}><span style={{ fontFamily: \"var(--font-mono)\", fontSize: \".9rem\", fontWeight: 600, color: \"var(--text-strong)\" }}>{d.display_name || d.name}</span><div style={{ display: \"flex\", gap: \"6px\" }}><button onClick={onToggle} disabled={actionBusy.value} className={isDisc && d.enabled ? \"provider-btn provider-btn-sm provider-btn-danger\" : \"provider-btn provider-btn-sm provider-btn-secondary\"}>{actionBusy.value ? \"...\" : isDisc && d.enabled ? \"Delete\" : d.enabled ? \"Disable\" : \"Enable\"}</button><button onClick={onClose} style={{ background: \"none\", border: \"none\", color: \"var(--muted)\", cursor: \"pointer\" }}>&times;</button></div></div><SkillMetadata detail={d} />{d.description && <p style={{ margin: \"0 0 8px\", fontSize: \".82rem\" }}>{d.description}</p>}{d.body_html && <div style={{ marginTop: \"10px\", border: \"1px solid var(--border)\", borderRadius: \"var(--radius-sm)\", background: \"var(--surface2)\" }}><div style={{ padding: \"6px 10px\", borderBottom: \"1px solid var(--border)\", fontSize: \".68rem\", color: \"var(--muted)\", fontFamily: \"var(--font-mono)\", textTransform: \"uppercase\" }}>SKILL.md source</div><div ref={bodyRef} className=\"skill-body-md\" style={{ padding: \"10px\", maxHeight: \"400px\", overflowY: \"auto\", fontSize: \".8rem\", lineHeight: 1.5 }} /></div>}{!d.body_html && d.body && <div style={{ marginTop: \"10px\", border: \"1px solid var(--border)\", borderRadius: \"var(--radius-sm)\", background: \"var(--surface2)\" }}><pre style={{ whiteSpace: \"pre-wrap\", wordBreak: \"break-word\", fontSize: \".78rem\", fontFamily: \"var(--font-mono)\", margin: 0, padding: \"10px\", maxHeight: \"400px\", overflowY: \"auto\" }}>{d.body}</pre></div>}</div>);\n}\n\nfunction RepoCard({ repo }: { repo: RepoSummary }): VNode {\n\tconst expanded = useSignal(false); const searchQuery = useSignal(\"\"); const searchResults = useSignal<SkillSummary[]>([]); const allSkills = useSignal<SkillSummary[]>([]); const searching = useSignal(false); const activeDetail = useSignal<SkillDetail | null>(null); const detailLoading = useSignal(false); const searchTimer = useRef<ReturnType<typeof setTimeout>|null>(null); const removingRepo = useSignal(false); const exportingRepo = useSignal(false);\n\tconst isOrphan = repo.orphaned === true; const sourceLabel = isOrphan ? repo.repo_name : repo.source; const href = isOrphan ? null : /^https?:\\/\\//.test(repo.source) ? repo.source : `https://github.com/${repo.source}`;\n\tfunction toggle(): void { const w = !expanded.value; expanded.value = w; if (w && !isOrphan && !allSkills.value.length) { searching.value = true; searchSkills(repo.source, \"\").then((r) => { allSkills.value = r; searching.value = false; }); } }\n\tfunction onSearch(e: Event): void { if (isOrphan) return; const q = (e.target as HTMLInputElement).value; searchQuery.value = q; activeDetail.value = null; if (searchTimer.current) clearTimeout(searchTimer.current); if (!q.trim()) { searchResults.value = []; return; } searching.value = true; searchTimer.current = setTimeout(() => { searchSkills(repo.source, q.trim()).then((r) => { searchResults.value = r; searching.value = false; }); }, 200); }\n\tfunction loadDetail(s: SkillSummary): void { detailLoading.value = true; sendRpc(\"skills.skill.detail\", { source: repo.source, skill: s.name }).then((r) => { detailLoading.value = false; if (r?.ok) activeDetail.value = r.payload as SkillDetail; else showToast(`Failed: ${r?.error || \"unknown\"}`, \"error\"); }); }\n\tconst displayed = searchQuery.value.trim() ? searchResults.value : allSkills.value;\n\treturn (<div className=\"skills-repo-card\"><div className=\"skills-repo-header\" onClick={toggle}><div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\" }}><span style={{ fontSize: \".65rem\", color: \"var(--muted)\", transform: expanded.value ? \"rotate(90deg)\" : \"\" }}>{\"\\u25B6\"}</span>{href ? <a href={href} target=\"_blank\" rel=\"noopener noreferrer\" onClick={(e) => e.stopPropagation()} style={{ fontFamily: \"var(--font-mono)\", fontSize: \".82rem\", fontWeight: 500, color: \"var(--text-strong)\", textDecoration: \"none\" }}>{sourceLabel}</a> : <span style={{ fontFamily: \"var(--font-mono)\", fontSize: \".82rem\", fontWeight: 500, color: \"var(--text-strong)\" }}>{sourceLabel}</span>}<span style={{ fontSize: \".72rem\", color: \"var(--muted)\" }}>{repo.enabled_count}/{repo.skill_count} enabled</span></div><div style={{ display: \"flex\", gap: \"6px\" }}>{!isOrphan && <button className=\"provider-btn provider-btn-sm provider-btn-secondary\" disabled={exportingRepo.value} onClick={(e) => { e.stopPropagation(); exportingRepo.value = true; doExportBundle(repo.source, null).finally(() => { exportingRepo.value = false; }); }}>{exportingRepo.value ? \"Exporting...\" : \"Export\"}</button>}<button className=\"provider-btn provider-btn-sm provider-btn-danger\" disabled={removingRepo.value} onClick={(e) => { e.stopPropagation(); removingRepo.value = true; sendRpc(\"skills.repos.remove\", { source: repo.source }).then((r) => { removingRepo.value = false; if (r?.ok) fetchAll(); else showToast(`Failed: ${r?.error || \"unknown\"}`, \"error\"); }); }}>{removingRepo.value ? \"Removing...\" : \"Remove\"}</button></div></div>{expanded.value && <div className=\"skills-repo-detail\" style={{ display: \"block\" }}><div style={{ marginBottom: \"8px\" }}><input type=\"text\" placeholder={`Search skills in ${repo.source}\\u2026`} value={searchQuery.value} disabled={isOrphan} onInput={onSearch} style={{ width: \"100%\", padding: \"6px 10px\", border: \"1px solid var(--border)\", borderRadius: \"var(--radius-sm)\", background: \"var(--surface)\", color: \"var(--text)\", fontSize: \".8rem\", fontFamily: \"var(--font-mono)\", boxSizing: \"border-box\" }} /></div>{!activeDetail.value && displayed.length > 0 && <div className=\"skills-browse-list\">{displayed.map((sk) => <div key={sk.name} className=\"skills-ac-item\" onClick={() => loadDetail(sk)}><span style={{ fontFamily: \"var(--font-mono)\", fontWeight: 500, color: \"var(--text-strong)\" }}>{sk.display_name || sk.name}</span>{sk.description && <span style={{ color: \"var(--muted)\", fontSize: \".72rem\", marginLeft: \"6px\" }}>{sk.description}</span>}</div>)}</div>}{searching.value && !activeDetail.value && <div style={{ padding: \"8px\", color: \"var(--muted)\", fontSize: \".78rem\" }}>Searching...</div>}{activeDetail.value && <SkillDetailPanel detail={activeDetail.value} repoSource={repo.source} onClose={() => { activeDetail.value = null; }} onReload={() => loadDetail({ name: activeDetail.value!.name } as SkillSummary)} />}</div>}</div>);\n}\n\nfunction ReposSection(): VNode { return (<div className=\"skills-section\"><h3 className=\"skills-section-title\">Installed Repositories</h3><div className=\"skills-section\">{(!repos.value || !repos.value.length) && <div style={{ padding: \"12px\", color: \"var(--muted)\", fontSize: \".82rem\" }}>No repositories installed.</div>}{repos.value.map((r) => <RepoCard key={r.source} repo={r} />)}</div></div>); }\n\nfunction EnabledSkillsTable(): VNode | null {\n\tconst s = enabledSkills.value; const map = skillRepoMap.value; const activeDetail = useSignal<SkillDetail|null>(null); const detailLoading = useSignal(false); const pending = useSignal<string|null>(null);\n\tif (!s?.length) return null;\n\tfunction isDisc(sk: SkillSummary): boolean { return sk.source === \"personal\" || sk.source === \"project\"; }\n\tfunction doDisable(sk: SkillSummary): void { pending.value = sk.name; sendRpc(\"skills.skill.disable\", { source: map[sk.name] || sk.source, skill: sk.name }).then((r) => { pending.value = null; if (r?.ok) { activeDetail.value = null; showToast(isDisc(sk) ? `Deleted ${sk.name}` : `Disabled ${sk.name}`, \"success\"); fetchAll(); } else showToast(`Failed: ${r?.error || \"unknown\"}`, \"error\"); }); }\n\tfunction onDisable(sk: SkillSummary): void { if (pending.value) return; if (isDisc(sk) && sk.protected) { showToast(\"Protected\", \"error\"); return; } if (isDisc(sk)) { requestConfirm(`Delete \"${sk.name}\"?`, { confirmLabel: \"Delete\", danger: true }).then((y) => { if (y) doDisable(sk); }); return; } doDisable(sk); }\n\tfunction loadDetail(sk: SkillSummary): void { if (activeDetail.value?.name === sk.name) { activeDetail.value = null; return; } detailLoading.value = true; sendRpc(\"skills.skill.detail\", { source: map[sk.name] || sk.source, skill: sk.name })