);\n}\n\nfunction ImagesPage(): VNode {\n\tuseEffect(() => {\n\t\tfetchImages();\n\t\tfetchContainers();\n\t\tfetchDiskUsage();\n\t\tfetchSharedHomeConfig();\n\t}, []);\n\n\tconst sbInfo = sandboxInfo.value as SandboxInfoValue | null;\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t{!sandboxRuntimeAvailable() && (\n\t\t\t\t<div className=\"alert-warning-text max-w-form\"><span className=\"alert-label-warn\">Warning: </span>{SANDBOX_DISABLED_HINT}</div>\n\t\t\t)}\n\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Sandboxes</h2>\n\t\t\t\t<button className=\"text-xs text-[var(--muted)] border border-[var(--border)] px-2.5 py-1 rounded-md hover:text-[var(--text)] hover:border-[var(--border-strong)] transition-colors cursor-pointer bg-transparent\"\n\t\t\t\t\tonClick={pruneAll} disabled={pruning.value || !sandboxRuntimeAvailable()}\n\t\t\t\t\ttitle={sandboxRuntimeAvailable() ? \"Prune all\" : SANDBOX_DISABLED_HINT}>\n\t\t\t\t\t{pruning.value ? \"Pruning\\u2026\" : \"Prune all\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<p className=\"text-sm text-[var(--muted)] leading-relaxed max-w-form\" style={{ margin: 0 }}>\n\t\t\t\tContainer images cached by moltis for sandbox execution. You can delete individual images or prune all. Build custom images from a base with apt packages.\n\t\t\t\t{sbInfo?.backend === \"apple-container\" && (\n\t\t\t\t\t<>\n\t\t\t\t\t\t<br /><br />Apple Container provides VM-isolated execution but does not support building images. Docker (or OrbStack) is required alongside Apple Container to build and cache custom images. Sandboxed commands run via Apple Container; image builds use Docker.\n\t\t\t\t\t</>\n\t\t\t\t)}\n\t\t\t</p>\n\n\t\t\t<SandboxBanner />\n\t\t\t<RunningContainersSection />\n\t\t\t<DefaultImageSelector />\n\t\t\t<SharedHomeSection />\n\n\t\t\t{/* Cached images list */}\n\t\t\t<div className=\"max-w-form\">\n\t\t\t\t{loading.value && <div className=\"text-xs text-[var(--muted)]\">Loading&hellip;</div>}\n\t\t\t\t{!loading.value && images.value.length === 0 && <div className=\"text-xs text-[var(--muted)]\" style={{ padding: \"12px 0\" }}>No cached images.</div>}\n\t\t\t\t{images.value.map((img) => <ImageRow key={img.tag} image={img} sandboxAvailable={sandboxRuntimeAvailable()} />)}\n\t\t\t</div>\n\n\t\t\t{/* Build custom image */}\n\t\t\t<div className=\"max-w-form\" style={{ marginTop: \"8px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"12px\" }}>Build custom image</h3>\n\t\t\t\t<div className=\"project-edit-group\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>Image name</div>\n\t\t\t\t\t<input type=\"text\" className=\"provider-key-input\" placeholder=\"my-tools\"\n\t\t\t\t\t\tstyle={{ width: \"100%\" }} value={buildName.value}\n\t\t\t\t\t\tonInput={(e) => { buildName.value = (e.target as HTMLInputElement).value; }} />\n\t\t\t\t</div>\n\t\t\t\t<div className=\"project-edit-group\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>Base image</div>\n\t\t\t\t\t<input type=\"text\" className=\"provider-key-input\" placeholder=\"ubuntu:25.10\"\n\t\t\t\t\t\tstyle={{ width: \"100%\", fontFamily: \"var(--font-mono)\" }} value={buildBase.value}\n\t\t\t\t\t\tonInput={(e) => { buildBase.value = (e.target as HTMLInputElement).value; }} />\n\t\t\t\t</div>\n\t\t\t\t<div className=\"project-edit-group\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>Packages (space or newline separated)</div>\n\t\t\t\t\t<textarea className=\"provider-key-input\"\n\t\t\t\t\t\tplaceholder=\"ffmpeg python3-pip curl\"\n\t\t\t\t\t\tstyle={{ width: \"100%\", minHeight: \"60px\", resize: \"vertical\", fontFamily: \"var(--font-mono)\", fontSize: \".8rem\" }}\n\t\t\t\t\t\tvalue={buildPackages.value}\n\t\t\t\t\t\tonInput={(e) => { buildPackages.value = (e.target as HTMLTextAreaElement).value; }} />\n\t\t\t\t</div>\n\t\t\t\t<button className=\"provider-btn\" onClick={buildImage}\n\t\t\t\t\tdisabled={building.value || !buildName.value.trim() || !buildPackages.value.trim() || !sandboxRuntimeAvailable()}\n\t\t\t\t\ttitle={sandboxRuntimeAvailable() ? \"Build\" : SANDBOX_DISABLED_HINT}>\n\t\t\t\t\t{building.value ? \"Building\\u2026\" : \"Build\"}\n\t\t\t\t</button>\n\t\t\t\t{buildWarning.value && (\n\t\t\t\t\t<div className=\"alert-warning-text\" style={{ marginTop: \"8px\" }}>\n\t\t\t\t\t\t<span className=\"alert-label-warn\">Warning: </span>{buildWarning.value}\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t{buildStatus.value && (\n\t\t\t\t\tbuildStatus.value.startsWith(\"Error\")\n\t\t\t\t\t\t? <div className=\"alert-error-text\" style={{ marginTop: \"8px\" }}><pre>{buildStatus.value}</pre></div>\n\t\t\t\t\t\t: <div className=\"text-xs\" style={{ marginTop: \"8px\", color: \"var(--muted)\" }}>{buildStatus.value}</div>\n\t\t\t\t)}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nlet _imagesContainer: HTMLElement | null = null;\n\nexport function initImages(container: HTMLElement): void {\n\t_imagesContainer = container;\n\tcontainer.style.cssText = \"flex-direction:column;padding:0;overflow:hidden;\";\n\timages.value = [];\n\tcontainers.value = [];\n\tdiskUsage.value = null;\n\tdefaultImage.value = (sandboxInfo.value as SandboxInfoValue | null)?.default_image || \"\";\n\tbuildStatus.value = \"\";\n\tbuildWarning.value = \"\";\n\tcontainerError.value = \"\";\n\tsharedHomeEnabled.value = false;\n\tsharedHomeMode.value = \"off\";\n\tsharedHomePath.value = \"\";\n\tsharedHomeConfiguredPath.value = \"\";\n\tsharedHomeLoading.value = false;\n\tsharedHomeSaving.value = false;\n\tsharedHomeMsg.value = \"\";\n\tsharedHomeErr.value = \"\";\n\trender(<ImagesPage />, container);\n}\n\nexport function teardownImages(): void {\n\tif (_imagesContainer) render(null, _imagesContainer);\n\t_imagesContainer = null;\n}\n","// ── Logs page (Preact toolbar + imperative log area) ─────────\n\nimport { signal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect, useRef } from \"preact/hooks\";\nimport { sendRpc } from \"../helpers\";\nimport { t } from \"../i18n\";\nimport * as S from \"../state\";\nimport { ComboSelect } from \"../ui\";\n\ninterface LogEntry {\n\tts: string;\n\tlevel: string;\n\ttarget: string;\n\tmessage: string;\n\tfields?: Record<string, unknown>;\n}\n\ninterface LogsStatusPayload {\n\tenabled_levels?: Record<string, boolean>;\n}\n\ninterface ComboOption {\n\tvalue: string;\n\tlabel: string;\n}\n\nconst paused = signal(false);\nconst levelFilter = signal(\"\");\nconst targetFilter = signal(\"\");\nconst searchFilter = signal(\"\");\nconst entryCount = signal(0);\nconst debugEnabled = signal(false);\nconst traceEnabled = signal(false);\nconst maxEntries = 2000;\n\nfunction levelColor(level: string): string {\n\tconst l = level.toUpperCase();\n\tif (l === \"ERROR\") return \"var(--error)\";\n\tif (l === \"WARN\") return \"var(--warn)\";\n\tif (l === \"DEBUG\") return \"var(--muted)\";\n\tif (l === \"TRACE\") return \"color-mix(in oklab, var(--muted) 60%, transparent)\";\n\treturn \"var(--text)\";\n}\n\nfunction levelBg(level: string): string {\n\tconst l = level.toUpperCase();\n\tif (l === \"ERROR\") return \"rgba(239,68,68,0.08)\";\n\tif (l === \"WARN\") return \"rgba(245,158,11,0.06)\";\n\treturn \"transparent\";\n}\n\nfunction renderEntry(entry: LogEntry): HTMLDivElement {\n\tconst row = document.createElement(\"div\");\n\trow.className = \"logs-row\";\n\trow.style.background = levelBg(entry.level);\n\tconst ts = document.createElement(\"span\");\n\tts.className = \"logs-ts\";\n\tconst d = new Date(entry.ts);\n\tts.textContent =\n\t\td.toLocaleTimeString([], {\n\t\t\thour: \"2-digit\",\n\t\t\tminute: \"2-digit\",\n\t\t\tsecond: \"2-digit\",\n\t\t}) +\n\t\t\".\" +\n\t\tString(d.getMilliseconds()).padStart(3, \"0\");\n\tconst lvl = document.createElement(\"span\");\n\tlvl.className = \"logs-level\";\n\tlvl.style.color = levelColor(entry.level);\n\tlvl.textContent = entry.level.toUpperCase().substring(0, 5);\n\tconst tgt = document.createElement(\"span\");\n\ttgt.className = \"logs-target\";\n\ttgt.textContent = entry.target;\n\tconst msg = document.createElement(\"span\");\n\tmsg.className = \"logs-msg\";\n\tmsg.textContent = entry.message;\n\tif (entry.fields && Object.keys(entry.fields).length > 0) {\n\t\tmsg.textContent +=\n\t\t\t\" \" +\n\t\t\tObject.keys(entry.fields)\n\t\t\t\t.map((k) => `${k}=${entry.fields![k]}`)\n\t\t\t\t.join(\" \");\n\t}\n\trow.appendChild(ts);\n\trow.appendChild(lvl);\n\trow.appendChild(tgt);\n\trow.appendChild(msg);\n\treturn row;\n}\n\nfunction levelFilterOptions(): ComboOption[] {\n\tconst options: ComboOption[] = [];\n\tif (traceEnabled.value) options.push({ value: \"trace\", label: t(\"logs:levels.trace\") });\n\tif (debugEnabled.value) options.push({ value: \"debug\", label: t(\"logs:levels.debug\") });\n\toptions.push({ value: \"info\", label: t(\"logs:levels.info\") });\n\toptions.push({ value: \"warn\", label: t(\"logs:levels.warn\") });\n\toptions.push({ value: \"error\", label: t(\"logs:levels.error\") });\n\treturn options;\n}\n\nfunction Toolbar(): VNode {\n\tconst targetRef = useRef<HTMLInputElement>(null);\n\tconst searchRef = useRef<HTMLInputElement>(null);\n\tconst filterTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n\n\tfunction debouncedUpdate(setter: (v: string) => void, ref: { current: HTMLInputElement | null }): () => void {\n\t\treturn () => {\n\t\t\tif (filterTimer.current != null) clearTimeout(filterTimer.current);\n\t\t\tfilterTimer.current = setTimeout(() => {\n\t\t\t\tsetter(ref.current?.value || \"\");\n\t\t\t}, 300);\n\t\t};\n\t}\n\n\treturn (\n\t\t<div className=\"logs-toolbar\">\n\t\t\t<div className=\"logs-level-filter\">\n\t\t\t\t<ComboSelect\n\t\t\t\t\toptions={levelFilterOptions()}\n\t\t\t\t\tvalue={levelFilter.value}\n\t\t\t\t\tonChange={(value: string) => {\n\t\t\t\t\t\tlevelFilter.value = value;\n\t\t\t\t\t}}\n\t\t\t\t\tplaceholder={t(\"logs:toolbar.allLevels\")}\n\t\t\t\t\tsearchable={false}\n\t\t\t\t/>\n\t\t\t</div>\n\t\t\t<input\n\t\t\t\tref={targetRef}\n\t\t\t\ttype=\"text\"\n\t\t\t\tplaceholder={t(\"logs:toolbar.filterTarget\")}\n\t\t\t\tclassName=\"logs-input\"\n\t\t\t\tstyle={{ width: \"140px\" }}\n\t\t\t\tonInput={debouncedUpdate((v) => {\n\t\t\t\t\ttargetFilter.value = v;\n\t\t\t\t}, targetRef)}\n\t\t\t/>\n\t\t\t<input\n\t\t\t\tref={searchRef}\n\t\t\t\ttype=\"text\"\n\t\t\t\tplaceholder={t(\"common:actions.search\")}\n\t\t\t\tclassName=\"logs-input\"\n\t\t\t\tstyle={{ width: \"160px\" }}\n\t\t\t\tonInput={debouncedUpdate((v) => {\n\t\t\t\t\tsearchFilter.value = v;\n\t\t\t\t}, searchRef)}\n\t\t\t/>\n\t\t\t<button\n\t\t\t\tclassName=\"logs-btn\"\n\t\t\t\tonClick={() => {\n\t\t\t\t\tpaused.value = !paused.value;\n\t\t\t\t}}\n\t\t\t\tstyle={paused.value ? { borderColor: \"var(--warn)\" } : undefined}\n\t\t\t>\n\t\t\t\t{paused.value ? t(\"logs:toolbar.resume\") : t(\"logs:toolbar.pause\")}\n\t\t\t</button>\n\t\t\t<button\n\t\t\t\tclassName=\"logs-btn\"\n\t\t\t\tonClick={() => {\n\t\t\t\t\tconst area = document.getElementById(\"logsArea\");\n\t\t\t\t\tif (area) area.textContent = \"\";\n\t\t\t\t\tentryCount.value = 0;\n\t\t\t\t}}\n\t\t\t>\n\t\t\t\t{t(\"logs:toolbar.clear\")}\n\t\t\t</button>\n\t\t\t<a\n\t\t\t\thref=\"/api/logs/download\"\n\t\t\t\tclassName=\"logs-btn\"\n\t\t\t\tdownload=\"moltis-logs.jsonl\"\n\t\t\t\tstyle={{ textDecoration: \"none\", textAlign: \"center\" }}\n\t\t\t>\n\t\t\t\t{t(\"logs:toolbar.download\")}\n\t\t\t</a>\n\t\t\t<span className=\"logs-count\">\n\t\t\t\t{entryCount.value} {t(\"logs:toolbar.entries\")}\n\t\t\t</span>\n\t\t</div>\n\t);\n}\n\nfunction LogsPage(): VNode {\n\tconst logAreaRef = useRef<HTMLDivElement>(null);\n\n\tfunction updateEnabledLevels(statusPayload: LogsStatusPayload): void {\n\t\tconst enabled = statusPayload?.enabled_levels || {};\n\t\ttraceEnabled.value = !!enabled.trace;\n\t\tdebugEnabled.value = !!enabled.debug || traceEnabled.value;\n\t\tif (levelFilter.value === \"trace\" && !traceEnabled.value) levelFilter.value = \"\";\n\t\tif (levelFilter.value === \"debug\" && !debugEnabled.value) levelFilter.value = \"\";\n\t}\n\n\tfunction appendEntry(entry: LogEntry): void {\n\t\tconst area = logAreaRef.current;\n\t\tif (!area) return;\n\t\tconst row = renderEntry(entry);\n\t\tarea.appendChild(row);\n\t\tentryCount.value++;\n\t\twhile (area.childNodes.length > maxEntries) {\n\t\t\tarea.removeChild(area.firstChild!);\n\t\t\tentryCount.value--;\n\t\t}\n\t\tif (!paused.value) {\n\t\t\tconst atBottom = area.scrollHeight - area.scrollTop - area.clientHeight < 60;\n\t\t\tif (atBottom) area.scrollTop = area.scrollHeight;\n\t\t}\n\t}\n\n\tfunction matchesFilter(entry: LogEntry): boolean {\n\t\tif (levelFilter.value) {\n\t\t\tconst levels = [\"trace\", \"debug\", \"info\", \"warn\", \"error\"];\n\t\t\tif (levels.indexOf(entry.level.toLowerCase()) < levels.indexOf(levelFilter.value)) return false;\n\t\t}\n\t\tconst tgtVal = targetFilter.value.trim();\n\t\tif (tgtVal && entry.target.indexOf(tgtVal) === -1) return false;\n\t\tconst searchVal = searchFilter.value.trim().toLowerCase();\n\t\tif (\n\t\t\tsearchVal &&\n\t\t\tentry.message.toLowerCase().indexOf(searchVal) === -1 &&\n\t\t\tentry.target.toLowerCase().indexOf(searchVal) === -1\n\t\t)\n\t\t\treturn false;\n\t\treturn true;\n\t}\n\n\tfunction refetch(): void {\n\t\tconst area = logAreaRef.current;\n\t\tif (area) area.textContent = \"\";\n\t\tentryCount.value = 0;\n\t\tsendRpc(\"logs.list\", {\n\t\t\tlevel: levelFilter.value || undefined,\n\t\t\ttarget: targetFilter.value.trim() || undefined,\n\t\t\tsearch: searchFilter.value.trim() || undefined,\n\t\t\tlimit: 500,\n\t\t}).then((res) => {\n\t\t\tif (!res?.ok) return;\n\t\t\tconst entries: LogEntry[] = (res.payload as { entries?: LogEntry[] })?.entries || [];\n\t\t\tlet i = 0;\n\t\t\tconst batchSize = 100;\n\t\t\tfunction renderBatch(): void {\n\t\t\t\tconst end = Math.min(i + batchSize, entries.length);\n\t\t\t\twhile (i < end) appendEntry(entries[i++]);\n\t\t\t\tif (i < entries.length) requestAnimationFrame(renderBatch);\n\t\t\t\telse if (logAreaRef.current) logAreaRef.current.scrollTop = logAreaRef.current.scrollHeight;\n\t\t\t}\n\t\t\trenderBatch();\n\t\t});\n\t}\n\n\tuseEffect(() => {\n\t\tsendRpc(\"logs.status\", {})\n\t\t\t.then((res) => {\n\t\t\t\tif (!res?.ok) return;\n\t\t\t\tupdateEnabledLevels((res.payload as LogsStatusPayload) || {});\n\t\t\t})\n\t\t\t.catch(() => undefined);\n\t\trefetch();\n\t\tS.setLogsEventHandler(((entry: unknown) => {\n\t\t\tif (paused.value) return;\n\t\t\tconst e = entry as LogEntry;\n\t\t\tif (!matchesFilter(e)) return;\n\t\t\tappendEntry(e);\n\t\t}) as unknown as () => void);\n\t\treturn () => S.setLogsEventHandler(null);\n\t}, []);\n\n\t// Re-fetch when filters change\n\tuseEffect(() => {\n\t\trefetch();\n\t}, [levelFilter.value, targetFilter.value, searchFilter.value]);\n\n\treturn (\n\t\t<>\n\t\t\t<Toolbar />\n\t\t\t<div ref={logAreaRef} id=\"logsArea\" className=\"logs-area\" />\n\t\t</>\n\t);\n}\n\nlet _logsContainer: HTMLElement | null = null;\n\nexport function initLogs(container: HTMLElement): void {\n\t_logsContainer = container;\n\tcontainer.style.cssText = \"flex-direction:column;padding:0;overflow:hidden;\";\n\tpaused.value = false;\n\tlevelFilter.value = \"\";\n\ttargetFilter.value = \"\";\n\tsearchFilter.value = \"\";\n\tentryCount.value = 0;\n\tdebugEnabled.value = false;\n\ttraceEnabled.value = false;\n\trender(<LogsPage />, container);\n}\n\nexport function teardownLogs(): void {\n\tS.setLogsEventHandler(null);\n\tif (_logsContainer) render(null, _logsContainer);\n\t_logsContainer = null;\n}\n","// ── MCP page ────────────────────────────────────────────────\n\nimport { signal, useSignal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect } from \"preact/hooks\";\nimport { onEvent } from \"../events\";\nimport { sendRpc } from \"../helpers\";\nimport { updateNavCount } from \"../nav-counts\";\nimport { ConfirmDialog, requestConfirm } from \"../ui\";\n\n// ── Types ────────────────────────────────────────────────────\n\ninterface McpServer {\n\tname: string;\n\tdisplay_name?: string;\n\tstate?: string;\n\tenabled?: boolean;\n\ttransport?: string;\n\tcommand?: string;\n\targs?: string[];\n\tenv?: Record<string, string>;\n\turl?: string;\n\theaders?: Record<string, string>;\n\theader_names?: string[];\n\theaderNames?: string[];\n\theader_count?: number;\n\theaderCount?: number;\n\ttool_count?: number;\n\tauth_state?: string;\n\trequest_timeout_secs?: number | null;\n\tconfigured_request_timeout_secs?: number;\n}\n\ninterface McpTool { name: string; description?: string; }\ninterface ToastItem { id: number; message: string; type: string; }\ninterface FeaturedServer { name: string; repo?: string; desc: string; command?: string; args?: string[]; transport?: string; url?: string; requiresConfig?: boolean; envKeys?: string[]; hint?: string; }\n\n// ── Signals ─────────────────────────────────────────────────\n\nconst servers = signal<McpServer[]>([]);\nconst loading = signal(false);\nconst configLoading = signal(false);\nconst configSaving = signal(false);\nconst requestTimeoutSecs = signal(\"30\");\nconst configDirty = signal(false);\nconst toasts = signal<ToastItem[]>([]);\nlet toastId = 0;\n\nfunction showToast(message: string, type: string): void { const id = ++toastId; toasts.value = [...toasts.value, { id, message, type }]; setTimeout(() => { toasts.value = toasts.value.filter((t) => t.id !== id); }, 4000); }\n\nasync function refreshServers(): Promise<void> {\n\tloading.value = true;\n\ttry { const res = await fetch(\"/api/mcp\"); if (res.ok) servers.value = (await res.json()) || []; }\n\tcatch { const rpc = await sendRpc(\"mcp.list\", {}); if (rpc.ok) servers.value = (rpc.payload as McpServer[]) || []; }\n\tloading.value = false;\n\tupdateNavCount(\"mcp\", servers.value.filter((s) => s.state === \"running\").length);\n}\n\nasync function refreshConfig(): Promise<void> {\n\tconfigLoading.value = true;\n\ttry { const res = await sendRpc(\"mcp.config.get\", {}); if (res?.ok && res.payload) { requestTimeoutSecs.value = String((res.payload as Record<string, number>).request_timeout_secs || 30); configDirty.value = false; } }\n\tfinally { configLoading.value = false; }\n}\n\nfunction normalizeOptionalTimeout(rawValue: string): { ok: boolean; value: number | null; message?: string } {\n\tconst trimmed = String(rawValue || \"\").trim();\n\tif (!trimmed) return { ok: true, value: null };\n\tif (!/^\\d+$/.test(trimmed)) return { ok: false, value: null, message: \"Timeout must be a positive number\" };\n\tconst parsed = Number.parseInt(trimmed, 10);\n\tif (!Number.isFinite(parsed) || parsed <= 0) return { ok: false, value: null, message: \"Timeout must be a positive number\" };\n\treturn { ok: true, value: parsed };\n}\n\nfunction resolveTimeoutOrAbort(rawValue: string, setBusy: (v: boolean) => void): { ok: boolean; value?: number | null } {\n\tconst t = normalizeOptionalTimeout(rawValue);\n\tif (!t.ok) { showToast(t.message || \"Invalid timeout\", \"error\"); setBusy(false); return { ok: false }; }\n\treturn { ok: true, value: t.value };\n}\n\nasync function saveConfig(): Promise<void> {\n\tconst t = normalizeOptionalTimeout(requestTimeoutSecs.value);\n\tif (!t.ok || t.value === null) { showToast(\"MCP request timeout must be a positive number\", \"error\"); return; }\n\tconfigSaving.value = true;\n\ttry {\n\t\tconst res = await sendRpc(\"mcp.config.update\", { request_timeout_secs: t.value });\n\t\tif (res?.ok) { requestTimeoutSecs.value = String((res.payload as Record<string, number>)?.request_timeout_secs || t.value); configDirty.value = false; showToast(\"Saved MCP settings. Restart servers to apply.\", \"success\"); }\n\t\telse showToast(`Failed: ${res?.error?.message || \"unknown\"}`, \"error\");\n\t} finally { configSaving.value = false; }\n}\n\nfunction oauthCallbackUrl(): string { return `${window.location.origin}/auth/callback`; }\n\nasync function addServer(payload: Record<string, unknown>): Promise<void> {\n\tconst req = { ...payload };\n\tconst t = (payload.transport as string) || \"stdio\";\n\tif (t === \"sse\" || t === \"streamable-http\") (req as Record<string, string>).redirectUri = oauthCallbackUrl();\n\tconst res = await sendRpc(\"mcp.add\", req);\n\tif (res?.ok) {\n\t\tconst p = res.payload as Record<string, unknown>;\n\t\tshowToast(`Added MCP tool \"${p?.name || payload.name}\"`, \"success\");\n\t\tif (p?.oauthPending && p?.authUrl) window.open(p.authUrl as string, \"_blank\", \"noopener,noreferrer\");\n\t} else showToast(`Failed to add \"${payload.name}\": ${res?.error?.message || \"unknown\"}`, \"error\");\n\tawait refreshServers();\n}\n\nfunction parseEnvLines(text: string): Record<string, string> {\n\tconst env: Record<string, string> = {};\n\tif (!text) return env;\n\tfor (const line of text.split(\"\\n\")) { const trimmed = line.trim(); if (!trimmed || trimmed.startsWith(\"#\")) continue; const idx = trimmed.indexOf(\"=\"); if (idx > 0) env[trimmed.slice(0, idx).trim()] = trimmed.slice(idx + 1).trim(); }\n\treturn env;\n}\n\nfunction transportLabel(transport: string | undefined): string { if (transport === \"streamable-http\") return \"streamable-http remote\"; return transport === \"sse\" ? \"sse remote\" : \"stdio local\"; }\nfunction deriveNameFromCommand(cmdLine: string): string { const parts = cmdLine.trim().split(/\\s+/).filter(Boolean); for (let i = parts.length - 1; i >= 0; i--) { const tk = parts[i]; if (tk.startsWith(\"-\")) continue; let base = tk.includes(\"/\") ? tk.split(\"/\").pop()! : tk; base = base.replace(/^mcp-server-/, \"\").replace(/^server-/, \"\").replace(/^mcp-/, \"\"); if (base) return base.toLowerCase().replace(/[^a-z0-9-]/g, \"-\"); } return parts[0] || \"\"; }\nfunction deriveSseName(url: string): string { if (!url) return \"\"; try { const parts = new URL(url.trim()).hostname.split(\".\").filter((p) => p !== \"mcp\" && p !== \"www\"); return parts.length > 0 ? parts[0].toLowerCase() : \"\"; } catch { return \"\"; } }\nfunction remoteHeaderNames(server: McpServer): string[] { return (server.header_names || server.headerNames || (server.headers ? Object.keys(server.headers) : [])).filter((n) => typeof n === \"string\" && n.trim()).map((n) => n.trim()); }\nfunction remoteHeaderCount(server: McpServer): number { const ec = server.header_count ?? server.headerCount; if (ec != null && Number.isFinite(ec) && ec >= 0) return ec; return remoteHeaderNames(server).length; }\nfunction remoteHeaderSummary(server: McpServer): string { const names = remoteHeaderNames(server); const count = remoteHeaderCount(server); if (!count && !names.length) return \"none configured\"; if (!names.length) return `${count} configured`; return `${names.join(\", \")} (${count} total)`; }\n\n// ── Featured MCP servers ────────────────────────────────────\n\nconst featuredServers: FeaturedServer[] = [\n\t{ name: \"filesystem\", repo: \"modelcontextprotocol/servers\", desc: \"Secure file operations\", command: \"npx\", args: [\"-y\", \"@modelcontextprotocol/server-filesystem\", \"/tmp\"], requiresConfig: true, hint: \"Last arg is the allowed directory path\" },\n\t{ name: \"memory\", repo: \"modelcontextprotocol/servers\", desc: \"Knowledge graph-based persistent memory\", command: \"npx\", args: [\"-y\", \"@modelcontextprotocol/server-memory\"] },\n\t{ name: \"github\", repo: \"modelcontextprotocol/servers\", desc: \"GitHub API integration\", command: \"npx\", args: [\"-y\", \"@modelcontextprotocol/server-github\"], requiresConfig: true, envKeys: [\"GITHUB_PERSONAL_ACCESS_TOKEN\"], hint: \"Requires a GitHub personal access token\" },\n\t{ name: \"linear\", repo: \"linear/linear\", desc: \"Remote Linear MCP server with browser OAuth\", transport: \"sse\", url: \"https://mcp.linear.app/mcp\", hint: \"After adding, click Enable and complete OAuth\" },\n];\n\n// ── Components ──────────────────────────────────────────────\n\nfunction Toasts(): VNode {\n\treturn (<div className=\"skills-toast-container\">{toasts.value.map((t) => {\n\t\tconst cls = t.type === \"error\" ? \"bg-[var(--error)]\" : \"bg-[var(--accent)]\";\n\t\treturn <div key={t.id} className={`pointer-events-auto max-w-[420px] px-4 py-2.5 rounded-md text-xs font-medium text-white shadow-lg ${cls}`}>{t.message}</div>;\n\t})}</div>);\n}\n\nfunction StatusBadge({ state }: { state?: string }): VNode {\n\tconst colors: Record<string, string> = { running: \"bg-[var(--ok)]\", stopped: \"bg-[var(--muted)]\", dead: \"bg-[var(--error)]\", connecting: \"bg-[var(--warn)]\" };\n\treturn <span className={`inline-block w-2 h-2 rounded-full ${colors[state || \"stopped\"] || colors.stopped}`} />;\n}\n\nfunction FeaturedCard({ server: f }: { server: FeaturedServer }): VNode {\n\tconst installing = useSignal(false);\n\tconst configuring = useSignal(false);\n\tconst argsVal = useSignal((f.args || []).join(\" \"));\n\tconst envVal = useSignal((f.envKeys || []).map((k) => `${k}=`).join(\"\\n\"));\n\tconst urlVal = useSignal(f.url || \"\");\n\tconst headerVal = useSignal(\"\");\n\tconst timeoutVal = useSignal(\"\");\n\tconst needsConfig = Boolean(f.requiresConfig || f.envKeys?.length || f.transport === \"sse\" || f.transport === \"streamable-http\");\n\tconst isSse = f.transport === \"sse\" || f.transport === \"streamable-http\";\n\n\tfunction onAdd(): void {\n\t\tif (needsConfig && !configuring.value) { configuring.value = true; return; }\n\t\tinstalling.value = true;\n\t\tconst tr = resolveTimeoutOrAbort(timeoutVal.value, (v) => { installing.value = v; });\n\t\tif (!tr.ok) return;\n\t\tif (isSse) { const url = (urlVal.value || \"\").trim(); if (!url) { showToast(\"URL required\", \"error\"); installing.value = false; return; } addServer({ headers: parseEnvLines(headerVal.value), name: f.name, command: \"\", args: [], transport: \"sse\", url, request_timeout_secs: tr.value }).finally(() => { installing.value = false; configuring.value = false; }); return; }\n\t\taddServer({ name: f.name, command: f.command, args: argsVal.value.split(/\\s+/).filter(Boolean), env: parseEnvLines(envVal.value), request_timeout_secs: tr.value }).finally(() => { installing.value = false; configuring.value = false; });\n\t}\n\n\treturn (\n\t\t<div className=\"mb-1\">\n\t\t\t<div className=\"provider-item\">\n\t\t\t\t<div className=\"flex-1 min-w-0\">\n\t\t\t\t\t<div className=\"provider-item-name font-mono text-sm\">{f.name}</div>\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mt-0.5 flex gap-3 items-center\">\n\t\t\t\t\t\t<span>{f.desc}</span>\n\t\t\t\t\t\t<span className=\"text-[0.6rem] px-1.5 py-px rounded-full bg-[var(--surface2)] text-[var(--muted)] font-medium\">{transportLabel(f.transport)}</span>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t<button onClick={onAdd} disabled={installing.value} className=\"shrink-0 whitespace-nowrap provider-btn provider-btn-sm\">\n\t\t\t\t\t{installing.value ? \"Adding\\u2026\" : configuring.value ? \"Confirm\" : needsConfig ? \"Configure\" : \"Add\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t{configuring.value && (\n\t\t\t\t<div className=\"px-3 pb-3 border border-t-0 border-[var(--border)] rounded-b-[var(--radius-sm)]\">\n\t\t\t\t\t{isSse ? (<>\n\t\t\t\t\t\t<div className=\"project-edit-group\"><div className=\"text-xs text-[var(--muted)] mb-1\">Server URL</div><input type=\"text\" value={urlVal.value} onInput={(e) => { urlVal.value = (e.target as HTMLInputElement).value; }} className=\"provider-key-input w-full font-mono\" /></div>\n\t\t\t\t\t\t<div className=\"project-edit-group\"><div className=\"text-xs text-[var(--muted)] mb-1\">Headers (KEY=VALUE per line)</div><textarea value={headerVal.value} onInput={(e) => { headerVal.value = (e.target as HTMLTextAreaElement).value; }} rows={3} className=\"provider-key-input w-full resize-y font-mono text-sm\" /></div>\n\t\t\t\t\t</>) : (<>\n\t\t\t\t\t\t<div className=\"project-edit-group\"><div className=\"text-xs text-[var(--muted)] mb-1\">Arguments</div><input type=\"text\" value={argsVal.value} onInput={(e) => { argsVal.value = (e.target as HTMLInputElement).value; }} className=\"provider-key-input w-full\" /></div>\n\t\t\t\t\t\t{f.envKeys?.length ? <div className=\"project-edit-group\"><div className=\"text-xs text-[var(--muted)] mb-1\">Env vars (KEY=VALUE per line)</div><textarea value={envVal.value} onInput={(e) => { envVal.value = (e.target as HTMLTextAreaElement).value; }} rows={f.envKeys.length} className=\"provider-key-input w-full resize-y\" /></div> : null}\n\t\t\t\t\t</>)}\n\t\t\t\t\t<button onClick={() => { configuring.value = false; }} className=\"self-start provider-btn provider-btn-secondary provider-btn-sm\">Cancel</button>\n\t\t\t\t</div>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\nfunction FeaturedSection(): VNode {\n\treturn (\n\t\t<div>\n\t\t\t<div className=\"flex items-center justify-between mb-2\">\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\">Popular MCP Servers</h3>\n\t\t\t\t<a href=\"https://github.com/modelcontextprotocol/servers\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"text-xs text-[var(--accent)] hover:underline\">Browse all on GitHub &rarr;</a>\n\t\t\t</div>\n\t\t\t<div>{featuredServers.map((f) => <FeaturedCard key={f.name} server={f} />)}</div>\n\t\t</div>\n\t);\n}\n\nfunction InstallBox(): VNode {\n\tconst cmdLine = useSignal(\"\"); const envVal = useSignal(\"\"); const adding = useSignal(false); const showEnv = useSignal(false);\n\tconst transportType = useSignal(\"stdio\"); const sseUrl = useSignal(\"\"); const sseHeaders = useSignal(\"\"); const timeoutVal = useSignal(\"\"); cons