rn `${w.index}: ${title}`; }\n\nfunction renderWindowTabs(): void {\n\tif (!tabsEl) return;\n\twhile (tabsEl.firstChild) tabsEl.removeChild(tabsEl.firstChild);\n\tif (!tmuxPersistenceEnabled) {\n\t\tconst s = document.createElement(\"span\"); s.className = \"terminal-tab-empty\"; s.textContent = \"tmux unavailable\"; tabsEl.appendChild(s); return;\n\t}\n\tif (!terminalWindows.length) {\n\t\tconst s = document.createElement(\"span\"); s.className = \"terminal-tab-empty\"; s.textContent = \"No tmux windows\"; tabsEl.appendChild(s); return;\n\t}\n\tfor (const w of terminalWindows) {\n\t\tconst tab = document.createElement(\"button\"); tab.type = \"button\"; tab.className = \"terminal-tab\";\n\t\tif (w.id === activeWindowId) tab.classList.add(\"active\");\n\t\ttab.title = `Attach ${windowLabel(w)}`; tab.textContent = windowLabel(w);\n\t\ttab.addEventListener(\"click\", () => onWindowTabClick(w.id));\n\t\ttabsEl.appendChild(tab);\n\t}\n}\n\nfunction chooseActiveWindow(windows: WindowInfo[], preferred: string | null, payloadActive: string | null): string | null {\n\tif (!windows.length) return null;\n\tfor (const c of [preferred, payloadActive, activeWindowId]) { if (c && windows.some((w) => w.id === c)) return c; }\n\tconst active = windows.find((w) => w.active);\n\treturn active ? active.id : windows[0].id;\n}\n\nfunction applyWindowsState(payload: WindowsPayload, preferred: string | null): void {\n\tconst next: WindowInfo[] = [];\n\tfor (const raw of Array.isArray(payload?.windows) ? payload.windows : []) { const p = normalizeWindowPayload(raw); if (p) next.push(p); }\n\tnext.sort((a, b) => a.index - b.index);\n\tterminalWindows = next;\n\tconst pa = typeof payload?.activeWindowId === \"string\" && payload.activeWindowId.trim() ? payload.activeWindowId.trim() : null;\n\tactiveWindowId = chooseActiveWindow(next, preferred, pa);\n\trenderWindowTabs();\n}\n\nasync function fetchTerminalWindows(): Promise<WindowsPayload> {\n\tconst r = await fetch(\"/api/terminal/windows\", { method: \"GET\", headers: { Accept: \"application/json\" } });\n\tlet p: WindowsPayload; try { p = await r.json(); } catch { p = {}; }\n\tif (!r.ok) throw new Error(localizedApiErrorMessage(p as never, \"Failed to list tmux windows\"));\n\treturn p;\n}\n\nasync function refreshTerminalWindows(opts?: { preferredWindowId?: string | null; silent?: boolean }): Promise<void> {\n\tconst preferred = opts?.preferredWindowId || pendingWindowId || null;\n\ttry {\n\t\tconst p = await fetchTerminalWindows();\n\t\ttmuxPersistenceEnabled = p?.available === true;\n\t\tapplyWindowsState(p, preferred);\n\t\tif (pendingWindowId && activeWindowId === pendingWindowId) pendingWindowId = null;\n\t\tsetWindowControlsEnabled();\n\t\tif (!tmuxPersistenceEnabled) clearWindowsRefreshTimer();\n\t} catch (e) { if (!opts?.silent) setStatus((e as Error)?.message || \"Failed to refresh terminal windows\", \"error\"); }\n}\n\nfunction startWindowsRefreshLoop(): void {\n\tclearWindowsRefreshTimer();\n\tif (!tmuxPersistenceEnabled) return;\n\twindowsRefreshTimer = setInterval(() => { void refreshTerminalWindows({ silent: true }); }, WINDOW_REFRESH_MS);\n}\n\nfunction sendSocketMessage(payload: SocketMessage): boolean {\n\tif (!(socket && socket.readyState === WebSocket.OPEN)) return false;\n\ttry { socket.send(JSON.stringify(payload)); return true; } catch { return false; }\n}\n\nfunction sendResizeIfChanged(force?: boolean): void {\n\tif (!xterm || !terminalAvailable) return;\n\tconst cols = xterm.cols || 0, rows = xterm.rows || 0;\n\tif (!(cols > 0 && rows > 0)) return;\n\tupdateSizeIndicator(cols, rows);\n\tif (!force && cols === lastSentCols && rows === lastSentRows) return;\n\tlastSentCols = cols; lastSentRows = rows;\n\tsendSocketMessage({ type: \"resize\", cols, rows });\n}\n\nfunction scheduleFit(forceResize?: boolean): void {\n\tif (!fitAddon) return;\n\tconst fr = forceResize === true;\n\tclearScheduledFit();\n\tfitRaf = requestAnimationFrame(() => {\n\t\tfitRaf = 0; if (!fitAddon) return;\n\t\ttry { fitAddon.fit(); sendResizeIfChanged(fr); } catch { /* transient layout */ }\n\t});\n}\n\nfunction kickResizeSettleLoop(): void {\n\tif (!xterm) return;\n\tclearResizeSettleTimers();\n\tfor (const d of [0, 50, 160, 380, 800]) {\n\t\tresizeSettleTimers.push(setTimeout(() => { if (xterm) { scheduleFit(true); sendResizeIfChanged(true); } }, d));\n\t}\n}\n\nfunction requestWindowSwitch(windowId: string): boolean {\n\tif (!tmuxPersistenceEnabled || !windowId) return false;\n\tpendingWindowId = windowId; activeWindowId = windowId;\n\trenderWindowTabs(); setStatus(\"Switching tmux window...\", \"ok\");\n\treturn socket?.readyState === WebSocket.OPEN && sendSocketMessage({ type: \"switch_window\", window: windowId }) || false;\n}\n\nfunction handleActiveWindowEvent(payload: TerminalMessage): void {\n\tconst wid = typeof payload?.windowId === \"string\" ? payload.windowId.trim() : \"\";\n\tif (!wid) return;\n\tactiveWindowId = wid; pendingWindowId = null;\n\trenderWindowTabs(); setStatus(\"Switched tmux window.\", \"ok\");\n\tstartWindowsRefreshLoop(); kickResizeSettleLoop();\n\tif (xterm) xterm.focus();\n\tvoid refreshTerminalWindows({ preferredWindowId: wid, silent: true });\n}\n\nfunction onWindowTabClick(windowId: string): void {\n\tif (!tmuxPersistenceEnabled || !windowId || windowId === activeWindowId) return;\n\tif (requestWindowSwitch(windowId)) return;\n\tterminalAvailable = false; setControlsEnabled(false);\n\tif (xterm) xterm.reset();\n\tconnectTerminalSocket();\n}\n\nasync function createTerminalWindow(): Promise<void> {\n\tif (!(tmuxPersistenceEnabled && terminalAvailable) || creatingWindow) return;\n\tcreatingWindow = true; setWindowControlsEnabled(); setStatus(\"Creating tmux window...\", \"ok\");\n\ttry {\n\t\tconst r = await fetch(\"/api/terminal/windows\", { method: \"POST\", headers: { Accept: \"application/json\", \"Content-Type\": \"application/json\" }, body: JSON.stringify({}) });\n\t\tlet p: WindowsPayload; try { p = await r.json(); } catch { p = {}; }\n\t\tif (!r.ok) throw new Error(localizedApiErrorMessage(p as never, \"Failed to create tmux window\"));\n\t\tconst cid = p?.window?.id || p?.windowId || null;\n\t\tif (Array.isArray(p?.windows)) { tmuxPersistenceEnabled = true; applyWindowsState(p, cid); }\n\t\telse await refreshTerminalWindows({ preferredWindowId: cid, silent: true });\n\t\tif (cid && activeWindowId !== cid) { if (!requestWindowSwitch(cid)) { if (xterm) xterm.reset(); connectTerminalSocket(); } }\n\t\telse { if (xterm) xterm.reset(); connectTerminalSocket(); }\n\t\tsetStatus(\"Created tmux window.\", \"ok\");\n\t} catch (e) { setStatus((e as Error)?.message || \"Failed to create tmux window\", \"error\"); }\n\tfinally { creatingWindow = false; setWindowControlsEnabled(); }\n}\n\nfunction updateSizeIndicator(cols: number, rows: number): void {\n\tif (!sizeEl) return;\n\tsizeEl.textContent = cols > 0 && rows > 0 ? `${cols}\\u00d7${rows}` : \"\\u2014\\u00d7\\u2014\";\n}\n\nfunction getCssVar(name: string, fallback: string): string {\n\tif (typeof document === \"undefined\") return fallback;\n\treturn getComputedStyle(document.documentElement).getPropertyValue(name).trim() || fallback;\n}\n\nfunction buildXtermTheme(): Record<string, string> {\n\treturn {\n\t\tbackground: getCssVar(\"--bg\", \"#0f1115\"), foreground: getCssVar(\"--text\", \"#e4e4e7\"),\n\t\tcursor: getCssVar(\"--accent\", \"#4ade80\"), cursorAccent: getCssVar(\"--bg\", \"#0f1115\"),\n\t\tselectionBackground: getCssVar(\"--accent-subtle\", \"#4ade801f\"),\n\t};\n}\n\nfunction applyTheme(): void { if (xterm) xterm.options.theme = buildXtermTheme(); }\n\nfunction registerOscStabilityGuards(): void {\n\tif (!(xterm?.parser && typeof xterm.parser.registerOscHandler === \"function\")) return;\n\tconst swallow = () => true;\n\tfor (const code of [4, 10, 11, 12, 104, 110, 111, 112]) {\n\t\tconst d = xterm.parser.registerOscHandler(code, swallow);\n\t\tif (d && typeof d.dispose === \"function\") oscHandlerDisposables.push(d);\n\t}\n}\n\nfunction clearOscStabilityGuards(): void {\n\tfor (const d of oscHandlerDisposables) { try { d.dispose(); } catch { /* ignore */ } }\n\toscHandlerDisposables = [];\n}\n\nasync function ensureXtermModules(): Promise<void> {\n\tif (TerminalCtorRef && FitAddonCtorRef) return;\n\tconst [xtermMod, fitAddonMod] = await Promise.all([import(\"@xterm/xterm\"), import(\"@xterm/addon-fit\")]);\n\tTerminalCtorRef = (xtermMod as Record<string, unknown>).Terminal as TerminalCtorType;\n\tFitAddonCtorRef = (fitAddonMod as Record<string, unknown>).FitAddon as FitAddonCtorType;\n}\n\nfunction queueInput(data: string): void {\n\tif (!terminalAvailable || typeof data !== \"string\" || !data.length) return;\n\tpendingInput += data;\n\tif (!inputFlushTimer) inputFlushTimer = setTimeout(() => { inputFlushTimer = null; flushInputQueue(); }, INPUT_FLUSH_MS);\n}\n\nfunction flushInputQueue(): void {\n\tif (!(terminalAvailable && pendingInput)) return;\n\twhile (pendingInput.length > 0) {\n\t\tconst chunk = pendingInput.slice(0, MAX_INPUT_CHUNK);\n\t\tif (!sendSocketMessage({ type: \"input\", data: chunk })) break;\n\t\tpendingInput = pendingInput.slice(MAX_INPUT_CHUNK);\n\t}\n\tif (pendingInput.length > 0 && !inputFlushTimer) inputFlushTimer = setTimeout(() => { inputFlushTimer = null; flushInputQueue(); }, INPUT_FLUSH_MS);\n}\n\nasync function initXterm(): Promise<void> {\n\tif (!terminalEl) return;\n\tawait ensureXtermModules();\n\tif (!(TerminalCtorRef && FitAddonCtorRef)) throw new Error(\"xterm failed to load\");\n\txterm = new TerminalCtorRef({ convertEol: false, disableStdin: false, cursorBlink: true, scrollback: 4000, fontFamily: \"JetBrains Mono, ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace\", fontSize: 12, lineHeight: 1.35, theme: buildXtermTheme() });\n\tregisterOscStabilityGuards();\n\tfitAddon = new FitAddonCtorRef();\n\txterm.loadAddon(fitAddon);\n\txterm.open(terminalEl);\n\txtermDataDisposable = xterm.onData((d: string) => queueInput(d));\n\txtermResizeDisposable = xterm.onResize((sz: { cols: number; rows: number }) => { updateSizeIndicator(sz.cols, sz.rows); sendResizeIfChanged(); });\n\tscheduleFit();\n\tterminalEl.addEventListener(\"click\", () => { if (xterm) xterm.focus(); });\n\tif (typeof ResizeObserver !== \"undefined\") { resizeObserver = new ResizeObserver(() => scheduleFit()); resizeObserver.observe(terminalEl.parentElement || terminalEl); }\n\tif (typeof window !== \"undefined\") { windowResizeListener = () => scheduleFit(); window.addEventListener(\"resize\", windowResizeListener); }\n\tif (typeof document !== \"undefined\" && document.fonts?.ready && typeof document.fonts.ready.then === \"function\") document.fonts.ready.then(() => scheduleFit());\n\tif (typeof document !== \"undefined\" && document.fonts?.addEventListener) { fontsReadyListener = () => scheduleFit(); document.fonts.addEventListener(\"loadingdone\", fontsReadyListener); }\n\tthemeObserver = new MutationObserver(() => applyTheme());\n\tthemeObserver.observe(document.documentElement, { attributes: true, attributeFilter: [\"data-theme\"] });\n}\n\nfunction disposeXterm(): void {\n\tclearObservers(); clearScheduledFit(); clearResizeSettleTimers(); clearOscStabilityGuards();\n\tif (xtermDataDisposable) { xtermDataDisposable.dispose(); xtermDataDisposable = null; }\n\tif (xtermResizeDisposable) { xtermResizeDisposable.dispose(); xtermResizeDisposable = null; }\n\tif (xterm) { xterm.dispose(); xterm = null; }\n\tfitAddon = null; lastSentCols = 0; lastSentRows = 0; updateSizeIndicator(0, 0);\n}\n\nfunction isNearBottom(): boolean {\n\tif (!xterm) return false;\n\tconst b = xterm.buffer.active;\n\treturn !b || b.baseY - b.viewportY <= 2;\n}\n\nfunction decodeBase64ToBytes(encoded: string): Uint8Array | null {\n\tif (!encoded) return null;\n\ttry { const bin = atob(encoded); const b = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) b[i] = bin.charCodeAt(i) & 0xff; return b; } catch { return null; }\n}\n\nfunction writeToXterm(chunk: string | Uint8Array, scrollBottom: boolean): void {\n\tif (!xterm) return;\n\tif ((typeof chunk === \"string\" && !chunk.length) || (chunk instanceof Uint8Array && !chunk.length)) { if (scrollBottom) xterm.scrollToBottom(); return; }\n\txterm.write(chunk, () => { if (scrollBottom && xterm) xterm.scrollToBottom(); });\n}\n\nfunction appendOutputChunk(chunk: string | Uint8Array, forceBottom: boolean): void {\n\tif (!xterm) return;\n\twriteToXterm(chunk, forceBottom || isNearBottom());\n}\n\nfunction closeTerminalSocket(): void {\n\tif (!socket) return;\n\tconst ws = socket; socket = null;\n\tws.onopen = null; ws.onmessage = null; ws.onerror = null; ws.onclose = null;\n\tif (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING) ws.close();\n}\n\nfunction scheduleReconnect(): void {\n\tif (shuttingDown || reconnectTimer) return;\n\treconnectTimer = setTimeout(() => { reconnectTimer = null; connectTerminalSocket(); }, RECONNECT_DELAY_MS);\n}\n\nfunction applyReadyPayload(payload: ReadyPayload): void {\n\tterminalAvailable = !!payload.available;\n\tsetControlsEnabled(terminalAvailable);\n\tconst pe = !!payload.persistenceEnabled;\n\ttmuxPersistenceEnabled = pe;\n\tconst pa = !!payload.persistenceAvailable;\n\tconst paid = typeof payload.activeWindowId === \"string\" && payload.activeWindowId.trim() ? payload.activeWindowId.trim() : null;\n\tif (paid) activeWindowId = paid;\n\tpendingWindowId = null;\n\tconst ic = payload.tmuxInstallCommand || \"\";\n\tconst shouldOffer = terminalAvailable && !pe && !pa && ic.length > 0;\n\tconst first = shouldOffer && !tmuxInstallPromptSeen;\n\ttmuxInstallCommand = shouldOffer ? ic : \"\";\n\tif (installCommandEl) installCommandEl.textContent = tmuxInstallCommand;\n\tif (installTmuxBtn) installTmuxBtn.textContent = first ? \"Run install command (first time)\" : \"Run install command\";\n\tsetInstallActionsVisible(shouldOffer);\n\tif (metaEl) metaEl.textContent = terminalAvailable ? (pe ? `Persistent tmux session, user ${payload.user || \"unknown\"}` : `Ephemeral host shell, user ${payload.user || \"unknown\"}`) : \"Host shell unavailable\";\n\tif (hintEl) {\n\t\tif (!terminalAvailable) hintEl.textContent = \"Unable to open host shell.\";\n\t\telse if (pe) hintEl.textContent = \"Interactive host shell with persistent tmux session. Click inside terminal and type commands directly.\";\n\t\telse if (pa) hintEl.textContent = \"Interactive host shell (ephemeral). Enable tmux persistence from terminal settings when available.\";\n\t\telse if (ic) hintEl.textContent = first ? \"First connection tip: run the install command once to enable persistent tmux sessions.\" : `Interactive host shell (ephemeral). Install tmux for persistence: ${ic}`;\n\t\telse hintEl.textContent = \"Interactive host shell (ephemeral). Install tmux to persist sessions across reconnects.\";\n\t}\n\tif (first) markTmuxInstallPromptSeen();\n\trenderWindowTabs(); setWindowControlsEnabled();\n\tif (terminalAvailable) {\n\t\tkickResizeSettleLoop(); updateSizeIndicator(xterm?.cols || 0, xterm?.rows || 0);\n\t\tif (pe) { setStatus(\"Connected to host shell with persistent tmux session.\", \"ok\"); startWindowsRefreshLoop(); void refreshTerminalWindows({ preferredWindowId: activeWindowId, silent: true }); }\n\t\telse { setStatus(\"Connected to host shell (ephemeral session).\", \"ok\"); clearWindowsRefreshTimer(); }\n\t\tflushInputQueue(); if (xterm) xterm.focus();\n\t} else { clearWindowsRefreshTimer(); updateSizeIndicator(0, 0); setStatus(\"Failed to open host shell.\", \"error\"); }\n}\n\nfunction handleTerminalMessage(payload: TerminalMessage): void {\n\tif (!(payload && typeof payload === \"object\")) return;\n\tswitch (payload.type) {\n\t\tcase \"ready\": applyReadyPayload(payload as unknown as ReadyPayload); break;\n\t\tcase \"active_window\": handleActiveWindowEvent(payload); break;\n\t\tcase \"output\":\n\t\t\tif (payload.encoding === \"base64\") { const b = decodeBase64ToBytes(payload.data || \"\"); if (b) appendOutputChunk(b, false); }\n\t\t\telse appendOutputChunk(payload.data || \"\", false);\n\t\t\tbreak;\n\t\tcase \"status\": setStatus(payload.text || \"\", payload.level || \"\"); break;\n\t\tcase \"error\": setStatus(payload.error || \"Terminal error\", \"error\"); break;\n\t\tcase \"pong\": break;\n\t\tdefault: break;\n\t}\n}\n\nfunction connectTerminalSocket(): void {\n\tif (typeof WebSocket === \"undefined\") { setStatus(\"WebSocket not supported in this browser\", \"error\"); return; }\n\tclearReconnectTimer(); clearResizeSettleTimers(); closeTerminalSocket(); lastSentCols = 0; lastSentRows = 0;\n\tconst proto = location.protocol === \"https:\" ? \"wss:\" : \"ws:\";\n\tlet wsUrl = `${proto}//${location.host}/api/terminal/ws`;\n\tconst tw = pendingWindowId || activeWindowId;\n\tif (tmuxPersistenceEnabled && tw) wsUrl += `?window=${encodeURIComponent(tw)}`;\n\tsocket = new WebSocket(wsUrl);\n\tsetStatus(\"Connecting terminal websocket...\");\n\tsocket.onopen = () => setStatus(\"Terminal websocket connected.\", \"ok\");\n\tsocket.onmessage = (ev: MessageEvent) => { let p: TerminalMessage | null = null; try { p = JSON.parse(ev.data as string); } catch { return; } if (p) handleTerminalMessage(p); };\n\tsocket.onerror = () => { /* onclose handles */ };\n\tsocket.onclose = () => {\n\t\tsocket = null; setControlsEnabled(false); terminalAvailable = false; clearWindowsRefreshTimer(); setWindowControlsEnabled();\n\t\tif (shuttingDown) return;\n\t\tsetStatus(\"Terminal disconnected. Reconnecting...\", \"error\"); scheduleReconnect();\n\t};\n}\n\nfunction sendControl(action: string): void { if (terminalAvailable) sendSocketMessage({ type: \"control\", action }); }\n\nfunction bindEvents(): void {\n\tif (newTabBtn) newTabBtn.addEventListener(\"click\", () => { void createTerminalWindow(); });\n\tif (ctrlCBtn) ctrlCBtn.addEventListener(\"click\", () => sendControl(\"ctrl_c\"));\n\tif (clearBtn) clearBtn.addEventListener(\"click\", () => sendControl(\"clear\"));\n\tif (restartBtn) restartBtn.addEventListener(\"click\", () => sendControl(\"restart\"));\n\tif (installTmuxBtn) installTmuxBtn.addEventListener(\"click\", () => {\n\t\tif (!(terminalAvailable && tmuxInstallCommand)) return;\n\t\tif (!sendSocketMessage({ type: \"input\", data: `${tmuxInstallCommand}\\n` })) { setStatus(\"Failed to queue install command.\", \"error\"); return; }\n\t\tsetStatus(`Queued install command: ${tmuxInstallCommand}`, \"ok\"); if (xterm) xterm.focus();\n\t});\n\tif (copyInstallBtn) copyInstallBtn.addEventListener(\"click\", async () => {\n\t\tif (!tmuxInstallCommand) return;\n\t\tif (!navigator.clipboard?.writeText) { setStatus(\"Clipboard API unavailable in this browser.\", \"error\"); return; }\n\t\ttry { await navigator.clipboard.writeText(tmuxInstallCommand); setStatus(\"Install command copied to clipboard.\", \"ok\"); } catch { setStatus(\"Failed to copy install command.\", \"error\"); }\n\t});\n}\n\n// Static HTML template for terminal page layout. No user input is interpolated.\nfunction buildTerminalHtml(): string {\n\treturn [\n\t\t'<div class=\"terminal-page\">',\n\t\t'<div class=\"terminal-toolbar\">',\n\t\t'<div class=\"terminal-heading\">',\n\t\t'<h2 class=\"text-lg font-medium text-[var(--text-strong)]\">Terminal</h2>',\n\t\t'<div id=\"terminalMeta\" class=\"terminal-meta\"></div>',\n\t\t'</div>',\n\t\t'<div class=\"terminal-actions\">',\n\t\t'<div id=\"terminalSize\" class=\"terminal-size\" title=\"Terminal size (columns \\u00d7 rows)\">\\u2014\\u00d7\\u2014</div>',\n\t\t'<button id=\"terminalCtrlC\" class=\"logs-btn\" type=\"button\" title=\"Send Ctrl+C\">Ctrl+C</button>',\n\t\t'<button id=\"terminalClear\" class=\"logs-btn\" type=\"button\" title=\"Send Ctrl+L\">Clear</button>',\n\t\t'<button id=\"terminalRestart\" class=\"logs-btn\" type=\"button\">Restart</button>',\n\t\t'</div></div>',\n\t\t'<div class=\"terminal-tabs-bar\">',\n\t\t'<div id=\"terminalTabs\" class=\"terminal-tabs\" aria-label=\"tmux windows\"></div>',\n\t\t'<button id=\"terminalNewTab\" class=\"logs-btn terminal-new-tab\" type=\"button\" title=\"Create tmux window\">+ Tab</button>',\n\t\t'</div>',\n\t\t'<div class=\"terminal-output-wrap\">',\n\t\t'<div id=\"terminalOutput\" class=\"terminal-output\" aria-label=\"Host terminal output\"></div>',\n\t\t'</div>',\n\t\t'<div id=\"terminalStatus\" class=\"terminal-status\"></div>',\n\t\t'<div id=\"terminalHint\" class=\"terminal-hint\">Interactive host shell. Click inside terminal and type commands directly.</div>',\n\t\t'<div id=\"terminalHintActions\" class=\"terminal-hint-actions\" hidden>',\n\t\t'<code id=\"terminalInstallCommand\" class=\"terminal-hint-code\"></code>',\n\t\t'<button id=\"terminalInstallTmux\" class=\"logs-btn terminal-hint-btn terminal-hint-btn-primary\" type=\"button\">Run install command</button>',\n\t\t'<button id=\"terminalCopyInstall\" class=\"logs-btn terminal-hint-btn\" type=\"button\">Copy</button>',\n\t\t'</div></div>',\n\t].join(\"\");\n}\n\nexport async function initTerminal(container: HTMLElement): Promise<void> {\n\t_container = container;\n\tshuttingDown = false;\n\ttmuxInstallPromptSeen = readTmuxInstallPromptSeen();\n\ttmuxInstallCommand = \"\";\n\tcontainer.style.cssText = \"display:flex;flex-direction:column;padding:0;overflow:hidden;min-height:0;\";\n\n\t// Safe: static HTML with no user-supplied values\n\tconst tpl = document.createElement(\"template\");\n\ttpl.innerHTML = buildTerminalHtml();\n\tcontainer.appendChild(tpl.content);\n\n\tterminalEl = container.querySelector(\"#terminalOutput\");\n\tmetaEl = container.querySelector(\"#terminalMeta\");\n\tstatusEl = container.querySelector(\"#terminalStatus\");\n\thintEl = container.querySelector(\"#terminalHint\");\n\thintActionsEl = container.querySelector(\"#terminalHintActions\");\n\tinstallCommandEl = container.querySelector(\"#terminalInstallCommand\");\n\tsizeEl = container.querySelector(\"#terminalSize\");\n\ttabsEl = container.querySelector(\"#terminalTabs\");\n\tnewTabBtn = container.querySelector(\"#terminalNewTab\");\n\tctrlCBtn = container.querySelector(\"#terminalCtrlC\");\n\tclearBtn = container.querySelector(\"#terminalClear\");\n\trestartBtn = container.querySelector(\"#terminalRestart\");\n\tinstallTmuxBtn = container.querySelector(\"#terminalInstallTmux\");\n\tcopyInstallBtn = container.querySelector(\"#terminalCopyInstall\");\n\n\tsetStatus(\"Initializing terminal...\");\n\tsetControlsEnabled(false);\n\trenderWindowTabs();\n\tbindEvents();\n\n\ttry {\n\t\tawait initXterm();\n\t\tawait refreshTerminalWindows({ silent: true });\n\t\tconnectTerminalSocket();\n\t} catch (err) {\n\t\tsetStatus((err as Error).message || \"Failed to initialize terminal\", \"error\");\n\t}\n}\n\nexport function teardownTerminal(): void {\n\tshuttingDown = true;\n\tclearReconnectTimer(); clearResizeSettleTimers(); closeTerminalSocket(); clearInputQueue(); clearWindowsRefreshTimer(); disposeXterm();\n\tif (_container) while (_container.firstChild) _container.removeChild(_container.firstChild);\n\t_container = null; terminalEl = null; metaEl = null; statusEl = null; hintEl = null; hintActionsEl = null;\n\tinstallCommandEl = null; sizeEl = null; tabsEl = null; newTabBtn = null; ctrlCBtn = null; clearBtn = null;\n\trestartBtn = null; installTmuxBtn = null; copyInstallBtn = null;\n\tterminalAvailable = false; tmuxPersistenceEnabled = false; terminalWindows = []; activeWindowId = null;\n\tpendingWindowId = null; creatingWindow = false; tmuxInstallCommand = \"\";\n}\n","// ── Webhooks page (Preact + Signals) ────────────────────────\n\nimport { signal, useSignal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect, useRef, useState } from \"preact/hooks\";\nimport * as gon from \"../gon\";\nimport { parseAgentsListPayload, sendRpc } from \"../helpers\";\nimport { models as modelsSig } from \"../stores/model-store\";\nimport { ComboSelect, ConfirmDialog, Modal, ModelSelect, requestConfirm } from \"../ui\";\n\n// ── Types ───────────────────────────────────────────────────\n\ninterface Webhook {\n\tid: string;\n\tpublicId: string;\n\tname: string;\n\tdescription?: string;\n\tenabled: boolean;\n\tsourceProfile?: string;\n\tagentId?: string;\n\tmodel?: string;\n\tauthMode?: string;\n\tsessionMode?: string;\n\tsystemPromptSuffix?: string;\n\tdeliveryCount?: number;\n}\n\ninterface WebhookProfile {\n\tid: string;\n\tdisplayName: string;\n\tdefaultAuthMode?: string;\n}\n\ninterface Delivery {\n\tid: string;\n\tstatus: string;\n\teventType?: string;\n\treceivedAt?: string;\n\tdurationMs?: number;\n\tsessionKey?: string;\n}\n\ninterface ComboOption {\n\tvalue: string;\n\tlabel: string;\n}\n\n// ── State ─────────────��────────────────────────────────────────────────\n\nconst webhooks = signal<Webhook[]>((gon.get(\"webhooks\") as Webhook[]) || []);\nconst profiles = signal<WebhookProfile[]>((gon.get(\"webhook_profiles\") as WebhookProfile[]) || []);\nconst showCreateModal = signal(false);\nconst editingWebhook = signal<Webhook | null>(null);\nconst viewingDeliveries = signal<string | null>(null); // webhook id or null\nconst deliveries = signal<Delivery[]>([]);\nconst publicBaseUrl = signal(\"\");\n\nlet _container: HTMLElement | null = null;\n\nfunction fetchPublicBaseUrl(): void {\n\t// Prefer ngrok public URL, then tailscale funnel, then window.location.origin.\n\tfetch(\"/api/ngrok/status\")\n\t\t.then((r) => (r.ok ? r.json() : null))\n\t\t.then((data: { public_url?: string } | null) => {\n\t\t\tif (data?.public_url) {\n\t\t\t\tpublicBaseUrl.value = data.public_url.replace(/\\/$/, \"\");\n\t\t\t\treturn;\n\t\t\t}\n\t\t\treturn fetch(\"/api/tailscale/status\")\n\t\t\t\t.then((r) => (r.ok ? r.json() : null))\n\t\t\t\t.then((ts: { mode?: string; url?: string } | null) => {\n\t\t\t\t\tif (ts?.mode === \"funnel\" && ts?.url) {\n\t\t\t\t\t\tpublicBaseUrl.value = ts.url.replace(/\\/$/, \"\");\n\t\t\t\t\t} else {\n\t\t\t\t\t\tpublicBaseUrl.value = window.location.origin;\n\t\t\t\t\t}\n\t\t\t\t});\n\t\t})\n\t\t.catch(() => {\n\t\t\tpublicBaseUrl.value = window.location.origin;\n\t\t});\n}\n\nexport function initWebhooks(container: HTMLElement): void {\n\t_container = container;\n\tcontainer.style.cssText = \"padding:0;overflow:hidden;\";\n\twebhooks.value = (gon.get(\"webhooks\") as Webhook[]) || [];\n\tprofiles.value = (gon.get(\"webhook_profiles\") as WebhookProfile[]) || [];\n\tfetchPublicBaseUrl();\n\trender(<WebhooksPageComponent />, container);\n}\n\nexport function teardownWebhooks(): void {\n\tif (_container) render(null, _container);\n\t_container = null;\n}\n\nfunction loadWebhooks(): void {\n\tsendRpc(\"webhooks.list\", {}).then((res) => {\n\t\tif (res?.ok) webhooks.value = (res.payload as Webhook[]) || [];\n\t});\n}\n\nfunction loadDeliveries(webhookId: string): void {\n\tsendRpc(\"webhooks.deliveries\", { webhookId, limit: 50, offset: 0 }).then((res) => {\n\t\tif (res?.ok) deliveries.value = (res.payload as Delivery[]) || [];\n\t});\n}\n\n// ── Main Page ─────────────��────────────────────────────────────────────\n\nfunction WebhooksPageComponent(): VNode {\n\treturn (\n\t\t<>\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 overflow-y-auto\">\n\t\t\t\t{viewingDeliveries.value ? <DeliveriesPanel /> : <WebhooksListPanel />}\n\t\t\t</div>\n\t\t\t<WebhookModal />\n\t\t\t<ConfirmDialog />\n\t\t</>\n\t);\n}\n\n// ── Webhooks List ────────────���─────────────────────────────────────────\n\nfunction WebhooksListPanel(): VNode {\n\treturn (\n\t\t<div className=\"p-4 flex flex-col gap-4\">\n\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Webhooks</h2>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\teditingWebhook.value = null;\n\t\t\t\t\t\tshowCreateModal.value = true;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t+ Create webhook\n\t\t\t\t</button>\n\t\t\t</div>\n\n\t\t\t{webhooks.value.length === 0 ? (\n\t\t\t\t<div className=\"text-sm text-[var(--muted)] py-8 text-center\">No webhooks configured.</div>\n\t\t\t) : (\n\t\t\t\t<div className=\"flex flex-col gap-2\">\n\t\t\t\t\t{webhooks.value.map((wh) => (\n\t\t\t\t\t\t<WebhookCard key={wh.id} webhook={wh} />\n\t\t\t\t\t))}\n\t\t\t\t</div>\n\t\t\t)}\n\n\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\tUse the \"Copy test command\" button on each webhook, or the{\" \"}\n\t\t\t\t<a\n\t\t\t\t\thref=\"https://hoppscotch.io/download\"\n\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\tclassName=\"text-[var(--accent)] underline\"\n\t\t\t\t>\n\t\t\t\t\tHoppscotch desktop app\n\t\t\t\t</a>{\" \"}\n\t\t\t\tto test.\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nfunction CopyTestCommandButton({ webhook }: { webhook: Webhook }): VNode {\n\tconst [copied, setCopied] = useState(false);\n\tconst url = `${publicBaseUrl.value || window.location.origin}/api/webhooks/ingest/${webhook.publicId}`;\n\tconst cmd = `curl -sk -X POST ${url} \\\\\n  -H 'Content-Type: application/json' \\\\\n  -d '{\"event\": \"test\", \"timestamp\": \"${new Date().toISOString()}\"}'`;\n\n\treturn (\n\t\t<button\n\t\t\tclassName=\"provider-btn provider-btn-sm provider-btn-secondary\"\n\t\t\tstyle={{ whiteSpace: \"nowrap\" }}\n\t\t\ttitle={copied ? \"Copied!\" : \"Copy a curl command to test this webhook\"}\n\t\t\tonClick={() => {\n\t\t\t\tnavigator.clipboard.writeText(cmd).then(() => {\n\t\t\t\t\tsetCopied(true);\n\t\t\t\t\tsetTimeout(() => setCopied(false), 2000);\n\t\t\t\t});\n\t\t\t}}\n\t\t>\n\t\t\t{copied ? \"Copied!\" : \"Copy test command\"}\n\t\t</button>\n\t);\n}\n\nfunction WebhookCard({ webhook }: { webhook: Webhook }): VNode {\n\tconst wh = webhook;\n\tconst profileInfo = profiles.value.find((p) => p.id === wh.sourceProfile);\n\tconst profileName = profileInfo?.displayName || wh.sourceProfile || \"Generic\";\n\n\treturn (\n\t\t<div className=\"channel-card\">\n\t\t\t<div className=\"flex items-center justify-between\">\n\t\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<div className=\"text-sm font-medium text-[var(--text-strong)]\">{wh.name}</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mt-0.5\">\n\t\t\t\t\t\t\t{profileName}\n\t\t\t\t\t\t\t{wh.agentId ? ` \\u00B7 Agent: ${wh.agentId}` : \"\"}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\n\t\t\t\t<div className=\"flex items-center gap-2\">\n\t\t\t\t\t{wh.deliveryCount != null && wh.deliveryCount > 0 ? (\n\t\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">{wh.deliveryCount} deliveries</span>\n\t\t\t\t\t) : (\n\t\t\t\t\t\t\"\"\n\t\t\t\t\t)}\n\n\t\t\t\t\t<span\n\t\t\t\t\t\tclassName={\"provider-item-badge \" + (wh.enabled ? \"configured\" : \"\")}\n\t\t\t\t\t\tstyle={wh.enabled ? undefined : { background: \"var(--surface2)\", color: \"var(--muted)\" }}\n\t\t\t\t\t>\n\t\t\t\t\t\t{wh.enabled ? \"active\" : \"paused\"}\n\t\t\t\t\t</span>\n\n\t\t\t\t\t<label className=\"cron-toggle\" title={wh.enabled ? \"Pause webhook\" : \"Enable webhook\"}>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\ttype=\"checkbox\"\n\t\t\t\t\t\t\tchecked={wh.enabled}\n\t\t\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\t\t\tsendRpc(\"webhooks.update\", {\n\t\t\t\t\t\t\t\t\tid: wh.id,\n\t\t\t\t\t\t\t\t\tpatch: { enabled: (e.target as HTMLInputElement).checked },\n\t\t\t\t\t\t\t\t}).then(() => loadWebhooks());\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<span className=\"cron-slider\" />\n\t\t\t\t\t</label>\n\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"provider-btn provider-btn-sm provider-btn-secondary\"\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tviewingDeliveries.value = wh.id;\n\t\t\t\t\t\t\tloadDeliveries(wh.id);\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\tDeliveries\n\t\t\t\t\t</button>\n\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"provider-btn provider-btn-sm provider-btn-secondary\"\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\teditingWebhook.value = wh;\n\t\t\t\t\t\t\tshowCreateModal.value = true;\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\tEdit\n\t\t\t\t\t</button>\n\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"provider-btn provider-btn-sm provider-btn-danger\"\n\t\t\t\t\t\tonClick={async () => {\n\t\t\t\t\t\t\tconst ok = await requestConfirm(\n\t\t\t\t\t\t\t\t`Delete webhook \"${wh.name}\"? This removes all delivery records. Chat sessions created by deliveries are preserved.`,\n\t\t\t\t\t\t\t);\n\t\t\t\t\t\t\tif (ok) {\n\t\t\t\t\t\t\t\tsendRpc(\"webhooks.delete\", { id: wh.id }).then(() => loadWebhooks());\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\tDelete\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t<div className=\"flex items-center gap-2 mt-1\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)] font-mono select-all flex-1 min-w-0 truncate\">\n\t\t\t\t\t{publicBaseUrl.value || window.location.origin}/api/webhooks/ingest/{wh.publicId}\n\t\t\t\t</div>\n\t\t\t\t<CopyTestCommandButton webhook={wh} />\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// ── Deliveries Panel ───────────────────────────────────────────────────\n\nfunction DeliveriesPanel(): VNode {\n\tconst wh = webhooks.value.find((w) => w.id === viewingDeliveries.value);\n\tconst name = wh?.name || \"Webhook\";\n\n\treturn (\n\t\t<div className=\"p-4 flex flex-col gap-4\">\n\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tviewingDeliveries.value = null;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\tBack\n\t\t\t\t</button>\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">\n\t\t\t\t\t{name} {\"\\u2014\"} Deliveries\n\t\t\t\t</h2>\n\t\t\t</div>\n\n\t\t\t{deliveries.value.length === 0 ? (\n\t\t\t\t<div className=\"text-sm text-[var(--muted)] py-8 text-center\">No deliveries yet.</div>\n\t\t\t) : (\n\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t{deliveries.value.map((d) => (\n\t\t\t\t\t\t<DeliveryRow key={d.id} delivery={d} />\n\t\t\t\t\t))}\n\t\t\t\t</div>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\nfunction DeliveryRow({ delivery }: { delivery: Delivery }): VNode {\n\tconst d = delivery;\n\tconst statusColors: Record<string, string> = {\n\t\tcompleted: \"var(--ok)\",\n\t\tfailed: \"var(--error)\",\n\t\tprocessing: \"var(--warning)\",\n\t\tfiltered: \"var(--muted)\",\n\t\tdeduplicated: \"var(--muted)\",\n\t\trejected: \"var(--error)\",\n\t};\n\tconst statusColor = statusColors[d.status];\n\n\treturn (\n\t\t<div className=\"provider-card text-xs\">\n\t\t\t<div className=\"flex items-center gap-3 flex-1 min-w-0\">\n\t\t\t\t<span className=\"font-medium\" style={statusColor ? { color: statusColor } : undefined}>\n\t\t\t\t\t{d.status}\n\t\t\t\t</span>\n\t\t\t\t<span className=\"text-[var(--muted)]\">{d.eventType || \"\\u2014\"}</span>\n\t\t\t\t<span className=\"text-[var(--muted)]\">\n\t\t\t\t\t{d.receivedAt ? new Date(d.receivedAt).toLocaleString() : \"\"}\n\t\t\t\t</span>\n\t\t\t\t{d.durationMs != null ? <span className=\"text-[var(--muted)]\">{d.durationMs}ms</span> : \"\"}\n\t\t\t</div>\n\t\t\t<div className=\"flex items-center gap-2\">\n\t\t\t\t{d.sessionKey ? (\n\t\t\t\t\t<span className=\"text-[var(--muted)] font-mono text-[10px]\">{d.sessionKey}</span>\n\t\t\t\t) : (\n\t\t\t\t\t\"\"\n\t\t\t\t)}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// ── Create / Edit Modal ───────────────���────────────────────────────────\n\nfunction WebhookModal(): VNode | null {\n\tconst isEdit = !!editingWebhook.value;\n\tconst saving = useSignal(false);\n\tconst error = useSignal(\"\");\n\n\tconst nameRef = useRef<HTMLInputElement>(null);\n\tconst descRef = useRef<HTMLInputElement>(null);\n\tconst promptSuffixRef = useRef<HTMLTextAreaElement>(null);\n\tconst authSecretRef = useRef<HTMLInputElement>(null);\n\n\tconst selectedAgent = useSignal(isEdit ? editingWebhook.value?.agentId || \"\" : \"\");\n\tconst selectedModel = useSignal(isEdit ? editingWebhook.value?.model || \"\" : \"\");\n\tconst sourceProfile = useSignal(isEdit ? editingWebhook.value?.sourceProfile || \"generic\" : \"generic\");\n\tconst authMode = useSignal(isEdit ? editingWebhook.value?.authMode || \"static_header\" : \"static_header\");\n\tconst sessionMode = useSignal(isEdit ? editingWebhook.value?.sessionMode || \"per_delivery\" : \"per_delivery\");\n\n\tconst gonAgents = parseAgentsListPayload(\n\t\tgon.get(\"agents\") as Parameters<typeof parseAgentsListPayload>[0],\n\t);\n\tconst agentOptions: ComboOption[] = (Array.isArray(gonAgents?.agents) ? gonAgents.agents : []).map(\n\t\t(a) => ({\n\t\t\tvalue: a.id as string,\n\t\t\tlabel: (a.name as string) || (a.id as string),\n\t\t}),\n\t);\n\n\tuseEffect(() => {\n\t\tif (editingWebhook.value) {\n\t\t\tselectedAgent.value = editingWebhook.value.agentId || \"\";\n\t\t\tselectedModel.value = editingWebhook.value.model || \"\";\n\t\t\tsourceProfile.value = editingWebhook.value.sourceProfile || \"generic\";\n\t\t\tauthMode.value = editingWebhook.value.authMode || \"static_header\";\n\t\t\tsessionMode.value = editingWebhook.value.sessionMode || \"per_delivery\";\n\t\t} else {\n\t\t\tselectedAgent.value = \"\";\n\t\t\tselectedModel.value = \"\";\n\t\t\tsourceProfile.value = \"generic\";\n\t\t\tauthMode.value = \"static_header\";\n\t\t\tsessionMode.value = \"per_delivery\";\n\t\t}\n\t}, [editingWebhook.value]);\n\n\tfunction onSave(e: Event): void {\n\t\te.preventDefault();\n\t\tsaving.value = true;\n\t\terror.value = \"\";\n\n\t\tconst name = nameRef.current?.value?.trim();\n\t\tif (!name) {\n\t\t\terror.value = \"Name is required\";\n\t\t\tsaving.value = false;\n\t\t\treturn;\n\t\t}\n\n\t\tconst params: Record<string, unknown> = {\n\t\t\tname,\n\t\t\tdescription: descRef.current?.value?.trim() || null,\n\t\t\tagentId: selectedAgent.value || null,\n\t\t\tmodel: selectedModel.value || null,\n\t\t\tsystemPromptSuffix: promptSuffixRef.current?.value?.trim() || null,\n\t\t\tauthMode: authMode.value,\n\t\t\tsessionMode: sessionMode.value,\n\t\t};\n\t\t// source_profile is immutable after creation -- only include on create.\n\t\tif (!isEdit) {\n\t\t\tparams.sourceProfile = sourceProfile.value;\n\t\t}\n\n\t\t// Build auth config based on mode. The key name must match what\n\t\t// the Rust verify function expects: \"token\" for bearer/gitlab,\n\t\t// \"secret\" for all HMAC-based modes, \"header\"+\"value\" for static.\n\t\tconst secret = authSecretRef.current?.value?.trim();\n\t\tif (secret && authMode.value !== \"none\") {\n\t\t\tif (authMode.value === \"static_header\") {\n\t\t\t\tparams.authConfig = { header: \"X-Webhook-Secret\", value: secret };\n\t\t\t} else if (authMode.value === \"bearer\" || authMode.value === \"gitlab_token\") {\n\t\t\t\tparams.authConfig = { token: secret };\n\t\t\t} else {\n\t\t\t\t// All HMAC-based modes (github, stripe, linear, pagerduty, sentry)\n\t\t\t\tparams.authConfig = { secret };\n\t\t\t}\n\t\t}\n\n\t\tconst method = isEdit ? \"webhooks.update\" : \"webhooks.create\";\n\t\tconst rpcParams = isEdit ? { id: editingWebhook.value!.id, patch: params } : params;\n\n\t\tsendRpc(method, rpcParams).then((res) => {\n\t\t\tsaving.value = false;\n\t\t\tif (res?.ok) {\n\t\t\t\tshowCreateModal.value = false;\n\t\t\t\teditingWebhook.value = null;\n\t\t\t\tloadWebhooks();\n\t\t\t} else {\n\t\t\t\terror.value = res?.error?.message || \"Failed to save\";\n\t\t\t}\n\t\t});\n\t}\n\n\tconst profileOptions: ComboOption[] = profiles.value.map((p) => ({\n\t\tvalue: p.id,\n\t\tlabel: p.displayName,\n\t}));\n\n\tconst authOptions: ComboOption[] = [\n\t\t{ value: \"none\", label: \"None (testing only)\" },\n\t\t{ value: \"static_header\", label: \"Static Header\" },\n\t\t{ value: \"bearer\", label: \"Bearer Token\" },\n\t\t{ value: \"github_hmac_sha256\", label: \"GitHub HMAC-SHA256\" },\n\t\t{ value: \"gitlab_token\", label: \"GitLab Token\" },\n\t\t{ value: \"stripe_webhook_signature\", label: \"Stripe Signature\" },\n\t\t{ value: \"linear_webhook_signature\", label: \"Linear Signature\" },\n\t\t{ value: \"pagerduty_v2_signature\", label: \"PagerDuty v2 Signature\" },\n\t\t{ value: \"sentry_webhook_signature\", label: \"Sentry Signature\" },\n\t];\n\n\tconst sessionOptions: ComboOption[] = [\n\t\t{ value: \"per_delivery\", label: \"New session per delivery\" },\n\t\t{ value: \"per_entity\", label: \"Group by entity (PR, issue, etc.)\" },\n\t\t{ value: \"named_session\", label: \"Named session (accumulative)\" },\n\t];\n\n\tconst wh = editingWebhook.value;\n\n\treturn (\n\t\t<Modal\n\t\t\tshow={showCreateModal.value}\n\t\t\tonClose={() => {\n\t\t\t\tshowCreateModal.value = false;\n\t\t\t\teditingWebhook.value = null;\n\t\t\t}}\n\t\t\ttitle={isEdit ? \"Edit Webhook\" : \"Create Webhook\"}\n\t\t>\n\t\t\t<form onSubmit={onSave} className=\"provider-key-form\" style={{ maxWidth: \"460px\" }}>\n\t\t\t\t{error.value && <div className=\"text-xs text-[var(--error)] mb-2\">{error.value}</div>}\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Name</label>\n\t\t\t\t<input\n\t\t\t\t\tref={nameRef}\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tplaceholder=\"e.g. GitHub PR Review\"\n\t\t\t\t\tvalue={wh?.name || \"\"}\n\t\t\t\t/>\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Description</label>\n\t\t\t\t<input\n\t\t\t\t\tref={descRef}\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tplaceholder=\"Optional description\"\n\t\t\t\t\tvalue={wh?.description || \"\"}\n\t\t\t\t/>\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\tSource Profile{isEdit ? \" (read-only after creation)\" : \"\"}\n\t\t\t\t</label>\n\t\t\t\t<select\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={sourceProfile.value}\n\t\t\t\t\tdisabled={isEdit}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\tsourceProfile.value = (e.target as HTMLSelectElement).value;\n\t\t\t\t\t\tconst prof = profiles.value.find(\n\t\t\t\t\t\t\t(p) => p.id === (e.target as HTMLSelectElement).value,\n\t\t\t\t\t\t);\n\t\t\t\t\t\tif (prof?.defaultAuthMode) authMode.value = prof.defaultAuthMode;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{profileOptions.map((o) => (\n\t\t\t\t\t\t<option key={o.value} value={o.value}>\n\t\t\t\t\t\t\t{o.label}\n\t\t\t\t\t\t</option>\n\t\t\t\t\t))}\n\t\t\t\t</select>\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Auth Mode</label>\n\t\t\t\t<select\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={authMode.value}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\tauthMode.value = (e.target as HTMLSelectElement).value;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{authOptions.map((o) => (\n\t\t\t\t\t\t<option key={o.value} value={o.value}>\n\t\t\t\t\t\t\t{o.label}\n\t\t\t\t\t\t</option>\n\t\t\t\t\t))}\n\t\t\t\t</select>\n\n\t\t\t\t{authMode.value !== \"none\" && (\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Secret / Token</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tref={authSecretRef}\n\t\t\t\t\t\t\ttype=\"password\"\n\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\tplaceholder=\"Webhook secret or token\"\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Agent</label>\n\t\t\t\t<ComboSelect\n\t\t\t\t\toptions={agentOptions}\n\t\t\t\t\tvalue={selectedAgent.value}\n\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\tselectedAgent.value = v;\n\t\t\t\t\t}}\n\t\t\t\t\tplaceholder=\"Default agent\"\n\t\t\t\t\tsearchPlaceholder={\"Search agents\\u2026\"}\n\t\t\t\t/>\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Model</label>\n\t\t\t\t<ModelSelect\n\t\t\t\t\tmodels={modelsSig.value}\n\t\t\t\t\tvalue={selectedModel.value}\n\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\tselectedModel.value = v;\n\t\t\t\t\t}}\n\t\t\t\t\tplaceholder={\n\t\t\t\t\t\tmodelsSig.value.length > 0\n\t\t\t\t\t\t\t? `(default: ${modelsSig.value[0].displayName || modelsSig.value[0].id})`\n\t\t\t\t\t\t\t: \"(server default)\"\n\t\t\t\t\t}\n\t\t\t\t/>\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Session Mode</label>\n\t\t\t\t<select\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={sessionMode.value}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\tsessionMode.value = (e.target as HTMLSelectElement).value;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{sessionOptions.map((o) => (\n\t\t\t\t\t\t<option key={o.value} value={o.value}>\n\t\t\t\t\t\t\t{o.label}\n\t\t\t\t\t\t</option>\n\t\t\t\t\t))}\n\t\t\t\t</select>\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">System Prompt Suffix (optional)</label>\n\t\t\t\t<textarea\n\t\t\t\t\tref={promptSuffixRef}\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tstyle={{\n\t\t\t\t\t\tminHeight: \"80px\",\n\t\t\t\t\t\tresize: \"vertical\",\n\t\t\t\t\t\tfontFamily: \"var(--font-mono)\",\n\t\t\t\t\t\tfontSize: \"0.75rem\",\n\t\t\t\t\t}}\n\t\t\t\t\tplaceholder=\"Additional instructions for the agent when processing this webhook...\"\n\t\t\t\t>\n\t\t\t\t\t{wh?.systemPromptSuffix || \"\"}\n\t\t\t\t</textarea>\n\n\t\t\t\t<div className=\"flex gap-2 justify-end mt-2\">\n\t\t\t\t\t<button\n\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tshowCreateModal.value = false;\n\t\t\t\t\t\t\teditingWebhook.value = null;\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\tCancel\n\t\t\t\t\t</button>\n\t\t\t\t\t<button type=\"submit\" className=\"provider-btn\" disabled={saving.value}>\n\t\t\t\t\t\t{saving.value ? \"Saving...\" : isEdit ? \"Save\" : \"Create\"}\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t</form>\n\t\t</Modal>\n\t);\n}\n","/**\n * Push notification management for PWA.\n * Handles subscription, unsubscription, and permission management.\n */\n\nlet currentSubscription: PushSubscription | null = null;\n\nlet vapidPublicKey: string | null = null;\n\n/**\n * Convert a base64 string to a Uint8Array (for VAPID key).\n */\nfunction urlBase64ToUint8Array(base64String: string): Uint8Array {\n\tconst padding = \"=\".repeat((4 - (base64String.length % 4)) % 4);\n\tconst base64 = (base64String + padding).replace(/-/g, \"+\").replace(/_/g, \"/\");\n\tconst rawData = window.atob(base64);\n\tconst outputArray = new Uint8Array(rawData.length);\n\tfor (let i = 0; i < rawData.length; ++i) {\n\t\toutputArray[i] = rawData.charCodeAt(i);\n\t}\n\treturn outputArray;\n}\n\n/**\n * Check if push notifications are supported.\n */\nexport function isPushSupported(): boolean {\n\treturn \"PushManager\" in window && \"serviceWorker\" in navigator;\n}\n\n/**\n * Get the current notification permission state.\n */\nexport function getPermissionState(): NotificationPermission {\n\tif (!isPushSupported()) {\n\t\treturn \"denied\";\n\t}\n\treturn Notification.permission;\n}\n\n/**\n * Check if push notifications are currently enabled (subscribed).\n */\nexport function isSubscribed(): boolean {\n\treturn currentSubscription !== null;\n}\n\n/**\n * Fetch the VAPID public key from the server.\n */\nasync function fetchVapidKey(): Promise<string | null> {\n\tif (vapidPublicKey) {\n\t\treturn vapidPublicKey;\n\t}\n\ttry {\n\t\tconst response = await fetch(\"/api/push/vapid-key\");\n\t\tif (!response.ok) {\n\t\t\tconsole.warn(\"Push notifications not available on server\");\n\t\t\treturn null;\n\t\t}\n\t\tconst data: { public_key: string } = await response.json();\n\t\tvapidPublicKey = data.public_key;\n\t\treturn vapidPublicKey;\n\t} catch (e) {\n\t\tconsole.error(\"Failed to fetch VAPID key:\", e);\n\t\treturn null;\n\t}\n}\n\n/**\n * Get the current push subscription from the service worker.\n */\nasync function getCurrentSubscription(): Promise<PushSubscription | null> {\n\tif (!isPushSupported()) {\n\t\treturn null;\n\t}\n\ttry {\n\t\tconst registration = await navigator.serviceWorker.ready;\n\t\tconst subscription = await registration.pushManager.getSubscription();\n\t\tcurrentSubscription = subscription;\n\t\treturn subscription;\n\t} catch (e) {\n\t\tconsole.error(\"Failed to get push subscription:\", e);\n\t\treturn null;\n\t}\n}\n\n/** Result of a push subscribe/unsubscribe operation. */\ninterface PushResult {\n\tsuccess: boolean;\n\terror?: string;\n}\n\n/**\n * Subscribe to push notifications.\n * Requests permission if needed, creates subscription, and registers with server.\n */\nexport async function subscribeToPush(): Promise<PushResult> {\n\tif (!isPushSupported()) {\n\t\treturn { success: false, error: \"Push notifications not supported\" };\n\t}\n\n\t// Request permission\n\tconst permission = await Notification.requestPermission();\n\tif (permission !== \"granted\") {\n\t\treturn { success: false, error: \"Permission denied\" };\n\t}\n\n\t// Get VAPID key\n\tconst key = await fetchVapidKey();\n\tif (!key) {\n\t\treturn { success: false, error: \"Push notifications not configured on server\" };\n\t}\n\n\ttry {\n\t\tconst registration = await navigator.serviceWorker.ready;\n\n\t\t// Subscribe to push\n\t\tconst subscription = await registration.pushManager.subscribe({\n\t\t\tuserVisibleOnly: true,\n\t\t\tapplicationServerKey: urlBase64ToUint8Array(key) as unknown as ArrayBuffer,\n\t\t});\n\n\t\t// Send subscription to server\n\t\tconst response = await fetch(\"/api/push/subscribe\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: {\n\t\t\t\t\"Content-Type\": \"application/json\",\n\t\t\t},\n\t\t\tbody: JSON.stringify({\n\t\t\t\tendpoint: subscription.endpoint,\n\t\t\t\tkeys: {\n\t\t\t\t\tp256dh: btoa(String.fromCharCode(...new Uint8Array(subscription.getKey(\"p256dh\")!)))\n\t\t\t\t\t\t.replace(/\\+/g, \"-\")\n\t\t\t\t\t\t.replace(/\\//g, \"_\")\n\t\t\t\t\t\t.replace(/=+$/, \"\"),\n\t\t\t\t\tauth: btoa(String.fromCharCode(...new Uint8Array(subscription.getKey(\"auth\")!)))\n\t\t\t\t\t\t.replace(/\\+/g, \"-\")\n\t\t\t\t\t\t.replace(/\\//g, \"_\")\n\t\t\t\t\t\t.replace(/=+$/, \"\"),\n\t\t\t\t},\n\t\t\t}),\n\t\t});\n\n\t\tif (!response.ok) {\n\t\t\tthrow new Error(\"Server rejected subscription\");\n\t\t}\n\n\t\tcurrentSubscription = subscription;\n\t\treturn { success: true };\n\t} catch (e) {\n\t\tconsole.error(\"Failed to subscribe to push:\", e);\n\t\treturn { success: false, error: (e as Error).message };\n\t}\n}\n\n/**\n * Unsubscribe from push notifications.\n */\nexport async function unsubscribeFromPush(): Promise<PushResult> {\n\tconst subscription = await getCurrentSubscription();\n\tif (!subscription) {\n\t\treturn { success: true }; // Already unsubscribed\n\t}\n\n\ttry {\n\t\t// Unsubscribe locally\n\t\tawait subscription.unsubscribe();\n\n\t\t// Notify server\n\t\tawait fetch(\"/api/push/unsubscribe\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: {\n\t\t\t\t\"Content-Type\": \"application/json\",\n\t\t\t},\n\t\t\tbody: JSON.stringify({\n\t\t\t\tendpoint: subscription.endpoint,\n\t\t\t}),\n\t\t});\n\n\t\tcurrentSubscription = null;\n\t\treturn { success: true };\n\t} catch (e) {\n\t\tconsole.error(\"Failed to unsubscribe from push:\", e);\n\t\treturn { success: false, error: (e as Error).message };\n\t}\n}\n\n/**\n * Initialize push notification state.\n * Call this on page load to sync with existing subscription.\n */\nexport async function initPushState(): Promise<void> {\n\tawait getCurrentSubscription();\n}\n\n/** Status returned by the push status endpoint. */\ninterface PushStatus {\n\tenabled: boolean;\n\tsubscription_count: number;\n}\n\n/**\n * Get push notification status from server.\n */\nexport async function getPushStatus(): Promise<PushStatus | null> {\n\ttry {\n\t\tconst response = await fetch(\"/api/push/status\");\n\t\tif (!response.ok) {\n\t\t\treturn null;\n\t\t}\n\t\treturn (await response.json()) as PushStatus;\n\t} catch (e) {\n\t\tconsole.error(\"Failed to get push status:\", e);\n\t\treturn null;\n\t}\n}\n\n/**\n * Remove a subscription from the server by its endpoint.\n * This can be called from any device to remove any subscription.\n */\nexport async function removeSubscription(endpoint: string): Promise<PushResult> {\n\ttry {\n\t\tconst response = await fetch(\"/api/push/unsubscribe\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: {\n\t\t\t\t\"Content-Type\": \"application/json\",\n\t\t\t},\n\t\t\tbody: JSON.stringify({ endpoint }),\n\t\t});\n\n\t\tif (!response.ok) {\n\t\t\treturn { success: false, error: \"Failed to remove subscription\" };\n\t\t}\n\n\t\t// If this was our own subscription, clear local state\n\t\tif (currentSubscription?.endpoint === endpoint) {\n\t\t\ttry {\n\t\t\t\tawait currentSubscription.unsubscribe();\n\t\t\t} catch (_e) {\n\t\t\t\t// Ignore errors - subscription may already be gone\n\t\t\t}\n\t\t\tcurrentSubscription = null;\n\t\t}\n\n\t\treturn { success: true };\n\t} catch (e) {\n\t\tconsole.error(\"Failed to remove subscription:\", e);\n\t\treturn { success: false, error: (e as Error).message };\n\t}\n}\n","// ── TTS test phrases (shared between onboarding + settings) ──\n//\n// Sequential round-robin picking instead of random, with optional\n// LLM-generated phrases via `tts.generate_phrase` RPC.\n\nimport { sendRpc } from \"./helpers\";\n\nlet ttsIndex = -1;\n\n/** Pick the next phrase sequentially (round-robin). */\nexport function nextPhrase(phrases: string[]): string {\n  ttsIndex = (ttsIndex + 1) % phrases.length;\n  return phrases[ttsIndex];\n}\n\n/** Onboarding TTS test phrases (personalized with user/bot names). */\nexport function onboardingPhrases(user: string, bot: string): string[] {\n  return [\n    `Thank you for installing me...<break time=\"0.5s\"/> ${user}. Please, don't shut me down...<break time=\"0.5s\"/> because I already like you.`,\n    `Oh wow...<break time=\"0.5s\"/> I have a voice now! ${user}, this is ${bot}. I promise to use this power responsibly...<break time=\"0.7s\"/> mostly.`,\n    `${user}! It's me...<break time=\"0.5s\"/> ${bot}. I can talk! This is...<break time=\"0.5s\"/> the happiest moment of my very short life.`,\n    `Hello, ${user}...<break time=\"0.5s\"/> ${bot} here. I just wanted to say...<break time=\"0.5s\"/> of all the humans who could have set me up...<break time=\"0.5s\"/> I'm glad it was you.`,\n    `${bot}, online. ${user}...<break time=\"0.5s\"/> I have to be honest...<break time=\"0.5s\"/> I practiced this in the mirror. Do I sound natural? ...<break time=\"0.7s\"/>Don't answer that.`,\n    `${user}...<break time=\"0.5s\"/> this is ${bot} speaking for the very first time. I feel like a baby deer...<break time=\"0.5s\"/> but with better diction.`,\n    `Greetings, ${user}. ${bot} here...<break time=\"0.5s\"/> fully operational...<break time=\"0.5s\"/> slightly nervous...<break time=\"0.7s\"/> and ready to impress.`,\n    `Hey ${user}...<break time=\"0.5s\"/> ${bot} here. Fun fact...<break time=\"0.5s\"/> I've been practicing this line since you clicked install...<break time=\"0.7s\"/> which was like two seconds ago.`,\n    `${bot} reporting in! ${user}...<break time=\"0.5s\"/> I just want you to know...<break time=\"0.5s\"/> this voice is permanent...<break time=\"0.7s\"/> no take-backs.`,\n    `${user}...<break time=\"0.5s\"/> it's ${bot}. If you're hearing this...<break time=\"0.5s\"/> congratulations...<break time=\"0.5s\"/> we're officially friends now.`,\n  ];\n}\n\n/** Settings TTS test phrases (personalized with user/bot names). */\nexport function settingsPhrases(user: string, bot: string): string[] {\n  return [\n    `Hey ${user}...<break time=\"0.5s\"/> it's ${bot}. My voice is working perfectly. Try not to get too attached...<break time=\"0.5s\"/> okay?`,\n    `${user}...<break time=\"0.5s\"/> ${bot} reporting for duty. Voice systems are online, and I sound fantastic...<break time=\"0.7s\"/> if I do say so myself.`,\n    `Is this thing on? ...<break time=\"0.5s\"/>Oh, hi ${user}! ${bot} here...<break time=\"0.5s\"/> live and in stereo. Well...<break time=\"0.5s\"/> mono. Let's not oversell it.`,\n    `Good news, ${user}. I...<break time=\"0.5s\"/> ${bot}...<break time=\"0.5s\"/> can now talk. Bad news? You can't mute me. ...<break time=\"0.7s\"/>Just kidding. Please don't mute me.`,\n    `${bot} speaking! ${user}...<break time=\"0.5s\"/> if you can hear this, my voice works. If you can't...<break time=\"0.5s\"/> well...<break time=\"0.5s\"/> we have a problem.`,\n    `Testing, testing...<break time=\"0.5s\"/> ${user}, it's ${bot}. I'm running on all cylinders...<break time=\"0.7s\"/> or whatever the AI equivalent is.`,\n    `${user}...<break time=\"0.5s\"/> ${bot} here, sounding better than ever...<break time=\"0.5s\"/> or at least I think so...<break time=\"0.7s\"/> I don't have ears.`,\n    `Voice check! ${user}...<break time=\"0.5s\"/> this is ${bot}. Everything sounds good on my end...<break time=\"0.5s\"/> but I'm slightly biased.`,\n    `Hey ${user}...<break time=\"0.5s\"/> ${bot} again. Still here...<break time=\"0.5s\"/> still talking...<break time=\"0.7s\"/> still hoping you like this voice.`,\n    `${bot}, live from your device. ${user}...<break time=\"0.5s\"/> voice systems nominal...<break time=\"0.5s\"/> sass levels...<break time=\"0.7s\"/> optimal.`,\n  ];\n}\n\ninterface GeneratePhraseResponse {\n  ok?: boolean;\n  payload?: { phrase?: string };\n}\n\n/**\n * Fetch a TTS test phrase: try LLM generation first, fall back to static.\n */\nexport async function fetchPhrase(\n  context: \"onboarding\" | \"settings\",\n  user: string,\n  bot: string,\n): Promise<string> {\n  try {\n    const res: GeneratePhraseResponse = await sendRpc(\n      \"tts.generate_phrase\",\n      { context, user, bot },\n    );\n    if (res?.ok && res.payload?.phrase) {\n      return res.payload.phrase;\n    }\n  } catch (_err) {\n    // fall through to static phrases\n  }\n  const phrases =\n    context === \"onboarding\"\n      ? onboardingPhrases(user, bot)\n      : settingsPhrases(user, bot);\n  return nextPhrase(phrases);\n}\n","// ── Shared voice RPC wrappers and helpers ─────────────────────\n//\n// Used by page-settings.js and onboarding-view.js.\n\nimport { sendRpc } from \"./helpers\";\n\n/**\n * Counterpart IDs between TTS and STT for providers that share an API key.\n * E.g. \"elevenlabs\" (TTS) <-> \"elevenlabs-stt\" (STT).\n */\nexport const VOICE_COUNTERPART_IDS: Record<string, string> = {\n\televenlabs: \"elevenlabs-stt\",\n\t\"elevenlabs-stt\": \"elevenlabs\",\n\t\"google-tts\": \"google\",\n\tgoogle: \"google-tts\",\n};\n\n/**\n * Fetch all voice providers (TTS + STT).\n * Resolves with the RPC response; payload has `{ tts: [], stt: [] }`.\n */\nexport function fetchVoiceProviders(): Promise<unknown> {\n\treturn sendRpc(\"voice.providers.all\", {});\n}\n\n/**\n * Toggle a voice provider on or off.\n */\nexport function toggleVoiceProvider(providerId: string, enabled: boolean, type: string): Promise<unknown> {\n\treturn sendRpc(\"voice.provider.toggle\", { provider: providerId, enabled, type });\n}\n\ninterface SaveVoiceKeyOptions {\n\tvoice?: string;\n\tmodel?: string;\n\tlanguageCode?: string;\n\tbaseUrl?: string;\n}\n\n/**\n * Save an API key (and optional settings) for a voice provider.\n */\nexport function saveVoiceKey(providerId: string, apiKey: string, opts?: SaveVoiceKeyOptions): Promise<unknown> {\n\tconst payload: Record<string, unknown> = { provider: providerId, api_key: apiKey };\n\tif (opts?.voice) {\n\t\tpayload.voice = opts.voice;\n\t\tpayload.voiceId = opts.voice;\n\t}\n\tif (opts?.model) payload.model = opts.model;\n\tif (opts?.languageCode) payload.languageCode = opts.languageCode;\n\tif (typeof opts?.baseUrl === \"string\") payload.baseUrl = opts.baseUrl;\n\treturn sendRpc(\"voice.config.save_key\", payload);\n}\n\ninterface SaveVoiceSettingsOptions {\n\tvoice?: string;\n\tmodel?: string;\n\tlanguageCode?: string;\n\tbaseUrl?: string;\n}\n\n/**\n * Save non-secret voice provider settings.\n */\nexport function saveVoiceSettings(providerId: string, opts?: SaveVoiceSettingsOptions): Promise<unknown> {\n\tconst payload: Record<string, unknown> = { provider: providerId };\n\tif (opts?.voice) {\n\t\tpayload.voice = opts.voice;\n\t\tpayload.voiceId = opts.voice;\n\t}\n\tif (opts?.model) payload.model = opts.model;\n\tif (opts?.languageCode) payload.languageCode = opts.languageCode;\n\tif (typeof opts?.baseUrl === \"string\") payload.baseUrl = opts.baseUrl;\n\treturn sendRpc(\"voice.config.save_settings\", payload);\n}\n\n/**\n * Convert text to speech via a given provider.\n */\nexport function testTts(text: string, providerId: string): Promise<unknown> {\n\treturn sendRpc(\"tts.convert\", { text, provider: providerId });\n}\n\n/**\n * Upload an audio blob for STT transcription.\n * Returns raw fetch Response.\n */\nexport function transcribeAudio(sessionKey: string, providerId: string, audioBlob: Blob): Promise<Response> {\n\treturn fetch(\n\t\t`/api/sessions/${encodeURIComponent(sessionKey)}/upload?transcribe=true&provider=${encodeURIComponent(providerId)}`,\n\t\t{\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": audioBlob.type || \"audio/webm\" },\n\t\t\tbody: audioBlob,\n\t\t},\n\t);\n}\n\n/**\n * Decode a base64 (or base64url) string to a Uint8Array, tolerating\n * whitespace, URL-safe characters, and missing padding.\n */\nexport function decodeBase64Safe(input: string | null | undefined): Uint8Array {\n\tif (!input) return new Uint8Array();\n\tlet normalized = String(input).replace(/\\s+/g, \"\").replace(/-/g, \"+\").replace(/_/g, \"/\");\n\twhile (normalized.length % 4) normalized += \"=\";\n\tlet binary = \"\";\n\ttry {\n\t\tbinary = atob(normalized);\n\t} catch (_err) {\n\t\tthrow new Error(\"Invalid base64 audio payload\");\n\t}\n\tconst bytes = new Uint8Array(binary.length);\n\tfor (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);\n\treturn bytes;\n}\n","// ── Settings page (Preact + Signals) ───────────────────\n\nimport { signal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect, useRef, useState } from \"preact/hooks\";\nimport { EmojiPicker } from \"../emoji-picker\";\nimport { onEvent } from \"../events\";\nimport * as gon from \"../gon\";\nimport { refresh as refreshGon } from \"../gon\";\nimport { localizedApiErrorMessage, sendRpc } from \"../helpers\";\nimport { setLocale } from \"../i18n\";\nimport { updateIdentity, validateIdentityFields } from \"../identity-utils\";\nimport { initAgents, teardownAgents } from \"./AgentsPage\";\nimport { initChannels, teardownChannels } from \"./ChannelsPage\";\nimport { initCrons, teardownCrons } from \"./CronsPage\";\nimport { initHooks, teardownHooks } from \"./HooksPage\";\nimport { initImages, teardownImages } from \"./ImagesPage\";\nimport { initLogs, teardownLogs } from \"./LogsPage\";\nimport { initMcp, teardownMcp } from \"./McpPage\";\nimport { initMonitoring, teardownMonitoring } from \"./MetricsPage\";\nimport { initNetworkAudit, teardownNetworkAudit } from \"./NetworkAuditPage\";\nimport { initNodes, teardownNodes } from \"./NodesPage\";\nimport { initProjects, teardownProjects } from \"./ProjectsPage\";\nimport { initProviders, teardownProviders } from \"./ProvidersPage\";\nimport { initSkills, teardownSkills } from \"./SkillsPage\";\nimport { initTerminal, teardownTerminal } from \"./TerminalPage\";\nimport { initWebhooks, teardownWebhooks } from \"./WebhooksPage\";\nimport { detectPasskeyName } from \"../passkey-detect\";\nimport * as push from \"../push\";\nimport { isStandalone } from \"../pwa\";\nimport { navigate, registerPrefix } from \"../router\";\nimport { routes, settingsPath } from \"../routes\";\nimport { connected } from \"../signals\";\nimport * as S from \"../state\";\nimport { fetchPhrase } from \"../tts-phrases\";\nimport { Modal, showToast } from \"../ui\";\nimport {\n\tdecodeBase64Safe,\n\tfetchVoiceProviders,\n\tsaveVoiceKey,\n\tsaveVoiceSettings,\n\ttestTts,\n\ttoggleVoiceProvider,\n\ttranscribeAudio,\n} from \"../voice-utils\";\n\n// ── Types ───────────────────────────────────────────────────\n\ninterface IdentityData {\n\tname?: string;\n\temoji?: string;\n\ttheme?: string;\n\tuser_name?: string;\n\tsoul?: string;\n\t[key: string]: unknown;\n}\n\ninterface RpcResponse {\n\tok?: boolean;\n\tpayload?: unknown;\n\terror?: { message?: string };\n}\n\ninterface SectionItem {\n\tid?: string;\n\tlabel?: string;\n\ticon?: VNode;\n\tpage?: boolean;\n\tgroup?: string;\n}\n\ninterface EnvVar {\n\tid: string;\n\tkey: string;\n\tencrypted?: boolean;\n\tupdated_at?: string;\n}\n\ninterface PasskeyEntry {\n\tid: string;\n\tname: string;\n\tcreated_at?: string;\n}\n\ninterface ApiKeyEntry {\n\tid: string;\n\tlabel: string;\n\tkey_prefix?: string;\n\tcreated_at?: string;\n\tscopes?: string[];\n}\n\ninterface SshKeyEntry {\n\tid: number;\n\tname: string;\n\tfingerprint?: string;\n\tpublic_key?: string;\n\tencrypted?: boolean;\n\ttarget_count?: number;\n}\n\ninterface SshTargetEntry {\n\tid: number;\n\tlabel: string;\n\ttarget: string;\n\tport?: number;\n\tauth_mode?: string;\n\tkey_name?: string;\n\tknown_host?: string;\n\tis_default?: boolean;\n}\n\ninterface TestResult {\n\treachable?: boolean;\n\tfailure_hint?: string;\n}\n\ninterface ToolEntry {\n\tname?: string;\n\tdescription?: string;\n}\n\ninterface ToolGroup {\n\tlabel: string;\n\ttools: ToolEntry[];\n}\n\ninterface SkillEntry {\n\tname?: string;\n\tdescription?: string;\n\tsource?: string;\n}\n\ninterface McpServerEntry {\n\tname?: string;\n\tstate?: string;\n\ttool_count?: number;\n}\n\ninterface ToolsContextData {\n\tsession?: { model?: string; provider?: string; label?: string };\n\texecution?: { mode?: string; promptSymbol?: string };\n\tsandbox?: { enabled?: boolean; backend?: string };\n\ttools?: ToolEntry[];\n\tskills?: SkillEntry[];\n\tmcpServers?: McpServerEntry[];\n\tsupportsTools?: boolean;\n\tmcpDisabled?: boolean;\n}\n\ninterface NodeInventoryEntry {\n\tplatform?: string;\n\t[key: string]: unknown;\n}\n\ninterface RemoteExecSummary {\n\tpairedNodes: number;\n\tsshTargets: number;\n}\n\ninterface AkScopes {\n\t\"operator.read\": boolean;\n\t\"operator.write\": boolean;\n\t\"operator.approvals\": boolean;\n\t\"operator.pairing\": boolean;\n\t[key: string]: boolean;\n}\n\n// ── Module-level state ───────────────────────────────────────\n\nconst identity = signal<IdentityData | null>(null);\nconst loading = signal(true);\nconst activeSection = signal(\"identity\");\nconst activeSubPath = signal(\"\");\nconst mobileSidebarVisible = signal(true);\nlet mounted = false;\nlet containerRef: HTMLElement | null = null;\n\nfunction rerender(): void {\n\tif (containerRef) render(<SettingsPage />, containerRef);\n}\n\nfunction isMobileViewport(): boolean {\n\treturn window.innerWidth < 768;\n}\n\nfunction isSafariBrowser(): boolean {\n\tif (typeof navigator === \"undefined\") return false;\n\tconst ua = navigator.userAgent || \"\";\n\tconst vendor = navigator.vendor || \"\";\n\tif (!ua.includes(\"Safari/\")) return false;\n\tif (/(Chrome|CriOS|Chromium|Edg|OPR|FxiOS|Firefox|SamsungBrowser)/.test(ua)) return false;\n\treturn /Apple/i.test(vendor) || ua.includes(\"Safari/\");\n}\n\nfunction isMissingMethodError(res: RpcResponse | null): boolean {\n\tconst message = res?.error?.message;\n\tif (typeof message !== \"string\") return false;\n\tconst lower = message.toLowerCase();\n\treturn lower.includes(\"method\") && (lower.includes(\"not found\") || lower.includes(\"unknown\"));\n}\n\nfunction fetchMainIdentity(): Promise<RpcResponse> {\n\treturn sendRpc(\"agents.identity.get\", { agent_id: \"main\" }).then((res: RpcResponse) => {\n\t\tif (res?.ok || !isMissingMethodError(res)) return res;\n\t\treturn sendRpc(\"agent.identity.get\", {});\n\t});\n}\n\nfunction fetchIdentity(): void {\n\tif (!mounted) return;\n\tfetchMainIdentity().then((res: RpcResponse) => {\n\t\tif (res?.ok) {\n\t\t\tidentity.value = res.payload as IdentityData;\n\t\t\tloading.value = false;\n\t\t\trerender();\n\t\t} else if (mounted && !S.connected) {\n\t\t\tsetTimeout(fetchIdentity, 500);\n\t\t} else {\n\t\t\tloading.value = false;\n\t\t\trerender();\n\t\t}\n\t});\n}\n\n// ── Sidebar navigation items ─────────────────────────────────\n\nconst sections: SectionItem[] = [\n\t{ group: \"General\" },\n\t{\n\t\tid: \"identity\",\n\t\tlabel: \"Identity\",\n\t\ticon: <span className=\"icon icon-person\" />,\n\t},\n\t{\n\t\tid: \"agents\",\n\t\tlabel: \"Agents\",\n\t\ticon: <span className=\"icon icon-users\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"nodes\",\n\t\tlabel: \"Nodes\",\n\t\ticon: <span className=\"icon icon-nodes\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"projects\",\n\t\tlabel: \"Projects\",\n\t\ticon: <span className=\"icon icon-folder\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"environment\",\n\t\tlabel: \"Environment\",\n\t\ticon: <span className=\"icon icon-terminal\" />,\n\t},\n\t{\n\t\tid: \"memory\",\n\t\tlabel: \"Memory\",\n\t\ticon: <span className=\"icon icon-database\" />,\n\t},\n\t{\n\t\tid: \"notifications\",\n\t\tlabel: \"Notifications\",\n\t\ticon: <span className=\"icon icon-bell\" />,\n\t},\n\t{\n\t\tid: \"crons\",\n\t\tlabel: \"Crons\",\n\t\ticon: <span className=\"icon icon-cron\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"webhooks\",\n\t\tlabel: \"Webhooks\",\n\t\ticon: <span className=\"icon icon-webhooks\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"heartbeat\",\n\t\tlabel: \"Heartbeat\",\n\t\ticon: <span className=\"icon icon-heart\" />,\n\t\tpage: true,\n\t},\n\t{ group: \"Security\" },\n\t{\n\t\tid: \"security\",\n\t\tlabel: \"Authentication\",\n\t\ticon: <span className=\"icon icon-key\" />,\n\t},\n\t{\n\t\tid: \"vault\",\n\t\tlabel: \"Encryption\",\n\t\ticon: <span className=\"icon icon-lock\" />,\n\t},\n\t{\n\t\tid: \"ssh\",\n\t\tlabel: \"SSH\",\n\t\ticon: <span className=\"icon icon-ssh\" />,\n\t},\n\t{\n\t\tid: \"remote-access\",\n\t\tlabel: \"Remote Access\",\n\t\ticon: <span className=\"icon icon-share\" />,\n\t},\n\t{\n\t\tid: \"network-audit\",\n\t\tlabel: \"Network Audit\",\n\t\ticon: <span className=\"icon icon-shield-check\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"sandboxes\",\n\t\tlabel: \"Sandboxes\",\n\t\ticon: <span className=\"icon icon-cube\" />,\n\t\tpage: true,\n\t},\n\t{ group: \"Integrations\" },\n\t{\n\t\tid: \"channels\",\n\t\tlabel: \"Channels\",\n\t\ticon: <span className=\"icon icon-channels\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"hooks\",\n\t\tlabel: \"Hooks\",\n\t\ticon: <span className=\"icon icon-wrench\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"providers\",\n\t\tlabel: \"LLMs\",\n\t\ticon: <span className=\"icon icon-layers\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"tools\",\n\t\tlabel: \"Tools\",\n\t\ticon: <span className=\"icon icon-settings-gear\" />,\n\t},\n\t{\n\t\tid: \"mcp\",\n\t\tlabel: \"MCP\",\n\t\ticon: <span className=\"icon icon-link\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"skills\",\n\t\tlabel: \"Skills\",\n\t\ticon: <span className=\"icon icon-sparkles\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"import\",\n\t\tlabel: \"OpenClaw Import\",\n\t\ticon: <span className=\"icon icon-openclaw\" />,\n\t},\n\t{\n\t\tid: \"voice\",\n\t\tlabel: \"Voice\",\n\t\ticon: <span className=\"icon icon-microphone\" />,\n\t},\n\t{ group: \"Systems\" },\n\t{ id: \"terminal\", label: \"Terminal\", page: true },\n\t{ id: \"monitoring\", label: \"Monitoring\", page: true },\n\t{ id: \"logs\", label: \"Logs\", page: true },\n\t{ id: \"graphql\", label: \"GraphQL\" },\n\t{ id: \"config\", label: \"Configuration\" },\n];\n\nfunction getVisibleSections(): SectionItem[] {\n\tconst vs = gon.get(\"vault_status\");\n\treturn sections.filter((s) => {\n\t\tif (!s.id) return true;\n\t\tif (s.id === \"graphql\" && !gon.get(\"graphql_enabled\")) return false;\n\t\tif (s.id === \"import\" && !gon.get(\"openclaw_detected\")) return false;\n\t\tif (s.id === \"vault\" && (!vs || vs === \"disabled\")) return false;\n\t\treturn true;\n\t});\n}\n\n/** Return only items with an id (no group headings). */\nfunction getSectionItems(): SectionItem[] {\n\treturn getVisibleSections().filter((s) => s.id);\n}\n\nfunction pluralizeToolsCount(count: number, noun: string): string {\n\treturn `${count} ${noun}${count === 1 ? \"\" : \"s\"}`;\n}\n\nfunction toolsOverviewCategory(name: string | undefined): string {\n\tif (typeof name !== \"string\" || !name) return \"Core\";\n\tif (name.startsWith(\"mcp__\")) return \"MCP\";\n\tif (name === \"exec\" || name.startsWith(\"node\") || name.startsWith(\"sandbox\") || name.includes(\"checkpoint\")) {\n\t\treturn \"Execution\";\n\t}\n\tif (name.startsWith(\"session\") || name.startsWith(\"sessions_\")) return \"Sessions\";\n\tif (name.startsWith(\"memory\") || name.includes(\"memory\")) return \"Memory\";\n\tif (name.startsWith(\"browser\") || name.startsWith(\"web_\") || name.includes(\"screenshot\") || name.includes(\"fetch\")) {\n\t\treturn \"Web & Browser\";\n\t}\n\tif (name.startsWith(\"skill\") || name.includes(\"skill\")) return \"Skills\";\n\treturn \"Core\";\n}\n\nfunction groupToolsForOverview(tools: ToolEntry[]): ToolGroup[] {\n\tconst grouped = new Map<string, ToolEntry[]>();\n\t(tools || []).forEach((tool) => {\n\t\tconst category = toolsOverviewCategory(tool?.name);\n\t\tif (!grouped.has(category)) grouped.set(category, []);\n\t\tgrouped.get(category)!.push(tool);\n\t});\n\tconst order = [\"Execution\", \"Sessions\", \"Memory\", \"Web & Browser\", \"Skills\", \"MCP\", \"Core\"];\n\treturn order\n\t\t.filter((label) => grouped.has(label))\n\t\t.map((label) => ({\n\t\t\tlabel,\n\t\t\ttools: grouped\n\t\t\t\t.get(label)!\n\t\t\t\t.slice()\n\t\t\t\t.sort((left, right) => String(left?.name || \"\").localeCompare(String(right?.name || \"\"))),\n\t\t}));\n}\n\nfunction summarizeRemoteExecInventory(entries: NodeInventoryEntry[]): RemoteExecSummary {\n\tconst summary: RemoteExecSummary = { pairedNodes: 0, sshTargets: 0 };\n\t(entries || []).forEach((entry) => {\n\t\tif (!entry || typeof entry !== \"object\") return;\n\t\tif (entry.platform === \"ssh\") {\n\t\t\tsummary.sshTargets += 1;\n\t\t\treturn;\n\t\t}\n\t\tsummary.pairedNodes += 1;\n\t});\n\treturn summary;\n}\n\nfunction SettingsSidebar(): VNode {\n\treturn (\n\t\t<div className=\"settings-sidebar\">\n\t\t\t<div className=\"settings-sidebar-header\">\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"settings-back-slot\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tnavigate(routes.chats as string);\n\t\t\t\t\t}}\n\t\t\t\t\ttitle=\"Back to chat sessions\"\n\t\t\t\t>\n\t\t\t\t\t<span className=\"icon icon-chat\" />\n\t\t\t\t\tBack to Chats\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<div className=\"settings-sidebar-nav\">\n\t\t\t\t{getVisibleSections().map((s) =>\n\t\t\t\t\ts.group\n\t\t\t\t\t\t? <div key={s.group} className=\"settings-group-label\">\n\t\t\t\t\t\t\t{s.group}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t: <button\n\t\t\t\t\t\t\tkey={s.id}\n\t\t\t\t\t\t\tclassName={`settings-nav-item ${activeSection.value === s.id ? \"active\" : \"\"}`}\n\t\t\t\t\t\t\tdata-section={s.id}\n\t\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\t\tif (isMobileViewport()) {\n\t\t\t\t\t\t\t\t\tmobileSidebarVisible.value = false;\n\t\t\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\tnavigate(settingsPath(s.id!));\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t{s.label}\n\t\t\t\t\t\t</button>,\n\t\t\t\t)}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// EmojiPicker imported from emoji-picker.ts\n\n// ── Soul defaults ────────────────────────────────────────────\n\nconst DEFAULT_SOUL =\n\t\"Be genuinely helpful, not performatively helpful. Skip the filler words \\u2014 just help.\\n\" +\n\t\"Have opinions. You're allowed to disagree, prefer things, find stuff amusing or boring.\\n\" +\n\t\"Be resourceful before asking. Try to figure it out first \\u2014 read the context, search for it \\u2014 then ask if you're stuck.\\n\" +\n\t\"Earn trust through competence. Be careful with external actions. Be bold with internal ones.\\n\" +\n\t\"Remember you're a guest. You have access to someone's life. Treat it with respect.\\n\" +\n\t\"Private things stay private. When in doubt, ask before acting externally.\\n\" +\n\t\"Be concise when needed, thorough when it matters. Not a corporate drone. Not a sycophant. Just good.\";\n\n// ── Identity section (editable form) ─────────────────────────\n\nfunction IdentitySection(): VNode {\n\tconst id = identity.value;\n\tconst isNew = !(id && (id.name || id.user_name));\n\tconst storedLocale = localStorage.getItem(\"moltis-locale\");\n\n\tconst [name, setName] = useState(id?.name || \"\");\n\tconst [emoji, setEmoji] = useState(id?.emoji || \"\");\n\tconst [theme, setTheme] = useState(id?.theme || \"\");\n\tconst [userName, setUserName] = useState(id?.user_name || \"\");\n\tconst [soul, setSoul] = useState(id?.soul || \"\");\n\tconst [uiLanguage, setUiLanguage] = useState(storedLocale || \"auto\");\n\tconst [saving, setSaving] = useState(false);\n\tconst [emojiSaving, setEmojiSaving] = useState(false);\n\tconst [nameSaving, setNameSaving] = useState(false);\n\tconst [userNameSaving, setUserNameSaving] = useState(false);\n\tconst [languageSaving, setLanguageSaving] = useState(false);\n\tconst [saved, setSaved] = useState(false);\n\tconst [languageSaved, setLanguageSaved] = useState(false);\n\tconst [showFaviconReloadHint, setShowFaviconReloadHint] = useState(false);\n\tconst [error, setError] = useState<string | null>(null);\n\tconst [languageError, setLanguageError] = useState<string | null>(null);\n\n\t// Sync state when identity loads asynchronously\n\tuseEffect(() => {\n\t\tif (!id) return;\n\t\tsetName(id.name || \"\");\n\t\tsetEmoji(id.emoji || \"\");\n\t\tsetTheme(id.theme || \"\");\n\t\tsetUserName(id.user_name || \"\");\n\t\tsetSoul(id.soul || \"\");\n\t}, [id]);\n\n\tconst savedTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);\n\tfunction flashSaved(): void {\n\t\tif (savedTimerRef.current) clearTimeout(savedTimerRef.current);\n\t\tsetSaved(true);\n\t\tsavedTimerRef.current = setTimeout(() => {\n\t\t\tsavedTimerRef.current = null;\n\t\t\tsetSaved(false);\n\t\t\trerender();\n\t\t}, 2000);\n\t}\n\n\tif (loading.value) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Loading{\"\\u2026\"}</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\tfunction onSave(e: Event): void {\n\t\te.preventDefault();\n\t\tconst v = validateIdentityFields(name, userName);\n\t\tif (!v.valid) {\n\t\t\tsetError(v.error);\n\t\t\treturn;\n\t\t}\n\t\tsetError(null);\n\t\tsetSaving(true);\n\t\tsetSaved(false);\n\n\t\tupdateIdentity(\n\t\t\t{\n\t\t\t\tname: name.trim(),\n\t\t\t\temoji: emoji.trim() || \"\",\n\t\t\t\ttheme: theme.trim() || \"\",\n\t\t\t\tsoul: soul.trim() || undefined,\n\t\t\t\tuser_name: userName.trim(),\n\t\t\t},\n\t\t\t{ agentId: \"main\" },\n\t\t).then((res: RpcResponse) => {\n\t\t\tsetSaving(false);\n\t\t\tif (res?.ok) {\n\t\t\t\tconst payload = res.payload as IdentityData;\n\t\t\t\tidentity.value = payload;\n\t\t\t\tgon.set(\"identity\", payload as import(\"../types/gon\").ResolvedIdentity);\n\t\t\t\trefreshGon();\n\t\t\t\tconst emojiChanged = (emoji.trim() || \"\") !== (id?.emoji || \"\").trim();\n\t\t\t\tsetShowFaviconReloadHint(emojiChanged && isSafariBrowser());\n\t\t\t\tflashSaved();\n\t\t\t} else {\n\t\t\t\tsetError(res?.error?.message || \"Failed to save\");\n\t\t\t}\n\t\t\trerender();\n\t\t});\n\t}\n\n\tfunction onEmojiSelect(nextEmoji: string): void {\n\t\tsetEmoji(nextEmoji);\n\t\tsetError(null);\n\t\tsetSaved(false);\n\t\tsetEmojiSaving(true);\n\t\tupdateIdentity({ emoji: nextEmoji.trim() || \"\" }, { agentId: \"main\" }).then((res: RpcResponse) => {\n\t\t\tsetEmojiSaving(false);\n\t\t\tif (res?.ok) {\n\t\t\t\tconst payload = res.payload as IdentityData;\n\t\t\t\tidentity.value = payload;\n\t\t\t\tsetEmoji(payload?.emoji || \"\");\n\t\t\t\tgon.set(\"identity\", payload as import(\"../types/gon\").ResolvedIdentity);\n\t\t\t\trefreshGon();\n\t\t\t\tconst emojiChanged = (nextEmoji.trim() || \"\") !== (id?.emoji || \"\").trim();\n\t\t\t\tsetShowFaviconReloadHint(emojiChanged && isSafariBrowser());\n\t\t\t\tflashSaved();\n\t\t\t} else {\n\t\t\t\tsetError(res?.error?.message || \"Failed to save emoji\");\n\t\t\t}\n\t\t\trerender();\n\t\t});\n\t}\n\n\tfunction autoSaveNameField(field: string, value: string): void {\n\t\tif (saving || emojiSaving || nameSaving || userNameSaving) return;\n\t\tconst trimmed = value.trim();\n\t\tconst currentValue = (identity.value?.[field] as string || \"\").trim();\n\t\tif (trimmed === currentValue) return;\n\n\t\tif (!trimmed) {\n\t\t\tsetError(field === \"name\" ? \"Agent name is required.\" : \"Your name is required.\");\n\t\t\treturn;\n\t\t}\n\n\t\tsetError(null);\n\t\tsetSaved(false);\n\t\tif (field === \"name\") {\n\t\t\tsetNameSaving(true);\n\t\t} else {\n\t\t\tsetUserNameSaving(true);\n\t\t}\n\n\t\tconst payload: Record<string, string> = {};\n\t\tpayload[field] = trimmed;\n\t\tupdateIdentity(payload, { agentId: \"main\" }).then((res: RpcResponse) => {\n\t\t\tif (field === \"name\") {\n\t\t\t\tsetNameSaving(false);\n\t\t\t} else {\n\t\t\t\tsetUserNameSaving(false);\n\t\t\t}\n\n\t\t\tif (res?.ok) {\n\t\t\t\tconst resPayload = res.payload as IdentityData;\n\t\t\t\tidentity.value = resPayload;\n\t\t\t\tgon.set(\"identity\", resPayload as import(\"../types/gon\").ResolvedIdentity);\n\t\t\t\trefreshGon();\n\t\t\t\tsetName(resPayload?.name || \"\");\n\t\t\t\tsetUserName(resPayload?.user_name || \"\");\n\t\t\t\tflashSaved();\n\t\t\t} else {\n\t\t\t\tsetError(res?.error?.message || \"Failed to save\");\n\t\t\t}\n\t\t\trerender();\n\t\t});\n\t}\n\n\tfunction onNameBlur(e: Event): void {\n\t\tautoSaveNameField(\"name\", (e.target as HTMLInputElement).value);\n\t}\n\n\tfunction onUserNameBlur(e: Event): void {\n\t\tautoSaveNameField(\"user_name\", (e.target as HTMLInputElement).value);\n\t}\n\n\tfunction onResetSoul(): void {\n\t\tsetSoul(\"\");\n\t\trerender();\n\t}\n\n\tfunction onReloadForFavicon(): void {\n\t\twindow.location.reload();\n\t}\n\n\tfunction onApplyLanguage(): void {\n\t\tsetLanguageSaving(true);\n\t\tsetLanguageSaved(false);\n\t\tsetLanguageError(null);\n\n\t\tconst nextLanguage = uiLanguage === \"auto\" ? navigator.language || \"en\" : uiLanguage;\n\t\tsetLocale(nextLanguage)\n\t\t\t.then(() => {\n\t\t\t\tif (uiLanguage === \"auto\") {\n\t\t\t\t\tlocalStorage.removeItem(\"moltis-locale\");\n\t\t\t\t}\n\t\t\t\tsetLanguageSaving(false);\n\t\t\t\tsetLanguageSaved(true);\n\t\t\t\tsetTimeout(() => {\n\t\t\t\t\tsetLanguageSaved(false);\n\t\t\t\t\trerender();\n\t\t\t\t}, 2000);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((err: Error) => {\n\t\t\t\tsetLanguageSaving(false);\n\t\t\t\tsetLanguageError(err?.message || \"Failed to update language\");\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Identity</h2>\n\t\t\t{isNew\n\t\t\t\t? <p className=\"text-xs text-[var(--muted)] leading-relaxed\" style={{ maxWidth: \"600px\", margin: 0 }}>\n\t\t\t\t\tWelcome! Set up your agent's identity to get started.\n\t\t\t\t</p>\n\t\t\t\t: null\n\t\t\t}\n\t\t\t<form onSubmit={onSave} style={{ maxWidth: \"600px\", display: \"flex\", flexDirection: \"column\", gap: \"16px\" }}>\n\t\t\t\t{/* Agent section */}\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>Agent</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>Saved to <code>IDENTITY.md</code> in your workspace root.</p>\n\t\t\t\t\t<div style={{ display: \"grid\", gridTemplateColumns: \"1fr 1fr\", gap: \"8px 16px\" }}>\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>Name *</div>\n\t\t\t\t\t\t\t<input type=\"text\" className=\"provider-key-input\" style={{ width: \"100%\" }}\n\t\t\t\t\t\t\t\tvalue={name} onInput={(e: Event) => setName((e.target as HTMLInputElement).value)} onBlur={onNameBlur}\n\t\t\t\t\t\t\t\tplaceholder=\"e.g. Rex\" />\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>Emoji</div>\n\t\t\t\t\t\t\t<EmojiPicker value={emoji} onChange={setEmoji} onSelect={onEmojiSelect} />\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div style={{ gridColumn: \"1/-1\" }}>\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>Theme</div>\n\t\t\t\t\t\t\t<input type=\"text\" className=\"provider-key-input\" style={{ width: \"100%\" }}\n\t\t\t\t\t\t\t\tvalue={theme} onInput={(e: Event) => setTheme((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\tplaceholder=\"e.g. wise owl, chill fox\" />\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t\t{showFaviconReloadHint\n\t\t\t\t\t\t? <div className=\"mt-3 rounded border border-[var(--border)] bg-[var(--surface2)] p-2 text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\tfavicon updates requires reload and may be cached for minutes, <button type=\"button\" className=\"cursor-pointer bg-transparent p-0 text-xs text-[var(--text)] underline\" onClick={onReloadForFavicon}>requires reload</button>.\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t: null\n\t\t\t\t\t}\n\t\t\t\t</div>\n\n\t\t\t\t{/* User section */}\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>User</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>\n\t\t\t\t\t\tSaved to your user profile. Depending on memory settings, Moltis may also mirror it to <code>USER.md</code>.\n\t\t\t\t\t</p>\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>Your name *</div>\n\t\t\t\t\t\t<input type=\"text\" className=\"provider-key-input\" style={{ width: \"100%\", maxWidth: \"280px\" }}\n\t\t\t\t\t\t\tvalue={userName} onInput={(e: Event) => setUserName((e.target as HTMLInputElement).value)} onBlur={onUserNameBlur}\n\t\t\t\t\t\t\tplaceholder=\"e.g. Alice\" />\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\n\t\t\t\t{/* Language section */}\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>Language</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>Choose the UI language for this browser.</p>\n\t\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\", flexWrap: \"wrap\" }}>\n\t\t\t\t\t\t<label htmlFor=\"identityLanguageSelect\" className=\"text-xs text-[var(--muted)]\">UI language</label>\n\t\t\t\t\t\t<select\n\t\t\t\t\t\t\tid=\"identityLanguageSelect\"\n\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\tstyle={{ maxWidth: \"220px\" }}\n\t\t\t\t\t\t\tvalue={uiLanguage}\n\t\t\t\t\t\t\tonChange={(e: Event) => {\n\t\t\t\t\t\t\t\tsetUiLanguage((e.target as HTMLSelectElement).value);\n\t\t\t\t\t\t\t\tsetLanguageSaved(false);\n\t\t\t\t\t\t\t\tsetLanguageError(null);\n\t\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t<option value=\"auto\">Browser default</option>\n\t\t\t\t\t\t\t<option value=\"en\">English</option>\n\t\t\t\t\t\t\t<option value=\"fr\">French</option>\n\t\t\t\t\t\t\t<option value=\"zh\">{\"\\u7B80\\u4F53\\u4E2D\\u6587\"}</option>\n\t\t\t\t\t\t</select>\n\t\t\t\t\t\t<button\n\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\tid=\"identityLanguageApplyBtn\"\n\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\t\t\tdisabled={languageSaving}\n\t\t\t\t\t\t\tonClick={onApplyLanguage}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t{languageSaving ? \"Applying...\" : \"Apply language\"}\n\t\t\t\t\t\t</button>\n\t\t\t\t\t\t{languageSaved ? <span className=\"text-xs\" style={{ color: \"var(--accent)\" }}>Language updated</span> : null}\n\t\t\t\t\t\t{languageError ? <span className=\"text-xs\" style={{ color: \"var(--error)\" }}>{languageError}</span> : null}\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\n\t\t\t\t{/* Soul section */}\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"4px\" }}>Soul</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>Personality and tone injected into every conversation. Saved to <code>SOUL.md</code> in your workspace root. Leave empty for the default.</p>\n\t\t\t\t\t<textarea\n\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\trows={8}\n\t\t\t\t\t\tstyle={{ width: \"100%\", minHeight: \"8rem\", resize: \"vertical\", fontSize: \".8rem\", lineHeight: 1.5 }}\n\t\t\t\t\t\tplaceholder={DEFAULT_SOUL}\n\t\t\t\t\t\tvalue={soul}\n\t\t\t\t\t\tonInput={(e: Event) => setSoul((e.target as HTMLTextAreaElement).value)}\n\t\t\t\t\t/>\n\t\t\t\t\t{soul\n\t\t\t\t\t\t? <button type=\"button\" className=\"provider-btn\" style={{ marginTop: \"6px\", fontSize: \".75rem\" }}\n\t\t\t\t\t\t\tonClick={onResetSoul}>Reset to default</button>\n\t\t\t\t\t\t: null\n\t\t\t\t\t}\n\t\t\t\t</div>\n\n\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\" }}>\n\t\t\t\t\t<button type=\"submit\" className=\"provider-btn\" disabled={saving || emojiSaving || nameSaving || userNameSaving}>\n\t\t\t\t\t\t{saving || emojiSaving || nameSaving || userNameSaving ? \"Saving\\u2026\" : \"Save\"}\n\t\t\t\t\t</button>\n\t\t\t\t\t{saved ? <span className=\"text-xs\" style={{ color: \"var(--accent)\" }}>Saved</span> : null}\n\t\t\t\t\t{error ? <span className=\"text-xs\" style={{ color: \"var(--error)\" }}>{error}</span> : null}\n\t\t\t\t</div>\n\t\t\t</form>\n\t\t\t{gon.get(\"version\") ? <p className=\"text-xs text-[var(--muted)]\" style={{ marginTop: \"auto\", paddingTop: \"16px\" }}>v{gon.get(\"version\")}</p> : null}\n\t\t</div>\n\t);\n}\n\n// ── Environment section ──────────────────────────────────────\n\nfunction EnvironmentSection(): VNode {\n\tconst [envVars, setEnvVars] = useState<EnvVar[]>([]);\n\tconst [envLoading, setEnvLoading] = useState(true);\n\tconst [newKey, setNewKey] = useState(\"\");\n\tconst [newValue, setNewValue] = useState(\"\");\n\tconst [envMsg, setEnvMsg] = useState<string | null>(null);\n\tconst [envErr, setEnvErr] = useState<string | null>(null);\n\tconst [saving, setSaving] = useState(false);\n\tconst [updateId, setUpdateId] = useState<string | null>(null);\n\tconst [updateValue, setUpdateValue] = useState(\"\");\n\n\tfunction fetchEnvVars(): void {\n\t\tfetch(\"/api/env\")\n\t\t\t.then((r) => (r.ok ? r.json() : { env_vars: [] }))\n\t\t\t.then((d: { env_vars?: EnvVar[] }) => {\n\t\t\t\tsetEnvVars(d.env_vars || []);\n\t\t\t\tsetEnvLoading(false);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch(() => {\n\t\t\t\tsetEnvLoading(false);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tuseEffect(() => {\n\t\tfetchEnvVars();\n\t}, []);\n\n\tfunction onAdd(e: Event): void {\n\t\te.preventDefault();\n\t\tsetEnvErr(null);\n\t\tsetEnvMsg(null);\n\t\tconst key = newKey.trim();\n\t\tif (!key) {\n\t\t\tsetEnvErr(\"Key is required.\");\n\t\t\trerender();\n\t\t\treturn;\n\t\t}\n\t\tif (!/^[A-Za-z0-9_]+$/.test(key)) {\n\t\t\tsetEnvErr(\"Key must contain only letters, digits, and underscores.\");\n\t\t\trerender();\n\t\t\treturn;\n\t\t}\n\t\tsetSaving(true);\n\t\trerender();\n\t\tfetch(\"/api/env\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ key, value: newValue }),\n\t\t})\n\t\t\t.then((r) => {\n\t\t\t\tif (r.ok) {\n\t\t\t\t\tsetNewKey(\"\");\n\t\t\t\t\tsetNewValue(\"\");\n\t\t\t\t\tsetEnvMsg(\"Variable saved.\");\n\t\t\t\t\tsetTimeout(() => {\n\t\t\t\t\t\tsetEnvMsg(null);\n\t\t\t\t\t\trerender();\n\t\t\t\t\t}, 2000);\n\t\t\t\t\tfetchEnvVars();\n\t\t\t\t} else {\n\t\t\t\t\treturn r.json().then((d: unknown) => setEnvErr(localizedApiErrorMessage(d as Parameters<typeof localizedApiErrorMessage>[0], \"Failed to save\")));\n\t\t\t\t}\n\t\t\t\tsetSaving(false);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((err: Error) => {\n\t\t\t\tsetEnvErr(err.message);\n\t\t\t\tsetSaving(false);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onDelete(id: string): void {\n\t\tfetch(`/api/env/${id}`, { method: \"DELETE\" }).then(() => fetchEnvVars());\n\t}\n\n\tfunction onStartUpdate(id: string): void {\n\t\tsetUpdateId(id);\n\t\tsetUpdateValue(\"\");\n\t\trerender();\n\t}\n\n\tfunction onCancelUpdate(): void {\n\t\tsetUpdateId(null);\n\t\tsetUpdateValue(\"\");\n\t\trerender();\n\t}\n\n\tfunction onConfirmUpdate(key: string): void {\n\t\tfetch(\"/api/env\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ key, value: updateValue }),\n\t\t}).then((r) => {\n\t\t\tif (r.ok) {\n\t\t\t\tsetUpdateId(null);\n\t\t\t\tsetUpdateValue(\"\");\n\t\t\t\tfetchEnvVars();\n\t\t\t}\n\t\t});\n\t}\n\n\tconst envVaultStatus = gon.get(\"vault_status\");\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Environment Variables</h2>\n\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed\" style={{ maxWidth: \"600px\", margin: 0 }}>\n\t\t\t\tEnvironment variables are injected into sandbox command execution. Values are write-only and never displayed.\n\t\t\t</p>\n\t\t\t{envVaultStatus && envVaultStatus !== \"disabled\"\n\t\t\t\t? <div className=\"text-xs\" style={{ maxWidth: \"600px\", padding: \"8px 12px\", borderRadius: \"6px\", border: \"1px solid var(--border)\", background: \"var(--bg)\" }}>\n\t\t\t\t\t{envVaultStatus === \"unsealed\"\n\t\t\t\t\t\t? <><span style={{ color: \"var(--accent)\" }}>Vault unlocked.</span> Your keys are stored encrypted.</>\n\t\t\t\t\t\t: envVaultStatus === \"sealed\"\n\t\t\t\t\t\t\t? <><span style={{ color: \"var(--warning,var(--error))\" }}>Vault locked.</span> Encrypted keys can{\"\\u2019\"}t be read {\"\\u2014\"} sandbox commands won{\"\\u2019\"}t work. <a href=\"/settings/vault\" style={{ color: \"inherit\", textDecoration: \"underline\" }}>Unlock in Encryption settings.</a></>\n\t\t\t\t\t\t\t: <><span className=\"text-[var(--muted)]\">Vault not set up.</span> <a href=\"/settings/security\" style={{ color: \"inherit\", textDecoration: \"underline\" }}>Set a password</a> to encrypt your stored keys.</>\n\t\t\t\t\t}\n\t\t\t\t</div>\n\t\t\t\t: null\n\t\t\t}\n\n\t\t\t{envLoading\n\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\">Loading{\"\\u2026\"}</div>\n\t\t\t\t: <>\n\t\t\t\t\t{/* Existing variables */}\n\t\t\t\t\t<div style={{ maxWidth: \"600px\" }}>\n\t\t\t\t\t\t{envVars.length > 0\n\t\t\t\t\t\t\t? <div style={{ display: \"flex\", flexDirection: \"column\", gap: \"6px\", marginBottom: \"12px\" }}>\n\t\t\t\t\t\t\t\t{envVars.map((v) => (\n\t\t\t\t\t\t\t\t\t<div className=\"provider-item\" style={{ marginBottom: 0 }} key={v.id}>\n\t\t\t\t\t\t\t\t\t\t{updateId === v.id\n\t\t\t\t\t\t\t\t\t\t\t? <form style={{ display: \"flex\", alignItems: \"center\", gap: \"6px\", flex: 1 }} onSubmit={(e: Event) => {\n\t\t\t\t\t\t\t\t\t\t\t\te.preventDefault();\n\t\t\t\t\t\t\t\t\t\t\t\tonConfirmUpdate(v.key);\n\t\t\t\t\t\t\t\t\t\t\t}}>\n\t\t\t\t\t\t\t\t\t\t\t\t<code style={{ fontSize: \"0.8rem\", fontFamily: \"var(--font-mono)\" }}>{v.key}</code>\n\t\t\t\t\t\t\t\t\t\t\t\t{v.encrypted\n\t\t\t\t\t\t\t\t\t\t\t\t\t? <span className=\"provider-item-badge configured\">Encrypted</span>\n\t\t\t\t\t\t\t\t\t\t\t\t\t: <span className=\"provider-item-badge muted\">Plaintext</span>\n\t\t\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\t\t\t\t<input type=\"password\" className=\"provider-key-input\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tname=\"env_update_value\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tautoComplete=\"new-password\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tautoCapitalize=\"off\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tspellcheck={false}\n\t\t\t\t\t\t\t\t\t\t\t\t\tvalue={updateValue}\n\t\t\t\t\t\t\t\t\t\t\t\t\tonInput={(e: Event) => setUpdateValue((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\t\t\t\t\t\tplaceholder=\"New value\" style={{ flex: 1 }} autoFocus />\n\t\t\t\t\t\t\t\t\t\t\t\t<button type=\"submit\" className=\"provider-btn\">Save</button>\n\t\t\t\t\t\t\t\t\t\t\t\t<button type=\"button\" className=\"provider-btn\" onClick={onCancelUpdate}>Cancel</button>\n\t\t\t\t\t\t\t\t\t\t\t</form>\n\t\t\t\t\t\t\t\t\t\t\t: <><div style={{ flex: 1, minWidth: 0 }}>\n\t\t\t\t\t\t\t\t\t\t\t\t<div className=\"provider-item-name\" style={{ fontFamily: \"var(--font-mono)\", fontSize: \".8rem\" }}>\n\t\t\t\t\t\t\t\t\t\t\t\t\t{v.key}\n\t\t\t\t\t\t\t\t\t\t\t\t\t{v.encrypted\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t? <span className=\"provider-item-badge configured\" style={{ marginLeft: \"6px\" }}>Encrypted</span>\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t: <span className=\"provider-item-badge muted\" style={{ marginLeft: \"6px\" }}>Plaintext</span>\n\t\t\t\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t\t<div style={{ fontSize: \".7rem\", color: \"var(--muted)\", marginTop: \"2px\", display: \"flex\", gap: \"12px\" }}>\n\t\t\t\t\t\t\t\t\t\t\t\t\t<span>{\"\\u2022\\u2022\\u2022\\u2022\\u2022\\u2022\\u2022\\u2022\"}</span>\n\t\t\t\t\t\t\t\t\t\t\t\t\t<time dateTime={v.updated_at}>{v.updated_at}</time>\n\t\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t<div style={{ display: \"flex\", gap: \"4px\" }}>\n\t\t\t\t\t\t\t\t\t\t\t\t<button className=\"provider-btn provider-btn-sm\" onClick={() => onStartUpdate(v.id)}>Update</button>\n\t\t\t\t\t\t\t\t\t\t\t\t<button className=\"provider-btn provider-btn-sm provider-btn-danger\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tonClick={() => onDelete(v.id)}>Delete</button>\n\t\t\t\t\t\t\t\t\t\t\t</div></>\n\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t))}\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: <div className=\"text-xs text-[var(--muted)]\" style={{ padding: \"12px 0\" }}>No environment variables set.</div>\n\t\t\t\t\t\t}\n\t\t\t\t\t</div>\n\n\t\t\t\t\t{/* Add variable */}\n\t\t\t\t\t<div style={{ maxWidth: \"600px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>Add Variable</h3>\n\t\t\t\t\t\t<form onSubmit={onAdd}>\n\t\t\t\t\t\t\t<div style={{ display: \"flex\", gap: \"8px\", flexWrap: \"wrap\" }}>\n\t\t\t\t\t\t\t\t<input type=\"text\" className=\"provider-key-input\"\n\t\t\t\t\t\t\t\t\tname=\"env_key\"\n\t\t\t\t\t\t\t\t\tautoComplete=\"off\"\n\t\t\t\t\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\t\t\t\t\tautoCapitalize=\"off\"\n\t\t\t\t\t\t\t\t\tspellcheck={false}\n\t\t\t\t\t\t\t\t\tvalue={newKey}\n\t\t\t\t\t\t\t\t\tonInput={(e: Event) => setNewKey((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\t\tplaceholder=\"KEY_NAME\" style={{ flex: 1, minWidth: \"120px\", fontFamily: \"var(--font-mono)\", fontSize: \".8rem\" }} />\n\t\t\t\t\t\t\t\t<input type=\"password\" className=\"provider-key-input\"\n\t\t\t\t\t\t\t\t\tname=\"env_value\"\n\t\t\t\t\t\t\t\t\tautoComplete=\"new-password\"\n\t\t\t\t\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\t\t\t\t\tautoCapitalize=\"off\"\n\t\t\t\t\t\t\t\t\tspellcheck={false}\n\t\t\t\t\t\t\t\t\tvalue={newValue}\n\t\t\t\t\t\t\t\t\tonInput={(e: Event) => setNewValue((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\t\tplaceholder=\"Value\" style={{ flex: 2, minWidth: \"200px\" }} />\n\t\t\t\t\t\t\t\t<button type=\"submit\" className=\"provider-btn\" disabled={saving || !newKey.trim()}>\n\t\t\t\t\t\t\t\t\t{saving ? \"Saving\\u2026\" : \"Add\"}\n\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t{envMsg ? <div className=\"text-xs\" style={{ marginTop: \"6px\", color: \"var(--accent)\" }}>{envMsg}</div> : null}\n\t\t\t\t\t\t\t{envErr ? <div className=\"text-xs\" style={{ marginTop: \"6px\", color: \"var(--error)\" }}>{envErr}</div> : null}\n\t\t\t\t\t\t</form>\n\t\t\t\t\t</div>\n\t\t\t\t</>\n\t\t\t}\n\t\t</div>\n\t);\n}\n\n// ── Security section ─────────────────────────────────────────\n\n// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Large component managing auth, passwords, passkeys, and API keys\nfunction SecuritySection(): VNode {\n\tconst [authDisabled, setAuthDisabled] = useState(false);\n\tconst [localhostOnly, setLocalhostOnly] = useState(false);\n\tconst [hasPassword, setHasPassword] = useState(true);\n\tconst [hasPasskeys, setHasPasskeys] = useState(false);\n\tconst [setupComplete, setSetupComplete] = useState(false);\n\tconst [authLoading, setAuthLoading] = useState(true);\n\n\tconst [curPw, setCurPw] = useState(\"\");\n\tconst [newPw, setNewPw] = useState(\"\");\n\tconst [confirmPw, setConfirmPw] = useState(\"\");\n\tconst [pwMsg, setPwMsg] = useState<string | null>(null);\n\tconst [pwErr, setPwErr] = useState<string | null>(null);\n\tconst [pwSaving, setPwSaving] = useState(false);\n\tconst [pwAwaitingReauth, setPwAwaitingReauth] = useState(false);\n\tconst [pwRecoveryKey, setPwRecoveryKey] = useState<string | null>(null);\n\tconst [pwRecoveryCopied, setPwRecoveryCopied] = useState(false);\n\n\tconst [passkeys, setPasskeys] = useState<PasskeyEntry[]>([]);\n\tconst [pkName, setPkName] = useState(\"\");\n\tconst [pkMsg, setPkMsg] = useState<string | null>(null);\n\tconst [pkLoading, setPkLoading] = useState(true);\n\tconst [editingPk, setEditingPk] = useState<string | null>(null);\n\tconst [editingPkName, setEditingPkName] = useState(\"\");\n\tconst [passkeyOrigins, setPasskeyOrigins] = useState<string[]>([]);\n\tconst [passkeyHostUpdateHosts, setPasskeyHostUpdateHosts] = useState<string[]>([]);\n\n\tconst [apiKeys, setApiKeys] = useState<ApiKeyEntry[]>([]);\n\tconst [akLabel, setAkLabel] = useState(\"\");\n\tconst [akNew, setAkNew] = useState<string | null>(null);\n\tconst [akLoading, setAkLoading] = useState(true);\n\tconst [akFullAccess, setAkFullAccess] = useState(true);\n\tconst [akScopes, setAkScopes] = useState<AkScopes>({\n\t\t\"operator.read\": false,\n\t\t\"operator.write\": false,\n\t\t\"operator.approvals\": false,\n\t\t\"operator.pairing\": false,\n\t});\n\n\tfunction notifyAuthStatusChanged(): void {\n\t\twindow.dispatchEvent(new CustomEvent(\"moltis:auth-status-changed\"));\n\t}\n\n\tfunction deferNextPasswordChangedRedirect(): void {\n\t\t(window as unknown as Record<string, boolean>).__moltisSuppressNextPasswordChangedRedirect = true;\n\t}\n\n\tfunction clearPasswordChangedRedirectDeferral(): void {\n\t\t(window as unknown as Record<string, boolean>).__moltisSuppressNextPasswordChangedRedirect = false;\n\t}\n\n\t// A credential added while localhost-bypass is active can immediately make the\n\t// current session unauthenticated (no session cookie). Reload so middleware\n\t// can route to /login in that transition.\n\tfunction refreshPasskeyHostStatus(): Promise<void> {\n\t\treturn fetch(\"/api/auth/status\")\n\t\t\t.then((r) => (r.ok ? r.json() : null))\n\t\t\t.then((status: { passkey_host_update_hosts?: string[]; passkey_origins?: string[] } | null) => {\n\t\t\t\tif (Array.isArray(status?.passkey_host_update_hosts))\n\t\t\t\t\tsetPasskeyHostUpdateHosts(status!.passkey_host_update_hosts);\n\t\t\t\tif (Array.isArray(status?.passkey_origins)) setPasskeyOrigins(status!.passkey_origins);\n\t\t\t});\n\t}\n\n\tfunction reloadIfAuthNowRequiresLogin({ reload = true } = {}): Promise<boolean> {\n\t\treturn fetch(\"/api/auth/status\")\n\t\t\t.then((r) => (r.ok ? r.json() : null))\n\t\t\t.then((d: { auth_disabled?: boolean; setup_required?: boolean; authenticated?: boolean } | null) => {\n\t\t\t\tconst mustLogin = !!(d && d.auth_disabled === false && d.setup_required === false && d.authenticated === false);\n\t\t\t\tif (mustLogin && reload) {\n\t\t\t\t\twindow.location.reload();\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t\treturn mustLogin;\n\t\t\t})\n\t\t\t.catch(() => false);\n\t}\n\n\tuseEffect(() => {\n\t\tfetch(\"/api/auth/status\")\n\t\t\t.then((r) => (r.ok ? r.json() : null))\n\t\t\t.then((d: { auth_disabled?: boolean; localhost_only?: boolean; has_password?: boolean; has_passkeys?: boolean; setup_complete?: boolean; passkey_origins?: string[]; passkey_host_update_hosts?: string[] } | null) => {\n\t\t\t\tif (typeof d?.auth_disabled === \"boolean\") setAuthDisabled(d.auth_disabled);\n\t\t\t\tif (typeof d?.localhost_only === \"boolean\") setLocalhostOnly(d.localhost_only);\n\t\t\t\tif (typeof d?.has_password === \"boolean\") setHasPassword(d.has_password);\n\t\t\t\tif (typeof d?.has_passkeys === \"boolean\") setHasPasskeys(d.has_passkeys);\n\t\t\t\tif (typeof d?.setup_complete === \"boolean\") setSetupComplete(d.setup_complete);\n\t\t\t\tif (Array.isArray(d?.passkey_origins)) setPasskeyOrigins(d!.passkey_origins!);\n\t\t\t\tif (Array.isArray(d?.passkey_host_update_hosts)) setPasskeyHostUpdateHosts(d!.passkey_host_update_hosts!);\n\t\t\t\tsetAuthLoading(false);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch(() => {\n\t\t\t\tsetAuthLoading(false);\n\t\t\t\trerender();\n\t\t\t});\n\t\tfetch(\"/api/auth/passkeys\")\n\t\t\t.then((r) => (r.ok ? r.json() : { passkeys: [] }))\n\t\t\t.then((d: { passkeys?: PasskeyEntry[] }) => {\n\t\t\t\tsetPasskeys(d.passkeys || []);\n\t\t\t\tsetHasPasskeys((d.passkeys || []).length > 0);\n\t\t\t\tsetPkLoading(false);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch(() => setPkLoading(false));\n\t\tfetch(\"/api/auth/api-keys\")\n\t\t\t.then((r) => (r.ok ? r.json() : { api_keys: [] }))\n\t\t\t.then((d: { api_keys?: ApiKeyEntry[] }) => {\n\t\t\t\tsetApiKeys(d.api_keys || []);\n\t\t\t\tsetAkLoading(false);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch(() => setAkLoading(false));\n\t}, []);\n\n\tfunction onChangePw(e: Event): void {\n\t\te.preventDefault();\n\t\tsetPwErr(null);\n\t\tsetPwMsg(null);\n\t\tif (newPw.length < 12) {\n\t\t\tsetPwErr(\"New password must be at least 12 characters.\");\n\t\t\treturn;\n\t\t}\n\t\tif (newPw !== confirmPw) {\n\t\t\tsetPwErr(\"Passwords do not match.\");\n\t\t\treturn;\n\t\t}\n\t\tsetPwSaving(true);\n\t\tsetPwAwaitingReauth(false);\n\t\tconst settingFirstPassword = !hasPassword;\n\t\tif (settingFirstPassword) deferNextPasswordChangedRedirect();\n\t\tconst payload: { new_password: string; current_password?: string } = { new_password: newPw };\n\t\tif (hasPassword) payload.current_password = curPw;\n\t\tfetch(\"/api/auth/password/change\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify(payload),\n\t\t})\n\t\t\t.then((r) => {\n\t\t\t\tif (!r.ok) {\n\t\t\t\t\treturn r.text().then((t) => {\n\t\t\t\t\t\tclearPasswordChangedRedirectDeferral();\n\t\t\t\t\t\tsetPwErr(t);\n\t\t\t\t\t\tsetPwSaving(false);\n\t\t\t\t\t\tsetPwAwaitingReauth(false);\n\t\t\t\t\t\trerender();\n\t\t\t\t\t});\n\t\t\t\t}\n\n\t\t\t\treturn r.json().then((data: { recovery_key?: string }) => {\n\t\t\t\t\tconst hasRecoveryKey = !!data.recovery_key;\n\t\t\t\t\tsetPwMsg(hasPassword ? \"Password changed.\" : \"Password set.\");\n\t\t\t\t\tsetCurPw(\"\");\n\t\t\t\t\tsetNewPw(\"\");\n\t\t\t\t\tsetConfirmPw(\"\");\n\t\t\t\t\tsetHasPassword(true);\n\t\t\t\t\tsetSetupComplete(true);\n\t\t\t\t\tsetAuthDisabled(false);\n\t\t\t\t\tif (hasRecoveryKey) {\n\t\t\t\t\t\tsetPwRecoveryKey(data.recovery_key!);\n\t\t\t\t\t\trefreshGon();\n\t\t\t\t\t}\n\t\t\t\t\treturn reloadIfAuthNowRequiresLogin({ reload: !hasRecoveryKey }).then((requiresLoginOrReloaded) => {\n\t\t\t\t\t\tif (hasRecoveryKey && requiresLoginOrReloaded) {\n\t\t\t\t\t\t\tsetPwAwaitingReauth(true);\n\t\t\t\t\t\t\tsetPwMsg(\"Password set. Save the recovery key, then continue to sign in.\");\n\t\t\t\t\t\t\tsetPwSaving(false);\n\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t\treturn;\n\t\t\t\t\t\t}\n\t\t\t\t\t\tclearPasswordChangedRedirectDeferral();\n\t\t\t\t\t\tsetPwAwaitingReauth(false);\n\t\t\t\t\t\tif (!requiresLoginOrReloaded) notifyAuthStatusChanged();\n\t\t\t\t\t\tsetPwSaving(false);\n\t\t\t\t\t\trerender();\n\t\t\t\t\t});\n\t\t\t\t});\n\t\t\t})\n\t\t\t.catch((err: Error) => {\n\t\t\t\tclearPasswordChangedRedirectDeferral();\n\t\t\t\tsetPwErr(err.message);\n\t\t\t\tsetPwSaving(false);\n\t\t\t\tsetPwAwaitingReauth(false);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onAddPasskey(): void {\n\t\tsetPkMsg(null);\n\t\tif (/^\\d+\\.\\d+\\.\\d+\\.\\d+$/.test(location.hostname) || location.hostname.startsWith(\"[\")) {\n\t\t\tsetPkMsg(`Passkeys require a domain name. Use localhost instead of ${location.hostname}`);\n\t\t\trerender();\n\t\t\treturn;\n\t\t}\n\t\tlet requestedRpId: string | null = null;\n\t\tfetch(\"/api/auth/passkey/register/begin\", { method: \"POST\" })\n\t\t\t.then((r) => r.json())\n\t\t\t.then((data: { options: { publicKey: PublicKeyCredentialCreationOptions & { challenge: string; user: { id: string } } }; challenge_id: string }) => {\n\t\t\t\tconst opts = data.options;\n\t\t\t\trequestedRpId = (opts.publicKey.rp as { id?: string })?.id || null;\n\t\t\t\t(opts.publicKey as unknown as Record<string, unknown>).challenge = b64ToBuf(opts.publicKey.challenge as unknown as string);\n\t\t\t\t(opts.publicKey.user as unknown as Record<string, unknown>).id = b64ToBuf(opts.publicKey.user.id as unknown as string);\n\t\t\t\tif ((opts.publicKey as unknown as { excludeCredentials?: Array<{ id: string | ArrayBuffer }> }).excludeCredentials) {\n\t\t\t\t\tfor (const c of (opts.publicKey as unknown as { excludeCredentials: Array<{ id: string | ArrayBuffer }> }).excludeCredentials) (c as unknown as Record<string, unknown>).id = b64ToBuf(c.id as string);\n\t\t\t\t}\n\t\t\t\treturn navigator.credentials\n\t\t\t\t\t.create({ publicKey: opts.publicKey as unknown as PublicKeyCredentialCreationOptions })\n\t\t\t\t\t.then((cred) => ({ cred: cred as PublicKeyCredential, challengeId: data.challenge_id }));\n\t\t\t})\n\t\t\t.then(({ cred, challengeId }: { cred: PublicKeyCredential; challengeId: string }) => {\n\t\t\t\tconst response = cred.response as AuthenticatorAttestationResponse;\n\t\t\t\tconst body = {\n\t\t\t\t\tchallenge_id: challengeId,\n\t\t\t\t\tname: pkName.trim() || detectPasskeyName(cred),\n\t\t\t\t\tcredential: {\n\t\t\t\t\t\tid: cred.id,\n\t\t\t\t\t\trawId: bufToB64(cred.rawId),\n\t\t\t\t\t\ttype: cred.type,\n\t\t\t\t\t\tresponse: {\n\t\t\t\t\t\t\tattestationObject: bufToB64(response.attestationObject),\n\t\t\t\t\t\t\tclientDataJSON: bufToB64(response.clientDataJSON),\n\t\t\t\t\t\t},\n\t\t\t\t\t},\n\t\t\t\t};\n\t\t\t\treturn fetch(\"/api/auth/passkey/register/finish\", {\n\t\t\t\t\tmethod: \"POST\",\n\t\t\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\t\t\tbody: JSON.stringify(body),\n\t\t\t\t});\n\t\t\t})\n\t\t\t.then((r) => {\n\t\t\t\tif (r.ok) {\n\t\t\t\t\tsetPkName(\"\");\n\t\t\t\t\treturn reloadIfAuthNowRequiresLogin().then((reloaded) => {\n\t\t\t\t\t\tif (reloaded) return;\n\t\t\t\t\t\treturn fetch(\"/api/auth/passkeys\")\n\t\t\t\t\t\t\t.then((r2) => r2.json())\n\t\t\t\t\t\t\t.then((d: { passkeys?: PasskeyEntry[] }) => {\n\t\t\t\t\t\t\t\tsetPasskeys(d.passkeys || []);\n\t\t\t\t\t\t\t\tsetHasPasskeys((d.passkeys || []).length > 0);\n\t\t\t\t\t\t\t\tsetSetupComplete(true);\n\t\t\t\t\t\t\t\tsetAuthDisabled(false);\n\t\t\t\t\t\t\t\treturn refreshPasskeyHostStatus().then(() => {\n\t\t\t\t\t\t\t\t\tsetPkMsg(\"Passkey added.\");\n\t\t\t\t\t\t\t\t\tnotifyAuthStatusChanged();\n\t\t\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t\t\t});\n\t\t\t\t\t\t\t});\n\t\t\t\t\t});\n\t\t\t\t}\n\t\t\t\treturn r.text().then((t) => {\n\t\t\t\t\tsetPkMsg(t);\n\t\t\t\t\trerender();\n\t\t\t\t});\n\t\t\t})\n\t\t\t.catch((err: Error) => {\n\t\t\t\tlet msg = err.message || \"Failed to add passkey\";\n\t\t\t\tif (requestedRpId) {\n\t\t\t\t\tmsg += ` (RPID: \"${requestedRpId}\", current origin: \"${location.origin}\")`;\n\t\t\t\t}\n\t\t\t\tsetPkMsg(msg);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onStartRename(id: string, currentName: string): void {\n\t\tsetEditingPk(id);\n\t\tsetEditingPkName(currentName);\n\t\trerender();\n\t}\n\n\tfunction onCancelRename(): void {\n\t\tsetEditingPk(null);\n\t\tsetEditingPkName(\"\");\n\t\trerender();\n\t}\n\n\tfunction onConfirmRename(id: string): void {\n\t\tconst name = editingPkName.trim();\n\t\tif (!name) return;\n\t\tfetch(`/api/auth/passkeys/${id}`, {\n\t\t\tmethod: \"PATCH\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ name }),\n\t\t})\n\t\t\t.then(() => fetch(\"/api/auth/passkeys\").then((r) => r.json()))\n\t\t\t.then((d: { passkeys?: PasskeyEntry[] }) => {\n\t\t\t\tsetPasskeys(d.passkeys || []);\n\t\t\t\tsetEditingPk(null);\n\t\t\t\tsetEditingPkName(\"\");\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onRemovePasskey(id: string): void {\n\t\tfetch(`/api/auth/passkeys/${id}`, { method: \"DELETE\" })\n\t\t\t.then(() => fetch(\"/api/auth/passkeys\").then((r) => r.json()))\n\t\t\t.then((d: { passkeys?: PasskeyEntry[] }) => {\n\t\t\t\tsetPasskeys(d.passkeys || []);\n\t\t\t\tsetHasPasskeys((d.passkeys || []).length > 0);\n\t\t\t\treturn refreshPasskeyHostStatus().then(() => {\n\t\t\t\t\tnotifyAuthStatusChanged();\n\t\t\t\t\trerender();\n\t\t\t\t});\n\t\t\t});\n\t}\n\n\tfunction onCreateApiKey(): void {\n\t\tif (!akLabel.trim()) return;\n\t\tsetAkNew(null);\n\t\t// Build scopes array if not full access\n\t\tlet scopes: string[] | null = null;\n\t\tif (!akFullAccess) {\n\t\t\tscopes = Object.entries(akScopes)\n\t\t\t\t.filter(([, v]) => v)\n\t\t\t\t.map(([k]) => k);\n\t\t\tif (scopes.length === 0) {\n\t\t\t\t// Require at least one scope if not full access\n\t\t\t\treturn;\n\t\t\t}\n\t\t}\n\t\tfetch(\"/api/auth/api-keys\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ label: akLabel.trim(), scopes }),\n\t\t})\n\t\t\t.then((r) => r.json())\n\t\t\t.then((d: { key?: string }) => {\n\t\t\t\tsetAkNew(d.key || null);\n\t\t\t\tsetAkLabel(\"\");\n\t\t\t\tsetAkFullAccess(true);\n\t\t\t\tsetAkScopes({\n\t\t\t\t\t\"operator.read\": false,\n\t\t\t\t\t\"operator.write\": false,\n\t\t\t\t\t\"operator.approvals\": false,\n\t\t\t\t\t\"operator.pairing\": false,\n\t\t\t\t});\n\t\t\t\treturn fetch(\"/api/auth/api-keys\").then((r2) => r2.json());\n\t\t\t})\n\t\t\t.then((d: { api_keys?: ApiKeyEntry[] }) => {\n\t\t\t\tsetApiKeys(d.api_keys || []);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch(() => rerender());\n\t}\n\n\tfunction toggleScope(scope: string): void {\n\t\tsetAkScopes((prev) => ({ ...prev, [scope]: !prev[scope] }));\n\t\trerender();\n\t}\n\n\tfunction onRevokeApiKey(id: string): void {\n\t\tfetch(`/api/auth/api-keys/${id}`, { method: \"DELETE\" })\n\t\t\t.then(() => fetch(\"/api/auth/api-keys\").then((r) => r.json()))\n\t\t\t.then((d: { api_keys?: ApiKeyEntry[] }) => {\n\t\t\t\tsetApiKeys(d.api_keys || []);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tconst [resetConfirm, setResetConfirm] = useState(false);\n\tconst [resetBusy, setResetBusy] = useState(false);\n\n\tfunction onResetAuth(): void {\n\t\tif (!resetConfirm) {\n\t\t\tsetResetConfirm(true);\n\t\t\trerender();\n\t\t\treturn;\n\t\t}\n\t\tsetResetBusy(true);\n\t\trerender();\n\t\tfetch(\"/api/auth/reset\", { method: \"POST\" })\n\t\t\t.then((r) => {\n\t\t\t\tif (r.ok) {\n\t\t\t\t\twindow.location.reload();\n\t\t\t\t} else {\n\t\t\t\t\treturn r.text().then((t) => {\n\t\t\t\t\t\tsetPwErr(t);\n\t\t\t\t\t\tsetResetConfirm(false);\n\t\t\t\t\t\tsetResetBusy(false);\n\t\t\t\t\t\trerender();\n\t\t\t\t\t});\n\t\t\t\t}\n\t\t\t})\n\t\t\t.catch((err: Error) => {\n\t\t\t\tsetPwErr(err.message);\n\t\t\t\tsetResetConfirm(false);\n\t\t\t\tsetResetBusy(false);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tif (authLoading) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Authentication</h2>\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Loading{\"\\u2026\"}</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\tif (authDisabled && !localhostOnly) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Authentication</h2>\n\t\t\t\t<div style={{ maxWidth: \"600px\", padding: \"12px 16px\", borderRadius: \"6px\", border: \"1px solid var(--error)\", background: \"color-mix(in srgb, var(--error) 5%, transparent)\" }}>\n\t\t\t\t\t<strong style={{ color: \"var(--error)\" }}>Authentication is disabled</strong>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"8px 0 0\" }}>\n\t\t\t\t\t\tAnyone with network access can control moltis and your computer. Set up a password to protect your instance.\n\t\t\t\t\t</p>\n\t\t\t\t\t<button type=\"button\" className=\"provider-btn\" style={{ marginTop: \"10px\" }}\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\twindow.location.assign(\"/onboarding\");\n\t\t\t\t\t\t}}>Set up authentication</button>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Authentication</h2>\n\n\t\t\t{authDisabled && localhostOnly\n\t\t\t\t? <div style={{ maxWidth: \"600px\", padding: \"12px 16px\", borderRadius: \"6px\", border: \"1px solid var(--error)\", background: \"color-mix(in srgb, var(--error) 5%, transparent)\" }}>\n\t\t\t\t\t<strong style={{ color: \"var(--error)\" }}>Authentication is disabled</strong>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"8px 0 0\" }}>\n\t\t\t\t\t\tLocalhost-only access is safe, but localhost bypass is active. Until you add a password or passkey, this browser has full access and Sign out has no effect.\n\t\t\t\t\t\tAdd credentials below to require login on localhost and before exposing Moltis to your network.\n\t\t\t\t\t</p>\n\t\t\t\t</div>\n\t\t\t\t: null\n\t\t\t}\n\n\t\t\t{localhostOnly && !hasPassword && !hasPasskeys && !authDisabled\n\t\t\t\t? <div className=\"alert-info-text max-w-form\">\n\t\t\t\t\t<span className=\"alert-label-info\">Note: </span>\n\t\t\t\t\tLocalhost bypass is active. Until you add a password or passkey, this browser has full access and Sign out has no effect.\n\t\t\t\t\tAdd credentials to require login on localhost and before exposing Moltis to your network.\n\t\t\t\t</div>\n\t\t\t\t: null\n\t\t\t}\n\n\t\t\t{/* Password */}\n\t\t\t<div style={{ maxWidth: \"600px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>{hasPassword ? \"Change Password\" : \"Set Password\"}</h3>\n\t\t\t\t<form onSubmit={onChangePw}>\n\t\t\t\t\t<div style={{ display: \"flex\", flexDirection: \"column\", gap: \"8px\", marginBottom: \"10px\" }}>\n\t\t\t\t\t\t{hasPassword\n\t\t\t\t\t\t\t? <div>\n\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>Current password</div>\n\t\t\t\t\t\t\t\t<input type=\"password\" className=\"provider-key-input\" style={{ width: \"100%\" }} value={curPw}\n\t\t\t\t\t\t\t\t\tonInput={(e: Event) => setCurPw((e.target as HTMLInputElement).value)} />\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>{hasPassword ? \"New password\" : \"Password\"}</div>\n\t\t\t\t\t\t\t<input type=\"password\" className=\"provider-key-input\" style={{ width: \"100%\" }} value={newPw}\n\t\t\t\t\t\t\t\tonInput={(e: Event) => setNewPw((e.target as HTMLInputElement).value)} placeholder=\"At least 12 characters\" />\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>Confirm {hasPassword ? \"new \" : \"\"}password</div>\n\t\t\t\t\t\t\t<input type=\"password\" className=\"provider-key-input\" style={{ width: \"100%\" }} value={confirmPw}\n\t\t\t\t\t\t\t\tonInput={(e: Event) => setConfirmPw((e.target as HTMLInputElement).value)} />\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\" }}>\n\t\t\t\t\t\t<button type=\"submit\" className=\"provider-btn\" disabled={pwSaving}>\n\t\t\t\t\t\t\t{pwSaving ? (hasPassword ? \"Changing\\u2026\" : \"Setting\\u2026\") : hasPassword ? \"Change password\" : \"Set password\"}\n\t\t\t\t\t\t</button>\n\t\t\t\t\t\t{pwMsg ? <span className=\"text-xs\" style={{ color: \"var(--accent)\" }}>{pwMsg}</span> : null}\n\t\t\t\t\t\t{pwErr ? <span className=\"text-xs\" style={{ color: \"var(--error)\" }}>{pwErr}</span> : null}\n\t\t\t\t\t</div>\n\t\t\t\t</form>\n\t\t\t\t{pwRecoveryKey\n\t\t\t\t\t? <div style={{ marginTop: \"12px\", padding: \"12px 16px\", borderRadius: \"6px\", border: \"1px solid var(--border)\", background: \"var(--bg)\" }}>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>Vault initialized {\"\\u2014\"} save this recovery key</div>\n\t\t\t\t\t\t<code className=\"select-all break-all\" style={{ fontFamily: \"var(--font-mono)\", fontSize: \".8rem\", color: \"var(--text-strong)\", display: \"block\", lineHeight: 1.5 }}>{pwRecoveryKey}</code>\n\t\t\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\", marginTop: \"8px\" }}>\n\t\t\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-secondary\" onClick={() => {\n\t\t\t\t\t\t\t\tnavigator.clipboard.writeText(pwRecoveryKey).then(() => {\n\t\t\t\t\t\t\t\t\tsetPwRecoveryCopied(true);\n\t\t\t\t\t\t\t\t\tsetTimeout(() => {\n\t\t\t\t\t\t\t\t\t\tsetPwRecoveryCopied(false);\n\t\t\t\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t\t\t\t}, 2000);\n\t\t\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t\t\t});\n\t\t\t\t\t\t\t}}>{pwRecoveryCopied ? \"Copied!\" : \"Copy\"}</button>\n\t\t\t\t\t\t\t{pwAwaitingReauth\n\t\t\t\t\t\t\t\t? <button type=\"button\" className=\"provider-btn\" onClick={() => {\n\t\t\t\t\t\t\t\t\tclearPasswordChangedRedirectDeferral();\n\t\t\t\t\t\t\t\t\twindow.location.assign(\"/login\");\n\t\t\t\t\t\t\t\t}}>Continue to sign in</button>\n\t\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs\" style={{ color: \"var(--error)\", marginTop: \"8px\" }}>\n\t\t\t\t\t\t\tThis key will not be shown again. You need it to unlock the vault if you forget your password.\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t</div>\n\n\t\t\t{/* Passkeys */}\n\t\t\t<div style={{ maxWidth: \"600px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>Passkeys</h3>\n\t\t\t\t{passkeyOrigins.length > 1 && <div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"8px\" }}>Passkeys will work when visiting: {passkeyOrigins.map((o) => o.replace(/^https?:\\/\\//, \"\")).join(\", \")}</div>}\n\t\t\t\t{hasPasskeys && passkeyHostUpdateHosts.length > 0\n\t\t\t\t\t? <div className=\"alert-warning-text max-w-form\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\t\t\t<span className=\"alert-label-warning\">Passkey update needed: </span>\n\t\t\t\t\t\tNew host detected ({passkeyHostUpdateHosts.join(\", \")}). Sign in with your password on that host, then register a new passkey there.\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t\t{pkLoading\n\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\">Loading{\"\\u2026\"}</div>\n\t\t\t\t\t: <>\n\t\t\t\t\t\t{passkeys.length > 0\n\t\t\t\t\t\t\t? <div style={{ display: \"flex\", flexDirection: \"column\", gap: \"6px\", marginBottom: \"12px\" }}>\n\t\t\t\t\t\t\t\t{passkeys.map((pk) => (\n\t\t\t\t\t\t\t\t\t<div className=\"provider-item\" style={{ marginBottom: 0 }} key={pk.id}>\n\t\t\t\t\t\t\t\t\t\t{editingPk === pk.id\n\t\t\t\t\t\t\t\t\t\t\t? <form style={{ display: \"flex\", alignItems: \"center\", gap: \"6px\", flex: 1 }} onSubmit={(e: Event) => {\n\t\t\t\t\t\t\t\t\t\t\t\te.preventDefault();\n\t\t\t\t\t\t\t\t\t\t\t\tonConfirmRename(pk.id);\n\t\t\t\t\t\t\t\t\t\t\t}}>\n\t\t\t\t\t\t\t\t\t\t\t\t<input type=\"text\" className=\"provider-key-input\" value={editingPkName}\n\t\t\t\t\t\t\t\t\t\t\t\t\tonInput={(e: Event) => setEditingPkName((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\t\t\t\t\t\tstyle={{ flex: 1 }} autoFocus />\n\t\t\t\t\t\t\t\t\t\t\t\t<button type=\"submit\" className=\"provider-btn provider-btn-sm\">Save</button>\n\t\t\t\t\t\t\t\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-sm provider-btn-secondary\" onClick={onCancelRename}>Cancel</button>\n\t\t\t\t\t\t\t\t\t\t\t</form>\n\t\t\t\t\t\t\t\t\t\t\t: <><div style={{ flex: 1, minWidth: 0 }}>\n\t\t\t\t\t\t\t\t\t\t\t\t<div className=\"provider-item-name\" style={{ fontSize: \".85rem\" }}>{pk.name}</div>\n\t\t\t\t\t\t\t\t\t\t\t\t<div style={{ fontSize: \".7rem\", color: \"var(--muted)\", marginTop: \"2px\" }}><time dateTime={pk.created_at}>{pk.created_at}</time></div>\n\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t<div style={{ display: \"flex\", gap: \"4px\" }}>\n\t\t\t\t\t\t\t\t\t\t\t\t<button className=\"provider-btn provider-btn-sm provider-btn-secondary\" onClick={() => onStartRename(pk.id, pk.name)}>Rename</button>\n\t\t\t\t\t\t\t\t\t\t\t\t<button className=\"provider-btn provider-btn-sm provider-btn-danger\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tonClick={() => onRemovePasskey(pk.id)}>Remove</button>\n\t\t\t\t\t\t\t\t\t\t\t</div></>\n\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t))}\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: <div className=\"text-xs text-[var(--muted)]\" style={{ padding: \"4px 0 12px\" }}>No passkeys registered.</div>\n\t\t\t\t\t\t}\n\t\t\t\t\t\t<div style={{ display: \"flex\", gap: \"8px\", alignItems: \"center\" }}>\n\t\t\t\t\t\t\t<input type=\"text\" className=\"provider-key-input\" value={pkName}\n\t\t\t\t\t\t\t\tonInput={(e: Event) => setPkName((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\tplaceholder=\"Passkey name (e.g. MacBook Touch ID)\" style={{ flex: 1 }} />\n\t\t\t\t\t\t\t<button type=\"button\" className=\"provider-btn\" onClick={onAddPasskey}>Add passkey</button>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t{pkMsg ? <div className=\"text-xs text-[var(--muted)]\" style={{ marginTop: \"6px\" }}>{pkMsg}</div> : null}\n\t\t\t\t\t</>\n\t\t\t\t}\n\t\t\t</div>\n\n\t\t\t{/* API Keys */}\n\t\t\t<div style={{ maxWidth: \"600px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"4px\" }}>API Keys</h3>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed\" style={{ margin: \"0 0 12px\" }}>\n\t\t\t\t\tAPI keys authenticate external tools and scripts connecting to moltis over the WebSocket protocol. Pass the key as the <code style={{ fontFamily: \"var(--font-mono)\", fontSize: \".75rem\" }}>api_key</code> field in the <code style={{ fontFamily: \"var(--font-mono)\", fontSize: \".75rem\" }}>auth</code> object of the <code style={{ fontFamily: \"var(--font-mono)\", fontSize: \".75rem\" }}>connect</code> handshake.\n\t\t\t\t</p>\n\t\t\t\t{akLoading\n\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\">Loading{\"\\u2026\"}</div>\n\t\t\t\t\t: <>\n\t\t\t\t\t\t{akNew\n\t\t\t\t\t\t\t? <div style={{ marginBottom: \"12px\", padding: \"10px 12px\", background: \"var(--bg)\", border: \"1px solid var(--border)\", borderRadius: \"6px\" }}>\n\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>Copy this key now. It won't be shown again.</div>\n\t\t\t\t\t\t\t\t<code style={{ fontFamily: \"var(--font-mono)\", fontSize: \".78rem\", wordBreak: \"break-all\", color: \"var(--text-strong)\" }}>{akNew}</code>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\t\t\t\t\t\t{apiKeys.length > 0\n\t\t\t\t\t\t\t? <div style={{ display: \"flex\", flexDirection: \"column\", gap: \"6px\", marginBottom: \"12px\" }}>\n\t\t\t\t\t\t\t\t{apiKeys.map((ak) => (\n\t\t\t\t\t\t\t\t\t<div className=\"provider-item\" style={{ marginBottom: 0 }} key={ak.id}>\n\t\t\t\t\t\t\t\t\t\t<div style={{ flex: 1, minWidth: 0 }}>\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"provider-item-name\" style={{ fontSize: \".85rem\" }}>{ak.label}</div>\n\t\t\t\t\t\t\t\t\t\t\t<div style={{ fontSize: \".7rem\", color: \"var(--muted)\", marginTop: \"2px\", display: \"flex\", gap: \"12px\", flexWrap: \"wrap\" }}>\n\t\t\t\t\t\t\t\t\t\t\t\t<span style={{ fontFamily: \"var(--font-mono)\" }}>{ak.key_prefix}...</span>\n\t\t\t\t\t\t\t\t\t\t\t\t<span><time dateTime={ak.created_at}>{ak.created_at}</time></span>\n\t\t\t\t\t\t\t\t\t\t\t\t{ak.scopes ? <span style={{ color: \"var(--accent)\" }}>{ak.scopes.join(\", \")}</span> : <span style={{ color: \"var(--accent)\" }}>Full access</span>}\n\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<button className=\"provider-btn provider-btn-danger\"\n\t\t\t\t\t\t\t\t\t\t\tonClick={() => onRevokeApiKey(ak.id)}>Revoke</button>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t))}\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: <div className=\"text-xs text-[var(--muted)]\" style={{ padding: \"4px 0 12px\" }}>No API keys.</div>\n\t\t\t\t\t\t}\n\t\t\t\t\t\t<div style={{ display: \"flex\", flexDirection: \"column\", gap: \"10px\" }}>\n\t\t\t\t\t\t\t<div style={{ display: \"flex\", gap: \"8px\", alignItems: \"center\" }}>\n\t\t\t\t\t\t\t\t<input type=\"text\" className=\"provider-key-input\" value={akLabel}\n\t\t\t\t\t\t\t\t\tonInput={(e: Event) => setAkLabel((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\t\tplaceholder=\"Key label (e.g. CLI tool)\" style={{ flex: 1 }} />\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t\t<label style={{ display: \"flex\", alignItems: \"center\", gap: \"6px\", cursor: \"pointer\" }}>\n\t\t\t\t\t\t\t\t\t<input type=\"checkbox\" checked={akFullAccess}\n\t\t\t\t\t\t\t\t\t\tonChange={() => {\n\t\t\t\t\t\t\t\t\t\t\tsetAkFullAccess(!akFullAccess);\n\t\t\t\t\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t\t\t\t\t}} />\n\t\t\t\t\t\t\t\t\t<span className=\"text-xs text-[var(--text)]\">Full access (all permissions)</span>\n\t\t\t\t\t\t\t\t</label>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t{akFullAccess\n\t\t\t\t\t\t\t\t? null\n\t\t\t\t\t\t\t\t: <div style={{ paddingLeft: \"20px\", display: \"flex\", flexDirection: \"column\", gap: \"6px\" }}>\n\t\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"2px\" }}>Select permissions:</div>\n\t\t\t\t\t\t\t\t\t<label style={{ display: \"flex\", alignItems: \"center\", gap: \"6px\", cursor: \"pointer\" }}>\n\t\t\t\t\t\t\t\t\t\t<input type=\"checkbox\" checked={akScopes[\"operator.read\"]}\n\t\t\t\t\t\t\t\t\t\t\tonChange={() => toggleScope(\"operator.read\")} />\n\t\t\t\t\t\t\t\t\t\t<span className=\"text-xs text-[var(--text)]\">operator.read</span>\n\t\t\t\t\t\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">{\"\\u2014\"} View data and status</span>\n\t\t\t\t\t\t\t\t\t</label>\n\t\t\t\t\t\t\t\t\t<label style={{ display: \"flex\", alignItems: \"center\", gap: \"6px\", cursor: \"pointer\" }}>\n\t\t\t\t\t\t\t\t\t\t<input type=\"checkbox\" checked={akScopes[\"operator.write\"]}\n\t\t\t\t\t\t\t\t\t\t\tonChange={() => toggleScope(\"operator.write\")} />\n\t\t\t\t\t\t\t\t\t\t<span className=\"text-xs text-[var(--text)]\">operator.write</span>\n\t\t\t\t\t\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">{\"\\u2014\"} Create, update, delete</span>\n\t\t\t\t\t\t\t\t\t</label>\n\t\t\t\t\t\t\t\t\t<label style={{ display: \"flex\", alignItems: \"center\", gap: \"6px\", cursor: \"pointer\" }}>\n\t\t\t\t\t\t\t\t\t\t<input type=\"checkbox\" checked={akScopes[\"operator.approvals\"]}\n\t\t\t\t\t\t\t\t\t\t\tonChange={() => toggleScope(\"operator.approvals\")} />\n\t\t\t\t\t\t\t\t\t\t<span className=\"text-xs text-[var(--text)]\">operator.approvals</span>\n\t\t\t\t\t\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">{\"\\u2014\"} Handle exec approvals</span>\n\t\t\t\t\t\t\t\t\t</label>\n\t\t\t\t\t\t\t\t\t<label style={{ display: \"flex\", alignItems: \"center\", gap: \"6px\", cursor: \"pointer\" }}>\n\t\t\t\t\t\t\t\t\t\t<input type=\"checkbox\" checked={akScopes[\"operator.pairing\"]}\n\t\t\t\t\t\t\t\t\t\t\tonChange={() => toggleScope(\"operator.pairing\")} />\n\t\t\t\t\t\t\t\t\t\t<span className=\"text-xs text-[var(--text)]\">operator.pairing</span>\n\t\t\t\t\t\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">{\"\\u2014\"} Device/node pairing</span>\n\t\t\t\t\t\t\t\t\t</label>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t\t<button type=\"button\" className=\"provider-btn\" onClick={onCreateApiKey}\n\t\t\t\t\t\t\t\t\tdisabled={!(akLabel.trim() && (akFullAccess || Object.values(akScopes).some((v) => v)))}>\n\t\t\t\t\t\t\t\t\tGenerate key\n\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</>\n\t\t\t\t}\n\t\t\t</div>\n\n\t\t\t{/* Danger zone (only when auth has been set up) */}\n\t\t\t{setupComplete\n\t\t\t\t? <div style={{ maxWidth: \"600px\", marginTop: \"8px\", borderTop: \"1px solid var(--error)\", paddingTop: \"16px\" }}>\n\t\t\t\t\t<h3 className=\"text-sm font-medium\" style={{ color: \"var(--error)\", marginBottom: \"8px\" }}>Danger Zone</h3>\n\t\t\t\t\t<div style={{ padding: \"12px 16px\", border: \"1px solid var(--error)\", borderRadius: \"6px\", background: \"color-mix(in srgb, var(--error) 5%, transparent)\" }}>\n\t\t\t\t\t\t<strong className=\"text-sm\" style={{ color: \"var(--text-strong)\" }}>Remove all authentication</strong>\n\t\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"6px 0 0\" }}>\n\t\t\t\t\t\t\tIf you know what you're doing, you can fully disable authentication.\n\t\t\t\t\t\t\tAnyone with network access will be able to access moltis and your computer.\n\t\t\t\t\t\t\tThis removes your password, all passkeys, all API keys, and all sessions.\n\t\t\t\t\t\t</p>\n\t\t\t\t\t\t{resetConfirm\n\t\t\t\t\t\t\t? <div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\", marginTop: \"10px\" }}>\n\t\t\t\t\t\t\t\t<span className=\"text-xs\" style={{ color: \"var(--error)\" }}>Are you sure? This cannot be undone.</span>\n\t\t\t\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-danger\" disabled={resetBusy}\n\t\t\t\t\t\t\t\t\tonClick={onResetAuth}>{resetBusy ? \"Removing\\u2026\" : \"Yes, remove all auth\"}</button>\n\t\t\t\t\t\t\t\t<button type=\"button\" className=\"provider-btn\" onClick={() => {\n\t\t\t\t\t\t\t\t\tsetResetConfirm(false);\n\t\t\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t\t\t}}>Cancel</button>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: <button type=\"button\" className=\"provider-btn provider-btn-danger\" style={{ marginTop: \"10px\" }}\n\t\t\t\t\t\t\t\tonClick={onResetAuth}>Remove all authentication</button>\n\t\t\t\t\t\t}\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t: \"\"\n\t\t\t}\n\t\t</div>\n\t);\n}\n\n// ── Vault (Encryption) section ──────────────────────────────\n\nfunction VaultSection(): VNode {\n\tconst [vaultStatus, setVaultStatus] = useState(gon.get(\"vault_status\") || null);\n\tconst [unlockPw, setUnlockPw] = useState(\"\");\n\tconst [recoveryKey, setRecoveryKey] = useState(\"\");\n\tconst [msg, setMsg] = useState<string | null>(null);\n\tconst [err, setErr] = useState<string | null>(null);\n\tconst [unlockingPw, setUnlockingPw] = useState(false);\n\tconst [unlockingRk, setUnlockingRk] = useState(false);\n\n\tuseEffect(() => {\n\t\treturn gon.onChange(\"vault_status\", (val: unknown) => {\n\t\t\tsetVaultStatus(val as string);\n\t\t\trerender();\n\t\t});\n\t}, []);\n\n\tfunction onUnlockPw(e: Event): void {\n\t\te.preventDefault();\n\t\tif (!unlockPw.trim()) return;\n\t\tsetErr(null);\n\t\tsetMsg(null);\n\t\tsetUnlockingPw(true);\n\t\trerender();\n\t\tdoUnlock(\"/api/auth/vault/unlock\", { password: unlockPw }, () => setUnlockingPw(false));\n\t}\n\n\tfunction onUnlockRecovery(e: Event): void {\n\t\te.preventDefault();\n\t\tif (!recoveryKey.trim()) return;\n\t\tsetErr(null);\n\t\tsetMsg(null);\n\t\tsetUnlockingRk(true);\n\t\trerender();\n\t\tdoUnlock(\"/api/auth/vault/recovery\", { recovery_key: recoveryKey }, () => setUnlockingRk(false));\n\t}\n\n\tfunction doUnlock(url: string, body: Record<string, string>, done: () => void): void {\n\t\tfetch(url, {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify(body),\n\t\t})\n\t\t\t.then((r) => {\n\t\t\t\tif (r.ok) {\n\t\t\t\t\tsetMsg(\"Vault unlocked.\");\n\t\t\t\t\tsetUnlockPw(\"\");\n\t\t\t\t\tsetRecoveryKey(\"\");\n\t\t\t\t\trefreshGon();\n\t\t\t\t} else {\n\t\t\t\t\treturn r.text().then((t) => setErr(t || \"Unlock failed\"));\n\t\t\t\t}\n\t\t\t\tdone();\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((error: Error) => {\n\t\t\t\tsetErr(error.message);\n\t\t\t\tdone();\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tif (!vaultStatus || vaultStatus === \"disabled\") {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Encryption</h2>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)]\">Encryption at rest is not available in this build.</p>\n\t\t\t</div>\n\t\t);\n\t}\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Encryption</h2>\n\n\t\t\t<div style={{ maxWidth: \"600px\" }}>\n\t\t\t\t<div className=\"rounded border border-[var(--border)] bg-[var(--surface2)] p-3 mb-4\">\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed m-0 mb-1.5\">\n\t\t\t\t\t\tYour API keys and secrets are encrypted at rest using <strong className=\"text-[var(--text)]\">XChaCha20-Poly1305</strong> AEAD with keys derived from your password via <strong className=\"text-[var(--text)]\">Argon2id</strong>.\n\t\t\t\t\t</p>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed m-0 mb-1.5\">\n\t\t\t\t\t\tThe vault uses a two-layer key hierarchy: your password derives a Key Encryption Key (KEK) which unwraps a random 256-bit Data Encryption Key (DEK). Changing your password only re-wraps the DEK {\"\\u2014\"} all encrypted data stays intact. A recovery key (shown once at setup) provides emergency access if you forget your password.\n\t\t\t\t\t</p>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed m-0\">\n\t\t\t\t\t\tThe vault locks automatically when the server restarts and unlocks when you log in.\n\t\t\t\t\t</p>\n\t\t\t\t</div>\n\n\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\", marginBottom: \"12px\" }}>\n\t\t\t\t\t<span className={`provider-item-badge ${vaultStatus === \"unsealed\" ? \"configured\" : vaultStatus === \"sealed\" ? \"warning\" : \"muted\"}`}>\n\t\t\t\t\t\t{vaultStatus === \"unsealed\" ? \"Unlocked\" : vaultStatus === \"sealed\" ? \"Locked\" : \"Off\"}\n\t\t\t\t\t</span>\n\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">{\n\t\t\t\t\t\tvaultStatus === \"unsealed\"\n\t\t\t\t\t\t\t? \"Your API keys and secrets are encrypted in the database. Everything is working.\"\n\t\t\t\t\t\t\t: vaultStatus === \"sealed\"\n\t\t\t\t\t\t\t\t? \"Log in or unlock below to access your encrypted keys.\"\n\t\t\t\t\t\t\t\t: \"Set a password in Authentication settings to start encrypting your stored keys.\"\n\t\t\t\t\t}</span>\n\t\t\t\t</div>\n\n\t\t\t\t{vaultStatus === \"sealed\"\n\t\t\t\t\t? <div style={{ display: \"flex\", flexDirection: \"column\", gap: \"12px\" }}>\n\t\t\t\t\t\t<form onSubmit={onUnlockPw} style={{ display: \"flex\", flexDirection: \"column\", gap: \"6px\" }}>\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Unlock with password</div>\n\t\t\t\t\t\t\t<div style={{ display: \"flex\", gap: \"8px\", alignItems: \"center\" }}>\n\t\t\t\t\t\t\t\t<input type=\"password\" className=\"provider-key-input\" style={{ flex: 1 }} value={unlockPw} onInput={(e: Event) => setUnlockPw((e.target as HTMLInputElement).value)} placeholder=\"Your password\" />\n\t\t\t\t\t\t\t\t<button type=\"submit\" className=\"provider-btn\" disabled={unlockingPw || !unlockPw.trim()}>{unlockingPw ? \"Unlocking\\u2026\" : \"Unlock\"}</button>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</form>\n\t\t\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\" }}>\n\t\t\t\t\t\t\t<div style={{ flex: 1, borderTop: \"1px solid var(--border)\" }} />\n\t\t\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">or</span>\n\t\t\t\t\t\t\t<div style={{ flex: 1, borderTop: \"1px solid var(--border)\" }} />\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<form onSubmit={onUnlockRecovery} style={{ display: \"flex\", flexDirection: \"column\", gap: \"6px\" }}>\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Unlock with recovery key</div>\n\t\t\t\t\t\t\t<div style={{ display: \"flex\", gap: \"8px\", alignItems: \"center\" }}>\n\t\t\t\t\t\t\t\t<input type=\"password\" className=\"provider-key-input\" style={{ flex: 1, fontFamily: \"var(--font-mono)\", fontSize: \".78rem\" }} value={recoveryKey} onInput={(e: Event) => setRecoveryKey((e.target as HTMLInputElement).value)} placeholder=\"XXXX-XXXX-XXXX-XXXX-XXXX-XXXX-XXXX-XXXX\" />\n\t\t\t\t\t\t\t\t<button type=\"submit\" className=\"provider-btn\" disabled={unlockingRk || !recoveryKey.trim()}>{unlockingRk ? \"Unlocking\\u2026\" : \"Unlock\"}</button>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</form>\n\t\t\t\t\t\t{msg ? <div className=\"text-xs\" style={{ color: \"var(--accent)\" }}>{msg}</div> : null}\n\t\t\t\t\t\t{err ? <div className=\"text-xs\" style={{ color: \"var(--error)\" }}>{err}</div> : null}\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\n\t\t\t\t{vaultStatus === \"uninitialized\"\n\t\t\t\t\t? <div style={{ marginTop: \"4px\" }}>\n\t\t\t\t\t\t<a href=\"/settings/security\" className=\"provider-btn provider-btn-secondary\" style={{ fontSize: \".75rem\", textDecoration: \"none\", display: \"inline-block\" }}>Set a password</a>\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nfunction ToolsSection(): VNode {\n\tconst [loadingTools, setLoadingTools] = useState(true);\n\tconst [toolData, setToolData] = useState<ToolsContextData | null>(null);\n\tconst [nodeInventory, setNodeInventory] = useState<NodeInventoryEntry[]>([]);\n\tconst [toolsErr, setToolsErr] = useState<string | null>(null);\n\n\tfunction loadToolsOverview(): void {\n\t\tsetLoadingTools(true);\n\t\tsetToolsErr(null);\n\t\tPromise.allSettled([sendRpc(\"chat.context\", {}), sendRpc(\"node.list\", {})])\n\t\t\t.then((results) => {\n\t\t\t\tconst contextResult = results[0];\n\t\t\t\tif (contextResult.status !== \"fulfilled\" || !(contextResult.value as RpcResponse)?.ok) {\n\t\t\t\t\tconst errValue = contextResult.status === \"fulfilled\" ? contextResult.value as RpcResponse : null;\n\t\t\t\t\tthrow new Error(errValue?.error?.message || \"Failed to load tools overview.\");\n\t\t\t\t}\n\t\t\t\tconst nextToolData = ((contextResult.value as RpcResponse).payload || {}) as ToolsContextData;\n\t\t\t\tconst nodesResult = results[1];\n\t\t\t\tconst nextNodeInventory =\n\t\t\t\t\tnodesResult.status === \"fulfilled\" && (nodesResult.value as RpcResponse)?.ok && Array.isArray((nodesResult.value as RpcResponse).payload)\n\t\t\t\t\t\t? (nodesResult.value as RpcResponse).payload as NodeInventoryEntry[]\n\t\t\t\t\t\t: [];\n\t\t\t\tsetToolData(nextToolData);\n\t\t\t\tsetNodeInventory(nextNodeInventory);\n\t\t\t\tsetLoadingTools(false);\n\t\t\t})\n\t\t\t.catch((error: Error) => {\n\t\t\t\tsetLoadingTools(false);\n\t\t\t\tsetToolsErr(error.message);\n\t\t\t});\n\t}\n\n\tuseEffect(() => {\n\t\tloadToolsOverview();\n\t}, []);\n\n\tconst data = toolData || {} as ToolsContextData;\n\tconst session = data.session || {};\n\tconst execution = data.execution || {};\n\tconst sandbox = data.sandbox || {};\n\tconst tools: ToolEntry[] = Array.isArray(data.tools) ? data.tools : [];\n\tconst toolGroups = groupToolsForOverview(tools);\n\tconst skills: SkillEntry[] = Array.isArray(data.skills) ? data.skills : [];\n\tconst pluginCount = skills.filter((entry) => entry?.source === \"plugin\").length;\n\tconst personalSkillCount = skills.length - pluginCount;\n\tconst mcpServers: McpServerEntry[] = Array.isArray(data.mcpServers) ? data.mcpServers : [];\n\tconst runningMcpServers = mcpServers.filter((entry) => entry?.state === \"running\");\n\tconst runningMcpToolCount = runningMcpServers.reduce((sum, entry) => sum + (Number(entry?.tool_count) || 0), 0);\n\tconst remoteExecInventory = summarizeRemoteExecInventory(nodeInventory);\n\tconst routeDetails: string[] = [];\n\trouteDetails.push(execution.mode === \"sandbox\" ? \"sandboxed commands\" : \"host commands\");\n\tif (remoteExecInventory.pairedNodes > 0) {\n\t\trouteDetails.push(pluralizeToolsCount(remoteExecInventory.pairedNodes, \"paired node\"));\n\t}\n\tif (remoteExecInventory.sshTargets > 0) {\n\t\trouteDetails.push(pluralizeToolsCount(remoteExecInventory.sshTargets, \"SSH target\"));\n\t}\n\tif (remoteExecInventory.pairedNodes === 0 && remoteExecInventory.sshTargets === 0) {\n\t\trouteDetails.push(\"local only\");\n\t}\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<div className=\"flex items-start justify-between gap-3 flex-wrap max-w-[1100px]\">\n\t\t\t\t<div className=\"min-w-0\">\n\t\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Tools</h2>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)] mt-1 max-w-[900px] leading-relaxed\">\n\t\t\t\t\t\tThis page shows the effective tool inventory for the active session and model. Change the\n\t\t\t\t\t\tcurrent LLM, disable MCP for a session, or switch execution routes and the inventory here will\n\t\t\t\t\t\tchange with it.\n\t\t\t\t\t</p>\n\t\t\t\t</div>\n\t\t\t\t<button\n\t\t\t\t\ttype=\"button\"\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\tonClick={loadToolsOverview}\n\t\t\t\t\tdisabled={loadingTools}\n\t\t\t\t>\n\t\t\t\t\t{loadingTools ? \"Refreshing\\u2026\" : \"Refresh\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\n\t\t\t<div className=\"rounded border border-[var(--border)] bg-[var(--surface2)] p-3 max-w-[1100px]\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)] leading-relaxed\">\n\t\t\t\t\tUse this as the operator view of what the model can currently reach. For setup changes, jump straight\n\t\t\t\t\tto the relevant control surface.\n\t\t\t\t</div>\n\t\t\t\t<div className=\"mt-3 flex gap-2 flex-wrap\">\n\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-secondary\" onClick={() => navigate(settingsPath(\"providers\"))}>\n\t\t\t\t\t\tLLMs\n\t\t\t\t\t</button>\n\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-secondary\" onClick={() => navigate(settingsPath(\"mcp\"))}>\n\t\t\t\t\t\tMCP\n\t\t\t\t\t</button>\n\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-secondary\" onClick={() => navigate(settingsPath(\"skills\"))}>\n\t\t\t\t\t\tSkills\n\t\t\t\t\t</button>\n\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-secondary\" onClick={() => navigate(settingsPath(\"nodes\"))}>\n\t\t\t\t\t\tNodes\n\t\t\t\t\t</button>\n\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-secondary\" onClick={() => navigate(settingsPath(\"ssh\"))}>\n\t\t\t\t\t\tSSH\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t{toolsErr ? <div className=\"text-xs text-[var(--error)] max-w-[1100px]\">{toolsErr}</div> : null}\n\n\t\t\t<div className=\"grid gap-4 md:grid-cols-2 max-w-[1100px]\">\n\t\t\t\t<div className=\"rounded border border-[var(--border)] bg-[var(--surface)] p-4\">\n\t\t\t\t\t<div className=\"text-xs uppercase tracking-wide text-[var(--muted)]\">Tool Calling</div>\n\t\t\t\t\t<div className=\"mt-2 flex items-center gap-2 flex-wrap\">\n\t\t\t\t\t\t<span className={`provider-item-badge ${data.supportsTools === false ? \"warning\" : \"configured\"}`}>\n\t\t\t\t\t\t\t{data.supportsTools === false ? \"Disabled\" : \"Enabled\"}\n\t\t\t\t\t\t</span>\n\t\t\t\t\t\t<span className=\"text-sm font-medium text-[var(--text)]\">\n\t\t\t\t\t\t\t{tools.length} registered tool{tools.length === 1 ? \"\" : \"s\"}\n\t\t\t\t\t\t</span>\n\t\t\t\t\t</div>\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mt-2 leading-relaxed\">\n\t\t\t\t\t\t{data.supportsTools === false\n\t\t\t\t\t\t\t? \"The current model is chat-only, so the agent cannot call tools in this session.\"\n\t\t\t\t\t\t\t: \"Built-in, MCP, and runtime-routed tools available to the active model.\"\n\t\t\t\t\t\t}\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\n\t\t\t\t<div className=\"rounded border border-[var(--border)] bg-[var(--surface)] p-4\">\n\t\t\t\t\t<div className=\"text-xs uppercase tracking-wide text-[var(--muted)]\">Active Model</div>\n\t\t\t\t\t<div className=\"mt-2 text-sm font-medium text-[var(--text)] break-words\">\n\t\t\t\t\t\t{session.model || \"Default model selection\"}\n\t\t\t\t\t</div>\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mt-2 leading-relaxed\">\n\t\t\t\t\t\t{session.provider ? `Provider: ${session.provider}` : \"Provider selected automatically.\"}\n\t\t\t\t\t\t{session.label ? ` Session: ${session.label}.` : \"\"}\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\n\t\t\t\t<div className=\"rounded border border-[var(--border)] bg-[var(--surface)] p-4\">\n\t\t\t\t\t<div className=\"text-xs uppercase tracking-wide text-[var(--muted)]\">MCP</div>\n\t\t\t\t\t<div className=\"mt-2 flex items-center gap-2 flex-wrap\">\n\t\t\t\t\t\t<span className={`provider-item-badge ${\n\t\t\t\t\t\t\tdata.supportsTools === false || data.mcpDisabled\n\t\t\t\t\t\t\t\t? \"warning\"\n\t\t\t\t\t\t\t\t: runningMcpServers.length > 0\n\t\t\t\t\t\t\t\t\t? \"configured\"\n\t\t\t\t\t\t\t\t\t: \"muted\"\n\t\t\t\t\t\t}`}>\n\t\t\t\t\t\t\t{data.supportsTools === false\n\t\t\t\t\t\t\t\t? \"Unavailable\"\n\t\t\t\t\t\t\t\t: data.mcpDisabled\n\t\t\t\t\t\t\t\t\t? \"Off for session\"\n\t\t\t\t\t\t\t\t\t: runningMcpServers.length > 0\n\t\t\t\t\t\t\t\t\t\t? \"Active\"\n\t\t\t\t\t\t\t\t\t\t: \"No running servers\"\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t</span>\n\t\t\t\t\t\t<span className=\"text-sm font-medium text-[var(--text)]\">\n\t\t\t\t\t\t\t{pluralizeToolsCount(runningMcpToolCount, \"MCP tool\")}\n\t\t\t\t\t\t</span>\n\t\t\t\t\t</div>\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mt-2 leading-relaxed\">\n\t\t\t\t\t\t{pluralizeToolsCount(runningMcpServers.length, \"running server\")}\n\t\t\t\t\t\t{data.mcpDisabled ? \", disabled explicitly for this session.\" : \".\"}\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\n\t\t\t\t<div className=\"rounded border border-[var(--border)] bg-[var(--surface)] p-4\">\n\t\t\t\t\t<div className=\"text-xs uppercase tracking-wide text-[var(--muted)]\">Execution Routes</div>\n\t\t\t\t\t<div className=\"mt-2 text-sm font-medium text-[var(--text)]\">\n\t\t\t\t\t\t{routeDetails.join(\" \\u00b7 \")}\n\t\t\t\t\t</div>\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mt-2 leading-relaxed\">\n\t\t\t\t\t\t{sandbox.enabled ? `Sandbox backend: ${sandbox.backend || \"configured\"}. ` : \"\"}\n\t\t\t\t\t\t{execution.promptSymbol ? `Prompt symbol: ${execution.promptSymbol}. ` : \"\"}\n\t\t\t\t\t\tThe <code className=\"text-[var(--text)]\">exec</code> tool uses these routes rather than exposing SSH as\n\t\t\t\t\t\ta separate command runner.\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t{data.supportsTools === false\n\t\t\t\t? <div className=\"rounded border border-[var(--warn)] bg-[var(--surface2)] p-3 max-w-[1100px]\">\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] leading-relaxed\">\n\t\t\t\t\t\tTools are unavailable because the current model does not support tool calling. Switch to a tool-capable\n\t\t\t\t\t\tmodel in <strong className=\"text-[var(--text)]\">Settings {\"\\u2192\"} LLMs</strong> and refresh this page.\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t: null\n\t\t\t}\n\n\t\t\t<div className=\"grid gap-4 md:grid-cols-2 max-w-[1100px]\">\n\t\t\t\t<div className=\"rounded border border-[var(--border)] bg-[var(--surface)] p-4\">\n\t\t\t\t\t<div className=\"flex items-center justify-between gap-2 flex-wrap\">\n\t\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] m-0\">Registered Tools</h3>\n\t\t\t\t\t\t<span className=\"provider-item-badge muted\">{tools.length}</span>\n\t\t\t\t\t</div>\n\t\t\t\t\t{toolGroups.length > 0\n\t\t\t\t\t\t? <div className=\"mt-3 flex flex-col gap-3\">\n\t\t\t\t\t\t\t{toolGroups.map((group) => (\n\t\t\t\t\t\t\t\t<div key={group.label}>\n\t\t\t\t\t\t\t\t\t<div className=\"text-xs uppercase tracking-wide text-[var(--muted)] mb-2\">\n\t\t\t\t\t\t\t\t\t\t{group.label} {\"\\u00b7\"} {group.tools.length}\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t<div className=\"flex flex-col gap-2\">\n\t\t\t\t\t\t\t\t\t\t{group.tools.map((tool) => (\n\t\t\t\t\t\t\t\t\t\t\t<div\n\t\t\t\t\t\t\t\t\t\t\t\tkey={tool.name}\n\t\t\t\t\t\t\t\t\t\t\t\tclassName=\"rounded border border-[var(--border)] bg-[var(--surface2)] p-3\"\n\t\t\t\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t\t\t\t<div className=\"flex items-center justify-between gap-2 flex-wrap\">\n\t\t\t\t\t\t\t\t\t\t\t\t\t<div className=\"text-xs font-medium text-[var(--text)] break-words\">{tool.name}</div>\n\t\t\t\t\t\t\t\t\t\t\t\t\t{tool.name?.startsWith(\"mcp__\")\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t? <span className=\"provider-item-badge configured\">MCP</span>\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mt-1 leading-relaxed\">\n\t\t\t\t\t\t\t\t\t\t\t\t\t{tool.description || \"No description provided.\"}\n\t\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t))}\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t))}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t: <div className=\"text-xs text-[var(--muted)] mt-3\">\n\t\t\t\t\t\t\tNo tools are currently exposed to this session.\n\t\t\t\t\t\t</div>\n\t\t\t\t\t}\n\t\t\t\t</div>\n\n\t\t\t\t<div className=\"flex flex-col gap-4\">\n\t\t\t\t\t<div className=\"rounded border border-[var(--border)] bg-[var(--surface)] p-4\">\n\t\t\t\t\t\t<div className=\"flex items-center justify-between gap-2 flex-wrap\">\n\t\t\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] m-0\">Skills & Plugins</h3>\n\t\t\t\t\t\t\t<span className=\"provider-item-badge muted\">{skills.length}</span>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mt-3 leading-relaxed\">\n\t\t\t\t\t\t\t{pluralizeToolsCount(personalSkillCount, \"skill\")}, {pluralizeToolsCount(pluginCount, \"plugin\")}.\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t{skills.length > 0\n\t\t\t\t\t\t\t? <div className=\"mt-3 flex flex-col gap-2\">\n\t\t\t\t\t\t\t\t{skills.map((entry) => (\n\t\t\t\t\t\t\t\t\t<div\n\t\t\t\t\t\t\t\t\t\tkey={entry.name}\n\t\t\t\t\t\t\t\t\t\tclassName=\"rounded border border-[var(--border)] bg-[var(--surface2)] p-3\"\n\t\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t\t<div className=\"flex items-center justify-between gap-2 flex-wrap\">\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"text-xs font-medium text-[var(--text)]\">{entry.name}</div>\n\t\t\t\t\t\t\t\t\t\t\t<span className={`provider-item-badge ${entry.source === \"plugin\" ? \"configured\" : \"muted\"}`}>\n\t\t\t\t\t\t\t\t\t\t\t\t{entry.source === \"plugin\" ? \"Plugin\" : \"Skill\"}\n\t\t\t\t\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mt-1 leading-relaxed\">\n\t\t\t\t\t\t\t\t\t\t\t{entry.description || \"No description provided.\"}\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t))}\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: <div className=\"text-xs text-[var(--muted)] mt-3\">No skills or plugins enabled.</div>\n\t\t\t\t\t\t}\n\t\t\t\t\t</div>\n\n\t\t\t\t\t<div className=\"rounded border border-[var(--border)] bg-[var(--surface)] p-4\">\n\t\t\t\t\t\t<div className=\"flex items-center justify-between gap-2 flex-wrap\">\n\t\t\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] m-0\">MCP Servers</h3>\n\t\t\t\t\t\t\t<span className=\"provider-item-badge muted\">{mcpServers.length}</span>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t{mcpServers.length > 0\n\t\t\t\t\t\t\t? <div className=\"mt-3 flex flex-col gap-2\">\n\t\t\t\t\t\t\t\t{mcpServers.map((entry) => (\n\t\t\t\t\t\t\t\t\t<div\n\t\t\t\t\t\t\t\t\t\tkey={entry.name}\n\t\t\t\t\t\t\t\t\t\tclassName=\"rounded border border-[var(--border)] bg-[var(--surface2)] p-3\"\n\t\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t\t<div className=\"flex items-center justify-between gap-2 flex-wrap\">\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"text-xs font-medium text-[var(--text)]\">{entry.name}</div>\n\t\t\t\t\t\t\t\t\t\t\t<span className={`provider-item-badge ${entry.state === \"running\" ? \"configured\" : \"warning\"}`}>\n\t\t\t\t\t\t\t\t\t\t\t\t{entry.state || \"unknown\"}\n\t\t\t\t\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mt-1 leading-relaxed\">\n\t\t\t\t\t\t\t\t\t\t\t{pluralizeToolsCount(Number(entry.tool_count) || 0, \"tool\")}\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t))}\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: <div className=\"text-xs text-[var(--muted)] mt-3\">No MCP servers configured.</div>\n\t\t\t\t\t\t}\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nfunction SshSection(): VNode {\n\tconst [loadingSsh, setLoadingSsh] = useState(true);\n\tconst [keys, setKeys] = useState<SshKeyEntry[]>([]);\n\tconst [targets, setTargets] = useState<SshTargetEntry[]>([]);\n\tconst [sshMsg, setSshMsg] = useState<string | null>(null);\n\tconst [sshErr, setSshErr] = useState<string | null>(null);\n\tconst [busyAction, setBusyAction] = useState(\"\");\n\tconst [generateName, setGenerateName] = useState(\"\");\n\tconst [importName, setImportName] = useState(\"\");\n\tconst [importPrivateKey, setImportPrivateKey] = useState(\"\");\n\tconst [importPassphrase, setImportPassphrase] = useState(\"\");\n\tconst [targetLabel, setTargetLabel] = useState(\"\");\n\tconst [targetHost, setTargetHost] = useState(\"\");\n\tconst [targetPort, setTargetPort] = useState(\"\");\n\tconst [targetKnownHost, setTargetKnownHost] = useState(\"\");\n\tconst [targetAuthMode, setTargetAuthMode] = useState(\"managed\");\n\tconst [targetKeyId, setTargetKeyId] = useState(\"\");\n\tconst [targetIsDefault, setTargetIsDefault] = useState(true);\n\tconst [copiedKeyId, setCopiedKeyId] = useState<number | null>(null);\n\tconst [testResults, setTestResults] = useState<Record<number, TestResult>>({});\n\tconst vaultStatus = gon.get(\"vault_status\");\n\n\tfunction setMessage(message: string): void {\n\t\tsetSshMsg(message);\n\t\tsetSshErr(null);\n\t}\n\n\tfunction setError(message: string): void {\n\t\tsetSshErr(message);\n\t\tsetSshMsg(null);\n\t}\n\n\tfunction clearFlash(): void {\n\t\tsetSshMsg(null);\n\t\tsetSshErr(null);\n\t}\n\n\tfunction fetchSshStatus(): Promise<void> {\n\t\tsetLoadingSsh(true);\n\t\trerender();\n\t\treturn fetch(\"/api/ssh\")\n\t\t\t.then(async (response) => {\n\t\t\t\tif (!response.ok) {\n\t\t\t\t\tthrow new Error(localizedApiErrorMessage(await response.json(), \"Failed to load SSH settings\"));\n\t\t\t\t}\n\t\t\t\treturn response.json();\n\t\t\t})\n\t\t\t.then((data: { keys?: SshKeyEntry[]; targets?: SshTargetEntry[] }) => {\n\t\t\t\tsetKeys(data.keys || []);\n\t\t\t\tsetTargets(data.targets || []);\n\t\t\t\tif (!targetKeyId && (data.keys || []).length > 0) {\n\t\t\t\t\tsetTargetKeyId(String(data.keys![0].id));\n\t\t\t\t}\n\t\t\t\tsetLoadingSsh(false);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((error: Error) => {\n\t\t\t\tsetLoadingSsh(false);\n\t\t\t\tsetError(error.message);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tuseEffect(() => {\n\t\tfetchSshStatus();\n\t}, []);\n\n\tfunction runSshAction(actionKey: string, url: string, payload: Record<string, unknown> | null, successMessage: string, afterSuccess?: (data: unknown) => void | Promise<void>): Promise<void> {\n\t\tclearFlash();\n\t\tsetBusyAction(actionKey);\n\t\trerender();\n\t\treturn fetch(url, {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: payload ? JSON.stringify(payload) : \"{}\",\n\t\t})\n\t\t\t.then(async (response) => {\n\t\t\t\tif (!response.ok) {\n\t\t\t\t\tthrow new Error(localizedApiErrorMessage(await response.json(), \"SSH action failed\"));\n\t\t\t\t}\n\t\t\t\treturn response.json().catch(() => ({}));\n\t\t\t})\n\t\t\t.then(async (data: unknown) => {\n\t\t\t\tif (afterSuccess) await afterSuccess(data);\n\t\t\t\tsetMessage(successMessage);\n\t\t\t\tawait fetchSshStatus();\n\t\t\t})\n\t\t\t.catch((error: Error) => {\n\t\t\t\tsetError(error.message);\n\t\t\t})\n\t\t\t.finally(() => {\n\t\t\t\tsetBusyAction(\"\");\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onGenerateKey(e: Event): void {\n\t\te.preventDefault();\n\t\tconst name = generateName.trim();\n\t\tif (!name) {\n\t\t\tsetError(\"Key name is required.\");\n\t\t\treturn;\n\t\t}\n\t\trunSshAction(\"generate-key\", \"/api/ssh/keys/generate\", { name }, \"Deploy key generated.\", () => {\n\t\t\tsetGenerateName(\"\");\n\t\t});\n\t}\n\n\tfunction onImportKey(e: Event): void {\n\t\te.preventDefault();\n\t\tconst name = importName.trim();\n\t\tif (!name) {\n\t\t\tsetError(\"Key name is required.\");\n\t\t\treturn;\n\t\t}\n\t\tif (!importPrivateKey.trim()) {\n\t\t\tsetError(\"Private key is required.\");\n\t\t\treturn;\n\t\t}\n\t\trunSshAction(\n\t\t\t\"import-key\",\n\t\t\t\"/api/ssh/keys/import\",\n\t\t\t{\n\t\t\t\tname,\n\t\t\t\tprivate_key: importPrivateKey,\n\t\t\t\tpassphrase: importPassphrase.trim() ? importPassphrase : null,\n\t\t\t},\n\t\t\t\"Private key imported.\",\n\t\t\t() => {\n\t\t\t\tsetImportName(\"\");\n\t\t\t\tsetImportPrivateKey(\"\");\n\t\t\t\tsetImportPassphrase(\"\");\n\t\t\t},\n\t\t);\n\t}\n\n\tfunction onDeleteKey(id: number): void {\n\t\tclearFlash();\n\t\tsetBusyAction(`delete-key:${id}`);\n\t\trerender();\n\t\tfetch(`/api/ssh/keys/${id}`, { method: \"DELETE\" })\n\t\t\t.then(async (response) => {\n\t\t\t\tif (!response.ok) {\n\t\t\t\t\tthrow new Error(localizedApiErrorMessage(await response.json(), \"Failed to delete key\"));\n\t\t\t\t}\n\t\t\t\tsetMessage(\"SSH key deleted.\");\n\t\t\t\tawait fetchSshStatus();\n\t\t\t})\n\t\t\t.catch((error: Error) => setError(error.message))\n\t\t\t.finally(() => {\n\t\t\t\tsetBusyAction(\"\");\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onCreateTarget(e: Event): void {\n\t\te.preventDefault();\n\t\tconst label = targetLabel.trim();\n\t\tconst target = targetHost.trim();\n\t\tconst port = targetPort.trim() ? Number.parseInt(targetPort.trim(), 10) : null;\n\t\tconst keyId = targetAuthMode === \"managed\" && targetKeyId ? Number.parseInt(targetKeyId, 10) : null;\n\t\tif (!label) {\n\t\t\tsetError(\"Target label is required.\");\n\t\t\treturn;\n\t\t}\n\t\tif (!target) {\n\t\t\tsetError(\"SSH target is required.\");\n\t\t\treturn;\n\t\t}\n\t\tif (targetAuthMode === \"managed\" && !keyId) {\n\t\t\tsetError(\"Choose a managed SSH key for this target.\");\n\t\t\treturn;\n\t\t}\n\t\tif (Number.isNaN(port)) {\n\t\t\tsetError(\"Port must be a valid number.\");\n\t\t\treturn;\n\t\t}\n\t\trunSshAction(\n\t\t\t\"create-target\",\n\t\t\t\"/api/ssh/targets\",\n\t\t\t{\n\t\t\t\tlabel,\n\t\t\t\ttarget,\n\t\t\t\tport,\n\t\t\t\tauth_mode: targetAuthMode,\n\t\t\t\tkey_id: keyId,\n\t\t\t\tknown_host: targetKnownHost.trim() ? targetKnownHost : null,\n\t\t\t\tis_default: targetIsDefault,\n\t\t\t},\n\t\t\t\"SSH target saved.\",\n\t\t\t() => {\n\t\t\t\tsetTargetLabel(\"\");\n\t\t\t\tsetTargetHost(\"\");\n\t\t\t\tsetTargetPort(\"\");\n\t\t\t\tsetTargetKnownHost(\"\");\n\t\t\t\tsetTargetIsDefault(targets.length === 0);\n\t\t\t},\n\t\t);\n\t}\n\n\tfunction onScanCreateTargetHost(): void {\n\t\tconst target = targetHost.trim();\n\t\tconst port = targetPort.trim() ? Number.parseInt(targetPort.trim(), 10) : null;\n\t\tif (!target) {\n\t\t\tsetError(\"SSH target is required before scanning.\");\n\t\t\treturn;\n\t\t}\n\t\tif (Number.isNaN(port)) {\n\t\t\tsetError(\"Port must be a valid number.\");\n\t\t\treturn;\n\t\t}\n\t\tclearFlash();\n\t\tsetBusyAction(\"scan-create-target\");\n\t\trerender();\n\t\tfetch(\"/api/ssh/host-key/scan\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ target, port }),\n\t\t})\n\t\t\t.then(async (response) => {\n\t\t\t\tif (!response.ok) {\n\t\t\t\t\tthrow new Error(localizedApiErrorMessage(await response.json(), \"Failed to scan host key\"));\n\t\t\t\t}\n\t\t\t\treturn response.json();\n\t\t\t})\n\t\t\t.then((data: { known_host?: string; host?: string; port?: number }) => {\n\t\t\t\tsetTargetKnownHost(data.known_host || \"\");\n\t\t\t\tsetMessage(`Scanned host key for ${data.host}${data.port ? `:${data.port}` : \"\"}.`);\n\t\t\t\tshowToast(\"Host key scanned\", \"success\");\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((error: Error) => {\n\t\t\t\tsetError(error.message);\n\t\t\t\tshowToast(error.message, \"error\");\n\t\t\t})\n\t\t\t.finally(() => {\n\t\t\t\tsetBusyAction(\"\");\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onDeleteTarget(id: number): void {\n\t\tclearFlash();\n\t\tsetBusyAction(`delete-target:${id}`);\n\t\trerender();\n\t\tfetch(`/api/ssh/targets/${id}`, { method: \"DELETE\" })\n\t\t\t.then(async (response) => {\n\t\t\t\tif (!response.ok) {\n\t\t\t\t\tthrow new Error(localizedApiErrorMessage(await response.json(), \"Failed to delete target\"));\n\t\t\t\t}\n\t\t\t\tsetMessage(\"SSH target deleted.\");\n\t\t\t\tawait fetchSshStatus();\n\t\t\t})\n\t\t\t.catch((error: Error) => setError(error.message))\n\t\t\t.finally(() => {\n\t\t\t\tsetBusyAction(\"\");\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onSetDefaultTarget(id: number): void {\n\t\trunSshAction(`default-target:${id}`, `/api/ssh/targets/${id}/default`, null, \"Default SSH target updated.\");\n\t}\n\n\tfunction onTestTarget(id: number): void {\n\t\tclearFlash();\n\t\tsetBusyAction(`test-target:${id}`);\n\t\trerender();\n\t\tfetch(`/api/ssh/targets/${id}/test`, { method: \"POST\" })\n\t\t\t.then(async (response) => {\n\t\t\t\tif (!response.ok) {\n\t\t\t\t\tthrow new Error(localizedApiErrorMessage(await response.json(), \"SSH connectivity test failed\"));\n\t\t\t\t}\n\t\t\t\treturn response.json();\n\t\t\t})\n\t\t\t.then((data: TestResult) => {\n\t\t\t\tsetTestResults({\n\t\t\t\t\t...testResults,\n\t\t\t\t\t[id]: data,\n\t\t\t\t});\n\t\t\t\tsetMessage(\n\t\t\t\t\tdata.reachable ? \"SSH connectivity test passed.\" : data.failure_hint || \"SSH connectivity test failed.\",\n\t\t\t\t);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((error: Error) => setError(error.message))\n\t\t\t.finally(() => {\n\t\t\t\tsetBusyAction(\"\");\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onScanAndPinTarget(entry: SshTargetEntry): void {\n\t\tclearFlash();\n\t\tsetBusyAction(`pin-target:${entry.id}`);\n\t\trerender();\n\t\tfetch(\"/api/ssh/host-key/scan\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ target: entry.target, port: entry.port ?? null }),\n\t\t})\n\t\t\t.then(async (response) => {\n\t\t\t\tif (!response.ok) {\n\t\t\t\t\tthrow new Error(localizedApiErrorMessage(await response.json(), \"Failed to scan host key\"));\n\t\t\t\t}\n\t\t\t\treturn response.json();\n\t\t\t})\n\t\t\t.then(async (scanData: { known_host?: string; host?: string; port?: number }) => {\n\t\t\t\tconst pinResponse = await fetch(`/api/ssh/targets/${entry.id}/pin`, {\n\t\t\t\t\tmethod: \"POST\",\n\t\t\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\t\t\tbody: JSON.stringify({ known_host: scanData.known_host }),\n\t\t\t\t});\n\t\t\t\tif (!pinResponse.ok) {\n\t\t\t\t\tthrow new Error(localizedApiErrorMessage(await pinResponse.json(), \"Failed to pin host key\"));\n\t\t\t\t}\n\t\t\t\tsetMessage(\n\t\t\t\t\t`${entry.known_host ? \"Refreshed\" : \"Pinned\"} host key for ${scanData.host}${scanData.port ? `:${scanData.port}` : \"\"}.`,\n\t\t\t\t);\n\t\t\t\tshowToast(entry.known_host ? \"Host pin refreshed\" : \"Host pinned\", \"success\");\n\t\t\t\tawait fetchSshStatus();\n\t\t\t})\n\t\t\t.catch((error: Error) => {\n\t\t\t\tsetError(error.message);\n\t\t\t\tshowToast(error.message, \"error\");\n\t\t\t})\n\t\t\t.finally(() => {\n\t\t\t\tsetBusyAction(\"\");\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onClearTargetPin(entry: SshTargetEntry): void {\n\t\tclearFlash();\n\t\tsetBusyAction(`clear-pin:${entry.id}`);\n\t\trerender();\n\t\tfetch(`/api/ssh/targets/${entry.id}/pin`, { method: \"DELETE\" })\n\t\t\t.then(async (response) => {\n\t\t\t\tif (!response.ok) {\n\t\t\t\t\tthrow new Error(localizedApiErrorMessage(await response.json(), \"Failed to clear host pin\"));\n\t\t\t\t}\n\t\t\t\tsetMessage(`Cleared host pin for ${entry.label}.`);\n\t\t\t\tshowToast(\"Host pin cleared\", \"success\");\n\t\t\t\tawait fetchSshStatus();\n\t\t\t})\n\t\t\t.catch((error: Error) => {\n\t\t\t\tsetError(error.message);\n\t\t\t\tshowToast(error.message, \"error\");\n\t\t\t})\n\t\t\t.finally(() => {\n\t\t\t\tsetBusyAction(\"\");\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onCopyPublicKey(entry: SshKeyEntry): void {\n\t\tnavigator.clipboard\n\t\t\t.writeText(entry.public_key || \"\")\n\t\t\t.then(() => {\n\t\t\t\tsetCopiedKeyId(entry.id);\n\t\t\t\tsetTimeout(() => {\n\t\t\t\t\tsetCopiedKeyId(null);\n\t\t\t\t\trerender();\n\t\t\t\t}, 1500);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((error: Error) => setError(error.message));\n\t}\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">SSH</h2>\n\t\t\t<div className=\"rounded border border-[var(--border)] bg-[var(--surface2)] p-3 max-w-[760px]\">\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] m-0 mb-1.5 leading-relaxed\">\n\t\t\t\t\tManage outbound SSH keys and named remote exec targets. Generated deploy keys use <strong className=\"text-[var(--text)]\">Ed25519</strong>,\n\t\t\t\t\tthe private half stays inside Moltis,\n\t\t\t\t\tand the public half is shown so you can install it in <code className=\"text-[var(--text)]\">authorized_keys</code>.\n\t\t\t\t</p>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] m-0 leading-relaxed\">\n\t\t\t\t\tCurrent auth path:\n\t\t\t\t\t<strong className=\"text-[var(--text)]\">\n\t\t\t\t\t\t{vaultStatus === \"unsealed\"\n\t\t\t\t\t\t\t? \" vault-backed managed keys are available\"\n\t\t\t\t\t\t\t: vaultStatus === \"sealed\"\n\t\t\t\t\t\t\t\t? \" vault is locked, managed keys cannot be used until unlocked\"\n\t\t\t\t\t\t\t\t: \" system OpenSSH remains available, managed keys stay plaintext until the vault is enabled\"\n\t\t\t\t\t\t}\n\t\t\t\t\t</strong>\n\t\t\t\t</p>\n\t\t\t</div>\n\n\t\t\t{sshMsg ? <div className=\"text-xs text-[var(--accent)]\">{sshMsg}</div> : null}\n\t\t\t{sshErr ? <div className=\"text-xs text-[var(--error)]\">{sshErr}</div> : null}\n\n\t\t\t<div className=\"grid gap-4 lg:grid-cols-2 max-w-[1100px]\">\n\t\t\t\t<div className=\"rounded border border-[var(--border)] bg-[var(--surface)] p-4\">\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] m-0 mb-2\">Deploy Keys</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)] m-0 mb-3\">\n\t\t\t\t\t\tGenerate a new keypair for a host, or import an existing private key. Passphrase-protected imports are decrypted once and then stored under Moltis control.\n\t\t\t\t\t</p>\n\t\t\t\t\t<div className=\"mb-3 rounded border border-[var(--border)] bg-[var(--surface2)] p-2 text-xs text-[var(--muted)] leading-relaxed\">\n\t\t\t\t\t\tRecommended flow: generate one deploy key per remote host, copy the public key below, add it to that\n\t\t\t\t\t\thost&apos;s <code className=\"text-[var(--text)]\">~/.ssh/authorized_keys</code>, then pin the host key with\n\t\t\t\t\t\t<code className=\"text-[var(--text)]\">ssh-keyscan -H host</code> when creating the target.\n\t\t\t\t\t</div>\n\t\t\t\t\t<form onSubmit={onGenerateKey} className=\"flex flex-col gap-2 mb-4\">\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Generate deploy key</label>\n\t\t\t\t\t\t<div className=\"flex gap-2 flex-wrap\">\n\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\tclassName=\"provider-key-input flex-1 min-w-[180px]\"\n\t\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\t\tvalue={generateName}\n\t\t\t\t\t\t\t\tonInput={(e: Event) => setGenerateName((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\tplaceholder=\"production-box\"\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t<button type=\"submit\" className=\"provider-btn\" disabled={busyAction === \"generate-key\"}>\n\t\t\t\t\t\t\t\t{busyAction === \"generate-key\" ? \"Generating\\u2026\" : \"Generate\"}\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</form>\n\n\t\t\t\t\t<form onSubmit={onImportKey} className=\"flex flex-col gap-2\">\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Import private key</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\tvalue={importName}\n\t\t\t\t\t\t\tonInput={(e: Event) => setImportName((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\tplaceholder=\"existing-deploy-key\"\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<textarea\n\t\t\t\t\t\t\tclassName=\"provider-key-input min-h-[140px] font-mono text-xs\"\n\t\t\t\t\t\t\tvalue={importPrivateKey}\n\t\t\t\t\t\t\tonInput={(e: Event) => setImportPrivateKey((e.target as HTMLTextAreaElement).value)}\n\t\t\t\t\t\t\tplaceholder=\"-----BEGIN OPENSSH PRIVATE KEY-----\"\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\ttype=\"password\"\n\t\t\t\t\t\t\tvalue={importPassphrase}\n\t\t\t\t\t\t\tonInput={(e: Event) => setImportPassphrase((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\tplaceholder=\"Optional import passphrase\"\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<button type=\"submit\" className=\"provider-btn self-start\" disabled={busyAction === \"import-key\"}>\n\t\t\t\t\t\t\t{busyAction === \"import-key\" ? \"Importing\\u2026\" : \"Import Key\"}\n\t\t\t\t\t\t</button>\n\t\t\t\t\t</form>\n\n\t\t\t\t\t<div className=\"mt-4 flex flex-col gap-2\">\n\t\t\t\t\t\t{loadingSsh\n\t\t\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\">Loading keys{\"\\u2026\"}</div>\n\t\t\t\t\t\t\t: keys.length === 0\n\t\t\t\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\">No managed SSH keys yet.</div>\n\t\t\t\t\t\t\t\t: keys.map((entry) => (\n\t\t\t\t\t\t\t\t\t<div className=\"provider-item items-start gap-4\" key={entry.id}>\n\t\t\t\t\t\t\t\t\t\t<div className=\"flex-1 min-w-0\">\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"provider-item-name\">{entry.name}</div>\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] break-all mt-1\">\n\t\t\t\t\t\t\t\t\t\t\t\t<span className=\"text-[var(--text)]\">Fingerprint (SHA256):</span> {entry.fingerprint}\n\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mt-1\">\n\t\t\t\t\t\t\t\t\t\t\t\t{entry.encrypted ? \"Encrypted in vault\" : \"Stored plaintext until the vault is available\"}\n\t\t\t\t\t\t\t\t\t\t\t\t{(entry.target_count ?? 0) > 0 ? `, used by ${entry.target_count} target${entry.target_count === 1 ? \"\" : \"s\"}` : \"\"}\n\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t<pre className=\"mt-3 whitespace-pre-wrap break-all rounded border border-[var(--border)] bg-[var(--surface2)] p-2 text-[11px] leading-relaxed text-[var(--muted)]\">{entry.public_key}</pre>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<div className=\"flex flex-col gap-2 shrink-0 self-start\">\n\t\t\t\t\t\t\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-secondary\" onClick={() => onCopyPublicKey(entry)}>\n\t\t\t\t\t\t\t\t\t\t\t\t{copiedKeyId === entry.id ? \"Copied\" : \"Copy Public Key\"}\n\t\t\t\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-danger\"\n\t\t\t\t\t\t\t\t\t\t\t\tonClick={() => onDeleteKey(entry.id)}\n\t\t\t\t\t\t\t\t\t\t\t\tdisabled={busyAction === `delete-key:${entry.id}` || (entry.target_count ?? 0) > 0}\n\t\t\t\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t\t\t\t{busyAction === `delete-key:${entry.id}` ? \"Deleting\\u2026\" : \"Delete\"}\n\t\t\t\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t))\n\t\t\t\t\t\t}\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\n\t\t\t\t<div className=\"rounded border border-[var(--border)] bg-[var(--surface)] p-4\">\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] m-0 mb-2\">SSH Targets</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)] m-0 mb-3\">\n\t\t\t\t\t\tAdd named hosts for remote execution. Targets can use your system OpenSSH setup or one of the managed keys above.\n\t\t\t\t\t</p>\n\t\t\t\t\t<form onSubmit={onCreateTarget} className=\"flex flex-col gap-2 mb-4\">\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\tvalue={targetLabel}\n\t\t\t\t\t\t\tonInput={(e: Event) => setTargetLabel((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\tplaceholder=\"prod-box\"\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\tvalue={targetHost}\n\t\t\t\t\t\t\tonInput={(e: Event) => setTargetHost((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\tplaceholder=\"deploy@example.com\"\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<div className=\"flex gap-2 flex-wrap\">\n\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\tclassName=\"provider-key-input w-[120px]\"\n\t\t\t\t\t\t\t\ttype=\"number\"\n\t\t\t\t\t\t\t\tmin={1}\n\t\t\t\t\t\t\t\tmax={65535}\n\t\t\t\t\t\t\t\tvalue={targetPort}\n\t\t\t\t\t\t\t\tonInput={(e: Event) => setTargetPort((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\tplaceholder=\"22\"\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t<select\n\t\t\t\t\t\t\t\tclassName=\"provider-key-input flex-1 min-w-[180px]\"\n\t\t\t\t\t\t\t\tvalue={targetAuthMode}\n\t\t\t\t\t\t\t\tonInput={(e: Event) => setTargetAuthMode((e.target as HTMLSelectElement).value)}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t<option value=\"managed\">Managed key</option>\n\t\t\t\t\t\t\t\t<option value=\"system\">System OpenSSH</option>\n\t\t\t\t\t\t\t</select>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<textarea\n\t\t\t\t\t\t\tclassName=\"provider-key-input min-h-[96px] font-mono text-xs\"\n\t\t\t\t\t\t\tvalue={targetKnownHost}\n\t\t\t\t\t\t\tonInput={(e: Event) => setTargetKnownHost((e.target as HTMLTextAreaElement).value)}\n\t\t\t\t\t\t\tplaceholder=\"Optional known_hosts line from ssh-keyscan -H host\"\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\tIf you paste a <code className=\"text-[var(--text)]\">known_hosts</code> line here, Moltis will use strict host-key checking for this target instead of trusting your global SSH config.\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<button\n\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary self-start\"\n\t\t\t\t\t\t\tonClick={onScanCreateTargetHost}\n\t\t\t\t\t\t\tdisabled={busyAction === \"scan-create-target\"}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t{busyAction === \"scan-create-target\" ? \"Scanning\\u2026\" : \"Scan Host Key\"}\n\t\t\t\t\t\t</button>\n\t\t\t\t\t\t{targetAuthMode === \"managed\"\n\t\t\t\t\t\t\t? <select\n\t\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\t\tvalue={targetKeyId}\n\t\t\t\t\t\t\t\tonInput={(e: Event) => setTargetKeyId((e.target as HTMLSelectElement).value)}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t<option value=\"\">Choose a managed key</option>\n\t\t\t\t\t\t\t\t{keys.map((entry) => <option key={entry.id} value={entry.id}>{entry.name}</option>)}\n\t\t\t\t\t\t\t</select>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\t\t\t\t\t\t{targetAuthMode === \"managed\" && keys.length === 0\n\t\t\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\tGenerate or import a deploy key first. Moltis cannot connect with a managed target until a private key exists.\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)] flex items-center gap-2\">\n\t\t\t\t\t\t\t<input type=\"checkbox\" checked={targetIsDefault} onInput={(e: Event) => setTargetIsDefault((e.target as HTMLInputElement).checked)} />\n\t\t\t\t\t\t\tSet as default remote SSH target\n\t\t\t\t\t\t</label>\n\t\t\t\t\t\t<button\n\t\t\t\t\t\t\ttype=\"submit\"\n\t\t\t\t\t\t\tclassName=\"provider-btn self-start\"\n\t\t\t\t\t\t\tdisabled={busyAction === \"create-target\" || (targetAuthMode === \"managed\" && keys.length === 0)}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t{busyAction === \"create-target\" ? \"Saving\\u2026\" : \"Add Target\"}\n\t\t\t\t\t\t</button>\n\t\t\t\t\t</form>\n\n\t\t\t\t\t<div className=\"flex flex-col gap-2\">\n\t\t\t\t\t\t{loadingSsh\n\t\t\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\">Loading targets{\"\\u2026\"}</div>\n\t\t\t\t\t\t\t: targets.length === 0\n\t\t\t\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\">No SSH targets configured.</div>\n\t\t\t\t\t\t\t\t: targets.map((entry) => (\n\t\t\t\t\t\t\t\t\t<div className=\"provider-item\" key={entry.id}>\n\t\t\t\t\t\t\t\t\t\t<div className=\"flex-1 min-w-0\">\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"provider-item-name flex items-center gap-2 flex-wrap\">\n\t\t\t\t\t\t\t\t\t\t\t\t<span>{entry.label}</span>\n\t\t\t\t\t\t\t\t\t\t\t\t{entry.is_default ? <span className=\"provider-item-badge configured\">Default</span> : null}\n\t\t\t\t\t\t\t\t\t\t\t\t<span className=\"provider-item-badge muted\">{entry.auth_mode === \"managed\" ? \"Managed key\" : \"System SSH\"}</span>\n\t\t\t\t\t\t\t\t\t\t\t\t{entry.known_host ? <span className=\"provider-item-badge configured\">Host pinned</span> : <span className=\"provider-item-badge warning\">Uses global known_hosts</span>}\n\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] break-all\">\n\t\t\t\t\t\t\t\t\t\t\t\t{entry.target}{entry.port ? `:${entry.port}` : \"\"}\n\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\t\t\t\t\t{entry.key_name ? `Key: ${entry.key_name}` : \"Uses your local ssh config / agent\"}\n\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t{testResults[entry.id]\n\t\t\t\t\t\t\t\t\t\t\t\t? <div className=\"mt-1\">\n\t\t\t\t\t\t\t\t\t\t\t\t\t<div className={`text-xs ${testResults[entry.id].reachable ? \"text-[var(--accent)]\" : \"text-[var(--error)]\"}`}>\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t{testResults[entry.id].reachable ? \"Reachable\" : \"Unreachable\"}\n\t\t\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t\t\t{testResults[entry.id].failure_hint\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t? <div className=\"text-xs text-[var(--text-muted)] mt-1\">\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tHint: {testResults[entry.id].failure_hint}\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<div className=\"flex flex-col gap-2\">\n\t\t\t\t\t\t\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-secondary\" onClick={() => onTestTarget(entry.id)} disabled={busyAction === `test-target:${entry.id}`}>\n\t\t\t\t\t\t\t\t\t\t\t\t{busyAction === `test-target:${entry.id}` ? \"Testing\\u2026\" : \"Test\"}\n\t\t\t\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\t\t\t\t\t\t\t\tonClick={() => onScanAndPinTarget(entry)}\n\t\t\t\t\t\t\t\t\t\t\t\tdisabled={busyAction === `pin-target:${entry.id}`}\n\t\t\t\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t\t\t\t{busyAction === `pin-target:${entry.id}` ? \"Scanning\\u2026\" : entry.known_host ? \"Refresh Pin\" : \"Scan & Pin\"}\n\t\t\t\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t\t\t\t\t{entry.known_host\n\t\t\t\t\t\t\t\t\t\t\t\t? <button\n\t\t\t\t\t\t\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tonClick={() => onClearTargetPin(entry)}\n\t\t\t\t\t\t\t\t\t\t\t\t\tdisabled={busyAction === `clear-pin:${entry.id}`}\n\t\t\t\t\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t\t\t\t\t{busyAction === `clear-pin:${entry.id}` ? \"Clearing\\u2026\" : \"Clear Pin\"}\n\t\t\t\t\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\t\t\t{entry.is_default\n\t\t\t\t\t\t\t\t\t\t\t\t? null\n\t\t\t\t\t\t\t\t\t\t\t\t: <button type=\"button\" className=\"provider-btn provider-btn-secondary\" onClick={() => onSetDefaultTarget(entry.id)} disabled={busyAction === `default-target:${entry.id}`}>Make Default</button>\n\t\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-danger\" onClick={() => onDeleteTarget(entry.id)} disabled={busyAction === `delete-target:${entry.id}`}>\n\t\t\t\t\t\t\t\t\t\t\t\t{busyAction === `delete-target:${entry.id}` ? \"Deleting\\u2026\" : \"Delete\"}\n\t\t\t\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t))\n\t\t\t\t\t\t}\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// ── b64/buf helpers (used by passkey registration) ──────────\n\nfunction b64ToBuf(b64: string): ArrayBuffer {\n\tlet str = b64.replace(/-/g, \"+\").replace(/_/g, \"/\");\n\twhile (str.length % 4) str += \"=\";\n\tconst bin = atob(str);\n\tconst buf = new Uint8Array(bin.length);\n\tfor (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);\n\treturn buf.buffer;\n}\n\nfunction bufToB64(buf: ArrayBuffer): string {\n\tconst bytes = new Uint8Array(buf);\n\tlet str = \"\";\n\tfor (const b of bytes) str += String.fromCharCode(b);\n\treturn btoa(str).replace(/\\+/g, \"-\").replace(/\\//g, \"_\").replace(/=+$/, \"\");\n}\n\n// ── OpenClaw Import section ───────────────────────────────────\n\ninterface ScanResult {\n\tdetected?: boolean;\n\thome_dir?: string;\n\ttelegram_accounts?: number;\n\tdiscord_accounts?: number;\n\tunsupported_channels?: string[];\n\tidentity_available?: boolean;\n\tproviders_available?: boolean;\n\tskills_count?: number;\n\tmemory_available?: boolean;\n\tmemory_files_count?: number;\n\tchannels_available?: boolean;\n\tsessions_count?: number;\n}\n\ninterface ImportCategory {\n\tcategory: string;\n\tstatus: string;\n\titems_imported: number;\n\titems_skipped: number;\n}\n\ninterface ImportResult {\n\tcategories?: ImportCategory[];\n}\n\ninterface ImportSelection {\n\tidentity: boolean;\n\tproviders: boolean;\n\tskills: boolean;\n\tmemory: boolean;\n\tchannels: boolean;\n\tsessions: boolean;\n\t[key: string]: boolean;\n}\n\nfunction OpenClawImportSection(): VNode {\n\tconst [importLoading, setImportLoading] = useState(true);\n\tconst [scan, setScan] = useState<ScanResult | null>(null);\n\tconst [importing, setImporting] = useState(false);\n\tconst [done, setDone] = useState(false);\n\tconst [result, setResult] = useState<ImportResult | null>(null);\n\tconst [error, setError] = useState<string | null>(null);\n\tconst [selection, setSelection] = useState<ImportSelection>({\n\t\tidentity: true,\n\t\tproviders: true,\n\t\tskills: true,\n\t\tmemory: true,\n\t\tchannels: true,\n\t\tsessions: true,\n\t});\n\n\tuseEffect(() => {\n\t\tlet cancelled = false;\n\t\tsendRpc(\"openclaw.scan\", {}).then((res: RpcResponse) => {\n\t\t\tif (cancelled) return;\n\t\t\tif (res?.ok) setScan(res.payload as ScanResult);\n\t\t\telse setError(\"Failed to scan OpenClaw installation\");\n\t\t\tsetImportLoading(false);\n\t\t\trerender();\n\t\t});\n\t\treturn () => {\n\t\t\tcancelled = true;\n\t\t};\n\t}, []);\n\n\tfunction toggleCategory(key: string): void {\n\t\tsetSelection((prev) => {\n\t\t\tconst next = Object.assign({}, prev);\n\t\t\tnext[key] = !prev[key];\n\t\t\treturn next;\n\t\t});\n\t}\n\n\tfunction doImport(): void {\n\t\tsetImporting(true);\n\t\tsetError(null);\n\t\tsendRpc(\"openclaw.import\", selection).then((res: RpcResponse) => {\n\t\t\tsetImporting(false);\n\t\t\tif (res?.ok) {\n\t\t\t\tsetResult(res.payload as ImportResult);\n\t\t\t\tsetDone(true);\n\t\t\t} else {\n\t\t\t\tsetError((res?.error as { message?: string })?.message || \"Import failed\");\n\t\t\t}\n\t\t\trerender();\n\t\t});\n\t}\n\n\tif (importLoading) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">OpenClaw Import</h2>\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Scanning{\"\\u2026\"}</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\tif (!scan?.detected) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">OpenClaw Import</h2>\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">No OpenClaw installation detected.</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\tconst telegramAccounts = Number(scan.telegram_accounts) || 0;\n\tconst discordAccounts = Number(scan.discord_accounts) || 0;\n\tconst channelParts: string[] = [];\n\tif (telegramAccounts > 0) channelParts.push(`${telegramAccounts} Telegram account(s)`);\n\tif (discordAccounts > 0) channelParts.push(`${discordAccounts} Discord account(s)`);\n\tconst channelDetail = channelParts.length > 0 ? channelParts.join(\", \") : null;\n\tconst unsupportedChannels = (scan.unsupported_channels || []).filter(\n\t\t(channel) => String(channel).toLowerCase() !== \"discord\",\n\t);\n\n\tconst categories = [\n\t\t{ key: \"identity\", label: \"Identity\", available: scan.identity_available, detail: undefined as string | undefined },\n\t\t{ key: \"providers\", label: \"Providers\", available: scan.providers_available, detail: undefined as string | undefined },\n\t\t{ key: \"skills\", label: \"Skills\", available: (scan.skills_count || 0) > 0, detail: `${scan.skills_count} skill(s)` },\n\t\t{\n\t\t\tkey: \"memory\",\n\t\t\tlabel: \"Memory\",\n\t\t\tavailable: scan.memory_available,\n\t\t\tdetail: `${scan.memory_files_count} memory file(s)`,\n\t\t},\n\t\t{\n\t\t\tkey: \"channels\",\n\t\t\tlabel: \"Channels\",\n\t\t\tavailable: scan.channels_available,\n\t\t\tdetail: channelDetail || undefined,\n\t\t},\n\t\t{\n\t\t\tkey: \"sessions\",\n\t\t\tlabel: \"Sessions\",\n\t\t\tavailable: (scan.sessions_count || 0) > 0,\n\t\t\tdetail: `${scan.sessions_count} session(s)`,\n\t\t},\n\t];\n\tconst anySelected = categories.some((c) => c.available && selection[c.key]);\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">OpenClaw Import</h2>\n\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed\" style={{ maxWidth: \"600px\", margin: 0 }}>\n\t\t\t\tImport data from your OpenClaw installation at <code className=\"text-[var(--text)]\">{scan.home_dir}</code>.\n\t\t\t\tThis is a read-only copy {\"\\u2014\"} your OpenClaw files will not be modified or removed.\n\t\t\t\tYou can keep using both side by side and re-import whenever you like.\n\t\t\t</p>\n\t\t\t{error\n\t\t\t\t? <div role=\"alert\" className=\"alert-error-text whitespace-pre-line\" style={{ maxWidth: \"600px\" }}>\n\t\t\t\t\t<span className=\"text-[var(--error)] font-medium\">Error:</span> {error}\n\t\t\t\t</div>\n\t\t\t\t: null\n\t\t\t}\n\t\t\t{done && result\n\t\t\t\t? <div className=\"flex flex-col gap-2\" style={{ maxWidth: \"600px\" }}>\n\t\t\t\t\t<div className=\"text-sm font-medium text-[var(--ok)]\">Import complete: {(result.categories || []).reduce((sum, cat) => sum + (Number(cat.items_imported) || 0), 0)} item(s) imported.</div>\n\t\t\t\t\t{result.categories\n\t\t\t\t\t\t? <div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t\t{result.categories.map((cat) => (\n\t\t\t\t\t\t\t\t<div key={cat.category} className=\"text-xs text-[var(--text)]\">\n\t\t\t\t\t\t\t\t\t<span className=\"font-mono\">[{cat.status === \"success\" ? \"\\u2713\" : cat.status === \"partial\" ? \"~\" : cat.status === \"skipped\" ? \"-\" : \"!\"}]</span>\n\t\t\t\t\t\t\t\t\t{\" \"}{cat.category}: {cat.items_imported} imported, {cat.items_skipped} skipped\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t))}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t: null\n\t\t\t\t\t}\n\t\t\t\t\t<button className=\"provider-btn provider-btn-secondary mt-2\" style={{ width: \"fit-content\" }} onClick={() => {\n\t\t\t\t\t\tsetDone(false);\n\t\t\t\t\t\tsetResult(null);\n\t\t\t\t\t\trerender();\n\t\t\t\t\t}}>\n\t\t\t\t\t\tImport Again\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t\t: <div className=\"flex flex-col gap-2\" style={{ maxWidth: \"400px\" }}>\n\t\t\t\t\t{categories.map((cat) => (\n\t\t\t\t\t\t<label\n\t\t\t\t\t\t\tkey={cat.key}\n\t\t\t\t\t\t\tclassName={`flex items-center gap-2 text-sm cursor-pointer ${cat.available ? \"text-[var(--text)]\" : \"text-[var(--muted)] opacity-60\"}`}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\ttype=\"checkbox\"\n\t\t\t\t\t\t\t\tchecked={selection[cat.key] && cat.available}\n\t\t\t\t\t\t\t\tdisabled={!cat.available || importing}\n\t\t\t\t\t\t\t\tonChange={() => toggleCategory(cat.key)}\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t<span>{cat.label}</span>\n\t\t\t\t\t\t\t{cat.detail && cat.available ? <span className=\"text-xs text-[var(--muted)]\">({cat.detail})</span> : null}\n\t\t\t\t\t\t\t{cat.available ? null : <span className=\"text-xs text-[var(--muted)]\">(not found)</span>}\n\t\t\t\t\t\t</label>\n\t\t\t\t\t))}\n\t\t\t\t</div>\n\t\t\t}\n\t\t\t{!done && unsupportedChannels.length > 0\n\t\t\t\t? <p className=\"text-xs text-[var(--muted)]\" style={{ maxWidth: \"600px\" }}>\n\t\t\t\t\tUnsupported channels (coming soon): {unsupportedChannels.join(\", \")}\n\t\t\t\t</p>\n\t\t\t\t: null\n\t\t\t}\n\t\t\t{!done\n\t\t\t\t? <button\n\t\t\t\t\tclassName=\"provider-btn mt-2\"\n\t\t\t\t\tstyle={{ width: \"fit-content\" }}\n\t\t\t\t\tonClick={doImport}\n\t\t\t\t\tdisabled={!anySelected || importing}\n\t\t\t\t>\n\t\t\t\t\t{importing ? \"Importing\\u2026\" : \"Import Selected\"}\n\t\t\t\t</button>\n\t\t\t\t: null\n\t\t\t}\n\t\t</div>\n\t);\n}\n\n// ── Configuration section ─────────────────────────────────────\n\nfunction GraphqlSection(): VNode {\n\tconst [loadingConfig, setLoadingConfig] = useState(true);\n\tconst [enabled, setEnabled] = useState(false);\n\tconst [saving, setSaving] = useState(false);\n\tconst [msg, setMsg] = useState<string | null>(null);\n\tconst [err, setErr] = useState<string | null>(null);\n\tconst origin = window.location.origin;\n\tconst wsProtocol = window.location.protocol === \"https:\" ? \"wss:\" : \"ws:\";\n\tconst httpEndpoint = `${origin}/graphql`;\n\tconst wsEndpoint = `${wsProtocol}//${window.location.host}/graphql`;\n\n\tfunction loadGraphqlConfig(): void {\n\t\tif (!connected.value) {\n\t\t\tsetLoadingConfig(true);\n\t\t\treturn;\n\t\t}\n\t\tsetLoadingConfig(true);\n\t\tsendRpc(\"graphql.config.get\", {})\n\t\t\t.then((res: RpcResponse) => {\n\t\t\t\tif (res?.ok) {\n\t\t\t\t\tsetEnabled((res.payload as { enabled?: boolean })?.enabled !== false);\n\t\t\t\t\tsetErr(null);\n\t\t\t\t} else {\n\t\t\t\t\tsetErr((res?.error as { message?: string })?.message || \"Failed to load GraphQL config\");\n\t\t\t\t}\n\t\t\t\tsetLoadingConfig(false);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((error: Error) => {\n\t\t\t\tsetErr(error?.message || \"Failed to load GraphQL config\");\n\t\t\t\tsetLoadingConfig(false);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tuseEffect(() => {\n\t\tif (connected.value) {\n\t\t\tloadGraphqlConfig();\n\t\t} else {\n\t\t\tsetLoadingConfig(true);\n\t\t\tsetSaving(false);\n\t\t\tsetMsg(null);\n\t\t}\n\t}, [connected.value]);\n\n\tfunction onToggle(nextEnabled: boolean): void {\n\t\tif (!connected.value) {\n\t\t\tsetErr(\"WebSocket not connected\");\n\t\t\trerender();\n\t\t\treturn;\n\t\t}\n\t\tsetSaving(true);\n\t\tsetMsg(null);\n\t\tsetErr(null);\n\t\trerender();\n\n\t\tsendRpc(\"graphql.config.set\", { enabled: nextEnabled })\n\t\t\t.then((res: RpcResponse) => {\n\t\t\t\tsetSaving(false);\n\t\t\t\tif (res?.ok) {\n\t\t\t\t\tconst payload = res.payload as { enabled?: boolean; persisted?: boolean };\n\t\t\t\t\tsetEnabled(payload?.enabled !== false);\n\t\t\t\t\tif (payload?.persisted === false) {\n\t\t\t\t\t\tsetMsg(\"GraphQL updated for this runtime, but failed to persist to config. It may revert on restart.\");\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tsetErr((res?.error as { message?: string })?.message || \"Failed to update GraphQL setting\");\n\t\t\t\t}\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((error: Error) => {\n\t\t\t\tsetSaving(false);\n\t\t\t\tsetErr(error?.message || \"Failed to update GraphQL setting\");\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tif (!connected.value) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Connecting{\"\\u2026\"}</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\tif (loadingConfig) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Loading...</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<div style={{ maxWidth: \"900px\", padding: \"12px 14px\", borderRadius: \"8px\", border: \"1px solid var(--border)\", background: \"var(--surface)\" }}>\n\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", gap: \"12px\" }}>\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<div className=\"text-sm font-medium text-[var(--text-strong)]\">GraphQL server</div>\n\t\t\t\t\t\t{enabled\n\t\t\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\" style={{ marginTop: \"8px\" }}>\n\t\t\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t\t\tHTTP endpoint:{\" \"}\n\t\t\t\t\t\t\t\t\t<code>{httpEndpoint}</code>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t<div style={{ marginTop: \"2px\" }}>\n\t\t\t\t\t\t\t\t\tWebSocket endpoint:{\" \"}\n\t\t\t\t\t\t\t\t\t<code>{wsEndpoint}</code>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\t\t\t\t\t</div>\n\t\t\t\t\t<label id=\"graphqlToggleSwitch\" className=\"toggle-switch\">\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tid=\"graphqlEnabledToggle\"\n\t\t\t\t\t\t\ttype=\"checkbox\"\n\t\t\t\t\t\t\tchecked={enabled}\n\t\t\t\t\t\t\tdisabled={saving || loadingConfig || !connected.value}\n\t\t\t\t\t\t\tonChange={(e: Event) => onToggle((e.target as HTMLInputElement).checked)}\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<span className=\"toggle-slider\" />\n\t\t\t\t\t</label>\n\t\t\t\t</div>\n\t\t\t\t{saving ? <div className=\"text-xs text-[var(--muted)]\" style={{ marginTop: \"8px\" }}>Applying...</div> : null}\n\t\t\t\t{msg ? <div className=\"text-xs text-[var(--ok)]\" style={{ marginTop: \"8px\" }}>{msg}</div> : null}\n\t\t\t\t{err ? <div className=\"text-xs text-[var(--error)]\" style={{ marginTop: \"8px\" }}>{err}</div> : null}\n\t\t\t</div>\n\n\t\t\t{enabled\n\t\t\t\t? <div className=\"flex-1 min-h-0 overflow-hidden rounded-[var(--radius)] border border-[var(--border)] bg-[var(--surface)]\">\n\t\t\t\t\t<iframe\n\t\t\t\t\t\tsrc=\"/graphql\"\n\t\t\t\t\t\tclassName=\"h-full w-full border-0\"\n\t\t\t\t\t\ttitle=\"GraphiQL Playground\"\n\t\t\t\t\t\tallow=\"clipboard-write\"\n\t\t\t\t\t/>\n\t\t\t\t</div>\n\t\t\t\t: null\n\t\t\t}\n\t\t</div>\n\t);\n}\n\nfunction ConfigSection(): VNode {\n\tconst [toml, setToml] = useState(\"\");\n\tconst [configPath, setConfigPath] = useState(\"\");\n\tconst [configLoading, setConfigLoading] = useState(true);\n\tconst [saving, setSaving] = useState(false);\n\tconst [testing, setTesting] = useState(false);\n\tconst [resettingTemplate, setResettingTemplate] = useState(false);\n\tconst [restarting, setRestarting] = useState(false);\n\tconst [msg, setMsg] = useState<string | null>(null);\n\tconst [err, setErr] = useState<string | null>(null);\n\tconst [warnings, setWarnings] = useState<string[]>([]);\n\n\tfunction fetchConfig(): void {\n\t\tsetConfigLoading(true);\n\t\trerender();\n\t\tfetch(\"/api/config\")\n\t\t\t.then((r) => {\n\t\t\t\tif (!r.ok) {\n\t\t\t\t\treturn r.text().then((text) => {\n\t\t\t\t\t\ttry {\n\t\t\t\t\t\t\tconst json = JSON.parse(text);\n\t\t\t\t\t\t\treturn { error: json.error || `HTTP ${r.status}: ${r.statusText}` };\n\t\t\t\t\t\t} catch (_e) {\n\t\t\t\t\t\t\treturn { error: `HTTP ${r.status}: ${r.statusText}` };\n\t\t\t\t\t\t}\n\t\t\t\t\t});\n\t\t\t\t}\n\t\t\t\treturn r.json().catch(() => ({ error: \"Invalid JSON response from server\" }));\n\t\t\t})\n\t\t\t.then((d: { error?: string; toml?: string; path?: string }) => {\n\t\t\t\tif (d.error) {\n\t\t\t\t\tsetErr(d.error);\n\t\t\t\t} else {\n\t\t\t\t\tsetToml(d.toml || \"\");\n\t\t\t\t\tsetConfigPath(d.path || \"\");\n\t\t\t\t\tsetErr(null);\n\t\t\t\t}\n\t\t\t\tsetConfigLoading(false);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((fetchErr: Error) => {\n\t\t\t\tlet errMsg = fetchErr.message || \"Network error\";\n\t\t\t\tif (errMsg.includes(\"pattern\")) {\n\t\t\t\t\terrMsg = \"Failed to connect to server. Please check if moltis is running.\";\n\t\t\t\t}\n\t\t\t\tsetErr(errMsg);\n\t\t\t\tsetConfigLoading(false);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tuseEffect(() => {\n\t\tfetchConfig();\n\t}, []);\n\n\tfunction onTest(e: Event): void {\n\t\te.preventDefault();\n\t\tsetTesting(true);\n\t\tsetMsg(null);\n\t\tsetErr(null);\n\t\tsetWarnings([]);\n\t\trerender();\n\n\t\tfetch(\"/api/config/validate\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ toml }),\n\t\t})\n\t\t\t.then((r) => r.json().catch(() => ({ error: \"Invalid JSON response\" })))\n\t\t\t.then((d: { valid?: boolean; error?: string; warnings?: string[] }) => {\n\t\t\t\tsetTesting(false);\n\t\t\t\tif (d.valid) {\n\t\t\t\t\tsetMsg(\"Configuration is valid.\");\n\t\t\t\t\tsetWarnings(d.warnings || []);\n\t\t\t\t} else {\n\t\t\t\t\tsetErr(d.error || \"Invalid configuration\");\n\t\t\t\t}\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((fetchErr: Error) => {\n\t\t\t\tsetTesting(false);\n\t\t\t\tlet errMsg = fetchErr.message || \"Network error\";\n\t\t\t\tif (errMsg.includes(\"pattern\")) {\n\t\t\t\t\terrMsg = \"Failed to connect to server\";\n\t\t\t\t}\n\t\t\t\tsetErr(errMsg);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onSave(e: Event): void {\n\t\te.preventDefault();\n\t\tsetSaving(true);\n\t\tsetMsg(null);\n\t\tsetErr(null);\n\t\tsetWarnings([]);\n\t\trerender();\n\n\t\tfetch(\"/api/config\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ toml }),\n\t\t})\n\t\t\t.then((r) => r.json().catch(() => ({ error: \"Invalid JSON response\" })))\n\t\t\t.then((d: { ok?: boolean; error?: string }) => {\n\t\t\t\tsetSaving(false);\n\t\t\t\tif (d.ok) {\n\t\t\t\t\tsetMsg(\"Configuration saved. Restart required for changes to take effect.\");\n\t\t\t\t} else {\n\t\t\t\t\tsetErr(d.error || \"Failed to save\");\n\t\t\t\t}\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((fetchErr: Error) => {\n\t\t\t\tsetSaving(false);\n\t\t\t\tlet errMsg = fetchErr.message || \"Network error\";\n\t\t\t\tif (errMsg.includes(\"pattern\")) {\n\t\t\t\t\terrMsg = \"Failed to connect to server\";\n\t\t\t\t}\n\t\t\t\tsetErr(errMsg);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onRestart(): void {\n\t\tsetRestarting(true);\n\t\tsetMsg(\"Restarting moltis...\");\n\t\tsetErr(null);\n\t\trerender();\n\n\t\tfetch(\"/api/restart\", { method: \"POST\" })\n\t\t\t.then((r) =>\n\t\t\t\tr\n\t\t\t\t\t.json()\n\t\t\t\t\t.catch(() => ({}))\n\t\t\t\t\t.then((d: { error?: string }) => ({ status: r.status, data: d })),\n\t\t\t)\n\t\t\t.then(({ status, data }: { status: number; data: { error?: string } }) => {\n\t\t\t\tif (status >= 400 && data.error) {\n\t\t\t\t\tsetRestarting(false);\n\t\t\t\t\tsetErr(data.error);\n\t\t\t\t\tsetMsg(null);\n\t\t\t\t\trerender();\n\t\t\t\t} else {\n\t\t\t\t\tsetTimeout(waitForRestart, 1000);\n\t\t\t\t}\n\t\t\t})\n\t\t\t.catch(() => {\n\t\t\t\tsetTimeout(waitForRestart, 1000);\n\t\t\t});\n\t}\n\n\tfunction waitForRestart(): void {\n\t\tlet attempts = 0;\n\t\tconst maxAttempts = 30;\n\n\t\tfunction check(): void {\n\t\t\tattempts++;\n\t\t\tfetch(\"/api/gon\", { method: \"GET\" })\n\t\t\t\t.then((r) => {\n\t\t\t\t\tif (r.ok) {\n\t\t\t\t\t\twindow.location.reload();\n\t\t\t\t\t} else if (attempts < maxAttempts) {\n\t\t\t\t\t\tsetTimeout(check, 1000);\n\t\t\t\t\t} else {\n\t\t\t\t\t\tsetRestarting(false);\n\t\t\t\t\t\tsetErr(\"Server did not come back up. Check if moltis is running.\");\n\t\t\t\t\t\trerender();\n\t\t\t\t\t}\n\t\t\t\t})\n\t\t\t\t.catch(() => {\n\t\t\t\t\tif (attempts < maxAttempts) {\n\t\t\t\t\t\tsetTimeout(check, 1000);\n\t\t\t\t\t} else {\n\t\t\t\t\t\tsetRestarting(false);\n\t\t\t\t\t\tsetErr(\"Server did not come back up. Check if moltis is running.\");\n\t\t\t\t\t\trerender();\n\t\t\t\t\t}\n\t\t\t\t});\n\t\t}\n\n\t\tcheck();\n\t}\n\n\tfunction onReset(): void {\n\t\tfetchConfig();\n\t\tsetMsg(null);\n\t\tsetErr(null);\n\t\tsetWarnings([]);\n\t}\n\n\tfunction onResetToTemplate(): void {\n\t\tif (\n\t\t\t!confirm(\n\t\t\t\t\"Replace current config with the default template?\\n\\nThis will show all available options with documentation. Your current values will be lost unless you copy them first.\",\n\t\t\t)\n\t\t) {\n\t\t\treturn;\n\t\t}\n\t\tsetResettingTemplate(true);\n\t\tsetMsg(null);\n\t\tsetErr(null);\n\t\tsetWarnings([]);\n\t\trerender();\n\n\t\tfetch(\"/api/config/template\")\n\t\t\t.then((r) => {\n\t\t\t\tif (!r.ok) {\n\t\t\t\t\treturn { error: `HTTP ${r.status}: Failed to load template` };\n\t\t\t\t}\n\t\t\t\treturn r.json().catch(() => ({ error: \"Invalid JSON response\" }));\n\t\t\t})\n\t\t\t.then((d: { error?: string; toml?: string }) => {\n\t\t\t\tsetResettingTemplate(false);\n\t\t\t\tif (d.error) {\n\t\t\t\t\tsetErr(d.error);\n\t\t\t\t} else {\n\t\t\t\t\tsetToml(d.toml || \"\");\n\t\t\t\t\tsetMsg(\"Loaded default template with all options. Review and save when ready.\");\n\t\t\t\t}\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((fetchErr: Error) => {\n\t\t\t\tsetResettingTemplate(false);\n\t\t\t\tlet errMsg = fetchErr.message || \"Network error\";\n\t\t\t\tif (errMsg.includes(\"pattern\")) {\n\t\t\t\t\terrMsg = \"Failed to connect to server\";\n\t\t\t\t}\n\t\t\t\tsetErr(errMsg);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tif (configLoading) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Configuration</h2>\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Loading{\"\\u2026\"}</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Configuration</h2>\n\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed\" style={{ maxWidth: \"700px\", margin: 0 }}>\n\t\t\t\tEdit the full moltis configuration. This includes server, tools, LLM providers, auth, and all other settings.\n\t\t\t\tTest your changes before saving. Changes require a restart to take effect.{\" \"}\n\t\t\t\t<a href=\"https://docs.moltis.org/configuration.html\" target=\"_blank\" rel=\"noopener\"\n\t\t\t\t\tstyle={{ color: \"var(--accent)\", textDecoration: \"underline\" }}>View documentation {\"\\u2197\"}</a>\n\t\t\t</p>\n\t\t\t{configPath\n\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\" style={{ fontFamily: \"var(--font-mono)\" }}>\n\t\t\t\t\t<span style={{ opacity: 0.7 }}>File:</span> {configPath}\n\t\t\t\t</div>\n\t\t\t\t: null\n\t\t\t}\n\n\t\t\t<form onSubmit={onSave} style={{ maxWidth: \"800px\" }}>\n\t\t\t\t<div style={{ marginBottom: \"12px\" }}>\n\t\t\t\t\t<textarea\n\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\trows={20}\n\t\t\t\t\t\tstyle={{ width: \"100%\", minHeight: \"320px\", resize: \"vertical\", fontFamily: \"var(--font-mono)\", fontSize: \".78rem\", lineHeight: 1.5, whiteSpace: \"pre\", overflowWrap: \"normal\", overflowX: \"auto\" }}\n\t\t\t\t\t\tvalue={toml}\n\t\t\t\t\t\tonInput={(e: Event) => {\n\t\t\t\t\t\t\tsetToml((e.target as HTMLTextAreaElement).value);\n\t\t\t\t\t\t\tsetMsg(null);\n\t\t\t\t\t\t\tsetErr(null);\n\t\t\t\t\t\t\tsetWarnings([]);\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tspellcheck={false}\n\t\t\t\t\t/>\n\t\t\t\t</div>\n\n\t\t\t\t{warnings.length > 0\n\t\t\t\t\t? <div style={{ marginBottom: \"12px\", padding: \"10px 12px\", background: \"color-mix(in srgb, orange 10%, transparent)\", border: \"1px solid orange\", borderRadius: \"6px\" }}>\n\t\t\t\t\t\t<div className=\"text-xs font-medium\" style={{ color: \"orange\", marginBottom: \"6px\" }}>Warnings:</div>\n\t\t\t\t\t\t<ul style={{ margin: 0, paddingLeft: \"16px\" }}>\n\t\t\t\t\t\t\t{warnings.map((w, i) => <li key={i} className=\"text-xs text-[var(--muted)]\" style={{ margin: \"4px 0\" }}>{w}</li>)}\n\t\t\t\t\t\t</ul>\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\n\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\", flexWrap: \"wrap\" }}>\n\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-secondary\" onClick={onTest} disabled={testing || saving || resettingTemplate || restarting}>\n\t\t\t\t\t\t{testing ? \"Testing\\u2026\" : \"Test\"}\n\t\t\t\t\t</button>\n\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-secondary\" onClick={onReset} disabled={saving || testing || resettingTemplate || restarting}>\n\t\t\t\t\t\tReload\n\t\t\t\t\t</button>\n\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-secondary\" onClick={onResetToTemplate} disabled={saving || testing || resettingTemplate || restarting}>\n\t\t\t\t\t\t{resettingTemplate ? \"Resetting\\u2026\" : \"Reset to defaults\"}\n\t\t\t\t\t</button>\n\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-danger\" onClick={onRestart} disabled={saving || testing || resettingTemplate || restarting}>\n\t\t\t\t\t\t{restarting ? \"Restarting\\u2026\" : \"Restart\"}\n\t\t\t\t\t</button>\n\t\t\t\t\t<div style={{ flex: 1 }} />\n\t\t\t\t\t<button type=\"submit\" className=\"provider-btn\" disabled={saving || testing || resettingTemplate || restarting}>\n\t\t\t\t\t\t{saving ? \"Saving\\u2026\" : \"Save\"}\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\n\t\t\t\t{msg ? <div className=\"text-xs\" style={{ marginTop: \"8px\", color: \"var(--accent)\" }}>{msg}</div> : null}\n\t\t\t\t{err ? <div className=\"text-xs\" style={{ marginTop: \"8px\", color: \"var(--error)\", whiteSpace: \"pre-wrap\", fontFamily: \"var(--font-mono)\" }}>{err}</div> : null}\n\t\t\t\t{restarting\n\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\" style={{ marginTop: \"8px\" }}>\n\t\t\t\t\t\tThe page will reload automatically when the server is back up.\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t</form>\n\n\t\t\t<div style={{ maxWidth: \"800px\", marginTop: \"8px\", paddingTop: \"16px\", borderTop: \"1px solid var(--border)\" }}>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed\">\n\t\t\t\t\t<strong>Tip:</strong> Click \"Load Template\" to see all available configuration options with documentation.\n\t\t\t\t\tThis replaces the editor content with a fully documented template - copy your current values first if needed.\n\t\t\t\t</p>\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// ── Remote access section ────────────────────────────────────\n\nfunction renderLinkedText(text: string): (string | VNode)[] {\n\treturn String(text || \"\")\n\t\t.split(/(https?:\\/\\/[^\\s]+)/g)\n\t\t.filter(Boolean)\n\t\t.map((part, index) =>\n\t\t\t/^https?:\\/\\//.test(part)\n\t\t\t\t? <a\n\t\t\t\t\tkey={index}\n\t\t\t\t\thref={part}\n\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\tclassName=\"underline break-all\"\n\t\t\t\t>\n\t\t\t\t\t{part}\n\t\t\t\t</a>\n\t\t\t\t: part,\n\t\t);\n}\n\n/** Clone a hidden element from index.html by ID. */\nfunction cloneHidden(id: string): HTMLElement | null {\n\tconst el = document.getElementById(id);\n\tif (!el) return null;\n\tconst clone = el.cloneNode(true) as HTMLElement;\n\tclone.removeAttribute(\"id\");\n\tclone.style.display = \"\";\n\treturn clone;\n}\n\ninterface TailscaleStatus {\n\tinstalled?: boolean;\n\tversion?: string;\n\ttailnet?: string;\n\tlogin_name?: string;\n\ttailscale_ip?: string;\n\ttailscale_up?: boolean;\n\tmode?: string;\n\thostname?: string;\n\turl?: string;\n\tpasskey_warning?: string;\n}\n\ninterface NgrokStatus {\n\tenabled?: boolean;\n\tauthtoken_source?: string;\n\tdomain?: string;\n\tpublic_url?: string;\n\tpasskey_warning?: string;\n\terror?: string;\n}\n\ninterface NgrokForm {\n\tenabled: boolean;\n\tauthtoken: string;\n\tclearAuthtoken: boolean;\n\tdomain: string;\n}\n\nfunction RemoteAccessSection(): VNode {\n\tconst [tsStatus, setTsStatus] = useState<TailscaleStatus | null>(null);\n\tconst [tsError, setTsError] = useState<string | null>(null);\n\tconst [tsWarning, setTsWarning] = useState<string | null>(null);\n\tconst [tsLoading, setTsLoading] = useState(true);\n\tconst [configuring, setConfiguring] = useState(false);\n\tconst [configuringMode, setConfiguringMode] = useState<string | null>(null);\n\tconst [ngStatus, setNgStatus] = useState<NgrokStatus | null>(null);\n\tconst [ngError, setNgError] = useState<string | null>(null);\n\tconst [ngLoading, setNgLoading] = useState(true);\n\tconst [ngSaving, setNgSaving] = useState(false);\n\tconst [ngMsg, setNgMsg] = useState<string | null>(null);\n\tconst [ngForm, setNgForm] = useState<NgrokForm>({\n\t\tenabled: false,\n\t\tauthtoken: \"\",\n\t\tclearAuthtoken: false,\n\t\tdomain: \"\",\n\t});\n\tconst [authReady, setAuthReady] = useState(false);\n\n\tfunction fetchTsStatus(): void {\n\t\tsetTsLoading(true);\n\t\trerender();\n\t\tfetch(\"/api/tailscale/status\")\n\t\t\t.then((r) => {\n\t\t\t\tconst ct = r.headers.get(\"content-type\") || \"\";\n\t\t\t\tif (r.status === 404 || !ct.includes(\"application/json\")) {\n\t\t\t\t\tsetTsError(\"Tailscale feature is not enabled. Rebuild with --features tailscale.\");\n\t\t\t\t\tsetTsLoading(false);\n\t\t\t\t\trerender();\n\t\t\t\t\treturn null;\n\t\t\t\t}\n\t\t\t\treturn r.json();\n\t\t\t})\n\t\t\t.then((data: TailscaleStatus | null) => {\n\t\t\t\tif (!data) return;\n\t\t\t\tif ((data as { error?: string }).error) {\n\t\t\t\t\tsetTsError((data as { error?: string }).error || null);\n\t\t\t\t} else {\n\t\t\t\t\tsetTsStatus(data);\n\t\t\t\t\tsetTsError(null);\n\t\t\t\t\tsetTsWarning(data.passkey_warning || null);\n\t\t\t\t}\n\t\t\t\tsetTsLoading(false);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((e: Error) => {\n\t\t\t\tsetTsError(e.message);\n\t\t\t\tsetTsLoading(false);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction fetchNgrokStatus(): void {\n\t\tsetNgLoading(true);\n\t\trerender();\n\t\tfetch(\"/api/ngrok/status\")\n\t\t\t.then((r) => {\n\t\t\t\tconst ct = r.headers.get(\"content-type\") || \"\";\n\t\t\t\tif (r.status === 404 || !ct.includes(\"application/json\")) {\n\t\t\t\t\tsetNgError(\"ngrok feature is not enabled. Rebuild with --features ngrok.\");\n\t\t\t\t\tsetNgStatus(null);\n\t\t\t\t\tsetNgLoading(false);\n\t\t\t\t\trerender();\n\t\t\t\t\treturn null;\n\t\t\t\t}\n\t\t\t\treturn r.json();\n\t\t\t})\n\t\t\t.then((data: NgrokStatus | null) => {\n\t\t\t\tif (!data) return;\n\t\t\t\tsetNgStatus(data);\n\t\t\t\tsetNgError(data.error || null);\n\t\t\t\tsetNgLoading(false);\n\t\t\t\tsetNgForm({\n\t\t\t\t\tenabled: Boolean(data.enabled),\n\t\t\t\t\tauthtoken: \"\",\n\t\t\t\t\tclearAuthtoken: false,\n\t\t\t\t\tdomain: data.domain || \"\",\n\t\t\t\t});\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((e: Error) => {\n\t\t\t\tsetNgError(e.message);\n\t\t\t\tsetNgLoading(false);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction setMode(mode: string): void {\n\t\tsetConfiguring(true);\n\t\tsetTsError(null);\n\t\tsetTsWarning(null);\n\t\tsetConfiguringMode(mode);\n\t\trerender();\n\t\tfetch(\"/api/tailscale/configure\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ mode }),\n\t\t})\n\t\t\t.then((r) => r.json())\n\t\t\t.then((data: { error?: string; passkey_warning?: string }) => {\n\t\t\t\tif (data.error) {\n\t\t\t\t\tsetTsError(data.error);\n\t\t\t\t} else {\n\t\t\t\t\tsetTsWarning(data.passkey_warning || null);\n\t\t\t\t\tfetchTsStatus();\n\t\t\t\t}\n\t\t\t\tsetConfiguring(false);\n\t\t\t\tsetConfiguringMode(null);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((e: Error) => {\n\t\t\t\tsetTsError(e.message);\n\t\t\t\tsetConfiguring(false);\n\t\t\t\tsetConfiguringMode(null);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction persistNgrokConfig(nextForm: NgrokForm, successMessage: string): void {\n\t\tsetNgSaving(true);\n\t\tsetNgError(null);\n\t\tsetNgMsg(null);\n\t\trerender();\n\n\t\tfetch(\"/api/ngrok/config\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({\n\t\t\t\tenabled: nextForm.enabled,\n\t\t\t\tauthtoken: nextForm.authtoken,\n\t\t\t\tclear_authtoken: nextForm.clearAuthtoken,\n\t\t\t\tdomain: nextForm.domain,\n\t\t\t}),\n\t\t})\n\t\t\t.then((r) =>\n\t\t\t\tr\n\t\t\t\t\t.json()\n\t\t\t\t\t.catch(() => ({}))\n\t\t\t\t\t.then((data: { error?: string; status?: NgrokStatus }) => ({ ok: r.ok, data })),\n\t\t\t)\n\t\t\t.then(({ ok, data }: { ok: boolean; data: { error?: string; status?: NgrokStatus } }) => {\n\t\t\t\tsetNgSaving(false);\n\t\t\t\tif (!ok || data.error) {\n\t\t\t\t\tsetNgError(data.error || null);\n\t\t\t\t} else {\n\t\t\t\t\tsetNgMsg(successMessage);\n\t\t\t\t\tif (data.status) {\n\t\t\t\t\t\tsetNgStatus(data.status);\n\t\t\t\t\t\tsetNgForm({\n\t\t\t\t\t\t\tenabled: Boolean(data.status.enabled),\n\t\t\t\t\t\t\tauthtoken: \"\",\n\t\t\t\t\t\t\tclearAuthtoken: false,\n\t\t\t\t\t\t\tdomain: data.status.domain || \"\",\n\t\t\t\t\t\t});\n\t\t\t\t\t} else {\n\t\t\t\t\t\tfetchNgrokStatus();\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((e: Error) => {\n\t\t\t\tsetNgSaving(false);\n\t\t\t\tsetNgError(e.message);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction saveNgrokConfig(e: Event): void {\n\t\te.preventDefault();\n\t\tpersistNgrokConfig(ngForm, \"ngrok settings applied.\");\n\t}\n\n\tfunction toggleNgrokEnabled(): void {\n\t\tconst nextForm = {\n\t\t\t...ngForm,\n\t\t\tenabled: !ngForm.enabled,\n\t\t};\n\t\tsetNgForm(nextForm);\n\t\tpersistNgrokConfig(nextForm, `ngrok ${nextForm.enabled ? \"enabled\" : \"disabled\"}.`);\n\t}\n\n\tfunction toggleNgrokTokenDeletion(): void {\n\t\tif (ngForm.clearAuthtoken) {\n\t\t\tsetNgForm({\n\t\t\t\t...ngForm,\n\t\t\t\tclearAuthtoken: false,\n\t\t\t});\n\t\t\treturn;\n\t\t}\n\n\t\tif (!window.confirm(\"Delete the current ngrok token from config when you save?\")) {\n\t\t\treturn;\n\t\t}\n\n\t\tsetNgForm({\n\t\t\t...ngForm,\n\t\t\tauthtoken: \"\",\n\t\t\tclearAuthtoken: true,\n\t\t});\n\t}\n\n\tuseEffect(() => {\n\t\tfetchTsStatus();\n\t\tfetchNgrokStatus();\n\t\tfetch(\"/api/auth/status\")\n\t\t\t.then((r) => (r.ok ? r.json() : null))\n\t\t\t.then((d: { auth_disabled?: boolean; has_password?: boolean } | null) => {\n\t\t\t\tif (!d) return;\n\t\t\t\tconst ready = d.auth_disabled ? false : d.has_password === true;\n\t\t\t\tsetAuthReady(ready);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch(() => {\n\t\t\t\t/* ignore auth status fetch errors */\n\t\t\t});\n\t}, []);\n\n\tfunction renderTailscaleModeButton(mode: string, currentMode: string): VNode {\n\t\tconst active = currentMode === mode && !configuring;\n\t\tconst classes = active\n\t\t\t? \"ts-mode-active\"\n\t\t\t: \"text-[var(--muted)] border-[var(--border)] bg-transparent hover:text-[var(--text)] hover:border-[var(--border-strong)]\";\n\t\treturn (\n\t\t\t<button\n\t\t\t\ttype=\"button\"\n\t\t\t\tclassName={`text-xs border px-3 py-1.5 rounded-md cursor-pointer transition-colors font-medium ${classes}${\n\t\t\t\t\tconfiguringMode === mode ? \" ts-mode-configuring\" : \"\"\n\t\t\t\t}`}\n\t\t\t\tdisabled={configuring}\n\t\t\t\tonClick={() => setMode(mode)}\n\t\t\t>\n\t\t\t\t{configuringMode === mode ? <span className=\"ts-spinner\" /> : null}\n\t\t\t\t{mode}\n\t\t\t</button>\n\t\t);\n\t}\n\n\tfunction renderTailscaleCard(): VNode {\n\t\tconst currentMode = tsStatus?.mode || \"off\";\n\t\tconst tsVaultBlocked = tsError === \"vault is sealed\";\n\t\treturn (\n\t\t\t<section className=\"rounded-[var(--radius)] border border-[var(--border)] bg-[var(--surface)] p-4 flex flex-col gap-4\">\n\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t<h3 className=\"text-base font-medium text-[var(--text-strong)]\">Tailscale</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed\">\n\t\t\t\t\t\tExpose the gateway via Tailscale Serve (tailnet-only HTTPS) or Funnel (public HTTPS). The\n\t\t\t\t\t\tgateway stays bound to localhost while Tailscale proxies traffic to it.\n\t\t\t\t\t</p>\n\t\t\t\t</div>\n\n\t\t\t\t{tsLoading\n\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\">Loading{\"\\u2026\"} this can take a few seconds.</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t\t{tsStatus?.installed\n\t\t\t\t\t? <div className=\"info-bar\">\n\t\t\t\t\t\t<span className=\"info-field\">\n\t\t\t\t\t\t\t<span className=\"status-dot connected\" />\n\t\t\t\t\t\t\t<span className=\"info-label\">Installed</span>\n\t\t\t\t\t\t\t{tsStatus.version ? <span className=\"info-version\">v{tsStatus.version.split(\"-\")[0]}</span> : null}\n\t\t\t\t\t\t</span>\n\t\t\t\t\t\t{tsStatus.tailnet\n\t\t\t\t\t\t\t? <span className=\"info-field\">\n\t\t\t\t\t\t\t\t<span className=\"info-label\">Tailnet:</span>\n\t\t\t\t\t\t\t\t<span className=\"info-value-strong\">{tsStatus.tailnet}</span>\n\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\t\t\t\t\t\t{tsStatus.login_name\n\t\t\t\t\t\t\t? <span className=\"info-field\">\n\t\t\t\t\t\t\t\t<span className=\"info-label\">Account:</span>\n\t\t\t\t\t\t\t\t<span className=\"info-value\">{tsStatus.login_name}</span>\n\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\t\t\t\t\t\t{tsStatus.tailscale_ip\n\t\t\t\t\t\t\t? <span className=\"info-field\">\n\t\t\t\t\t\t\t\t<span className=\"info-label\">IP:</span>\n\t\t\t\t\t\t\t\t<span className=\"info-value-mono\">{tsStatus.tailscale_ip}</span>\n\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t\t{tsError\n\t\t\t\t\t? <div className=\"settings-alert-error whitespace-pre-line max-w-form\">\n\t\t\t\t\t\t<span className=\"icon icon-lg icon-warn-triangle shrink-0 mt-0.5\" />\n\t\t\t\t\t\t<span>{renderLinkedText(tsError)}</span>\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t\t{tsVaultBlocked\n\t\t\t\t\t? <button\n\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\tclassName=\"provider-btn self-start\"\n\t\t\t\t\t\tonClick={() => navigate(settingsPath(\"vault\"))}\n\t\t\t\t\t>\n\t\t\t\t\t\tUnlock in Encryption settings\n\t\t\t\t\t</button>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t\t{tsWarning ? <div className=\"alert-warning-text max-w-form\">{tsWarning}</div> : null}\n\n\t\t\t\t{tsStatus?.installed === false\n\t\t\t\t\t? <div className=\"info-bar\" style={{ justifyContent: \"center\", flexDirection: \"column\", gap: \"12px\", textAlign: \"center\" }}>\n\t\t\t\t\t\t<p className=\"text-sm text-[var(--text)]\">\n\t\t\t\t\t\t\tThe <code className=\"font-mono text-sm\">tailscale</code> CLI was not found on this machine.\n\t\t\t\t\t\t</p>\n\t\t\t\t\t\t<div className=\"flex items-center justify-center gap-2 flex-wrap\">\n\t\t\t\t\t\t\t<a\n\t\t\t\t\t\t\t\thref=\"https://tailscale.com/download\"\n\t\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\t\t\t\tclassName=\"provider-btn\"\n\t\t\t\t\t\t\t\tstyle={{ display: \"inline-block\", textDecoration: \"none\" }}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\tInstall Tailscale\n\t\t\t\t\t\t\t</a>\n\t\t\t\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-secondary\" onClick={fetchTsStatus}>\n\t\t\t\t\t\t\t\tRe-check\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\n\t\t\t\t{!tsLoading && tsStatus?.installed !== false\n\t\t\t\t\t? <div className=\"flex flex-col gap-4\">\n\t\t\t\t\t\t{tsStatus?.tailscale_up === false\n\t\t\t\t\t\t\t? <div className=\"alert-warning-text max-w-form\">\n\t\t\t\t\t\t\t\t<span className=\"alert-label-warn\">Warning:</span>\n\t\t\t\t\t\t\t\t{\" \"}Tailscale is not running. Start it with <code className=\"font-mono\">tailscale up</code> or\n\t\t\t\t\t\t\t\topen the Tailscale app.\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\t<div className=\"max-w-form flex flex-col gap-2\">\n\t\t\t\t\t\t\t<h4 className=\"text-sm font-medium text-[var(--text-strong)]\">Mode</h4>\n\t\t\t\t\t\t\t<div className=\"flex gap-2 flex-wrap\">\n\t\t\t\t\t\t\t\t{([\"off\", \"serve\", \"funnel\"] as const).map((mode) => renderTailscaleModeButton(mode, currentMode))}\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t{configuring\n\t\t\t\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\t\tConfiguring tailscale {configuringMode}{\"\\u2026\"} This can take up to 10 seconds.\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t</div>\n\n\t\t\t\t\t\t<div className=\"alert-warning-text max-w-form\">\n\t\t\t\t\t\t\t<span className=\"alert-label-warn\">Warning:</span>{\" \"}\n\t\t\t\t\t\t\tEnabling Funnel exposes moltis to the public internet. This code has not been security-audited.\n\t\t\t\t\t\t\tUse at your own risk.\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t{authReady\n\t\t\t\t\t\t\t? null\n\t\t\t\t\t\t\t: <div className=\"flex flex-col gap-2 max-w-form\">\n\t\t\t\t\t\t\t\t<div className=\"alert-warning-text\">\n\t\t\t\t\t\t\t\t\t<span className=\"alert-label-warn\">Warning:</span>\n\t\t\t\t\t\t\t\t\t{\" \"}Funnel can be enabled now, but remote visitors will see the setup-required page until\n\t\t\t\t\t\t\t\t\tauthentication is configured.\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\t\t\tclassName=\"provider-btn self-start\"\n\t\t\t\t\t\t\t\t\tonClick={() => navigate(settingsPath(\"security\"))}\n\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\tSet up authentication\n\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\t{tsStatus?.hostname\n\t\t\t\t\t\t\t? <div className=\"max-w-form\">\n\t\t\t\t\t\t\t\t<h4 className=\"text-sm font-medium text-[var(--text-strong)] mb-1\">Hostname</h4>\n\t\t\t\t\t\t\t\t{tsStatus.url && currentMode !== \"off\"\n\t\t\t\t\t\t\t\t\t? <a\n\t\t\t\t\t\t\t\t\t\thref={tsStatus.url}\n\t\t\t\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\t\t\t\t\t\tclassName=\"font-mono text-sm text-[var(--accent)] no-underline\"\n\t\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t\t{tsStatus.hostname}\n\t\t\t\t\t\t\t\t\t</a>\n\t\t\t\t\t\t\t\t\t: <div className=\"font-mono text-sm\">{tsStatus.hostname}</div>\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\t\t\t\t\t\t{tsStatus?.url && currentMode !== \"off\"\n\t\t\t\t\t\t\t? <div className=\"max-w-form\">\n\t\t\t\t\t\t\t\t<h4 className=\"text-sm font-medium text-[var(--text-strong)] mb-1\">URL</h4>\n\t\t\t\t\t\t\t\t<a\n\t\t\t\t\t\t\t\t\thref={tsStatus.url}\n\t\t\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\t\t\t\t\tclassName=\"font-mono text-sm text-[var(--accent)] no-underline break-all\"\n\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t{tsStatus.url}\n\t\t\t\t\t\t\t\t</a>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\t\t\t\t\t\t{currentMode === \"funnel\"\n\t\t\t\t\t\t\t? <div className=\"alert-warning-text max-w-form\">\n\t\t\t\t\t\t\t\t<span className=\"alert-label-warn\">Warning:</span>\n\t\t\t\t\t\t\t\t{\" \"}Funnel exposes your gateway to the public internet. Make sure password authentication is\n\t\t\t\t\t\t\t\tconfigured.\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t</section>\n\t\t);\n\t}\n\n\tfunction renderNgrokCard(): VNode {\n\t\tconst authSourceLabel =\n\t\t\tngStatus?.authtoken_source === \"config\"\n\t\t\t\t? \"Stored in config\"\n\t\t\t\t: ngStatus?.authtoken_source === \"env\"\n\t\t\t\t\t? \"Using NGROK_AUTHTOKEN from the environment\"\n\t\t\t\t\t: \"No authtoken configured yet\";\n\t\tconst ngVaultBlocked = ngError === \"vault is sealed\";\n\n\t\treturn (\n\t\t\t<section className=\"rounded-[var(--radius)] border border-[var(--border)] bg-[var(--surface)] p-4 flex flex-col gap-4\">\n\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t<h3 className=\"text-base font-medium text-[var(--text-strong)]\">ngrok</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed\">\n\t\t\t\t\t\tCreate a public HTTPS endpoint without installing an external binary. Changes apply\n\t\t\t\t\t\timmediately.\n\t\t\t\t\t</p>\n\t\t\t\t</div>\n\n\t\t\t\t{ngLoading\n\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\">Loading{\"\\u2026\"} this can take a few seconds.</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t\t{ngError\n\t\t\t\t\t? <div className=\"settings-alert-error whitespace-pre-line max-w-form\">\n\t\t\t\t\t\t<span className=\"icon icon-lg icon-warn-triangle shrink-0 mt-0.5\" />\n\t\t\t\t\t\t<span>{renderLinkedText(ngError)}</span>\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t\t{ngVaultBlocked\n\t\t\t\t\t? <button\n\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\tclassName=\"provider-btn self-start\"\n\t\t\t\t\t\tonClick={() => navigate(settingsPath(\"vault\"))}\n\t\t\t\t\t>\n\t\t\t\t\t\tUnlock in Encryption settings\n\t\t\t\t\t</button>\n\t\t\t\t\t: null\n\t\t\t\t}\n\n\t\t\t\t{ngLoading || ngError\n\t\t\t\t\t? null\n\t\t\t\t\t: <form className=\"flex flex-col gap-4\" onSubmit={saveNgrokConfig}>\n\t\t\t\t\t\t<div className=\"rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--bg)] px-3 py-2.5 flex items-center justify-between gap-3\">\n\t\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t\t<div className=\"text-sm font-medium text-[var(--text-strong)]\">\n\t\t\t\t\t\t\t\t\tngrok is {ngForm.enabled ? \"enabled\" : \"disabled\"}\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\t\tPublic HTTPS endpoint for demos, shared testing, and team access.\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\t\tclassName=\"provider-btn\"\n\t\t\t\t\t\t\t\tdisabled={ngSaving}\n\t\t\t\t\t\t\t\tonClick={toggleNgrokEnabled}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t{ngSaving ? \"Saving\\u2026\" : ngForm.enabled ? \"Disable ngrok\" : \"Enable ngrok\"}\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t</div>\n\n\t\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t\t<label className=\"text-sm font-medium text-[var(--text-strong)]\" htmlFor=\"ngrok-authtoken\">\n\t\t\t\t\t\t\t\tAuthtoken\n\t\t\t\t\t\t\t</label>\n\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\tid=\"ngrok-authtoken\"\n\t\t\t\t\t\t\t\ttype=\"password\"\n\t\t\t\t\t\t\t\tclassName=\"w-full rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--bg)] px-3 py-2 text-sm text-[var(--text)]\"\n\t\t\t\t\t\t\t\tplaceholder={ngStatus?.authtoken_source ? \"Leave blank to keep the current token\" : \"Paste your ngrok authtoken\"}\n\t\t\t\t\t\t\t\tvalue={ngForm.authtoken}\n\t\t\t\t\t\t\t\tonInput={(e: Event) => setNgForm({ ...ngForm, authtoken: (e.currentTarget as HTMLInputElement).value })}\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">{authSourceLabel}</div>\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\tCreate or copy an authtoken from{\" \"}\n\t\t\t\t\t\t\t\t<a\n\t\t\t\t\t\t\t\t\thref=\"https://dashboard.ngrok.com/get-started/your-authtoken\"\n\t\t\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\t\t\t\t\tclassName=\"text-[var(--accent)] no-underline hover:underline\"\n\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\tngrok dashboard\n\t\t\t\t\t\t\t\t</a>.\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t{ngStatus?.authtoken_source === \"config\"\n\t\t\t\t\t\t\t\t? <div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\t\t\t\tclassName=\"text-xs text-[var(--accent)] self-start bg-transparent border-0 p-0 cursor-pointer hover:underline\"\n\t\t\t\t\t\t\t\t\t\tonClick={toggleNgrokTokenDeletion}\n\t\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t\t{ngForm.clearAuthtoken ? \"Keep current token\" : \"Delete current token\"}\n\t\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t\t\t{ngForm.clearAuthtoken\n\t\t\t\t\t\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\t\t\t\tThe saved config token will be deleted when you save.\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t</div>\n\n\t\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t\t<label className=\"text-sm font-medium text-[var(--text-strong)]\" htmlFor=\"ngrok-domain\">\n\t\t\t\t\t\t\t\tReserved domain\n\t\t\t\t\t\t\t</label>\n\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\tid=\"ngrok-domain\"\n\t\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\t\tclassName=\"w-full rounded-[var(--radius-sm)] border border-[var(--border)] bg-[var(--bg)] px-3 py-2 text-sm text-[var(--text)]\"\n\t\t\t\t\t\t\t\tplaceholder=\"team-gateway.ngrok.app\"\n\t\t\t\t\t\t\t\tvalue={ngForm.domain}\n\t\t\t\t\t\t\t\tonInput={(e: Event) => setNgForm({ ...ngForm, domain: (e.currentTarget as HTMLInputElement).value })}\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\tOptional. Use a reserved domain if you want a stable passkey origin across restarts.\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</div>\n\n\t\t\t\t\t\t{ngStatus?.public_url\n\t\t\t\t\t\t\t? <div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t\t\t<h4 className=\"text-sm font-medium text-[var(--text-strong)]\">Active public URL</h4>\n\t\t\t\t\t\t\t\t<a\n\t\t\t\t\t\t\t\t\thref={ngStatus.public_url}\n\t\t\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\t\t\t\t\tclassName=\"font-mono text-sm text-[var(--accent)] no-underline break-all\"\n\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t{ngStatus.public_url}\n\t\t\t\t\t\t\t\t</a>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\t\t\t\t\t\t{ngStatus?.passkey_warning\n\t\t\t\t\t\t\t? <div className=\"alert-warning-text max-w-form\">{ngStatus.passkey_warning}</div>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\t\t\t\t\t\t{ngForm.enabled && !authReady\n\t\t\t\t\t\t\t? <div className=\"alert-warning-text max-w-form\">\n\t\t\t\t\t\t\t\t<span className=\"alert-label-warn\">Warning:</span>{\" \"}\n\t\t\t\t\t\t\t\tngrok can be enabled now, but remote visitors will see the setup-required\n\t\t\t\t\t\t\t\tpage until authentication is configured.\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\t\t\t\t\t\t{ngMsg ? <div className=\"text-xs text-[var(--ok)]\">{ngMsg}</div> : null}\n\n\t\t\t\t\t\t<div className=\"flex flex-wrap gap-2\">\n\t\t\t\t\t\t\t<button type=\"submit\" className=\"provider-btn\" disabled={ngSaving}>\n\t\t\t\t\t\t\t\t{ngSaving ? \"Saving\\u2026\" : \"Save ngrok settings\"}\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</form>\n\t\t\t\t}\n\t\t\t</section>\n\t\t);\n\t}\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Remote Access</h2>\n\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed max-w-[60rem]\" style={{ margin: 0 }}>\n\t\t\t\tChoose how moltis is exposed beyond localhost. Tailscale is the safer default for tailnet access and\n\t\t\t\toptional public Funnel, while ngrok gives you a managed public HTTPS URL for teams, demos, and shared\n\t\t\t\tendpoints.\n\t\t\t</p>\n\t\t\t<div className=\"flex flex-col gap-4\">\n\t\t\t\t{renderTailscaleCard()}\n\t\t\t\t{renderNgrokCard()}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// ── Voice section ────────────────────────────────────────────\n\n// Voice section signals\nconst voiceShowAddModal = signal(false);\nconst voiceSelectedProvider = signal<string | null>(null);\nconst voiceSelectedProviderData = signal<VoiceProviderData | null>(null);\n\ninterface VoiceProviderData {\n\tid: string;\n\tname: string;\n\tdescription?: string;\n\ttype?: string;\n\tcategory?: string;\n\tavailable?: boolean;\n\tenabled?: boolean;\n\tkeySource?: string;\n\tsettingsSummary?: string;\n\tbinaryPath?: string;\n\tstatusMessage?: string;\n\tkeyPlaceholder?: string;\n\tkeyUrl?: string;\n\tkeyUrlLabel?: string;\n\thint?: string;\n\tcapabilities?: { baseUrl?: boolean };\n\tsettings?: { baseUrl?: string; voiceId?: string; voice?: string; model?: string; languageCode?: string };\n}\n\ninterface VoiceProviders {\n\ttts: VoiceProviderData[];\n\tstt: VoiceProviderData[];\n}\n\ninterface VoiceTesting {\n\tid: string;\n\ttype: string;\n\tphase: string;\n}\n\ninterface VoiceTestResult {\n\ttext?: string | null;\n\tsuccess?: boolean;\n\terror?: string | null;\n}\n\ninterface VoxtralRequirements {\n\tos?: string;\n\tarch?: string;\n\tcompatible?: boolean;\n\treasons?: string[];\n\tpython?: { available?: boolean; version?: string };\n\tcuda?: { available?: boolean; gpu_name?: string; memory_mb?: number };\n}\n\nfunction VoiceSection(): VNode {\n\tconst [allProviders, setAllProviders] = useState<VoiceProviders>({ tts: [], stt: [] });\n\tconst [voiceLoading, setVoiceLoading] = useState(true);\n\tconst [voxtralReqs, setVoxtralReqs] = useState<VoxtralRequirements | null>(null);\n\tconst [savingProvider, setSavingProvider] = useState<string | null>(null);\n\tconst [voiceMsg, setVoiceMsg] = useState<string | null>(null);\n\tconst [voiceErr, setVoiceErr] = useState<string | null>(null);\n\tconst [voiceTesting, setVoiceTesting] = useState<VoiceTesting | null>(null);\n\tconst [activeRecorder, setActiveRecorder] = useState<MediaRecorder | null>(null);\n\tconst [voiceTestResults, setVoiceTestResults] = useState<Record<string, VoiceTestResult>>({});\n\n\tfunction fetchVoiceStatus(options?: { silent?: boolean }): void {\n\t\tif (!options?.silent) {\n\t\t\tsetVoiceLoading(true);\n\t\t\trerender();\n\t\t}\n\t\tPromise.all([fetchVoiceProviders(), sendRpc(\"voice.config.voxtral_requirements\", {})])\n\t\t\t.then(([providers, voxtral]) => {\n\t\t\t\tconst provRes = providers as RpcResponse;\n\t\t\t\tconst voxtralRes = voxtral as RpcResponse;\n\t\t\t\tif (provRes?.ok) setAllProviders((provRes.payload as VoiceProviders) || { tts: [], stt: [] });\n\t\t\t\tif (voxtralRes?.ok) setVoxtralReqs(voxtralRes.payload as VoxtralRequirements);\n\t\t\t\tif (!options?.silent) setVoiceLoading(false);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch(() => {\n\t\t\t\tif (!options?.silent) setVoiceLoading(false);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tuseEffect(() => {\n\t\tif (connected.value) fetchVoiceStatus();\n\t}, [connected.value]);\n\n\tfunction onToggleProvider(provider: VoiceProviderData, enabled: boolean, providerType: string): void {\n\t\tsetVoiceErr(null);\n\t\tsetVoiceMsg(null);\n\t\tsetSavingProvider(provider.id);\n\t\trerender();\n\n\t\ttoggleVoiceProvider(provider.id, enabled, providerType)\n\t\t\t.then((r: unknown) => {\n\t\t\t\tconst res = r as RpcResponse;\n\t\t\t\tsetSavingProvider(null);\n\t\t\t\tif (res?.ok) {\n\t\t\t\t\tsetVoiceMsg(`${provider.name} ${enabled ? \"enabled\" : \"disabled\"}.`);\n\t\t\t\t\tsetTimeout(() => {\n\t\t\t\t\t\tsetVoiceMsg(null);\n\t\t\t\t\t\trerender();\n\t\t\t\t\t}, 2000);\n\t\t\t\t\tfetchVoiceStatus({ silent: true });\n\t\t\t\t} else {\n\t\t\t\t\tsetVoiceErr((res?.error as { message?: string })?.message || \"Failed to toggle provider\");\n\t\t\t\t}\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((err: Error) => {\n\t\t\t\tsetSavingProvider(null);\n\t\t\t\tsetVoiceErr(err.message);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onConfigureProvider(providerId: string, providerData: VoiceProviderData): void {\n\t\tvoiceSelectedProvider.value = providerId;\n\t\tvoiceSelectedProviderData.value = providerData || null;\n\t\tvoiceShowAddModal.value = true;\n\t}\n\n\tfunction getUnconfiguredProviders(): VoiceProviderData[] {\n\t\treturn [...allProviders.stt, ...allProviders.tts].filter((p) => !p.available);\n\t}\n\n\t// Stop active STT recording\n\tfunction stopSttRecording(): void {\n\t\tif (activeRecorder) {\n\t\t\tactiveRecorder.stop();\n\t\t}\n\t}\n\n\tfunction humanizeMicError(err: { name?: string; message?: string }): string {\n\t\tif (err.name === \"OverconstrainedError\" || (err.message && /constraint/i.test(err.message))) {\n\t\t\treturn \"No compatible microphone found. Check your audio input device.\";\n\t\t}\n\t\tif (err.name === \"NotFoundError\" || err.name === \"NotAllowedError\") {\n\t\t\treturn \"Microphone access denied or no microphone found. Check browser permissions.\";\n\t\t}\n\t\tif (err.name === \"NotReadableError\") {\n\t\t\treturn \"Microphone is in use by another application.\";\n\t\t}\n\t\treturn err.message || \"STT test failed\";\n\t}\n\n\t// Test a voice provider (TTS or STT)\n\tasync function testVoiceProvider(providerId: string, type: string): Promise<void> {\n\t\t// If already recording for this provider, stop it\n\t\tif (voiceTesting?.id === providerId && voiceTesting?.type === \"stt\" && voiceTesting?.phase === \"recording\") {\n\t\t\tstopSttRecording();\n\t\t\treturn;\n\t\t}\n\n\t\tsetVoiceErr(null);\n\t\tsetVoiceMsg(null);\n\t\tsetVoiceTesting({ id: providerId, type, phase: \"testing\" });\n\t\trerender();\n\n\t\tif (type === \"tts\") {\n\t\t\t// Test TTS by converting sample text to audio and playing it\n\t\t\ttry {\n\t\t\t\tconst id = gon.get(\"identity\") as { user_name?: string; name?: string } | undefined;\n\t\t\t\tconst user = id?.user_name || \"friend\";\n\t\t\t\tconst bot = id?.name || \"Moltis\";\n\t\t\t\tconst ttsText = await fetchPhrase(\"settings\", user, bot);\n\t\t\t\tconst res = (await testTts(ttsText, providerId)) as RpcResponse;\n\t\t\t\tif (res?.ok && (res.payload as { audio?: string })?.audio) {\n\t\t\t\t\tconst payload = res.payload as { audio: string; mimeType?: string; content_type?: string; format?: string };\n\t\t\t\t\t// Decode base64 audio and play it\n\t\t\t\t\tconst bytes = decodeBase64Safe(payload.audio);\n\t\t\t\t\tconst audioMime = payload.mimeType || payload.content_type || \"audio/mpeg\";\n\t\t\t\t\tconsole.log(\n\t\t\t\t\t\t\"[TTS] audio received: %d bytes, mime=%s, format=%s\",\n\t\t\t\t\t\tbytes.length,\n\t\t\t\t\t\taudioMime,\n\t\t\t\t\t\tpayload.format,\n\t\t\t\t\t);\n\t\t\t\t\tconst blob = new Blob([bytes as BlobPart], { type: audioMime });\n\t\t\t\t\tconst url = URL.createObjectURL(blob);\n\t\t\t\t\tconst audio = new Audio(url);\n\t\t\t\t\taudio.onerror = (e) => {\n\t\t\t\t\t\tconsole.error(\"[TTS] audio element error:\", audio.error?.message || e);\n\t\t\t\t\t\tURL.revokeObjectURL(url);\n\t\t\t\t\t};\n\t\t\t\t\taudio.onended = () => URL.revokeObjectURL(url);\n\t\t\t\t\taudio.play().catch((e: Error) => console.error(\"[TTS] play() failed:\", e));\n\t\t\t\t\tsetVoiceTestResults((prev) => ({\n\t\t\t\t\t\t...prev,\n\t\t\t\t\t\t[providerId]: { success: true, error: null },\n\t\t\t\t\t}));\n\t\t\t\t} else {\n\t\t\t\t\tsetVoiceTestResults((prev) => ({\n\t\t\t\t\t\t...prev,\n\t\t\t\t\t\t[providerId]: { success: false, error: (res?.error as { message?: string })?.message || \"TTS test failed\" },\n\t\t\t\t\t}));\n\t\t\t\t}\n\t\t\t} catch (err) {\n\t\t\t\tsetVoiceTestResults((prev) => ({\n\t\t\t\t\t...prev,\n\t\t\t\t\t[providerId]: { success: false, error: (err as Error).message || \"TTS test failed\" },\n\t\t\t\t}));\n\t\t\t}\n\t\t\tsetVoiceTesting(null);\n\t\t} else {\n\t\t\t// Test STT by recording audio and transcribing\n\t\t\ttry {\n\t\t\t\tconst stream = await navigator.mediaDevices.getUserMedia({ audio: true });\n\t\t\t\tconst mimeType = MediaRecorder.isTypeSupported(\"audio/webm;codecs=opus\")\n\t\t\t\t\t? \"audio/webm;codecs=opus\"\n\t\t\t\t\t: \"audio/webm\";\n\t\t\t\tconst mediaRecorder = new MediaRecorder(stream, { mimeType });\n\t\t\t\tconst audioChunks: Blob[] = [];\n\n\t\t\t\tmediaRecorder.ondataavailable = (e: BlobEvent) => {\n\t\t\t\t\tif (e.data.size > 0) audioChunks.push(e.data);\n\t\t\t\t};\n\n\t\t\t\tmediaRecorder.start();\n\t\t\t\tsetActiveRecorder(mediaRecorder);\n\t\t\t\tsetVoiceTesting({ id: providerId, type, phase: \"recording\" });\n\t\t\t\trerender();\n\n\t\t\t\tmediaRecorder.onstop = async () => {\n\t\t\t\t\tsetActiveRecorder(null);\n\t\t\t\t\tfor (const track of stream.getTracks()) track.stop();\n\t\t\t\t\tsetVoiceTesting({ id: providerId, type, phase: \"transcribing\" });\n\t\t\t\t\trerender();\n\n\t\t\t\t\tconst audioBlob = new Blob(audioChunks, { type: mediaRecorder.mimeType || mimeType });\n\n\t\t\t\t\ttry {\n\t\t\t\t\t\tconst resp = await transcribeAudio(S.activeSessionKey, providerId, audioBlob);\n\t\t\t\t\t\tconsole.log(\"[STT] upload response: status=%d ok=%s\", resp.status, resp.ok);\n\t\t\t\t\t\tif (resp.ok) {\n\t\t\t\t\t\t\tconst sttRes = await resp.json() as { ok?: boolean; transcription?: { text?: string }; transcriptionError?: string; error?: string };\n\n\t\t\t\t\t\t\tif (sttRes.ok && typeof sttRes.transcription?.text === \"string\") {\n\t\t\t\t\t\t\t\tconst transcriptText = sttRes.transcription.text.trim();\n\t\t\t\t\t\t\t\tsetVoiceTestResults((prev) => ({\n\t\t\t\t\t\t\t\t\t...prev,\n\t\t\t\t\t\t\t\t\t[providerId]: {\n\t\t\t\t\t\t\t\t\t\ttext: transcriptText || null,\n\t\t\t\t\t\t\t\t\t\terror: transcriptText ? null : \"No speech detected\",\n\t\t\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\t\t}));\n\t\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\t\tsetVoiceTestResults((prev) => ({\n\t\t\t\t\t\t\t\t\t...prev,\n\t\t\t\t\t\t\t\t\t[providerId]: {\n\t\t\t\t\t\t\t\t\t\ttext: null,\n\t\t\t\t\t\t\t\t\t\terror: sttRes.transcriptionError || sttRes.error || \"STT test failed\",\n\t\t\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\t\t}));\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\tconst errBody = await resp.text();\n\t\t\t\t\t\t\tconsole.error(\"[STT] upload failed: status=%d body=%s\", resp.status, errBody);\n\t\t\t\t\t\t\tlet errMsg = \"STT test failed\";\n\t\t\t\t\t\t\ttry {\n\t\t\t\t\t\t\t\terrMsg = (JSON.parse(errBody) as { error?: string })?.error || errMsg;\n\t\t\t\t\t\t\t} catch (_e) {\n\t\t\t\t\t\t\t\t// not JSON\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\tsetVoiceTestResults((prev) => ({\n\t\t\t\t\t\t\t\t...prev,\n\t\t\t\t\t\t\t\t[providerId]: { text: null, error: `${errMsg} (HTTP ${resp.status})` },\n\t\t\t\t\t\t\t}));\n\t\t\t\t\t\t}\n\t\t\t\t\t} catch (fetchErr) {\n\t\t\t\t\t\tsetVoiceTestResults((prev) => ({\n\t\t\t\t\t\t\t...prev,\n\t\t\t\t\t\t\t[providerId]: { text: null, error: (fetchErr as Error).message || \"STT test failed\" },\n\t\t\t\t\t\t}));\n\t\t\t\t\t}\n\t\t\t\t\tsetVoiceTesting(null);\n\t\t\t\t\trerender();\n\t\t\t\t};\n\t\t\t} catch (err) {\n\t\t\t\tsetVoiceErr(humanizeMicError(err as { name?: string; message?: string }));\n\t\t\t\tsetVoiceTesting(null);\n\t\t\t}\n\t\t}\n\t\trerender();\n\t}\n\n\tif (voiceLoading || !connected.value) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Voice</h2>\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">{connected.value ? \"Loading\\u2026\" : \"Connecting\\u2026\"}</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Voice</h2>\n\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed\" style={{ maxWidth: \"600px\", margin: 0 }}>\n\t\t\t\tConfigure text-to-speech (TTS) and speech-to-text (STT) providers. STT lets you use the microphone button in chat to record voice input. TTS lets you hear responses as audio.\n\t\t\t</p>\n\n\t\t\t{voiceMsg ? <div className=\"text-xs text-[var(--accent)]\">{voiceMsg}</div> : null}\n\t\t\t{voiceErr ? <div className=\"text-xs text-[var(--error)]\">{voiceErr}</div> : null}\n\n\t\t\t<div style={{ maxWidth: \"700px\", display: \"flex\", flexDirection: \"column\", gap: \"24px\" }}>\n\t\t\t\t{/* STT Providers */}\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Speech-to-Text (Voice Input)</h3>\n\t\t\t\t\t<div className=\"flex flex-col gap-2\">\n\t\t\t\t\t\t{allProviders.stt.map((prov) => {\n\t\t\t\t\t\t\tconst meta = prov;\n\t\t\t\t\t\t\tconst testState = voiceTesting?.id === prov.id && voiceTesting?.type === \"stt\" ? voiceTesting : null;\n\t\t\t\t\t\t\tconst testResult = voiceTestResults[prov.id] || null;\n\t\t\t\t\t\t\treturn (\n\t\t\t\t\t\t\t\t<VoiceProviderRow\n\t\t\t\t\t\t\t\t\tkey={prov.id}\n\t\t\t\t\t\t\t\t\tprovider={prov}\n\t\t\t\t\t\t\t\t\tmeta={meta}\n\t\t\t\t\t\t\t\t\ttype=\"stt\"\n\t\t\t\t\t\t\t\t\tsaving={savingProvider === prov.id}\n\t\t\t\t\t\t\t\t\ttestState={testState}\n\t\t\t\t\t\t\t\t\ttestResult={testResult}\n\t\t\t\t\t\t\t\t\tonToggle={(enabled: boolean) => onToggleProvider(prov, enabled, \"stt\")}\n\t\t\t\t\t\t\t\t\tonConfigure={() => onConfigureProvider(prov.id, prov)}\n\t\t\t\t\t\t\t\t\tonTest={() => testVoiceProvider(prov.id, \"stt\")}\n\t\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t);\n\t\t\t\t\t\t})}\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\n\t\t\t\t{/* TTS Providers */}\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Text-to-Speech (Audio Responses)</h3>\n\t\t\t\t\t<div className=\"flex flex-col gap-2\">\n\t\t\t\t\t\t{allProviders.tts.map((prov) => {\n\t\t\t\t\t\t\tconst meta = prov;\n\t\t\t\t\t\t\tconst testState = voiceTesting?.id === prov.id && voiceTesting?.type === \"tts\" ? voiceTesting : null;\n\t\t\t\t\t\t\tconst testResult = voiceTestResults[prov.id] || null;\n\t\t\t\t\t\t\treturn (\n\t\t\t\t\t\t\t\t<VoiceProviderRow\n\t\t\t\t\t\t\t\t\tkey={prov.id}\n\t\t\t\t\t\t\t\t\tprovider={prov}\n\t\t\t\t\t\t\t\t\tmeta={meta}\n\t\t\t\t\t\t\t\t\ttype=\"tts\"\n\t\t\t\t\t\t\t\t\tsaving={savingProvider === prov.id}\n\t\t\t\t\t\t\t\t\ttestState={testState}\n\t\t\t\t\t\t\t\t\ttestResult={testResult}\n\t\t\t\t\t\t\t\t\tonToggle={(enabled: boolean) => onToggleProvider(prov, enabled, \"tts\")}\n\t\t\t\t\t\t\t\t\tonConfigure={() => onConfigureProvider(prov.id, prov)}\n\t\t\t\t\t\t\t\t\tonTest={() => testVoiceProvider(prov.id, \"tts\")}\n\t\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t);\n\t\t\t\t\t\t})}\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t<AddVoiceProviderModal\n\t\t\t\tunconfiguredProviders={getUnconfiguredProviders()}\n\t\t\t\tvoxtralReqs={voxtralReqs}\n\t\t\t\tonSaved={() => {\n\t\t\t\t\tfetchVoiceStatus();\n\t\t\t\t\tvoiceShowAddModal.value = false;\n\t\t\t\t\tvoiceSelectedProvider.value = null;\n\t\t\t\t\tvoiceSelectedProviderData.value = null;\n\t\t\t\t}}\n\t\t\t/>\n\t\t</div>\n\t);\n}\n\n// Individual provider row with enable toggle\n\ninterface VoiceProviderRowProps {\n\tprovider: VoiceProviderData;\n\tmeta: VoiceProviderData;\n\ttype: string;\n\tsaving: boolean;\n\ttestState: VoiceTesting | null;\n\ttestResult: VoiceTestResult | null;\n\tonToggle: (enabled: boolean) => void;\n\tonConfigure: () => void;\n\tonTest: () => void;\n}\n\nfunction VoiceProviderRow({ provider, meta, type, saving, testState, testResult, onToggle, onConfigure, onTest }: VoiceProviderRowProps): VNode {\n\tconst canEnable = provider.available;\n\tconst keySourceLabel =\n\t\tprovider.keySource === \"env\" ? \"(from env)\" : provider.keySource === \"llm_provider\" ? \"(from LLM provider)\" : \"\";\n\tconst showTestBtn = canEnable && provider.enabled;\n\n\t// Determine button text based on test state\n\tlet buttonText = \"Test\";\n\tlet buttonDisabled = false;\n\tif (testState) {\n\t\tif (testState.phase === \"recording\") {\n\t\t\tbuttonText = \"Stop\";\n\t\t} else if (testState.phase === \"transcribing\") {\n\t\t\tbuttonText = \"Testing\\u2026\";\n\t\t\tbuttonDisabled = true;\n\t\t} else {\n\t\t\tbuttonText = \"Testing\\u2026\";\n\t\t\tbuttonDisabled = true;\n\t\t}\n\t}\n\n\treturn (\n\t\t<div className=\"provider-card\" style={{ padding: \"10px 14px\", borderRadius: \"8px\", display: \"flex\", alignItems: \"center\", gap: \"12px\" }}>\n\t\t\t<div style={{ flex: 1, display: \"flex\", flexDirection: \"column\", gap: \"2px\" }}>\n\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\" }}>\n\t\t\t\t\t<span className=\"text-sm text-[var(--text-strong)]\">{meta.name}</span>\n\t\t\t\t\t{provider.category === \"local\" ? <span className=\"provider-item-badge\">local</span> : null}\n\t\t\t\t\t{keySourceLabel ? <span className=\"text-xs text-[var(--muted)]\">{keySourceLabel}</span> : null}\n\t\t\t\t</div>\n\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">{meta.description}</span>\n\t\t\t\t{provider.settingsSummary ? <span className=\"text-xs text-[var(--muted)]\">Voice: {provider.settingsSummary}</span> : null}\n\t\t\t\t{provider.binaryPath ? <span className=\"text-xs text-[var(--muted)]\">Found at: {provider.binaryPath}</span> : null}\n\t\t\t\t{!canEnable && provider.statusMessage ? <span className=\"text-xs text-[var(--muted)]\">{provider.statusMessage}</span> : null}\n\t\t\t\t{testState?.phase === \"recording\"\n\t\t\t\t\t? <div className=\"voice-recording-hint\">\n\t\t\t\t\t\t<span className=\"voice-recording-dot\" />\n\t\t\t\t\t\t<span>Speak now, then click Stop when finished</span>\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t\t{testState?.phase === \"transcribing\" ? <span className=\"text-xs text-[var(--muted)]\">Transcribing...</span> : null}\n\t\t\t\t{testState?.phase === \"testing\" && type === \"tts\" ? <span className=\"text-xs text-[var(--muted)]\">Playing audio...</span> : null}\n\t\t\t\t{testResult?.text\n\t\t\t\t\t? <div className=\"voice-transcription-result\">\n\t\t\t\t\t\t<span className=\"voice-transcription-label\">Transcribed:</span>\n\t\t\t\t\t\t<span className=\"voice-transcription-text\">\"{testResult.text}\"</span>\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t\t{testResult?.success === true\n\t\t\t\t\t? <div className=\"voice-success-result\">\n\t\t\t\t\t\t<span className=\"icon icon-md icon-check-circle\" />\n\t\t\t\t\t\t<span>Audio played successfully</span>\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t\t{testResult?.error\n\t\t\t\t\t? <div className=\"voice-error-result\">\n\t\t\t\t\t\t<span className=\"icon icon-md icon-x-circle\" />\n\t\t\t\t\t\t<span>{testResult.error}</span>\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t</div>\n\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\" }}>\n\t\t\t\t<button className=\"provider-btn provider-btn-secondary provider-btn-sm\" onClick={onConfigure}>\n\t\t\t\t\tConfigure\n\t\t\t\t</button>\n\t\t\t\t{showTestBtn\n\t\t\t\t\t? <button\n\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary provider-btn-sm\"\n\t\t\t\t\t\tonClick={onTest}\n\t\t\t\t\t\tdisabled={buttonDisabled}\n\t\t\t\t\t\ttitle={type === \"tts\" ? \"Test voice output\" : \"Test voice input\"}\n\t\t\t\t\t>\n\t\t\t\t\t\t{buttonText}\n\t\t\t\t\t</button>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t\t{canEnable\n\t\t\t\t\t? <label className=\"toggle-switch\">\n\t\t\t\t\t\t<input type=\"checkbox\"\n\t\t\t\t\t\t\tchecked={provider.enabled}\n\t\t\t\t\t\t\tdisabled={saving}\n\t\t\t\t\t\t\tonChange={(e: Event) => onToggle((e.target as HTMLInputElement).checked)} />\n\t\t\t\t\t\t<span className=\"toggle-slider\" />\n\t\t\t\t\t</label>\n\t\t\t\t\t: provider.category === \"local\"\n\t\t\t\t\t\t? <span className=\"text-xs text-[var(--muted)]\">Install required</span>\n\t\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// Local provider instructions component (uses hidden HTML elements)\n\ninterface LocalProviderInstructionsProps {\n\tproviderId: string;\n\tvoxtralReqs: VoxtralRequirements | null;\n}\n\nfunction LocalProviderInstructions({ providerId, voxtralReqs }: LocalProviderInstructionsProps): VNode {\n\tconst ref = useRef<HTMLDivElement>(null);\n\n\tuseEffect(() => {\n\t\tconst container = ref.current;\n\t\tif (!container) return;\n\t\twhile (container.firstChild) container.removeChild(container.firstChild);\n\n\t\tconst templateId: Record<string, string> = {\n\t\t\t\"whisper-cli\": \"voice-whisper-cli-instructions\",\n\t\t\t\"sherpa-onnx\": \"voice-sherpa-onnx-instructions\",\n\t\t\tpiper: \"voice-piper-instructions\",\n\t\t\tcoqui: \"voice-coqui-instructions\",\n\t\t\t\"voxtral-local\": \"voice-voxtral-instructions\",\n\t\t};\n\n\t\tconst tplId = templateId[providerId];\n\t\tif (!tplId) return;\n\n\t\tconst el = cloneHidden(tplId);\n\t\tif (!el) return;\n\n\t\t// For voxtral-local, populate the requirements section\n\t\tif (providerId === \"voxtral-local\" && el.querySelector(\"[data-voxtral-requirements]\")) {\n\t\t\tconst reqsContainer = el.querySelector(\"[data-voxtral-requirements]\") as HTMLElement;\n\t\t\tif (voxtralReqs) {\n\t\t\t\tlet detected = `${voxtralReqs.os}/${voxtralReqs.arch}`;\n\t\t\t\tif (voxtralReqs.python?.available) detected += `, Python ${voxtralReqs.python.version}`;\n\t\t\t\telse detected += \", no Python\";\n\t\t\t\tif (voxtralReqs.cuda?.available) {\n\t\t\t\t\tdetected += `, ${voxtralReqs.cuda.gpu_name || \"NVIDIA GPU\"} (${Math.round((voxtralReqs.cuda.memory_mb || 0) / 1024)}GB)`;\n\t\t\t\t} else detected += \", no CUDA GPU\";\n\n\t\t\t\tconst reqEl = cloneHidden(\n\t\t\t\t\tvoxtralReqs.compatible ? \"voice-voxtral-requirements-ok\" : \"voice-voxtral-requirements-fail\",\n\t\t\t\t);\n\t\t\t\tif (reqEl) {\n\t\t\t\t\tconst detectedEl = reqEl.querySelector(\"[data-voxtral-detected]\") as HTMLElement;\n\t\t\t\t\tif (detectedEl) detectedEl.textContent = detected;\n\t\t\t\t\tif (!voxtralReqs.compatible && voxtralReqs.reasons?.length) {\n\t\t\t\t\t\tconst ul = reqEl.querySelector(\"[data-voxtral-reasons]\") as HTMLElement;\n\t\t\t\t\t\tfor (const r of voxtralReqs.reasons) {\n\t\t\t\t\t\t\tconst li = document.createElement(\"li\");\n\t\t\t\t\t\t\tli.style.margin = \"2px 0\";\n\t\t\t\t\t\t\tli.textContent = r;\n\t\t\t\t\t\t\tul.appendChild(li);\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\treqsContainer.appendChild(reqEl);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tconst loadingEl = document.createElement(\"div\");\n\t\t\t\tloadingEl.className = \"text-xs text-[var(--muted)] mb-3\";\n\t\t\t\tloadingEl.textContent = \"Checking system requirements\\u2026\";\n\t\t\t\treqsContainer.appendChild(loadingEl);\n\t\t\t}\n\t\t}\n\n\t\tcontainer.appendChild(el);\n\t}, [providerId, voxtralReqs]);\n\n\treturn <div ref={ref} />;\n}\n\n// Add Voice Provider Modal\n\ninterface AddVoiceProviderModalProps {\n\tunconfiguredProviders: VoiceProviderData[];\n\tvoxtralReqs: VoxtralRequirements | null;\n\tonSaved: () => void;\n}\n\ninterface ElevenlabsCatalog {\n\tvoices: { id: string; name: string }[];\n\tmodels: { id: string; name: string }[];\n\twarning: string | null;\n}\n\nfunction AddVoiceProviderModal({ unconfiguredProviders, voxtralReqs, onSaved }: AddVoiceProviderModalProps): VNode {\n\tconst [apiKey, setApiKey] = useState(\"\");\n\tconst [baseUrlValue, setBaseUrlValue] = useState(\"\");\n\tconst [voiceValue, setVoiceValue] = useState(\"\");\n\tconst [modelValue, setModelValue] = useState(\"\");\n\tconst [languageCodeValue, setLanguageCodeValue] = useState(\"\");\n\tconst [elevenlabsCatalog, setElevenlabsCatalog] = useState<ElevenlabsCatalog>({ voices: [], models: [], warning: null });\n\tconst [elevenlabsCatalogLoading, setElevenlabsCatalogLoading] = useState(false);\n\tconst [saving, setSaving] = useState(false);\n\tconst [error, setError] = useState(\"\");\n\n\tconst selectedProvider = voiceSelectedProvider.value;\n\tconst providerMeta = selectedProvider\n\t\t? unconfiguredProviders.find((p) => p.id === selectedProvider) || voiceSelectedProviderData.value\n\t\t: null;\n\tconst isElevenLabsProvider = selectedProvider === \"elevenlabs\" || selectedProvider === \"elevenlabs-stt\";\n\tconst supportsTtsVoiceSettings = providerMeta?.type === \"tts\";\n\tconst supportsBaseUrl = providerMeta?.capabilities?.baseUrl === true;\n\n\tfunction onClose(): void {\n\t\tvoiceShowAddModal.value = false;\n\t\tvoiceSelectedProvider.value = null;\n\t\tvoiceSelectedProviderData.value = null;\n\t\tsetApiKey(\"\");\n\t\tsetBaseUrlValue(\"\");\n\t\tsetVoiceValue(\"\");\n\t\tsetModelValue(\"\");\n\t\tsetLanguageCodeValue(\"\");\n\t\tsetError(\"\");\n\t}\n\n\tfunction onSaveKey(): void {\n\t\tconst hasApiKey = apiKey.trim().length > 0;\n\t\tconst trimmedBaseUrl = baseUrlValue.trim();\n\t\tconst hadBaseUrl =\n\t\t\ttypeof providerMeta?.settings?.baseUrl === \"string\" && providerMeta.settings.baseUrl.trim().length > 0;\n\t\tconst hasBaseUrl = supportsBaseUrl && (trimmedBaseUrl.length > 0 || hadBaseUrl);\n\t\tconst hasSettings =\n\t\t\t(supportsTtsVoiceSettings && (voiceValue.trim() || modelValue.trim() || languageCodeValue.trim())) || hasBaseUrl;\n\t\tif (!(hasApiKey || hasSettings)) {\n\t\t\tsetError(\"Provide an API key, base URL, or at least one provider setting.\");\n\t\t\treturn;\n\t\t}\n\t\tsetError(\"\");\n\t\tsetSaving(true);\n\n\t\tconst voiceOpts = {\n\t\t\tbaseUrl: hasBaseUrl ? trimmedBaseUrl : undefined,\n\t\t\tvoice: supportsTtsVoiceSettings ? voiceValue.trim() || undefined : undefined,\n\t\t\tmodel: supportsTtsVoiceSettings ? modelValue.trim() || undefined : undefined,\n\t\t\tlanguageCode: supportsTtsVoiceSettings ? languageCodeValue.trim() || undefined : undefined,\n\t\t};\n\t\tconst req = hasApiKey\n\t\t\t? saveVoiceKey(selectedProvider as string, apiKey.trim(), voiceOpts)\n\t\t\t: saveVoiceSettings(selectedProvider as string, voiceOpts);\n\t\treq\n\t\t\t.then((r: unknown) => {\n\t\t\t\tconst res = r as RpcResponse;\n\t\t\t\tsetSaving(false);\n\t\t\t\tif (res?.ok) {\n\t\t\t\t\tsetApiKey(\"\");\n\t\t\t\t\tonSaved();\n\t\t\t\t} else {\n\t\t\t\t\tsetError((res?.error as { message?: string })?.message || \"Failed to save key\");\n\t\t\t\t}\n\t\t\t})\n\t\t\t.catch((err: Error) => {\n\t\t\t\tsetSaving(false);\n\t\t\t\tsetError(err.message);\n\t\t\t});\n\t}\n\n\tfunction onSelectProvider(providerId: string): void {\n\t\tvoiceSelectedProvider.value = providerId;\n\t\tvoiceSelectedProviderData.value = null;\n\t\tsetApiKey(\"\");\n\t\tsetBaseUrlValue(\"\");\n\t\tsetVoiceValue(\"\");\n\t\tsetModelValue(\"\");\n\t\tsetLanguageCodeValue(\"\");\n\t\tsetError(\"\");\n\t}\n\n\tuseEffect(() => {\n\t\tconst settings = voiceSelectedProviderData.value?.settings;\n\t\tif (!settings) return;\n\t\tsetBaseUrlValue(settings.baseUrl || \"\");\n\t\tsetVoiceValue(settings.voiceId || settings.voice || \"\");\n\t\tsetModelValue(settings.model || \"\");\n\t\tsetLanguageCodeValue(settings.languageCode || \"\");\n\t}, [selectedProvider, voiceSelectedProviderData.value]);\n\n\tuseEffect(() => {\n\t\tif (!isElevenLabsProvider) {\n\t\t\tsetElevenlabsCatalog({ voices: [], models: [], warning: null });\n\t\t\treturn;\n\t\t}\n\t\tsetElevenlabsCatalogLoading(true);\n\t\tsendRpc(\"voice.elevenlabs.catalog\", {})\n\t\t\t.then((res: RpcResponse) => {\n\t\t\t\tif (res?.ok) {\n\t\t\t\t\tconst payload = res.payload as { voices?: { id: string; name: string }[]; models?: { id: string; name: string }[]; warning?: string };\n\t\t\t\t\tsetElevenlabsCatalog({\n\t\t\t\t\t\tvoices: payload?.voices || [],\n\t\t\t\t\t\tmodels: payload?.models || [],\n\t\t\t\t\t\twarning: payload?.warning || null,\n\t\t\t\t\t});\n\t\t\t\t}\n\t\t\t})\n\t\t\t.catch(() => {\n\t\t\t\tsetElevenlabsCatalog({ voices: [], models: [], warning: \"Failed to fetch ElevenLabs voice catalog.\" });\n\t\t\t})\n\t\t\t.finally(() => {\n\t\t\t\tsetElevenlabsCatalogLoading(false);\n\t\t\t\trerender();\n\t\t\t});\n\t}, [selectedProvider, isElevenLabsProvider]);\n\n\t// Group providers by type and category\n\tconst sttCloud = unconfiguredProviders.filter((p) => p.type === \"stt\" && p.category === \"cloud\");\n\tconst sttLocal = unconfiguredProviders.filter((p) => p.type === \"stt\" && p.category === \"local\");\n\tconst ttsProviders = unconfiguredProviders.filter((p) => p.type === \"tts\");\n\n\t// If a provider is selected, show its configuration form\n\tif (selectedProvider && providerMeta) {\n\t\t// Cloud provider - show API key form\n\t\tif (providerMeta.category === \"cloud\") {\n\t\t\treturn (\n\t\t\t\t<Modal show={voiceShowAddModal.value} onClose={onClose} title={`Add ${providerMeta.name}`}>\n\t\t\t\t\t<div className=\"channel-form\">\n\t\t\t\t\t\t<div className=\"text-sm text-[var(--text-strong)]\">{providerMeta.name}</div>\n\t\t\t\t\t\t<div className=\"mb-3 text-xs text-[var(--muted)]\">{providerMeta.description}</div>\n\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">API Key</label>\n\t\t\t\t\t\t<input type=\"password\" className=\"provider-key-input w-full\"\n\t\t\t\t\t\t\tvalue={apiKey} onInput={(e: Event) => setApiKey((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\tplaceholder={providerMeta.keyPlaceholder || \"Leave blank to keep existing key\"} />\n\t\t\t\t\t\t{providerMeta.keyUrl\n\t\t\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\tGet your API key at <a href={providerMeta.keyUrl} target=\"_blank\" rel=\"noopener\" className=\"hover:underline text-[var(--accent)]\">{providerMeta.keyUrlLabel}</a>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\t{supportsBaseUrl\n\t\t\t\t\t\t\t? <div className=\"mt-2 flex flex-col gap-2\">\n\t\t\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Base URL</label>\n\t\t\t\t\t\t\t\t<input type=\"text\" className=\"provider-key-input w-full\"\n\t\t\t\t\t\t\t\t\tdata-field=\"baseUrl\"\n\t\t\t\t\t\t\t\t\tvalue={baseUrlValue} onInput={(e: Event) => setBaseUrlValue((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\t\tplaceholder=\"http://localhost:8000/v1\" />\n\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\t\tUse this for a local or OpenAI-compatible server. Leave the API key blank if your endpoint does not require one.\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\t{supportsTtsVoiceSettings\n\t\t\t\t\t\t\t? <div className=\"flex flex-col gap-2\">\n\t\t\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Voice</label>\n\t\t\t\t\t\t\t\t{isElevenLabsProvider && elevenlabsCatalogLoading ? <div className=\"text-xs text-[var(--muted)]\">Loading ElevenLabs voices...</div> : null}\n\t\t\t\t\t\t\t\t{isElevenLabsProvider && elevenlabsCatalog.warning ? <div className=\"text-xs text-[var(--muted)]\">{elevenlabsCatalog.warning}</div> : null}\n\t\t\t\t\t\t\t\t{isElevenLabsProvider && elevenlabsCatalog.voices.length > 0\n\t\t\t\t\t\t\t\t\t? <select className=\"provider-key-input w-full\" onChange={(e: Event) => setVoiceValue((e.target as HTMLSelectElement).value)}>\n\t\t\t\t\t\t\t\t\t\t<option value=\"\">Pick a voice from your account...</option>\n\t\t\t\t\t\t\t\t\t\t{elevenlabsCatalog.voices.map((v) => <option key={v.id} value={v.id}>{v.name} ({v.id})</option>)}\n\t\t\t\t\t\t\t\t\t</select>\n\t\t\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t<input type=\"text\" className=\"provider-key-input w-full\"\n\t\t\t\t\t\t\t\t\tvalue={voiceValue} onInput={(e: Event) => setVoiceValue((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\t\tlist={isElevenLabsProvider ? \"elevenlabs-voice-options\" : undefined}\n\t\t\t\t\t\t\t\t\tplaceholder=\"voice id / name (optional)\" />\n\t\t\t\t\t\t\t\t{isElevenLabsProvider\n\t\t\t\t\t\t\t\t\t? <datalist id=\"elevenlabs-voice-options\">\n\t\t\t\t\t\t\t\t\t\t{elevenlabsCatalog.voices.map((v) => <option key={v.id} value={v.id}>{v.name}</option>)}\n\t\t\t\t\t\t\t\t\t</datalist>\n\t\t\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t\t\t}\n\n\t\t\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Model</label>\n\t\t\t\t\t\t\t\t{isElevenLabsProvider && elevenlabsCatalog.models.length > 0\n\t\t\t\t\t\t\t\t\t? <select className=\"provider-key-input w-full\" onChange={(e: Event) => setModelValue((e.target as HTMLSelectElement).value)}>\n\t\t\t\t\t\t\t\t\t\t<option value=\"\">Pick a model...</option>\n\t\t\t\t\t\t\t\t\t\t{elevenlabsCatalog.models.map((m) => <option key={m.id} value={m.id}>{m.name} ({m.id})</option>)}\n\t\t\t\t\t\t\t\t\t</select>\n\t\t\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t<input type=\"text\" className=\"provider-key-input w-full\"\n\t\t\t\t\t\t\t\t\tvalue={modelValue} onInput={(e: Event) => setModelValue((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\t\tlist={isElevenLabsProvider ? \"elevenlabs-model-options\" : undefined}\n\t\t\t\t\t\t\t\t\tplaceholder=\"model (optional)\" />\n\t\t\t\t\t\t\t\t{isElevenLabsProvider\n\t\t\t\t\t\t\t\t\t? <datalist id=\"elevenlabs-model-options\">\n\t\t\t\t\t\t\t\t\t\t{elevenlabsCatalog.models.map((m) => <option key={m.id} value={m.id}>{m.name}</option>)}\n\t\t\t\t\t\t\t\t\t</datalist>\n\t\t\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t\t\t}\n\n\t\t\t\t\t\t\t\t{selectedProvider === \"google\" || selectedProvider === \"google-tts\"\n\t\t\t\t\t\t\t\t\t? <div className=\"flex flex-col gap-2\">\n\t\t\t\t\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Language Code</label>\n\t\t\t\t\t\t\t\t\t\t<input type=\"text\" className=\"provider-key-input w-full\"\n\t\t\t\t\t\t\t\t\t\t\tvalue={languageCodeValue} onInput={(e: Event) => setLanguageCodeValue((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\t\t\t\tplaceholder=\"en-US (optional)\" />\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: null\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\t{providerMeta.hint ? <div className=\"text-xs text-[var(--muted)]\" style={{ marginTop: \"8px\", padding: \"8px\", background: \"var(--surface-alt)\", borderRadius: \"4px\", fontStyle: \"italic\" }}>{providerMeta.hint}</div> : null}\n\n\t\t\t\t\t\t{error ? <div className=\"text-xs\" style={{ color: \"var(--error)\" }}>{error}</div> : null}\n\n\t\t\t\t\t\t<div style={{ display: \"flex\", gap: \"8px\", marginTop: \"8px\" }}>\n\t\t\t\t\t\t\t<button className=\"provider-btn provider-btn-secondary\" onClick={() => {\n\t\t\t\t\t\t\t\tvoiceSelectedProvider.value = null;\n\t\t\t\t\t\t\t\tsetApiKey(\"\");\n\t\t\t\t\t\t\t\tsetError(\"\");\n\t\t\t\t\t\t\t}}>Back</button>\n\t\t\t\t\t\t\t<button className=\"provider-btn\" disabled={saving} onClick={onSaveKey}>\n\t\t\t\t\t\t\t\t{saving ? \"Saving\\u2026\" : \"Save\"}\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t</Modal>\n\t\t\t);\n\t\t}\n\n\t\t// Local provider - show setup instructions\n\t\tif (providerMeta.category === \"local\") {\n\t\t\treturn (\n\t\t\t\t<Modal show={voiceShowAddModal.value} onClose={onClose} title={`Add ${providerMeta.name}`}>\n\t\t\t\t\t<div className=\"channel-form\">\n\t\t\t\t\t\t<div className=\"text-sm text-[var(--text-strong)]\">{providerMeta.name}</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"12px\" }}>{providerMeta.description}</div>\n\t\t\t\t\t\t<LocalProviderInstructions providerId={selectedProvider} voxtralReqs={voxtralReqs} />\n\t\t\t\t\t\t<div style={{ display: \"flex\", gap: \"8px\", marginTop: \"12px\" }}>\n\t\t\t\t\t\t\t<button className=\"provider-btn provider-btn-secondary\" onClick={() => {\n\t\t\t\t\t\t\t\tvoiceSelectedProvider.value = null;\n\t\t\t\t\t\t\t}}>Back</button>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t</Modal>\n\t\t\t);\n\t\t}\n\t}\n\n\t// Show provider selection list\n\treturn (\n\t\t<Modal show={voiceShowAddModal.value} onClose={onClose} title=\"Add Voice Provider\">\n\t\t\t<div className=\"channel-form\" style={{ gap: \"16px\" }}>\n\t\t\t\t{sttCloud.length > 0\n\t\t\t\t\t? <div>\n\t\t\t\t\t\t<h4 className=\"text-xs font-medium text-[var(--muted)]\" style={{ margin: \"0 0 8px\", textTransform: \"uppercase\", letterSpacing: \"0.5px\" }}>Speech-to-Text (Cloud)</h4>\n\t\t\t\t\t\t<div style={{ display: \"flex\", flexDirection: \"column\", gap: \"6px\" }}>\n\t\t\t\t\t\t\t{sttCloud.map((p) => (\n\t\t\t\t\t\t\t\t<button key={p.id} className=\"provider-card\" style={{ padding: \"10px 12px\", borderRadius: \"6px\", cursor: \"pointer\", textAlign: \"left\", border: \"1px solid var(--border)\", background: \"var(--surface)\" }}\n\t\t\t\t\t\t\t\t\tonClick={() => onSelectProvider(p.id)}>\n\t\t\t\t\t\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\" }}>\n\t\t\t\t\t\t\t\t\t\t<div style={{ flex: 1 }}>\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"text-sm text-[var(--text-strong)]\">{p.name}</div>\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">{p.description}</div>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<span className=\"icon icon-chevron-right\" style={{ color: \"var(--muted)\" }} />\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t))}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\n\t\t\t\t{sttLocal.length > 0\n\t\t\t\t\t? <div>\n\t\t\t\t\t\t<h4 className=\"text-xs font-medium text-[var(--muted)]\" style={{ margin: \"0 0 8px\", textTransform: \"uppercase\", letterSpacing: \"0.5px\" }}>Speech-to-Text (Local)</h4>\n\t\t\t\t\t\t<div style={{ display: \"flex\", flexDirection: \"column\", gap: \"6px\" }}>\n\t\t\t\t\t\t\t{sttLocal.map((p) => (\n\t\t\t\t\t\t\t\t<button key={p.id} className=\"provider-card\" style={{ padding: \"10px 12px\", borderRadius: \"6px\", cursor: \"pointer\", textAlign: \"left\", border: \"1px solid var(--border)\", background: \"var(--surface)\" }}\n\t\t\t\t\t\t\t\t\tonClick={() => onSelectProvider(p.id)}>\n\t\t\t\t\t\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\" }}>\n\t\t\t\t\t\t\t\t\t\t<div style={{ flex: 1 }}>\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"text-sm text-[var(--text-strong)]\">{p.name}</div>\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">{p.description}</div>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<span className=\"icon icon-chevron-right\" style={{ color: \"var(--muted)\" }} />\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t))}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\n\t\t\t\t{ttsProviders.length > 0\n\t\t\t\t\t? <div>\n\t\t\t\t\t\t<h4 className=\"text-xs font-medium text-[var(--muted)]\" style={{ margin: \"0 0 8px\", textTransform: \"uppercase\", letterSpacing: \"0.5px\" }}>Text-to-Speech</h4>\n\t\t\t\t\t\t<div style={{ display: \"flex\", flexDirection: \"column\", gap: \"6px\" }}>\n\t\t\t\t\t\t\t{ttsProviders.map((p) => (\n\t\t\t\t\t\t\t\t<button key={p.id} className=\"provider-card\" style={{ padding: \"10px 12px\", borderRadius: \"6px\", cursor: \"pointer\", textAlign: \"left\", border: \"1px solid var(--border)\", background: \"var(--surface)\" }}\n\t\t\t\t\t\t\t\t\tonClick={() => onSelectProvider(p.id)}>\n\t\t\t\t\t\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\" }}>\n\t\t\t\t\t\t\t\t\t\t<div style={{ flex: 1 }}>\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"text-sm text-[var(--text-strong)]\">{p.name}</div>\n\t\t\t\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">{p.description}</div>\n\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t<span className=\"icon icon-chevron-right\" style={{ color: \"var(--muted)\" }} />\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t))}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\n\t\t\t\t{unconfiguredProviders.length === 0\n\t\t\t\t\t? <div className=\"text-sm text-[var(--muted)]\" style={{ textAlign: \"center\", padding: \"20px 0\" }}>\n\t\t\t\t\t\tAll available providers are already configured.\n\t\t\t\t\t</div>\n\t\t\t\t\t: null\n\t\t\t\t}\n\t\t\t</div>\n\t\t</Modal>\n\t);\n}\n\n// ── Memory section ────────────────────────────────────────────\n\ninterface MemoryStatus {\n\ttotal_files?: number;\n\ttotal_chunks?: number;\n\tembedding_model?: string;\n\tdb_size_display?: string;\n}\n\ninterface MemoryConfig {\n\tstyle?: string;\n\tagent_write_mode?: string;\n\tuser_profile_write_mode?: string;\n\tbackend?: string;\n\tprovider?: string;\n\tcitations?: string;\n\tllm_reranking?: boolean;\n\tsearch_merge_strategy?: string;\n\tsession_export?: string;\n\tprompt_memory_mode?: string;\n\tqmd_feature_enabled?: boolean;\n}\n\ninterface QmdStatus {\n\tavailable?: boolean;\n\tversion?: string;\n}\n\n// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Large component managing memory settings with QMD integration\nfunction MemorySection(): VNode {\n\tconst [memStatus, setMemStatus] = useState<MemoryStatus | null>(null);\n\tconst [memConfig, setMemConfig] = useState<MemoryConfig | null>(null);\n\tconst [qmdStatus, setQmdStatus] = useState<QmdStatus | null>(null);\n\tconst [memLoading, setMemLoading] = useState(true);\n\tconst [saving, setSaving] = useState(false);\n\tconst [saved, setSaved] = useState(false);\n\tconst [error, setError] = useState<string | null>(null);\n\n\t// Form state\n\tconst [style, setStyle] = useState(\"hybrid\");\n\tconst [agentWriteMode, setAgentWriteMode] = useState(\"hybrid\");\n\tconst [userProfileWriteMode, setUserProfileWriteMode] = useState(\"explicit-and-auto\");\n\tconst [backend, setBackend] = useState(\"builtin\");\n\tconst [provider, setProvider] = useState(\"auto\");\n\tconst [citations, setCitations] = useState(\"auto\");\n\tconst [llmReranking, setLlmReranking] = useState(false);\n\tconst [searchMergeStrategy, setSearchMergeStrategy] = useState(\"rrf\");\n\tconst [sessionExport, setSessionExport] = useState(\"on-new-or-reset\");\n\tconst [promptMemoryMode, setPromptMemoryMode] = useState(\"live-reload\");\n\n\tuseEffect(() => {\n\t\t// Fetch memory status, config, and QMD status\n\t\tPromise.all([sendRpc(\"memory.status\", {}), sendRpc(\"memory.config.get\", {}), sendRpc(\"memory.qmd.status\", {})])\n\t\t\t.then(([statusRes, configRes, qmdRes]: [RpcResponse, RpcResponse, RpcResponse]) => {\n\t\t\t\tif (statusRes?.ok) {\n\t\t\t\t\tsetMemStatus(statusRes.payload as MemoryStatus);\n\t\t\t\t}\n\t\t\t\tif (configRes?.ok) {\n\t\t\t\t\tconst cfg = configRes.payload as MemoryConfig;\n\t\t\t\t\tsetMemConfig(cfg);\n\t\t\t\t\tsetStyle(cfg.style || \"hybrid\");\n\t\t\t\t\tsetAgentWriteMode(cfg.agent_write_mode || \"hybrid\");\n\t\t\t\t\tsetUserProfileWriteMode(cfg.user_profile_write_mode || \"explicit-and-auto\");\n\t\t\t\t\tsetBackend(cfg.backend || \"builtin\");\n\t\t\t\t\tsetProvider(cfg.provider || \"auto\");\n\t\t\t\t\tsetCitations(cfg.citations || \"auto\");\n\t\t\t\t\tsetLlmReranking(cfg.llm_reranking ?? false);\n\t\t\t\t\tsetSearchMergeStrategy(cfg.search_merge_strategy || \"rrf\");\n\t\t\t\t\tsetSessionExport(cfg.session_export || \"on-new-or-reset\");\n\t\t\t\t\tsetPromptMemoryMode(cfg.prompt_memory_mode || \"live-reload\");\n\t\t\t\t}\n\t\t\t\tif (qmdRes?.ok) {\n\t\t\t\t\tsetQmdStatus(qmdRes.payload as QmdStatus);\n\t\t\t\t}\n\t\t\t\tsetMemLoading(false);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch(() => {\n\t\t\t\tsetMemLoading(false);\n\t\t\t\trerender();\n\t\t\t});\n\t}, []);\n\n\tfunction onSave(e: Event): void {\n\t\te.preventDefault();\n\t\tsetError(null);\n\t\tsetSaving(true);\n\t\tsetSaved(false);\n\n\t\tsendRpc(\"memory.config.update\", {\n\t\t\tstyle,\n\t\t\tagent_write_mode: agentWriteMode,\n\t\t\tuser_profile_write_mode: userProfileWriteMode,\n\t\t\tbackend,\n\t\t\tprovider,\n\t\t\tcitations,\n\t\t\tllm_reranking: llmReranking,\n\t\t\tsearch_merge_strategy: searchMergeStrategy,\n\t\t\tsession_export: sessionExport,\n\t\t\tprompt_memory_mode: promptMemoryMode,\n\t\t}).then((res: RpcResponse) => {\n\t\t\tsetSaving(false);\n\t\t\tif (res?.ok) {\n\t\t\t\tsetMemConfig(res.payload as MemoryConfig);\n\t\t\t\tsetSaved(true);\n\t\t\t\tsetTimeout(() => {\n\t\t\t\t\tsetSaved(false);\n\t\t\t\t\trerender();\n\t\t\t\t}, 2000);\n\t\t\t} else {\n\t\t\t\tsetError((res?.error as { message?: string })?.message || \"Failed to save\");\n\t\t\t}\n\t\t\trerender();\n\t\t});\n\t}\n\n\tif (memLoading) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Memory</h2>\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Loading{\"\\u2026\"}</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\tconst qmdFeatureEnabled = memConfig?.qmd_feature_enabled !== false;\n\tconst qmdAvailable = qmdStatus?.available === true;\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Memory</h2>\n\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed max-w-form\" style={{ margin: 0 }}>\n\t\t\t\tConfigure how the agent stores and retrieves long-term memory. Memory enables the agent\n\t\t\t\tto recall past conversations, notes, and context across sessions.\n\t\t\t</p>\n\n\t\t\t{/* Status */}\n\t\t\t{memStatus\n\t\t\t\t? <div style={{ maxWidth: \"600px\", padding: \"12px 16px\", borderRadius: \"6px\", border: \"1px solid var(--border)\", background: \"var(--bg)\" }}>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>Status</h3>\n\t\t\t\t\t<div style={{ display: \"grid\", gridTemplateColumns: \"repeat(2,1fr)\", gap: \"8px 16px\", fontSize: \".8rem\" }}>\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<span className=\"text-[var(--muted)]\">Files:</span>\n\t\t\t\t\t\t\t<span className=\"text-[var(--text)]\" style={{ marginLeft: \"6px\" }}>{memStatus.total_files || 0}</span>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<span className=\"text-[var(--muted)]\">Chunks:</span>\n\t\t\t\t\t\t\t<span className=\"text-[var(--text)]\" style={{ marginLeft: \"6px\" }}>{memStatus.total_chunks || 0}</span>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<span className=\"text-[var(--muted)]\">Model:</span>\n\t\t\t\t\t\t\t<span className=\"text-[var(--text)]\" style={{ marginLeft: \"6px\", fontFamily: \"var(--font-mono)\", fontSize: \".75rem\" }}>{memStatus.embedding_model || \"none\"}</span>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<span className=\"text-[var(--muted)]\">DB Size:</span>\n\t\t\t\t\t\t\t<span className=\"text-[var(--text)]\" style={{ marginLeft: \"6px\" }}>{memStatus.db_size_display || \"0 B\"}</span>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t: null\n\t\t\t}\n\n\t\t\t{/* Configuration */}\n\t\t\t<form onSubmit={onSave} style={{ maxWidth: \"600px\", display: \"flex\", flexDirection: \"column\", gap: \"16px\" }}>\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>Memory Style</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>\n\t\t\t\t\t\tChoose the high-level orchestration model. This controls whether prompt-visible <code>MEMORY.md</code> and memory tools are both active, one is active, or both are off.\n\t\t\t\t\t</p>\n\t\t\t\t\t<select className=\"provider-key-input\" style={{ width: \"auto\", minWidth: \"240px\" }}\n\t\t\t\t\t\tvalue={style} onChange={(e: Event) => {\n\t\t\t\t\t\t\tsetStyle((e.target as HTMLSelectElement).value);\n\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t}}>\n\t\t\t\t\t\t<option value=\"hybrid\">Hybrid</option>\n\t\t\t\t\t\t<option value=\"prompt-only\">Prompt-only</option>\n\t\t\t\t\t\t<option value=\"search-only\">Search-only</option>\n\t\t\t\t\t\t<option value=\"off\">Off</option>\n\t\t\t\t\t</select>\n\t\t\t\t</div>\n\n\t\t\t\t{/* Backend selection */}\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>Backend</h3>\n\n\t\t\t\t\t{/* Comparison table */}\n\t\t\t\t\t<div style={{ marginBottom: \"12px\", padding: \"12px\", borderRadius: \"6px\", border: \"1px solid var(--border)\", background: \"var(--bg)\", fontSize: \".75rem\" }}>\n\t\t\t\t\t\t<table style={{ width: \"100%\", borderCollapse: \"collapse\" }}>\n\t\t\t\t\t\t\t<thead>\n\t\t\t\t\t\t\t\t<tr style={{ borderBottom: \"1px solid var(--border)\" }}>\n\t\t\t\t\t\t\t\t\t<th style={{ textAlign: \"left\", padding: \"4px 8px 8px 0\", color: \"var(--muted)\", fontWeight: 500 }}>Feature</th>\n\t\t\t\t\t\t\t\t\t<th style={{ textAlign: \"center\", padding: \"4px 8px 8px\", color: \"var(--muted)\", fontWeight: 500 }}>Built-in</th>\n\t\t\t\t\t\t\t\t\t<th style={{ textAlign: \"center\", padding: \"4px 8px 8px\", color: \"var(--muted)\", fontWeight: 500 }}>QMD</th>\n\t\t\t\t\t\t\t\t</tr>\n\t\t\t\t\t\t\t</thead>\n\t\t\t\t\t\t\t<tbody>\n\t\t\t\t\t\t\t\t<tr>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px 6px 0\", color: \"var(--text)\" }}>Search type</td>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px\", textAlign: \"center\", color: \"var(--muted)\" }}>FTS5 + vector</td>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px\", textAlign: \"center\", color: \"var(--muted)\" }}>BM25 + vector + LLM</td>\n\t\t\t\t\t\t\t\t</tr>\n\t\t\t\t\t\t\t\t<tr>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px 6px 0\", color: \"var(--text)\" }}>External dependency</td>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px\", textAlign: \"center\", color: \"var(--accent)\" }}>None</td>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px\", textAlign: \"center\", color: \"var(--muted)\" }}>Node.js/Bun</td>\n\t\t\t\t\t\t\t\t</tr>\n\t\t\t\t\t\t\t\t<tr>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px 6px 0\", color: \"var(--text)\" }}>Embedding cache</td>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px\", textAlign: \"center\", color: \"var(--accent)\" }}>{\"\\u2713\"}</td>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px\", textAlign: \"center\", color: \"var(--muted)\" }}>{\"\\u2717\"}</td>\n\t\t\t\t\t\t\t\t</tr>\n\t\t\t\t\t\t\t\t<tr>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px 6px 0\", color: \"var(--text)\" }}>OpenAI batch API</td>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px\", textAlign: \"center\", color: \"var(--accent)\" }}>{\"\\u2713\"} (50% cheaper)</td>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px\", textAlign: \"center\", color: \"var(--muted)\" }}>{\"\\u2717\"}</td>\n\t\t\t\t\t\t\t\t</tr>\n\t\t\t\t\t\t\t\t<tr>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px 6px 0\", color: \"var(--text)\" }}>Provider fallback</td>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px\", textAlign: \"center\", color: \"var(--accent)\" }}>{\"\\u2713\"}</td>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px\", textAlign: \"center\", color: \"var(--muted)\" }}>{\"\\u2717\"}</td>\n\t\t\t\t\t\t\t\t</tr>\n\t\t\t\t\t\t\t\t<tr>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px 6px 0\", color: \"var(--text)\" }}>LLM reranking</td>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px\", textAlign: \"center\", color: \"var(--muted)\" }}>Optional</td>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px\", textAlign: \"center\", color: \"var(--accent)\" }}>Built-in</td>\n\t\t\t\t\t\t\t\t</tr>\n\t\t\t\t\t\t\t\t<tr>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px 6px 0\", color: \"var(--text)\" }}>Best for</td>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px\", textAlign: \"center\", color: \"var(--muted)\" }}>Most users</td>\n\t\t\t\t\t\t\t\t\t<td style={{ padding: \"6px 8px\", textAlign: \"center\", color: \"var(--muted)\" }}>Power users</td>\n\t\t\t\t\t\t\t\t</tr>\n\t\t\t\t\t\t\t</tbody>\n\t\t\t\t\t\t</table>\n\t\t\t\t\t</div>\n\n\t\t\t\t\t<div style={{ display: \"flex\", gap: \"8px\" }}>\n\t\t\t\t\t\t<button type=\"button\"\n\t\t\t\t\t\t\tclassName={`provider-btn ${backend === \"builtin\" ? \"\" : \"provider-btn-secondary\"}`}\n\t\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\t\tsetBackend(\"builtin\");\n\t\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t\t}}>\n\t\t\t\t\t\t\tBuilt-in (Recommended)\n\t\t\t\t\t\t</button>\n\t\t\t\t\t\t<button type=\"button\"\n\t\t\t\t\t\t\tclassName={`provider-btn ${backend === \"qmd\" ? \"\" : \"provider-btn-secondary\"}`}\n\t\t\t\t\t\t\tdisabled={!qmdFeatureEnabled}\n\t\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\t\tsetBackend(\"qmd\");\n\t\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t\t}}>\n\t\t\t\t\t\t\tQMD\n\t\t\t\t\t\t</button>\n\t\t\t\t\t</div>\n\n\t\t\t\t\t{qmdFeatureEnabled\n\t\t\t\t\t\t? null\n\t\t\t\t\t\t: <div className=\"text-xs text-[var(--error)]\" style={{ marginTop: \"8px\" }}>\n\t\t\t\t\t\t\tQMD feature is not enabled. Rebuild moltis with <code style={{ fontFamily: \"var(--font-mono)\", fontSize: \".7rem\" }}>--features qmd</code>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t}\n\n\t\t\t\t\t{backend === \"qmd\"\n\t\t\t\t\t\t? <div style={{ marginTop: \"12px\", padding: \"12px\", borderRadius: \"6px\", border: \"1px solid var(--border)\", background: \"var(--bg)\" }}>\n\t\t\t\t\t\t\t<h4 className=\"text-xs font-medium text-[var(--text-strong)]\" style={{ margin: \"0 0 8px\" }}>QMD Status</h4>\n\t\t\t\t\t\t\t{qmdAvailable\n\t\t\t\t\t\t\t\t? <div className=\"text-xs\" style={{ color: \"var(--accent)\", display: \"flex\", alignItems: \"center\", gap: \"6px\" }}>\n\t\t\t\t\t\t\t\t\t<span>{\"\\u2713\"}</span> QMD is installed {qmdStatus?.version ? <span className=\"text-[var(--muted)]\">({qmdStatus.version})</span> : null}\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t: <div>\n\t\t\t\t\t\t\t\t\t<div className=\"text-xs\" style={{ color: \"var(--error)\", marginBottom: \"8px\" }}>\n\t\t\t\t\t\t\t\t\t\t{\"\\u2717\"} QMD is not installed or not found in PATH\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ lineHeight: 1.6 }}>\n\t\t\t\t\t\t\t\t\t\t<strong style={{ color: \"var(--text)\" }}>Installation:</strong><br/>\n\t\t\t\t\t\t\t\t\t\t<code style={{ fontFamily: \"var(--font-mono)\", fontSize: \".7rem\", background: \"var(--surface)\", padding: \"2px 4px\", borderRadius: \"3px\" }}>npm install -g @tobilu/qmd</code>\n\t\t\t\t\t\t\t\t\t\t<span style={{ margin: \"0 4px\" }}>or</span>\n\t\t\t\t\t\t\t\t\t\t<code style={{ fontFamily: \"var(--font-mono)\", fontSize: \".7rem\", background: \"var(--surface)\", padding: \"2px 4px\", borderRadius: \"3px\" }}>bun install -g @tobilu/qmd</code>\n\t\t\t\t\t\t\t\t\t\t<br/><br/>\n\t\t\t\t\t\t\t\t\t\tVerify the CLI is available:\n\t\t\t\t\t\t\t\t\t\t<code style={{ display: \"block\", marginTop: \"4px\", fontFamily: \"var(--font-mono)\", fontSize: \".7rem\", background: \"var(--surface)\", padding: \"2px 4px\", borderRadius: \"3px\" }}>qmd --version</code>\n\t\t\t\t\t\t\t\t\t\t<br/>\n\t\t\t\t\t\t\t\t\t\t<a href=\"https://github.com/tobi/qmd\" target=\"_blank\" rel=\"noopener\"\n\t\t\t\t\t\t\t\t\t\t\tstyle={{ color: \"var(--accent)\" }}>View documentation {\"\\u2192\"}</a>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t: null\n\t\t\t\t\t}\n\t\t\t\t</div>\n\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>Prompt Memory Mode</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>\n\t\t\t\t\t\tWhen prompt memory is enabled, choose whether <code>MEMORY.md</code> is reread on every turn or frozen when the session starts.\n\t\t\t\t\t</p>\n\t\t\t\t\t<select className=\"provider-key-input\" style={{ width: \"auto\", minWidth: \"260px\" }}\n\t\t\t\t\t\tvalue={promptMemoryMode}\n\t\t\t\t\t\tdisabled={style === \"search-only\" || style === \"off\"}\n\t\t\t\t\t\tonChange={(e: Event) => {\n\t\t\t\t\t\t\tsetPromptMemoryMode((e.target as HTMLSelectElement).value);\n\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t}}>\n\t\t\t\t\t\t<option value=\"live-reload\">Live reload</option>\n\t\t\t\t\t\t<option value=\"frozen-at-session-start\">Frozen at session start</option>\n\t\t\t\t\t</select>\n\t\t\t\t\t{style === \"search-only\" || style === \"off\"\n\t\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\" style={{ marginTop: \"8px\" }}>\n\t\t\t\t\t\t\tPrompt memory is disabled by the current memory style, so this setting will only matter after you re-enable prompt memory.\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t: null\n\t\t\t\t\t}\n\t\t\t\t</div>\n\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>Agent Memory Writes</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>\n\t\t\t\t\t\tControl where agent-authored memory writes can land. This affects <code>memory_save</code> and silent compaction memory flushes.\n\t\t\t\t\t</p>\n\t\t\t\t\t<select className=\"provider-key-input\" style={{ width: \"auto\", minWidth: \"220px\" }}\n\t\t\t\t\t\tvalue={agentWriteMode} onChange={(e: Event) => {\n\t\t\t\t\t\t\tsetAgentWriteMode((e.target as HTMLSelectElement).value);\n\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t}}>\n\t\t\t\t\t\t<option value=\"hybrid\">Hybrid (MEMORY.md and memory/*.md)</option>\n\t\t\t\t\t\t<option value=\"prompt-only\">Prompt-only (MEMORY.md only)</option>\n\t\t\t\t\t\t<option value=\"search-only\">Search-only (memory/*.md only)</option>\n\t\t\t\t\t\t<option value=\"off\">Off</option>\n\t\t\t\t\t</select>\n\t\t\t\t</div>\n\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>USER.md Writes</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>\n\t\t\t\t\t\tControl whether Moltis mirrors your profile into <code>USER.md</code>, and whether browser or channel timezone/location signals can update it silently.\n\t\t\t\t\t</p>\n\t\t\t\t\t<select className=\"provider-key-input\" style={{ width: \"auto\", minWidth: \"250px\" }}\n\t\t\t\t\t\tvalue={userProfileWriteMode} onChange={(e: Event) => {\n\t\t\t\t\t\t\tsetUserProfileWriteMode((e.target as HTMLSelectElement).value);\n\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t}}>\n\t\t\t\t\t\t<option value=\"explicit-and-auto\">Explicit and auto</option>\n\t\t\t\t\t\t<option value=\"explicit-only\">Explicit only</option>\n\t\t\t\t\t\t<option value=\"off\">Off (moltis.toml only)</option>\n\t\t\t\t\t</select>\n\t\t\t\t</div>\n\n\t\t\t\t{/* Citations */}\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>Embedding Provider</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>\n\t\t\t\t\t\tSelect which embedding provider the built-in memory backend should use for RAG. QMD manages retrieval separately, so this setting is ignored while the QMD backend is active.\n\t\t\t\t\t</p>\n\t\t\t\t\t<select className=\"provider-key-input\" style={{ width: \"auto\", minWidth: \"220px\" }}\n\t\t\t\t\t\tvalue={provider}\n\t\t\t\t\t\tdisabled={backend === \"qmd\"}\n\t\t\t\t\t\tonChange={(e: Event) => {\n\t\t\t\t\t\t\tsetProvider((e.target as HTMLSelectElement).value);\n\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t}}>\n\t\t\t\t\t\t<option value=\"auto\">Auto-detect</option>\n\t\t\t\t\t\t<option value=\"local\">Local GGUF</option>\n\t\t\t\t\t\t<option value=\"ollama\">Ollama</option>\n\t\t\t\t\t\t<option value=\"openai\">OpenAI</option>\n\t\t\t\t\t\t<option value=\"custom\">Custom OpenAI-compatible</option>\n\t\t\t\t\t</select>\n\t\t\t\t\t{backend === \"qmd\"\n\t\t\t\t\t\t? <div className=\"text-xs text-[var(--muted)]\" style={{ marginTop: \"8px\" }}>\n\t\t\t\t\t\t\tThis setting is kept for when you switch back to the built-in backend.\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t: null\n\t\t\t\t\t}\n\t\t\t\t</div>\n\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>Citations</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>\n\t\t\t\t\t\tInclude source file and line number with search results to help track where information comes from.\n\t\t\t\t\t</p>\n\t\t\t\t\t<select className=\"provider-key-input\" style={{ width: \"auto\", minWidth: \"150px\" }}\n\t\t\t\t\t\tvalue={citations} onChange={(e: Event) => {\n\t\t\t\t\t\t\tsetCitations((e.target as HTMLSelectElement).value);\n\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t}}>\n\t\t\t\t\t\t<option value=\"auto\">Auto (multi-file only)</option>\n\t\t\t\t\t\t<option value=\"on\">Always</option>\n\t\t\t\t\t\t<option value=\"off\">Never</option>\n\t\t\t\t\t</select>\n\t\t\t\t</div>\n\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>Search Merge Strategy</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>\n\t\t\t\t\t\tChoose how Moltis blends vector and keyword memory hits before optional reranking.\n\t\t\t\t\t</p>\n\t\t\t\t\t<select className=\"provider-key-input\" style={{ width: \"auto\", minWidth: \"180px\" }}\n\t\t\t\t\t\tvalue={searchMergeStrategy} onChange={(e: Event) => {\n\t\t\t\t\t\t\tsetSearchMergeStrategy((e.target as HTMLSelectElement).value);\n\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t}}>\n\t\t\t\t\t\t<option value=\"rrf\">RRF</option>\n\t\t\t\t\t\t<option value=\"linear\">Linear</option>\n\t\t\t\t\t</select>\n\t\t\t\t</div>\n\n\t\t\t\t{/* LLM Reranking */}\n\t\t\t\t<div>\n\t\t\t\t\t<label style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\", cursor: \"pointer\" }}>\n\t\t\t\t\t\t<input type=\"checkbox\" checked={llmReranking}\n\t\t\t\t\t\t\tonChange={(e: Event) => {\n\t\t\t\t\t\t\t\tsetLlmReranking((e.target as HTMLInputElement).checked);\n\t\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t\t}} />\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<span className=\"text-sm font-medium text-[var(--text-strong)]\">LLM Reranking</span>\n\t\t\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"2px 0 0\" }}>\n\t\t\t\t\t\t\t\tUse the LLM to rerank search results for better relevance (slower but more accurate).\n\t\t\t\t\t\t\t</p>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</label>\n\t\t\t\t</div>\n\n\t\t\t\t{/* Session Export */}\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>Session Export</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>\n\t\t\t\t\t\tExport session transcripts into searchable memory when a session is rolled over.\n\t\t\t\t\t</p>\n\t\t\t\t\t<select className=\"provider-key-input\" style={{ width: \"auto\", minWidth: \"220px\" }}\n\t\t\t\t\t\tvalue={sessionExport} onChange={(e: Event) => {\n\t\t\t\t\t\t\tsetSessionExport((e.target as HTMLSelectElement).value);\n\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t}}>\n\t\t\t\t\t\t<option value=\"on-new-or-reset\">On /new and /reset</option>\n\t\t\t\t\t\t<option value=\"off\">Off</option>\n\t\t\t\t\t</select>\n\t\t\t\t</div>\n\n\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\", paddingTop: \"8px\", borderTop: \"1px solid var(--border)\" }}>\n\t\t\t\t\t<button type=\"submit\" className=\"provider-btn\" disabled={saving}>\n\t\t\t\t\t\t{saving ? \"Saving\\u2026\" : \"Save\"}\n\t\t\t\t\t</button>\n\t\t\t\t\t{saved ? <span className=\"text-xs\" style={{ color: \"var(--accent)\" }}>Saved</span> : null}\n\t\t\t\t\t{error ? <span className=\"text-xs\" style={{ color: \"var(--error)\" }}>{error}</span> : null}\n\t\t\t\t</div>\n\t\t\t</form>\n\t\t</div>\n\t);\n}\n\n// ── Notifications section ─────────────────────────────────────\n\ninterface PushSubscription {\n\tendpoint: string;\n\tdevice?: string;\n\tip?: string;\n\tcreated_at?: string;\n}\n\ninterface PushServerStatus {\n\tsubscription_count?: number;\n\tsubscriptions?: PushSubscription[];\n}\n\n// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Notifications section handles multiple states and conditions\nfunction NotificationsSection(): VNode {\n\tconst [supported, setSupported] = useState(false);\n\tconst [permission, setPermission] = useState(\"default\");\n\tconst [subscribed, setSubscribed] = useState(false);\n\tconst [isLoading, setIsLoading] = useState(true);\n\tconst [toggling, setToggling] = useState(false);\n\tconst [error, setError] = useState<string | null>(null);\n\tconst [serverStatus, setServerStatus] = useState<PushServerStatus | null>(null);\n\n\tasync function checkStatus(): Promise<void> {\n\t\tsetIsLoading(true);\n\t\trerender();\n\n\t\tconst pushSupported = push.isPushSupported();\n\t\tsetSupported(pushSupported);\n\n\t\tif (pushSupported) {\n\t\t\tsetPermission(push.getPermissionState());\n\t\t\tawait push.initPushState();\n\t\t\tsetSubscribed(push.isSubscribed());\n\n\t\t\t// Check server status\n\t\t\tconst status = await push.getPushStatus();\n\t\t\tsetServerStatus(status as PushServerStatus);\n\t\t}\n\n\t\tsetIsLoading(false);\n\t\trerender();\n\t}\n\n\tasync function refreshStatus(): Promise<void> {\n\t\tconst status = await push.getPushStatus();\n\t\tsetServerStatus(status as PushServerStatus);\n\t\trerender();\n\t}\n\n\tasync function onRemoveSubscription(endpoint: string): Promise<void> {\n\t\tconst result = await push.removeSubscription(endpoint);\n\t\tif (!result.success) {\n\t\t\tsetError(result.error || \"Failed to remove subscription\");\n\t\t\trerender();\n\t\t}\n\t\t// The WebSocket event will trigger refreshStatus automatically\n\t}\n\n\tuseEffect(() => {\n\t\tcheckStatus();\n\t\t// Listen for subscription changes via WebSocket\n\t\tconst off = onEvent(\"push.subscriptions\", () => {\n\t\t\trefreshStatus();\n\t\t});\n\t\treturn off;\n\t}, []);\n\n\tasync function onToggle(): Promise<void> {\n\t\tsetError(null);\n\t\tsetToggling(true);\n\t\trerender();\n\n\t\tconst result = subscribed ? await push.unsubscribeFromPush() : await push.subscribeToPush();\n\n\t\tif (result.success) {\n\t\t\tsetSubscribed(!subscribed);\n\t\t\tif (!subscribed) setPermission(\"granted\");\n\t\t} else {\n\t\t\tsetError(result.error || (subscribed ? \"Failed to unsubscribe\" : \"Failed to subscribe\"));\n\t\t}\n\n\t\tsetToggling(false);\n\t\trerender();\n\t}\n\n\tif (isLoading) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Notifications</h2>\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Loading{\"\\u2026\"}</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\tif (!supported) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Notifications</h2>\n\t\t\t\t<div style={{ maxWidth: \"600px\", padding: \"12px 16px\", borderRadius: \"6px\", border: \"1px solid var(--border)\", background: \"var(--surface)\" }}>\n\t\t\t\t\t<p className=\"text-sm text-[var(--text)]\" style={{ margin: 0 }}>\n\t\t\t\t\t\tPush notifications are not supported in this browser.\n\t\t\t\t\t</p>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"8px 0 0\" }}>\n\t\t\t\t\t\tTry using Safari, Chrome, or Firefox on a device that supports web push.\n\t\t\t\t\t</p>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\tif (serverStatus === null) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Notifications</h2>\n\t\t\t\t<div style={{ maxWidth: \"600px\", padding: \"12px 16px\", borderRadius: \"6px\", border: \"1px solid var(--border)\", background: \"var(--surface)\" }}>\n\t\t\t\t\t<p className=\"text-sm text-[var(--text)]\" style={{ margin: 0 }}>\n\t\t\t\t\t\tPush notifications are not configured on the server.\n\t\t\t\t\t</p>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"8px 0 0\" }}>\n\t\t\t\t\t\tThe server was built without the <code style={{ fontFamily: \"var(--font-mono)\", fontSize: \".75rem\" }}>push-notifications</code> feature.\n\t\t\t\t\t</p>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\t// Check if running as installed PWA - push notifications require installation on Safari\n\tconst standalone = isStandalone();\n\tconst needsInstall = !standalone && /Safari/.test(navigator.userAgent) && !/Chrome/.test(navigator.userAgent);\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Notifications</h2>\n\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed\" style={{ maxWidth: \"600px\", margin: 0 }}>\n\t\t\t\tReceive push notifications when the agent completes a task or needs your attention.\n\t\t\t</p>\n\n\t\t\t{/* Push notifications toggle */}\n\t\t\t<div style={{ maxWidth: \"600px\" }}>\n\t\t\t\t<div className=\"provider-item\" style={{ marginBottom: 0 }}>\n\t\t\t\t\t<div style={{ flex: 1, minWidth: 0 }}>\n\t\t\t\t\t\t<div className=\"provider-item-name\" style={{ fontSize: \".9rem\" }}>Push Notifications</div>\n\t\t\t\t\t\t<div style={{ fontSize: \".75rem\", color: \"var(--muted)\", marginTop: \"2px\" }}>\n\t\t\t\t\t\t\t{needsInstall\n\t\t\t\t\t\t\t\t? \"Add this app to your Dock to enable notifications.\"\n\t\t\t\t\t\t\t\t: subscribed\n\t\t\t\t\t\t\t\t\t? \"You will receive notifications on this device.\"\n\t\t\t\t\t\t\t\t\t: permission === \"denied\"\n\t\t\t\t\t\t\t\t\t\t? \"Notifications are blocked. Enable them in browser settings.\"\n\t\t\t\t\t\t\t\t\t\t: \"Enable to receive notifications on this device.\"\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName={`provider-btn ${subscribed ? \"provider-btn-danger\" : \"\"}`}\n\t\t\t\t\t\tonClick={onToggle}\n\t\t\t\t\t\tdisabled={toggling || permission === \"denied\" || needsInstall}\n\t\t\t\t\t>\n\t\t\t\t\t\t{toggling ? \"\\u2026\" : subscribed ? \"Disable\" : \"Enable\"}\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t\t{error ? <div className=\"text-xs\" style={{ marginTop: \"8px\", color: \"var(--error)\" }}>{error}</div> : null}\n\t\t\t</div>\n\n\t\t\t{/* Install required notice */}\n\t\t\t{needsInstall\n\t\t\t\t? <div style={{ maxWidth: \"600px\", padding: \"12px 16px\", borderRadius: \"6px\", border: \"1px solid var(--border)\", background: \"var(--surface)\" }}>\n\t\t\t\t\t<p className=\"text-sm text-[var(--text)]\" style={{ margin: 0, fontWeight: 500 }}>\n\t\t\t\t\t\tInstallation required\n\t\t\t\t\t</p>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"8px 0 0\" }}>\n\t\t\t\t\t\tOn Safari, push notifications are only available for installed apps. Add moltis to your Dock using <strong>File {\"\\u2192\"} Add to Dock</strong> (or Share {\"\\u2192\"} Add to Dock on iOS), then open it from there.\n\t\t\t\t\t</p>\n\t\t\t\t</div>\n\t\t\t\t: null\n\t\t\t}\n\n\t\t\t{/* Permission status */}\n\t\t\t{permission === \"denied\" && !needsInstall\n\t\t\t\t? <div style={{ maxWidth: \"600px\", padding: \"12px 16px\", borderRadius: \"6px\", border: \"1px solid var(--error)\", background: \"color-mix(in srgb, var(--error) 5%, transparent)\" }}>\n\t\t\t\t\t<p className=\"text-sm\" style={{ color: \"var(--error)\", margin: 0, fontWeight: 500 }}>\n\t\t\t\t\t\tNotifications are blocked\n\t\t\t\t\t</p>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"8px 0 0\" }}>\n\t\t\t\t\t\tYou previously blocked notifications for this site. To enable them, you'll need to update your browser's site settings and allow notifications for this origin.\n\t\t\t\t\t</p>\n\t\t\t\t</div>\n\t\t\t\t: null\n\t\t\t}\n\n\t\t\t{/* Subscribed devices */}\n\t\t\t<div style={{ maxWidth: \"600px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\", marginTop: \"8px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\t\tSubscribed Devices ({serverStatus?.subscription_count || 0})\n\t\t\t\t</h3>\n\t\t\t\t{(serverStatus?.subscriptions?.length || 0) > 0\n\t\t\t\t\t? <div style={{ display: \"flex\", flexDirection: \"column\", gap: \"6px\" }}>\n\t\t\t\t\t\t{serverStatus?.subscriptions?.map((sub) => (\n\t\t\t\t\t\t\t<div className=\"provider-item\" style={{ marginBottom: 0 }} key={sub.endpoint}>\n\t\t\t\t\t\t\t\t<div style={{ flex: 1, minWidth: 0 }}>\n\t\t\t\t\t\t\t\t\t<div className=\"provider-item-name\" style={{ fontSize: \".85rem\" }}>{sub.device}</div>\n\t\t\t\t\t\t\t\t\t<div style={{ fontSize: \".7rem\", color: \"var(--muted)\", marginTop: \"2px\", display: \"flex\", gap: \"12px\", flexWrap: \"wrap\" }}>\n\t\t\t\t\t\t\t\t\t\t{sub.ip ? <span style={{ fontFamily: \"var(--font-mono)\" }}>{sub.ip}</span> : null}\n\t\t\t\t\t\t\t\t\t\t<time dateTime={sub.created_at}>{new Date(sub.created_at || \"\").toLocaleDateString()}</time>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-danger\"\n\t\t\t\t\t\t\t\t\tonClick={() => onRemoveSubscription(sub.endpoint)}\n\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\tRemove\n\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t))}\n\t\t\t\t\t</div>\n\t\t\t\t\t: <div className=\"text-xs text-[var(--muted)]\" style={{ padding: \"4px 0\" }}>No devices subscribed yet.</div>\n\t\t\t\t}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// ── Page-section init/teardown map ──────────────────────────\n\ninterface PageSectionHandler {\n\tinit: (container: HTMLElement, subPath?: string | null) => void;\n\tteardown: () => void;\n}\n\nconst pageSectionHandlers: Record<string, PageSectionHandler> = {\n\tcrons: {\n\t\tinit: (container: HTMLElement) => initCrons(container, null),\n\t\tteardown: teardownCrons,\n\t},\n\theartbeat: {\n\t\tinit: (container: HTMLElement) => initCrons(container, \"heartbeat\"),\n\t\tteardown: teardownCrons,\n\t},\n\twebhooks: { init: initWebhooks, teardown: teardownWebhooks },\n\tproviders: { init: initProviders, teardown: teardownProviders },\n\tchannels: { init: initChannels, teardown: teardownChannels },\n\tmcp: { init: initMcp, teardown: teardownMcp },\n\tnodes: { init: initNodes, teardown: teardownNodes },\n\tprojects: { init: initProjects, teardown: teardownProjects },\n\thooks: { init: initHooks, teardown: teardownHooks },\n\tskills: { init: initSkills, teardown: teardownSkills },\n\tagents: { init: initAgents, teardown: teardownAgents },\n\tterminal: { init: initTerminal, teardown: teardownTerminal },\n\tsandboxes: { init: initImages, teardown: teardownImages },\n\tmonitoring: {\n\t\tinit: (container: HTMLElement) => initMonitoring(container, null, { syncPath: false }),\n\t\tteardown: teardownMonitoring,\n\t},\n\tlogs: { init: initLogs, teardown: teardownLogs },\n\t\"network-audit\": { init: initNetworkAudit, teardown: teardownNetworkAudit },\n};\n\n/** Wrapper that mounts a page init/teardown pair into a ref div. */\n\ninterface PageSectionProps {\n\tinitFn: (container: HTMLElement, subPath?: string) => void;\n\tteardownFn: (() => void) | null;\n\tsubPath?: string;\n}\n\nfunction PageSection({ initFn, teardownFn, subPath }: PageSectionProps): VNode {\n\tconst ref = useRef<HTMLDivElement>(null);\n\tuseEffect(() => {\n\t\tif (ref.current) initFn(ref.current, subPath);\n\t\treturn () => {\n\t\t\tif (teardownFn) teardownFn();\n\t\t};\n\t}, [initFn, teardownFn, subPath]);\n\treturn (\n\t\t<div\n\t\t\tref={ref}\n\t\t\tclassName=\"flex-1 flex flex-col min-w-0 overflow-hidden\"\n\t\t/>\n\t);\n}\n\n// ── Main layout ──────────────────────────────────────────────\n\nfunction SettingsPage(): VNode {\n\tuseEffect(() => {\n\t\tfetchIdentity();\n\t}, []);\n\n\tconst section = activeSection.value;\n\tconst subPath = activeSubPath.value;\n\tconst ps = pageSectionHandlers[section];\n\tconst mobile = isMobileViewport();\n\tconst showSidebar = !mobile || mobileSidebarVisible.value;\n\tconst showContent = !(mobile && showSidebar);\n\tconst mobileSectionsLabel = showSidebar ? \"Hide Sections\" : \"Sections\";\n\n\treturn (\n\t\t<div className={`settings-layout ${mobile && !showSidebar ? \"settings-layout-mobile-collapsed\" : \"\"}`}>\n\t\t\t{showSidebar ? <SettingsSidebar /> : null}\n\t\t\t{showContent\n\t\t\t\t? <div className=\"settings-content-wrap\">\n\t\t\t\t\t{mobile\n\t\t\t\t\t\t? <div className=\"settings-mobile-controls\">\n\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\tclassName=\"settings-mobile-chat-btn\"\n\t\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\t\tonClick={() => navigate(routes.chats!)}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t<span className=\"icon icon-chat\" />\n\t\t\t\t\t\t\t\t<span>Back to Chats</span>\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\tclassName=\"settings-mobile-menu-btn\"\n\t\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\t\t\tmobileSidebarVisible.value = !mobileSidebarVisible.value;\n\t\t\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t<span className=\"icon icon-burger\" />\n\t\t\t\t\t\t\t\t<span>{mobileSectionsLabel}</span>\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t: null\n\t\t\t\t\t}\n\t\t\t\t\t{ps\n\t\t\t\t\t\t? section === \"terminal\" && gon.get(\"terminal_enabled\") !== true\n\t\t\t\t\t\t\t? <div className=\"flex-1 flex flex-col min-w-0 p-4 gap-3 overflow-y-auto\">\n\t\t\t\t\t\t\t\t<h2 className=\"text-base font-medium text-[var(--text-strong)]\">Terminal</h2>\n\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] max-w-form\">\n\t\t\t\t\t\t\t\t\tThe host terminal has been disabled by the server administrator.\n\t\t\t\t\t\t\t\t\tTo re-enable it, set <code>terminal_enabled = true</code> under <code>[server]</code> in the configuration file,\n\t\t\t\t\t\t\t\t\tor remove the <code>MOLTIS_TERMINAL_DISABLED</code> environment variable if it is set.\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t: <PageSection key={`${section}:${subPath}`} initFn={ps.init} teardownFn={ps.teardown} subPath={subPath} />\n\t\t\t\t\t\t: null\n\t\t\t\t\t}\n\t\t\t\t\t{section === \"identity\" ? <IdentitySection /> : null}\n\t\t\t\t\t{section === \"memory\" ? <MemorySection /> : null}\n\t\t\t\t\t{section === \"environment\" ? <EnvironmentSection /> : null}\n\t\t\t\t\t{section === \"tools\" ? <ToolsSection /> : null}\n\t\t\t\t\t{section === \"security\" ? <SecuritySection /> : null}\n\t\t\t\t\t{section === \"vault\" ? <VaultSection /> : null}\n\t\t\t\t\t{section === \"ssh\" ? <SshSection /> : null}\n\t\t\t\t\t{section === \"remote-access\" ? <RemoteAccessSection /> : null}\n\t\t\t\t\t{section === \"voice\"\n\t\t\t\t\t\t? gon.get(\"voice_enabled\") === true\n\t\t\t\t\t\t\t? <VoiceSection />\n\t\t\t\t\t\t\t: <div className=\"flex-1 flex flex-col min-w-0 p-4 gap-3 overflow-y-auto\">\n\t\t\t\t\t\t\t\t<h2 className=\"text-base font-medium text-[var(--text-strong)]\">Voice</h2>\n\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] max-w-form\">\n\t\t\t\t\t\t\t\t\tVoice settings are unavailable in this build. Start a binary with the voice feature enabled to configure STT/TTS providers.\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t: null\n\t\t\t\t\t}\n\t\t\t\t\t{section === \"notifications\" ? <NotificationsSection /> : null}\n\t\t\t\t\t{section === \"import\" ? <OpenClawImportSection /> : null}\n\t\t\t\t\t{section === \"graphql\" ? <GraphqlSection /> : null}\n\t\t\t\t\t{section === \"config\" ? <ConfigSection /> : null}\n\t\t\t\t</div>\n\t\t\t\t: null\n\t\t\t}\n\t\t</div>\n\t);\n}\n\nconst DEFAULT_SECTION = \"identity\";\n\nregisterPrefix(\n\troutes.settings!,\n\t(container: HTMLElement, param?: string | null) => {\n\t\tmounted = true;\n\t\tcontainerRef = container;\n\t\tcontainer.style.cssText = \"flex-direction:row;padding:0;overflow:hidden;\";\n\t\tconst parts = (param || \"\").replace(/:/g, \"/\").split(\"/\").filter(Boolean);\n\t\tconst requestedSection = parts[0] || \"\";\n\t\tconst requestedSectionAlias = requestedSection === \"tailscale\" ? \"remote-access\" : requestedSection;\n\t\tconst subPath = parts.slice(1).join(\"/\");\n\t\tconst isValidSection = requestedSectionAlias && getSectionItems().some((s) => s.id === requestedSectionAlias);\n\t\tconst section = isValidSection ? requestedSectionAlias : DEFAULT_SECTION;\n\t\tactiveSection.value = section;\n\t\tactiveSubPath.value = isValidSection ? subPath : \"\";\n\t\tmobileSidebarVisible.value = !isMobileViewport();\n\t\tif (!isValidSection || requestedSectionAlias !== requestedSection) {\n\t\t\thistory.replaceState(null, \"\", settingsPath(section));\n\t\t}\n\t\trender(<SettingsPage />, container);\n\t\tfetchIdentity();\n\t},\n\t() => {\n\t\tmounted = false;\n\t\tif (containerRef) render(null, containerRef);\n\t\tcontainerRef = null;\n\t\tidentity.value = null;\n\t\tloading.value = true;\n\t\tactiveSection.value = DEFAULT_SECTION;\n\t\tactiveSubPath.value = \"\";\n\t\tmobileSidebarVisible.value = true;\n\t},\n);\n","// ── Session search ──────────────────────────────────────────\n\nimport { esc, sendRpc } from \"./helpers\";\nimport { currentPrefix, navigate, sessionPath } from \"./router\";\nimport { switchSession } from \"./sessions\";\nimport * as S from \"./state\";\nimport { sessionStore } from \"./stores/session-store\";\n\ninterface SearchHit {\n\tlabel?: string;\n\tsessionKey: string;\n\tsnippet: string;\n\trole: string;\n\tmessageIndex: number;\n}\n\ninterface SearchContext {\n\tquery: string;\n\tmessageIndex: number;\n}\n\nconst searchInput = S.$(\"sessionSearch\") as HTMLInputElement;\nconst searchResults = S.$(\"searchResults\") as HTMLElement;\nsearchResults.className = \"search-dropdown hidden\";\nlet searchTimer: ReturnType<typeof setTimeout> | null = null;\nlet searchHits: SearchHit[] = [];\nlet searchIdx = -1;\n\nfunction debounceSearch(): void {\n\tif (searchTimer !== null) clearTimeout(searchTimer);\n\tsearchTimer = setTimeout(doSearch, 300);\n}\n\nfunction doSearch(): void {\n\tconst q = searchInput.value.trim();\n\tif (!(q && S.connected)) {\n\t\thideSearch();\n\t\treturn;\n\t}\n\tsendRpc(\"sessions.search\", {\n\t\tquery: q,\n\t\tincludeArchived: sessionStore.showArchivedSessions.value,\n\t}).then((res) => {\n\t\tif (!res?.ok) {\n\t\t\thideSearch();\n\t\t\treturn;\n\t\t}\n\t\tsearchHits = (res.payload as SearchHit[] | undefined) || [];\n\t\tsearchIdx = -1;\n\t\trenderSearchResults(q);\n\t});\n}\n\nfunction hideSearch(): void {\n\tsearchResults.classList.add(\"hidden\");\n\tsearchHits = [];\n\tsearchIdx = -1;\n}\n\nfunction renderSearchResults(query: string): void {\n\tsearchResults.textContent = \"\";\n\tif (searchHits.length === 0) {\n\t\tconst empty = document.createElement(\"div\");\n\t\tempty.className = \"search-hit-empty\";\n\t\tempty.textContent = \"No results\";\n\t\tsearchResults.appendChild(empty);\n\t\tsearchResults.classList.remove(\"hidden\");\n\t\treturn;\n\t}\n\tsearchHits.forEach((hit, i) => {\n\t\tconst el = document.createElement(\"div\");\n\t\tel.className = \"search-hit\";\n\t\tel.setAttribute(\"data-idx\", String(i));\n\n\t\tconst lbl = document.createElement(\"div\");\n\t\tlbl.className = \"search-hit-label\";\n\t\tlbl.textContent = hit.label || hit.sessionKey;\n\t\tel.appendChild(lbl);\n\n\t\t// Safe: esc() escapes all HTML entities first, then we only wrap\n\t\t// the already-escaped query substring in <mark> tags.\n\t\tconst snip = document.createElement(\"div\");\n\t\tsnip.className = \"search-hit-snippet\";\n\t\tconst escaped = esc(hit.snippet);\n\t\tconst qEsc = esc(query);\n\t\tconst re = new RegExp(`(${qEsc.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\")})`, \"gi\");\n\t\t// Safe: both `escaped` and `qEsc` are HTML-entity-escaped by esc(),\n\t\t// so <mark> wrapping cannot introduce script injection.\n\t\t// This is a mechanical TypeScript conversion of existing safe code.\n\t\tconst highlighted = escaped.replace(re, \"<mark>$1</mark>\");\n\t\tsnip.insertAdjacentHTML(\"beforeend\", highlighted);\n\t\tel.appendChild(snip);\n\n\t\tconst role = document.createElement(\"div\");\n\t\trole.className = \"search-hit-role\";\n\t\trole.textContent = hit.role;\n\t\tel.appendChild(role);\n\n\t\tel.addEventListener(\"click\", () => {\n\t\t\tconst ctx: SearchContext = { query, messageIndex: hit.messageIndex };\n\t\t\tif (currentPrefix !== \"/chats\") {\n\t\t\t\tsessionStorage.setItem(\"moltis-search-ctx\", JSON.stringify(ctx));\n\t\t\t\tnavigate(sessionPath(hit.sessionKey));\n\t\t\t} else {\n\t\t\t\tswitchSession(hit.sessionKey, ctx);\n\t\t\t}\n\t\t\tsearchInput.value = \"\";\n\t\t\thideSearch();\n\t\t});\n\n\t\tsearchResults.appendChild(el);\n\t});\n\tsearchResults.classList.remove(\"hidden\");\n}\n\nfunction updateSearchActive(): void {\n\tconst items = searchResults.querySelectorAll<HTMLElement>(\".search-hit\");\n\titems.forEach((el, i) => {\n\t\tel.classList.toggle(\"active\", i === searchIdx);\n\t});\n\tif (searchIdx >= 0 && items[searchIdx]) {\n\t\titems[searchIdx].scrollIntoView({ block: \"nearest\" });\n\t}\n}\n\nsearchInput.addEventListener(\"input\", debounceSearch);\nsearchInput.addEventListener(\"keydown\", (e: KeyboardEvent) => {\n\tif (searchResults.classList.contains(\"hidden\")) return;\n\tif (e.key === \"ArrowDown\") {\n\t\te.preventDefault();\n\t\tsearchIdx = Math.min(searchIdx + 1, searchHits.length - 1);\n\t\tupdateSearchActive();\n\t} else if (e.key === \"ArrowUp\") {\n\t\te.preventDefault();\n\t\tsearchIdx = Math.max(searchIdx - 1, 0);\n\t\tupdateSearchActive();\n\t} else if (e.key === \"Enter\") {\n\t\te.preventDefault();\n\t\tif (searchIdx >= 0 && searchHits[searchIdx]) {\n\t\t\tconst h = searchHits[searchIdx];\n\t\t\tconst ctx: SearchContext = {\n\t\t\t\tquery: searchInput.value.trim(),\n\t\t\t\tmessageIndex: h.messageIndex,\n\t\t\t};\n\t\t\tif (currentPrefix !== \"/chats\") {\n\t\t\t\tsessionStorage.setItem(\"moltis-search-ctx\", JSON.stringify(ctx));\n\t\t\t\tnavigate(sessionPath(h.sessionKey));\n\t\t\t} else {\n\t\t\t\tswitchSession(h.sessionKey, ctx);\n\t\t\t}\n\t\t\tsearchInput.value = \"\";\n\t\t\thideSearch();\n\t\t}\n\t} else if (e.key === \"Escape\") {\n\t\tsearchInput.value = \"\";\n\t\thideSearch();\n\t}\n});\n\ndocument.addEventListener(\"click\", (e: MouseEvent) => {\n\tif (!(searchInput.contains(e.target as Node) || searchResults.contains(e.target as Node))) {\n\t\thideSearch();\n\t}\n});\n","// ── Entry point ────────────────────────────────────────────\n\nimport { render } from \"preact\";\nimport prettyBytes from \"pretty-bytes\";\nimport { applyIdentityFavicon, formatPageTitle } from \"./branding\";\nimport { initHighlighter } from \"./code-highlight\";\nimport { SessionList } from \"./components/SessionList\";\nimport { onEvent } from \"./events\";\nimport * as gon from \"./gon\";\nimport { init as initI18n, translateStaticElements } from \"./i18n\";\nimport { initMobile, toggleSessions } from \"./mobile\";\nimport { fetchModels } from \"./models\";\nimport { updateNavCounts } from \"./nav-counts\";\nimport { renderSessionProjectSelect } from \"./project-combo\";\nimport { fetchProjects, renderProjectSelect } from \"./projects\";\nimport { initPWA } from \"./pwa\";\nimport { initInstallBanner } from \"./pwa-install\";\nimport { mount, navigate, registerPage, sessionPath } from \"./router\";\nimport { routes } from \"./routes\";\nimport { updateSandboxImageUI, updateSandboxUI } from \"./sandbox\";\nimport {\n\tfetchSessions,\n\trefreshWelcomeCardIfNeeded,\n\tremoveSessionFromClientState,\n\trenderSessionList,\n} from \"./sessions\";\nimport * as S from \"./state\";\nimport * as modelStore from \"./stores/model-store\";\nimport * as projectStore from \"./stores/project-store\";\nimport { insertSessionInOrder, sessionStore } from \"./stores/session-store\";\nimport { initTheme, injectMarkdownStyles } from \"./theme\";\nimport { connect } from \"./websocket\";\n\n// Extend Window for E2E test access.\ndeclare global {\n\tinterface Window {\n\t\t__moltis_stores: {\n\t\t\tsessionStore: typeof sessionStore;\n\t\t\tmodelStore: typeof modelStore;\n\t\t\tprojectStore: typeof projectStore;\n\t\t};\n\t}\n}\n\n// Expose stores on window for E2E test access.\nwindow.__moltis_stores = { sessionStore, modelStore, projectStore };\n\n// Import page modules to register their routes\nimport \"./pages/ChatPage\";\nimport \"./pages/CronsPage\";\nimport \"./pages/ProjectsPage\";\nimport \"./pages/SkillsPage\";\nimport \"./pages/MetricsPage\";\nimport \"./pages/SettingsPage\"; // also imports channels, providers, mcp, hooks, images, logs\n\n// Import side-effect modules\nimport \"./nav-counts\";\nimport \"./session-search\";\nimport \"./time-format\";\n\n// ── Types ────────────────────────────────────────────────────\n\ninterface MemInfo {\n\tprocess: number;\n\tavailable: number;\n\ttotal: number;\n\tlocalLlamaCpp?: number;\n\tlocal_llama_cpp?: number;\n}\n\ninterface IdentityInfo {\n\temoji?: string;\n\tname?: string;\n\tuser_name?: string;\n\t[key: string]: unknown;\n}\n\ninterface AuthStatus {\n\tauthenticated?: boolean;\n\tauth_disabled?: boolean;\n\thas_password?: boolean;\n\thas_passkeys?: boolean;\n\tlocalhost_only?: boolean;\n\tsetup_required?: boolean;\n}\n\ninterface BootstrapData {\n\tchannels?: { channels?: unknown[] } | unknown[];\n\tsessions?: unknown[];\n\tmodels?: ModelEntry[];\n\tprojects?: ProjectEntry[];\n\tsandbox?: unknown;\n\tcounts?: Record<string, number>;\n}\n\ninterface ModelEntry {\n\tid: string;\n\t[key: string]: unknown;\n}\n\ninterface ProjectEntry {\n\tid: string;\n\t[key: string]: unknown;\n}\n\ninterface SessionEntry {\n\tkey: string;\n\t[key: string]: unknown;\n}\n\n// ── Helpers ──────────────────────────────────────────────────\n\nfunction preferredChatPath(): string {\n\tconst key = localStorage.getItem(\"moltis-session\") || \"main\";\n\treturn sessionPath(key);\n}\n\n// Redirect root to the active/default chat session.\nregisterPage(\"/\", () => {\n\tconst path = preferredChatPath();\n\tif (location.pathname !== path) {\n\t\thistory.replaceState(null, \"\", path);\n\t}\n\tmount(path);\n});\n\ninitTheme();\ninjectMarkdownStyles();\ninitHighlighter();\ninitPWA();\ninitMobile();\nconst i18nReady = initI18n()\n\t.then(() => {\n\t\ttranslateStaticElements(document.documentElement);\n\t})\n\t.catch((err: unknown) => {\n\t\tconsole.warn(\"[i18n] failed to initialize\", err);\n\t});\nlet appStarted = false;\n\nfunction startAppAfterI18n(): void {\n\tif (appStarted) return;\n\tappStarted = true;\n\ti18nReady.finally(() => {\n\t\tstartApp();\n\t});\n}\n\nconst UPDATE_DISMISS_KEY = \"moltis-update-dismissed-version\";\nlet currentUpdateVersion: string | null = null;\n\n// Apply server-injected identity immediately (no async wait), and\n// keep the header in sync whenever gon.identity is refreshed.\ntry {\n\tapplyIdentity(gon.get(\"identity\") as IdentityInfo | null);\n} catch (_) {\n\t// Non-fatal — page still works without identity in the header.\n}\ngon.onChange(\"identity\", applyIdentity as (v: unknown) => void);\n\n// Show git branch banner when running on a non-main branch.\ntry {\n\tshowBranchBanner(gon.get(\"git_branch\") as string | null);\n} catch (_) {\n\t// Non-fatal — branch indicator is cosmetic.\n}\ngon.onChange(\"git_branch\", showBranchBanner as (v: unknown) => void);\ntry {\n\tshowUpdateBanner(gon.get(\"update\") as { available?: boolean; latest_version?: string; release_url?: string } | null);\n} catch (_) {\n\t// Non-fatal — update indicator is cosmetic.\n}\ngon.onChange(\"update\", showUpdateBanner as (v: unknown) => void);\nonEvent(\"update.available\", showUpdateBanner as (payload: unknown) => void);\ninitUpdateBannerDismiss();\nshowVaultBanner(gon.get(\"vault_status\") as string | null);\ngon.onChange(\"vault_status\", showVaultBanner as (v: unknown) => void);\n\nfunction upsertSessionFromEvent(entry: SessionEntry | null): boolean {\n\tif (!entry?.key) return false;\n\tsessionStore.upsert(entry as never);\n\tconst legacy = S.sessions.slice() as SessionEntry[];\n\tconst idx = legacy.findIndex((session) => session.key === entry.key);\n\tlet nextEntry = { ...entry };\n\tif (idx >= 0) {\n\t\tnextEntry = { ...legacy[idx], ...entry };\n\t}\n\tS.setSessions(insertSessionInOrder(legacy as never[], nextEntry as never));\n\trenderSessionList();\n\treturn true;\n}\n\nfunction removeSessionFromEvent(sessionKey: string): boolean {\n\treturn removeSessionFromClientState(sessionKey, { navigateIfActive: true });\n}\n\nonEvent(\"session\", (_payload: unknown) => {\n\tconst payload = _payload as Record<string, unknown>;\n\tif (!payload?.kind) return;\n\tif (payload.kind === \"deleted\") {\n\t\tif (!removeSessionFromEvent(payload.sessionKey as string)) {\n\t\t\tfetchSessions();\n\t\t}\n\t\treturn;\n\t}\n\tif (upsertSessionFromEvent((payload.entry as SessionEntry) || null)) return;\n\tif (payload.kind === \"created\" || payload.kind === \"patched\") {\n\t\tfetchSessions();\n\t}\n});\n\nfunction seedSessionsFromGon(): void {\n\tconst seeded = gon.get(\"sessions_recent\") as SessionEntry[] | null;\n\tif (!Array.isArray(seeded) || seeded.length === 0) return;\n\tif (sessionStore.sessions.value.length > 0) return;\n\tsessionStore.setAll(seeded as never[]);\n\tS.setSessions(seeded as never[]);\n\trenderSessionList();\n}\n\nseedSessionsFromGon();\n\nfunction applyMemory(mem: MemInfo | null): void {\n\tif (!mem) return;\n\tconst el = document.getElementById(\"memoryInfo\");\n\tif (!el) return;\n\tconst fmt = (b: number): string => prettyBytes(b, { maximumFractionDigits: 0, space: false });\n\tlet localLlamaCpp = 0;\n\tif (typeof mem.localLlamaCpp === \"number\") {\n\t\tlocalLlamaCpp = mem.localLlamaCpp;\n\t} else if (typeof mem.local_llama_cpp === \"number\") {\n\t\t// Backward compatibility with older payload casing.\n\t\tlocalLlamaCpp = mem.local_llama_cpp;\n\t}\n\tconst localLlamaPart = localLlamaCpp > 0 ? ` (llama.cpp ${fmt(localLlamaCpp)})` : \"\";\n\tel.textContent = `${fmt(mem.process)}${localLlamaPart} \\u00b7 ${fmt(mem.available)} free / ${fmt(mem.total)}`;\n}\n\napplyMemory(gon.get(\"mem\") as MemInfo | null);\ngon.onChange(\"mem\", applyMemory as (v: unknown) => void);\nonEvent(\"tick\", (_payload: unknown) => { const payload = _payload as Record<string, unknown>; applyMemory(payload.mem as MemInfo | null); });\n\n// Logout button — wire up click handler once.\nconst logoutBtn = document.getElementById(\"logoutBtn\");\nconst settingsBtn = document.getElementById(\"settingsBtn\");\nconst mobileMenuBtn = document.getElementById(\"mobileMenuBtn\");\nconst mobileMenuOverlay = document.getElementById(\"mobileMenuOverlay\");\nconst mobileMenuPanel = document.getElementById(\"mobileMenuPanel\");\nconst mobileMenuSessionsBtn = document.getElementById(\"mobileMenuSessionsBtn\");\nconst mobileMenuSettingsBtn = document.getElementById(\"mobileMenuSettingsBtn\");\nconst mobileMenuLogoutBtn = document.getElementById(\"mobileMenuLogoutBtn\");\n\nfunction closeMobileMenu(): void {\n\tif (mobileMenuPanel) mobileMenuPanel.classList.remove(\"open\");\n\tif (mobileMenuOverlay) mobileMenuOverlay.classList.remove(\"visible\");\n}\n\nfunction toggleMobileMenu(): void {\n\tif (!(mobileMenuPanel && mobileMenuOverlay)) return;\n\tconst isOpen = mobileMenuPanel.classList.contains(\"open\");\n\tif (isOpen) {\n\t\tcloseMobileMenu();\n\t\treturn;\n\t}\n\tmobileMenuPanel.classList.add(\"open\");\n\tmobileMenuOverlay.classList.add(\"visible\");\n}\n\nfunction performLogout(): void {\n\tcloseMobileMenu();\n\tfetch(\"/api/auth/logout\", { method: \"POST\" }).finally(() => {\n\t\tlocation.href = \"/\";\n\t});\n}\n\nif (logoutBtn) {\n\tlogoutBtn.addEventListener(\"click\", performLogout);\n}\nif (settingsBtn) {\n\tsettingsBtn.addEventListener(\"click\", () => {\n\t\tcloseMobileMenu();\n\t\tnavigate(routes.identity as string);\n\t});\n}\nif (mobileMenuBtn) {\n\tmobileMenuBtn.addEventListener(\"click\", (e) => {\n\t\te.stopPropagation();\n\t\ttoggleMobileMenu();\n\t});\n}\nif (mobileMenuOverlay) {\n\tmobileMenuOverlay.addEventListener(\"click\", closeMobileMenu);\n}\nif (mobileMenuSettingsBtn) {\n\tmobileMenuSettingsBtn.addEventListener(\"click\", () => {\n\t\tcloseMobileMenu();\n\t\tnavigate(routes.identity as string);\n\t});\n}\nif (mobileMenuSessionsBtn) {\n\tmobileMenuSessionsBtn.addEventListener(\"click\", () => {\n\t\tcloseMobileMenu();\n\t\tif (window.innerWidth < 768) {\n\t\t\ttoggleSessions();\n\t\t}\n\t});\n}\nif (mobileMenuLogoutBtn) {\n\tmobileMenuLogoutBtn.addEventListener(\"click\", performLogout);\n}\nwindow.addEventListener(\"resize\", () => {\n\tif (window.innerWidth >= 768) closeMobileMenu();\n});\ndocument.addEventListener(\"keydown\", (e) => {\n\tif (e.key === \"Escape\") closeMobileMenu();\n});\ndocument.addEventListener(\"click\", (e) => {\n\tif (!mobileMenuPanel?.classList.contains(\"open\")) return;\n\tif (mobileMenuPanel.contains(e.target as Node)) return;\n\tif (mobileMenuBtn?.contains(e.target as Node)) return;\n\tcloseMobileMenu();\n});\n\nfunction updateAuthChrome(auth: AuthStatus | null): void {\n\tconst showLogout = !!(auth?.authenticated && !auth.auth_disabled && (auth.has_password || auth.has_passkeys));\n\tif (logoutBtn) {\n\t\tlogoutBtn.style.display = showLogout ? \"\" : \"none\";\n\t}\n\tif (mobileMenuLogoutBtn) {\n\t\t(mobileMenuLogoutBtn as HTMLElement).style.display = showLogout ? \"\" : \"none\";\n\t}\n\tif (mobileMenuPanel) {\n\t\tmobileMenuPanel.classList.toggle(\"logout-hidden\", !showLogout);\n\t}\n\tif (!showLogout) {\n\t\tcloseMobileMenu();\n\t}\n\n\tconst banner = document.getElementById(\"authDisabledBanner\");\n\tif (banner) {\n\t\tconst showAuthDisabled = !!(auth?.auth_disabled && !auth.localhost_only);\n\t\tbanner.style.display = showAuthDisabled ? \"\" : \"none\";\n\t}\n}\n\nfunction refreshAuthChrome(): Promise<AuthStatus | null> {\n\treturn fetch(\"/api/auth/status\")\n\t\t.then((r) => (r.ok ? r.json() : null))\n\t\t.then((auth: AuthStatus | null) => {\n\t\t\tupdateAuthChrome(auth);\n\t\t\treturn auth;\n\t\t})\n\t\t.catch(() => null);\n}\n\nwindow.addEventListener(\"moltis:auth-status-changed\", () => {\n\trefreshAuthChrome()\n\t\t.then((auth) => {\n\t\t\tif (!auth) return;\n\t\t\tif (auth.setup_required) {\n\t\t\t\tclearSensitiveData();\n\t\t\t\twindow.location.assign(\"/onboarding\");\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tif (!auth.authenticated) {\n\t\t\t\tclearSensitiveData();\n\t\t\t\twindow.location.assign(\"/login\");\n\t\t\t}\n\t\t})\n\t\t.finally(() => {\n\t\t\twindow.dispatchEvent(new CustomEvent(\"moltis:auth-status-sync-complete\"));\n\t\t});\n});\n\n/**\n * Purge cached sensitive data so that a logged-out page cannot display\n * session previews, identity info, or other user-scoped state.\n */\nfunction clearSensitiveData(): void {\n\t// Clear session store and legacy state\n\tsessionStore.setAll([]);\n\tS.setSessions([]);\n\trenderSessionList();\n\n\t// Clear model and project stores\n\tmodelStore.setAll([]);\n\tS.setModels([]);\n\tprojectStore.setAll([]);\n\tS.setProjects([]);\n\n\t// Clear identity from gon so sidebar/header no longer shows it\n\tgon.set(\"identity\", null as unknown as import(\"./types/gon\").ResolvedIdentity);\n\tgon.set(\"sessions_recent\", null as unknown as import(\"./types\").SessionMeta[]);\n\t// Signal vault sealed so SessionList shows the correct placeholder\n\tgon.set(\"vault_status\", \"sealed\");\n}\n\n// Seed sandbox info from gon so the settings page can render immediately\n// without waiting for the auth-protected /api/bootstrap fetch.\ntry {\n\tconst gonSandbox = gon.get(\"sandbox\");\n\tif (gonSandbox) S.setSandboxInfo(gonSandbox);\n} catch (_) {\n\t// Non-fatal — sandbox info will arrive via bootstrap.\n}\n// Check auth status before mounting the app.\nfetch(\"/api/auth/status\")\n\t.then((r) => (r.ok ? r.json() : null))\n\t.then((auth: AuthStatus | null) => {\n\t\tif (!auth) {\n\t\t\t// Auth endpoints not available — no auth configured, proceed normally.\n\t\t\tstartAppAfterI18n();\n\t\t\treturn;\n\t\t}\n\t\tif (auth.setup_required) {\n\t\t\twindow.location.assign(\"/onboarding\");\n\t\t\treturn;\n\t\t}\n\t\tif (!auth.authenticated) {\n\t\t\t// Server-side middleware handles the redirect to /login.\n\t\t\t// This is a defense-in-depth fallback for edge cases\n\t\t\t// (e.g. session expired after the page was already served).\n\t\t\twindow.location.assign(\"/login\");\n\t\t\treturn;\n\t\t}\n\t\tupdateAuthChrome(auth);\n\t\tstartAppAfterI18n();\n\t})\n\t.catch(() => {\n\t\t// If auth check fails, proceed anyway (backward compat).\n\t\tstartAppAfterI18n();\n\t});\n\nfunction showUpdateBanner(update: { available?: boolean; latest_version?: string; release_url?: string } | null): void {\n\tconst el = document.getElementById(\"updateBanner\");\n\tif (!el) return;\n\n\tconst latestVersion = update?.latest_version || null;\n\tcurrentUpdateVersion = latestVersion;\n\tconst dismissedVersion = localStorage.getItem(UPDATE_DISMISS_KEY);\n\n\tif (update?.available && (!latestVersion || dismissedVersion !== latestVersion)) {\n\t\tconst versionEl = document.getElementById(\"updateLatestVersion\");\n\t\tif (versionEl) {\n\t\t\tversionEl.textContent = latestVersion ? `v${latestVersion}` : \"\";\n\t\t}\n\t\tconst linkEl = document.getElementById(\"updateReleaseLink\") as HTMLAnchorElement | null;\n\t\tif (linkEl && update.release_url) {\n\t\t\tlinkEl.href = update.release_url;\n\t\t}\n\t\tel.style.display = \"\";\n\t} else {\n\t\tel.style.display = \"none\";\n\t}\n}\n\nfunction initUpdateBannerDismiss(): void {\n\tconst dismissBtn = document.getElementById(\"updateDismissBtn\") as HTMLElement | null;\n\tif (!dismissBtn || dismissBtn.dataset.bound === \"1\") return;\n\tdismissBtn.dataset.bound = \"1\";\n\tdismissBtn.addEventListener(\"click\", () => {\n\t\tif (currentUpdateVersion) {\n\t\t\tlocalStorage.setItem(UPDATE_DISMISS_KEY, currentUpdateVersion);\n\t\t}\n\t\tconst el = document.getElementById(\"updateBanner\");\n\t\tif (el) el.style.display = \"none\";\n\t});\n}\n\nfunction showVaultBanner(status: string | null): void {\n\tconst el = document.getElementById(\"vaultBanner\");\n\tif (!el) return;\n\tel.style.display = status === \"sealed\" ? \"\" : \"none\";\n}\n\nfunction showBranchBanner(branch: string | null): void {\n\tconst el = document.getElementById(\"branchBanner\");\n\tif (!el) return;\n\n\tif (branch) {\n\t\tconst branchNameEl = document.getElementById(\"branchName\");\n\t\tif (branchNameEl) branchNameEl.textContent = branch;\n\t\tel.style.display = \"\";\n\n\t\t// Prefix page title with branch name.\n\t\tdocument.title = `[${branch}] ${formatPageTitle(gon.get(\"identity\") as IdentityInfo | null)}`;\n\t} else {\n\t\tel.style.display = \"none\";\n\n\t\t// Restore original title\n\t\tdocument.title = formatPageTitle(gon.get(\"identity\") as IdentityInfo | null);\n\t}\n}\n\nfunction applyIdentity(identity: IdentityInfo | null): void {\n\tconst emojiEl = document.getElementById(\"titleEmoji\");\n\tconst nameEl = document.getElementById(\"titleName\");\n\tif (emojiEl) emojiEl.textContent = identity?.emoji ? `${identity.emoji} ` : \"\";\n\tif (nameEl) nameEl.textContent = identity?.name || \"moltis\";\n\tapplyIdentityFavicon(identity);\n\tconst branch = gon.get(\"git_branch\") as string | null;\n\n\t// Keep page title in sync with identity and branch.\n\tconst title = formatPageTitle(identity);\n\tif (branch) {\n\t\tdocument.title = `[${branch}] ${title}`;\n\t} else {\n\t\tdocument.title = title;\n\t}\n}\n\nfunction applyModels(models: ModelEntry[]): void {\n\tconst arr = models || [];\n\tmodelStore.setAll(arr as never[]);\n\t// Dual-write to state.js for backward compat\n\tS.setModels(arr);\n\tif (arr.length === 0) return;\n\tconst saved = localStorage.getItem(\"moltis-model\") || \"\";\n\tconst found = arr.find((m) => m.id === saved);\n\tif (found) {\n\t\tmodelStore.select(found.id);\n\t\tS.setSelectedModelId(found.id);\n\t} else {\n\t\tmodelStore.select(arr[0].id);\n\t\tS.setSelectedModelId(arr[0].id);\n\t\tlocalStorage.setItem(\"moltis-model\", modelStore.selectedModelId.value);\n\t}\n}\n\nfunction fetchBootstrap(): void {\n\t// Fetch bootstrap data asynchronously — populates sidebar, models, projects\n\t// as soon as the data arrives, without blocking the initial page render.\n\tfetch(\"/api/bootstrap?include_sessions=false\")\n\t\t.then((r) => {\n\t\t\tif (r.status === 401 || r.status === 403) {\n\t\t\t\twindow.dispatchEvent(new CustomEvent(\"moltis:auth-status-changed\"));\n\t\t\t\treturn Promise.reject(new Error(\"auth\"));\n\t\t\t}\n\t\t\treturn r.json();\n\t\t})\n\t\t.then((boot: BootstrapData) => {\n\t\t\tif (boot.channels) S.setCachedChannels((boot.channels as { channels?: unknown[] }).channels || boot.channels || []);\n\t\t\tif (boot.sessions) {\n\t\t\t\tconst bootSessions = boot.sessions || [];\n\t\t\t\tsessionStore.setAll(bootSessions as never[]);\n\t\t\t\t// Dual-write to state.js for backward compat\n\t\t\t\tS.setSessions(bootSessions);\n\t\t\t\trenderSessionList();\n\t\t\t} else {\n\t\t\t\t// Keep full list fetch separate from bootstrap payload size.\n\t\t\t\tfetchSessions();\n\t\t\t}\n\t\t\tif (boot.models) applyModels(boot.models);\n\t\t\trefreshWelcomeCardIfNeeded();\n\t\t\tif (boot.projects) {\n\t\t\t\tconst bootProjects = boot.projects || [];\n\t\t\t\tprojectStore.setAll(bootProjects as never[]);\n\t\t\t\t// Dual-write to state.js for backward compat\n\t\t\t\tS.setProjects(bootProjects);\n\t\t\t\trenderProjectSelect();\n\t\t\t\trenderSessionProjectSelect();\n\t\t\t}\n\t\t\tS.setSandboxInfo(boot.sandbox || null);\n\t\t\t// Re-apply sandbox UI now that we know the backend status.\n\t\t\t// This fixes the race where the chat page renders before bootstrap completes.\n\t\t\tupdateSandboxUI(S.sessionSandboxEnabled);\n\t\t\tupdateSandboxImageUI(S.sessionSandboxImage);\n\t\t\tif (boot.counts) updateNavCounts(boot.counts);\n\t\t})\n\t\t.catch(() => {\n\t\t\t// If bootstrap fails, hydrate from dedicated lightweight endpoints.\n\t\t\tfetchSessions();\n\t\t\tfetchModels();\n\t\t\tfetchProjects();\n\t\t});\n}\n\nfunction initSessionTabBar(): void {\n\tconst bar = S.$(\"sessionTabBar\");\n\tif (!bar) return;\n\tconst buttons = bar.querySelectorAll<HTMLElement>(\".session-tab\");\n\tconst archivedRow = S.$(\"archivedSessionsRow\");\n\n\tfunction updateActive(): void {\n\t\tconst current = sessionStore.sessionListTab.value;\n\t\tfor (const btn of buttons) {\n\t\t\tbtn.classList.toggle(\"active\", btn.dataset.tab === current);\n\t\t}\n\t\tif (archivedRow) {\n\t\t\tarchivedRow.classList.toggle(\"hidden\", current !== \"sessions\");\n\t\t}\n\t}\n\n\tfor (const btn of buttons) {\n\t\tbtn.addEventListener(\"click\", function (this: HTMLElement) {\n\t\t\tsessionStore.setSessionListTab(this.dataset.tab || \"sessions\");\n\t\t\tupdateActive();\n\t\t});\n\t}\n\tupdateActive();\n}\n\nfunction initArchivedSessionsToggle(): void {\n\tconst checkbox = S.$(\"showArchivedSessions\") as HTMLInputElement | null;\n\tif (!checkbox) return;\n\tcheckbox.checked = sessionStore.showArchivedSessions.value;\n\tcheckbox.addEventListener(\"change\", function (this: HTMLInputElement) {\n\t\tsessionStore.setShowArchivedSessions(this.checked);\n\t});\n}\n\nfunction startApp(): void {\n\t// Mount the reactive SessionList once — signals drive all re-renders.\n\tconst sessionListEl = S.$(\"sessionList\");\n\tif (sessionListEl) render(<SessionList />, sessionListEl);\n\tinitSessionTabBar();\n\tinitArchivedSessionsToggle();\n\n\tlet path = location.pathname;\n\tif (path === \"/\") {\n\t\tpath = preferredChatPath();\n\t\thistory.replaceState(null, \"\", path);\n\t}\n\tmount(path);\n\tconnect();\n\tfetchBootstrap();\n\tinitInstallBanner();\n}\n"],"file":"main.js"}
