utton>\n\t\t\t\t)}\n\t\t\t\t{showClear && isMain && (\n\t\t\t\t\t<button className={actionButtonClass} onClick={onClear} title=\"Clear session\" disabled={clearing}>\n\t\t\t\t\t\t{clearing ? \"Clearing\\u2026\" : \"Clear\"}\n\t\t\t\t\t</button>\n\t\t\t\t)}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n","// ── Media drag-and-drop + paste module ──────────────────────\n// Handles drag-and-drop image upload, clipboard paste, and\n// image preview strip above the chat input area.\n\nimport { t } from \"./i18n\";\nimport * as S from \"./state\";\n\ninterface PendingImage {\n\tdataUrl: string;\n\tfile: File;\n\tname: string;\n}\n\nlet pendingImages: PendingImage[] = [];\nlet previewStrip: HTMLElement | null = null;\nlet chatMsgBoxRef: HTMLElement | null = null;\n\n// Track bound handlers for teardown\nlet boundDragOver: ((e: DragEvent) => void) | null = null;\nlet boundDragEnter: ((e: DragEvent) => void) | null = null;\nlet boundDragLeave: ((e: DragEvent) => void) | null = null;\nlet boundDrop: ((e: DragEvent) => void) | null = null;\nlet boundPaste: ((e: ClipboardEvent) => void) | null = null;\nlet dragEnterCount = 0;\n\nconst ACCEPTED_TYPES: string[] = [\"image/png\", \"image/jpeg\", \"image/gif\", \"image/webp\"];\nconst MAX_FILE_SIZE = 20 * 1024 * 1024; // 20 MB\n\nfunction isImageFile(file: File): boolean {\n\treturn ACCEPTED_TYPES.indexOf(file.type) !== -1;\n}\n\nfunction readFileAsDataUrl(file: File): Promise<string> {\n\treturn new Promise((resolve, reject) => {\n\t\tconst reader = new FileReader();\n\t\treader.onload = (): void => {\n\t\t\tresolve(reader.result as string);\n\t\t};\n\t\treader.onerror = (): void => {\n\t\t\treject(reader.error);\n\t\t};\n\t\treader.readAsDataURL(file);\n\t});\n}\n\nfunction addImage(dataUrl: string, file: File): void {\n\tpendingImages.push({ dataUrl: dataUrl, file: file, name: file.name });\n\trenderPreview();\n}\n\nfunction removeImage(index: number): void {\n\tpendingImages.splice(index, 1);\n\trenderPreview();\n}\n\nfunction renderPreview(): void {\n\tif (!previewStrip) return;\n\tpreviewStrip.textContent = \"\";\n\n\tif (pendingImages.length === 0) {\n\t\tpreviewStrip.classList.add(\"hidden\");\n\t\treturn;\n\t}\n\n\tpreviewStrip.classList.remove(\"hidden\");\n\n\tfor (let i = 0; i < pendingImages.length; i++) {\n\t\tconst item = document.createElement(\"div\");\n\t\titem.className = \"media-preview-item\";\n\n\t\tconst img = document.createElement(\"img\");\n\t\timg.className = \"media-preview-thumb\";\n\t\timg.src = pendingImages[i].dataUrl;\n\t\timg.alt = pendingImages[i].name;\n\t\titem.appendChild(img);\n\n\t\tconst name = document.createElement(\"span\");\n\t\tname.className = \"media-preview-name\";\n\t\tname.textContent = pendingImages[i].name;\n\t\titem.appendChild(name);\n\n\t\tconst removeBtn = document.createElement(\"button\");\n\t\tremoveBtn.className = \"media-preview-remove\";\n\t\tremoveBtn.textContent = \"\\u2715\";\n\t\tremoveBtn.title = t(\"common:actions.remove\");\n\t\tremoveBtn.dataset.idx = String(i);\n\t\tremoveBtn.addEventListener(\"click\", (e: MouseEvent): void => {\n\t\t\tconst idx = Number.parseInt((e.currentTarget as HTMLButtonElement).dataset.idx!, 10);\n\t\t\tremoveImage(idx);\n\t\t});\n\t\titem.appendChild(removeBtn);\n\n\t\tpreviewStrip.appendChild(item);\n\t}\n}\n\nasync function handleFiles(files: FileList | File[]): Promise<void> {\n\tfor (const file of files) {\n\t\tif (!isImageFile(file)) continue;\n\t\tif (file.size > MAX_FILE_SIZE) continue;\n\t\ttry {\n\t\t\tconst dataUrl = await readFileAsDataUrl(file);\n\t\t\taddImage(dataUrl, file);\n\t\t} catch (err) {\n\t\t\tconsole.warn(\"[media-drop] Failed to read file:\", err);\n\t\t}\n\t}\n}\n\nfunction onDragOver(e: DragEvent): void {\n\te.preventDefault();\n\te.dataTransfer!.dropEffect = \"copy\";\n}\n\nfunction onDragEnter(e: DragEvent): void {\n\te.preventDefault();\n\tdragEnterCount++;\n\tif (chatMsgBoxRef) chatMsgBoxRef.classList.add(\"drag-over\");\n}\n\nfunction onDragLeave(e: DragEvent): void {\n\te.preventDefault();\n\tdragEnterCount--;\n\tif (dragEnterCount <= 0) {\n\t\tdragEnterCount = 0;\n\t\tif (chatMsgBoxRef) chatMsgBoxRef.classList.remove(\"drag-over\");\n\t}\n}\n\nfunction onDrop(e: DragEvent): void {\n\te.preventDefault();\n\tdragEnterCount = 0;\n\tif (chatMsgBoxRef) chatMsgBoxRef.classList.remove(\"drag-over\");\n\n\tconst files = e.dataTransfer!.files;\n\tif (files.length > 0) {\n\t\thandleFiles(files);\n\t}\n}\n\nfunction onPaste(e: ClipboardEvent): void {\n\tconst items = e.clipboardData?.files;\n\tif (!items || items.length === 0) return;\n\n\tconst imageFiles: File[] = [];\n\tfor (const f of items) {\n\t\tif (isImageFile(f)) imageFiles.push(f);\n\t}\n\tif (imageFiles.length > 0) {\n\t\te.preventDefault();\n\t\thandleFiles(imageFiles);\n\t}\n}\n\n/**\n * Initialize drag-and-drop and paste handling.\n */\nexport function initMediaDrop(msgBox: HTMLElement, inputArea: HTMLElement): void {\n\tchatMsgBoxRef = msgBox;\n\n\t// Create preview strip above the input row (not inside it)\n\tpreviewStrip = document.createElement(\"div\");\n\tpreviewStrip.className = \"media-preview-strip hidden\";\n\tif (inputArea?.parentElement) {\n\t\tinputArea.parentElement.insertBefore(previewStrip, inputArea);\n\t}\n\n\t// Bind drag-and-drop to messages area\n\tif (msgBox) {\n\t\tboundDragOver = onDragOver;\n\t\tboundDragEnter = onDragEnter;\n\t\tboundDragLeave = onDragLeave;\n\t\tboundDrop = onDrop;\n\t\tmsgBox.addEventListener(\"dragover\", boundDragOver);\n\t\tmsgBox.addEventListener(\"dragenter\", boundDragEnter);\n\t\tmsgBox.addEventListener(\"dragleave\", boundDragLeave);\n\t\tmsgBox.addEventListener(\"drop\", boundDrop);\n\t}\n\n\t// Bind paste to chat input\n\tif (S.chatInput) {\n\t\tboundPaste = onPaste;\n\t\t(S.chatInput as HTMLElement).addEventListener(\"paste\", boundPaste as EventListener);\n\t}\n}\n\n/** Remove all listeners and clean up. */\nexport function teardownMediaDrop(): void {\n\tif (chatMsgBoxRef) {\n\t\tif (boundDragOver) chatMsgBoxRef.removeEventListener(\"dragover\", boundDragOver);\n\t\tif (boundDragEnter) chatMsgBoxRef.removeEventListener(\"dragenter\", boundDragEnter);\n\t\tif (boundDragLeave) chatMsgBoxRef.removeEventListener(\"dragleave\", boundDragLeave);\n\t\tif (boundDrop) chatMsgBoxRef.removeEventListener(\"drop\", boundDrop);\n\t}\n\tif (S.chatInput && boundPaste) {\n\t\t(S.chatInput as HTMLElement).removeEventListener(\"paste\", boundPaste as EventListener);\n\t}\n\tif (previewStrip?.parentElement) {\n\t\tpreviewStrip.parentElement.removeChild(previewStrip);\n\t}\n\tpendingImages = [];\n\tpreviewStrip = null;\n\tchatMsgBoxRef = null;\n\tboundDragOver = null;\n\tboundDragEnter = null;\n\tboundDragLeave = null;\n\tboundDrop = null;\n\tboundPaste = null;\n\tdragEnterCount = 0;\n}\n\nexport function getPendingImages(): PendingImage[] {\n\treturn pendingImages;\n}\n\n/** Clear pending images and hide preview strip. */\nexport function clearPendingImages(): void {\n\tpendingImages = [];\n\trenderPreview();\n}\n\nexport function hasPendingImages(): boolean {\n\treturn pendingImages.length > 0;\n}\n","// ── Voice input module ───────────────────────────────────────\n// Handles microphone recording and speech-to-text transcription.\n\nimport { chatAddMsg } from \"./chat-ui\";\nimport * as gon from \"./gon\";\nimport { renderAudioPlayer, renderMarkdown, sendRpc, warmAudioPlayback } from \"./helpers\";\nimport { t } from \"./i18n\";\nimport { bumpSessionCount, seedSessionPreviewFromUserText, setSessionReplying } from \"./sessions\";\nimport * as S from \"./state\";\n\nlet micBtn: HTMLButtonElement | null = null;\nlet mediaRecorder: MediaRecorder | null = null;\nlet audioChunks: Blob[] = [];\nlet sttConfigured = false;\nlet isRecording = false;\nlet isStarting = false;\nlet transcribingEl: HTMLElement | null = null;\n\n/** Check if voice feature is enabled. */\nfunction isVoiceEnabled(): boolean {\n\treturn gon.get(\"voice_enabled\") === true;\n}\n\n/** Check if STT is available and enable/disable mic button. */\nasync function checkSttStatus(): Promise<void> {\n\t// If voice feature is disabled, always hide the button\n\tif (!isVoiceEnabled()) {\n\t\tsttConfigured = false;\n\t\tupdateMicButton();\n\t\treturn;\n\t}\n\tconst res = await sendRpc(\"stt.status\", {});\n\tif (res?.ok && res.payload) {\n\t\tsttConfigured = (res.payload as Record<string, unknown>).configured === true;\n\t} else {\n\t\tsttConfigured = false;\n\t}\n\tupdateMicButton();\n}\n\n/** Update mic button visibility based on STT configuration. */\nfunction updateMicButton(): void {\n\tif (!micBtn) return;\n\t// Hide button when voice feature is disabled or STT is not configured\n\tmicBtn.style.display = sttConfigured && isVoiceEnabled() ? \"\" : \"none\";\n\t// Disable only when not connected (button is only visible when STT configured)\n\tmicBtn.disabled = !S.connected;\n\tmicBtn.title = isStarting ? t(\"chat:micStarting\") : isRecording ? t(\"chat:micStopAndSend\") : t(\"chat:micTooltip\");\n}\n\n/** Pause all currently playing audio elements on the page. */\nfunction stopAllAudio(): void {\n\tfor (const audio of document.querySelectorAll(\"audio\")) {\n\t\tif (!audio.paused) {\n\t\t\taudio.pause();\n\t\t\tconsole.debug(\"[voice] paused playing audio\");\n\t\t}\n\t}\n}\n\n/** Start recording audio from the microphone. */\nasync function startRecording(): Promise<void> {\n\tif (isRecording || isStarting || !sttConfigured) return;\n\n\t// Stop any playing audio so the mic doesn't pick up speaker output.\n\tstopAllAudio();\n\n\tisStarting = true;\n\tmicBtn!.classList.add(\"starting\");\n\tmicBtn!.setAttribute(\"aria-busy\", \"true\");\n\tmicBtn!.title = t(\"chat:micStarting\");\n\n\ttry {\n\t\tconst stream = await navigator.mediaDevices.getUserMedia({ audio: true });\n\t\taudioChunks = [];\n\t\tlet recordingUiShown = false;\n\n\t\tfunction showRecordingUi(): void {\n\t\t\tif (recordingUiShown || !micBtn) return;\n\t\t\trecordingUiShown = true;\n\t\t\tisStarting = false;\n\t\t\tmicBtn.classList.remove(\"starting\");\n\t\t\tmicBtn.removeAttribute(\"aria-busy\");\n\t\t\tmicBtn.classList.add(\"recording\");\n\t\t\tmicBtn.setAttribute(\"aria-pressed\", \"true\");\n\t\t\tmicBtn.title = t(\"chat:micStopAndSend\");\n\t\t}\n\n\t\t// Use webm/opus if available, fall back to audio/webm\n\t\tconst mimeType = MediaRecorder.isTypeSupported(\"audio/webm;codecs=opus\") ? \"audio/webm;codecs=opus\" : \"audio/webm\";\n\n\t\tmediaRecorder = new MediaRecorder(stream, { mimeType });\n\n\t\tmediaRecorder.ondataavailable = (e: BlobEvent): void => {\n\t\t\tif (e.data.size > 0) {\n\t\t\t\taudioChunks.push(e.data);\n\t\t\t\tshowRecordingUi();\n\t\t\t}\n\t\t};\n\n\t\t// Recorder start means stop is now valid; visual indicator waits for actual audio data.\n\t\tmediaRecorder.onstart = (): void => {\n\t\t\tisRecording = true;\n\t\t};\n\n\t\tconst audioTrack = stream.getAudioTracks()[0];\n\t\tif (audioTrack && !audioTrack.muted) {\n\t\t\tsetTimeout(showRecordingUi, 150);\n\t\t} else if (audioTrack) {\n\t\t\taudioTrack.addEventListener(\"unmute\", showRecordingUi, { once: true });\n\t\t}\n\n\t\tmediaRecorder.onstop = async (): Promise<void> => {\n\t\t\t// Stop all tracks to release the microphone\n\t\t\tfor (const track of stream.getTracks()) {\n\t\t\t\ttrack.stop();\n\t\t\t}\n\t\t\tawait transcribeAudio();\n\t\t};\n\n\t\tmediaRecorder.start(250);\n\t} catch (err) {\n\t\tisStarting = false;\n\t\tisRecording = false;\n\t\tif (micBtn) {\n\t\t\tmicBtn.classList.remove(\"starting\");\n\t\t\tmicBtn.removeAttribute(\"aria-busy\");\n\t\t\tmicBtn.setAttribute(\"aria-pressed\", \"false\");\n\t\t\tmicBtn.title = t(\"chat:micTooltip\");\n\t\t}\n\t\tconsole.error(\"Failed to start recording:\", err);\n\t\t// Show user-friendly error\n\t\tif ((err as DOMException).name === \"NotAllowedError\") {\n\t\t\talert(t(\"settings:voice.micDenied\"));\n\t\t} else if ((err as DOMException).name === \"NotFoundError\") {\n\t\t\talert(t(\"settings:voice.noMicFound\"));\n\t\t}\n\t}\n}\n\n/** Stop recording and trigger transcription. */\nfunction stopRecording(): void {\n\tif (!(isRecording && mediaRecorder)) return;\n\n\tisStarting = false;\n\tisRecording = false;\n\tmicBtn!.classList.remove(\"starting\");\n\tmicBtn!.removeAttribute(\"aria-busy\");\n\tmicBtn!.classList.remove(\"recording\");\n\tmicBtn!.setAttribute(\"aria-pressed\", \"false\");\n\tmicBtn!.classList.add(\"transcribing\");\n\tmicBtn!.title = t(\"chat:voiceTranscribing\");\n\n\t// Stop the recorder, which triggers onstop -> transcribeAudio\n\tmediaRecorder.stop();\n}\n\n/** Cancel recording without sending -- discards audio chunks. */\nfunction cancelRecording(): void {\n\tif (!(isRecording && mediaRecorder)) return;\n\n\tconsole.debug(\"[voice] recording cancelled via Escape\");\n\n\t// Prevent onstop from transcribing by clearing chunks first.\n\taudioChunks = [];\n\n\tisStarting = false;\n\tisRecording = false;\n\tmicBtn!.classList.remove(\"starting\", \"recording\");\n\tmicBtn!.removeAttribute(\"aria-busy\");\n\tmicBtn!.setAttribute(\"aria-pressed\", \"false\");\n\tmicBtn!.title = t(\"chat:micTooltip\");\n\n\t// Stop the recorder -- onstop will see empty chunks and bail out.\n\tmediaRecorder.stop();\n}\n\n/** Create transcribing indicator element. */\nfunction createTranscribingIndicator(message: string, isError: boolean): HTMLElement {\n\tconst el = document.createElement(\"div\");\n\tel.className = \"msg voice-transcribing\";\n\n\tconst spinner = document.createElement(\"span\");\n\tspinner.className = \"voice-transcribing-spinner\";\n\n\tconst text = document.createElement(\"span\");\n\ttext.className = \"voice-transcribing-text\";\n\tif (isError) text.classList.add(\"text-[var(--error)]\");\n\ttext.textContent = message;\n\n\tif (!isError) el.appendChild(spinner);\n\tel.appendChild(text);\n\treturn el;\n}\n\n/** Update transcribing element with a message. */\nfunction updateTranscribingMessage(message: string, isError: boolean): void {\n\tif (!transcribingEl) return;\n\ttranscribingEl.textContent = \"\";\n\tconst text = document.createElement(\"span\");\n\ttext.className = \"voice-transcribing-text\";\n\ttext.classList.add(isError ? \"text-[var(--error)]\" : \"text-[var(--muted)]\");\n\ttext.textContent = message;\n\ttranscribingEl.appendChild(text);\n}\n\n/** Show a temporary message then remove the transcribing element. */\nfunction showTemporaryMessage(message: string, isError: boolean, delayMs: number): void {\n\tupdateTranscribingMessage(message, isError);\n\tsetTimeout(() => {\n\t\tif (transcribingEl) {\n\t\t\ttranscribingEl.remove();\n\t\t\ttranscribingEl = null;\n\t\t}\n\t}, delayMs);\n}\n\n/** Remove transcribing indicator and reset mic button state. */\nfunction cleanupTranscribingState(): void {\n\tisStarting = false;\n\tmicBtn!.classList.remove(\"starting\");\n\tmicBtn!.removeAttribute(\"aria-busy\");\n\tmicBtn!.classList.remove(\"transcribing\");\n\tmicBtn!.title = t(\"chat:micTooltip\");\n\tif (transcribingEl) {\n\t\ttranscribingEl.remove();\n\t\ttranscribingEl = null;\n\t}\n}\n\n/** Send transcribed text as a chat message. */\nfunction sendTranscribedMessage(text: string, audioFilename: string | null): void {\n\t// Unlock audio playback while we still have user-gesture context.\n\twarmAudioPlayback();\n\n\t// Add user message to chat (like sendChat does), including the recorded\n\t// audio player when we have a saved filename from the upload endpoint.\n\tif (audioFilename) {\n\t\tconst userEl = chatAddMsg(\"user\", \"\", true);\n\t\tif (userEl) {\n\t\t\tconst audioSrc = `/api/sessions/${encodeURIComponent(S.activeSessionKey)}/media/${encodeURIComponent(audioFilename)}`;\n\t\t\trenderAudioPlayer(userEl, audioSrc);\n\t\t\tif (text) {\n\t\t\t\tconst textWrap = document.createElement(\"div\");\n\t\t\t\ttextWrap.className = \"mt-2\";\n\t\t\t\t// Safe: renderMarkdown escapes untrusted content before formatting tags.\n\t\t\t\ttextWrap.textContent = \"\";\n\t\t\t\tconst rendered = renderMarkdown(text);\n\t\t\t\tconst fragment = document.createRange().createContextualFragment(rendered);\n\t\t\t\ttextWrap.appendChild(fragment);\n\t\t\t\tuserEl.appendChild(textWrap);\n\t\t\t}\n\t\t}\n\t} else {\n\t\tchatAddMsg(\"user\", renderMarkdown(text), true);\n\t}\n\n\t// Send the message\n\tconst chatParams: Record<string, unknown> = { text: text, _input_medium: \"voice\" };\n\tif (audioFilename) {\n\t\tchatParams._audio_filename = audioFilename;\n\t}\n\tconst selectedModel = S.selectedModelId;\n\tif (selectedModel) {\n\t\tchatParams.model = selectedModel;\n\t}\n\tbumpSessionCount(S.activeSessionKey, 1);\n\tseedSessionPreviewFromUserText(S.activeSessionKey, text);\n\tsetSessionReplying(S.activeSessionKey, true);\n\tsendRpc(\"chat.send\", chatParams).then((sendRes) => {\n\t\tif (sendRes && !sendRes.ok && sendRes.error) {\n\t\t\tchatAddMsg(\"error\", sendRes.error?.message || \"Request failed\");\n\t\t}\n\t});\n}\n\n/** Send recorded audio to STT service for transcription via upload endpoint. */\nasync function transcribeAudio(): Promise<void> {\n\tif (audioChunks.length === 0) {\n\t\tcleanupTranscribingState();\n\t\treturn;\n\t}\n\n\t// Show transcribing indicator in chat immediately\n\tif (S.chatMsgBox) {\n\t\ttranscribingEl = createTranscribingIndicator(t(\"chat:voiceTranscribingMessage\"), false);\n\t\t(S.chatMsgBox as HTMLElement).appendChild(transcribingEl);\n\t\t(S.chatMsgBox as HTMLElement).scrollTop = (S.chatMsgBox as HTMLElement).scrollHeight;\n\t}\n\n\ttry {\n\t\tconst blob = new Blob(audioChunks, { type: \"audio/webm\" });\n\t\taudioChunks = [];\n\n\t\tconst resp = await fetch(`/api/sessions/${encodeURIComponent(S.activeSessionKey)}/upload?transcribe=true`, {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": blob.type || \"audio/webm\" },\n\t\t\tbody: blob,\n\t\t});\n\t\tconst res: Record<string, unknown> = await resp.json();\n\n\t\tmicBtn!.classList.remove(\"transcribing\");\n\t\tmicBtn!.title = t(\"chat:micTooltip\");\n\n\t\tif (res.ok && (res.transcription as Record<string, unknown> | undefined)?.text) {\n\t\t\tconst text = String((res.transcription as Record<string, unknown>).text).trim();\n\t\t\tconst audioFilename = typeof res.filename === \"string\" ? (res.filename as string).trim() : \"\";\n\t\t\tif (text) {\n\t\t\t\tcleanupTranscribingState();\n\t\t\t\tsendTranscribedMessage(text, audioFilename || null);\n\t\t\t} else {\n\t\t\t\tshowTemporaryMessage(\"No speech detected\", false, 2000);\n\t\t\t}\n\t\t} else if (res.transcriptionError) {\n\t\t\tconsole.error(\"Transcription failed:\", res.transcriptionError);\n\t\t\tshowTemporaryMessage(`Transcription failed: ${res.transcriptionError}`, true, 4000);\n\t\t} else if (!res.ok) {\n\t\t\tconsole.error(\"Upload failed:\", res.error);\n\t\t\tshowTemporaryMessage(`Upload failed: ${res.error || \"Unknown error\"}`, true, 4000);\n\t\t}\n\t} catch (err) {\n\t\tconsole.error(\"Transcription error:\", err);\n\t\tmicBtn!.classList.remove(\"transcribing\");\n\t\tmicBtn!.title = t(\"chat:micTooltip\");\n\t\tshowTemporaryMessage(\"Transcription error\", true, 4000);\n\t}\n}\n\n/** Handle click on mic button - toggle recording. */\nfunction onMicClick(e: Event): void {\n\te.preventDefault();\n\tif (isRecording) {\n\t\tstopRecording();\n\t} else {\n\t\tstartRecording();\n\t}\n}\n\n/** Initialize voice input with the mic button element. */\nexport function initVoiceInput(btn: HTMLButtonElement | null): void {\n\tif (!btn) return;\n\n\tmicBtn = btn;\n\n\t// Check STT status on init\n\tcheckSttStatus();\n\n\t// Click to toggle recording (start on first click, stop on second)\n\tmicBtn.addEventListener(\"click\", onMicClick);\n\n\t// Keyboard accessibility: Space/Enter to toggle\n\tmicBtn.addEventListener(\"keydown\", (e: KeyboardEvent): void => {\n\t\tif (e.key === \" \" || e.key === \"Enter\") {\n\t\t\te.preventDefault();\n\t\t\tonMicClick(e);\n\t\t}\n\t});\n\n\t// Escape cancels recording without sending.\n\tdocument.addEventListener(\"keydown\", (e: KeyboardEvent): void => {\n\t\tif (e.key === \"Escape\" && isRecording) {\n\t\t\te.preventDefault();\n\t\t\tcancelRecording();\n\t\t}\n\t});\n\n\t// Re-check STT status when voice config changes\n\twindow.addEventListener(\"voice-config-changed\", checkSttStatus);\n}\n\n/** Teardown voice input module. */\nexport function teardownVoiceInput(): void {\n\tif (isRecording && mediaRecorder) {\n\t\tmediaRecorder.stop();\n\t}\n\twindow.removeEventListener(\"voice-config-changed\", checkSttStatus);\n\tmicBtn = null;\n\tmediaRecorder = null;\n\taudioChunks = [];\n\tisRecording = false;\n}\n\n/** Re-check STT status (can be called externally). */\nexport function refreshVoiceStatus(): void {\n\tcheckSttStatus();\n}\n","// ── Chat page (Preact + JSX) ────────────────────────────────────────\n// This is a TypeScript/JSX conversion of page-chat.js. The page is\n// heavily imperative (DOM manipulation + registerPrefix router pattern)\n// so the conversion preserves that style while adding types.\n\n// NOTE: The chatPageHTML constant uses innerHTML assignment which is safe\n// because it is a compile-time static string with no user input interpolated.\n// The original JS file documents this explicitly. The eslint-disable comment\n// is preserved from the original source.\n\nimport { effect } from \"@preact/signals\";\nimport { render } from \"preact\";\nimport { chatAddMsg, chatAddMsgWithImages, updateCommandInputUI } from \"../chat-ui\";\nimport { highlightCodeBlocks } from \"../code-highlight\";\nimport { SessionHeader } from \"../components/SessionHeader\";\nimport { formatBytes, formatTokens, renderMarkdown, sendRpc, warmAudioPlayback } from \"../helpers\";\nimport {\n\tclearPendingImages,\n\tgetPendingImages,\n\thasPendingImages,\n\tinitMediaDrop,\n\tteardownMediaDrop,\n} from \"../media-drop\";\nimport { bindModelComboEvents, setSessionModel } from \"../models\";\nimport { bindNodeComboEvents, fetchNodes, unbindNodeEvents } from \"../nodes-selector\";\nimport { bindReasoningToggle, unbindReasoningToggle } from \"../reasoning-toggle\";\nimport { registerPrefix, sessionPath } from \"../router\";\nimport { routes } from \"../routes\";\nimport { bindSandboxImageEvents, bindSandboxToggleEvents, updateSandboxImageUI, updateSandboxUI } from \"../sandbox\";\nimport {\n\tbumpSessionCount,\n\tcacheOutgoingUserMessage,\n\tclearActiveSession,\n\tclearAllSessions,\n\tseedSessionPreviewFromUserText,\n\tsetSessionActiveRunId,\n\tsetSessionReplying,\n\tswitchSession,\n} from \"../sessions\";\nimport * as S from \"../state\";\nimport { modelStore } from \"../stores/model-store\";\nimport { sessionStore } from \"../stores/session-store\";\nimport { initVoiceInput, teardownVoiceInput } from \"../voice-input\";\n\n// ── Types ───────────────────────────────────────────────────\n\ninterface SlashCommand {\n\tname: string;\n\tdescription: string;\n}\n\ninterface ParsedSlash {\n\tname: string;\n\targs: string;\n}\n\ninterface ContextData {\n\tsession?: Record<string, unknown>;\n\tproject?: Record<string, unknown> | null;\n\ttools?: Array<{ name: string; description?: string }>;\n\tskills?: Array<{ name: string; description?: string; source?: string }>;\n\tmcpServers?: Array<{ name: string; state?: string; tool_count?: number }>;\n\tmcpDisabled?: boolean;\n\tsandbox?: Record<string, unknown>;\n\texecution?: Record<string, unknown>;\n\ttokenUsage?: Record<string, number>;\n\tpromptMemory?: PromptMemoryData | null;\n\tsupportsTools?: boolean;\n}\n\ninterface PromptMemoryData {\n\tmode?: string;\n\tpresent?: boolean;\n\tchars?: number;\n\tfileSource?: string;\n\tpath?: string;\n\tsnapshotActive?: boolean;\n}\n\ninterface CompactCardData {\n\tmode?: string;\n\tmessageCount?: number;\n\ttotalTokens?: number;\n\testimatedNextInputTokens?: number;\n\tcontextWindow?: number;\n\tcompactionTotalTokens?: number;\n\tcompactionInputTokens?: number;\n\tcompactionOutputTokens?: number;\n\tsettingsHint?: string;\n}\n\ninterface ModelNotice {\n\tid: string;\n\tdisplayName?: string;\n\tprovider?: string;\n\tsupportsTools?: boolean;\n}\n\ninterface ContextMessage {\n\