sName=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\tWith DM policy on allowlist, unknown users get a 6-digit PIN challenge by default.\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Room Policy</label>\n\t\t\t\t\t\t<select\n\t\t\t\t\t\t\tdata-field=\"roomPolicy\"\n\t\t\t\t\t\t\tclassName=\"channel-select\"\n\t\t\t\t\t\t\tvalue={(cfg.room_policy as string) || \"allowlist\"}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t<option value=\"allowlist\">Room allowlist only</option>\n\t\t\t\t\t\t\t<option value=\"open\">Open (any joined room)</option>\n\t\t\t\t\t\t\t<option value=\"disabled\">Disabled</option>\n\t\t\t\t\t\t</select>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Invite Auto-Join</label>\n\t\t\t\t\t\t<select data-field=\"autoJoin\" className=\"channel-select\" value={(cfg.auto_join as string) || \"always\"}>\n\t\t\t\t\t\t\t<option value=\"always\">Always join invites</option>\n\t\t\t\t\t\t\t<option value=\"allowlist\">Only when inviter or room is allowlisted</option>\n\t\t\t\t\t\t\t<option value=\"off\">Do not auto-join</option>\n\t\t\t\t\t\t</select>\n\t\t\t\t\t</>\n\t\t\t\t)}\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Default Model</label>\n\t\t\t\t<ModelSelect\n\t\t\t\t\tmodels={modelsSig.value}\n\t\t\t\t\tvalue={editModel.value}\n\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\teditModel.value = v;\n\t\t\t\t\t}}\n\t\t\t\t\tplaceholder={defaultPlaceholder}\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">DM Allowlist</label>\n\t\t\t\t<AllowlistInput\n\t\t\t\t\tvalue={allowlistItems.value}\n\t\t\t\t\tpreserveAt={isMatrix}\n\t\t\t\t\tonChange={(v) => {\n\t\t\t\t\t\tallowlistItems.value = v;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t{isMatrix && (\n\t\t\t\t\t<>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Room Allowlist</label>\n\t\t\t\t\t\t<AllowlistInput\n\t\t\t\t\t\t\tvalue={roomAllowlistItems.value}\n\t\t\t\t\t\t\tpreserveAt={true}\n\t\t\t\t\t\t\tonChange={(v) => {\n\t\t\t\t\t\t\t\troomAllowlistItems.value = v;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</>\n\t\t\t\t)}\n\t\t\t\t<AdvancedConfigPatchField\n\t\t\t\t\tvalue={editAdvancedConfigPatch.value}\n\t\t\t\t\tonInput={(value) => {\n\t\t\t\t\t\teditAdvancedConfigPatch.value = value;\n\t\t\t\t\t}}\n\t\t\t\t\tcurrentConfig={cfg}\n\t\t\t\t/>\n\t\t\t\t{error.value && <div className=\"text-xs text-[var(--error)] py-1\">{error.value}</div>}\n\t\t\t\t<button className=\"provider-btn\" onClick={onSave} disabled={saving.value}>\n\t\t\t\t\t{saving.value ? \"Saving\\u2026\" : \"Save Changes\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</Modal>\n\t);\n}\n\n// ── Channel event handlers ───────────────────────────────────\n\nfunction handleWhatsAppPairingEvent(p: ChannelEvent): void {\n\tif (p.kind === \"pairing_qr_code\" && p.account_id === waPairingAccountId.value) {\n\t\twaQrData.value = p.qr_data || null;\n\t\twaQrSvg.value = p.qr_svg || null;\n\t}\n\tif (p.kind === \"pairing_complete\" && p.account_id === waPairingAccountId.value) {\n\t\tshowToast(\"WhatsApp connected!\");\n\t\tshowAddWhatsApp.value = false;\n\t\twaPairingAccountId.value = null;\n\t\twaQrData.value = null;\n\t\twaQrSvg.value = null;\n\t\tloadChannels();\n\t}\n\tif (p.kind === \"pairing_failed\" && p.account_id === waPairingAccountId.value) {\n\t\twaPairingError.value = p.reason || \"Pairing failed\";\n\t}\n}\n\nfunction handleChannelEvent(_payload: unknown): void {\n\tconst p = _payload as ChannelEvent;\n\tif (p.kind === \"otp_resolved\") {\n\t\tloadChannels();\n\t}\n\thandleWhatsAppPairingEvent(p);\n\tif (p.kind === \"pairing_complete\" || p.kind === \"account_disabled\") {\n\t\tloadChannels();\n\t}\n\tconst selected = parseSenderSelectionKey(sendersAccount.value || \"\");\n\tif (\n\t\tactiveTab.value === \"senders\" &&\n\t\tselected.account_id === p.account_id &&\n\t\tselected.type === channelType(p.channel_type) &&\n\t\t(p.kind === \"inbound_message\" || p.kind === \"otp_challenge\" || p.kind === \"otp_resolved\")\n\t) {\n\t\tloadSenders();\n\t}\n}\n\n// ── Main page component ──────────────────────────────────────\n\nfunction ChannelsPageComponent(): VNode {\n\tuseEffect(() => {\n\t\tS.setRefreshChannelsPage(loadChannels);\n\t\t// Use prefetched cache for instant render\n\t\tif (S.cachedChannels !== null) channels.value = S.cachedChannels as Channel[];\n\t\tif (connected.value) loadChannels();\n\n\t\tconst unsub = onEvent(\"channel\", handleChannelEvent);\n\t\tS.setChannelEventUnsub(unsub);\n\n\t\treturn () => {\n\t\t\tS.setRefreshChannelsPage(null);\n\t\t\tif (unsub) unsub();\n\t\t\tS.setChannelEventUnsub(null);\n\t\t};\n\t}, [connected.value]);\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<div className=\"flex items-center gap-3 flex-wrap\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Channels</h2>\n\t\t\t\t<div style={{ display: \"flex\", gap: \"4px\", marginLeft: \"12px\" }}>\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"session-action-btn\"\n\t\t\t\t\t\tstyle={activeTab.value === \"channels\" ? { fontWeight: 600 } : undefined}\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tactiveTab.value = \"channels\";\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\tChannels\n\t\t\t\t\t</button>\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"session-action-btn\"\n\t\t\t\t\t\tstyle={activeTab.value === \"senders\" ? { fontWeight: 600 } : undefined}\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tactiveTab.value = \"senders\";\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\tSenders\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t\t{activeTab.value === \"channels\" && channels.value.length > 0 && <ConnectButtons />}\n\t\t\t</div>\n\t\t\t{activeTab.value === \"channels\" && <ChannelStorageNotice />}\n\t\t\t{activeTab.value === \"channels\" ? <ChannelsTab /> : <SendersTab />}\n\t\t\t<AddTelegramModal />\n\t\t\t<AddTeamsModal />\n\t\t\t<AddDiscordModal />\n\t\t\t<AddSlackModal />\n\t\t\t<AddMatrixModal />\n\t\t\t<AddNostrModal />\n\t\t\t<AddWhatsAppModal />\n\t\t\t<EditChannelModal />\n\t\t\t<ConfirmDialog />\n\t\t</div>\n\t);\n}\n\n// ── Mount / unmount exports ──────────────────────────────────\n\nlet _channelsContainer: HTMLElement | null = null;\n\nexport function initChannels(container: HTMLElement): void {\n\t_channelsContainer = container;\n\tcontainer.style.cssText = \"flex-direction:column;padding:0;overflow:hidden;\";\n\tactiveTab.value = \"channels\";\n\tshowAddTelegram.value = false;\n\tshowAddTeams.value = false;\n\tshowAddDiscord.value = false;\n\tshowAddSlack.value = false;\n\tshowAddMatrix.value = false;\n\tshowAddNostr.value = false;\n\tshowAddWhatsApp.value = false;\n\teditingChannel.value = null;\n\tsendersAccount.value = \"\";\n\tsenders.value = [];\n\trender(<ChannelsPageComponent />, container);\n}\n\nexport function teardownChannels(): void {\n\tS.setRefreshChannelsPage(null);\n\tif (S.channelEventUnsub) {\n\t\tS.channelEventUnsub();\n\t\tS.setChannelEventUnsub(null);\n\t}\n\tif (_channelsContainer) render(null, _channelsContainer);\n\t_channelsContainer = null;\n}\n","// ── WebSocket ─────────────────────────────────────────────────\n\nimport {\n\tappendChannelFooter,\n\tappendReasoningDisclosure,\n\tchatAddErrorCard,\n\tchatAddErrorMsg,\n\tchatAddMsg,\n\tremoveThinking,\n\trenderApprovalCard,\n\tstripChannelPrefix,\n\tupdateTokenBar,\n} from \"./chat-ui\";\nimport { highlightCodeBlocks } from \"./code-highlight\";\nimport { eventListeners } from \"./events\";\nimport {\n\tformatAssistantTokenUsage,\n\tformatTokenSpeed,\n\tlocalizeStructuredError,\n\trenderAudioPlayer,\n\trenderDocument,\n\trenderMapLinks,\n\trenderMapPointGroups,\n\trenderMarkdown,\n\trenderScreenshot,\n\tsendRpc,\n\ttokenSpeedTone,\n\ttoolCallSummary,\n} from \"./helpers\";\nimport { t } from \"./i18n\";\nimport { clearLogsAlert, updateLogsAlert } from \"./logs-alert\";\nimport { attachMessageVoiceControl } from \"./message-voice\";\nimport { fetchModels } from \"./models\";\nimport { prefetchChannels } from \"./pages/ChannelsPage\";\nimport { maybeRefreshFullContext, renderCompactCard } from \"./pages/ChatPage\";\nimport { fetchProjects } from \"./projects\";\nimport { currentPage, currentPrefix, mount, navigate } from \"./router\";\nimport {\n\tappendLastMessageTimestamp,\n\tbumpSessionCount,\n\tcacheSessionHistoryMessage,\n\tclearSessionHistoryCache,\n\tfetchSessions,\n\tmarkSessionLocallyCleared,\n\tsetSessionActiveRunId,\n\tsetSessionReplying,\n\tsetSessionUnread,\n} from \"./sessions\";\nimport * as S from \"./state\";\nimport { sessionStore } from \"./stores/session-store\";\nimport type { ConnectOptions } from \"./ws-connect\";\nimport { connectWs, forceReconnect, subscribeEvents } from \"./ws-connect\";\n\n// ── Payload / event interfaces ──────────────────────────────\n\ninterface ToolCallPayload {\n\trunId?: string;\n\ttoolCallId?: string;\n\ttoolName?: string;\n\targuments?: Record<string, unknown>;\n\texecutionMode?: string;\n\tmessageIndex?: number;\n\tsessionKey?: string;\n\tsuccess?: boolean;\n\tresult?: ToolResult;\n\terror?: ToolError;\n}\n\ninterface ToolResult {\n\tstdout?: string;\n\tstderr?: string;\n\texit_code?: number;\n\tscreenshot?: string;\n\tscreenshot_scale?: number;\n\tdocument_ref?: string;\n\tfilename?: string;\n\tmime_type?: string;\n\tsize_bytes?: number;\n\tpoints?: MapPoint[];\n\tlabel?: string;\n\tmap_links?: MapLinks;\n}\n\ninterface ToolError {\n\tdetail?: string;\n\tmessage?: string;\n\tretryAfterMs?: number;\n\ttype?: string;\n}\n\ninterface MapLinks {\n\turl?: string;\n\tgoogle_maps?: string;\n\tapple_maps?: string;\n\topenstreetmap?: string;\n\t[key: string]: unknown;\n}\n\ninterface MapPoint {\n\tlabel?: string;\n\tlatitude?: number;\n\tlongitude?: number;\n\tmap_links?: MapLinks;\n}\n\ninterface ChatPayload {\n\tstate?: string;\n\tsessionKey?: string;\n\trunId?: string;\n\ttext?: string;\n\tmodel?: string;\n\tprovider?: string;\n\tinputTokens?: number;\n\toutputTokens?: number;\n\tcacheReadTokens?: number;\n\tcacheWriteTokens?: number;\n\tdurationMs?: number;\n\trequestInputTokens?: number;\n\trequestOutputTokens?: number;\n\trequestCacheReadTokens?: number;\n\trequestCacheWriteTokens?: number;\n\treasoning?: string;\n\taudio?: string;\n\taudioWarning?: string | null;\n\treplyMedium?: string;\n\tmessageIndex?: number;\n\ttoolCallId?: string;\n\ttoolName?: string;\n\targuments?: Record<string, unknown>;\n\texecutionMode?: string;\n\tsuccess?: boolean;\n\tresult?: ToolResult;\n\terror?: ChatError;\n\tmessage?: string;\n\tchannel?: ChannelInfo;\n\ttitle?: string;\n\tphase?: string;\n\tmode?: string;\n\tseq?: number;\n\tretryAfterMs?: number;\n\tpartialMessage?: PartialMessage;\n\tcanContinue?: boolean;\n}\n\ninterface ChatError {\n\ttitle?: string;\n\tdetail?: string;\n\tmessage?: string;\n\ttype?: string;\n\tretryAfterMs?: number;\n\tcanContinue?: boolean;\n}\n\ninterface ChannelInfo {\n\taudio_filename?: string;\n\t[key: string]: unknown;\n}\n\ninterface PartialMessage {\n\tcontent?: string;\n\treasoning?: string;\n\tmodel?: string;\n\tprovider?: string;\n\tinputTokens?: number;\n\toutputTokens?: number;\n\tdurationMs?: number;\n\trequestInputTokens?: number;\n\trequestOutputTokens?: number;\n\trequestCacheReadTokens?: number;\n\trequestCacheWriteTokens?: number;\n\taudio?: string;\n\trun_id?: string;\n\tcreated_at?: number;\n}\n\ninterface CompactPayload {\n\tsessionKey?: string;\n\tphase?: string;\n\terror?: string;\n\tmode?: string;\n\t[key: string]: unknown;\n}\n\ninterface ApprovalPayload {\n\trequestId: string;\n\tcommand: string;\n}\n\ninterface LogEntryPayload {\n\tlevel?: string;\n\t[key: string]: unknown;\n}\n\ninterface SandboxPhasePayload {\n\tphase?: string;\n\terror?: string;\n\ttag?: string;\n\tbuilt?: boolean;\n\tcount?: number;\n\tinstalled?: number;\n\tskipped?: number;\n\timage?: string;\n}\n\ninterface LocalLlmDownloadPayload {\n\tdisplayName?: string;\n\tmodelId?: string;\n\terror?: string;\n\tcomplete?: boolean;\n\tprogress?: number;\n\tdownloaded?: number;\n\ttotal?: number;\n}\n\ninterface ModelsUpdatedPayload {\n\tphase?: string;\n\t[key: string]: unknown;\n}\n\ninterface WsErrorPayload {\n\tmessage?: string;\n}\n\ninterface LocationRequestPayload {\n\trequestId?: string;\n\tprecision?: string;\n}\n\ninterface AuthCredentialsPayload {\n\treason?: string;\n}\n\ninterface WsFrame {\n\ttype: string;\n\tevent?: string;\n\tpayload?: Record<string, unknown>;\n\tstream?: unknown;\n\tdone?: unknown;\n\tchannel?: unknown;\n}\n\ninterface StreamMeta {\n\tstream: unknown;\n\tdone: unknown;\n\tchannel: unknown;\n}\n\ninterface AbortedPartialState {\n\tpartial: PartialMessage | null;\n\tpartialText: string;\n\tpartialReasoning: string;\n\thasVisiblePartial: boolean;\n}\n\ntype ChatHandler = (p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string) => void;\n\n// Extend Window for moltis-specific global\ndeclare global {\n\tinterface Window {\n\t\t__moltisSuppressNextPasswordChangedRedirect?: boolean;\n\t}\n}\n\n// ── Chat event handlers ──────────────────────────────────────\n\nconst pendingToolCallEnds: Map<string, ToolCallPayload> = new Map();\nlet hasConnectedOnce = false;\n\nfunction clearChatEmptyState(): void {\n\tif (!S.chatMsgBox) return;\n\tconst welcome = S.chatMsgBox.querySelector(\"#welcomeCard\");\n\tif (welcome) welcome.remove();\n\tconst noProviders = S.chatMsgBox.querySelector(\"#noProvidersCard\");\n\tif (noProviders) noProviders.remove();\n\tS.chatMsgBox.classList.remove(\"chat-messages-empty\");\n}\n\nfunction toolCallLogicalId(payload: ToolCallPayload | null | undefined): string {\n\tif (!payload) return \"\";\n\tif (payload.runId) return `${payload.runId}:${payload.toolCallId}`;\n\treturn String(payload.toolCallId || \"\");\n}\n\nfunction toolCallCardId(payload: ToolCallPayload | ChatPayload | null | undefined): string {\n\tif ((payload as ToolCallPayload)?.runId) {\n\t\treturn `tool-${(payload as ToolCallPayload).runId}-${(payload as ToolCallPayload).toolCallId}`;\n\t}\n\treturn `tool-${(payload as ToolCallPayload)?.toolCallId}`;\n}\n\nfunction toolCallEventKey(eventSession: string, payload: ToolCallPayload | ChatPayload | null | undefined): string {\n\treturn `${eventSession}:${toolCallLogicalId(payload as ToolCallPayload)}`;\n}\n\nfunction clearPendingToolCallEndsForSession(sessionKey: string): void {\n\tconst prefix = `${sessionKey}:`;\n\tfor (const key of pendingToolCallEnds.keys()) {\n\t\tif (key.startsWith(prefix)) {\n\t\t\tpendingToolCallEnds.delete(key);\n\t\t}\n\t}\n}\n\nfunction makeThinkingDots(): Element {\n\tconst tpl = document.getElementById(\"tpl-thinking-dots\") as HTMLTemplateElement;\n\treturn (tpl.content.cloneNode(true) as DocumentFragment).firstElementChild!;\n}\n\nfunction updateSessionRunId(sessionKey: string, runId: string | undefined): void {\n\tif (!runId) return;\n\tsetSessionActiveRunId(sessionKey, runId);\n}\n\nfunction updateSessionHistoryIndex(sessionKey: string, messageIndex: number | undefined): void {\n\tconst idx = Number(messageIndex);\n\tif (!Number.isInteger(idx) || idx < 0) return;\n\tconst session = sessionStore.getByKey(sessionKey);\n\tif (session && idx > session.lastHistoryIndex.value) {\n\t\tsession.lastHistoryIndex.value = idx;\n\t}\n\tif (sessionKey === sessionStore.activeSessionKey.value && idx > S.lastHistoryIndex) {\n\t\tS.setLastHistoryIndex(idx);\n\t}\n}\n\nfunction moveFirstQueuedToChat(): void {\n\tconst tray = document.getElementById(\"queuedMessages\");\n\tif (!tray) return;\n\tconst firstQueued = tray.querySelector(\".msg.user.queued\");\n\tif (!firstQueued) return;\n\tconsole.debug(\"[queued] moving queued message from tray to chat\", {\n\t\tremaining: tray.querySelectorAll(\".msg\").length - 1,\n\t});\n\tfirstQueued.classList.remove(\"queued\");\n\tconst badge = firstQueued.querySelector(\".queued-badge\");\n\tif (badge) badge.remove();\n\tclearChatEmptyState();\n\tS.chatMsgBox!.appendChild(firstQueued);\n\tif (!tray.querySelector(\".msg\")) tray.classList.add(\"hidden\");\n}\n\nfunction makeThinkingStopBtn(sessionKey: string): HTMLButtonElement {\n\tconst btn = document.createElement(\"button\");\n\tbtn.className = \"thinking-stop-btn\";\n\tbtn.type = \"button\";\n\tbtn.title = \"Stop generation\";\n\tbtn.textContent = \"Stop\";\n\tbtn.addEventListener(\"click\", () => {\n\t\tbtn.disabled = true;\n\t\tbtn.textContent = \"Stopping\\u2026\";\n\t\tsendRpc(\"chat.abort\", { sessionKey }).catch(() => undefined);\n\t});\n\treturn btn;\n}\n\nfunction handleChatThinking(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tupdateSessionRunId(eventSession, p.runId);\n\tsetSessionReplying(eventSession, true);\n\tif (!(isActive && isChatPage)) return;\n\tremoveThinking();\n\tclearChatEmptyState();\n\tconst thinkEl = document.createElement(\"div\");\n\tthinkEl.className = \"msg assistant thinking\";\n\tthinkEl.id = \"thinkingIndicator\";\n\tthinkEl.appendChild(makeThinkingDots());\n\tthinkEl.appendChild(makeThinkingStopBtn(eventSession));\n\tS.chatMsgBox!.appendChild(thinkEl);\n\tS.chatMsgBox!.scrollTop = S.chatMsgBox!.scrollHeight;\n}\n\nfunction handleChatThinkingText(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tupdateSessionRunId(eventSession, p.runId);\n\tsetSessionReplying(eventSession, true);\n\tif (!(isActive && isChatPage)) return;\n\tconst indicator = document.getElementById(\"thinkingIndicator\");\n\tif (indicator) {\n\t\tconst existingBtn = indicator.querySelector(\".thinking-stop-btn\");\n\t\twhile (indicator.firstChild) indicator.removeChild(indicator.firstChild);\n\t\tconst textEl = document.createElement(\"span\");\n\t\ttextEl.className = \"thinking-text\";\n\t\ttextEl.textContent = p.text || \"\";\n\t\tindicator.appendChild(textEl);\n\t\tindicator.appendChild(existingBtn || makeThinkingStopBtn(eventSession));\n\t\tS.chatMsgBox!.scrollTop = S.chatMsgBox!.scrollHeight;\n\t}\n}\n\nfunction handleChatThinkingDone(_p: ChatPayload, isActive: boolean, isChatPage: boolean): void {\n\t// Don't remove the thinking indicator here. It will be removed by either:\n\t// - handleChatDelta (when text starts streaming)\n\t// - handleChatToolCallStart (which preserves thinking text as a disclosure)\n\t// - handleChatFinal / handleChatError (cleanup)\n\t// This keeps the thinking text visible until we know whether to preserve it.\n\tvoid (isActive && isChatPage);\n}\n\nfunction handleChatVoicePending(_p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\t// Update per-session signal\n\tconst session = sessionStore.getByKey(eventSession);\n\tif (session) session.voicePending.value = true;\n\tif (!(isActive && isChatPage)) return;\n\t// Dual-write to global state for backward compat\n\tS.setVoicePending(true);\n\t// Keep the existing thinking dots visible — no separate voice indicator.\n}\n\n/** Check whether a reasoning disclosure with the given text already exists in\n * the chat box (from a previous preserveThinkingAsDisclosure call). */\nfunction isReasoningAlreadyShown(text: string | null | undefined): boolean {\n\tif (!(S.chatMsgBox && text)) return false;\n\tconst normalized = text.trim();\n\tfor (const el of S.chatMsgBox.querySelectorAll(\".msg-reasoning-body\")) {\n\t\tif (el.textContent?.trim() === normalized) return true;\n\t}\n\treturn false;\n}\n\n/** Extract thinking text from the indicator before it is removed. Returns the\n * trimmed text or null if the indicator has no thinking content. */\nfunction extractThinkingText(): string | null {\n\tconst indicator = document.getElementById(\"thinkingIndicator\");\n\tif (!indicator) return null;\n\tconst textEl = indicator.querySelector(\".thinking-text\");\n\tconst text = textEl?.textContent?.trim();\n\treturn text || null;\n}\n\nfunction handleChatToolCallStart(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tupdateSessionRunId(eventSession, p.runId);\n\t// Update per-session signal\n\tconst session = sessionStore.getByKey(eventSession);\n\tif (session) session.streamText.value = \"\";\n\tif (!(isActive && isChatPage)) return;\n\tconst thinkingText = extractThinkingText();\n\tremoveThinking();\n\t// Close the current streaming element so new text deltas after this tool\n\t// call will create a fresh element positioned after the tool card\n\tif (S.streamEl) {\n\t\t// Remove the element if it's empty (e.g. only whitespace from a\n\t\t// pre-tool-call delta) to avoid leaving an orphaned empty div.\n\t\tif (!S.streamEl.textContent?.trim()) {\n\t\t\tS.streamEl.remove();\n\t\t}\n\t\tS.setStreamEl(null);\n\t\tS.setStreamText(\"\");\n\t}\n\tconst cardId = toolCallCardId(p);\n\tif (document.getElementById(cardId)) return;\n\tconst tpl = document.getElementById(\"tpl-exec-card\") as HTMLTemplateElement;\n\tconst frag = tpl.content.cloneNode(true) as DocumentFragment;\n\tconst card = frag.firstElementChild as HTMLElement;\n\tcard.id = cardId;\n\tconst cmd = toolCallSummary(p.toolName, p.arguments, p.executionMode);\n\tconst cmdEl = card.querySelector(\"[data-cmd]\");\n\tif (cmdEl) cmdEl.textContent = ` ${cmd}`;\n\t// Preserve thinking text as a reasoning disclosure inside the tool card\n\tif (thinkingText) appendReasoningDisclosure(card, thinkingText);\n\tclearChatEmptyState();\n\tS.chatMsgBox!.appendChild(card);\n\tconst endKey = toolCallEventKey(eventSession, p);\n\tconst pendingEnd = pendingToolCallEnds.get(endKey);\n\tif (pendingEnd) {\n\t\tpendingToolCallEnds.delete(endKey);\n\t\tcompleteToolCard(card, pendingEnd as ChatPayload, eventSession);\n\t}\n\tS.chatMsgBox!.scrollTop = S.chatMsgBox!.scrollHeight;\n}\n\nfunction appendToolResult(toolCard: HTMLElement, result: ToolResult, eventSession: string): void {\n\tconst out = (result.stdout || \"\").replace(/\\n+$/, \"\");\n\t// Update per-session signal\n\tconst toolSession = sessionStore.getByKey(eventSession);\n\tif (toolSession) toolSession.lastToolOutput.value = out;\n\t// Dual-write to global state for backward compat\n\tS.setLastToolOutput(out);\n\tif (out) {\n\t\tconst outEl = document.createElement(\"pre\");\n\t\toutEl.className = \"exec-output\";\n\t\toutEl.textContent = out;\n\t\ttoolCard.appendChild(outEl);\n\t}\n\tconst stderrText = (result.stderr || \"\").replace(/\\n+$/, \"\");\n\tif (stderrText) {\n\t\tconst errEl = document.createElement(\"pre\");\n\t\terrEl.className = \"exec-output exec-stderr\";\n\t\terrEl.textContent = stderrText;\n\t\ttoolCard.appendChild(errEl);\n\t}\n\tif (result.exit_code !== undefined && result.exit_code !== 0) {\n\t\tconst codeEl = document.createElement(\"div\");\n\t\tcodeEl.className = \"exec-exit\";\n\t\tcodeEl.textContent = `exit ${result.exit_code}`;\n\t\ttoolCard.appendChild(codeEl);\n\t}\n\t// Browser screenshot support - display as thumbnail with lightbox and download\n\tif (result.screenshot) {\n\t\tconst imgSrc = result.screenshot.startsWith(\"data:\")\n\t\t\t? result.screenshot\n\t\t\t: `data:image/png;base64,${result.screenshot}`;\n\t\trenderScreenshot(toolCard, imgSrc, result.screenshot_scale || 1);\n\t}\n\t// Document card (send_document tool)\n\tif (result.document_ref) {\n\t\tconst docStoredName = result.document_ref.split(\"/\").pop() || \"\";\n\t\tconst docDisplayName = result.filename || docStoredName;\n\t\tconst docSessionKey = eventSession || S.activeSessionKey || \"main\";\n\t\tconst docMediaSrc = `/api/sessions/${encodeURIComponent(docSessionKey)}/media/${encodeURIComponent(docStoredName)}`;\n\t\trenderDocument(toolCard, docMediaSrc, docDisplayName, result.mime_type, result.size_bytes);\n\t}\n\t// Map link buttons (show_map tool)\n\tconst renderedPointGroups = renderMapPointGroups(toolCard, result.points, result.label);\n\tif (!renderedPointGroups && result.map_links) {\n\t\trenderMapLinks(toolCard, result.map_links, result.label);\n\t}\n}\n\nfunction isToolValidationErrorPayload(p: ChatPayload): boolean {\n\tif (!(p && !p.success && p.error && p.error.detail)) return false;\n\tconst errDetail = p.error.detail.toLowerCase();\n\treturn (\n\t\terrDetail.includes(\"missing field\") ||\n\t\terrDetail.includes(\"missing required\") ||\n\t\terrDetail.includes(\"missing 'action'\") ||\n\t\terrDetail.includes(\"missing 'url'\")\n\t);\n}\n\nfunction completeToolCard(toolCard: HTMLElement, p: ChatPayload, eventSession: string): void {\n\t// Use muted \"retry\" style for validation errors, normal styles otherwise.\n\tif (isToolValidationErrorPayload(p)) {\n\t\ttoolCard.className = \"msg exec-card exec-retry\";\n\t} else {\n\t\ttoolCard.className = `msg exec-card ${p.success ? \"exec-ok\" : \"exec-err\"}`;\n\t}\n\n\tconst toolSpin = toolCard.querySelector(\".exec-status\");\n\tif (toolSpin) toolSpin.remove();\n\n\tif (p.success && p.result) {\n\t\tappendToolResult(toolCard, p.result, eventSession);\n\t\treturn;\n\t}\n\tif (!p.success && p.error && p.error.detail) {\n\t\tconst errMsg = document.createElement(\"div\");\n\t\terrMsg.className = isToolValidationErrorPayload(p) ? \"exec-retry-detail\" : \"exec-error-detail\";\n\t\terrMsg.textContent = p.error.detail;\n\t\ttoolCard.appendChild(errMsg);\n\t}\n\t// Show a hint below the card when a skill is created or updated.\n\tif (p.success && (p.toolName === \"create_skill\" || p.toolName === \"update_skill\")) {\n\t\tconst hint = document.createElement(\"div\");\n\t\thint.className = \"skill-hint\";\n\t\tconst verb = p.toolName === \"create_skill\" ? \"created\" : \"updated\";\n\t\tconst link = document.createElement(\"a\");\n\t\tlink.href = \"/skills\";\n\t\tlink.textContent = \"personal skills\";\n\t\tlink.addEventListener(\"click\", (e: MouseEvent) => {\n\t\t\te.preventDefault();\n\t\t\tnavigate(\"/skills\");\n\t\t});\n\t\thint.append(`Skill ${verb} \\u2014 available in your `, link);\n\t\ttoolCard.appendChild(hint);\n\t}\n}\n\nfunction clearStaleRunningToolCards(): void {\n\tif (!S.chatMsgBox) return;\n\tconst statusEls = S.chatMsgBox.querySelectorAll(\".msg.exec-card .exec-status\");\n\tfor (const statusEl of statusEls) {\n\t\tconst card = statusEl.closest(\".msg.exec-card\") as HTMLElement | null;\n\t\tstatusEl.remove();\n\t\tif (!card) continue;\n\t\tif (!(card.classList.contains(\"exec-ok\") || card.classList.contains(\"exec-err\"))) {\n\t\t\tcard.className = \"msg exec-card exec-ok\";\n\t\t}\n\t}\n}\n\nfunction handleChatToolCallEnd(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tupdateSessionRunId(eventSession, p.runId);\n\t// Always bump badge — the server persists both the hidden assistant\n\t// tool-call frame and the visible tool_result for each completed call.\n\tbumpSessionCount(eventSession, 2);\n\tlet toolHistoryIndex: number | undefined | null = p.messageIndex;\n\tif (toolHistoryIndex === undefined || toolHistoryIndex === null) {\n\t\tconst toolSession = sessionStore.getByKey(eventSession);\n\t\tif (toolSession && typeof toolSession.messageCount === \"number\" && toolSession.messageCount > 0) {\n\t\t\ttoolHistoryIndex = toolSession.messageCount - 1;\n\t\t}\n\t}\n\tcacheSessionHistoryMessage(\n\t\teventSession,\n\t\t{\n\t\t\trole: \"tool_result\",\n\t\t\ttool_call_id: p.toolCallId || \"\",\n\t\t\ttool_name: p.toolName || \"\",\n\t\t\tsuccess: p.success === true,\n\t\t\tresult: p.result || null,\n\t\t\terror:\n\t\t\t\tp.error?.detail || p.error?.message || (typeof p.error === \"string\" ? (p.error as unknown as string) : null),\n\t\t\tcreated_at: Date.now(),\n\t\t},\n\t\ttoolHistoryIndex as number | undefined,\n\t);\n\tupdateSessionHistoryIndex(eventSession, toolHistoryIndex as number | undefined);\n\tif (!(isActive && isChatPage)) return;\n\tconst toolCard = document.getElementById(toolCallCardId(p));\n\tif (!toolCard) {\n\t\tpendingToolCallEnds.set(toolCallEventKey(eventSession, p), p as unknown as ToolCallPayload);\n\t\treturn;\n\t}\n\tcompleteToolCard(toolCard, p, eventSession);\n}\n\nfunction handleChatChannelUser(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\t// Always bump the badge so the total message count stays accurate,\n\t// even when the user is not on the chat page (e.g. Telegram messages).\n\tbumpSessionCount(eventSession, 1);\n\tconst cachedAudio = p.channel?.audio_filename\n\t\t? `media/${eventSession.replaceAll(\":\", \"_\")}/${p.channel.audio_filename}`\n\t\t: undefined;\n\tcacheSessionHistoryMessage(\n\t\teventSession,\n\t\t{\n\t\t\trole: \"user\",\n\t\t\tcontent: p.text || \"\",\n\t\t\tchannel: p.channel || null,\n\t\t\taudio: cachedAudio,\n\t\t\tcreated_at: Date.now(),\n\t\t},\n\t\tp.messageIndex,\n\t);\n\tif (!isActive) {\n\t\tsetSessionUnread(eventSession, true);\n\t}\n\tif (!(isChatPage && isActive)) {\n\t\tupdateSessionHistoryIndex(eventSession, p.messageIndex);\n\t\treturn;\n\t}\n\t// Compare against the per-session history index, not the global one,\n\t// to avoid skipping events when viewing a different session.\n\tconst chanSession = sessionStore.getByKey(p.sessionKey || S.activeSessionKey);\n\tconst chanLastIdx = chanSession ? chanSession.lastHistoryIndex.value : S.lastHistoryIndex;\n\tif (p.messageIndex !== undefined && p.messageIndex <= chanLastIdx) return;\n\tupdateSessionHistoryIndex(eventSession, p.messageIndex);\n\tconst cleanText = stripChannelPrefix(p.text || \"\");\n\tconst sessionKey = p.sessionKey || S.activeSessionKey;\n\tconst audioFilename = p.channel?.audio_filename;\n\tlet el: HTMLElement | null;\n\tif (audioFilename) {\n\t\tel = chatAddMsg(\"user\", \"\", true);\n\t\tif (el) {\n\t\t\tconst audioSrc = `/api/sessions/${encodeURIComponent(sessionKey)}/media/${encodeURIComponent(audioFilename)}`;\n\t\t\trenderAudioPlayer(el, audioSrc);\n\t\t\tif (cleanText) {\n\t\t\t\tconst textWrap = document.createElement(\"div\");\n\t\t\t\ttextWrap.className = \"mt-2\";\n\t\t\t\t// Safe: renderMarkdown calls esc() first — all user input is\n\t\t\t\t// HTML-escaped before formatting tags are applied.\n\t\t\t\ttextWrap.innerHTML = renderMarkdown(cleanText); // eslint-disable-line no-unsanitized/property\n\t\t\t\tel.appendChild(textWrap);\n\t\t\t}\n\t\t}\n\t} else {\n\t\tel = chatAddMsg(\"user\", renderMarkdown(cleanText), true);\n\t}\n\tif (el && p.channel) {\n\t\tappendChannelFooter(el, p.channel as unknown as Parameters<typeof appendChannelFooter>[1]);\n\t}\n}\n\n// Handle user messages broadcast by the backend after persisting a message\n// sent via the GraphQL API, mobile app, or any non-web-UI client.\n// The originating web client already rendered the message optimistically,\n// so we skip rendering when the broadcast's seq matches a seq this client\n// has already sent (seq <= S.chatSeq).\nfunction handleChatUserMessage(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\t// Suppress the echo for the originating client.\n\tif (p.seq !== undefined && p.seq !== null && p.seq <= S.chatSeq) return;\n\n\tbumpSessionCount(eventSession, 1);\n\tcacheSessionHistoryMessage(\n\t\teventSession,\n\t\t{\n\t\t\trole: \"user\",\n\t\t\tcontent: p.text || \"\",\n\t\t\tcreated_at: Date.now(),\n\t\t},\n\t\tp.messageIndex,\n\t);\n\tif (!isActive) {\n\t\tsetSessionUnread(eventSession, true);\n\t}\n\tif (!(isChatPage && isActive)) return;\n\t// Safe: renderMarkdown calls esc() first — all user input is\n\t// HTML-escaped before formatting tags are applied.\n\tchatAddMsg(\"user\", renderMarkdown(p.text || \"\"), true);\n}\n\n// Safe: renderMarkdown calls esc() first — all user input is HTML-escaped before\n// being passed to innerHTML. This is the standard rendering path for chat messages.\nfunction setSafeMarkdownHtml(el: HTMLElement, text: string): void {\n\tel.innerHTML = renderMarkdown(text); // eslint-disable-line no-unsanitized/property\n}\n\nfunction hasNonWhitespaceContent(text: string | null | undefined): boolean {\n\treturn String(text || \"\").trim().length > 0;\n}\n\nfunction handleChatDelta(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tupdateSessionRunId(eventSession, p.runId);\n\tif (!p.text) return;\n\t// Update per-session signal\n\tconst session = sessionStore.getByKey(eventSession);\n\tif (session) session.streamText.value += p.text;\n\tif (!(isActive && isChatPage)) return;\n\t// When voice is pending, accumulate text silently without rendering.\n\tif (S.voicePending) {\n\t\tS.setStreamText(S.streamText + p.text);\n\t\treturn;\n\t}\n\t// Skip leading whitespace before any real content has been streamed.\n\t// Some providers emit newlines between thinking and content; rendering\n\t// them would create an empty assistant div that lingers if a tool call\n\t// follows immediately.  We must check this BEFORE removeThinking() so\n\t// the thinking text is still available for handleChatToolCallStart to\n\t// extract into a reasoning disclosure on the tool card.\n\tif (!(S.streamEl || p.text.trim())) return;\n\tremoveThinking();\n\tif (!S.streamEl) {\n\t\tS.setStreamText(\"\");\n\t\tS.setStreamEl(document.createElement(\"div\"));\n\t\tS.streamEl!.className = \"msg assistant\";\n\t\tclearChatEmptyState();\n\t\tS.chatMsgBox!.appendChild(S.streamEl!);\n\t}\n\tS.setStreamText(S.streamText + p.text);\n\tsetSafeMarkdownHtml(S.streamEl!, S.streamText);\n\tS.chatMsgBox!.scrollTop = S.chatMsgBox!.scrollHeight;\n}\n\nfunction normalizeEchoComparable(text: string | null | undefined): string {\n\tif (!text) return \"\";\n\treturn text\n\t\t.replace(/```[a-zA-Z0-9_-]*\\n?/g, \"\")\n\t\t.replace(/```/g, \"\")\n\t\t.replace(/[`\\s]/g, \"\");\n}\n\nfunction isPureToolOutputEcho(finalText: string, toolOutput: string): boolean {\n\tconst finalComparable = normalizeEchoComparable(finalText);\n\tconst toolComparable = normalizeEchoComparable(toolOutput);\n\tif (!(finalComparable && toolComparable)) return false;\n\treturn finalComparable === toolComparable;\n}\n\nfunction resolveFinalMessageEl(p: ChatPayload): HTMLElement | null {\n\tconst finalText = String(p.text || \"\");\n\tconst hasFinalText = hasNonWhitespaceContent(finalText);\n\tconst isEcho = hasFinalText && isPureToolOutputEcho(finalText, S.lastToolOutput);\n\tif (!isEcho) {\n\t\tif (hasFinalText && S.streamEl) {\n\t\t\tsetSafeMarkdownHtml(S.streamEl, finalText);\n\t\t\treturn S.streamEl;\n\t\t}\n\t\tif (hasFinalText) return chatAddMsg(\"assistant\", renderMarkdown(finalText), true);\n\t\t// No text (silent reply) — remove any leftover stream element.\n\t\tif (S.streamEl) S.streamEl.remove();\n\t\treturn null;\n\t}\n\tif (S.streamEl) S.streamEl.remove();\n\treturn null;\n}\n\nfunction appendFinalFooter(msgEl: HTMLElement | null, p: ChatPayload, eventSession: string): void {\n\tif (!(msgEl && p.model)) return;\n\tconst footer = document.createElement(\"div\");\n\tfooter.className = \"msg-model-footer\";\n\tlet footerText = p.provider ? `${p.provider} / ${p.model}` : p.model;\n\tif (p.inputTokens || p.outputTokens) {\n\t\tfooterText += ` \\u00b7 ${formatAssistantTokenUsage(p.inputTokens, p.outputTokens, p.cacheReadTokens)}`;\n\t}\n\tconst textSpan = document.createElement(\"span\");\n\ttextSpan.textContent = footerText;\n\tfooter.appendChild(textSpan);\n\n\tconst speedLabel = formatTokenSpeed(p.outputTokens || 0, p.durationMs || 0);\n\tif (speedLabel) {\n\t\tconst speed = document.createElement(\"span\");\n\t\tspeed.className = \"msg-token-speed\";\n\t\tconst tone = tokenSpeedTone(p.outputTokens || 0, p.durationMs || 0);\n\t\tif (tone) speed.classList.add(`msg-token-speed-${tone}`);\n\t\tspeed.textContent = ` \\u00b7 ${speedLabel}`;\n\t\tfooter.appendChild(speed);\n\t}\n\n\tif (p.replyMedium === \"voice\" || p.replyMedium === \"text\") {\n\t\tconst badge = document.createElement(\"span\");\n\t\tbadge.className = \"reply-medium-badge\";\n\t\tbadge.textContent = p.replyMedium;\n\t\tfooter.appendChild(badge);\n\t}\n\tmsgEl.appendChild(footer);\n\n\tvoid attachMessageVoiceControl({\n\t\tmessageEl: msgEl,\n\t\tfooterEl: footer,\n\t\tsessionKey: p.sessionKey || eventSession || S.activeSessionKey,\n\t\ttext: p.text || \"\",\n\t\trunId: p.runId,\n\t\tmessageIndex: p.messageIndex,\n\t\taudioPath: p.audio || undefined,\n\t\taudioWarning: p.audioWarning || undefined,\n\t\tforceAction: p.replyMedium === \"voice\" && !p.audio,\n\t\tautoplayOnGenerate: true,\n\t});\n}\n\n// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Final message handling with audio/voice branching\nfunction handleChatFinal(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tclearPendingToolCallEndsForSession(eventSession);\n\tupdateSessionRunId(eventSession, p.runId);\n\t// Always bump badge — the server persists the final assistant message.\n\tbumpSessionCount(eventSession, 1);\n\tconst finalText = String(p.text || \"\");\n\tconst hasVisibleFinal =\n\t\thasNonWhitespaceContent(finalText) ||\n\t\thasNonWhitespaceContent(p.reasoning || \"\") ||\n\t\thasNonWhitespaceContent(p.audio || \"\");\n\tif (hasVisibleFinal) {\n\t\tcacheSessionHistoryMessage(\n\t\t\teventSession,\n\t\t\t{\n\t\t\t\trole: \"assistant\",\n\t\t\t\tcontent: finalText,\n\t\t\t\tmodel: p.model || \"\",\n\t\t\t\tprovider: p.provider || \"\",\n\t\t\t\tinputTokens: p.inputTokens || 0,\n\t\t\t\toutputTokens: p.outputTokens || 0,\n\t\t\t\tcacheReadTokens: p.cacheReadTokens || 0,\n\t\t\t\tcacheWriteTokens: p.cacheWriteTokens || 0,\n\t\t\t\tdurationMs: p.durationMs || 0,\n\t\t\t\trequestInputTokens: p.requestInputTokens,\n\t\t\t\trequestOutputTokens: p.requestOutputTokens,\n\t\t\t\trequestCacheReadTokens: p.requestCacheReadTokens,\n\t\t\t\trequestCacheWriteTokens: p.requestCacheWriteTokens,\n\t\t\t\treasoning: p.reasoning || undefined,\n\t\t\t\taudio: p.audio || undefined,\n\t\t\t\trun_id: p.runId || undefined,\n\t\t\t\tcreated_at: Date.now(),\n\t\t\t},\n\t\t\tp.messageIndex,\n\t\t);\n\t}\n\t// Compare against the per-session history index so cross-session\n\t// events aren't wrongly skipped by another session's index.\n\tconst evtSession = sessionStore.getByKey(eventSession);\n\tconst lastIdx = evtSession ? evtSession.lastHistoryIndex.value : S.lastHistoryIndex;\n\tif (p.messageIndex !== undefined && p.messageIndex <= lastIdx) {\n\t\tsetSessionReplying(eventSession, false);\n\t\tsetSessionActiveRunId(eventSession, null);\n\t\treturn;\n\t}\n\tupdateSessionHistoryIndex(eventSession, p.messageIndex);\n\tsetSessionReplying(eventSession, false);\n\tsetSessionActiveRunId(eventSession, null);\n\tif (!isActive) {\n\t\tsetSessionUnread(eventSession, true);\n\t}\n\tif (!(isActive && isChatPage)) {\n\t\tS.setVoicePending(false);\n\t\treturn;\n\t}\n\tremoveThinking();\n\tclearStaleRunningToolCards();\n\n\tif (S.voicePending && p.text && p.replyMedium === \"voice\") {\n\t\t// Voice pending path: we suppressed streaming, so render everything at once.\n\t\tconsole.debug(\"[audio] voice-pending path, audio:\", !!p.audio, \"text:\", p.text.substring(0, 40));\n\t\tconst msgEl = S.streamEl || document.createElement(\"div\");\n\t\tmsgEl.className = \"msg assistant\";\n\t\tmsgEl.textContent = \"\";\n\t\tif (!msgEl.parentNode) {\n\t\t\tclearChatEmptyState();\n\t\t\tS.chatMsgBox!.appendChild(msgEl);\n\t\t}\n\n\t\tif (p.audio) {\n\t\t\tconst filename = p.audio.split(\"/\").pop() || \"\";\n\t\t\tconst audioSrc = `/api/sessions/${encodeURIComponent(p.sessionKey || S.activeSessionKey)}/media/${encodeURIComponent(filename)}`;\n\t\t\tconsole.debug(\"[audio] rendering persisted audio:\", filename);\n\t\t\trenderAudioPlayer(msgEl, audioSrc, true);\n\t\t}\n\t\tif (hasNonWhitespaceContent(p.text)) {\n\t\t\t// Safe: renderMarkdown calls esc() first — all user input is HTML-escaped.\n\t\t\tconst textWrap = document.createElement(\"div\");\n\t\t\ttextWrap.className = \"mt-2\";\n\t\t\tsetSafeMarkdownHtml(textWrap, p.text);\n\t\t\tmsgEl.appendChild(textWrap);\n\t\t}\n\t\tif (p.reasoning && !isReasoningAlreadyShown(p.reasoning)) {\n\t\t\tappendReasoningDisclosure(msgEl, p.reasoning);\n\t\t}\n\t\tappendFinalFooter(msgEl, p, eventSession);\n\t\tS.chatMsgBox!.scrollTop = S.chatMsgBox!.scrollHeight;\n\t} else {\n\t\tlet resolvedEl = resolveFinalMessageEl(p);\n\t\tconst skipReasoning = p.reasoning && isReasoningAlreadyShown(p.reasoning);\n\t\tif (!resolvedEl && p.reasoning && !skipReasoning) {\n\t\t\tresolvedEl = chatAddMsg(\"assistant\", \"\", false);\n\t\t}\n\t\tif (resolvedEl && p.reasoning && !skipReasoning) {\n\t\t\tappendReasoningDisclosure(resolvedEl, p.reasoning);\n\t\t}\n\t\tif (resolvedEl && p.text && p.replyMedium === \"voice\") {\n\t\t\tconsole.debug(\n\t\t\t\t\"[audio] streamed path, audio:\",\n\t\t\t\t!!p.audio,\n\t\t\t\t\"voicePending:\",\n\t\t\t\tS.voicePending,\n\t\t\t\t\"text:\",\n\t\t\t\tp.text.substring(0, 40),\n\t\t\t);\n\t\t\tif (p.audio) {\n\t\t\t\tconst fn2 = p.audio.split(\"/\").pop() || \"\";\n\t\t\t\tconst src2 = `/api/sessions/${encodeURIComponent(p.sessionKey || S.activeSessionKey)}/media/${encodeURIComponent(fn2)}`;\n\t\t\t\tconsole.debug(\"[audio] rendering persisted audio (streamed):\", fn2);\n\t\t\t\tresolvedEl.textContent = \"\";\n\t\t\t\trenderAudioPlayer(resolvedEl, src2, true);\n\t\t\t\tappendFinalFooter(resolvedEl, p, eventSession);\n\t\t\t} else {\n\t\t\t\tconsole.debug(\"[audio] no persisted audio, showing voice fallback action\");\n\t\t\t\tappendFinalFooter(resolvedEl, p, eventSession);\n\t\t\t}\n\t\t} else {\n\t\t\t// Silent reply — attach footer to the last visible assistant element\n\t\t\t// (e.g. exec card). Never attach to a user message.\n\t\t\tlet target = resolvedEl;\n\t\t\tif (!target) {\n\t\t\t\tconst last = S.chatMsgBox?.lastElementChild as HTMLElement | null;\n\t\t\t\tif (last && !last.classList.contains(\"user\")) target = last;\n\t\t\t}\n\t\t\tappendFinalFooter(target, p, eventSession);\n\t\t}\n\t}\n\tif (p.inputTokens || p.outputTokens) {\n\t\tS.sessionTokens.input += p.inputTokens || 0;\n\t\tS.sessionTokens.output += p.outputTokens || 0;\n\t}\n\tif (p.requestInputTokens !== undefined && p.requestInputTokens !== null) {\n\t\tS.setSessionCurrentInputTokens(p.requestInputTokens || 0);\n\t} else if (p.inputTokens || p.outputTokens) {\n\t\tS.setSessionCurrentInputTokens(p.inputTokens || 0);\n\t}\n\tupdateTokenBar();\n\tappendLastMessageTimestamp(Date.now());\n\t// Reset per-session stream state\n\tconst finalSession = sessionStore.getByKey(eventSession);\n\tif (finalSession) finalSession.resetStreamState();\n\t// Dual-write to global state for backward compat\n\tS.setStreamEl(null);\n\tS.setStreamText(\"\");\n\tS.setLastToolOutput(\"\");\n\tS.setVoicePending(false);\n\tmaybeRefreshFullContext();\n\t// Syntax-highlight any code blocks in the completed message.\n\tif (S.chatMsgBox?.lastElementChild) {\n\t\thighlightCodeBlocks(S.chatMsgBox.lastElementChild as HTMLElement);\n\t}\n\t// Move the next queued message from the tray AFTER the response is\n\t// fully rendered. This ensures correct ordering: user-msg -> response ->\n\t// next-user-msg -> next-response (never next-user-msg before response).\n\tmoveFirstQueuedToChat();\n}\n\n// Shared debounce so the auto-compact path (which broadcasts both\n// `chat.compact done` from within ChatService::compact AND a wrapping\n// `auto_compact done` from the send() caller) renders the card exactly\n// once. Whichever event arrives first claims the render; the other is\n// a no-op within the debounce window.\nconst COMPACT_CARD_DEBOUNCE_MS = 500;\nconst lastCompactCardAt: Map<string, number> = new Map();\n\n// Per-session reference to the \"Compacting conversation...\" status message\n// appended on `auto_compact start`. Tracked explicitly (not via\n// `lastChild`) because `send()`'s pre-emptive auto-compact path\n// interleaves `chat.compact done` between `auto_compact start` and\n// `auto_compact done`, which means the old \"remove lastChild\" pattern\n// would remove the compact card instead of the status message.\n// Greptile P1 on commit 0531913b.\nconst compactingStatusElements: Map<string, HTMLElement> = new Map();\n\nfunction shouldRenderCompactCard(p: CompactPayload): boolean {\n\tconst key = p.sessionKey || \"__active__\";\n\tconst now = Date.now();\n\tconst previous = lastCompactCardAt.get(key) || 0;\n\tif (now - previous < COMPACT_CARD_DEBOUNCE_MS) {\n\t\treturn false;\n\t}\n\tlastCompactCardAt.set(key, now);\n\treturn true;\n}\n\n// Drop the \"Compacting conversation...\" status message the auto-compact\n// start phase appended for this session, if one exists. Called by both\n// compact-done handlers before rendering the card so the status message\n// never outlives its purpose, regardless of which event arrives first.\nfunction removeCompactingStatus(p: CompactPayload): void {\n\tconst key = p.sessionKey || \"__active__\";\n\tconst el = compactingStatusElements.get(key);\n\tcompactingStatusElements.delete(key);\n\tif (el && el.parentNode === S.chatMsgBox) {\n\t\tS.chatMsgBox!.removeChild(el);\n\t}\n}\n\nfunction resetTokensAfterCompaction(): void {\n\tS.setSessionTokens({ input: 0, output: 0 });\n\tS.setSessionCurrentInputTokens(0);\n\tupdateTokenBar();\n}\n\nfunction handleChatAutoCompact(p: ChatPayload, isActive: boolean, isChatPage: boolean): void {\n\tif (!(isActive && isChatPage)) return;\n\tif (p.phase === \"start\") {\n\t\tconst statusEl = chatAddMsg(\"system\", \"Compacting conversation (context limit reached)\\u2026\");\n\t\tconst key = p.sessionKey || \"__active__\";\n\t\tif (statusEl) {\n\t\t\tcompactingStatusElements.set(key, statusEl);\n\t\t}\n\t} else if (p.phase === \"done\") {\n\t\t// Always drop the status message — even when the card was\n\t\t// already rendered by an earlier `chat.compact done` event.\n\t\tremoveCompactingStatus(p as CompactPayload);\n\t\tif (shouldRenderCompactCard(p as CompactPayload)) {\n\t\t\trenderCompactCard(p);\n\t\t}\n\t\tresetTokensAfterCompaction();\n\t} else if (p.phase === \"error\") {\n\t\tremoveCompactingStatus(p as CompactPayload);\n\t\tchatAddMsg(\"error\", `Auto-compact failed: ${p.error?.message || p.error?.detail || \"unknown error\"}`);\n\t}\n}\n\n// `chat.compact done` is emitted by ChatService::compact on every\n// compaction run (manual `/compact` RPCs AND the pre-emptive auto-\n// compact path). It carries the mode/tokens/settings metadata from\n// CompactionOutcome::broadcast_metadata() so the same card renders.\nfunction handleChatCompact(p: ChatPayload, isActive: boolean, isChatPage: boolean): void {\n\tif (!(isActive && isChatPage)) return;\n\tif (p.phase !== \"done\") return;\n\t// Drop the auto-compact status message if one exists. For the\n\t// manual `/compact` RPC path there is no status message, so this\n\t// is a no-op. For `send()`'s pre-emptive auto-compact path,\n\t// `chat.compact done` arrives BEFORE `auto_compact done`, so we\n\t// clear the status message here; the subsequent `auto_compact done`\n\t// handler will find the slot already empty.\n\tremoveCompactingStatus(p as CompactPayload);\n\tif (!shouldRenderCompactCard(p as CompactPayload)) return;\n\trenderCompactCard(p);\n\tresetTokensAfterCompaction();\n}\n\nfunction retryDelayMsFromPayload(p: ChatPayload): number {\n\tif (p.retryAfterMs !== undefined && p.retryAfterMs !== null) return Number(p.retryAfterMs) || 0;\n\tif (p.error?.retryAfterMs !== undefined && p.error?.retryAfterMs !== null) return Number(p.error.retryAfterMs) || 0;\n\treturn 0;\n}\n\nfunction retryStatusText(p: ChatPayload): string {\n\tconst retryMs = retryDelayMsFromPayload(p);\n\tconst retrySecs = Math.max(1, Math.ceil(retryMs / 1000));\n\tconst rateLimited = p.error?.type === \"rate_limit_exceeded\";\n\treturn rateLimited\n\t\t? `Rate limited by provider, retrying in ${retrySecs}s\\u2026`\n\t\t: `Temporary provider issue, retrying in ${retrySecs}s\\u2026`;\n}\n\nfunction handleChatRetrying(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tupdateSessionRunId(eventSession, p.runId);\n\tsetSessionReplying(eventSession, true);\n\tif (!(isActive && isChatPage)) return;\n\n\tlet indicator = document.getElementById(\"thinkingIndicator\");\n\tif (!indicator) {\n\t\tremoveThinking();\n\t\tindicator = document.createElement(\"div\");\n\t\tindicator.className = \"msg assistant thinking\";\n\t\tindicator.id = \"thinkingIndicator\";\n\t\tindicator.appendChild(makeThinkingDots());\n\t\tclearChatEmptyState();\n\t\tS.chatMsgBox!.appendChild(indicator);\n\t}\n\n\twhile (indicator.firstChild) indicator.removeChild(indicator.firstChild);\n\tconst textEl = document.createElement(\"span\");\n\ttextEl.className = \"thinking-text\";\n\ttextEl.textContent = retryStatusText(p);\n\tindicator.appendChild(textEl);\n\tS.chatMsgBox!.scrollTop = S.chatMsgBox!.scrollHeight;\n}\n\nfunction handleChatError(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tclearPendingToolCallEndsForSession(eventSession);\n\tsetSessionReplying(eventSession, false);\n\tsetSessionActiveRunId(eventSession, null);\n\t// Reset per-session stream state\n\tconst errSession = sessionStore.getByKey(eventSession);\n\tif (errSession) errSession.resetStreamState();\n\tif (!(isActive && isChatPage)) {\n\t\tS.setVoicePending(false);\n\t\treturn;\n\t}\n\tremoveThinking();\n\tclearStaleRunningToolCards();\n\tif (p.error?.title) {\n\t\tchatAddErrorCard(localizeStructuredError(p.error) as Parameters<typeof chatAddErrorCard>[0]);\n\t} else {\n\t\tchatAddErrorMsg(p.message || \"unknown\");\n\t}\n\t// Add continue button for max_iterations_reached errors.\n\tif (p.error?.canContinue) {\n\t\tconst lastCard = S.chatMsgBox!.querySelector(\".error-card:last-child\") as HTMLElement | null;\n\t\tif (lastCard) {\n\t\t\tconst btn = document.createElement(\"button\") as HTMLButtonElement;\n\t\t\tbtn.className = \"provider-btn error-continue-btn\";\n\t\t\tbtn.textContent = t(\"errors:chat.continue\", \"Continue\");\n\t\t\tbtn.onclick = () => {\n\t\t\t\tbtn.disabled = true;\n\t\t\t\tbtn.textContent = t(\"errors:chat.continuing\", \"Continuing...\");\n\t\t\t\t(S.chatInput as HTMLInputElement).value = t(\n\t\t\t\t\t\"errors:chat.continueMessage\",\n\t\t\t\t\t\"Please continue where you left off.\",\n\t\t\t\t);\n\t\t\t\t// Trigger send by clicking the chat send button (sendChat is local to ChatPage)\n\t\t\t\t(S.chatSendBtn as HTMLButtonElement)?.click();\n\t\t\t};\n\t\t\tconst body = lastCard.querySelector(\".error-body\");\n\t\t\tif (body) body.appendChild(btn);\n\t\t}\n\t}\n\tS.setStreamEl(null);\n\tS.setStreamText(\"\");\n\tS.setVoicePending(false);\n\tmoveFirstQueuedToChat();\n}\n\nfunction getAbortedPartialState(p: ChatPayload): AbortedPartialState {\n\tconst partial = p.partialMessage && typeof p.partialMessage === \"object\" ? p.partialMessage : null;\n\tconst partialText = String(partial?.content || \"\");\n\tconst partialReasoning = String(partial?.reasoning || \"\");\n\treturn {\n\t\tpartial,\n\t\tpartialText,\n\t\tpartialReasoning,\n\t\thasVisiblePartial: hasNonWhitespaceContent(partialText) || hasNonWhitespaceContent(partialReasoning),\n\t};\n}\n\nfunction cacheAbortedPartial(\n\teventSession: string,\n\tp: ChatPayload,\n\tabortSession: ReturnType<typeof sessionStore.getByKey>,\n\tpartialState: AbortedPartialState,\n): void {\n\tif (!partialState.hasVisiblePartial) return;\n\tconst partial = partialState.partial;\n\tconst lastIdx = abortSession ? abortSession.lastHistoryIndex.value : S.lastHistoryIndex;\n\tif (p.messageIndex === undefined || p.messageIndex === null || p.messageIndex > lastIdx) {\n\t\tbumpSessionCount(eventSession, 1);\n\t}\n\tcacheSessionHistoryMessage(\n\t\teventSession,\n\t\t{\n\t\t\trole: \"assistant\",\n\t\t\tcontent: partialState.partialText,\n\t\t\tmodel: partial?.model || \"\",\n\t\t\tprovider: partial?.provider || \"\",\n\t\t\tinputTokens: partial?.inputTokens || 0,\n\t\t\toutputTokens: partial?.outputTokens || 0,\n\t\t\tdurationMs: partial?.durationMs || 0,\n\t\t\trequestInputTokens: partial?.requestInputTokens,\n\t\t\trequestOutputTokens: partial?.requestOutputTokens,\n\t\t\treasoning: partial?.reasoning || undefined,\n\t\t\taudio: partial?.audio || undefined,\n\t\t\trun_id: partial?.run_id || p.runId || undefined,\n\t\t\tcreated_at: partial?.created_at || Date.now(),\n\t\t},\n\t\tp.messageIndex,\n\t);\n\tupdateSessionHistoryIndex(eventSession, p.messageIndex);\n}\n\nfunction renderAbortedPartialInDom(eventSession: string, p: ChatPayload, partialState: AbortedPartialState): void {\n\tif (!partialState.hasVisiblePartial) return;\n\tconst partial = partialState.partial;\n\tlet partialEl: HTMLElement | null = null;\n\tif (hasNonWhitespaceContent(partialState.partialText) && S.streamEl) {\n\t\tsetSafeMarkdownHtml(S.streamEl, partialState.partialText);\n\t\tpartialEl = S.streamEl;\n\t} else if (hasNonWhitespaceContent(partialState.partialText)) {\n\t\tpartialEl = chatAddMsg(\"assistant\", renderMarkdown(partialState.partialText), true);\n\t} else if (hasNonWhitespaceContent(partialState.partialReasoning)) {\n\t\tpartialEl = chatAddMsg(\"assistant\", \"\", false);\n\t}\n\tif (partialEl && partialState.partialReasoning && !isReasoningAlreadyShown(partialState.partialReasoning)) {\n\t\tappendReasoningDisclosure(partialEl, partialState.partialReasoning);\n\t}\n\tif (!partialEl) return;\n\tappendFinalFooter(\n\t\tpartialEl,\n\t\t{\n\t\t\tmodel: partial?.model || \"\",\n\t\t\tprovider: partial?.provider || \"\",\n\t\t\tinputTokens: partial?.inputTokens || 0,\n\t\t\toutputTokens: partial?.outputTokens || 0,\n\t\t\tdurationMs: partial?.durationMs || 0,\n\t\t\treplyMedium: p.replyMedium || \"text\",\n\t\t\ttext: partialState.partialText,\n\t\t\taudio: partial?.audio || undefined,\n\t\t\taudioWarning: undefined,\n\t\t\trunId: p.runId,\n\t\t\tmessageIndex: p.messageIndex,\n\t\t\tsessionKey: eventSession,\n\t\t},\n\t\teventSession,\n\t);\n\tS.chatMsgBox!.scrollTop = S.chatMsgBox!.scrollHeight;\n}\n\nfunction handleChatAborted(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tclearPendingToolCallEndsForSession(eventSession);\n\tsetSessionReplying(eventSession, false);\n\tsetSessionActiveRunId(eventSession, null);\n\tconst partialState = getAbortedPartialState(p);\n\tconst abortSession = sessionStore.getByKey(eventSession);\n\tcacheAbortedPartial(eventSession, p, abortSession, partialState);\n\tif (abortSession) abortSession.resetStreamState();\n\tif (partialState.hasVisiblePartial && !isActive) {\n\t\tsetSessionUnread(eventSession, true);\n\t}\n\tif (!(isActive && isChatPage)) {\n\t\tS.setVoicePending(false);\n\t\treturn;\n\t}\n\tremoveThinking();\n\tclearStaleRunningToolCards();\n\trenderAbortedPartialInDom(eventSession, p, partialState);\n\tS.setStreamEl(null);\n\tS.setStreamText(\"\");\n\tS.setVoicePending(false);\n\tmoveFirstQueuedToChat();\n}\n\nfunction handleChatNotice(p: ChatPayload, isActive: boolean, isChatPage: boolean): void {\n\tif (!(isActive && isChatPage)) return;\n\t// Render titled notices as markdown so emphasis is visible.\n\tconst msg = p.title ? `**${p.title}:** ${p.message}` : p.message || \"\";\n\tconst noticeEl = p.title ? chatAddMsg(\"system\", renderMarkdown(msg), true) : chatAddMsg(\"system\", msg);\n\tif (!(noticeEl && p.title)) return;\n\tnoticeEl.classList.add(\"system-notice\");\n\tif (String(p.title).toLowerCase() !== \"sandbox\") return;\n\tnoticeEl.classList.add(\"system-notice-sandbox\");\n\tconst normalizedMessage = String(p.message || \"\").toLowerCase();\n\tif (normalizedMessage.indexOf(\"enabled\") !== -1) {\n\t\tnoticeEl.classList.add(\"is-enabled\");\n\t} else if (normalizedMessage.indexOf(\"disabled\") !== -1) {\n\t\tnoticeEl.classList.add(\"is-disabled\");\n\t}\n}\n\nfunction handleChatQueueCleared(_p: ChatPayload, isActive: boolean, isChatPage: boolean): void {\n\tif (!(isActive && isChatPage)) return;\n\tconst tray = document.getElementById(\"queuedMessages\");\n\tif (tray) {\n\t\tconst count = tray.querySelectorAll(\".msg\").length;\n\t\tconsole.debug(\"[queued] queue_cleared: removing all from tray\", { count });\n\t\twhile (tray.firstChild) tray.removeChild(tray.firstChild);\n\t\ttray.classList.add(\"hidden\");\n\t}\n}\n\nfunction handleChatSessionCleared(_p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tclearPendingToolCallEndsForSession(eventSession);\n\tsetSessionActiveRunId(eventSession, null);\n\tclearSessionHistoryCache(eventSession);\n\t// Reset badge, unread state, and history index for every client.\n\tmarkSessionLocallyCleared(eventSession);\n\tif (isActive) {\n\t\tS.setLastHistoryIndex(-1);\n\t\tS.setChatSeq(0);\n\t}\n\tif (!(isActive && isChatPage)) return;\n\t// Active viewer: clear the chat box and token bar.\n\tif (S.chatMsgBox) S.chatMsgBox.textContent = \"\";\n\tS.setSessionTokens({ input: 0, output: 0 });\n\tS.setSessionCurrentInputTokens(0);\n\tupdateTokenBar();\n}\n\nconst chatHandlers: Record<string, ChatHandler> = {\n\tthinking: handleChatThinking,\n\tthinking_text: handleChatThinkingText,\n\tthinking_done: handleChatThinkingDone,\n\tvoice_pending: handleChatVoicePending,\n\ttool_call_start: handleChatToolCallStart,\n\ttool_call_end: handleChatToolCallEnd,\n\tchannel_user: handleChatChannelUser,\n\tuser_message: handleChatUserMessage,\n\tdelta: handleChatDelta,\n\tfinal: handleChatFinal,\n\tauto_compact: handleChatAutoCompact,\n\tcompact: handleChatCompact,\n\tretrying: handleChatRetrying,\n\terror: handleChatError,\n\taborted: handleChatAborted,\n\tnotice: handleChatNotice,\n\tqueue_cleared: handleChatQueueCleared,\n\tsession_cleared: handleChatSessionCleared,\n};\n\nfunction handleChatEvent(p: ChatPayload): void {\n\tconst eventSession = p.sessionKey || sessionStore.activeSessionKey.value;\n\tconst isActive = eventSession === sessionStore.activeSessionKey.value;\n\tconst isChatPage = currentPrefix === \"/chats\";\n\n\tif (isActive && sessionStore.switchInProgress.value) {\n\t\t// If session switching got stuck (e.g. lost RPC response), do not drop\n\t\t// terminal frames. Unstick and process final/error so replies still show\n\t\t// without requiring a full page reload.\n\t\tconst allowDuringSwitch =\n\t\t\tp.state === \"final\" ||\n\t\t\tp.state === \"error\" ||\n\t\t\tp.state === \"aborted\" ||\n\t\t\tp.state === \"notice\" ||\n\t\t\tp.state === \"session_cleared\" ||\n\t\t\tp.state === \"queue_cleared\";\n\t\tif (!allowDuringSwitch) {\n\t\t\treturn;\n\t\t}\n\t\tif (p.state === \"final\" || p.state === \"error\" || p.state === \"aborted\") {\n\t\t\tsessionStore.switchInProgress.value = false;\n\t\t\tS.setSessionSwitchInProgress(false);\n\t\t}\n\t}\n\n\tif (p.sessionKey && !sessionStore.getByKey(p.sessionKey)) {\n\t\tfetchSessions();\n\t}\n\n\tconst handler = chatHandlers[p.state || \"\"];\n\tif (handler) handler(p, isActive, isChatPage, eventSession);\n}\n\nfunction handleApprovalEvent(payload: ApprovalPayload): void {\n\trenderApprovalCard(payload.requestId, payload.command);\n}\n\nfunction handleLogEntry(payload: LogEntryPayload): void {\n\tif (S.logsEventHandler) S.logsEventHandler(payload);\n\tif (currentPage !== \"/logs\") {\n\t\tconst ll = (payload.level || \"\").toUpperCase();\n\t\tif (ll === \"ERROR\") {\n\t\t\tS.setUnseenErrors(S.unseenErrors + 1);\n\t\t\tupdateLogsAlert();\n\t\t} else if (ll === \"WARN\") {\n\t\t\tS.setUnseenWarns(S.unseenWarns + 1);\n\t\t\tupdateLogsAlert();\n\t\t}\n\t}\n}\n\nfunction updateSandboxBuildingFlag(building: boolean): void {\n\tconst info = S.sandboxInfo as Record<string, unknown> | null;\n\tif (info) S.setSandboxInfo({ ...info, image_building: building });\n}\n\nlet sandboxPrepareIndicatorEl: HTMLElement | null = null;\nfunction handleSandboxPrepare(payload: SandboxPhasePayload): void {\n\tconst isChatPage = currentPrefix === \"/chats\";\n\tif (!isChatPage) return;\n\n\tif (payload.phase === \"start\") {\n\t\tif (sandboxPrepareIndicatorEl) {\n\t\t\tsandboxPrepareIndicatorEl.remove();\n\t\t\tsandboxPrepareIndicatorEl = null;\n\t\t}\n\t\tsandboxPrepareIndicatorEl = chatAddMsg(\n\t\t\t\"system\",\n\t\t\t\"Preparing sandbox environment (first run may take a minute)\\u2026\",\n\t\t);\n\t\treturn;\n\t}\n\n\tif (sandboxPrepareIndicatorEl) {\n\t\tsandboxPrepareIndicatorEl.remove();\n\t\tsandboxPrepareIndicatorEl = null;\n\t}\n\n\tif (payload.phase === \"error\") {\n\t\tchatAddMsg(\"error\", `Sandbox setup failed: ${payload.error || \"unknown\"}`);\n\t}\n}\n\nfunction handleSandboxImageBuild(payload: SandboxPhasePayload): void {\n\tconst phase = payload.phase;\n\t// Update the sandboxInfo signal so all pages (chat, settings) reflect the build state.\n\tupdateSandboxBuildingFlag(phase === \"start\");\n\n\tconst isChatPage = currentPrefix === \"/chats\";\n\tif (!isChatPage) return;\n\tif (phase === \"start\") {\n\t\tchatAddMsg(\"system\", \"Building sandbox image (installing packages)\\u2026\");\n\t} else if (phase === \"done\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tconst msg = payload.built ? `Sandbox image ready: ${payload.tag}` : `Sandbox image already cached: ${payload.tag}`;\n\t\tchatAddMsg(\"system\", msg);\n\t} else if (phase === \"error\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tchatAddMsg(\"error\", `Sandbox image build failed: ${payload.error || \"unknown\"}`);\n\t}\n}\n\nfunction handleSandboxImageProvision(payload: SandboxPhasePayload): void {\n\tconst isChatPage = currentPrefix === \"/chats\";\n\tif (!isChatPage) return;\n\tif (payload.phase === \"start\") {\n\t\tchatAddMsg(\"system\", \"Provisioning sandbox packages\\u2026\");\n\t} else if (payload.phase === \"done\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tchatAddMsg(\"system\", \"Sandbox packages provisioned\");\n\t} else if (payload.phase === \"error\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tchatAddMsg(\"error\", `Sandbox provisioning failed: ${payload.error || \"unknown\"}`);\n\t}\n}\n\n// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Provisioning UI with multiple phases\nfunction handleSandboxHostProvision(payload: SandboxPhasePayload): void {\n\tconst isChatPage = currentPrefix === \"/chats\";\n\tif (!isChatPage) return;\n\tif (payload.phase === \"start\") {\n\t\tconst msg = `Installing ${payload.count || \"\"} package${payload.count === 1 ? \"\" : \"s\"} on host\\u2026`;\n\t\tchatAddMsg(\"system\", msg);\n\t} else if (payload.phase === \"done\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tconst parts: string[] = [];\n\t\tif ((payload.installed || 0) > 0) parts.push(`${payload.installed} installed`);\n\t\tif ((payload.skipped || 0) > 0) parts.push(`${payload.skipped} already present`);\n\t\tchatAddMsg(\"system\", `Host packages ready (${parts.join(\", \") || \"done\"})`);\n\t} else if (payload.phase === \"error\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tchatAddMsg(\"error\", `Host package install failed: ${payload.error || \"unknown\"}`);\n\t}\n}\n\nfunction handleBrowserImagePull(payload: SandboxPhasePayload): void {\n\tconst isChatPage = currentPrefix === \"/chats\";\n\tif (!isChatPage) return;\n\tconst image = payload.image || \"browser container\";\n\tif (payload.phase === \"start\") {\n\t\tchatAddMsg(\"system\", `Pulling browser container image (${image})\\u2026 This may take a few minutes on first run.`);\n\t} else if (payload.phase === \"done\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tchatAddMsg(\"system\", `Browser container image ready: ${image}`);\n\t} else if (payload.phase === \"error\") {\n\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\tchatAddMsg(\"error\", `Browser container image pull failed: ${payload.error || \"unknown\"}`);\n\t}\n}\n\n// Track download indicator element\nlet downloadIndicatorEl: HTMLElement | null = null;\n\n// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Download progress UI with multiple states\nfunction handleLocalLlmDownload(payload: LocalLlmDownloadPayload): void {\n\tconst isChatPage = currentPrefix === \"/chats\";\n\tif (!isChatPage) return;\n\n\tconst modelName = payload.displayName || payload.modelId || \"model\";\n\n\tif (payload.error) {\n\t\t// Download error\n\t\tif (downloadIndicatorEl) {\n\t\t\tdownloadIndicatorEl.remove();\n\t\t\tdownloadIndicatorEl = null;\n\t\t}\n\t\tchatAddMsg(\"error\", `Failed to download ${modelName}: ${payload.error}`);\n\t\treturn;\n\t}\n\n\tif (payload.complete) {\n\t\t// Download complete\n\t\tif (downloadIndicatorEl) {\n\t\t\tdownloadIndicatorEl.remove();\n\t\t\tdownloadIndicatorEl = null;\n\t\t}\n\t\tchatAddMsg(\"system\", `${modelName} ready`);\n\t\treturn;\n\t}\n\n\t// Download in progress - show/update progress indicator\n\tif (!downloadIndicatorEl) {\n\t\tdownloadIndicatorEl = document.createElement(\"div\");\n\t\tdownloadIndicatorEl.className = \"msg system download-indicator\";\n\n\t\tconst status = document.createElement(\"div\");\n\t\tstatus.className = \"download-status\";\n\t\tstatus.textContent = `Downloading ${modelName}\\u2026`;\n\t\tdownloadIndicatorEl.appendChild(status);\n\n\t\tconst progressContainer = document.createElement(\"div\");\n\t\tprogressContainer.className = \"download-progress\";\n\t\tconst progressBar = document.createElement(\"div\");\n\t\tprogressBar.className = \"download-progress-bar\";\n\t\tprogressContainer.appendChild(progressBar);\n\t\tdownloadIndicatorEl.appendChild(progressContainer);\n\n\t\tconst progressText = document.createElement(\"div\");\n\t\tprogressText.className = \"download-progress-text\";\n\t\tdownloadIndicatorEl.appendChild(progressText);\n\n\t\tif (S.chatMsgBox) {\n\t\t\tclearChatEmptyState();\n\t\t\tS.chatMsgBox.appendChild(downloadIndicatorEl);\n\t\t\tS.chatMsgBox.scrollTop = S.chatMsgBox.scrollHeight;\n\t\t}\n\t}\n\n\t// Update progress bar\n\tconst barEl = downloadIndicatorEl.querySelector(\".download-progress-bar\") as HTMLElement | null;\n\tconst textEl = downloadIndicatorEl.querySelector(\".download-progress-text\") as HTMLElement | null;\n\tconst containerEl = downloadIndicatorEl.querySelector(\".download-progress\") as HTMLElement | null;\n\n\tif (barEl && containerEl) {\n\t\tif (payload.progress != null) {\n\t\t\t// Determinate progress - show actual percentage\n\t\t\tcontainerEl.classList.remove(\"indeterminate\");\n\t\t\tbarEl.style.width = `${payload.progress.toFixed(1)}%`;\n\t\t} else if (payload.total == null && payload.downloaded != null) {\n\t\t\t// Indeterminate progress - CSS handles the animation\n\t\t\tcontainerEl.classList.add(\"indeterminate\");\n\t\t\tbarEl.style.width = \"\"; // Let CSS control width\n\t\t}\n\t}\n\n\tif (payload.downloaded != null && textEl) {\n\t\tconst downloadedMb = (payload.downloaded / (1024 * 1024)).toFixed(1);\n\t\tif (payload.total != null) {\n\t\t\tconst totalMb = (payload.total / (1024 * 1024)).toFixed(1);\n\t\t\ttextEl.textContent = `${downloadedMb} / ${totalMb} MB`;\n\t\t} else {\n\t\t\ttextEl.textContent = `${downloadedMb} MB`;\n\t\t}\n\t}\n}\n\nlet modelsUpdatedTimer: ReturnType<typeof setTimeout> | null = null;\nfunction handleModelsUpdated(payload: ModelsUpdatedPayload): void {\n\t// Progress/status frames are consumed directly by the Providers page.\n\t// Avoid spamming model refresh requests while a probe is running.\n\tif (payload?.phase === \"start\" || payload?.phase === \"progress\") return;\n\tif (modelsUpdatedTimer) return;\n\tmodelsUpdatedTimer = setTimeout(() => {\n\t\tmodelsUpdatedTimer = null;\n\t\t// fetchModels() delegates to modelStore.fetch() internally\n\t\tfetchModels();\n\t\tif (S.refreshProvidersPage) S.refreshProvidersPage();\n\t}, 150);\n}\n\n// ── Location request handler ─────────────────────────────────\n\nfunction handleWsError(payload: WsErrorPayload): void {\n\tconst isChatPage = currentPrefix === \"/chats\";\n\tif (!isChatPage) return;\n\tchatAddErrorMsg(payload.message || \"Unknown error\");\n}\n\nfunction handleLocationRequest(payload: LocationRequestPayload): void {\n\tconst requestId = payload.requestId;\n\tif (!requestId) return;\n\n\tif (!navigator.geolocation) {\n\t\tsendRpc(\"location.result\", {\n\t\t\trequestId,\n\t\t\terror: { code: 0, message: \"Geolocation not supported\" },\n\t\t});\n\t\treturn;\n\t}\n\n\t// Coarse: city-level, fast, longer cache. Precise: GPS-level, fresh.\n\tconst coarse = payload.precision === \"coarse\";\n\tconst geoOpts: PositionOptions = coarse\n\t\t? { enableHighAccuracy: false, timeout: 10000, maximumAge: 1800000 }\n\t\t: { enableHighAccuracy: true, timeout: 15000, maximumAge: 60000 };\n\n\tnavigator.geolocation.getCurrentPosition(\n\t\t(pos: GeolocationPosition) => {\n\t\t\tsendRpc(\"location.result\", {\n\t\t\t\trequestId,\n\t\t\t\tlocation: {\n\t\t\t\t\tlatitude: pos.coords.latitude,\n\t\t\t\t\tlongitude: pos.coords.longitude,\n\t\t\t\t\taccuracy: pos.coords.accuracy,\n\t\t\t\t},\n\t\t\t});\n\t\t},\n\t\t(err: GeolocationPositionError) => {\n\t\t\tsendRpc(\"location.result\", {\n\t\t\t\trequestId,\n\t\t\t\terror: { code: err.code, message: err.message },\n\t\t\t});\n\t\t},\n\t\tgeoOpts,\n\t);\n}\n\nfunction handleNetworkAuditEntry(payload: Record<string, unknown>): void {\n\tif (S.networkAuditEventHandler) S.networkAuditEventHandler(payload);\n}\n\nfunction handleAuthCredentialsChanged(payload: AuthCredentialsPayload): void {\n\tif (payload?.reason === \"password_changed\" && window.__moltisSuppressNextPasswordChangedRedirect === true) {\n\t\twindow.__moltisSuppressNextPasswordChangedRedirect = false;\n\t\tconsole.info(\"Deferring redirect for password_changed to show recovery key first\");\n\t\treturn;\n\t}\n\tconsole.warn(\"Auth credentials changed:\", payload.reason);\n\twindow.location.href = \"/login\";\n}\n\nconst eventHandlers: Record<string, (payload: Record<string, unknown>, streamMeta?: StreamMeta | null) => void> = {\n\tchat: handleChatEvent as (payload: Record<string, unknown>) => void,\n\terror: handleWsError as (payload: Record<string, unknown>) => void,\n\t\"auth.credentials_changed\": handleAuthCredentialsChanged as (payload: Record<string, unknown>) => void,\n\t\"exec.approval.requested\": handleApprovalEvent as unknown as (payload: Record<string, unknown>) => void,\n\t\"logs.entry\": handleLogEntry as (payload: Record<string, unknown>) => void,\n\t\"sandbox.prepare\": handleSandboxPrepare as (payload: Record<string, unknown>) => void,\n\t\"sandbox.image.build\": handleSandboxImageBuild as (payload: Record<string, unknown>) => void,\n\t\"sandbox.image.provision\": handleSandboxImageProvision as (payload: Record<string, unknown>) => void,\n\t\"sandbox.host.provision\": handleSandboxHostProvision as (payload: Record<string, unknown>) => void,\n\t\"browser.image.pull\": handleBrowserImagePull as (payload: Record<string, unknown>) => void,\n\t\"local-llm.download\": handleLocalLlmDownload as (payload: Record<string, unknown>) => void,\n\t\"models.updated\": handleModelsUpdated as (payload: Record<string, unknown>) => void,\n\t\"location.request\": handleLocationRequest as (payload: Record<string, unknown>) => void,\n\t\"network.audit.entry\": handleNetworkAuditEntry as (payload: Record<string, unknown>) => void,\n};\n\nfunction dispatchFrame(frame: WsFrame): void {\n\tif (frame.type !== \"event\") return;\n\tconst streamMeta: StreamMeta | null =\n\t\tframe.stream != null || frame.done != null\n\t\t\t? { stream: frame.stream, done: frame.done, channel: frame.channel }\n\t\t\t: null;\n\tconst listeners = eventListeners[frame.event || \"\"] || [];\n\tlisteners.forEach((h) => {\n\t\th(frame.payload || {});\n\t});\n\tconst handler = eventHandlers[frame.event || \"\"];\n\tif (handler) handler(frame.payload || {}, streamMeta);\n}\n\nconst connectOpts: ConnectOptions = {\n\tonFrame: dispatchFrame as ConnectOptions[\"onFrame\"],\n\tonConnected: async (hello) => {\n\t\tconst isReconnect = hasConnectedOnce;\n\t\thasConnectedOnce = true;\n\t\tsetStatus(\"connected\", \"\");\n\t\tconst now = new Date();\n\t\tconst ts = now.toLocaleTimeString([], {\n\t\t\thour: \"2-digit\",\n\t\t\tminute: \"2-digit\",\n\t\t\tsecond: \"2-digit\",\n\t\t});\n\t\tchatAddMsg(\"system\", `Connected to moltis gateway v${hello.server.version} at ${ts}`);\n\t\tif ((S.sandboxInfo as Record<string, unknown> | null)?.image_building) {\n\t\t\tchatAddMsg(\"system\", \"Building sandbox image (installing packages)\\u2026\");\n\t\t}\n\t\t// Subscribe to all needed events (v4 protocol).\n\t\t// Await so that events are not lost to a race between subscribe and\n\t\t// the first broadcast after connect.\n\t\tS.setSubscribed(false);\n\t\tawait subscribeEvents(\n\t\t\tObject.keys(eventHandlers).concat([\n\t\t\t\t\"tick\",\n\t\t\t\t\"shutdown\",\n\t\t\t\t\"auth.credentials_changed\",\n\t\t\t\t\"exec.approval.requested\",\n\t\t\t\t\"exec.approval.resolved\",\n\t\t\t\t\"device.pair.requested\",\n\t\t\t\t\"device.pair.resolved\",\n\t\t\t\t\"node.pair.requested\",\n\t\t\t\t\"node.pair.resolved\",\n\t\t\t\t\"node.invoke.request\",\n\t\t\t\t\"session\",\n\t\t\t\t\"update.available\",\n\t\t\t\t\"hooks.status\",\n\t\t\t\t\"push.subscriptions\",\n\t\t\t\t\"channel\",\n\t\t\t\t\"metrics.update\",\n\t\t\t\t\"skills.install.progress\",\n\t\t\t\t\"mcp.status\",\n\t\t\t]),\n\t\t);\n\t\tS.setSubscribed(true);\n\t\t// Keep initial hydration authoritative via app bootstrap/gon.\n\t\t// On reconnect, force a fresh snapshot in case realtime events were missed.\n\t\tif (isReconnect) {\n\t\t\tfetchModels();\n\t\t\tfetchSessions();\n\t\t\tfetchProjects();\n\t\t\tprefetchChannels();\n\t\t}\n\t\tsendRpc(\"logs.status\", {}).then((res) => {\n\t\t\tif (res?.ok) {\n\t\t\t\tconst p = (res.payload || {}) as Record<string, unknown>;\n\t\t\t\tS.setUnseenErrors((p.unseen_errors as number) || 0);\n\t\t\t\tS.setUnseenWarns((p.unseen_warns as number) || 0);\n\t\t\t\tif (currentPage === \"/logs\") clearLogsAlert();\n\t\t\t\telse updateLogsAlert();\n\t\t\t}\n\t\t});\n\t\tif (currentPage === \"/chats\" || currentPrefix === \"/chats\") mount(currentPage || \"\");\n\t},\n\tonHandshakeFailed: (frame) => {\n\t\tsetStatus(\"\", \"handshake failed\");\n\t\tconst reason = frame.error?.message || \"unknown error\";\n\t\tchatAddMsg(\"error\", `Handshake failed: ${reason}`);\n\t},\n\tonDisconnected: (wasConnected: boolean) => {\n\t\tif (wasConnected) {\n\t\t\tsetStatus(\"\", \"disconnected \\u2014 reconnecting\\u2026\");\n\t\t}\n\t\t// Reset active session's stream state\n\t\tconst activeS = sessionStore.activeSession.value;\n\t\tif (activeS) activeS.resetStreamState();\n\t\tS.setStreamEl(null);\n\t\tS.setStreamText(\"\");\n\t},\n};\n\nexport function connect(): void {\n\tsetStatus(\"connecting\", \"connecting...\");\n\tconnectWs(connectOpts);\n}\n\nfunction setStatus(state: string, text: string): void {\n\tconst dot = S.$(\"statusDot\");\n\tconst sText = S.$(\"statusText\");\n\tif (dot) dot.className = `status-dot ${state}`;\n\tif (sText) {\n\t\tsText.textContent = text;\n\t\tsText.classList.toggle(\"status-text-live\", state === \"connected\");\n\t}\n\tconst sendBtn = S.$(\"sendBtn\") as HTMLButtonElement | null;\n\tif (sendBtn) sendBtn.disabled = state !== \"connected\";\n}\n\ndocument.addEventListener(\"visibilitychange\", () => {\n\tif (!(document.hidden || S.connected)) {\n\t\tforceReconnect(connectOpts);\n\t}\n});\n","// ── Crons page (Preact + Signals) ──────────────────────────\n\nimport { signal, useSignal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect } from \"preact/hooks\";\nimport { fetchChannelStatus } from \"../channel-utils\";\nimport * as gon from \"../gon\";\nimport { refresh as refreshGon } from \"../gon\";\nimport { sendRpc } from \"../helpers\";\nimport { updateNavCount } from \"../nav-counts\";\nimport { models as modelsSig } from \"../stores/model-store\";\nimport { ComboSelect, ConfirmDialog, Modal, ModelSelect, requestConfirm } from \"../ui\";\n\n// ── Types ────────────────────────────────────────────────────\n\ninterface CronJob {\n\tid: string;\n\tname: string;\n\tenabled: boolean;\n\tsystem?: boolean;\n\tschedule: CronSchedule;\n\tpayload: CronPayload;\n\tsessionTarget?: string;\n\tdeleteAfterRun?: boolean;\n\tstate?: { lastStatus?: string; nextRunAtMs?: number };\n\tsandbox?: { enabled?: boolean; image?: string };\n}\n\ninterface CronSchedule {\n\tkind: string;\n\texpr?: string;\n\ttz?: string;\n\tat_ms?: number;\n\tevery_ms?: number;\n}\n\ninterface CronPayload {\n\tkind: string;\n\ttext?: string;\n\tmessage?: string;\n\tmodel?: string;\n\tdeliver?: boolean;\n\tchannel?: string;\n\tto?: string;\n}\n\ninterface CronStatusInfo {\n\trunning: boolean;\n\tjobCount: number;\n\tenabledCount: number;\n\tnextRunAtMs?: number;\n}\n\ninterface HeartbeatConfig {\n\tenabled?: boolean;\n\tevery?: string;\n\tmodel?: string;\n\tprompt?: string;\n\tack_max_chars?: number;\n\tdeliver?: boolean;\n\tchannel?: string;\n\tto?: string;\n\tactive_hours?: { start?: string; end?: string; timezone?: string };\n\tsandbox_enabled?: boolean;\n\tsandbox_image?: string;\n}\n\ninterface HeartbeatStatusInfo {\n\tpromptSource?: string;\n\tjob?: CronJob;\n}\n\ninterface CronRun {\n\tstartedAtMs: number;\n\tstatus: string;\n\tdurationMs: number;\n\terror?: string;\n\tinputTokens?: number;\n\toutputTokens?: number;\n}\n\ninterface RunsHistory {\n\tjobId: string;\n\tjobName: string;\n\truns: CronRun[] | null;\n}\n\ninterface SandboxImage {\n\ttag: string;\n}\n\ninterface ChannelAccount {\n\taccount_id: string;\n\tname?: string;\n\tstatus: string;\n}\n\n// ── Signals ──────────────────────────────────────────────────\n\nconst initialCrons = (gon.get(\"crons\") as CronJob[] | null) || [];\nconst cronJobs = signal<CronJob[]>(initialCrons);\nconst cronStatus = signal<CronStatusInfo | null>(gon.get(\"cron_status\") as CronStatusInfo | null);\nif (initialCrons.length) updateNavCount(\"crons\", initialCrons.filter((j) => j.enabled).length);\nconst runsHistory = signal<RunsHistory | null>(null);\nconst showModal = signal(false);\nconst editingJob = signal<CronJob | null>(null);\nconst activeSection = signal<\"jobs\" | \"heartbeat\">(\"jobs\");\nlet _cronsContainer: HTMLElement | null = null;\n\n// Heartbeat state\nconst heartbeatStatus = signal<HeartbeatStatusInfo | null>(null);\nconst heartbeatRuns = signal<CronRun[] | null>((gon.get(\"heartbeat_runs\") as CronRun[] | null) || []);\nconst heartbeatSaving = signal(false);\nconst heartbeatRunning = signal(false);\nconst heartbeatConfig = signal<HeartbeatConfig>((gon.get(\"heartbeat_config\") as HeartbeatConfig | null) || {});\nconst sandboxImages = signal<SandboxImage[]>([]);\nconst channelAccounts = signal<ChannelAccount[]>([]);\nconst heartbeatModel = signal((gon.get(\"heartbeat_config\") as HeartbeatConfig | null)?.model || \"\");\nconst heartbeatSandboxImage = signal((gon.get(\"heartbeat_config\") as HeartbeatConfig | null)?.sandbox_image || \"\");\n\nfunction loadSandboxImages(): void {\n\tfetch(\"/api/images/cached\")\n\t\t.then((r) => r.json())\n\t\t.then((d) => {\n\t\t\tsandboxImages.value = d?.images || [];\n\t\t})\n\t\t.catch(() => {\n\t\t\t/* optional */\n\t\t});\n}\nfunction loadChannelAccounts(): void {\n\tfetchChannelStatus().then((res: unknown) => {\n\t\tconst r = res as { ok?: boolean; payload?: { channels?: ChannelAccount[] } } | null;\n\t\tif (r?.ok) channelAccounts.value = (r.payload?.channels || []).filter((c) => c.status === \"connected\");\n\t});\n}\nfunction loadHeartbeatStatus(): void {\n\tsendRpc(\"heartbeat.status\", {}).then((res) => {\n\t\tif (res?.ok) heartbeatStatus.value = res.payload as HeartbeatStatusInfo;\n\t});\n}\nfunction findHeartbeatJob(): CronJob | null {\n\treturn cronJobs.value.find((j) => j.name === \"__heartbeat__\") || (heartbeatStatus.value?.job as CronJob) || null;\n}\nfunction loadHeartbeatRuns(): void {\n\tif (!findHeartbeatJob()) {\n\t\theartbeatRuns.value = heartbeatRuns.value || [];\n\t\treturn;\n\t}\n\theartbeatRuns.value = null;\n\tsendRpc(\"heartbeat.runs\", { limit: 10 }).then((res) => {\n\t\theartbeatRuns.value = res?.ok ? (res.payload as CronRun[]) || [] : [];\n\t});\n}\nfunction heartbeatRunBlockedReason(cfg: HeartbeatConfig, promptSource: string, job: CronJob | null): string | null {\n\tif (cfg.enabled === false) return \"Heartbeat is disabled. Enable it to allow manual runs.\";\n\tif (promptSource === \"default\")\n\t\treturn \"Heartbeat is inactive because no prompt is configured. Add a custom prompt or write actionable content in HEARTBEAT.md.\";\n\tif (!job) return \"Heartbeat has no active cron job yet. Save the heartbeat settings to recreate it.\";\n\treturn null;\n}\nfunction loadStatus(): void {\n\tsendRpc(\"cron.status\", {}).then((res) => {\n\t\tif (res?.ok) cronStatus.value = res.payload as CronStatusInfo;\n\t});\n}\nfunction loadJobs(): void {\n\tsendRpc(\"cron.list\", {}).then((res) => {\n\t\tif (res?.ok) {\n\t\t\tcronJobs.value = (res.payload as CronJob[]) || [];\n\t\t\tupdateNavCount(\"crons\", cronJobs.value.filter((j) => j.enabled).length);\n\t\t}\n\t});\n}\n\nfunction formatSchedule(sched: CronSchedule): string {\n\tif (sched.kind === \"at\") return `At ${new Date(sched.at_ms!).toLocaleString()}`;\n\tif (sched.kind === \"every\") {\n\t\tconst ms = sched.every_ms!;\n\t\tif (ms >= 3600000) return `Every ${ms / 3600000}h`;\n\t\tif (ms >= 60000) return `Every ${ms / 60000}m`;\n\t\treturn `Every ${ms / 1000}s`;\n\t}\n\tif (sched.kind === \"cron\") return sched.expr! + (sched.tz ? ` (${sched.tz})` : \"\");\n\treturn JSON.stringify(sched);\n}\n\nfunction formatTokens(n: number | null | undefined): string | null {\n\tif (n == null) return null;\n\tif (n >= 1000) return `${(n / 1000).toFixed(1).replace(/\\.0$/, \"\")}K`;\n\treturn String(n);\n}\n\nfunction TokenBadge({ run }: { run: CronRun }): VNode | null {\n\tif (run.inputTokens == null && run.outputTokens == null) return null;\n\tconst parts: string[] = [];\n\tif (run.inputTokens != null) parts.push(`${formatTokens(run.inputTokens)} in`);\n\tif (run.outputTokens != null) parts.push(`${formatTokens(run.outputTokens)} out`);\n\treturn <span className=\"text-xs text-[var(--muted)] font-mono\">{parts.join(\" / \")}</span>;\n}\n\nfunction HeartbeatRunsList({ runs }: { runs: CronRun[] | null }): VNode {\n\tif (runs === null) return <div className=\"text-xs text-[var(--muted)]\">Loading&hellip;</div>;\n\tif (runs.length === 0) return <div className=\"text-xs text-[var(--muted)]\">No runs yet.</div>;\n\treturn (\n\t\t<div className=\"flex flex-col\">\n\t\t\t{runs.map((run) => (\n\t\t\t\t<div\n\t\t\t\t\tkey={run.startedAtMs}\n\t\t\t\t\tclassName=\"flex items-center gap-3 py-2 border-b border-[var(--border)]\"\n\t\t\t\t\tstyle={{ minHeight: \"36px\" }}\n\t\t\t\t>\n\t\t\t\t\t<span className={`status-dot ${run.status === \"ok\" ? \"connected\" : \"\"}`} />\n\t\t\t\t\t<span className={`cron-badge ${run.status}`}>{run.status}</span>\n\t\t\t\t\t<span className=\"text-xs text-[var(--muted)] font-mono\">{run.durationMs}ms</span>\n\t\t\t\t\t<TokenBadge run={run} />\n\t\t\t\t\t{run.error && <span className=\"text-xs text-[var(--error)] truncate\">{run.error}</span>}\n\t\t\t\t\t<span className=\"flex-1\" />\n\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t<time data-epoch-ms={run.startedAtMs}>{new Date(run.startedAtMs).toISOString()}</time>\n\t\t\t\t\t</span>\n\t\t\t\t</div>\n\t\t\t))}\n\t\t</div>\n\t);\n}\n\nfunction HeartbeatJobStatus({ job }: { job: CronJob | null }): VNode | null {\n\tif (!job) return null;\n\tconst statusDotClass = job.enabled ? \"connected\" : \"\";\n\treturn (\n\t\t<div className=\"info-bar\" style={{ marginTop: \"16px\", marginBottom: \"16px\" }}>\n\t\t\t<span className=\"info-field\">\n\t\t\t\t<span className={`status-dot ${statusDotClass}`} />\n\t\t\t\t<span className=\"info-label\">{job.enabled ? \"Enabled\" : \"Disabled\"}</span>\n\t\t\t</span>\n\t\t\t{job.state?.lastStatus && (\n\t\t\t\t<span className=\"info-field\">\n\t\t\t\t\t<span className=\"info-label\">Last:</span>\n\t\t\t\t\t<span className={`cron-badge ${job.state.lastStatus}`}>{job.state.lastStatus}</span>\n\t\t\t\t</span>\n\t\t\t)}\n\t\t\t{job.state?.nextRunAtMs && (\n\t\t\t\t<span className=\"info-field\">\n\t\t\t\t\t<span className=\"info-label\">Next:</span>\n\t\t\t\t\t<span className=\"info-value\">\n\t\t\t\t\t\t<time data-epoch-ms={job.state.nextRunAtMs}>{new Date(job.state.nextRunAtMs).toLocaleString()}</time>\n\t\t\t\t\t</span>\n\t\t\t\t</span>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\nfunction defaultModelPlaceholder(): string {\n\tif (!modelsSig.value.length) return \"(server default)\";\n\tconst m = modelsSig.value[0] as unknown as { displayName?: string; id: string };\n\treturn `(default: ${m.displayName || m.id})`;\n}\n\nconst systemTimezone = Intl.DateTimeFormat().resolvedOptions().timeZone;\nfunction cronTimezoneHelpText(): string {\n\treturn systemTimezone\n\t\t? `Leave blank to use UTC. Enter ${systemTimezone} to use your local timezone.`\n\t\t: \"Leave blank to use UTC. Enter a timezone like Europe/Paris to use your local timezone.\";\n}\n\nfunction collectHeartbeatForm(form: Element): HeartbeatConfig {\n\treturn {\n\t\tenabled: (form.querySelector(\"[data-hb=enabled]\") as HTMLInputElement).checked,\n\t\tevery: (form.querySelector(\"[data-hb=every]\") as HTMLInputElement).value.trim() || \"30m\",\n\t\tmodel: heartbeatModel.value || undefined,\n\t\tprompt: (form.querySelector(\"[data-hb=prompt]\") as HTMLTextAreaElement).value.trim() || undefined,\n\t\tack_max_chars: parseInt((form.querySelector(\"[data-hb=ackMax]\") as HTMLInputElement).value, 10) || 300,\n\t\tdeliver: (form.querySelector(\"[data-hb=deliver]\") as HTMLInputElement).checked,\n\t\tchannel: (form.querySelector(\"[data-hb=channel]\") as HTMLInputElement).value.trim() || undefined,\n\t\tto: (form.querySelector(\"[data-hb=to]\") as HTMLInputElement).value.trim() || undefined,\n\t\tactive_hours: {\n\t\t\tstart: (form.querySelector(\"[data-hb=ahStart]\") as HTMLInputElement).value.trim() || \"08:00\",\n\t\t\tend: (form.querySelector(\"[data-hb=ahEnd]\") as HTMLInputElement).value.trim() || \"24:00\",\n\t\t\ttimezone: (form.querySelector(\"[data-hb=ahTz]\") as HTMLSelectElement).value.trim() || \"local\",\n\t\t},\n\t\tsandbox_enabled: (form.querySelector(\"[data-hb=sandboxEnabled]\") as HTMLInputElement).checked,\n\t\tsandbox_image: heartbeatSandboxImage.value || undefined,\n\t};\n}\n\nfunction HeartbeatSection(): VNode {\n\tconst cfg = heartbeatConfig.value;\n\tconst saving = heartbeatSaving.value;\n\tconst promptSource = heartbeatStatus.value?.promptSource || \"default\";\n\tconst job = findHeartbeatJob();\n\tconst runBlockedReason = heartbeatRunBlockedReason(cfg, promptSource, job);\n\n\tfunction onSave(e: Event): void {\n\t\te.preventDefault();\n\t\tconst updated = collectHeartbeatForm((e.target as HTMLElement).closest(\".heartbeat-form\")!);\n\t\theartbeatSaving.value = true;\n\t\tsendRpc(\"heartbeat.update\", updated).then((res) => {\n\t\t\theartbeatSaving.value = false;\n\t\t\tif (res?.ok) {\n\t\t\t\theartbeatConfig.value = updated;\n\t\t\t\theartbeatModel.value = updated.model || \"\";\n\t\t\t\theartbeatSandboxImage.value = updated.sandbox_image || \"\";\n\t\t\t\trefreshGon();\n\t\t\t\tloadHeartbeatStatus();\n\t\t\t\tloadJobs();\n\t\t\t\tloadStatus();\n\t\t\t}\n\t\t});\n\t}\n\n\tfunction onRunNow(): void {\n\t\tif (runBlockedReason) return;\n\t\theartbeatRunning.value = true;\n\t\tsendRpc(\"heartbeat.run\", {}).then(() => {\n\t\t\theartbeatRunning.value = false;\n\t\t\tloadHeartbeatStatus();\n\t\t\tloadHeartbeatRuns();\n\t\t\tloadJobs();\n\t\t\tloadStatus();\n\t\t});\n\t}\n\n\tfunction onToggleEnabled(e: Event): void {\n\t\tconst newEnabled = (e.target as HTMLInputElement).checked;\n\t\tconst updated = { ...cfg, enabled: newEnabled };\n\t\tsendRpc(\"heartbeat.update\", updated).then((res) => {\n\t\t\tif (res?.ok) {\n\t\t\t\theartbeatConfig.value = updated;\n\t\t\t\trefreshGon();\n\t\t\t\tloadHeartbeatStatus();\n\t\t\t\tloadJobs();\n\t\t\t\tloadStatus();\n\t\t\t}\n\t\t});\n\t}\n\n\tconst running = heartbeatRunning.value;\n\tconst runNowDisabled = running || !!runBlockedReason;\n\tconst promptSourceText =\n\t\tpromptSource === \"config\"\n\t\t\t? \"config custom prompt\"\n\t\t\t: promptSource === \"heartbeat_md\"\n\t\t\t\t? \"HEARTBEAT.md\"\n\t\t\t\t: \"none (heartbeat inactive)\";\n\n\treturn (\n\t\t<div className=\"heartbeat-form\" style={{ maxWidth: \"600px\" }}>\n\t\t\t<div className=\"flex items-center justify-between mb-2\">\n\t\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Heartbeat</h2>\n\t\t\t\t\t<label className=\"cron-toggle\">\n\t\t\t\t\t\t<input data-hb=\"enabled\" type=\"checkbox\" checked={cfg.enabled !== false} onChange={onToggleEnabled} />\n\t\t\t\t\t\t<span className=\"cron-slider\" />\n\t\t\t\t\t</label>\n\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">Enable</span>\n\t\t\t\t</div>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\tonClick={onRunNow}\n\t\t\t\t\tdisabled={runNowDisabled}\n\t\t\t\t\ttitle={runBlockedReason || undefined}\n\t\t\t\t>\n\t\t\t\t\t{running ? \"Running\\u2026\" : \"Run Now\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<p className=\"text-sm text-[var(--muted)] mb-4\">\n\t\t\t\tPeriodic AI check-in that monitors your environment and reports status.\n\t\t\t</p>\n\t\t\t{runBlockedReason && (\n\t\t\t\t<div className=\"alert-info-text max-w-form mb-4\">\n\t\t\t\t\t<span className=\"alert-label-info\">Heartbeat inactive:</span> {runBlockedReason}\n\t\t\t\t</div>\n\t\t\t)}\n\t\t\t<HeartbeatJobStatus job={job} />\n\n\t\t\t{/* Schedule */}\n\t\t\t<div style={{ marginTop: \"24px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Schedule</h3>\n\t\t\t\t<div className=\"grid gap-4\" style={{ gridTemplateColumns: \"1fr 1fr\" }}>\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<label className=\"block text-xs text-[var(--muted)] mb-1\">Interval</label>\n\t\t\t\t\t\t<input data-hb=\"every\" className=\"provider-key-input\" placeholder=\"30m\" value={cfg.every || \"30m\"} />\n\t\t\t\t\t</div>\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<label className=\"block text-xs text-[var(--muted)] mb-1\">Model</label>\n\t\t\t\t\t\t<ModelSelect\n\t\t\t\t\t\t\tmodels={modelsSig.value}\n\t\t\t\t\t\t\tvalue={heartbeatModel.value}\n\t\t\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\t\t\theartbeatModel.value = v;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\tplaceholder={defaultModelPlaceholder()}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t{/* Prompt */}\n\t\t\t<div style={{ marginTop: \"24px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Prompt</h3>\n\t\t\t\t<label className=\"block text-xs text-[var(--muted)] mb-1\">Custom Prompt (optional)</label>\n\t\t\t\t<textarea\n\t\t\t\t\tdata-hb=\"prompt\"\n\t\t\t\t\tclassName=\"provider-key-input textarea-sm\"\n\t\t\t\t\tplaceholder=\"Leave blank to use default heartbeat prompt\"\n\t\t\t\t>\n\t\t\t\t\t{cfg.prompt || \"\"}\n\t\t\t\t</textarea>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] mt-2\">\n\t\t\t\t\tLeave this empty to use <code>HEARTBEAT.md</code> in your workspace root. If that file exists but is\n\t\t\t\t\tempty/comments-only, heartbeat LLM runs are skipped to save tokens.\n\t\t\t\t</p>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] mt-1\">\n\t\t\t\t\tEffective prompt source: <span className=\"text-[var(--text)]\">{promptSourceText}</span>\n\t\t\t\t</p>\n\t\t\t\t<div className=\"grid gap-4 mt-3\" style={{ gridTemplateColumns: \"1fr\" }}>\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<label className=\"block text-xs text-[var(--muted)] mb-1\">Max Response Characters</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tdata-hb=\"ackMax\"\n\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\ttype=\"number\"\n\t\t\t\t\t\t\tmin=\"50\"\n\t\t\t\t\t\t\tvalue={cfg.ack_max_chars || 300}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t{/* Delivery */}\n\t\t\t<div style={{ marginTop: \"24px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Delivery</h3>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] mb-3\">Send heartbeat replies to a channel/chat destination.</p>\n\t\t\t\t<div className=\"flex items-center gap-3 mb-3\">\n\t\t\t\t\t<label className=\"cron-toggle\">\n\t\t\t\t\t\t<input data-hb=\"deliver\" type=\"checkbox\" checked={cfg.deliver === true} />\n\t\t\t\t\t\t<span className=\"cron-slider\" />\n\t\t\t\t\t</label>\n\t\t\t\t\t<span className=\"text-sm text-[var(--text)]\">Deliver to channel</span>\n\t\t\t\t</div>\n\t\t\t\t<div className=\"grid gap-4\" style={{ gridTemplateColumns: \"1fr 1fr\" }}>\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<label className=\"block text-xs text-[var(--muted)] mb-1\">Channel Account</label>\n\t\t\t\t\t\t<input data-hb=\"channel\" className=\"provider-key-input\" placeholder=\"my-bot\" value={cfg.channel || \"\"} />\n\t\t\t\t\t</div>\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<label className=\"block text-xs text-[var(--muted)] mb-1\">Chat ID</label>\n\t\t\t\t\t\t<input data-hb=\"to\" className=\"provider-key-input\" placeholder=\"123456789\" value={cfg.to || \"\"} />\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] mt-2\">\n\t\t\t\t\tRequired when delivery is enabled. Account is your configured channel account id, chat ID is the destination\n\t\t\t\t\trecipient/group id.\n\t\t\t\t</p>\n\t\t\t</div>\n\n\t\t\t{/* Active Hours */}\n\t\t\t<div style={{ marginTop: \"24px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Active Hours</h3>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] mb-3\">Only run heartbeat during these hours.</p>\n\t\t\t\t<div className=\"grid gap-4\" style={{ gridTemplateColumns: \"1fr 1fr\" }}>\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<label className=\"block text-xs text-[var(--muted)] mb-1\">Start</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tdata-hb=\"ahStart\"\n\t\t\t\t\t\t\ttype=\"time\"\n\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\tvalue={cfg.active_hours?.start || \"08:00\"}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<label className=\"block text-xs text-[var(--muted)] mb-1\">End</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tdata-hb=\"ahEnd\"\n\t\t\t\t\t\t\ttype=\"time\"\n\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\tvalue={cfg.active_hours?.end === \"24:00\" ? \"23:59\" : cfg.active_hours?.end || \"23:59\"}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t<div className=\"mt-3\">\n\t\t\t\t\t<label className=\"block text-xs text-[var(--muted)] mb-1\">Timezone</label>\n\t\t\t\t\t<select data-hb=\"ahTz\" className=\"provider-key-input\">\n\t\t\t\t\t\t<option value=\"local\" selected={!cfg.active_hours?.timezone || cfg.active_hours?.timezone === \"local\"}>\n\t\t\t\t\t\t\tLocal ({systemTimezone})\n\t\t\t\t\t\t</option>\n\t\t\t\t\t\t<option value=\"UTC\" selected={cfg.active_hours?.timezone === \"UTC\"}>\n\t\t\t\t\t\t\tUTC\n\t\t\t\t\t\t</option>\n\t\t\t\t\t\t<option value=\"America/New_York\" selected={cfg.active_hours?.timezone === \"America/New_York\"}>\n\t\t\t\t\t\t\tAmerica/New_York (EST/EDT)\n\t\t\t\t\t\t</option>\n\t\t\t\t\t\t<option value=\"America/Chicago\" selected={cfg.active_hours?.timezone === \"America/Chicago\"}>\n\t\t\t\t\t\t\tAmerica/Chicago (CST/CDT)\n\t\t\t\t\t\t</option>\n\t\t\t\t\t\t<option value=\"America/Denver\" selected={cfg.active_hours?.timezone === \"America/Denver\"}>\n\t\t\t\t\t\t\tAmerica/Denver (MST/MDT)\n\t\t\t\t\t\t</option>\n\t\t\t\t\t\t<option value=\"America/Los_Angeles\" selected={cfg.active_hours?.timezone === \"America/Los_Angeles\"}>\n\t\t\t\t\t\t\tAmerica/Los_Angeles (PST/PDT)\n\t\t\t\t\t\t</option>\n\t\t\t\t\t\t<option value=\"Europe/London\" selected={cfg.active_hours?.timezone === \"Europe/London\"}>\n\t\t\t\t\t\t\tEurope/London (GMT/BST)\n\t\t\t\t\t\t</option>\n\t\t\t\t\t\t<option value=\"Europe/Paris\" selected={cfg.active_hours?.timezone === \"Europe/Paris\"}>\n\t\t\t\t\t\t\tEurope/Paris (CET/CEST)\n\t\t\t\t\t\t</option>\n\t\t\t\t\t\t<option value=\"Europe/Berlin\" selected={cfg.active_hours?.timezone === \"Europe/Berlin\"}>\n\t\t\t\t\t\t\tEurope/Berlin (CET/CEST)\n\t\t\t\t\t\t</option>\n\t\t\t\t\t\t<option value=\"Asia/Tokyo\" selected={cfg.active_hours?.timezone === \"Asia/Tokyo\"}>\n\t\t\t\t\t\t\tAsia/Tokyo (JST)\n\t\t\t\t\t\t</option>\n\t\t\t\t\t\t<option value=\"Asia/Shanghai\" selected={cfg.active_hours?.timezone === \"Asia/Shanghai\"}>\n\t\t\t\t\t\t\tAsia/Shanghai (CST)\n\t\t\t\t\t\t</option>\n\t\t\t\t\t\t<option value=\"Asia/Singapore\" selected={cfg.active_hours?.timezone === \"Asia/Singapore\"}>\n\t\t\t\t\t\t\tAsia/Singapore (SGT)\n\t\t\t\t\t\t</option>\n\t\t\t\t\t\t<option value=\"Australia/Sydney\" selected={cfg.active_hours?.timezone === \"Australia/Sydney\"}>\n\t\t\t\t\t\t\tAustralia/Sydney (AEST/AEDT)\n\t\t\t\t\t\t</option>\n\t\t\t\t\t</select>\n\t\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t{/* Sandbox */}\n\t\t\t<div style={{ marginTop: \"24px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Sandbox</h3>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] mb-3\">Run heartbeat commands in an isolated container.</p>\n\t\t\t\t<div className=\"flex items-center gap-3 mb-3\">\n\t\t\t\t\t<label className=\"cron-toggle\">\n\t\t\t\t\t\t<input data-hb=\"sandboxEnabled\" type=\"checkbox\" checked={cfg.sandbox_enabled !== false} />\n\t\t\t\t\t\t<span className=\"cron-slider\" />\n\t\t\t\t\t</label>\n\t\t\t\t\t<span className=\"text-sm text-[var(--text)]\">Enable sandbox</span>\n\t\t\t\t</div>\n\t\t\t\t<div>\n\t\t\t\t\t<label className=\"block text-xs text-[var(--muted)] mb-1\">Sandbox Image</label>\n\t\t\t\t\t<ComboSelect\n\t\t\t\t\t\toptions={sandboxImages.value.map((img) => ({ value: img.tag, label: img.tag }))}\n\t\t\t\t\t\tvalue={heartbeatSandboxImage.value}\n\t\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\t\theartbeatSandboxImage.value = v;\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tplaceholder=\"Default image\"\n\t\t\t\t\t\tsearchPlaceholder=\"Search images\\u2026\"\n\t\t\t\t\t/>\n\t\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t{/* Recent Runs */}\n\t\t\t<div style={{ marginTop: \"24px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Recent Runs</h3>\n\t\t\t\t<HeartbeatRunsList runs={heartbeatRuns.value} />\n\t\t\t</div>\n\n\t\t\t{/* Save */}\n\t\t\t<div style={{ marginTop: \"24px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t<button className=\"provider-btn\" onClick={onSave} disabled={saving}>\n\t\t\t\t\t{saving ? \"Saving\\u2026\" : \"Save\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// ── Cron Jobs ────────────────────────────────────────────────\n\nfunction StatusBar(): VNode {\n\tconst s = cronStatus.value;\n\tif (!s) return <div className=\"cron-status-bar\">Loading&hellip;</div>;\n\tconst parts = [\n\t\ts.running ? \"Running\" : \"Stopped\",\n\t\t`${s.jobCount} job${s.jobCount === 1 ? \"\" : \"s\"}`,\n\t\t`${s.enabledCount} enabled`,\n\t];\n\tif (s.nextRunAtMs) parts.push(`next: ${new Date(s.nextRunAtMs).toLocaleString()}`);\n\treturn <div className=\"cron-status-bar\">{parts.join(\" \\u2022 \")}</div>;\n}\n\nfunction CronJobRow({ job }: { job: CronJob }): VNode {\n\tconst modelLabel = job.payload?.kind === \"agentTurn\" ? job.payload.model || \"default\" : \"\\u2014\";\n\tconst deliveryLabel = job.payload?.deliver && job.payload?.channel ? `\\u2192 ${job.payload.channel}` : null;\n\tconst executionLabel =\n\t\tjob.sandbox?.enabled === false\n\t\t\t? \"host\"\n\t\t\t: job.sandbox?.image\n\t\t\t\t? `sandbox (${job.sandbox.image})`\n\t\t\t\t: \"sandbox (default)\";\n\tfunction onToggle(e: Event): void {\n\t\tsendRpc(\"cron.update\", { id: job.id, patch: { enabled: (e.target as HTMLInputElement).checked } }).then(() => {\n\t\t\tloadJobs();\n\t\t\tloadStatus();\n\t\t});\n\t}\n\tfunction onRun(): void {\n\t\tsendRpc(\"cron.run\", { id: job.id, force: true }).then(() => {\n\t\t\tloadJobs();\n\t\t\tloadStatus();\n\t\t});\n\t}\n\tfunction onDelete(): void {\n\t\trequestConfirm(`Delete job '${job.name}'?`).then((yes) => {\n\t\t\tif (yes)\n\t\t\t\tsendRpc(\"cron.remove\", { id: job.id }).then(() => {\n\t\t\t\t\tloadJobs();\n\t\t\t\t\tloadStatus();\n\t\t\t\t});\n\t\t});\n\t}\n\tfunction onHistory(): void {\n\t\trunsHistory.value = { jobId: job.id, jobName: job.name, runs: null };\n\t\tsendRpc(\"cron.runs\", { id: job.id }).then((res) => {\n\t\t\tif (res?.ok) runsHistory.value = { jobId: job.id, jobName: job.name, runs: (res.payload as CronRun[]) || [] };\n\t\t});\n\t}\n\n\treturn (\n\t\t<tr>\n\t\t\t<td>{job.name}</td>\n\t\t\t<td className=\"cron-mono\">{formatSchedule(job.schedule)}</td>\n\t\t\t<td className=\"cron-mono\">{modelLabel}</td>\n\t\t\t<td className=\"cron-mono\">{deliveryLabel ? <span className=\"text-xs\">{deliveryLabel}</span> : \"\\u2014\"}</td>\n\t\t\t<td className=\"cron-mono\">{executionLabel}</td>\n\t\t\t<td className=\"cron-mono\">\n\t\t\t\t{job.state?.nextRunAtMs ? (\n\t\t\t\t\t<time data-epoch-ms={job.state.nextRunAtMs}>{new Date(job.state.nextRunAtMs).toISOString()}</time>\n\t\t\t\t) : (\n\t\t\t\t\t\"\\u2014\"\n\t\t\t\t)}\n\t\t\t</td>\n\t\t\t<td>\n\t\t\t\t{job.state?.lastStatus ? (\n\t\t\t\t\t<span className={`cron-badge ${job.state.lastStatus}`}>{job.state.lastStatus}</span>\n\t\t\t\t) : (\n\t\t\t\t\t\"\\u2014\"\n\t\t\t\t)}\n\t\t\t</td>\n\t\t\t<td className=\"cron-actions\">\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"cron-action-btn\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\teditingJob.value = job;\n\t\t\t\t\t\tshowModal.value = true;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\tEdit\n\t\t\t\t</button>\n\t\t\t\t<button className=\"cron-action-btn\" onClick={onRun}>\n\t\t\t\t\tRun\n\t\t\t\t</button>\n\t\t\t\t<button className=\"cron-action-btn\" onClick={onHistory}>\n\t\t\t\t\tHistory\n\t\t\t\t</button>\n\t\t\t\t<button className=\"cron-action-btn cron-action-danger\" onClick={onDelete}>\n\t\t\t\t\tDelete\n\t\t\t\t</button>\n\t\t\t</td>\n\t\t\t<td>\n\t\t\t\t<label className=\"cron-toggle\">\n\t\t\t\t\t<input type=\"checkbox\" checked={job.enabled} onChange={onToggle} />\n\t\t\t\t\t<span className=\"cron-slider\" />\n\t\t\t\t</label>\n\t\t\t</td>\n\t\t</tr>\n\t);\n}\n\nfunction CronJobTable(): VNode {\n\tconst jobs = cronJobs.value.filter((j) => !j.system);\n\tif (jobs.length === 0) return <div className=\"text-sm text-[var(--muted)]\">No cron jobs configured.</div>;\n\treturn (\n\t\t<table className=\"cron-table\">\n\t\t\t<thead>\n\t\t\t\t<tr>\n\t\t\t\t\t<th>Name</th>\n\t\t\t\t\t<th>Schedule</th>\n\t\t\t\t\t<th>Model</th>\n\t\t\t\t\t<th>Delivery</th>\n\t\t\t\t\t<th>Execution</th>\n\t\t\t\t\t<th>Next Run</th>\n\t\t\t\t\t<th>Last Status</th>\n\t\t\t\t\t<th>Actions</th>\n\t\t\t\t\t<th>Enabled</th>\n\t\t\t\t</tr>\n\t\t\t</thead>\n\t\t\t<tbody>\n\t\t\t\t{jobs.map((job) => (\n\t\t\t\t\t<CronJobRow key={job.id} job={job} />\n\t\t\t\t))}\n\t\t\t</tbody>\n\t\t</table>\n\t);\n}\n\nfunction RunHistoryPanel(): VNode | null {\n\tconst h = runsHistory.value;\n\tif (!h) return null;\n\treturn (\n\t\t<div className=\"mb-md\">\n\t\t\t<div className=\"flex items-center justify-between mb-md\">\n\t\t\t\t<span className=\"text-sm font-medium text-[var(--text-strong)]\">Run History: {h.jobName}</span>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"text-xs text-[var(--muted)] cursor-pointer bg-transparent border-none hover:text-[var(--text)]\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\trunsHistory.value = null;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t&times; Close\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t{h.runs === null && <div className=\"text-sm text-[var(--muted)]\">Loading&hellip;</div>}\n\t\t\t{h.runs !== null && h.runs.length === 0 && <div className=\"text-xs text-[var(--muted)]\">No runs yet.</div>}\n\t\t\t{h.runs?.map((run) => (\n\t\t\t\t<div className=\"cron-run-item\" key={run.startedAtMs}>\n\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t<time data-epoch-ms={run.startedAtMs}>{new Date(run.startedAtMs).toISOString()}</time>\n\t\t\t\t\t</span>\n\t\t\t\t\t<span className={`cron-badge ${run.status}`}>{run.status}</span>\n\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">{run.durationMs}ms</span>\n\t\t\t\t\t<TokenBadge run={run} />\n\t\t\t\t\t{run.error && <span className=\"text-xs text-[var(--error)]\">{run.error}</span>}\n\t\t\t\t</div>\n\t\t\t))}\n\t\t</div>\n\t);\n}\n\nfunction parseScheduleFromForm(\n\tkind: string,\n\tsignals: Record<string, string>,\n): { schedule?: CronSchedule; error?: string } {\n\tif (kind === \"at\") {\n\t\tconst ts = new Date(signals.schedAtTimestamp).getTime();\n\t\tif (Number.isNaN(ts)) return { error: \"at\" };\n\t\treturn { schedule: { kind: \"at\", at_ms: ts } };\n\t}\n\tif (kind === \"every\") {\n\t\tconst secs = parseInt(signals.schedEverySecs, 10);\n\t\tif (Number.isNaN(secs) || secs <= 0) return { error: \"every\" };\n\t\treturn { schedule: { kind: \"every\", every_ms: secs * 1000 } };\n\t}\n\tconst expr = signals.schedCronExpr.trim();\n\tif (!expr) return { error: \"cron\" };\n\tconst schedule: CronSchedule = { kind: \"cron\", expr };\n\tconst tz = signals.schedCronTz.trim();\n\tif (tz) schedule.tz = tz;\n\treturn { schedule };\n}\n\nfunction CronModal(): VNode {\n\tconst isEdit = !!editingJob.value;\n\tconst job = editingJob.value;\n\tconst saving = useSignal(false);\n\tconst schedKind = useSignal(\"cron\");\n\tconst errorField = useSignal<string | null>(null);\n\tconst jobModel = useSignal(\"\");\n\tconst jobSandboxImage = useSignal(\"\");\n\tconst jobName = useSignal(\"\");\n\tconst payloadKind = useSignal(\"systemEvent\");\n\tconst sessionTarget = useSignal(\"main\");\n\tconst messageText = useSignal(\"\");\n\tconst executionTarget = useSignal(\"sandbox\");\n\tconst deleteAfterRun = useSignal(false);\n\tconst jobEnabled = useSignal(true);\n\tconst deliverToChannel = useSignal(false);\n\tconst deliverChannel = useSignal(\"\");\n\tconst deliverTo = useSignal(\"\");\n\tconst schedCronExpr = useSignal(\"\");\n\tconst schedCronTz = useSignal(\"\");\n\tconst schedEverySecs = useSignal(\"\");\n\tconst schedAtTimestamp = useSignal(\"\");\n\n\tuseEffect(() => {\n\t\tif (editingJob.value) {\n\t\t\tconst j = editingJob.value;\n\t\t\tsaving.value = false;\n\t\t\terrorField.value = null;\n\t\t\tschedKind.value = j.schedule.kind;\n\t\t\tjobModel.value = j.payload.kind === \"agentTurn\" ? j.payload.model || \"\" : \"\";\n\t\t\tjobSandboxImage.value = j.sandbox?.image || \"\";\n\t\t\tjobName.value = j.name;\n\t\t\tpayloadKind.value = j.payload.kind;\n\t\t\tsessionTarget.value = j.sessionTarget || \"main\";\n\t\t\tmessageText.value = j.payload.text || j.payload.message || \"\";\n\t\t\texecutionTarget.value = j.sandbox?.enabled === false ? \"host\" : \"sandbox\";\n\t\t\tdeleteAfterRun.value = !!j.deleteAfterRun;\n\t\t\tjobEnabled.value = j.enabled;\n\t\t\tdeliverToChannel.value = j.payload?.deliver === true;\n\t\t\tdeliverChannel.value = j.payload?.channel || \"\";\n\t\t\tdeliverTo.value = j.payload?.to || \"\";\n\t\t\tschedCronExpr.value = j.schedule.kind === \"cron\" ? j.schedule.expr || \"\" : \"\";\n\t\t\tschedCronTz.value = j.schedule.kind === \"cron\" ? j.schedule.tz || \"\" : \"\";\n\t\t\tschedEverySecs.value = j.schedule.kind === \"every\" ? String(Math.round(j.schedule.every_ms! / 1000)) : \"\";\n\t\t\tschedAtTimestamp.value = j.schedule.kind === \"at\" ? new Date(j.schedule.at_ms!).toISOString().slice(0, 16) : \"\";\n\t\t} else {\n\t\t\tsaving.value = false;\n\t\t\terrorField.value = null;\n\t\t\tschedKind.value = \"cron\";\n\t\t\tjobModel.value = \"\";\n\t\t\tjobSandboxImage.value = \"\";\n\t\t\tjobName.value = \"\";\n\t\t\tpayloadKind.value = \"systemEvent\";\n\t\t\tsessionTarget.value = \"main\";\n\t\t\tmessageText.value = \"\";\n\t\t\texecutionTarget.value = \"sandbox\";\n\t\t\tdeleteAfterRun.value = false;\n\t\t\tjobEnabled.value = true;\n\t\t\tdeliverToChannel.value = false;\n\t\t\tdeliverChannel.value = \"\";\n\t\t\tdeliverTo.value = \"\";\n\t\t\tschedCronExpr.value = \"\";\n\t\t\tschedCronTz.value = \"\";\n\t\t\tschedEverySecs.value = \"\";\n\t\t\tschedAtTimestamp.value = \"\";\n\t\t}\n\t}, [editingJob.value]);\n\n\tfunction onSave(e: Event): void {\n\t\te.preventDefault();\n\t\tconst name = jobName.value.trim();\n\t\tif (!name) {\n\t\t\terrorField.value = \"name\";\n\t\t\treturn;\n\t\t}\n\t\tconst parsed = parseScheduleFromForm(schedKind.value, {\n\t\t\tschedCronExpr: schedCronExpr.value,\n\t\t\tschedCronTz: schedCronTz.value,\n\t\t\tschedEverySecs: schedEverySecs.value,\n\t\t\tschedAtTimestamp: schedAtTimestamp.value,\n\t\t});\n\t\tif (parsed.error) {\n\t\t\terrorField.value = parsed.error;\n\t\t\treturn;\n\t\t}\n\t\tconst msgText = messageText.value.trim();\n\t\tif (!msgText) {\n\t\t\terrorField.value = \"message\";\n\t\t\treturn;\n\t\t}\n\t\tconst pk = payloadKind.value;\n\t\tconst payload: Record<string, unknown> =\n\t\t\tpk === \"systemEvent\"\n\t\t\t\t? { kind: \"systemEvent\", text: msgText }\n\t\t\t\t: {\n\t\t\t\t\t\tkind: \"agentTurn\",\n\t\t\t\t\t\tmessage: msgText,\n\t\t\t\t\t\tdeliver: deliverToChannel.value,\n\t\t\t\t\t\t...(deliverToChannel.value && deliverChannel.value ? { channel: deliverChannel.value } : {}),\n\t\t\t\t\t\t...(deliverToChannel.value && deliverTo.value.trim() ? { to: deliverTo.value.trim() } : {}),\n\t\t\t\t\t};\n\t\tif (pk === \"agentTurn\" && jobModel.value) payload.model = jobModel.value;\n\t\tconst sandboxEnabled = executionTarget.value === \"sandbox\";\n\t\tconst fields = {\n\t\t\tname,\n\t\t\tschedule: parsed.schedule,\n\t\t\tpayload,\n\t\t\tsessionTarget: sessionTarget.value,\n\t\t\tdeleteAfterRun: deleteAfterRun.value,\n\t\t\tenabled: jobEnabled.value,\n\t\t\tsandbox: { enabled: sandboxEnabled, image: sandboxEnabled ? jobSandboxImage.value || null : null },\n\t\t};\n\t\tsaving.value = true;\n\t\tconst rpcMethod = isEdit ? \"cron.update\" : \"cron.add\";\n\t\tconst rpcParams = isEdit ? { id: job!.id, patch: fields } : fields;\n\t\tsendRpc(rpcMethod, rpcParams).then((res) => {\n\t\t\tsaving.value = false;\n\t\t\tif (res?.ok) {\n\t\t\t\tshowModal.value = false;\n\t\t\t\teditingJob.value = null;\n\t\t\t\tloadJobs();\n\t\t\t\tloadStatus();\n\t\t\t}\n\t\t});\n\t}\n\n\tfunction schedParams(): VNode {\n\t\tif (schedKind.value === \"at\")\n\t\t\treturn (\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"at\"\n\t\t\t\t\tclassName={`provider-key-input ${errorField.value === \"at\" ? \"field-error\" : \"\"}`}\n\t\t\t\t\ttype=\"datetime-local\"\n\t\t\t\t\tvalue={schedAtTimestamp.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\tschedAtTimestamp.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t);\n\t\tif (schedKind.value === \"every\")\n\t\t\treturn (\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"every\"\n\t\t\t\t\tclassName={`provider-key-input ${errorField.value === \"every\" ? \"field-error\" : \"\"}`}\n\t\t\t\t\ttype=\"number\"\n\t\t\t\t\tplaceholder=\"Interval in seconds\"\n\t\t\t\t\tmin=\"1\"\n\t\t\t\t\tvalue={schedEverySecs.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\tschedEverySecs.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t);\n\t\treturn (\n\t\t\t<>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"cron\"\n\t\t\t\t\tclassName={`provider-key-input ${errorField.value === \"cron\" ? \"field-error\" : \"\"}`}\n\t\t\t\t\tplaceholder=\"*/5 * * * *\"\n\t\t\t\t\tvalue={schedCronExpr.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\tschedCronExpr.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"tz\"\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tplaceholder=\"Timezone (optional, e.g. Europe/Paris)\"\n\t\t\t\t\tvalue={schedCronTz.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\tschedCronTz.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] mt-1\">{cronTimezoneHelpText()}</p>\n\t\t\t</>\n\t\t);\n\t}\n\n\treturn (\n\t\t<Modal\n\t\t\tshow={showModal.value}\n\t\t\tonClose={() => {\n\t\t\t\tshowModal.value = false;\n\t\t\t\teditingJob.value = null;\n\t\t\t}}\n\t\t\ttitle={isEdit ? \"Edit Job\" : \"Add Job\"}\n\t\t>\n\t\t\t<div className=\"provider-key-form\">\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Name</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"name\"\n\t\t\t\t\tclassName={`provider-key-input ${errorField.value === \"name\" ? \"field-error\" : \"\"}`}\n\t\t\t\t\tplaceholder=\"Job name\"\n\t\t\t\t\tvalue={jobName.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\tjobName.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Schedule Type</label>\n\t\t\t\t<select\n\t\t\t\t\tdata-field=\"schedKind\"\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={schedKind.value}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\tschedKind.value = (e.target as HTMLSelectElement).value;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<option value=\"at\">Run Once</option>\n\t\t\t\t\t<option value=\"every\">Every (interval)</option>\n\t\t\t\t\t<option value=\"cron\">Cron (expression)</option>\n\t\t\t\t</select>\n\t\t\t\t{schedParams()}\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Payload Type</label>\n\t\t\t\t<select\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={payloadKind.value}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\tpayloadKind.value = (e.target as HTMLSelectElement).value;\n\t\t\t\t\t\tsessionTarget.value = (e.target as HTMLSelectElement).value === \"systemEvent\" ? \"main\" : \"isolated\";\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<option value=\"systemEvent\">System Event</option>\n\t\t\t\t\t<option value=\"agentTurn\">Agent Turn</option>\n\t\t\t\t</select>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Message</label>\n\t\t\t\t<textarea\n\t\t\t\t\tclassName={`provider-key-input textarea-sm ${errorField.value === \"message\" ? \"field-error\" : \"\"}`}\n\t\t\t\t\tplaceholder={\n\t\t\t\t\t\tpayloadKind.value === \"agentTurn\" ? \"Prompt sent to the agent\" : \"Message sent to the main session\"\n\t\t\t\t\t}\n\t\t\t\t\tvalue={messageText.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\tmessageText.value = (e.target as HTMLTextAreaElement).value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Model (Agent Turn)</label>\n\t\t\t\t<ModelSelect\n\t\t\t\t\tmodels={modelsSig.value}\n\t\t\t\t\tvalue={jobModel.value}\n\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\tjobModel.value = v;\n\t\t\t\t\t}}\n\t\t\t\t\tplaceholder={defaultModelPlaceholder()}\n\t\t\t\t/>\n\n\t\t\t\t{payloadKind.value === \"agentTurn\" && (\n\t\t\t\t\t<div style={{ marginTop: \"12px\", borderTop: \"1px solid var(--border)\", paddingTop: \"12px\" }}>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)] flex items-center gap-2\">\n\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\ttype=\"checkbox\"\n\t\t\t\t\t\t\t\tchecked={deliverToChannel.value}\n\t\t\t\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\t\t\t\tdeliverToChannel.value = (e.target as HTMLInputElement).checked;\n\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t/>{\" \"}\n\t\t\t\t\t\t\tDeliver output to channel\n\t\t\t\t\t\t</label>\n\t\t\t\t\t\t{deliverToChannel.value && (\n\t\t\t\t\t\t\t<>\n\t\t\t\t\t\t\t\t<div className=\"mt-3\">\n\t\t\t\t\t\t\t\t\t<label className=\"block text-xs text-[var(--muted)] mb-1\">Channel Account</label>\n\t\t\t\t\t\t\t\t\t<ComboSelect\n\t\t\t\t\t\t\t\t\t\toptions={channelAccounts.value.map((c) => ({ value: c.account_id, label: c.name || c.account_id }))}\n\t\t\t\t\t\t\t\t\t\tvalue={deliverChannel.value}\n\t\t\t\t\t\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\t\t\t\t\t\tdeliverChannel.value = v;\n\t\t\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\t\t\tplaceholder=\"Select channel account\"\n\t\t\t\t\t\t\t\t\t\tsearchPlaceholder=\"Search channels\\u2026\"\n\t\t\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t<div className=\"mt-3\">\n\t\t\t\t\t\t\t\t\t<label className=\"block text-xs text-[var(--muted)] mb-1\">Chat ID (recipient)</label>\n\t\t\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\t\t\t\tplaceholder=\"Telegram chat_id\"\n\t\t\t\t\t\t\t\t\t\tvalue={deliverTo.value}\n\t\t\t\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\t\t\t\tdeliverTo.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t</>\n\t\t\t\t\t\t)}\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Session Target</label>\n\t\t\t\t<select\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={sessionTarget.value}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\tsessionTarget.value = (e.target as HTMLSelectElement).value;\n\t\t\t\t\t\tpayloadKind.value = (e.target as HTMLSelectElement).value === \"main\" ? \"systemEvent\" : \"agentTurn\";\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<option value=\"isolated\">Isolated</option>\n\t\t\t\t\t<option value=\"main\">Main</option>\n\t\t\t\t</select>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Execution Target</label>\n\t\t\t\t<select\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={executionTarget.value}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\texecutionTarget.value = (e.target as HTMLSelectElement).value;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<option value=\"sandbox\">Sandbox</option>\n\t\t\t\t\t<option value=\"host\">Host</option>\n\t\t\t\t</select>\n\t\t\t\t<div>\n\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Sandbox Image</label>\n\t\t\t\t\t<ComboSelect\n\t\t\t\t\t\toptions={sandboxImages.value.map((img) => ({ value: img.tag, label: img.tag }))}\n\t\t\t\t\t\tvalue={jobSandboxImage.value}\n\t\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\t\tjobSandboxImage.value = v;\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tplaceholder=\"Default image\"\n\t\t\t\t\t\tsearchPlaceholder=\"Search images\\u2026\"\n\t\t\t\t\t/>\n\t\t\t\t</div>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)] flex items-center gap-2\">\n\t\t\t\t\t<input\n\t\t\t\t\t\ttype=\"checkbox\"\n\t\t\t\t\t\tchecked={deleteAfterRun.value}\n\t\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\t\tdeleteAfterRun.value = (e.target as HTMLInputElement).checked;\n\t\t\t\t\t\t}}\n\t\t\t\t\t/>{\" \"}\n\t\t\t\t\tDelete after run\n\t\t\t\t</label>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)] flex items-center gap-2\">\n\t\t\t\t\t<input\n\t\t\t\t\t\ttype=\"checkbox\"\n\t\t\t\t\t\tchecked={jobEnabled.value}\n\t\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\t\tjobEnabled.value = (e.target as HTMLInputElement).checked;\n\t\t\t\t\t\t}}\n\t\t\t\t\t/>{\" \"}\n\t\t\t\t\tEnabled\n\t\t\t\t</label>\n\t\t\t\t<div className=\"btn-row-mt\">\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tshowModal.value = false;\n\t\t\t\t\t\t\teditingJob.value = null;\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\tCancel\n\t\t\t\t\t</button>\n\t\t\t\t\t<button className=\"provider-btn\" onClick={onSave} disabled={saving.value}>\n\t\t\t\t\t\t{saving.value ? \"Saving\\u2026\" : isEdit ? \"Update\" : \"Create\"}\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t</Modal>\n\t);\n}\n\n// ── Section panels ───────────────────────────────────────────\n\nfunction HeartbeatPanel(): VNode {\n\tuseEffect(() => {\n\t\tloadHeartbeatStatus();\n\t\tloadSandboxImages();\n\t\tloadHeartbeatRuns();\n\t}, []);\n\treturn (\n\t\t<div className=\"p-6\">\n\t\t\t<HeartbeatSection />\n\t\t</div>\n\t);\n}\n\nfunction CronJobsPanel(): VNode {\n\tuseEffect(() => {\n\t\tloadStatus();\n\t\tloadJobs();\n\t\tloadSandboxImages();\n\t\tloadChannelAccounts();\n\t}, []);\n\treturn (\n\t\t<div className=\"p-4 flex flex-col gap-4\">\n\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Cron Jobs</h2>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\teditingJob.value = null;\n\t\t\t\t\t\tshowModal.value = true;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t+ Add Job\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<StatusBar />\n\t\t\t<CronJobTable />\n\t\t\t<RunHistoryPanel />\n\t\t</div>\n\t);\n}\n\n// ── Main page ───────────────────────────────────────────────\n\nfunction CronsPage(): VNode {\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 overflow-y-auto\">\n\t\t\t{activeSection.value === \"jobs\" && <CronJobsPanel />}\n\t\t\t{activeSection.value === \"heartbeat\" && <HeartbeatPanel />}\n\t\t\t<CronModal />\n\t\t\t<ConfirmDialog />\n\t\t</div>\n\t);\n}\n\nexport function initCrons(container: HTMLElement, param?: string | null): void {\n\t_cronsContainer = container;\n\tcontainer.style.cssText = \"padding:0;overflow:hidden;\";\n\tcronJobs.value = (gon.get(\"crons\") as CronJob[] | null) || [];\n\tcronStatus.value = gon.get(\"cron_status\") as CronStatusInfo | null;\n\theartbeatConfig.value = (gon.get(\"heartbeat_config\") as HeartbeatConfig | null) || {};\n\trunsHistory.value = null;\n\tshowModal.value = false;\n\teditingJob.value = null;\n\theartbeatStatus.value = null;\n\theartbeatRuns.value = (gon.get(\"heartbeat_runs\") as CronRun[] | null) || [];\n\tsandboxImages.value = [];\n\tchannelAccounts.value = [];\n\theartbeatModel.value = (gon.get(\"heartbeat_config\") as HeartbeatConfig | null)?.model || \"\";\n\theartbeatSandboxImage.value = (gon.get(\"heartbeat_config\") as HeartbeatConfig | null)?.sandbox_image || \"\";\n\tactiveSection.value = param === \"heartbeat\" ? \"heartbeat\" : \"jobs\";\n\tloadHeartbeatRuns();\n\tloadHeartbeatStatus();\n\trender(<CronsPage />, container);\n}\n\nexport function teardownCrons(): void {\n\tif (_cronsContainer) render(null, _cronsContainer);\n\t_cronsContainer = null;\n}\n","// ── Projects page (Preact + Signals) ──────────────────────────\n\nimport { signal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect, useRef } from \"preact/hooks\";\nimport { sendRpc } from \"../helpers\";\nimport { t } from \"../i18n\";\nimport { fetchProjects } from \"../projects\";\nimport { registerPage } from \"../router\";\nimport { routes } from \"../routes\";\nimport * as S from \"../state\";\nimport { projects as projectsSig } from \"../stores/project-store\";\nimport { ConfirmDialog, requestConfirm } from \"../ui\";\n\ninterface Project {\n\tid: string;\n\tlabel: string;\n\tdirectory: string;\n\tsystem_prompt?: string | null;\n\tsetup_command?: string | null;\n\tteardown_command?: string | null;\n\tbranch_prefix?: string | null;\n\tauto_worktree?: boolean;\n\tsandbox_image?: string | null;\n\tdetected?: boolean;\n\tcreated_at?: number;\n\tupdated_at?: number;\n}\n\ninterface CachedImage {\n\ttag: string;\n}\n\ninterface PathInputProps {\n\tonAdd: (dir: string) => Promise<void>;\n}\n\ninterface ProjectEditFormProps {\n\tproject: Project;\n}\n\ninterface ProjectCardProps {\n\tproject: Project;\n}\n\nconst completions = signal<string[]>([]);\nconst editingProject = signal<string | null>(null);\nconst detecting = signal(false);\nconst clearing = signal(false);\nlet _projectsContainer: HTMLElement | null = null;\n\nfunction PathInput(props: PathInputProps): VNode {\n\tconst inputRef = useRef<HTMLInputElement>(null);\n\tconst timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);\n\n\tfunction onInput(): void {\n\t\tif (timerRef.current != null) clearTimeout(timerRef.current);\n\t\ttimerRef.current = setTimeout(() => {\n\t\t\tconst val = inputRef.current?.value || \"\";\n\t\t\tif (val.length < 2) {\n\t\t\t\tcompletions.value = [];\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tsendRpc(\"projects.complete_path\", { partial: val }).then((res) => {\n\t\t\t\tif (!res?.ok) {\n\t\t\t\t\tcompletions.value = [];\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tcompletions.value = (res.payload as string[]) || [];\n\t\t\t});\n\t\t}, 200);\n\t}\n\n\tfunction selectPath(p: string): void {\n\t\tif (inputRef.current) {\n\t\t\tinputRef.current.value = `${p}/`;\n\t\t\tinputRef.current.focus();\n\t\t}\n\t\tcompletions.value = [];\n\t\tonInput();\n\t}\n\n\treturn (\n\t\t<div className=\"project-dir-group\">\n\t\t\t<div className=\"text-xs text-[var(--muted)] mb-1\">{t(\"projects:pathInput.directory\")}</div>\n\t\t\t<div className=\"flex gap-2 items-center\">\n\t\t\t\t<input\n\t\t\t\t\tref={inputRef}\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tclassName=\"provider-key-input flex-1\"\n\t\t\t\t\tplaceholder={t(\"projects:pathInput.placeholder\")}\n\t\t\t\t\tstyle={{ fontFamily: \"var(--font-mono)\" }}\n\t\t\t\t\tonInput={onInput}\n\t\t\t\t/>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tconst dir = inputRef.current?.value.trim();\n\t\t\t\t\t\tif (!dir) return;\n\t\t\t\t\t\tprops.onAdd(dir).then(() => {\n\t\t\t\t\t\t\tif (inputRef.current) inputRef.current.value = \"\";\n\t\t\t\t\t\t});\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{t(\"common:actions.add\")}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t{completions.value.length > 0 && (\n\t\t\t\t<div className=\"project-completion\" style={{ display: \"block\" }}>\n\t\t\t\t\t{completions.value.map((p) => (\n\t\t\t\t\t\t<div key={p} className=\"project-completion-item\" onClick={() => selectPath(p)}>\n\t\t\t\t\t\t\t{p}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t))}\n\t\t\t\t</div>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\nconst cachedImages = signal<CachedImage[]>([]);\n\nfunction fetchCachedImages(): void {\n\tfetch(\"/api/images/cached\")\n\t\t.then((r) => (r.ok ? r.json() : { images: [] }))\n\t\t.then((data: { images?: CachedImage[] }) => {\n\t\t\tcachedImages.value = data.images || [];\n\t\t})\n\t\t.catch(() => {\n\t\t\tcachedImages.value = [];\n\t\t});\n}\n\nfunction ProjectEditForm(props: ProjectEditFormProps): VNode {\n\tconst p = props.project;\n\tconst labelRef = useRef<HTMLInputElement>(null);\n\tconst dirRef = useRef<HTMLInputElement>(null);\n\tconst promptRef = useRef<HTMLTextAreaElement>(null);\n\tconst setupRef = useRef<HTMLInputElement>(null);\n\tconst teardownRef = useRef<HTMLInputElement>(null);\n\tconst prefixRef = useRef<HTMLInputElement>(null);\n\tconst wtRef = useRef<HTMLInputElement>(null);\n\tconst imageRef = useRef<HTMLInputElement>(null);\n\n\tuseEffect(() => {\n\t\tfetchCachedImages();\n\t}, []);\n\n\tfunction onSave(): void {\n\t\tconst updated: Project = JSON.parse(JSON.stringify(p));\n\t\tupdated.label = labelRef.current?.value.trim() || p.label;\n\t\tupdated.directory = dirRef.current?.value.trim() || p.directory;\n\t\tupdated.system_prompt = promptRef.current?.value.trim() || null;\n\t\tupdated.setup_command = setupRef.current?.value.trim() || null;\n\t\tupdated.teardown_command = teardownRef.current?.value.trim() || null;\n\t\tupdated.branch_prefix = prefixRef.current?.value.trim() || null;\n\t\tupdated.auto_worktree = wtRef.current?.checked;\n\t\tupdated.sandbox_image = imageRef.current?.value.trim() || null;\n\t\tupdated.updated_at = Date.now();\n\t\tsendRpc(\"projects.upsert\", updated).then(() => {\n\t\t\teditingProject.value = null;\n\t\t\tfetchProjects();\n\t\t});\n\t}\n\n\tfunction field(\n\t\tlabel: string,\n\t\tref: { current: HTMLInputElement | null },\n\t\tvalue: string | null | undefined,\n\t\tplaceholder: string,\n\t\tmono?: boolean,\n\t): VNode {\n\t\treturn (\n\t\t\t<div className=\"project-edit-group\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)] project-edit-label\">{label}</div>\n\t\t\t\t<input\n\t\t\t\t\tref={ref}\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={value || \"\"}\n\t\t\t\t\tplaceholder={placeholder || \"\"}\n\t\t\t\t\tstyle={mono ? { fontFamily: \"var(--font-mono)\", width: \"100%\" } : { width: \"100%\" }}\n\t\t\t\t/>\n\t\t\t</div>\n\t\t);\n\t}\n\n\treturn (\n\t\t<div className=\"project-edit-form\">\n\t\t\t{field(t(\"projects:editForm.label\"), labelRef, p.label, t(\"projects:editForm.labelPlaceholder\"))}\n\t\t\t{field(t(\"projects:editForm.directory\"), dirRef, p.directory, t(\"projects:editForm.directoryPlaceholder\"), true)}\n\t\t\t<div className=\"project-edit-group\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)] project-edit-label\">{t(\"projects:editForm.systemPrompt\")}</div>\n\t\t\t\t<textarea\n\t\t\t\t\tref={promptRef}\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tplaceholder={t(\"projects:editForm.systemPromptPlaceholder\")}\n\t\t\t\t\tstyle={{ width: \"100%\", minHeight: \"60px\", resize: \"vertical\", fontSize: \".8rem\" }}\n\t\t\t\t>\n\t\t\t\t\t{p.system_prompt || \"\"}\n\t\t\t\t</textarea>\n\t\t\t</div>\n\t\t\t{field(\n\t\t\t\tt(\"projects:editForm.setupCommand\"),\n\t\t\t\tsetupRef,\n\t\t\t\tp.setup_command,\n\t\t\t\tt(\"projects:editForm.setupCommandPlaceholder\"),\n\t\t\t\ttrue,\n\t\t\t)}\n\t\t\t{field(\n\t\t\t\tt(\"projects:editForm.teardownCommand\"),\n\t\t\t\tteardownRef,\n\t\t\t\tp.teardown_command,\n\t\t\t\tt(\"projects:editForm.teardownCommandPlaceholder\"),\n\t\t\t\ttrue,\n\t\t\t)}\n\t\t\t{field(\n\t\t\t\tt(\"projects:editForm.branchPrefix\"),\n\t\t\t\tprefixRef,\n\t\t\t\tp.branch_prefix,\n\t\t\t\tt(\"projects:editForm.branchPrefixPlaceholder\"),\n\t\t\t\ttrue,\n\t\t\t)}\n\t\t\t<div className=\"project-edit-group\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)] project-edit-label\">{t(\"projects:editForm.sandboxImage\")}</div>\n\t\t\t\t<input\n\t\t\t\t\tref={imageRef}\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tlist=\"project-image-list\"\n\t\t\t\t\tvalue={p.sandbox_image || \"\"}\n\t\t\t\t\tplaceholder={t(\"projects:editForm.sandboxImagePlaceholder\")}\n\t\t\t\t\tstyle={{ width: \"100%\", fontFamily: \"var(--font-mono)\", fontSize: \".8rem\" }}\n\t\t\t\t/>\n\t\t\t\t<datalist id=\"project-image-list\">\n\t\t\t\t\t{cachedImages.value.map((img) => (\n\t\t\t\t\t\t<option key={img.tag} value={img.tag} />\n\t\t\t\t\t))}\n\t\t\t\t</datalist>\n\t\t\t</div>\n\t\t\t<div style={{ marginBottom: \"10px\", display: \"flex\", alignItems: \"center\", gap: \"8px\" }}>\n\t\t\t\t<input ref={wtRef} type=\"checkbox\" checked={p.auto_worktree} />\n\t\t\t\t<span className=\"text-xs text-[var(--text)]\">{t(\"projects:editForm.autoWorktree\")}</span>\n\t\t\t</div>\n\t\t\t<div style={{ display: \"flex\", gap: \"8px\" }}>\n\t\t\t\t<button className=\"provider-btn\" onClick={onSave}>\n\t\t\t\t\t{t(\"common:actions.save\")}\n\t\t\t\t</button>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\teditingProject.value = null;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{t(\"common:actions.cancel\")}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nfunction ProjectCard(props: ProjectCardProps): VNode {\n\tconst p = props.project;\n\n\tfunction onDelete(): void {\n\t\tsendRpc(\"projects.delete\", { id: p.id }).then(() => fetchProjects());\n\t}\n\n\treturn (\n\t\t<div className=\"provider-item\" style={{ marginBottom: \"6px\" }}>\n\t\t\t<div style={{ flex: 1, minWidth: 0 }}>\n\t\t\t\t<div className=\"flex items-center gap-2\">\n\t\t\t\t\t<div className=\"provider-item-name\">{p.label || p.id}</div>\n\t\t\t\t\t{p.detected && <span className=\"provider-item-badge api-key\">{t(\"projects:badges.auto\")}</span>}\n\t\t\t\t\t{p.auto_worktree && <span className=\"provider-item-badge oauth\">{t(\"projects:badges.worktree\")}</span>}\n\t\t\t\t\t{p.setup_command && <span className=\"provider-item-badge api-key\">{t(\"projects:badges.setup\")}</span>}\n\t\t\t\t\t{p.teardown_command && <span className=\"provider-item-badge api-key\">{t(\"projects:badges.teardown\")}</span>}\n\t\t\t\t\t{p.branch_prefix && <span className=\"provider-item-badge oauth\">{p.branch_prefix}/*</span>}\n\t\t\t\t\t{p.sandbox_image && (\n\t\t\t\t\t\t<span className=\"provider-item-badge api-key\" title={p.sandbox_image}>\n\t\t\t\t\t\t\t{t(\"projects:badges.image\")}\n\t\t\t\t\t\t</span>\n\t\t\t\t\t)}\n\t\t\t\t</div>\n\t\t\t\t<div\n\t\t\t\t\tstyle={{\n\t\t\t\t\t\tfontSize: \".72rem\",\n\t\t\t\t\t\tcolor: \"var(--muted)\",\n\t\t\t\t\t\tfontFamily: \"var(--font-mono)\",\n\t\t\t\t\t\twhiteSpace: \"nowrap\",\n\t\t\t\t\t\toverflow: \"hidden\",\n\t\t\t\t\t\ttextOverflow: \"ellipsis\",\n\t\t\t\t\t\tmarginTop: \"2px\",\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{p.directory}\n\t\t\t\t</div>\n\t\t\t\t{p.system_prompt && (\n\t\t\t\t\t<div style={{ fontSize: \".7rem\", color: \"var(--muted)\", marginTop: \"2px\", fontStyle: \"italic\" }}>\n\t\t\t\t\t\t{t(\"projects:card.systemPromptPrefix\")}\n\t\t\t\t\t\t{p.system_prompt.substring(0, 80)}\n\t\t\t\t\t\t{p.system_prompt.length > 80 ? \"...\" : \"\"}\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t</div>\n\t\t\t<div style={{ display: \"flex\", gap: \"4px\", flexShrink: 0 }}>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"session-action-btn\"\n\t\t\t\t\ttitle={t(\"projects:card.editProject\")}\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\teditingProject.value = p.id;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{t(\"projects:card.edit\")}\n\t\t\t\t</button>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"session-action-btn session-delete\"\n\t\t\t\t\ttitle={t(\"projects:card.removeProject\")}\n\t\t\t\t\tonClick={onDelete}\n\t\t\t\t>\n\t\t\t\t\tx\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nfunction ProjectsPageComponent(): VNode {\n\tuseEffect(() => {\n\t\tsendRpc(\"projects.list\", {}).then((res) => {\n\t\t\tif (res?.ok) S.setProjects((res.payload as Project[]) || []);\n\t\t});\n\t}, []);\n\n\tfunction onAdd(dir: string): Promise<void> {\n\t\treturn sendRpc(\"projects.detect\", { directories: [dir] }).then((res) => {\n\t\t\tif (res?.ok) {\n\t\t\t\tconst detected = (res.payload as Project[]) || [];\n\t\t\t\tif (detected.length === 0) {\n\t\t\t\t\tconst slug = dir.split(\"/\").filter(Boolean).pop() || \"project\";\n\t\t\t\t\tconst now = Date.now();\n\t\t\t\t\treturn sendRpc(\"projects.upsert\", {\n\t\t\t\t\t\tid: slug.toLowerCase().replace(/[^a-z0-9-]/g, \"-\"),\n\t\t\t\t\t\tlabel: slug,\n\t\t\t\t\t\tdirectory: dir,\n\t\t\t\t\t\tauto_worktree: false,\n\t\t\t\t\t\tdetected: false,\n\t\t\t\t\t\tcreated_at: now,\n\t\t\t\t\t\tupdated_at: now,\n\t\t\t\t\t}).then(() => fetchProjects()) as Promise<void>;\n\t\t\t\t}\n\t\t\t\tfetchProjects();\n\t\t\t}\n\t\t});\n\t}\n\n\tfunction onDetect(): void {\n\t\tdetecting.value = true;\n\t\tsendRpc(\"projects.detect\", { directories: [] }).then(() => {\n\t\t\tdetecting.value = false;\n\t\t\tfetchProjects();\n\t\t});\n\t}\n\n\tfunction onClearAll(): void {\n\t\tif (clearing.value) return;\n\t\trequestConfirm(t(\"projects:confirmClearAll\"), {\n\t\t\tconfirmLabel: t(\"projects:confirmClearAllButton\"),\n\t\t\tdanger: true,\n\t\t}).then((yes) => {\n\t\t\tif (!yes) return;\n\t\t\tconst ids = (projectsSig.value as unknown as Project[]).map((p) => p.id);\n\t\t\tif (ids.length === 0) return;\n\t\t\tclearing.value = true;\n\t\t\tlet chain = Promise.resolve();\n\t\t\tfor (const id of ids) {\n\t\t\t\tchain = chain.then(() => sendRpc(\"projects.delete\", { id: id }) as unknown as Promise<void>);\n\t\t\t}\n\t\t\tchain\n\t\t\t\t.then(() => fetchProjects())\n\t\t\t\t.finally(() => {\n\t\t\t\t\tclearing.value = false;\n\t\t\t\t});\n\t\t});\n\t}\n\n\tconst list = projectsSig.value as unknown as Project[];\n\tconst clearDisabled = clearing.value || detecting.value || list.length === 0;\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">{t(\"projects:title\")}</h2>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\tonClick={onDetect}\n\t\t\t\t\tdisabled={detecting.value}\n\t\t\t\t\ttitle={t(\"projects:autoDetectTooltip\")}\n\t\t\t\t>\n\t\t\t\t\t{detecting.value ? t(\"projects:detecting\") : t(\"projects:autoDetect\")}\n\t\t\t\t</button>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-danger\"\n\t\t\t\t\tonClick={onClearAll}\n\t\t\t\t\tdisabled={clearDisabled}\n\t\t\t\t\ttitle={t(\"projects:clearAllTooltip\")}\n\t\t\t\t>\n\t\t\t\t\t{clearing.value ? t(\"projects:clearing\") : t(\"projects:clearAll\")}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<p className=\"text-xs text-[var(--muted)] max-w-form\">\n\t\t\t\tClear All only removes repository entries from Moltis, it does not delete anything from disk.\n\t\t\t</p>\n\t\t\t<p className=\"text-sm text-[var(--muted)]\" style={{ maxWidth: \"600px\", margin: 0 }}>\n\t\t\t\tProjects bind sessions to a codebase directory. When a session is linked to a project, context files (CLAUDE.md,\n\t\t\t\tAGENTS.md, .cursorrules, and rule directories) are loaded automatically, scanned for risky prompt-injection\n\t\t\t\tpatterns, and injected into the system prompt. Enable auto-worktree to give each session its own git branch for\n\t\t\t\tisolated work.\n\t\t\t</p>\n\t\t\t<p className=\"text-sm text-[var(--muted)]\" style={{ maxWidth: \"600px\", margin: 0 }}>\n\t\t\t\t<strong className=\"text-[var(--text)]\">Auto-detect</strong> scans common directories under your home folder (\n\t\t\t\t<code className=\"font-mono text-xs\">~/Projects</code>, <code className=\"font-mono text-xs\">~/Developer</code>,{\" \"}\n\t\t\t\t<code className=\"font-mono text-xs\">~/src</code>, <code className=\"font-mono text-xs\">~/code</code>,{\" \"}\n\t\t\t\t<code className=\"font-mono text-xs\">~/repos</code>, <code className=\"font-mono text-xs\">~/workspace</code>,{\" \"}\n\t\t\t\t<code className=\"font-mono text-xs\">~/dev</code>, <code className=\"font-mono text-xs\">~/git</code>) and Superset\n\t\t\t\tworktrees (<code className=\"font-mono text-xs\">~/.superset/worktrees</code>) for git repositories and adds them\n\t\t\t\tas projects.\n\t\t\t</p>\n\t\t\t<div className=\"project-form-row\">\n\t\t\t\t<PathInput onAdd={onAdd} />\n\t\t\t</div>\n\t\t\t<div style={{ maxWidth: \"600px\", marginTop: \"8px\" }}>\n\t\t\t\t{list.length === 0 && (\n\t\t\t\t\t<div className=\"text-sm text-[var(--muted)]\" style={{ padding: \"12px 0\" }}>\n\t\t\t\t\t\tNo projects configured. Add a directory above or use auto-detect.\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t{list.map((p) =>\n\t\t\t\t\teditingProject.value === p.id ? (\n\t\t\t\t\t\t<ProjectEditForm key={p.id} project={p} />\n\t\t\t\t\t) : (\n\t\t\t\t\t\t<ProjectCard key={p.id} project={p} />\n\t\t\t\t\t),\n\t\t\t\t)}\n\t\t\t</div>\n\t\t\t<ConfirmDialog />\n\t\t</div>\n\t);\n}\n\nexport function initProjects(container: HTMLElement): void {\n\t_projectsContainer = container;\n\tcontainer.style.cssText = \"flex-direction:column;padding:0;overflow:hidden;\";\n\teditingProject.value = null;\n\tcompletions.value = [];\n\tdetecting.value = false;\n\tclearing.value = false;\n\trender(<ProjectsPageComponent />, container);\n}\n\nexport function teardownProjects(): void {\n\tif (_projectsContainer) render(null, _projectsContainer);\n\t_projectsContainer = null;\n}\n\nregisterPage(routes.projects!, initProjects, teardownProjects);\n","// ── Skills page (Preact + Signals) ───────────────────────────\n// Note: body_html is server-rendered trusted content from SKILL.md\n// processed by pulldown-cmark on the Rust gateway side.\n\nimport { computed, signal, useSignal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect, useRef } from \"preact/hooks\";\nimport { onEvent } from \"../events\";\nimport { sendRpc } from \"../helpers\";\nimport { updateNavCount } from \"../nav-counts\";\nimport { registerPage } from \"../router\";\nimport { routes } from \"../routes\";\nimport * as S from \"../state\";\nimport { ConfirmDialog, requestConfirm } from \"../ui\";\n\n// ── Types ────────────────────────────────────────────────────\n\ninterface SkillSummary {\n\tname: string;\n\tdescription?: string;\n\tsource?: string;\n\tenabled?: boolean;\n\tprotected?: boolean;\n\tdisplay_name?: string;\n\tquarantined?: boolean;\n\ttrusted?: boolean;\n\tdrifted?: boolean;\n\teligible?: boolean;\n}\ninterface SkillDetail extends SkillSummary {\n\tbody?: string;\n\tbody_html?: string;\n\tauthor?: string;\n\tversion?: string;\n\thomepage?: string;\n\tsource_url?: string;\n\tcommit_sha?: string;\n\tcommit_url?: string;\n\tcommit_age_days?: number;\n\tcompatibility?: string;\n\tallowed_tools?: string[];\n\tlicense?: string;\n\tlicense_url?: string;\n\tmissing_bins?: string[];\n\tinstall_options?: { label?: string; kind?: string }[];\n\trequires?: { bins?: string[]; any_bins?: string[] };\n\tprovenance?: { original_source?: string; original_commit_sha?: string; imported_from?: string };\n\tquarantine_reason?: string;\n}\ninterface RepoSummary {\n\tsource: string;\n\tskill_count: number;\n\tenabled_count: number;\n\tcommit_sha?: string;\n\tquarantined?: boolean;\n\tdrifted?: boolean;\n\torphaned?: boolean;\n\trepo_name?: string;\n\tprovenance?: { original_source?: string; original_commit_sha?: string; imported_from?: string };\n\tquarantine_reason?: string;\n}\ninterface ToastItem {\n\tid: number;\n\tmessage: string;\n\ttype: string;\n}\ninterface InstallProgress {\n\tid: string;\n\tsource: string;\n\tstate: string;\n}\n\nconst repos = signal<RepoSummary[]>([]);\nconst enabledSkills = signal<SkillSummary[]>([]);\nconst loading = signal(false);\nconst toasts = signal<ToastItem[]>([]);\nlet toastId = 0;\nconst installProgresses = signal<InstallProgress[]>([]);\nlet installProgressId = 0;\n\nlet prefetchPromise: Promise<unknown> | null = null;\nfunction ensurePrefetch(): Promise<unknown> {\n\tif (!prefetchPromise)\n\t\tprefetchPromise = fetch(\"/api/skills\")\n\t\t\t.then((r) => r.json())\n\t\t\t.then((data) => {\n\t\t\t\tif (data.skills) enabledSkills.value = data.skills;\n\t\t\t\tif (data.repos) repos.value = data.repos;\n\t\t\t\treturn data;\n\t\t\t})\n\t\t\t.catch(() => null);\n\treturn prefetchPromise;\n}\n\nconst skillRepoMap = computed<Record<string, string>>(() => {\n\tconst map: Record<string, string> = {};\n\tenabledSkills.value.forEach((s) => {\n\t\tif (s.source) map[s.name] = s.source;\n\t});\n\treturn map;\n});\n\nfunction showToast(message: string, type: string): void {\n\tconst id = ++toastId;\n\ttoasts.value = toasts.value.concat([{ id, message, type }]);\n\tsetTimeout(() => {\n\t\ttoasts.value = toasts.value.filter((t) => t.id !== id);\n\t}, 4000);\n}\nfunction shortSha(sha: string | null | undefined): string {\n\treturn sha?.slice(0, 12) || \"\";\n}\nfunction startInstallProgress(source: string, id?: string): string {\n\tconst pid = id || `install-${++installProgressId}`;\n\tif (installProgresses.value.some((p) => p.id === pid)) return pid;\n\tinstallProgresses.value = [...installProgresses.value, { id: pid, source: source || \"repository\", state: \"running\" }];\n\treturn pid;\n}\nfunction stopInstallProgress(id: string, _ok: boolean): void {\n\tinstallProgresses.value = installProgresses.value.filter((p) => p.id !== id);\n}\n\nfunction emergencyDisableAllSkills(): void {\n\trequestConfirm(\"Disable all third-party skills now?\", { confirmLabel: \"Disable All\", danger: true }).then((yes) => {\n\t\tif (!yes) return;\n\t\tsendRpc(\"skills.emergency_disable\", {}).then((res) => {\n\t\t\tif (!res?.ok) {\n\t\t\t\tshowToast(`Emergency disable failed: ${res?.error || \"unknown\"}`, \"error\");\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tshowToast(`Disabled ${(res.payload as Record<string, number>)?.skills_disabled || 0} skills`, \"success\");\n\t\t\tfetchAll();\n\t\t});\n\t});\n}\n\nfunction fetchAll(): void {\n\tloading.value = true;\n\tfetch(\"/api/skills\")\n\t\t.then((r) => r.json())\n\t\t.then((data) => {\n\t\t\tif (data.skills) enabledSkills.value = data.skills;\n\t\t\tif (data.repos) repos.value = data.repos;\n\t\t\tloading.value = false;\n\t\t\tupdateNavCount(\"skills\", (data.skills || []).length);\n\t\t})\n\t\t.catch(() => {\n\t\t\tloading.value = false;\n\t\t});\n}\n\nfunction doInstall(source: string): Promise<void> {\n\tif (!(source && S.connected)) {\n\t\tif (!S.connected) showToast(\"Not connected to gateway.\", \"error\");\n\t\treturn Promise.resolve();\n\t}\n\tconst opId = `skills-install-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;\n\tconst pid = startInstallProgress(source, opId);\n\treturn sendRpc(\"skills.install\", { source, op_id: opId }).then((res) => {\n\t\tif (res?.ok) {\n\t\t\tconst p = (res.payload || {}) as Record<string, unknown[]>;\n\t\t\tshowToast(`Installed ${source} (${(p.installed || []).length} skills)`, \"success\");\n\t\t\tfetchAll();\n\t\t\tstopInstallProgress(pid, true);\n\t\t} else {\n\t\t\tshowToast(`Failed: ${res?.error || \"unknown error\"}`, \"error\");\n\t\t\tstopInstallProgress(pid, false);\n\t\t}\n\t});\n}\nfunction doImportBundle(path: string): Promise<void> {\n\tif (!(path && S.connected)) {\n\t\tif (!S.connected) showToast(\"Not connected.\", \"error\");\n\t\treturn Promise.resolve();\n\t}\n\treturn sendRpc(\"skills.repos.import\", { path }).then((res) => {\n\t\tif (res?.ok) {\n\t\t\tconst p = (res.payload || {}) as Record<string, unknown>;\n\t\t\tshowToast(`Imported ${p.repo_name || \"bundle\"} (${p.skill_count || 0} skills)`, \"success\");\n\t\t\tfetchAll();\n\t\t} else showToast(`Failed: ${res?.error || \"unknown\"}`, \"error\");\n\t});\n}\nfunction doExportBundle(source: string, path: string | null): Promise<void> {\n\tif (!(source && S.connected)) return Promise.resolve();\n\tconst params: Record<string, string> = { source };\n\tif (path) params.path = path;\n\treturn sendRpc(\"skills.repos.export\", params).then((res) => {\n\t\tif (res?.ok) showToast(`Exported ${source}`, \"success\");\n\t\telse showToast(`Failed: ${res?.error || \"unknown\"}`, \"error\");\n\t});\n}\nexport function doUnquarantine(source: string): Promise<void> {\n\tif (!(source && S.connected)) return Promise.resolve();\n\treturn sendRpc(\"skills.repos.unquarantine\", { source }).then((res) => {\n\t\tif (res?.ok) {\n\t\t\tshowToast(`Cleared quarantine for ${source}`, \"success\");\n\t\t\tfetchAll();\n\t\t} else showToast(`Failed: ${res?.error || \"u