\t\t\tvalue={editEnv.value}\n\t\t\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\t\t\teditEnv.value = (e.target as HTMLTextAreaElement).value;\n\t\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</>\n\t\t\t\t\t)}\n\t\t\t\t\t<div className=\"project-edit-group mb-2\">\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mb-1\">Timeout override (seconds)</div>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\ttype=\"number\"\n\t\t\t\t\t\t\tclassName=\"provider-key-input w-full font-mono\"\n\t\t\t\t\t\t\tmin=\"1\"\n\t\t\t\t\t\t\tstep=\"1\"\n\t\t\t\t\t\t\tplaceholder=\"Use global default\"\n\t\t\t\t\t\t\tvalue={editTimeout.value}\n\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\teditTimeout.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t\t<div className=\"flex gap-2\">\n\t\t\t\t\t\t<button className=\"provider-btn\" onClick={saveEdit} disabled={saving.value}>\n\t\t\t\t\t\t\t{saving.value ? \"Saving\\u2026\" : \"Save\"}\n\t\t\t\t\t\t</button>\n\t\t\t\t\t\t<button\n\t\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\t\tediting.value = false;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary provider-btn-sm\"\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\tCancel\n\t\t\t\t\t\t</button>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t)}\n\t\t\t{expanded.value && (\n\t\t\t\t<div className=\"skills-repo-detail\" style={{ display: \"block\" }}>\n\t\t\t\t\t{isSse ? (\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<div className=\"flex items-center gap-1.5 py-1.5 text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\t<span className=\"opacity-60\">URL</span>\n\t\t\t\t\t\t\t\t<code className=\"font-mono text-[var(--text)]\">{currentSafeUrl || \"(hidden)\"}</code>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<div className=\"flex items-center gap-1.5 py-1.5 text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\t<span className=\"opacity-60\">HEADERS</span>\n\t\t\t\t\t\t\t\t<code className=\"font-mono text-[var(--text)]\">{currentHeaderSummary}</code>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t) : (\n\t\t\t\t\t\t<div className=\"flex items-center gap-1.5 py-1.5 text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t<span className=\"opacity-60\">$</span>\n\t\t\t\t\t\t\t<code className=\"font-mono text-[var(--text)]\">\n\t\t\t\t\t\t\t\t{server.command} {(server.args || []).join(\" \")}\n\t\t\t\t\t\t\t</code>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t)}\n\t\t\t\t\t{!tools.value && <div className=\"text-[var(--muted)] text-sm py-2\">Loading tools&hellip;</div>}\n\t\t\t\t\t{tools.value && tools.value.length > 0 && (\n\t\t\t\t\t\t<div className=\"max-h-[360px] overflow-y-auto\">\n\t\t\t\t\t\t\t{tools.value.map((t) => (\n\t\t\t\t\t\t\t\t<div key={t.name} className=\"flex items-center justify-between py-1.5 border-b border-[var(--border)]\">\n\t\t\t\t\t\t\t\t\t<div className=\"flex items-center gap-2 min-w-0 flex-1 overflow-hidden\">\n\t\t\t\t\t\t\t\t\t\t<span className=\"font-mono text-sm font-medium text-[var(--text-strong)] whitespace-nowrap\">\n\t\t\t\t\t\t\t\t\t\t\t{t.name}\n\t\t\t\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t\t\t\t{t.description && (\n\t\t\t\t\t\t\t\t\t\t\t<span className=\"text-[var(--muted)] text-xs overflow-hidden text-ellipsis whitespace-nowrap\">\n\t\t\t\t\t\t\t\t\t\t\t\t{t.description}\n\t\t\t\t\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t\t\t\t)}\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t))}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t)}\n\t\t\t\t\t{tools.value && tools.value.length === 0 && (\n\t\t\t\t\t\t<div className=\"text-[var(--muted)] text-sm py-2\">No tools exposed.</div>\n\t\t\t\t\t)}\n\t\t\t\t</div>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\nfunction ConfiguredServersSection(): VNode {\n\treturn (\n\t\t<div>\n\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-2\">Configured MCP Servers</h3>\n\t\t\t<div>\n\t\t\t\t{(!servers.value || servers.value.length === 0) && !loading.value && (\n\t\t\t\t\t<div className=\"p-3 text-[var(--muted)] text-sm\">No MCP tools configured.</div>\n\t\t\t\t)}\n\t\t\t\t{servers.value.map((s) => (\n\t\t\t\t\t<ServerCard key={s.name} server={s} />\n\t\t\t\t))}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nfunction ConfigSection(): VNode {\n\treturn (\n\t\t<div className=\"max-w-[600px] bg-[var(--surface2)] border border-[var(--border)] rounded-[var(--radius)] px-5 py-4\">\n\t\t\t<div className=\"flex items-center justify-between gap-3 mb-2\">\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\">Request Timeout</h3>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary provider-btn-sm\"\n\t\t\t\t\tonClick={refreshConfig}\n\t\t\t\t\tdisabled={configLoading.value || configSaving.value}\n\t\t\t\t>\n\t\t\t\t\t{configLoading.value ? \"Loading\\u2026\" : \"Reload\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<p className=\"text-xs text-[var(--muted)] mb-3\">Controls how long Moltis waits for an MCP server response.</p>\n\t\t\t<div className=\"flex flex-wrap items-end gap-3\">\n\t\t\t\t<label className=\"flex flex-col gap-1\">\n\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">Timeout (seconds)</span>\n\t\t\t\t\t<input\n\t\t\t\t\t\ttype=\"number\"\n\t\t\t\t\t\tmin=\"1\"\n\t\t\t\t\t\tstep=\"1\"\n\t\t\t\t\t\tvalue={requestTimeoutSecs.value}\n\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\trequestTimeoutSecs.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\tconfigDirty.value = true;\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tclassName=\"provider-key-input w-[140px]\"\n\t\t\t\t\t/>\n\t\t\t\t</label>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-sm\"\n\t\t\t\t\tonClick={saveConfig}\n\t\t\t\t\tdisabled={configSaving.value || configLoading.value || !configDirty.value}\n\t\t\t\t>\n\t\t\t\t\t{configSaving.value ? \"Saving\\u2026\" : \"Save\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nfunction McpPageComponent(): VNode {\n\tuseEffect(() => {\n\t\trefreshServers();\n\t\trefreshConfig();\n\t\tconst off = onEvent(\"mcp.status\", (payload: unknown) => {\n\t\t\tif (Array.isArray(payload)) {\n\t\t\t\tservers.value = payload as McpServer[];\n\t\t\t\tupdateNavCount(\"mcp\", (payload as McpServer[]).filter((s) => s.state === \"running\").length);\n\t\t\t}\n\t\t});\n\t\treturn off;\n\t}, []);\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">MCP</h2>\n\t\t\t\t<button className=\"provider-btn provider-btn-secondary provider-btn-sm\" onClick={refreshServers}>\n\t\t\t\t\tRefresh\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<div className=\"max-w-[600px] bg-[var(--surface2)] border border-[var(--border)] rounded-[var(--radius)] px-5 py-4 leading-relaxed\">\n\t\t\t\t<p className=\"text-sm text-[var(--text)] mb-2.5\">\n\t\t\t\t\t<strong className=\"text-[var(--text-strong)]\">MCP (Model Context Protocol)</strong> tools extend the AI agent\n\t\t\t\t\twith external capabilities.\n\t\t\t\t</p>\n\t\t\t\t<div className=\"flex items-center gap-2 my-3 px-3.5 py-2.5 bg-[var(--surface)] rounded-[var(--radius-sm)] font-mono text-xs text-[var(--text-strong)]\">\n\t\t\t\t\t<span className=\"opacity-50\">Agent</span>\n\t\t\t\t\t<span className=\"text-[var(--accent)]\">&rarr;</span>\n\t\t\t\t\t<span>Moltis</span>\n\t\t\t\t\t<span className=\"text-[var(--accent)]\">&rarr;</span>\n\t\t\t\t\t<span>Local / Remote MCP</span>\n\t\t\t\t\t<span className=\"text-[var(--accent)]\">&rarr;</span>\n\t\t\t\t\t<span className=\"opacity-50\">External API</span>\n\t\t\t\t</div>\n\t\t\t\t<p className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\tSupports both <strong>local stdio MCP processes</strong> and{\" \"}\n\t\t\t\t\t<strong>remote Streamable HTTP/SSE servers</strong>.\n\t\t\t\t</p>\n\t\t\t</div>\n\t\t\t<div className=\"skills-warn max-w-[600px]\">\n\t\t\t\t<div className=\"skills-warn-title\">{\"\\u26a0\\ufe0f\"} Review MCP trust boundaries before enabling</div>\n\t\t\t\t<div>\n\t\t\t\t\tLocal stdio servers run with <strong>your full system privileges</strong>.\n\t\t\t\t</div>\n\t\t\t\t<div className=\"mt-1\">Remote SSE servers receive your tool inputs. Use trusted hosts only.</div>\n\t\t\t</div>\n\t\t\t<ConfigSection />\n\t\t\t<InstallBox />\n\t\t\t<FeaturedSection />\n\t\t\t<ConfiguredServersSection />\n\t\t\t{loading.value && servers.value.length === 0 && (\n\t\t\t\t<div className=\"p-6 text-center text-[var(--muted)] text-sm\">Loading MCP servers&hellip;</div>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\n// ── Exported init/teardown ──────────────────────────────────\n\nlet _mcpContainer: HTMLElement | null = null;\n\nexport function initMcp(container: HTMLElement): void {\n\t_mcpContainer = container;\n\tcontainer.style.cssText = \"flex-direction:column;padding:0;overflow:hidden;\";\n\trender(\n\t\t<>\n\t\t\t<McpPageComponent />\n\t\t\t<Toasts />\n\t\t\t<ConfirmDialog />\n\t\t</>,\n\t\tcontainer,\n\t);\n}\n\nexport function teardownMcp(): void {\n\tif (_mcpContainer) render(null, _mcpContainer);\n\t_mcpContainer = null;\n}\n","// ── Network Audit page (Preact toolbar + imperative entry area) ──\n\nimport { signal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect, useRef } from \"preact/hooks\";\nimport { sendRpc } from \"../helpers\";\nimport * as S from \"../state\";\nimport { ComboSelect } from \"../ui\";\n\ninterface AuditEntry {\n\ttimestamp: string;\n\tprotocol: string;\n\taction: string;\n\tdomain: string;\n\tport: number;\n\tmethod?: string;\n\turl?: string;\n\tbytes_sent: number;\n\tbytes_received: number;\n\tduration_ms: number;\n\terror?: string;\n}\n\ninterface ComboOption {\n\tvalue: string;\n\tlabel: string;\n}\n\nconst paused = signal(false);\nconst domainFilter = signal(\"\");\nconst protocolFilter = signal(\"\");\nconst actionFilter = signal(\"\");\nconst entryCount = signal(0);\nconst maxEntries = 2000;\n\nfunction actionColor(action: string): string {\n\tif (action === \"allowed\" || action === \"approved_by_user\") return \"var(--ok, #22c55e)\";\n\tif (action === \"denied\") return \"var(--error, #ef4444)\";\n\tif (action === \"timeout\") return \"var(--warn, #f59e0b)\";\n\treturn \"var(--text)\";\n}\n\nfunction actionBg(action: string): string {\n\tif (action === \"denied\") return \"rgba(239,68,68,0.08)\";\n\tif (action === \"timeout\") return \"rgba(245,158,11,0.06)\";\n\treturn \"transparent\";\n}\n\nfunction formatBytes(n: number): string {\n\tif (n < 1024) return `${n}B`;\n\tif (n < 1024 * 1024) return `${(n / 1024).toFixed(1)}KB`;\n\treturn `${(n / (1024 * 1024)).toFixed(1)}MB`;\n}\n\nfunction renderEntry(entry: AuditEntry): HTMLDivElement {\n\tconst row = document.createElement(\"div\");\n\trow.className = \"logs-row\";\n\trow.style.background = actionBg(entry.action);\n\n\t// Timestamp\n\tconst ts = document.createElement(\"span\");\n\tts.className = \"logs-ts\";\n\tconst d = new Date(entry.timestamp);\n\tts.textContent =\n\t\td.toLocaleTimeString([], { hour: \"2-digit\", minute: \"2-digit\", second: \"2-digit\" }) +\n\t\t\".\" +\n\t\tString(d.getMilliseconds()).padStart(3, \"0\");\n\n\t// Protocol badge\n\tconst proto = document.createElement(\"span\");\n\tproto.className = \"logs-level\";\n\tproto.style.color = \"var(--accent, #3b82f6)\";\n\tproto.textContent = entry.protocol === \"http_connect\" ? \"CONNECT\" : \"HTTP\";\n\n\t// Action badge\n\tconst act = document.createElement(\"span\");\n\tact.className = \"logs-level\";\n\tact.style.color = actionColor(entry.action);\n\tact.textContent =\n\t\tentry.action === \"approved_by_user\"\n\t\t\t? \"\\u2713\"\n\t\t\t: entry.action === \"allowed\"\n\t\t\t\t? \"\\u2713\"\n\t\t\t\t: entry.action === \"denied\"\n\t\t\t\t\t? \"\\u2717\"\n\t\t\t\t\t: \"\\u29D6\";\n\n\t// Domain\n\tconst dom = document.createElement(\"span\");\n\tdom.className = \"logs-target\";\n\tdom.textContent = `${entry.domain}:${entry.port}`;\n\n\t// Details\n\tconst details = document.createElement(\"span\");\n\tdetails.className = \"logs-msg\";\n\tconst parts: string[] = [];\n\tif (entry.method) parts.push(entry.method);\n\tif (entry.url) parts.push(entry.url);\n\tparts.push(`${formatBytes(entry.bytes_sent)}\\u2191`);\n\tparts.push(`${formatBytes(entry.bytes_received)}\\u2193`);\n\tparts.push(`${entry.duration_ms}ms`);\n\tif (entry.error) parts.push(`ERR: ${entry.error}`);\n\tdetails.textContent = parts.join(\"  \");\n\n\trow.appendChild(ts);\n\trow.appendChild(proto);\n\trow.appendChild(act);\n\trow.appendChild(dom);\n\trow.appendChild(details);\n\treturn row;\n}\n\nfunction Toolbar(): VNode {\n\tconst domainRef = useRef<HTMLInputElement>(null);\n\tconst filterTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n\n\tfunction debouncedDomain(): void {\n\t\tif (filterTimer.current != null) clearTimeout(filterTimer.current);\n\t\tfilterTimer.current = setTimeout(() => {\n\t\t\tdomainFilter.value = domainRef.current?.value || \"\";\n\t\t}, 300);\n\t}\n\n\tconst protocolOptions: ComboOption[] = [\n\t\t{ value: \"http_connect\", label: \"CONNECT\" },\n\t\t{ value: \"http_forward\", label: \"HTTP\" },\n\t];\n\n\tconst actionOptions: ComboOption[] = [\n\t\t{ value: \"allowed\", label: \"Allowed\" },\n\t\t{ value: \"denied\", label: \"Denied\" },\n\t\t{ value: \"approved_by_user\", label: \"Approved\" },\n\t\t{ value: \"timeout\", label: \"Timeout\" },\n\t];\n\n\treturn (\n\t\t<div className=\"logs-toolbar\">\n\t\t\t<input\n\t\t\t\tref={domainRef}\n\t\t\t\ttype=\"text\"\n\t\t\t\tplaceholder={\"Filter domain\\u2026\"}\n\t\t\t\tclassName=\"logs-input\"\n\t\t\t\tstyle={{ width: \"180px\" }}\n\t\t\t\tonInput={debouncedDomain}\n\t\t\t/>\n\t\t\t<div className=\"logs-level-filter\">\n\t\t\t\t<ComboSelect\n\t\t\t\t\toptions={protocolOptions}\n\t\t\t\t\tvalue={protocolFilter.value}\n\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\tprotocolFilter.value = v;\n\t\t\t\t\t}}\n\t\t\t\t\tplaceholder=\"All protocols\"\n\t\t\t\t\tsearchable={false}\n\t\t\t\t/>\n\t\t\t</div>\n\t\t\t<div className=\"logs-level-filter\">\n\t\t\t\t<ComboSelect\n\t\t\t\t\toptions={actionOptions}\n\t\t\t\t\tvalue={actionFilter.value}\n\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\tactionFilter.value = v;\n\t\t\t\t\t}}\n\t\t\t\t\tplaceholder=\"All actions\"\n\t\t\t\t\tsearchable={false}\n\t\t\t\t/>\n\t\t\t</div>\n\t\t\t<button\n\t\t\t\tclassName=\"logs-btn\"\n\t\t\t\tonClick={() => {\n\t\t\t\t\tpaused.value = !paused.value;\n\t\t\t\t}}\n\t\t\t\tstyle={paused.value ? { borderColor: \"var(--warn)\" } : undefined}\n\t\t\t>\n\t\t\t\t{paused.value ? \"Resume\" : \"Pause\"}\n\t\t\t</button>\n\t\t\t<button\n\t\t\t\tclassName=\"logs-btn\"\n\t\t\t\tonClick={() => {\n\t\t\t\t\tconst area = document.getElementById(\"networkAuditArea\");\n\t\t\t\t\tif (area) area.textContent = \"\";\n\t\t\t\t\tentryCount.value = 0;\n\t\t\t\t}}\n\t\t\t>\n\t\t\t\tClear\n\t\t\t</button>\n\t\t\t<span className=\"logs-count\">{entryCount.value} entries</span>\n\t\t</div>\n\t);\n}\n\nfunction NetworkAuditPage(): VNode {\n\tconst areaRef = useRef<HTMLDivElement>(null);\n\n\tfunction appendEntry(entry: AuditEntry): void {\n\t\tconst area = areaRef.current;\n\t\tif (!area) return;\n\t\tconst row = renderEntry(entry);\n\t\tarea.appendChild(row);\n\t\tentryCount.value++;\n\t\twhile (area.childNodes.length > maxEntries) {\n\t\t\tarea.removeChild(area.firstChild!);\n\t\t\tentryCount.value--;\n\t\t}\n\t\tif (!paused.value) {\n\t\t\tconst atBottom = area.scrollHeight - area.scrollTop - area.clientHeight < 60;\n\t\t\tif (atBottom) area.scrollTop = area.scrollHeight;\n\t\t}\n\t}\n\n\tfunction matchesFilter(entry: AuditEntry): boolean {\n\t\tconst dVal = domainFilter.value.trim().toLowerCase();\n\t\tif (dVal && entry.domain.toLowerCase().indexOf(dVal) === -1) return false;\n\t\tif (protocolFilter.value && entry.protocol !== protocolFilter.value) return false;\n\t\tif (actionFilter.value && entry.action !== actionFilter.value) return false;\n\t\treturn true;\n\t}\n\n\tfunction refetch(): void {\n\t\tconst area = areaRef.current;\n\t\tif (area) area.textContent = \"\";\n\t\tentryCount.value = 0;\n\t\tsendRpc(\"network.audit.list\", {\n\t\t\tdomain: domainFilter.value.trim() || undefined,\n\t\t\tprotocol: protocolFilter.value || undefined,\n\t\t\taction: actionFilter.value || undefined,\n\t\t\tlimit: 500,\n\t\t}).then((res) => {\n\t\t\tif (!res?.ok) return;\n\t\t\tconst entries: AuditEntry[] = (res.payload as { entries?: AuditEntry[] })?.entries || [];\n\t\t\tlet i = 0;\n\t\t\tconst batchSize = 100;\n\t\t\tfunction renderBatch(): void {\n\t\t\t\tconst end = Math.min(i + batchSize, entries.length);\n\t\t\t\twhile (i < end) appendEntry(entries[i++]);\n\t\t\t\tif (i < entries.length) requestAnimationFrame(renderBatch);\n\t\t\t\telse if (areaRef.current) areaRef.current.scrollTop = areaRef.current.scrollHeight;\n\t\t\t}\n\t\t\trenderBatch();\n\t\t});\n\t}\n\n\tuseEffect(() => {\n\t\trefetch();\n\t\tS.setNetworkAuditEventHandler(((entry: unknown) => {\n\t\t\tif (paused.value) return;\n\t\t\tconst e = entry as AuditEntry;\n\t\t\tif (!matchesFilter(e)) return;\n\t\t\tappendEntry(e);\n\t\t}) as unknown as () => void);\n\t\treturn () => S.setNetworkAuditEventHandler(null);\n\t}, []);\n\n\tuseEffect(() => {\n\t\trefetch();\n\t}, [domainFilter.value, protocolFilter.value, actionFilter.value]);\n\n\treturn (\n\t\t<>\n\t\t\t<Toolbar />\n\t\t\t<div ref={areaRef} id=\"networkAuditArea\" className=\"logs-area\" />\n\t\t</>\n\t);\n}\n\nlet _container: HTMLElement | null = null;\n\nexport function initNetworkAudit(container: HTMLElement): void {\n\t_container = container;\n\tcontainer.style.cssText = \"flex-direction:column;padding:0;overflow:hidden;\";\n\tpaused.value = false;\n\tdomainFilter.value = \"\";\n\tprotocolFilter.value = \"\";\n\tactionFilter.value = \"\";\n\tentryCount.value = 0;\n\trender(<NetworkAuditPage />, container);\n}\n\nexport function teardownNetworkAudit(): void {\n\tS.setNetworkAuditEventHandler(null);\n\tif (_container) render(null, _container);\n\t_container = null;\n}\n","// ── Nodes page ──────────────────────────────────────────────\n\nimport { signal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect } from \"preact/hooks\";\nimport { onEvent } from \"../events\";\nimport { sendRpc } from \"../helpers\";\nimport { navigate } from \"../router\";\nimport { settingsPath } from \"../routes\";\nimport { ConfirmDialog, requestConfirm } from \"../ui\";\n\n// ── Types ────────────────────────────────────────────────────\n\ninterface NodeInfo {\n\tnodeId: string;\n\tdisplayName?: string;\n\tplatform?: string;\n\tversion?: string;\n\tremoteIp?: string;\n\tcapabilities?: string[];\n\ttelemetry?: TelemetryData;\n}\n\ninterface TelemetryData {\n\tcpuCount?: number;\n\tcpuUsage?: number;\n\tmemTotal?: number;\n\tmemAvailable?: number;\n\tuptimeSecs?: number;\n\tservices?: unknown[];\n\tstale?: boolean;\n}\n\ninterface PendingPair {\n\tid: string;\n\tdeviceId: string;\n\tdisplayName?: string;\n\tplatform?: string;\n}\n\ninterface PairedDevice {\n\tdeviceId: string;\n\tdisplayName?: string;\n\tplatform?: string;\n\tcreatedAt?: string;\n}\n\ninterface DoctorSnapshot {\n\texec_host?: string;\n\tactive_route?: {\n\t\tlabel?: string;\n\t\ttarget?: string;\n\t\ttarget_id?: string;\n\t\tport?: number;\n\t\thost_pinned?: boolean;\n\t};\n\tchecks?: DoctorCheck[];\n\tpaired_node_count?: number;\n\tmanaged_target_count?: number;\n\tpinned_target_count?: number;\n\tmanaged_key_count?: number;\n\tencrypted_key_count?: number;\n}\n\ninterface DoctorCheck {\n\ttitle: string;\n\tlevel: string;\n\tmessage: string;\n\thint?: string;\n}\n\ninterface DoctorTestResult {\n\troute_label?: string;\n\treachable: boolean;\n\texit_code?: number;\n\tfailure_hint?: string;\n\tstderr?: string;\n}\n\ninterface ToastItem {\n\tid: number;\n\tmessage: string;\n\ttype: string;\n}\n\ninterface GeneratedToken {\n\ttoken: string;\n\tdeviceId: string;\n\tcommand: string;\n}\n\n// ── Signals ─────────────────────────────────────────────────\nconst nodes = signal<NodeInfo[]>([]);\nconst pendingPairs = signal<PendingPair[]>([]);\nconst pairedDevices = signal<PairedDevice[]>([]);\nconst loading = signal(false);\nconst activeTab = signal<\"connected\" | \"paired\" | \"pending\">(\"connected\");\nconst toasts = signal<ToastItem[]>([]);\nlet toastId = 0;\nconst generatedToken = signal<GeneratedToken | null>(null);\nconst generatingToken = signal(false);\nconst deviceName = signal(\"\");\nconst doctor = signal<DoctorSnapshot | null>(null);\nconst doctorLoading = signal(false);\nconst doctorError = signal(\"\");\nconst doctorTest = signal<DoctorTestResult | null>(null);\nconst doctorTestLoading = signal(false);\nconst doctorPinLoading = signal(false);\n\n// ── Helpers ─────────────────────────────────────────────────\n\nfunction isSshTargetNode(node: NodeInfo): boolean {\n\treturn node?.platform === \"ssh\" || String(node?.nodeId || \"\").startsWith(\"ssh:\");\n}\n\nfunction sshTargetValue(node: NodeInfo): string {\n\tif (String(node.nodeId || \"\").startsWith(\"ssh:\")) return String(node.nodeId).slice(4);\n\treturn String(node.displayName || \"\")\n\t\t.replace(/^SSH:\\s*/i, \"\")\n\t\t.trim();\n}\n\nfunction nodeDisplayLabel(node: NodeInfo | null): string {\n\tif (!node) return \"Local\";\n\tif (isSshTargetNode(node)) {\n\t\tconst target = sshTargetValue(node);\n\t\treturn target ? `SSH: ${target}` : node.displayName || node.nodeId;\n\t}\n\treturn node.displayName || node.nodeId;\n}\n\nfunction gatewayWsUrl(): string {\n\tconst proto = location.protocol === \"https:\" ? \"wss:\" : \"ws:\";\n\tconst host = location.hostname;\n\tconst port = location.port;\n\treturn `${proto}//${host}${port ? `:${port}` : \"\"}/ws`;\n}\n\nfunction showToast(message: string, type: string): void {\n\tconst id = ++toastId;\n\ttoasts.value = toasts.value.concat([{ id, message, type }]);\n\tsetTimeout(() => {\n\t\ttoasts.value = toasts.value.filter((t) => t.id !== id);\n\t}, 4000);\n}\n\nfunction copyToClipboard(text: string): void {\n\tif (navigator.clipboard?.writeText) {\n\t\tnavigator.clipboard.writeText(text).then(() => showToast(\"Copied to clipboard\", \"success\"));\n\t}\n}\n\nasync function generateToken(): Promise<void> {\n\tgeneratingToken.value = true;\n\tconst name = deviceName.value.trim() || null;\n\tconst res = await sendRpc<{ deviceToken: string; deviceId: string }>(\"device.token.create\", {\n\t\tdisplayName: name,\n\t\tplatform: \"remote\",\n\t});\n\tif (res?.ok && res.payload) {\n\t\tconst wsUrl = gatewayWsUrl();\n\t\tgeneratedToken.value = {\n\t\t\ttoken: res.payload.deviceToken,\n\t\t\tdeviceId: res.payload.deviceId,\n\t\t\tcommand: `moltis node add --host ${wsUrl} --token ${res.payload.deviceToken}`,\n\t\t};\n\t\tshowToast(\"Token generated\", \"success\");\n\t\tawait refreshPairedDevices();\n\t} else {\n\t\tshowToast(res?.error?.message || \"Failed to generate token\", \"error\");\n\t}\n\tgeneratingToken.value = false;\n}\n\nasync function refreshNodes(): Promise<void> {\n\tloading.value = true;\n\ttry {\n\t\tconst res = await sendRpc<NodeInfo[]>(\"node.list\", {});\n\t\tif (res?.ok) nodes.value = res.payload || [];\n\t} catch {\n\t\t/* ignore */\n\t}\n\tloading.value = false;\n}\n\nasync function refreshPendingPairs(): Promise<void> {\n\ttry {\n\t\tconst res = await sendRpc<PendingPair[]>(\"node.pair.list\", {});\n\t\tif (res?.ok) pendingPairs.value = res.payload || [];\n\t} catch {\n\t\t/* ignore */\n\t}\n}\n\nasync function refreshPairedDevices(): Promise<void> {\n\ttry {\n\t\tconst res = await sendRpc<PairedDevice[]>(\"device.pair.list\", {});\n\t\tif (res?.ok) pairedDevices.value = res.payload || [];\n\t} catch {\n\t\t/* ignore */\n\t}\n}\n\nasync function refreshDoctor(): Promise<void> {\n\tdoctorLoading.value = true;\n\tdoctorError.value = \"\";\n\ttry {\n\t\tconst response = await fetch(\"/api/ssh/doctor\");\n\t\tif (!response.ok) throw new Error(\"Failed to load remote exec status\");\n\t\tdoctor.value = await response.json();\n\t} catch (err) {\n\t\tdoctorError.value = (err as Error).message || \"Failed to load remote exec status\";\n\t} finally {\n\t\tdoctorLoading.value = false;\n\t}\n}\n\nasync function testActiveSshRoute(): Promise<void> {\n\tdoctorTestLoading.value = true;\n\tdoctorError.value = \"\";\n\ttry {\n\t\tconst response = await fetch(\"/api/ssh/doctor/test-active\", { method: \"POST\" });\n\t\tconst data = await response.json();\n\t\tif (!response.ok) throw new Error(data?.error || \"Failed to test SSH route\");\n\t\tdoctorTest.value = data;\n\t\tshowToast(\n\t\t\tdata.reachable ? \"Active SSH route is reachable\" : data.failure_hint || \"Active SSH route check failed\",\n\t\t\tdata.reachable ? \"success\" : \"error\",\n\t\t);\n\t} catch (err) {\n\t\tdoctorError.value = (err as Error).message || \"Failed to test SSH route\";\n\t\tshowToast(doctorError.value, \"error\");\n\t} finally {\n\t\tdoctorTestLoading.value = false;\n\t}\n}\n\nasync function repairActiveRouteHostPin(): Promise<void> {\n\tconst snapshot = doctor.value;\n\tconst activeRoute = snapshot?.active_route || null;\n\tif (!activeRoute?.target_id) {\n\t\tshowToast(\"The active SSH route cannot be managed from the doctor panel\", \"error\");\n\t\treturn;\n\t}\n\tdoctorPinLoading.value = true;\n\tdoctorError.value = \"\";\n\ttry {\n\t\tconst scanResponse = await fetch(\"/api/ssh/host-key/scan\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ target: activeRoute.target, port: activeRoute.port ?? null }),\n\t\t});\n\t\tconst scanData = await scanResponse.json();\n\t\tif (!scanResponse.ok) throw new Error(scanData?.error || \"Failed to scan SSH host key\");\n\t\tconst pinResponse = await fetch(`/api/ssh/targets/${activeRoute.target_id}/pin`, {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ known_host: scanData.known_host }),\n\t\t});\n\t\tconst pinData = await pinResponse.json();\n\t\tif (!pinResponse.ok) throw new Error(pinData?.error || \"Failed to pin SSH host key\");\n\t\tawait refreshDoctor();\n\t\tshowToast(activeRoute.host_pinned ? \"Active SSH host pin refreshed\" : \"Active SSH host pinned\", \"success\");\n\t} catch (err) {\n\t\tdoctorError.value = (err as Error).message || \"Failed to repair SSH host pin\";\n\t\tshowToast(doctorError.value, \"error\");\n\t} finally {\n\t\tdoctorPinLoading.value = false;\n\t}\n}\n\nasync function clearActiveRouteHostPin(): Promise<void> {\n\tconst snapshot = doctor.value;\n\tconst activeRoute = snapshot?.active_route || null;\n\tif (!activeRoute?.target_id) {\n\t\tshowToast(\"The active SSH route cannot be managed from the doctor panel\", \"error\");\n\t\treturn;\n\t}\n\tdoctorPinLoading.value = true;\n\tdoctorError.value = \"\";\n\ttry {\n\t\tconst response = await fetch(`/api/ssh/targets/${activeRoute.target_id}/pin`, { method: \"DELETE\" });\n\t\tconst data = await response.json();\n\t\tif (!response.ok) throw new Error(data?.error || \"Failed to clear SSH host pin\");\n\t\tawait refreshDoctor();\n\t\tshowToast(\"Active SSH host pin cleared\", \"success\");\n\t} catch (err) {\n\t\tdoctorError.value = (err as Error).message || \"Failed to clear SSH host pin\";\n\t\tshowToast(doctorError.value, \"error\");\n\t} finally {\n\t\tdoctorPinLoading.value = false;\n\t}\n}\n\nasync function refreshAll(): Promise<void> {\n\tawait Promise.all([refreshNodes(), refreshPendingPairs(), refreshPairedDevices(), refreshDoctor()]);\n}\n\nasync function approvePair(id: string): Promise<void> {\n\tconst res = await sendRpc(\"node.pair.approve\", { id });\n\tif (res?.ok) {\n\t\tshowToast(\"Pairing approved -- device token issued\", \"success\");\n\t\tawait refreshAll();\n\t} else showToast(res?.error?.message || \"Failed to approve\", \"error\");\n}\n\nasync function rejectPair(id: string): Promise<void> {\n\tconst res = await sendRpc(\"node.pair.reject\", { id });\n\tif (res?.ok) {\n\t\tshowToast(\"Pairing rejected\", \"success\");\n\t\tawait refreshAll();\n\t} else showToast(res?.error?.message || \"Failed to reject\", \"error\");\n}\n\nasync function revokeDevice(deviceId: string): Promise<void> {\n\tconst ok = await requestConfirm(\n\t\t`Revoke device \"${deviceId}\"? This will disconnect the device and invalidate its token.`,\n\t);\n\tif (!ok) return;\n\tconst res = await sendRpc(\"device.token.revoke\", { deviceId });\n\tif (res?.ok) {\n\t\tshowToast(\"Device token revoked\", \"success\");\n\t\tawait refreshAll();\n\t} else showToast(res?.error?.message || \"Failed to revoke\", \"error\");\n}\n\n// ── Components ──────────────────────────────────────────────\n\nfunction TabBar(): VNode {\n\tconst tabs = [\n\t\t{ id: \"connected\" as const, label: \"Connected\", count: nodes.value.length },\n\t\t{ id: \"paired\" as const, label: \"Paired Devices\", count: pairedDevices.value.length },\n\t\t{ id: \"pending\" as const, label: \"Pending\", count: pendingPairs.value.length },\n\t];\n\treturn (\n\t\t<div className=\"flex gap-1 mb-4\">\n\t\t\t{tabs.map((tab) => (\n\t\t\t\t<button\n\t\t\t\t\tkey={tab.id}\n\t\t\t\t\tclassName={`px-3 py-1.5 text-sm rounded-md transition-colors ${activeTab.value === tab.id ? \"bg-[var(--accent)] text-white\" : \"bg-[var(--surface-alt)] text-[var(--text-muted)] hover:bg-[var(--hover)]\"}`}\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tactiveTab.value = tab.id;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{tab.label}\n\t\t\t\t\t{tab.count > 0 ? <span className=\"ml-1 opacity-70\">({tab.count})</span> : null}\n\t\t\t\t</button>\n\t\t\t))}\n\t\t</div>\n\t);\n}\n\nfunction formatBytes(bytes: number | null | undefined): string | null {\n\tif (bytes == null) return null;\n\tconst gb = bytes / 1073741824;\n\tif (gb >= 1) return `${gb.toFixed(1)} GB`;\n\treturn `${(bytes / 1048576).toFixed(0)} MB`;\n}\n\nfunction TelemetryBar({\n\tlabel,\n\tvalue,\n\tmax,\n}: {\n\tlabel: string;\n\tvalue: number | null | undefined;\n\tmax: number | null | undefined;\n}): VNode | null {\n\tif (value == null || max == null || max === 0) return null;\n\tconst pct = Math.min(100, Math.max(0, (value / max) * 100));\n\tconst color = pct > 80 ? \"bg-red-500\" : pct > 60 ? \"bg-yellow-500\" : \"bg-green-500\";\n\treturn (\n\t\t<div className=\"flex items-center gap-2 text-xs text-[var(--text-muted)]\">\n\t\t\t<span className=\"w-8 shrink-0\">{label}</span>\n\t\t\t<div className=\"flex-1 h-1.5 rounded bg-[var(--border)] overflow-hidden\">\n\t\t\t\t<div className={`${color} h-full rounded`} style={{ width: `${pct.toFixed(1)}%` }} />\n\t\t\t</div>\n\t\t\t<span className=\"w-16 text-right shrink-0\">{pct.toFixed(0)}%</span>\n\t\t</div>\n\t);\n}\n\nfunction NodeTelemetry({ telemetry }: { telemetry?: TelemetryData }): VNode | null {\n\tif (!telemetry) return null;\n\tconst parts: VNode[] = [];\n\tif (telemetry.cpuCount != null) parts.push(<span>{telemetry.cpuCount} cores</span>);\n\tif (telemetry.memTotal != null) parts.push(<span>{formatBytes(telemetry.memTotal)} RAM</span>);\n\tif (telemetry.uptimeSecs != null) {\n\t\tconst h = Math.floor(telemetry.uptimeSecs / 3600);\n\t\tconst d = Math.floor(h / 24);\n\t\tparts.push(<span>up {d > 0 ? `${d}d ${h % 24}h` : `${h}h`}</span>);\n\t}\n\tif (telemetry.stale) parts.push(<span className=\"text-yellow-500\">(stale)</span>);\n\treturn (\n\t\t<div className=\"mt-1.5 flex flex-col gap-1\">\n\t\t\t{telemetry.cpuUsage != null ? <TelemetryBar label=\"CPU\" value={telemetry.cpuUsage} max={100} /> : null}\n\t\t\t{telemetry.memTotal != null && telemetry.memAvailable != null ? (\n\t\t\t\t<TelemetryBar label=\"MEM\" value={telemetry.memTotal - telemetry.memAvailable} max={telemetry.memTotal} />\n\t\t\t) : null}\n\t\t\t{parts.length > 0 ? <div className=\"text-xs text-[var(--text-muted)] flex gap-2 flex-wrap\">{parts}</div> : null}\n\t\t</div>\n\t);\n}\n\nfunction DoctorBadge({ level }: { level: string }): VNode {\n\tconst tone =\n\t\tlevel === \"error\"\n\t\t\t? \"bg-red-500/15 text-red-500\"\n\t\t\t: level === \"warn\"\n\t\t\t\t? \"bg-yellow-500/15 text-yellow-500\"\n\t\t\t\t: \"bg-green-500/15 text-green-500\";\n\treturn <span className={`text-[10px] uppercase tracking-wide px-1.5 py-0.5 rounded ${tone}`}>{level}</span>;\n}\n\nfunction ConnectNodeForm(): VNode {\n\tconst wsUrl = gatewayWsUrl();\n\treturn (\n\t\t<div className=\"rounded-lg border border-[var(--border)] bg-[var(--surface-alt)] p-4\">\n\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)] mb-3\">Connect a Remote Node</h3>\n\t\t\t<p className=\"text-xs text-[var(--text-muted)] mb-3\">\n\t\t\t\tGenerate a token and run the command on the remote machine you want to connect.\n\t\t\t</p>\n\t\t\t<div className=\"mb-3\">\n\t\t\t\t<label className=\"block text-xs text-[var(--text-muted)] mb-1\">This gateway's public endpoint</label>\n\t\t\t\t<div className=\"flex items-center gap-2\">\n\t\t\t\t\t<code className=\"flex-1 text-xs bg-[var(--bg)] px-2 py-1.5 rounded border border-[var(--border)] break-all\">\n\t\t\t\t\t\t{wsUrl}\n\t\t\t\t\t</code>\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary provider-btn-sm shrink-0\"\n\t\t\t\t\t\tonClick={() => copyToClipboard(wsUrl)}\n\t\t\t\t\t>\n\t\t\t\t\t\tCopy\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t\t<p className=\"text-xs text-[var(--text-muted)] mt-1\">\n\t\t\t\t\tThe remote node will connect back to this address. Replace with your public IP or domain if needed.\n\t\t\t\t</p>\n\t\t\t</div>\n\t\t\t<div className=\"mb-3\">\n\t\t\t\t<label className=\"block text-xs text-[var(--text-muted)] mb-1\">Remote node name (optional)</label>\n\t\t\t\t<input\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tclassName=\"w-full text-sm bg-[var(--bg)] px-2 py-1.5 rounded border border-[var(--border)] text-[var(--text-strong)] placeholder-[var(--text-muted)]\"\n\t\t\t\t\tplaceholder=\"e.g. my-server\"\n\t\t\t\t\tvalue={deviceName.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\tdeviceName.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t</div>\n\t\t\t<butt