cket = null;\n\tws.onopen = null;\n\tws.onmessage = null;\n\tws.onerror = null;\n\tws.onclose = null;\n\tif (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING) ws.close();\n}\n\nfunction scheduleReconnect(): void {\n\tif (shuttingDown || reconnectTimer) return;\n\treconnectTimer = setTimeout(() => {\n\t\treconnectTimer = null;\n\t\tconnectTerminalSocket();\n\t}, RECONNECT_DELAY_MS);\n}\n\nfunction applyReadyPayload(payload: ReadyPayload): void {\n\tterminalAvailable = !!payload.available;\n\tsetControlsEnabled(terminalAvailable);\n\tconst pe = !!payload.persistenceEnabled;\n\ttmuxPersistenceEnabled = pe;\n\tconst pa = !!payload.persistenceAvailable;\n\tconst paid =\n\t\ttypeof payload.activeWindowId === \"string\" && payload.activeWindowId.trim() ? payload.activeWindowId.trim() : null;\n\tif (paid) activeWindowId = paid;\n\tpendingWindowId = null;\n\tconst ic = payload.tmuxInstallCommand || \"\";\n\tconst shouldOffer = terminalAvailable && !pe && !pa && ic.length > 0;\n\tconst first = shouldOffer && !tmuxInstallPromptSeen;\n\ttmuxInstallCommand = shouldOffer ? ic : \"\";\n\tif (installCommandEl) installCommandEl.textContent = tmuxInstallCommand;\n\tif (installTmuxBtn) installTmuxBtn.textContent = first ? \"Run install command (first time)\" : \"Run install command\";\n\tsetInstallActionsVisible(shouldOffer);\n\tif (metaEl)\n\t\tmetaEl.textContent = terminalAvailable\n\t\t\t? pe\n\t\t\t\t? `Persistent tmux session, user ${payload.user || \"unknown\"}`\n\t\t\t\t: `Ephemeral host shell, user ${payload.user || \"unknown\"}`\n\t\t\t: \"Host shell unavailable\";\n\tif (hintEl) {\n\t\tif (!terminalAvailable) hintEl.textContent = \"Unable to open host shell.\";\n\t\telse if (pe)\n\t\t\thintEl.textContent =\n\t\t\t\t\"Interactive host shell with persistent tmux session. Click inside terminal and type commands directly.\";\n\t\telse if (pa)\n\t\t\thintEl.textContent =\n\t\t\t\t\"Interactive host shell (ephemeral). Enable tmux persistence from terminal settings when available.\";\n\t\telse if (ic)\n\t\t\thintEl.textContent = first\n\t\t\t\t? \"First connection tip: run the install command once to enable persistent tmux sessions.\"\n\t\t\t\t: `Interactive host shell (ephemeral). Install tmux for persistence: ${ic}`;\n\t\telse hintEl.textContent = \"Interactive host shell (ephemeral). Install tmux to persist sessions across reconnects.\";\n\t}\n\tif (first) markTmuxInstallPromptSeen();\n\trenderWindowTabs();\n\tsetWindowControlsEnabled();\n\tif (terminalAvailable) {\n\t\tkickResizeSettleLoop();\n\t\tupdateSizeIndicator(xterm?.cols || 0, xterm?.rows || 0);\n\t\tif (pe) {\n\t\t\tsetStatus(\"Connected to host shell with persistent tmux session.\", \"ok\");\n\t\t\tstartWindowsRefreshLoop();\n\t\t\tvoid refreshTerminalWindows({ preferredWindowId: activeWindowId, silent: true });\n\t\t} else {\n\t\t\tsetStatus(\"Connected to host shell (ephemeral session).\", \"ok\");\n\t\t\tclearWindowsRefreshTimer();\n\t\t}\n\t\tflushInputQueue();\n\t\tif (xterm) xterm.focus();\n\t} else {\n\t\tclearWindowsRefreshTimer();\n\t\tupdateSizeIndicator(0, 0);\n\t\tsetStatus(\"Failed to open host shell.\", \"error\");\n\t}\n}\n\nfunction handleTerminalMessage(payload: TerminalMessage): void {\n\tif (!(payload && typeof payload === \"object\")) return;\n\tswitch (payload.type) {\n\t\tcase \"ready\":\n\t\t\tapplyReadyPayload(payload as unknown as ReadyPayload);\n\t\t\tbreak;\n\t\tcase \"active_window\":\n\t\t\thandleActiveWindowEvent(payload);\n\t\t\tbreak;\n\t\tcase \"output\":\n\t\t\tif (payload.encoding === \"base64\") {\n\t\t\t\tconst b = decodeBase64ToBytes(payload.data || \"\");\n\t\t\t\tif (b) appendOutputChunk(b, false);\n\t\t\t} else appendOutputChunk(payload.data || \"\", false);\n\t\t\tbreak;\n\t\tcase \"status\":\n\t\t\tsetStatus(payload.text || \"\", payload.level || \"\");\n\t\t\tbreak;\n\t\tcase \"error\":\n\t\t\tsetStatus(payload.error || \"Terminal error\", \"error\");\n\t\t\tbreak;\n\t\tcase \"pong\":\n\t\t\tbreak;\n\t\tdefault:\n\t\t\tbreak;\n\t}\n}\n\nfunction connectTerminalSocket(): void {\n\tif (typeof WebSocket === \"undefined\") {\n\t\tsetStatus(\"WebSocket not supported in this browser\", \"error\");\n\t\treturn;\n\t}\n\tclearReconnectTimer();\n\tclearResizeSettleTimers();\n\tcloseTerminalSocket();\n\tlastSentCols = 0;\n\tlastSentRows = 0;\n\tconst proto = location.protocol === \"https:\" ? \"wss:\" : \"ws:\";\n\tlet wsUrl = `${proto}//${location.host}/api/terminal/ws`;\n\tconst tw = pendingWindowId || activeWindowId;\n\tif (tmuxPersistenceEnabled && tw) wsUrl += `?window=${encodeURIComponent(tw)}`;\n\tsocket = new WebSocket(wsUrl);\n\tsetStatus(\"Connecting terminal websocket...\");\n\tsocket.onopen = () => setStatus(\"Terminal websocket connected.\", \"ok\");\n\tsocket.onmessage = (ev: MessageEvent) => {\n\t\tlet p: TerminalMessage | null = null;\n\t\ttry {\n\t\t\tp = JSON.parse(ev.data as string);\n\t\t} catch {\n\t\t\treturn;\n\t\t}\n\t\tif (p) handleTerminalMessage(p);\n\t};\n\tsocket.onerror = () => {\n\t\t/* onclose handles */\n\t};\n\tsocket.onclose = () => {\n\t\tsocket = null;\n\t\tsetControlsEnabled(false);\n\t\tterminalAvailable = false;\n\t\tclearWindowsRefreshTimer();\n\t\tsetWindowControlsEnabled();\n\t\tif (shuttingDown) return;\n\t\tsetStatus(\"Terminal disconnected. Reconnecting...\", \"error\");\n\t\tscheduleReconnect();\n\t};\n}\n\nfunction sendControl(action: string): void {\n\tif (terminalAvailable) sendSocketMessage({ type: \"control\", action });\n}\n\nfunction bindEvents(): void {\n\tif (newTabBtn)\n\t\tnewTabBtn.addEventListener(\"click\", () => {\n\t\t\tvoid createTerminalWindow();\n\t\t});\n\tif (ctrlCBtn) ctrlCBtn.addEventListener(\"click\", () => sendControl(\"ctrl_c\"));\n\tif (clearBtn) clearBtn.addEventListener(\"click\", () => sendControl(\"clear\"));\n\tif (restartBtn) restartBtn.addEventListener(\"click\", () => sendControl(\"restart\"));\n\tif (installTmuxBtn)\n\t\tinstallTmuxBtn.addEventListener(\"click\", () => {\n\t\t\tif (!(terminalAvailable && tmuxInstallCommand)) return;\n\t\t\tif (!sendSocketMessage({ type: \"input\", data: `${tmuxInstallCommand}\\n` })) {\n\t\t\t\tsetStatus(\"Failed to queue install command.\", \"error\");\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tsetStatus(`Queued install command: ${tmuxInstallCommand}`, \"ok\");\n\t\t\tif (xterm) xterm.focus();\n\t\t});\n\tif (copyInstallBtn)\n\t\tcopyInstallBtn.addEventListener(\"click\", async () => {\n\t\t\tif (!tmuxInstallCommand) return;\n\t\t\tif (!navigator.clipboard?.writeText) {\n\t\t\t\tsetStatus(\"Clipboard API unavailable in this browser.\", \"error\");\n\t\t\t\treturn;\n\t\t\t}\n\t\t\ttry {\n\t\t\t\tawait navigator.clipboard.writeText(tmuxInstallCommand);\n\t\t\t\tsetStatus(\"Install command copied to clipboard.\", \"ok\");\n\t\t\t} catch {\n\t\t\t\tsetStatus(\"Failed to copy install command.\", \"error\");\n\t\t\t}\n\t\t});\n}\n\n// Static HTML template for terminal page layout. No user input is interpolated.\nfunction buildTerminalHtml(): string {\n\treturn [\n\t\t'<div class=\"terminal-page\">',\n\t\t'<div class=\"terminal-toolbar\">',\n\t\t'<div class=\"terminal-heading\">',\n\t\t'<h2 class=\"text-lg font-medium text-[var(--text-strong)]\">Terminal</h2>',\n\t\t'<div id=\"terminalMeta\" class=\"terminal-meta\"></div>',\n\t\t\"</div>\",\n\t\t'<div class=\"terminal-actions\">',\n\t\t'<div id=\"terminalSize\" class=\"terminal-size\" title=\"Terminal size (columns \\u00d7 rows)\">\\u2014\\u00d7\\u2014</div>',\n\t\t'<button id=\"terminalCtrlC\" class=\"logs-btn\" type=\"button\" title=\"Send Ctrl+C\">Ctrl+C</button>',\n\t\t'<button id=\"terminalClear\" class=\"logs-btn\" type=\"button\" title=\"Send Ctrl+L\">Clear</button>',\n\t\t'<button id=\"terminalRestart\" class=\"logs-btn\" type=\"button\">Restart</button>',\n\t\t\"</div></div>\",\n\t\t'<div class=\"terminal-tabs-bar\">',\n\t\t'<div id=\"terminalTabs\" class=\"terminal-tabs\" aria-label=\"tmux windows\"></div>',\n\t\t'<button id=\"terminalNewTab\" class=\"logs-btn terminal-new-tab\" type=\"button\" title=\"Create tmux window\">+ Tab</button>',\n\t\t\"</div>\",\n\t\t'<div class=\"terminal-output-wrap\">',\n\t\t'<div id=\"terminalOutput\" class=\"terminal-output\" aria-label=\"Host terminal output\"></div>',\n\t\t\"</div>\",\n\t\t'<div id=\"terminalStatus\" class=\"terminal-status\"></div>',\n\t\t'<div id=\"terminalHint\" class=\"terminal-hint\">Interactive host shell. Click inside terminal and type commands directly.</div>',\n\t\t'<div id=\"terminalHintActions\" class=\"terminal-hint-actions\" hidden>',\n\t\t'<code id=\"terminalInstallCommand\" class=\"terminal-hint-code\"></code>',\n\t\t'<button id=\"terminalInstallTmux\" class=\"logs-btn terminal-hint-btn terminal-hint-btn-primary\" type=\"button\">Run install command</button>',\n\t\t'<button id=\"terminalCopyInstall\" class=\"logs-btn terminal-hint-btn\" type=\"button\">Copy</button>',\n\t\t\"</div></div>\",\n\t].join(\"\");\n}\n\nexport async function initTerminal(container: HTMLElement): Promise<void> {\n\t_container = container;\n\tshuttingDown = false;\n\ttmuxInstallPromptSeen = readTmuxInstallPromptSeen();\n\ttmuxInstallCommand = \"\";\n\tcontainer.style.cssText = \"display:flex;flex-direction:column;padding:0;overflow:hidden;min-height:0;\";\n\n\t// Safe: static HTML with no user-supplied values\n\tconst tpl = document.createElement(\"template\");\n\ttpl.innerHTML = buildTerminalHtml();\n\tcontainer.appendChild(tpl.content);\n\n\tterminalEl = container.querySelector(\"#terminalOutput\");\n\tmetaEl = container.querySelector(\"#terminalMeta\");\n\tstatusEl = container.querySelector(\"#terminalStatus\");\n\thintEl = container.querySelector(\"#terminalHint\");\n\thintActionsEl = container.querySelector(\"#terminalHintActions\");\n\tinstallCommandEl = container.querySelector(\"#terminalInstallCommand\");\n\tsizeEl = container.querySelector(\"#terminalSize\");\n\ttabsEl = container.querySelector(\"#terminalTabs\");\n\tnewTabBtn = container.querySelector(\"#terminalNewTab\");\n\tctrlCBtn = container.querySelector(\"#terminalCtrlC\");\n\tclearBtn = container.querySelector(\"#terminalClear\");\n\trestartBtn = container.querySelector(\"#terminalRestart\");\n\tinstallTmuxBtn = container.querySelector(\"#terminalInstallTmux\");\n\tcopyInstallBtn = container.querySelector(\"#terminalCopyInstall\");\n\n\tsetStatus(\"Initializing terminal...\");\n\tsetControlsEnabled(false);\n\trenderWindowTabs();\n\tbindEvents();\n\n\ttry {\n\t\tawait initXterm();\n\t\tawait refreshTerminalWindows({ silent: true });\n\t\tconnectTerminalSocket();\n\t} catch (err) {\n\t\tsetStatus((err as Error).message || \"Failed to initialize terminal\", \"error\");\n\t}\n}\n\nexport function teardownTerminal(): void {\n\tshuttingDown = true;\n\tclearReconnectTimer();\n\tclearResizeSettleTimers();\n\tcloseTerminalSocket();\n\tclearInputQueue();\n\tclearWindowsRefreshTimer();\n\tdisposeXterm();\n\tif (_container) while (_container.firstChild) _container.removeChild(_container.firstChild);\n\t_container = null;\n\tterminalEl = null;\n\tmetaEl = null;\n\tstatusEl = null;\n\thintEl = null;\n\thintActionsEl = null;\n\tinstallCommandEl = null;\n\tsizeEl = null;\n\ttabsEl = null;\n\tnewTabBtn = null;\n\tctrlCBtn = null;\n\tclearBtn = null;\n\trestartBtn = null;\n\tinstallTmuxBtn = null;\n\tcopyInstallBtn = null;\n\tterminalAvailable = false;\n\ttmuxPersistenceEnabled = false;\n\tterminalWindows = [];\n\tactiveWindowId = null;\n\tpendingWindowId = null;\n\tcreatingWindow = false;\n\ttmuxInstallCommand = \"\";\n}\n","// ── Webhooks page (Preact + Signals) ────────────────────────\n\nimport { signal, useSignal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect, useRef, useState } from \"preact/hooks\";\nimport * as gon from \"../gon\";\nimport { parseAgentsListPayload, sendRpc } from \"../helpers\";\nimport { models as modelsSig } from \"../stores/model-store\";\nimport { ComboSelect, ConfirmDialog, Modal, ModelSelect, requestConfirm } from \"../ui\";\n\n// ── Types ───────────────────────────────────────────────────\n\ninterface Webhook {\n\tid: string;\n\tpublicId: string;\n\tname: string;\n\tdescription?: string;\n\tenabled: boolean;\n\tsourceProfile?: string;\n\tagentId?: string;\n\tmodel?: string;\n\tauthMode?: string;\n\tsessionMode?: string;\n\tsystemPromptSuffix?: string;\n\tdeliveryCount?: number;\n}\n\ninterface WebhookProfile {\n\tid: string;\n\tdisplayName: string;\n\tdefaultAuthMode?: string;\n}\n\ninterface Delivery {\n\tid: string;\n\tstatus: string;\n\teventType?: string;\n\treceivedAt?: string;\n\tdurationMs?: number;\n\tsessionKey?: string;\n}\n\ninterface ComboOption {\n\tvalue: string;\n\tlabel: string;\n}\n\n// ── State ─────────────��────────────────────────────────────────────────\n\nconst webhooks = signal<Webhook[]>((gon.get(\"webhooks\") as Webhook[]) || []);\nconst profiles = signal<WebhookProfile[]>((gon.get(\"webhook_profiles\") as WebhookProfile[]) || []);\nconst showCreateModal = signal(false);\nconst editingWebhook = signal<Webhook | null>(null);\nconst viewingDeliveries = signal<string | null>(null); // webhook id or null\nconst deliveries = signal<Delivery[]>([]);\nconst publicBaseUrl = signal(\"\");\n\nlet _container: HTMLElement | null = null;\n\nfunction fetchPublicBaseUrl(): void {\n\t// Prefer ngrok public URL, then tailscale funnel, then window.location.origin.\n\tfetch(\"/api/ngrok/status\")\n\t\t.then((r) => (r.ok ? r.json() : null))\n\t\t.then((data: { public_url?: string } | null) => {\n\t\t\tif (data?.public_url) {\n\t\t\t\tpublicBaseUrl.value = data.public_url.replace(/\\/$/, \"\");\n\t\t\t\treturn;\n\t\t\t}\n\t\t\treturn fetch(\"/api/tailscale/status\")\n\t\t\t\t.then((r) => (r.ok ? r.json() : null))\n\t\t\t\t.then((ts: { mode?: string; url?: string } | null) => {\n\t\t\t\t\tif (ts?.mode === \"funnel\" && ts?.url) {\n\t\t\t\t\t\tpublicBaseUrl.value = ts.url.replace(/\\/$/, \"\");\n\t\t\t\t\t} else {\n\t\t\t\t\t\tpublicBaseUrl.value = window.location.origin;\n\t\t\t\t\t}\n\t\t\t\t});\n\t\t})\n\t\t.catch(() => {\n\t\t\tpublicBaseUrl.value = window.location.origin;\n\t\t});\n}\n\nexport function initWebhooks(container: HTMLElement): void {\n\t_container = container;\n\tcontainer.style.cssText = \"padding:0;overflow:hidden;\";\n\twebhooks.value = (gon.get(\"webhooks\") as Webhook[]) || [];\n\tprofiles.value = (gon.get(\"webhook_profiles\") as WebhookProfile[]) || [];\n\tfetchPublicBaseUrl();\n\trender(<WebhooksPageComponent />, container);\n}\n\nexport function teardownWebhooks(): void {\n\tif (_container) render(null, _container);\n\t_container = null;\n}\n\nfunction loadWebhooks(): void {\n\tsendRpc(\"webhooks.list\", {}).then((res) => {\n\t\tif (res?.ok) webhooks.value = (res.payload as Webhook[]) || [];\n\t});\n}\n\nfunction loadDeliveries(webhookId: string): void {\n\tsendRpc(\"webhooks.deliveries\", { webhookId, limit: 50, offset: 0 }).then((res) => {\n\t\tif (res?.ok) deliveries.value = (res.payload as Delivery[]) || [];\n\t});\n}\n\n// ── Main Page ─────────────��────────────────────────────────────────────\n\nfunction WebhooksPageComponent(): VNode {\n\treturn (\n\t\t<>\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 overflow-y-auto\">\n\t\t\t\t{viewingDeliveries.value ? <DeliveriesPanel /> : <WebhooksListPanel />}\n\t\t\t</div>\n\t\t\t<WebhookModal />\n\t\t\t<ConfirmDialog />\n\t\t</>\n\t);\n}\n\n// ── Webhooks List ────────────���─────────────────────────────────────────\n\nfunction WebhooksListPanel(): VNode {\n\treturn (\n\t\t<div className=\"p-4 flex flex-col gap-4\">\n\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Webhooks</h2>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\teditingWebhook.value = null;\n\t\t\t\t\t\tshowCreateModal.value = true;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t+ Create webhook\n\t\t\t\t</button>\n\t\t\t</div>\n\n\t\t\t{webhooks.value.length === 0 ? (\n\t\t\t\t<div className=\"text-sm text-[var(--muted)] py-8 text-center\">No webhooks configured.</div>\n\t\t\t) : (\n\t\t\t\t<div className=\"flex flex-col gap-2\">\n\t\t\t\t\t{webhooks.value.map((wh) => (\n\t\t\t\t\t\t<WebhookCard key={wh.id} webhook={wh} />\n\t\t\t\t\t))}\n\t\t\t\t</div>\n\t\t\t)}\n\n\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\tUse the \"Copy test command\" button on each webhook, or the{\" \"}\n\t\t\t\t<a\n\t\t\t\t\thref=\"https://hoppscotch.io/download\"\n\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\tclassName=\"text-[var(--accent)] underline\"\n\t\t\t\t>\n\t\t\t\t\tHoppscotch desktop app\n\t\t\t\t</a>{\" \"}\n\t\t\t\tto test.\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nfunction CopyTestCommandButton({ webhook }: { webhook: Webhook }): VNode {\n\tconst [copied, setCopied] = useState(false);\n\tconst url = `${publicBaseUrl.value || window.location.origin}/api/webhooks/ingest/${webhook.publicId}`;\n\tconst cmd = `curl -sk -X POST ${url} \\\\\n  -H 'Content-Type: application/json' \\\\\n  -d '{\"event\": \"test\", \"timestamp\": \"${new Date().toISOString()}\"}'`;\n\n\treturn (\n\t\t<button\n\t\t\tclassName=\"provider-btn provider-btn-sm provider-btn-secondary\"\n\t\t\tstyle={{ whiteSpace: \"nowrap\" }}\n\t\t\ttitle={copied ? \"Copied!\" : \"Copy a curl command to test this webhook\"}\n\t\t\tonClick={() => {\n\t\t\t\tnavigator.clipboard.writeText(cmd).then(() => {\n\t\t\t\t\tsetCopied(true);\n\t\t\t\t\tsetTimeout(() => setCopied(false), 2000);\n\t\t\t\t});\n\t\t\t}}\n\t\t>\n\t\t\t{copied ? \"Copied!\" : \"Copy test command\"}\n\t\t</button>\n\t);\n}\n\nfunction WebhookCard({ webhook }: { webhook: Webhook }): VNode {\n\tconst wh = webhook;\n\tconst profileInfo = profiles.value.find((p) => p.id === wh.sourceProfile);\n\tconst profileName = profileInfo?.displayName || wh.sourceProfile || \"Generic\";\n\n\treturn (\n\t\t<div className=\"channel-card\">\n\t\t\t<div className=\"flex items-center justify-between\">\n\t\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<div className=\"text-sm font-medium text-[var(--text-strong)]\">{wh.name}</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mt-0.5\">\n\t\t\t\t\t\t\t{profileName}\n\t\t\t\t\t\t\t{wh.agentId ? ` \\u00B7 Agent: ${wh.agentId}` : \"\"}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\n\t\t\t\t<div className=\"flex items-center gap-2\">\n\t\t\t\t\t{wh.deliveryCount != null && wh.deliveryCount > 0 ? (\n\t\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">{wh.deliveryCount} deliveries</span>\n\t\t\t\t\t) : (\n\t\t\t\t\t\t\"\"\n\t\t\t\t\t)}\n\n\t\t\t\t\t<span\n\t\t\t\t\t\tclassName={`provider-item-badge ${wh.enabled ? \"configured\" : \"\"}`}\n\t\t\t\t\t\tstyle={wh.enabled ? undefined : { background: \"var(--surface2)\", color: \"var(--muted)\" }}\n\t\t\t\t\t>\n\t\t\t\t\t\t{wh.enabled ? \"active\" : \"paused\"}\n\t\t\t\t\t</span>\n\n\t\t\t\t\t<label className=\"cron-toggle\" title={wh.enabled ? \"Pause webhook\" : \"Enable webhook\"}>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\ttype=\"checkbox\"\n\t\t\t\t\t\t\tchecked={wh.enabled}\n\t\t\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\t\t\tsendRpc(\"webhooks.update\", {\n\t\t\t\t\t\t\t\t\tid: wh.id,\n\t\t\t\t\t\t\t\t\tpatch: { enabled: (e.target as HTMLInputElement).checked },\n\t\t\t\t\t\t\t\t}).then(() => loadWebhooks());\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<span className=\"cron-slider\" />\n\t\t\t\t\t</label>\n\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"provider-btn provider-btn-sm provider-btn-secondary\"\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tviewingDeliveries.value = wh.id;\n\t\t\t\t\t\t\tloadDeliveries(wh.id);\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\tDeliveries\n\t\t\t\t\t</button>\n\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"provider-btn provider-btn-sm provider-btn-secondary\"\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\teditingWebhook.value = wh;\n\t\t\t\t\t\t\tshowCreateModal.value = true;\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\tEdit\n\t\t\t\t\t</button>\n\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"provider-btn provider-btn-sm provider-btn-danger\"\n\t\t\t\t\t\tonClick={async () => {\n\t\t\t\t\t\t\tconst ok = await requestConfirm(\n\t\t\t\t\t\t\t\t`Delete webhook \"${wh.name}\"? This removes all delivery records. Chat sessions created by deliveries are preserved.`,\n\t\t\t\t\t\t\t);\n\t\t\t\t\t\t\tif (ok) {\n\t\t\t\t\t\t\t\tsendRpc(\"webhooks.delete\", { id: wh.id }).then(() => loadWebhooks());\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\tDelete\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t<div className=\"flex items-center gap-2 mt-1\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)] font-mono select-all flex-1 min-w-0 truncate\">\n\t\t\t\t\t{publicBaseUrl.value || window.location.origin}/api/webhooks/ingest/{wh.publicId}\n\t\t\t\t</div>\n\t\t\t\t<CopyTestCommandButton webhook={wh} />\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// ── Deliveries Panel ───────────────────────────────────────────────────\n\nfunction DeliveriesPanel(): VNode {\n\tconst wh = webhooks.value.find((w) => w.id === viewingDeliveries.value);\n\tconst name = wh?.name || \"Webhook\";\n\n\treturn (\n\t\t<div className=\"p-4 flex flex-col gap-4\">\n\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tviewingDeliveries.value = null;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\tBack\n\t\t\t\t</button>\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">\n\t\t\t\t\t{name} {\"\\u2014\"} Deliveries\n\t\t\t\t</h2>\n\t\t\t</div>\n\n\t\t\t{deliveries.value.length === 0 ? (\n\t\t\t\t<div className=\"text-sm text-[var(--muted)] py-8 text-center\">No deliveries yet.</div>\n\t\t\t) : (\n\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t{deliveries.value.map((d) => (\n\t\t\t\t\t\t<DeliveryRow key={d.id} delivery={d} />\n\t\t\t\t\t))}\n\t\t\t\t</div>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\nfunction DeliveryRow({ delivery }: { delivery: Delivery }): VNode {\n\tconst d = delivery;\n\tconst statusColors: Record<string, string> = {\n\t\tcompleted: \"var(--ok)\",\n\t\tfailed: \"var(--error)\",\n\t\tprocessing: \"var(--warning)\",\n\t\tfiltered: \"var(--muted)\",\n\t\tdeduplicated: \"var(--muted)\",\n\t\trejected: \"var(--error)\",\n\t};\n\tconst statusColor = statusColors[d.status];\n\n\treturn (\n\t\t<div className=\"provider-card text-xs\">\n\t\t\t<div className=\"flex items-center gap-3 flex-1 min-w-0\">\n\t\t\t\t<span className=\"font-medium\" style={statusColor ? { color: statusColor } : undefined}>\n\t\t\t\t\t{d.status}\n\t\t\t\t</span>\n\t\t\t\t<span className=\"text-[var(--muted)]\">{d.eventType || \"\\u2014\"}</span>\n\t\t\t\t<span className=\"text-[var(--muted)]\">{d.receivedAt ? new Date(d.receivedAt).toLocaleString() : \"\"}</span>\n\t\t\t\t{d.durationMs != null ? <span className=\"text-[var(--muted)]\">{d.durationMs}ms</span> : \"\"}\n\t\t\t</div>\n\t\t\t<div className=\"flex items-center gap-2\">\n\t\t\t\t{d.sessionKey ? <span className=\"text-[var(--muted)] font-mono text-[10px]\">{d.sessionKey}</span> : \"\"}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// ── Create / Edit Modal ───────────────���────────────────────────────────\n\nfunction WebhookModal(): VNode | null {\n\tconst isEdit = !!editingWebhook.value;\n\tconst saving = useSignal(false);\n\tconst error = useSignal(\"\");\n\n\tconst nameRef = useRef<HTMLInputElement>(null);\n\tconst descRef = useRef<HTMLInputElement>(null);\n\tconst promptSuffixRef = useRef<HTMLTextAreaElement>(null);\n\tconst authSecretRef = useRef<HTMLInputElement>(null);\n\n\tconst selectedAgent = useSignal(isEdit ? editingWebhook.value?.agentId || \"\" : \"\");\n\tconst selectedModel = useSignal(isEdit ? editingWebhook.value?.model || \"\" : \"\");\n\tconst sourceProfile = useSignal(isEdit ? editingWebhook.value?.sourceProfile || \"generic\" : \"generic\");\n\tconst authMode = useSignal(isEdit ? editingWebhook.value?.authMode || \"static_header\" : \"static_header\");\n\tconst sessionMode = useSignal(isEdit ? editingWebhook.value?.sessionMode || \"per_delivery\" : \"per_delivery\");\n\n\tconst gonAgents = parseAgentsListPayload(gon.get(\"agents\") as Parameters<typeof parseAgentsListPayload>[0]);\n\tconst agentOptions: ComboOption[] = (Array.isArray(gonAgents?.agents) ? gonAgents.agents : []).map((a) => ({\n\t\tvalue: a.id as string,\n\t\tlabel: (a.name as string) || (a.id as string),\n\t}));\n\n\tuseEffect(() => {\n\t\tif (editingWebhook.value) {\n\t\t\tselectedAgent.value = editingWebhook.value.agentId || \"\";\n\t\t\tselectedModel.value = editingWebhook.value.model || \"\";\n\t\t\tsourceProfile.value = editingWebhook.value.sourceProfile || \"generic\";\n\t\t\tauthMode.value = editingWebhook.value.authMode || \"static_header\";\n\t\t\tsessionMode.value = editingWebhook.value.sessionMode || \"per_delivery\";\n\t\t} else {\n\t\t\tselectedAgent.value = \"\";\n\t\t\tselectedModel.value = \"\";\n\t\t\tsourceProfile.value = \"generic\";\n\t\t\tauthMode.value = \"static_header\";\n\t\t\tsessionMode.value = \"per_delivery\";\n\t\t}\n\t}, [editingWebhook.value]);\n\n\tfunction onSave(e: Event): void {\n\t\te.preventDefault();\n\t\tsaving.value = true;\n\t\terror.value = \"\";\n\n\t\tconst name = nameRef.current?.value?.trim();\n\t\tif (!name) {\n\t\t\terror.value = \"Name is required\";\n\t\t\tsaving.value = false;\n\t\t\treturn;\n\t\t}\n\n\t\tconst params: Record<string, unknown> = {\n\t\t\tname,\n\t\t\tdescription: descRef.current?.value?.trim() || null,\n\t\t\tagentId: selectedAgent.value || null,\n\t\t\tmodel: selectedModel.value || null,\n\t\t\tsystemPromptSuffix: promptSuffixRef.current?.value?.trim() || null,\n\t\t\tauthMode: authMode.value,\n\t\t\tsessionMode: sessionMode.value,\n\t\t};\n\t\t// source_profile is immutable after creation -- only include on create.\n\t\tif (!isEdit) {\n\t\t\tparams.sourceProfile = sourceProfile.value;\n\t\t}\n\n\t\t// Build auth config based on mode. The key name must match what\n\t\t// the Rust verify function expects: \"token\" for bearer/gitlab,\n\t\t// \"secret\" for all HMAC-based modes, \"header\"+\"value\" for static.\n\t\tconst secret = authSecretRef.current?.value?.trim();\n\t\tif (secret && authMode.value !== \"none\") {\n\t\t\tif (authMode.value === \"static_header\") {\n\t\t\t\tparams.authConfig = { header: \"X-Webhook-Secret\", value: secret };\n\t\t\t} else if (authMode.value === \"bearer\" || authMode.value === \"gitlab_token\") {\n\t\t\t\tparams.authConfig = { token: secret };\n\t\t\t} else {\n\t\t\t\t// All HMAC-based modes (github, stripe, linear, pagerduty, sentry)\n\t\t\t\tparams.authConfig = { secret };\n\t\t\t}\n\t\t}\n\n\t\tconst method = isEdit ? \"webhooks.update\" : \"webhooks.create\";\n\t\tconst rpcParams = isEdit ? { id: editingWebhook.value?.id, patch: params } : params;\n\n\t\tsendRpc(method, rpcParams).then((res) => {\n\t\t\tsaving.value = false;\n\t\t\tif (res?.ok) {\n\t\t\t\tshowCreateModal.value = false;\n\t\t\t\teditingWebhook.value = null;\n\t\t\t\tloadWebhooks();\n\t\t\t} else {\n\t\t\t\terror.value = res?.error?.message || \"Failed to save\";\n\t\t\t}\n\t\t});\n\t}\n\n\tconst profileOptions: ComboOption[] = profiles.value.map((p) => ({\n\t\tvalue: p.id,\n\t\tlabel: p.displayName,\n\t}));\n\n\tconst authOptions: ComboOption[] = [\n\t\t{ value: \"none\", label: \"None (testing only)\" },\n\t\t{ value: \"static_header\", label: \"Static Header\" },\n\t\t{ value: \"bearer\", label: \"Bearer Token\" },\n\t\t{ value: \"github_hmac_sha256\", label: \"GitHub HMAC-SHA256\" },\n\t\t{ value: \"gitlab_token\", label: \"GitLab Token\" },\n\t\t{ value: \"stripe_webhook_signature\", label: \"Stripe Signature\" },\n\t\t{ value: \"linear_webhook_signature\", label: \"Linear Signature\" },\n\t\t{ value: \"pagerduty_v2_signature\", label: \"PagerDuty v2 Signature\" },\n\t\t{ value: \"sentry_webhook_signature\", label: \"Sentry Signature\" },\n\t];\n\n\tconst sessionOptions: ComboOption[] = [\n\t\t{ value: \"per_delivery\", label: \"New session per delivery\" },\n\t\t{ value: \"per_entity\", label: \"Group by entity (PR, issue, etc.)\" },\n\t\t{ value: \"named_session\", label: \"Named session (accumulative)\" },\n\t];\n\n\tconst wh = editingWebhook.value;\n\n\treturn (\n\t\t<Modal\n\t\t\tshow={showCreateModal.value}\n\t\t\tonClose={() => {\n\t\t\t\tshowCreateModal.value = false;\n\t\t\t\teditingWebhook.value = null;\n\t\t\t}}\n\t\t\ttitle={isEdit ? \"Edit Webhook\" : \"Create Webhook\"}\n\t\t>\n\t\t\t<form onSubmit={onSave} className=\"provider-key-form\" style={{ maxWidth: \"460px\" }}>\n\t\t\t\t{error.value && <div className=\"text-xs text-[var(--error)] mb-2\">{error.value}</div>}\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Name</label>\n\t\t\t\t<input\n\t\t\t\t\tref={nameRef}\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tplaceholder=\"e.g. GitHub PR Review\"\n\t\t\t\t\tvalue={wh?.name || \"\"}\n\t\t\t\t/>\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Description</label>\n\t\t\t\t<input\n\t\t\t\t\tref={descRef}\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tplaceholder=\"Optional description\"\n\t\t\t\t\tvalue={wh?.description || \"\"}\n\t\t\t\t/>\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\tSource Profile{isEdit ? \" (read-only after creation)\" : \"\"}\n\t\t\t\t</label>\n\t\t\t\t<select\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={sourceProfile.value}\n\t\t\t\t\tdisabled={isEdit}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\tsourceProfile.value = (e.target as HTMLSelectElement).value;\n\t\t\t\t\t\tconst prof = profiles.value.find((p) => p.id === (e.target as HTMLSelectElement).value);\n\t\t\t\t\t\tif (prof?.defaultAuthMode) authMode.value = prof.defaultAuthMode;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{profileOptions.map((o) => (\n\t\t\t\t\t\t<option key={o.value} value={o.value}>\n\t\t\t\t\t\t\t{o.label}\n\t\t\t\t\t\t</option>\n\t\t\t\t\t))}\n\t\t\t\t</select>\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Auth Mode</label>\n\t\t\t\t<select\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={authMode.value}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\tauthMode.value = (e.target as HTMLSelectElement).value;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{authOptions.map((o) => (\n\t\t\t\t\t\t<option key={o.value} value={o.value}>\n\t\t\t\t\t\t\t{o.label}\n\t\t\t\t\t\t</option>\n\t\t\t\t\t))}\n\t\t\t\t</select>\n\n\t\t\t\t{authMode.value !== \"none\" && (\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Secret / Token</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tref={authSecretRef}\n\t\t\t\t\t\t\ttype=\"password\"\n\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\tplaceholder=\"Webhook secret or token\"\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Agent</label>\n\t\t\t\t<ComboSelect\n\t\t\t\t\toptions={agentOptions}\n\t\t\t\t\tvalue={selectedAgent.value}\n\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\tselectedAgent.value = v;\n\t\t\t\t\t}}\n\t\t\t\t\tplaceholder=\"Default agent\"\n\t\t\t\t\tsearchPlaceholder={\"Search agents\\u2026\"}\n\t\t\t\t/>\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Model</label>\n\t\t\t\t<ModelSelect\n\t\t\t\t\tmodels={modelsSig.value}\n\t\t\t\t\tvalue={selectedModel.value}\n\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\tselectedModel.value = v;\n\t\t\t\t\t}}\n\t\t\t\t\tplaceholder={\n\t\t\t\t\t\tmodelsSig.value.length > 0\n\t\t\t\t\t\t\t? `(default: ${modelsSig.value[0].displayName || modelsSig.value[0].id})`\n\t\t\t\t\t\t\t: \"(server default)\"\n\t\t\t\t\t}\n\t\t\t\t/>\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Session Mode</label>\n\t\t\t\t<select\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={sessionMode.value}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\tsessionMode.value = (e.target as HTMLSelectElement).value;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{sessionOptions.map((o) => (\n\t\t\t\t\t\t<option key={o.value} value={o.value}>\n\t\t\t\t\t\t\t{o.label}\n\t\t\t\t\t\t</option>\n\t\t\t\t\t))}\n\t\t\t\t</select>\n\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">System Prompt Suffix (optional)</label>\n\t\t\t\t<textarea\n\t\t\t\t\tref={promptSuffixRef}\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tstyle={{\n\t\t\t\t\t\tminHeight: \"80px\",\n\t\t\t\t\t\tresize: \"vertical\",\n\t\t\t\t\t\tfontFamily: \"var(--font-mono)\",\n\t\t\t\t\t\tfontSize: \"0.75rem\",\n\t\t\t\t\t}}\n\t\t\t\t\tplaceholder=\"Additional instructions for the agent when processing this webhook...\"\n\t\t\t\t>\n\t\t\t\t\t{wh?.systemPromptSuffix || \"\"}\n\t\t\t\t</textarea>\n\n\t\t\t\t<div className=\"flex gap-2 justify-end mt-2\">\n\t\t\t\t\t<button\n\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tshowCreateModal.value = false;\n\t\t\t\t\t\t\teditingWebhook.value = null;\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\tCancel\n\t\t\t\t\t</button>\n\t\t\t\t\t<button type=\"submit\" className=\"provider-btn\" disabled={saving.value}>\n\t\t\t\t\t\t{saving.value ? \"Saving...\" : isEdit ? \"Save\" : \"Create\"}\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t</form>\n\t\t</Modal>\n\t);\n}\n","// ── Settings page (Preact + Signals) ───────────────────\n\nimport { signal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect, useRef, useState } from \"preact/hooks\";\nimport { EmojiPicker } from \"../emoji-picker\";\nimport { onEvent } from \"../events\";\nimport * as gon from \"../gon\";\nimport { refresh as refreshGon } from \"../gon\";\nimport { localizedApiErrorMessage, sendRpc } from \"../helpers\";\nimport { setLocale } from \"../i18n\";\nimport { updateIdentity, validateIdentityFields } from \"../identity-utils\";\nimport { detectPasskeyName } from \"../passkey-detect\";\nimport * as push from \"../push\";\nimport { isStandalone } from \"../pwa\";\nimport { navigate, registerPrefix } from \"../router\";\nimport { routes, settingsPath } from \"../routes\";\nimport { connected } from \"../signals\";\nimport * as S from \"../state\";\nimport { fetchPhrase } from \"../tts-phrases\";\nimport { Modal, showToast } from \"../ui\";\nimport {\n\tdecodeBase64Safe,\n\tfetchVoiceProviders,\n\tsaveVoiceKey,\n\tsaveVoiceSettings,\n\ttestTts,\n\ttoggleVoiceProvider,\n\ttranscribeAudio,\n} from \"../voice-utils\";\nimport { initAgents, teardownAgents } from \"./AgentsPage\";\nimport { initChannels, teardownChannels } from \"./ChannelsPage\";\nimport { initCrons, teardownCrons } from \"./CronsPage\";\nimport { initHooks, teardownHooks } from \"./HooksPage\";\nimport { initImages, teardownImages } from \"./ImagesPage\";\nimport { initLogs, teardownLogs } from \"./LogsPage\";\nimport { initMcp, teardownMcp } from \"./McpPage\";\nimport { initMonitoring, teardownMonitoring } from \"./MetricsPage\";\nimport { initNetworkAudit, teardownNetworkAudit } from \"./NetworkAuditPage\";\nimport { initNodes, teardownNodes } from \"./NodesPage\";\nimport { initProjects, teardownProjects } from \"./ProjectsPage\";\nimport { initProviders, teardownProviders } from \"./ProvidersPage\";\nimport { initSkills, teardownSkills } from \"./SkillsPage\";\nimport { initTerminal, teardownTerminal } from \"./TerminalPage\";\nimport { initWebhooks, teardownWebhooks } from \"./WebhooksPage\";\n\n// ── Types ───────────────────────────────────────────────────\n\ninterface IdentityData {\n\tname?: string;\n\temoji?: string;\n\ttheme?: string;\n\tuser_name?: string;\n\tsoul?: string;\n\t[key: string]: unknown;\n}\n\ninterface RpcResponse {\n\tok?: boolean;\n\tpayload?: unknown;\n\terror?: { message?: string };\n}\n\ninterface SectionItem {\n\tid?: string;\n\tlabel?: string;\n\ticon?: VNode;\n\tpage?: boolean;\n\tgroup?: string;\n}\n\ninterface EnvVar {\n\tid: string;\n\tkey: string;\n\tencrypted?: boolean;\n\tupdated_at?: string;\n}\n\ninterface PasskeyEntry {\n\tid: string;\n\tname: string;\n\tcreated_at?: string;\n}\n\ninterface ApiKeyEntry {\n\tid: string;\n\tlabel: string;\n\tkey_prefix?: string;\n\tcreated_at?: string;\n\tscopes?: string[];\n}\n\ninterface SshKeyEntry {\n\tid: number;\n\tname: string;\n\tfingerprint?: string;\n\tpublic_key?: string;\n\tencrypted?: boolean;\n\ttarget_count?: number;\n}\n\ninterface SshTargetEntry {\n\tid: number;\n\tlabel: string;\n\ttarget: string;\n\tport?: number;\n\tauth_mode?: string;\n\tkey_name?: string;\n\tknown_host?: string;\n\tis_default?: boolean;\n}\n\ninterface TestResult {\n\treachable?: boolean;\n\tfailure_hint?: string;\n}\n\ninterface ToolEntry {\n\tname?: string;\n\tdescription?: string;\n}\n\ninterface ToolGroup {\n\tlabel: string;\n\ttools: ToolEntry[];\n}\n\ninterface SkillEntry {\n\tname?: string;\n\tdescription?: string;\n\tsource?: string;\n}\n\ninterface McpServerEntry {\n\tname?: string;\n\tstate?: string;\n\ttool_count?: number;\n}\n\ninterface ToolsContextData {\n\tsession?: { model?: string; provider?: string; label?: string };\n\texecution?: { mode?: string; promptSymbol?: string };\n\tsandbox?: { enabled?: boolean; backend?: string };\n\ttools?: ToolEntry[];\n\tskills?: SkillEntry[];\n\tmcpServers?: McpServerEntry[];\n\tsupportsTools?: boolean;\n\tmcpDisabled?: boolean;\n}\n\ninterface NodeInventoryEntry {\n\tplatform?: string;\n\t[key: string]: unknown;\n}\n\ninterface RemoteExecSummary {\n\tpairedNodes: number;\n\tsshTargets: number;\n}\n\ninterface AkScopes {\n\t\"operator.read\": boolean;\n\t\"operator.write\": boolean;\n\t\"operator.approvals\": boolean;\n\t\"operator.pairing\": boolean;\n\t[key: string]: boolean;\n}\n\n// ── Module-level state ───────────────────────────────────────\n\nconst identity = signal<IdentityData | null>(null);\nconst loading = signal(true);\nconst activeSection = signal(\"identity\");\nconst activeSubPath = signal(\"\");\nconst mobileSidebarVisible = signal(true);\nlet mounted = false;\nlet containerRef: HTMLElement | null = null;\n\nfunction rerender(): void {\n\tif (containerRef) render(<SettingsPage />, containerRef);\n}\n\nfunction isMobileViewport(): boolean {\n\treturn window.innerWidth < 768;\n}\n\nfunction isSafariBrowser(): boolean {\n\tif (typeof navigator === \"undefined\") return false;\n\tconst ua = navigator.userAgent || \"\";\n\tconst vendor = navigator.vendor || \"\";\n\tif (!ua.includes(\"Safari/\")) return false;\n\tif (/(Chrome|CriOS|Chromium|Edg|OPR|FxiOS|Firefox|SamsungBrowser)/.test(ua)) return false;\n\treturn /Apple/i.test(vendor) || ua.includes(\"Safari/\");\n}\n\nfunction isMissingMethodError(res: RpcResponse | null): boolean {\n\tconst message = res?.error?.message;\n\tif (typeof message !== \"string\") return false;\n\tconst lower = message.toLowerCase();\n\treturn lower.includes(\"method\") && (lower.includes(\"not found\") || lower.includes(\"unknown\"));\n}\n\nfunction fetchMainIdentity(): Promise<RpcResponse> {\n\treturn sendRpc(\"agents.identity.get\", { agent_id: \"main\" }).then((res: RpcResponse) => {\n\t\tif (res?.ok || !isMissingMethodError(res)) return res;\n\t\treturn sendRpc(\"agent.identity.get\", {});\n\t});\n}\n\nfunction fetchIdentity(): void {\n\tif (!mounted) return;\n\tfetchMainIdentity().then((res: RpcResponse) => {\n\t\tif (res?.ok) {\n\t\t\tidentity.value = res.payload as IdentityData;\n\t\t\tloading.value = false;\n\t\t\trerender();\n\t\t} else if (mounted && !S.connected) {\n\t\t\tsetTimeout(fetchIdentity, 500);\n\t\t} else {\n\t\t\tloading.value = false;\n\t\t\trerender();\n\t\t}\n\t});\n}\n\n// ── Sidebar navigation items ─────────────────────────────────\n\nconst sections: SectionItem[] = [\n\t{ group: \"General\" },\n\t{\n\t\tid: \"identity\",\n\t\tlabel: \"Identity\",\n\t\ticon: <span className=\"icon icon-person\" />,\n\t},\n\t{\n\t\tid: \"agents\",\n\t\tlabel: \"Agents\",\n\t\ticon: <span className=\"icon icon-users\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"nodes\",\n\t\tlabel: \"Nodes\",\n\t\ticon: <span className=\"icon icon-nodes\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"projects\",\n\t\tlabel: \"Projects\",\n\t\ticon: <span className=\"icon icon-folder\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"environment\",\n\t\tlabel: \"Environment\",\n\t\ticon: <span className=\"icon icon-terminal\" />,\n\t},\n\t{\n\t\tid: \"memory\",\n\t\tlabel: \"Memory\",\n\t\ticon: <span className=\"icon icon-database\" />,\n\t},\n\t{\n\t\tid: \"notifications\",\n\t\tlabel: \"Notifications\",\n\t\ticon: <span className=\"icon icon-bell\" />,\n\t},\n\t{\n\t\tid: \"crons\",\n\t\tlabel: \"Crons\",\n\t\ticon: <span className=\"icon icon-cron\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"webhooks\",\n\t\tlabel: \"Webhooks\",\n\t\ticon: <span className=\"icon icon-webhooks\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"heartbeat\",\n\t\tlabel: \"Heartbeat\",\n\t\ticon: <span className=\"icon icon-heart\" />,\n\t\tpage: true,\n\t},\n\t{ group: \"Security\" },\n\t{\n\t\tid: \"security\",\n\t\tlabel: \"Authentication\",\n\t\ticon: <span className=\"icon icon-key\" />,\n\t},\n\t{\n\t\tid: \"vault\",\n\t\tlabel: \"Encryption\",\n\t\ticon: <span className=\"icon icon-lock\" />,\n\t},\n\t{\n\t\tid: \"ssh\",\n\t\tlabel: \"SSH\",\n\t\ticon: <span className=\"icon icon-ssh\" />,\n\t},\n\t{\n\t\tid: \"remote-access\",\n\t\tlabel: \"Remote Access\",\n\t\ticon: <span className=\"icon icon-share\" />,\n\t},\n\t{\n\t\tid: \"network-audit\",\n\t\tlabel: \"Network Audit\",\n\t\ticon: <span className=\"icon icon-shield-check\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"sandboxes\",\n\t\tlabel: \"Sandboxes\",\n\t\ticon: <span className=\"icon icon-cube\" />,\n\t\tpage: true,\n\t},\n\t{ group: \"Integrations\" },\n\t{\n\t\tid: \"channels\",\n\t\tlabel: \"Channels\",\n\t\ticon: <span className=\"icon icon-channels\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"hooks\",\n\t\tlabel: \"Hooks\",\n\t\ticon: <span className=\"icon icon-wrench\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"providers\",\n\t\tlabel: \"LLMs\",\n\t\ticon: <span className=\"icon icon-layers\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"tools\",\n\t\tlabel: \"Tools\",\n\t\ticon: <span className=\"icon icon-settings-gear\" />,\n\t},\n\t{\n\t\tid: \"mcp\",\n\t\tlabel: \"MCP\",\n\t\ticon: <span className=\"icon icon-link\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"skills\",\n\t\tlabel: \"Skills\",\n\t\ticon: <span className=\"icon icon-sparkles\" />,\n\t\tpage: true,\n\t},\n\t{\n\t\tid: \"import\",\n\t\tlabel: \"OpenClaw Import\",\n\t\ticon: <span className=\"icon icon-openclaw\" />,\n\t},\n\t{\n\t\tid: \"voice\",\n\t\tlabel: \"Voice\",\n\t\ticon: <span className=\"icon icon-microphone\" />,\n\t},\n\t{ group: \"Systems\" },\n\t{ id: \"terminal\", label: \"Terminal\", page: true },\n\t{ id: \"monitoring\", label: \"Monitoring\", page: true },\n\t{ id: \"logs\", label: \"Logs\", page: true },\n\t{ id: \"graphql\", label: \"GraphQL\" },\n\t{ id: \"config\", label: \"Configuration\" },\n];\n\nfunction getVisibleSections(): SectionItem[] {\n\tconst vs = gon.get(\"vault_status\");\n\treturn sections.filter((s) => {\n\t\tif (!s.id) return true;\n\t\tif (s.id === \"graphql\" && !gon.get(\"graphql_enabled\")) return false;\n\t\tif (s.id === \"import\" && !gon.get(\"openclaw_detected\")) return false;\n\t\tif (s.id === \"vault\" && (!vs || vs === \"disabled\")) return false;\n\t\treturn true;\n\t});\n}\n\n/** Return only items with an id (no group headings). */\nfunction getSectionItems(): SectionItem[] {\n\treturn getVisibleSections().filter((s) => s.id);\n}\n\nfunction pluralizeToolsCount(count: number, noun: string): string {\n\treturn `${count} ${noun}${count === 1 ? \"\" : \"s\"}`;\n}\n\nfunction toolsOverviewCategory(name: string | undefined): string {\n\tif (typeof name !== \"string\" || !name) return \"Core\";\n\tif (name.startsWith(\"mcp__\")) return \"MCP\";\n\tif (name === \"exec\" || name.startsWith(\"node\") || name.startsWith(\"sandbox\") || name.includes(\"checkpoint\")) {\n\t\treturn \"Execution\";\n\t}\n\tif (name.startsWith(\"session\") || name.startsWith(\"sessions_\")) return \"Sessions\";\n\tif (name.startsWith(\"memory\") || name.includes(\"memory\")) return \"Memory\";\n\tif (name.startsWith(\"browser\") || name.startsWith(\"web_\") || name.includes(\"screenshot\") || name.includes(\"fetch\")) {\n\t\treturn \"Web & Browser\";\n\t}\n\tif (name.startsWith(\"skill\") || name.includes(\"skill\")) return \"Skills\";\n\treturn \"Core\";\n}\n\nfunction groupToolsForOverview(tools: ToolEntry[]): ToolGroup[] {\n\tconst grouped = new Map<string, ToolEntry[]>();\n\t(tools || []).forEach((tool) => {\n\t\tconst category = toolsOverviewCategory(tool?.name);\n\t\tif (!grouped.has(category)) grouped.set(category, []);\n\t\tgrouped.get(category)!.push(tool);\n\t});\n\tconst order = [\"Execution\", \"Sessions\", \"Memory\", \"Web & Browser\", \"Skills\", \"MCP\", \"Core\"];\n\treturn order\n\t\t.filter((label) => grouped.has(label))\n\t\t.map((label) => ({\n\t\t\tlabel,\n\t\t\ttools: grouped\n\t\t\t\t.get(label)!\n\t\t\t\t.slice()\n\t\t\t\t.sort((left, right) => String(left?.name || \"\").localeCompare(String(right?.name || \"\"))),\n\t\t}));\n}\n\nfunction summarizeRemoteExecInventory(entries: NodeInventoryEntry[]): RemoteExecSummary {\n\tconst summary: RemoteExecSummary = { pairedNodes: 0, sshTargets: 0 };\n\t(entries || []).forEach((entry) => {\n\t\tif (!entry || typeof entry !== \"object\") return;\n\t\tif (entry.platform === \"ssh\") {\n\t\t\tsummary.sshTargets += 1;\n\t\t\treturn;\n\t\t}\n\t\tsummary.pairedNodes += 1;\n\t});\n\treturn summary;\n}\n\nfunction SettingsSidebar(): VNode {\n\treturn (\n\t\t<div className=\"settings-sidebar\">\n\t\t\t<div className=\"settings-sidebar-header\">\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"settings-back-slot\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tnavigate(routes.chats as string);\n\t\t\t\t\t}}\n\t\t\t\t\ttitle=\"Back to chat sessions\"\n\t\t\t\t>\n\t\t\t\t\t<span className=\"icon icon-chat\" />\n\t\t\t\t\tBack to Chats\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<div className=\"settings-sidebar-nav\">\n\t\t\t\t{getVisibleSections().map((s) =>\n\t\t\t\t\ts.group ? (\n\t\t\t\t\t\t<div key={s.group} className=\"settings-group-label\">\n\t\t\t\t\t\t\t{s.group}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t) : (\n\t\t\t\t\t\t<button\n\t\t\t\t\t\t\tkey={s.id}\n\t\t\t\t\t\t\tclassName={`settings-nav-item ${activeSection.value === s.id ? \"active\" : \"\"}`}\n\t\t\t\t\t\t\tdata-section={s.id}\n\t\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\t\tif (isMobileViewport()) {\n\t\t\t\t\t\t\t\t\tmobileSidebarVisible.value = false;\n\t\t\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\tnavigate(settingsPath(s.id!));\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t{s.label}\n\t\t\t\t\t\t</button>\n\t\t\t\t\t),\n\t\t\t\t)}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// EmojiPicker imported from emoji-picker.ts\n\n// ── Soul defaults ────────────────────────────────────────────\n\nconst DEFAULT_SOUL =\n\t\"Be genuinely helpful, not performatively helpful. Skip the filler words \\u2014 just help.\\n\" +\n\t\"Have opinions. You're allowed to disagree, prefer things, find stuff amusing or boring.\\n\" +\n\t\"Be resourceful before asking. Try to figure it out first \\u2014 read the context, search for it \\u2014 then ask if you're stuck.\\n\" +\n\t\"Earn trust through competence. Be careful with external actions. Be bold with internal ones.\\n\" +\n\t\"Remember you're a guest. You have access to someone's life. Treat it with respect.\\n\" +\n\t\"Private things stay private. When in doubt, ask before acting externally.\\n\" +\n\t\"Be concise when needed, thorough when it matters. Not a corporate drone. Not a sycophant. Just good.\";\n\n// ── Identity section (editable form) ─────────────────────────\n\nfunction IdentitySection(): VNode {\n\tconst id = identity.value;\n\tconst isNew = !(id && (id.name || id.user_name));\n\tconst storedLocale = localStorage.getItem(\"moltis-locale\");\n\n\tconst [name, setName] = useState(id?.name || \"\");\n\tconst [emoji, setEmoji] = useState(id?.emoji || \"\");\n\tconst [theme, setTheme] = useState(id?.theme || \"\");\n\tconst [userName, setUserName] = useState(id?.user_name || \"\");\n\tconst [soul, setSoul] = useState(id?.soul || \"\");\n\tconst [uiLanguage, setUiLanguage] = useState(storedLocale || \"auto\");\n\tconst [saving, setSaving] = useState(false);\n\tconst [emojiSaving, setEmojiSaving] = useState(false);\n\tconst [nameSaving, setNameSaving] = useState(false);\n\tconst [userNameSaving, setUserNameSaving] = useState(false);\n\tconst [languageSaving, setLanguageSaving] = useState(false);\n\tconst [saved, setSaved] = useState(false);\n\tconst [languageSaved, setLanguageSaved] = useState(false);\n\tconst [showFaviconReloadHint, setShowFaviconReloadHint] = useState(false);\n\tconst [error, setError] = useState<string | null>(null);\n\tconst [languageError, setLanguageError] = useState<string | null>(null);\n\n\t// Sync state when identity loads asynchronously\n\tuseEffect(() => {\n\t\tif (!id) return;\n\t\tsetName(id.name || \"\");\n\t\tsetEmoji(id.emoji || \"\");\n\t\tsetTheme(id.theme || \"\");\n\t\tsetUserName(id.user_name || \"\");\n\t\tsetSoul(id.soul || \"\");\n\t}, [id]);\n\n\tconst savedTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);\n\tfunction flashSaved(): void {\n\t\tif (savedTimerRef.current) clearTimeout(savedTimerRef.current);\n\t\tsetSaved(true);\n\t\tsavedTimerRef.current = setTimeout(() => {\n\t\t\tsavedTimerRef.current = null;\n\t\t\tsetSaved(false);\n\t\t\trerender();\n\t\t}, 2000);\n\t}\n\n\tif (loading.value) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Loading{\"\\u2026\"}</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\tfunction onSave(e: Event): void {\n\t\te.preventDefault();\n\t\tconst v = validateIdentityFields(name, userName);\n\t\tif (!v.valid) {\n\t\t\tsetError(v.error);\n\t\t\treturn;\n\t\t}\n\t\tsetError(null);\n\t\tsetSaving(true);\n\t\tsetSaved(false);\n\n\t\tupdateIdentity(\n\t\t\t{\n\t\t\t\tname: name.trim(),\n\t\t\t\temoji: emoji.trim() || \"\",\n\t\t\t\ttheme: theme.trim() || \"\",\n\t\t\t\tsoul: soul.trim() || undefined,\n\t\t\t\tuser_name: userName.trim(),\n\t\t\t},\n\t\t\t{ agentId: \"main\" },\n\t\t).then((res: RpcResponse) => {\n\t\t\tsetSaving(false);\n\t\t\tif (res?.ok) {\n\t\t\t\tconst payload = res.payload as IdentityData;\n\t\t\t\tidentity.value = payload;\n\t\t\t\tgon.set(\"identity\", payload as import(\"../types/gon\").ResolvedIdentity);\n\t\t\t\trefreshGon();\n\t\t\t\tconst emojiChanged = (emoji.trim() || \"\") !== (id?.emoji || \"\").trim();\n\t\t\t\tsetShowFaviconReloadHint(emojiChanged && isSafariBrowser());\n\t\t\t\tflashSaved();\n\t\t\t} else {\n\t\t\t\tsetError(res?.error?.message || \"Failed to save\");\n\t\t\t}\n\t\t\trerender();\n\t\t});\n\t}\n\n\tfunction onEmojiSelect(nextEmoji: string): void {\n\t\tsetEmoji(nextEmoji);\n\t\tsetError(null);\n\t\tsetSaved(false);\n\t\tsetEmojiSaving(true);\n\t\tupdateIdentity({ emoji: nextEmoji.trim() || \"\" }, { agentId: \"main\" }).then((res: RpcResponse) => {\n\t\t\tsetEmojiSaving(false);\n\t\t\tif (res?.ok) {\n\t\t\t\tconst payload = res.payload as IdentityData;\n\t\t\t\tidentity.value = payload;\n\t\t\t\tsetEmoji(payload?.emoji || \"\");\n\t\t\t\tgon.set(\"identity\", payload as import(\"../types/gon\").ResolvedIdentity);\n\t\t\t\trefreshGon();\n\t\t\t\tconst emojiChanged = (nextEmoji.trim() || \"\") !== (id?.emoji || \"\").trim();\n\t\t\t\tsetShowFaviconReloadHint(emojiChanged && isSafariBrowser());\n\t\t\t\tflashSaved();\n\t\t\t} else {\n\t\t\t\tsetError(res?.error?.message || \"Failed to save emoji\");\n\t\t\t}\n\t\t\trerender();\n\t\t});\n\t}\n\n\tfunction autoSaveNameField(field: string, value: string): void {\n\t\tif (saving || emojiSaving || nameSaving || userNameSaving) return;\n\t\tconst trimmed = value.trim();\n\t\tconst currentValue = ((identity.value?.[field] as string) || \"\").trim();\n\t\tif (trimmed === currentValue) return;\n\n\t\tif (!trimmed) {\n\t\t\tsetError(field === \"name\" ? \"Agent name is required.\" : \"Your name is required.\");\n\t\t\treturn;\n\t\t}\n\n\t\tsetError(null);\n\t\tsetSaved(false);\n\t\tif (field === \"name\") {\n\t\t\tsetNameSaving(true);\n\t\t} else {\n\t\t\tsetUserNameSaving(true);\n\t\t}\n\n\t\tconst payload: Record<string, string> = {};\n\t\tpayload[field] = trimmed;\n\t\tupdateIdentity(payload, { agentId: \"main\" }).then((res: RpcResponse) => {\n\t\t\tif (field === \"name\") {\n\t\t\t\tsetNameSaving(false);\n\t\t\t} else {\n\t\t\t\tsetUserNameSaving(false);\n\t\t\t}\n\n\t\t\tif (res?.ok) {\n\t\t\t\tconst resPayload = res.payload as IdentityData;\n\t\t\t\tidentity.value = resPayload;\n\t\t\t\tgon.set(\"identity\", resPayload as import(\"../types/gon\").ResolvedIdentity);\n\t\t\t\trefreshGon();\n\t\t\t\tsetName(resPayload?.name || \"\");\n\t\t\t\tsetUserName(resPayload?.user_name || \"\");\n\t\t\t\tflashSaved();\n\t\t\t} else {\n\t\t\t\tsetError(res?.error?.message || \"Failed to save\");\n\t\t\t}\n\t\t\trerender();\n\t\t});\n\t}\n\n\tfunction onNameBlur(e: Event): void {\n\t\tautoSaveNameField(\"name\", (e.target as HTMLInputElement).value);\n\t}\n\n\tfunction onUserNameBlur(e: Event): void {\n\t\tautoSaveNameField(\"user_name\", (e.target as HTMLInputElement).value);\n\t}\n\n\tfunction onResetSoul(): void {\n\t\tsetSoul(\"\");\n\t\trerender();\n\t}\n\n\tfunction onReloadForFavicon(): void {\n\t\twindow.location.reload();\n\t}\n\n\tfunction onApplyLanguage(): void {\n\t\tsetLanguageSaving(true);\n\t\tsetLanguageSaved(false);\n\t\tsetLanguageError(null);\n\n\t\tconst nextLanguage = uiLanguage === \"auto\" ? navigator.language || \"en\" : uiLanguage;\n\t\tsetLocale(nextLanguage)\n\t\t\t.then(() => {\n\t\t\t\tif (uiLanguage === \"auto\") {\n\t\t\t\t\tlocalStorage.removeItem(\"moltis-locale\");\n\t\t\t\t}\n\t\t\t\tsetLanguageSaving(false);\n\t\t\t\tsetLanguageSaved(true);\n\t\t\t\tsetTimeout(() => {\n\t\t\t\t\tsetLanguageSaved(false);\n\t\t\t\t\trerender();\n\t\t\t\t}, 2000);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((err: Error) => {\n\t\t\t\tsetLanguageSaving(false);\n\t\t\t\tsetLanguageError(err?.message || \"Failed to update language\");\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Identity</h2>\n\t\t\t{isNew ? (\n\t\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed\" style={{ maxWidth: \"600px\", margin: 0 }}>\n\t\t\t\t\tWelcome! Set up your agent's identity to get started.\n\t\t\t\t</p>\n\t\t\t) : null}\n\t\t\t<form onSubmit={onSave} style={{ maxWidth: \"600px\", display: \"flex\", flexDirection: \"column\", gap: \"16px\" }}>\n\t\t\t\t{/* Agent section */}\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\t\t\tAgent\n\t\t\t\t\t</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>\n\t\t\t\t\t\tSaved to <code>IDENTITY.md</code> in your workspace root.\n\t\t\t\t\t</p>\n\t\t\t\t\t<div style={{ display: \"grid\", gridTemplateColumns: \"1fr 1fr\", gap: \"8px 16px\" }}>\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>\n\t\t\t\t\t\t\t\tName *\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\t\tstyle={{ width: \"100%\" }}\n\t\t\t\t\t\t\t\tvalue={name}\n\t\t\t\t\t\t\t\tonInput={(e: Event) => setName((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\tonBlur={onNameBlur}\n\t\t\t\t\t\t\t\tplaceholder=\"e.g. Rex\"\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>\n\t\t\t\t\t\t\t\tEmoji\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<EmojiPicker value={emoji} onChange={setEmoji} onSelect={onEmojiSelect} />\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div style={{ gridColumn: \"1/-1\" }}>\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>\n\t\t\t\t\t\t\t\tTheme\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\t\tstyle={{ width: \"100%\" }}\n\t\t\t\t\t\t\t\tvalue={theme}\n\t\t\t\t\t\t\t\tonInput={(e: Event) => setTheme((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\tplaceholder=\"e.g. wise owl, chill fox\"\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t\t{showFaviconReloadHint ? (\n\t\t\t\t\t\t<div className=\"mt-3 rounded border border-[var(--border)] bg-[var(--surface2)] p-2 text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\tfavicon updates requires reload and may be cached for minutes,{\" \"}\n\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\t\tclassName=\"cursor-pointer bg-transparent p-0 text-xs text-[var(--text)] underline\"\n\t\t\t\t\t\t\t\tonClick={onReloadForFavicon}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\trequires reload\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t.\n\t\t\t\t\t\t</div>\n\t\t\t\t\t) : null}\n\t\t\t\t</div>\n\n\t\t\t\t{/* User section */}\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\t\t\tUser\n\t\t\t\t\t</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>\n\t\t\t\t\t\tSaved to your user profile. Depending on memory settings, Moltis may also mirror it to <code>USER.md</code>.\n\t\t\t\t\t</p>\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>\n\t\t\t\t\t\t\tYour name *\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\tstyle={{ width: \"100%\", maxWidth: \"280px\" }}\n\t\t\t\t\t\t\tvalue={userName}\n\t\t\t\t\t\t\tonInput={(e: Event) => setUserName((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\tonBlur={onUserNameBlur}\n\t\t\t\t\t\t\tplaceholder=\"e.g. Alice\"\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\n\t\t\t\t{/* Language section */}\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\t\t\tLanguage\n\t\t\t\t\t</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>\n\t\t\t\t\t\tChoose the UI language for this browser.\n\t\t\t\t\t</p>\n\t\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\", flexWrap: \"wrap\" }}>\n\t\t\t\t\t\t<label htmlFor=\"identityLanguageSelect\" className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\tUI language\n\t\t\t\t\t\t</label>\n\t\t\t\t\t\t<select\n\t\t\t\t\t\t\tid=\"identityLanguageSelect\"\n\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\tstyle={{ maxWidth: \"220px\" }}\n\t\t\t\t\t\t\tvalue={uiLanguage}\n\t\t\t\t\t\t\tonChange={(e: Event) => {\n\t\t\t\t\t\t\t\tsetUiLanguage((e.target as HTMLSelectElement).value);\n\t\t\t\t\t\t\t\tsetLanguageSaved(false);\n\t\t\t\t\t\t\t\tsetLanguageError(null);\n\t\t\t\t\t\t\t\trerender();\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t<option value=\"auto\">Browser default</option>\n\t\t\t\t\t\t\t<option value=\"en\">English</option>\n\t\t\t\t\t\t\t<option value=\"fr\">French</option>\n\t\t\t\t\t\t\t<option value=\"zh\">{\"\\u7B80\\u4F53\\u4E2D\\u6587\"}</option>\n\t\t\t\t\t\t</select>\n\t\t\t\t\t\t<button\n\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\tid=\"identityLanguageApplyBtn\"\n\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\t\t\tdisabled={languageSaving}\n\t\t\t\t\t\t\tonClick={onApplyLanguage}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t{languageSaving ? \"Applying...\" : \"Apply language\"}\n\t\t\t\t\t\t</button>\n\t\t\t\t\t\t{languageSaved ? (\n\t\t\t\t\t\t\t<span className=\"text-xs\" style={{ color: \"var(--accent)\" }}>\n\t\t\t\t\t\t\t\tLanguage updated\n\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t) : null}\n\t\t\t\t\t\t{languageError ? (\n\t\t\t\t\t\t\t<span className=\"text-xs\" style={{ color: \"var(--error)\" }}>\n\t\t\t\t\t\t\t\t{languageError}\n\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t) : null}\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\n\t\t\t\t{/* Soul section */}\n\t\t\t\t<div>\n\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"4px\" }}>\n\t\t\t\t\t\tSoul\n\t\t\t\t\t</h3>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>\n\t\t\t\t\t\tPersonality and tone injected into every conversation. Saved to <code>SOUL.md</code> in your workspace root.\n\t\t\t\t\t\tLeave empty for the default.\n\t\t\t\t\t</p>\n\t\t\t\t\t<textarea\n\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\trows={8}\n\t\t\t\t\t\tstyle={{ width: \"100%\", minHeight: \"8rem\", resize: \"vertical\", fontSize: \".8rem\", lineHeight: 1.5 }}\n\t\t\t\t\t\tplaceholder={DEFAULT_SOUL}\n\t\t\t\t\t\tvalue={soul}\n\t\t\t\t\t\tonInput={(e: Event) => setSoul((e.target as HTMLTextAreaElement).value)}\n\t\t\t\t\t/>\n\t\t\t\t\t{soul ? (\n\t\t\t\t\t\t<button\n\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\tclassName=\"provider-btn\"\n\t\t\t\t\t\t\tstyle={{ marginTop: \"6px\", fontSize: \".75rem\" }}\n\t\t\t\t\t\t\tonClick={onResetSoul}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\tReset to default\n\t\t\t\t\t\t</button>\n\t\t\t\t\t) : null}\n\t\t\t\t</div>\n\n\t\t\t\t<div style={{ display: \"flex\", alignItems: \"center\", gap: \"8px\" }}>\n\t\t\t\t\t<button\n\t\t\t\t\t\ttype=\"submit\"\n\t\t\t\t\t\tclassName=\"provider-btn\"\n\t\t\t\t\t\tdisabled={saving || emojiSaving || nameSaving || userNameSaving}\n\t\t\t\t\t>\n\t\t\t\t\t\t{saving || emojiSaving || nameSaving || userNameSaving ? \"Saving\\u2026\" : \"Save\"}\n\t\t\t\t\t</button>\n\t\t\t\t\t{saved ? (\n\t\t\t\t\t\t<span className=\"text-xs\" style={{ color: \"var(--accent)\" }}>\n\t\t\t\t\t\t\tSaved\n\t\t\t\t\t\t</span>\n\t\t\t\t\t) : null}\n\t\t\t\t\t{error ? (\n\t\t\t\t\t\t<span className=\"text-xs\" style={{ color: \"var(--error)\" }}>\n\t\t\t\t\t\t\t{error}\n\t\t\t\t\t\t</span>\n\t\t\t\t\t) : null}\n\t\t\t\t</div>\n\t\t\t</form>\n\t\t\t{gon.get(\"version\") ? (\n\t\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ marginTop: \"auto\", paddingTop: \"16px\" }}>\n\t\t\t\t\tv{gon.get(\"version\")}\n\t\t\t\t</p>\n\t\t\t) : null}\n\t\t</div>\n\t);\n}\n\n// ── Environment section ──────────────────────────────────────\n\nfunction EnvironmentSection(): VNode {\n\tconst [envVars, setEnvVars] = useState<EnvVar[]>([]);\n\tconst [envLoading, setEnvLoading] = useState(true);\n\tconst [newKey, setNewKey] = useState(\"\");\n\tconst [newValue, setNewValue] = useState(\"\");\n\tconst [envMsg, setEnvMsg] = useState<string | null>(null);\n\tconst [envErr, setEnvErr] = useState<string | null>(null);\n\tconst [saving, setSaving] = useState(false);\n\tconst [updateId, setUpdateId] = useState<string | null>(null);\n\tconst [updateValue, setUpdateValue] = useState(\"\");\n\n\tfunction fetchEnvVars(): void {\n\t\tfetch(\"/api/env\")\n\t\t\t.then((r) => (r.ok ? r.json() : { env_vars: [] }))\n\t\t\t.then((d: { env_vars?: EnvVar[] }) => {\n\t\t\t\tsetEnvVars(d.env_vars || []);\n\t\t\t\tsetEnvLoading(false);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch(() => {\n\t\t\t\tsetEnvLoading(false);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tuseEffect(() => {\n\t\tfetchEnvVars();\n\t}, []);\n\n\tfunction onAdd(e: Event): void {\n\t\te.preventDefault();\n\t\tsetEnvErr(null);\n\t\tsetEnvMsg(null);\n\t\tconst key = newKey.trim();\n\t\tif (!key) {\n\t\t\tsetEnvErr(\"Key is required.\");\n\t\t\trerender();\n\t\t\treturn;\n\t\t}\n\t\tif (!/^[A-Za-z0-9_]+$/.test(key)) {\n\t\t\tsetEnvErr(\"Key must contain only letters, digits, and underscores.\");\n\t\t\trerender();\n\t\t\treturn;\n\t\t}\n\t\tsetSaving(true);\n\t\trerender();\n\t\tfetch(\"/api/env\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ key, value: newValue }),\n\t\t})\n\t\t\t.then((r) => {\n\t\t\t\tif (r.ok) {\n\t\t\t\t\tsetNewKey(\"\");\n\t\t\t\t\tsetNewValue(\"\");\n\t\t\t\t\tsetEnvMsg(\"Variable saved.\");\n\t\t\t\t\tsetTimeout(() => {\n\t\t\t\t\t\tsetEnvMsg(null);\n\t\t\t\t\t\trerender();\n\t\t\t\t\t}, 2000);\n\t\t\t\t\tfetchEnvVars();\n\t\t\t\t} else {\n\t\t\t\t\treturn r\n\t\t\t\t\t\t.json()\n\t\t\t\t\t\t.then((d: unknown) =>\n\t\t\t\t\t\t\tsetEnvErr(\n\t\t\t\t\t\t\t\tlocalizedApiErrorMessage(d as Parameters<typeof localizedApiErrorMessage>[0], \"Failed to save\"),\n\t\t\t\t\t\t\t),\n\t\t\t\t\t\t);\n\t\t\t\t}\n\t\t\t\tsetSaving(false);\n\t\t\t\trerender();\n\t\t\t})\n\t\t\t.catch((err: Error) => {\n\t\t\t\tsetEnvErr(err.message);\n\t\t\t\tsetSaving(false);\n\t\t\t\trerender();\n\t\t\t});\n\t}\n\n\tfunction onDelete(id: string): void {\n\t\tfetch(`/api/env/${id}`, { method: \"DELETE\" }).then(() => fetchEnvVars());\n\t}\n\n\tfunction onStartUpdate(id: string): void {\n\t\tsetUpdateId(id);\n\t\tsetUpdateValue(\"\");\n\t\trerender();\n\t}\n\n\tfunction onCancelUpdate(): void {\n\t\tsetUpdateId(null);\n\t\tsetUpdateValue(\"\");\n\t\trerender();\n\t}\n\n\tfunction onConfirmUpdate(key: string): void {\n\t\tfetch(\"/api/env\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ key, value: updateValue }),\n\t\t}).then((r) => {\n\t\t\tif (r.ok) {\n\t\t\t\tsetUpdateId(null);\n\t\t\t\tsetUpdateValue(\"\");\n\t\t\t\tfetchEnvVars();\n\t\t\t}\n\t\t});\n\t}\n\n\tconst envVaultStatus = gon.get(\"vault_status\");\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Environment Variables</h2>\n\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed\" style={{ maxWidth: \"600px\", margin: 0 }}>\n\t\t\t\tEnvironment variables are injected into sandbox command execution. Values are write-only and never displayed.\n\t\t\t</p>\n\t\t\t{envVaultStatus && envVaultStatus !== \"disabled\" ? (\n\t\t\t\t<div\n\t\t\t\t\tclassName=\"text-xs\"\n\t\t\t\t\tstyle={{\n\t\t\t\t\t\tmaxWidth: \"600px\",\n\t\t\t\t\t\tpadding: \"8px 12px\",\n\t\t\t\t\t\tborderRadius: \"6px\",\n\t\t\t\t\t\tborder: \"1px solid var(--border)\",\n\t\t\t\t\t\tbackground: \"var(--bg)\",\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{envVaultStatus === \"unsealed\" ? (\n\t\t\t\t\t\t<>\n\t\t\t\t\t\t\t<span style={{ color: \"var(--accent)\" }}>Vault unlocked.</span> Your keys are stored encrypted.\n\t\t\t\t\t\t</>\n\t\t\t\t\t) : envVaultStatus === \"sealed\" ? (\n\t\t\t\t\t\t<>\n\t\t\t\t\t\t\t<span style={{ color: \"var(--warning,var(--error))\" }}>Vault locked.</span> Encrypted keys can{\"\\u2019\"}t\n\t\t\t\t\t\t\tbe read {\"\\u2014\"} sandbox commands won{\"\\u2019\"}t work.{\" \"}\n\t\t\t\t\t\t\t<a href=\"/settings/vault\" style={{ color: \"inherit\", textDecoration: \"underline\" }}>\n\t\t\t\t\t\t\t\tUnlock in Encryption settings.\n\t\t\t\t\t\t\t</a>\n\t\t\t\t\t\t</>\n\t\t\t\t\t) : (\n\t\t\t\t\t\t<>\n\t\t\t\t\t\t\t<span className=\"text-[var(--muted)]\">Vault not set up.</span>{\" \"}\n\t\t\t\t\t\t\t<a href=\"/settings/security\" style={{ color: \"inherit\", textDecoration: \"underline\" }}>\n\t\t\t\t\t\t\t\tSet a password\n\t\t\t\t\t\t\t</a>{\" \"}\n\t\t\t\t\t\t\tto encrypt your stored keys.\n\t\t\t\t\t\t</>\n\t\t\t\t\t)}\n\t\t\t\t</div>\n\t\t\t) : null}\n\n\t\t\t{envLoading ? (\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Loading{\"\\u2026\"}</div>\n\t\t\t) : (\n\t\t\t\t<>\n\t\t\t\t\t{/* Existing variables */}\n\t\t\t\t\t<div style={{ maxWidth: \"600px\" }}>\n\t\t\t\t\t\t{envVars.length > 0 ? (\n\t\t\t\t\t\t\t<div style={{ display: \"flex\", flexDirection: \"column\", gap: \"6px\", marginBottom: \"12px\" }}>\n\t\t\t\t\t\t\t\t{envVars.map((v) => (\n\t\t\t\t\t\t\t\t\t<div className=\"provider-item\" style={{ marginBottom: 0 }} key={v.id}>\n\t\t\t\t\t\t\t\t\t\t{updateId === v.id ? (\n\t\t\t\t\t\t\t\t\t\t\t<form\n\t\t\t\t\t\t\t\t\t\t\t\tstyle={{ display: \"flex\", alignItems: \"center\", gap: \"6px\", flex: 1 }}\n\t\t\t\t\t\t\t\t\t\t\t\tonSubmit={(e: Event) => {\n\t\t\t\t\t\t\t\t\t\t\t\t\te.preventDefault();\n\t\t\t\t\t\t\t\t\t\t\t\t\tonConfirmUpdate(v.key);\n\t\t\t\t\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t\t\t\t<code style={{ fontSize: \"0.8rem\", fontFamily: \"var(--font-mono)\" }}>{v.key}</code>\n\t\t\t\t\t\t\t\t\t\t\t\t{v.encrypted ? (\n\t\t\t\t\t\t\t\t\t\t\t\t\t<span className=\"provider-item-badge configured\">Encrypted</span>\n\t\t\t\t\t\t\t\t\t\t\t\t) : (\n\t\t\t\t\t\t\t\t\t\t\t\t\t<span className=\"provider-item-badge muted\">Plaintext</span>\n\t\t\t\t\t\t\t\t\t\t\t\t)}\n\t\t\t\t\t\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\t\t\t\t\t\ttype=\"password\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tname=\"env_update_value\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tautoComplete=\"new-password\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tautoCapitalize=\"off\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tspellcheck={false}\n\t\t\t\t\t\t\t\t\t\t\t\t\tvalue={updateValue}\n\t\t\t\t\t\t\t\t\t\t\t\t\tonInput={(e: Event) => setUpdateValue((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\t\t\t\t\t\tplaceholder=\"New value\"\n\t\t\t\t\t\t\t\t\t\t\t\t\tstyle={{ flex: 1 }}\n\t\t\t\t\t\t\t\t\t\t\t\t\tautoFocus\n\t\t\t\t\t\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t\t\t\t\t\t<button type=\"submit\" className=\"provider-btn\">\n\t\t\t\t\t\t\t\t\t\t\t\t\tSave\n\t\t\t\t\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t\t\t\t\t\t<button type=\"button\" className=\"provider-btn\" onClick={onCancelUpdate}>\n\t\t\t\t\t\t\t\t\t\t\t\t\tCancel\n\t\t\t\t\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t\t\t\t\t</form>\n\t\t\t\t\t\t\t\t\t\t) : (\n\t\t\t\t\t\t\t\t\t\t\t<>\n\t\t\t\t\t\t\t\t\t\t\t\t<div style={{ flex: 1, minWidth: 0 }}>\n\t\t\t\t\t\t\t\t\t\t\t\t\t<div\n\t\t\t\t\t\t\t\t\t\t\t\t\t\tclassName=\"provider-item-name\"\n\t\t\t\t\t\t\t\t\t\t\t\t\t\tstyle={{ fontFamily: \"var(--font-mono)\", fontSize: \".8rem\" }}\n\t\t\t\t\t\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t{v.key}\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t{v.encrypted ? (\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t<span className=\"provider-item-badge configured\" style={{ marginLeft: \"6px\" }}>\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tEncrypted\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t) : (\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t<span className=\"provider-item-badge muted\" style={{ marginLeft: \"6px\" }}>\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tPlaintext\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t)}\n\t\t\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t\t\t<div\n\t\t\t\t\t\t\t\t\t\t\t\t\t\tstyle={{\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tfontSize: \".7rem\",\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tcolor: \"var(--muted)\",\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tmarginTop: \"2px\",\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tdisplay: \"flex\",\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tgap: \"12px\",\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t<span>{\"\\u2022\\u2022\\u2022\\u2022\\u2022\\u2022\\u2022\\u2022\"}</span>\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t<time dateTime={v.updated_at}>{v.updated_at}</time>\n\t\t\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t\t<div style={{ display: \"flex\", gap: \"4px\" }}>\n\t\t\t\t\t\t\t\t\t\t\t\t\t<button className=\"provider-btn provider-btn-sm\" onClick={() => onStartUpdate(v.id)}>\n\t\t\t\t\t\t\t\t\t\t\t\t\t\tUpdate\n\t\t\t\t\t\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-sm provider-btn-danger\"\n\t\t\t\t\t\t\t\t\t\t\t\t\t\tonClick={() => onDelete(v.id)}\n\t\t\t\t\t\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t\t\t\t\t\tDelete\n\t\t\t\t\t\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t\t\t</>\n\t\t\t\t\t\t\t\t\t\t)}\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t))}\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t) : (\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ padding: \"12px 0\" }}>\n\t\t\t\t\t\t\t\tNo environment variables set.\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t)}\n\t\t\t\t\t</div>\n\n\t\t\t\t\t{/* Add variable */}\n\t\t\t\t\t<div style={{ maxWidth: \"600px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\t\t\t\tAdd Variable\n\t\t\t\t\t\t</h3>\n\t\t\t\t\t\t<form onSubmit={onAdd}>\n\t\t\t\t\t\t\t<div style={{ display: \"flex\", gap: \"8px\", flexWrap: \"wrap\" }}>\n\t\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\t\t\tname=\"env_key\"\n\t\t\t\t\t\t\t\t\tautoComplete=\"off\"\n\t\t\t\t\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\t\t\t\t\tautoCapitalize=\"off\"\n\t\t\t\t\t\t\t\t\tspellcheck={false}\n\t\t\t\t\t\t\t\t\tvalue={newKey}\n\t\t\t\t\t\t\t\t\tonInput={(e: Event) => setNewKey((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\t\tplaceholder=\"KEY_NAME\"\n\t\t\t\t\t\t\t\t\tstyle={{ flex: 1, minWidth: \"120px\", fontFamily: \"var(--font-mono)\", fontSize: \".8rem\" }}\n\t\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\t\ttype=\"password\"\n\t\t\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\t\t\tname=\"env_value\"\n\t\t\t\t\t\t\t\t\tautoComplete=\"new-password\"\n\t\t\t\t\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\t\t\t\t\tautoCapitalize=\"off\"\n\t\t\t\t\t\t\t\t\tspellcheck={false}\n\t\t\t\t\t\t\t\t\tvalue={newValue}\n\t\t\t\t\t\t\t\t\tonInput={(e: Event) => setNewValue((e.target as HTMLInputElement).value)}\n\t\t\t\t\t\t\t\t\tplaceholder=\"Value\"\n\t\t\t\t\t\t\t\t\tstyle={{ flex: 2, minWidth: \"200px\" }}\