enuIdx = 0;\n\n\tif (!slashMenuEl) {\n\t\tslashMenuEl = document.createElement(\"div\");\n\t\tslashMenuEl.className = \"slash-menu\";\n\t}\n\twhile (slashMenuEl.firstChild) slashMenuEl.removeChild(slashMenuEl.firstChild);\n\tmatches.forEach((cmd, i) => {\n\t\tconst item = document.createElement(\"div\");\n\t\titem.className = `slash-menu-item${i === 0 ? \" active\" : \"\"}`;\n\t\tconst nameSpan = document.createElement(\"span\");\n\t\tnameSpan.className = \"slash-name\";\n\t\tnameSpan.textContent = `/${cmd.name}`;\n\t\tconst descSpan = document.createElement(\"span\");\n\t\tdescSpan.className = \"slash-desc\";\n\t\tdescSpan.textContent = cmd.description;\n\t\titem.appendChild(nameSpan);\n\t\titem.appendChild(descSpan);\n\t\titem.addEventListener(\"mousedown\", (e: MouseEvent) => {\n\t\t\te.preventDefault();\n\t\t\tslashSelectItem(i);\n\t\t});\n\t\tslashMenuEl!.appendChild(item);\n\t});\n\n\tconst inputWrap = S.chatInput?.parentElement;\n\tif (inputWrap && !slashMenuEl.parentElement) {\n\t\tinputWrap.classList.add(\"relative\");\n\t\tinputWrap.appendChild(slashMenuEl);\n\t}\n}\n\nfunction slashHideMenu(): void {\n\tif (slashMenuEl?.parentElement) {\n\t\tslashMenuEl.parentElement.removeChild(slashMenuEl);\n\t}\n\tslashMenuItems = [];\n\tslashMenuIdx = 0;\n}\n\nfunction slashSelectItem(idx: number): void {\n\tif (!slashMenuItems[idx]) return;\n\t(S.chatInput as HTMLTextAreaElement).value = `/${slashMenuItems[idx].name}`;\n\tslashHideMenu();\n\tsendChat();\n}\n\nfunction slashHandleInput(): void {\n\tconst val = (S.chatInput as HTMLTextAreaElement).value;\n\tif (val.indexOf(\"/\") === 0 && val.indexOf(\" \") === -1) {\n\t\tslashShowMenu(val);\n\t} else {\n\t\tslashHideMenu();\n\t}\n}\n\nfunction slashHandleKeydown(e: KeyboardEvent): boolean {\n\tif (!slashMenuEl?.parentElement || slashMenuItems.length === 0) return false;\n\tif (e.key === \"ArrowUp\") {\n\t\te.preventDefault();\n\t\tslashMenuIdx = (slashMenuIdx - 1 + slashMenuItems.length) % slashMenuItems.length;\n\t\tslashUpdateActive();\n\t\treturn true;\n\t}\n\tif (e.key === \"ArrowDown\") {\n\t\te.preventDefault();\n\t\tslashMenuIdx = (slashMenuIdx + 1) % slashMenuItems.length;\n\t\tslashUpdateActive();\n\t\treturn true;\n\t}\n\tif (e.key === \"Enter\" || e.key === \"Tab\") {\n\t\te.preventDefault();\n\t\tslashSelectItem(slashMenuIdx);\n\t\treturn true;\n\t}\n\tif (e.key === \"Escape\") {\n\t\te.preventDefault();\n\t\tslashHideMenu();\n\t\treturn true;\n\t}\n\treturn false;\n}\n\nfunction slashUpdateActive(): void {\n\tif (!slashMenuEl) return;\n\tconst items = slashMenuEl.querySelectorAll(\".slash-menu-item\");\n\titems.forEach((el, i) => {\n\t\tel.classList.toggle(\"active\", i === slashMenuIdx);\n\t});\n}\n\nfunction parseSlashCommand(text: string): ParsedSlash | null {\n\tif (!text || text.charAt(0) !== \"/\") return null;\n\tconst body = text.substring(1).trim();\n\tif (!body) return null;\n\tconst spaceIdx = body.indexOf(\" \");\n\tif (spaceIdx === -1) return { name: body.toLowerCase(), args: \"\" };\n\treturn {\n\t\tname: body.substring(0, spaceIdx).toLowerCase(),\n\t\targs: body.substring(spaceIdx + 1).trim(),\n\t};\n}\n\nfunction isShLocalToggle(args: string): boolean {\n\tif (!args) return true;\n\tconst normalized = args.toLowerCase();\n\treturn normalized === \"on\" || normalized === \"off\" || normalized === \"exit\";\n}\n\nfunction shouldHandleSlashLocally(cmdName: string, args: string): boolean {\n\tif (cmdName === \"sh\") return isShLocalToggle(args);\n\treturn slashCommands.some((c) => c.name === cmdName);\n}\n\nfunction commandModeSummary(): string {\n\tconst execModeLabel = S.sessionExecMode === \"sandbox\" ? \"sandboxed\" : \"host\";\n\tconst promptSymbol = S.sessionExecPromptSymbol || \"$\";\n\treturn `${execModeLabel}, prompt ${promptSymbol}`;\n}\n\nfunction setCommandMode(enabled: boolean): void {\n\tS.setCommandModeEnabled(!!enabled);\n\tupdateCommandInputUI();\n}\n\n// ── Context card helpers ─────────────────────────────────\nfunction ctxEl(tag: string, cls: string, text?: string): HTMLElement {\n\tconst el = document.createElement(tag);\n\tif (cls) el.className = cls;\n\tif (text !== undefined) el.textContent = text;\n\treturn el;\n}\n\nfunction ctxRow(label: string, value: string, mono?: boolean): HTMLElement {\n\tconst row = ctxEl(\"div\", \"ctx-row\");\n\trow.appendChild(ctxEl(\"span\", \"ctx-label\", label));\n\trow.appendChild(ctxEl(\"span\", `ctx-value${mono ? \" mono\" : \"\"}`, value));\n\treturn row;\n}\n\nfunction ctxSection(title: string): HTMLElement {\n\tconst sec = ctxEl(\"div\", \"ctx-section\");\n\tsec.appendChild(ctxEl(\"div\", \"ctx-section-title\", title));\n\treturn sec;\n}\n\nfunction formatPromptMemoryMode(mode: string | undefined): string {\n\tif (mode === \"frozen-at-session-start\") return \"Frozen at session start\";\n\tif (mode === \"live-reload\") return \"Live reload\";\n\treturn mode || \"unknown\";\n}\n\nfunction formatPromptMemorySource(source: string | undefined): string {\n\tif (source === \"agent_workspace\") return \"Agent workspace\";\n\tif (source === \"root_workspace\") return \"Root workspace\";\n\treturn source || \"unknown\";\n}\n\nfunction buildPromptMemorySummary(promptMemory: PromptMemoryData | null): string {\n\tif (!promptMemory) return \"Unavailable\";\n\tconst parts: string[] = [formatPromptMemoryMode(promptMemory.mode)];\n\tif (promptMemory.snapshotActive) parts.push(\"snapshot active\");\n\tparts.push(promptMemory.present ? `${Number(promptMemory.chars || 0).toLocaleString()} chars` : \"empty\");\n\treturn parts.join(\" \\u00b7 \");\n}\n\nfunction promptMemoryDetailParts(promptMemory: PromptMemoryData | null): string[] {\n\tif (!promptMemory) return [];\n\tconst parts: string[] = [];\n\tif (promptMemory.fileSource) parts.push(`source ${formatPromptMemorySource(promptMemory.fileSource)}`);\n\tif (promptMemory.path) parts.push(promptMemory.path);\n\treturn parts;\n}\n\nfunction promptMemoryToolbarTitle(promptMemory: PromptMemoryData | null): string {\n\tif (!promptMemory) return \"Prompt memory unavailable\";\n\tconst parts = [`Prompt memory: ${buildPromptMemorySummary(promptMemory)}`];\n\tconst dp = promptMemoryDetailParts(promptMemory);\n\tif (dp.length > 0) parts.push(dp.join(\" \\u00b7 \"));\n\treturn parts.join(\"\\n\");\n}\n\nfunction promptMemoryToolbarLabel(promptMemory: PromptMemoryData | null): string {\n\tif (!promptMemory) return \"Memory\";\n\tif (promptMemory.mode === \"frozen-at-session-start\") return \"Memory frozen\";\n\tif (promptMemory.mode === \"live-reload\") return \"Memory live\";\n\treturn \"Memory\";\n}\n\nfunction setPromptMemoryToolbarState(pm: PromptMemoryData | null, loading: boolean, refreshing: boolean): void {\n\tconst toolbar = S.$(\"promptMemoryToolbar\") as HTMLElement | null;\n\tconst statusBtn = S.$(\"promptMemoryStatusBtn\") as HTMLButtonElement | null;\n\tconst statusLabel = S.$(\"promptMemoryStatusLabel\") as HTMLElement | null;\n\tconst refreshBtn = S.$(\"promptMemoryRefreshBtn\") as HTMLButtonElement | null;\n\tif (!(toolbar && statusBtn && statusLabel && refreshBtn)) return;\n\ttoolbar.classList.remove(\"hidden\");\n\ttoolbar.classList.add(\"inline-flex\");\n\tstatusBtn.disabled = !!loading;\n\trefreshBtn.disabled = !!refreshing;\n\tif (loading) {\n\t\tstatusLabel.textContent = \"Memory\\u2026\";\n\t\tstatusBtn.title = \"Loading prompt memory status\";\n\t\trefreshBtn.classList.add(\"hidden\");\n\t\treturn;\n\t}\n\tstatusLabel.textContent = promptMemoryToolbarLabel(pm);\n\tstatusBtn.title = promptMemoryToolbarTitle(pm);\n\trefreshBtn.classList.toggle(\"hidden\", pm?.mode !== \"frozen-at-session-start\");\n\trefreshBtn.title = pm?.mode === \"frozen-at-session-start\" ? \"Refresh frozen prompt memory\" : \"Refresh unavailable\";\n}\n\nfunction refreshPromptMemoryToolbarFromPayload(pm: PromptMemoryData | null): void {\n\tsetPromptMemoryToolbarState(pm || null, false, false);\n}\n\nfunction refreshPromptMemoryToolbar(): Promise<PromptMemoryData | null> {\n\tif (!S.connected) {\n\t\tsetPromptMemoryToolbarState(null, false, false);\n\t\treturn Promise.resolve(null);\n\t}\n\tconst requestId = ++promptMemoryToolbarRequestId;\n\tsetPromptMemoryToolbarState(null, true, false);\n\treturn sendRpc(\"chat.context\", {}).then((res: any) => {\n\t\tif (requestId !== promptMemoryToolbarRequestId) return null;\n\t\tif (res?.ok && res.payload) {\n\t\t\tconst pm = res.payload.promptMemory || null;\n\t\t\trefreshPromptMemoryToolbarFromPayload(pm);\n\t\t\treturn pm;\n\t\t}\n\t\tsetPromptMemoryToolbarState(null, false, false);\n\t\treturn null;\n\t});\n}\n\nfunction refreshPromptMemoryToolbarSnapshot(): Promise<PromptMemoryData | null> {\n\tsetPromptMemoryToolbarState(null, false, true);\n\treturn sendRpc(\"chat.prompt_memory.refresh\", {})\n\t\t.then((res: any) => {\n\t\t\tif (!(res?.ok && res.payload)) throw new Error(res?.error?.message || \"Failed to refresh prompt memory\");\n\t\t\tconst pm = res.payload.promptMemory || null;\n\t\t\trefreshPromptMemoryToolbarFromPayload(pm);\n\t\t\tmaybeRefreshFullContext();\n\t\t\treturn pm;\n\t\t})\n\t\t.catch((error: any) => {\n\t\t\trefreshPromptMemoryToolbar();\n\t\t\tchatAddMsg(\"error\", error?.message || \"Failed to refresh prompt memory\");\n\t\t\treturn null;\n\t\t});\n}\n\n// ── Context card section renderers ───────────────────────\nfunction renderContextSessionSection(card: HTMLElement, data: ContextData): void {\n\tconst sess: any = data.session || {};\n\tconst sec = ctxSection(\"Session\");\n\tsec.appendChild(ctxRow(\"Key\", sess.key || \"unknown\", true));\n\tsec.appendChild(ctxRow(\"Messages\", String(sess.messageCount || 0)));\n\tsec.appendChild(ctxRow(\"Model\", sess.model || \"default\", true));\n\tif (sess.provider) sec.appendChild(ctxRow(\"Provider\", sess.provider, true));\n\tif (sess.label) sec.appendChild(ctxRow(\"Label\", sess.label));\n\tsec.appendChild(ctxRow(\"Tool Support\", data.supportsTools === false ? \"Disabled\" : \"Enabled\"));\n\tcard.appendChild(sec);\n}\n\nfunction renderContextProjectSection(card: HTMLElement, data: ContextData): void {\n\tconst proj: any = data.project;\n\tconst sec = ctxSection(\"Project\");\n\tif (proj) {\n\t\tsec.appendChild(ctxRow(\"Name\", proj.label || \"(unnamed)\"));\n\t\tif (proj.directory) sec.appendChild(ctxRow(\"Directory\", proj.directory, true));\n\t\tif (proj.systemPrompt) sec.appendChild(ctxRow(\"System Prompt\", `${proj.systemPrompt.length} chars`));\n\t\tconst ctxFiles: any[] = proj.contextFiles || [];\n\t\tif (ctxFiles.length > 0) {\n\t\t\tconst fl = ctxEl(\"div\", \"ctx-section-title\", `Context Files (${ctxFiles.length})`);\n\t\t\tfl.classList.add(\"spaced\");\n\t\t\tsec.appendChild(fl);\n\t\t\tctxFiles.forEach((f: any) => {\n\t\t\t\tconst row = ctxEl(\"div\", \"ctx-file\");\n\t\t\t\trow.appendChild(ctxEl(\"span\", \"ctx-file-path\", f.path));\n\t\t\t\trow.appendChild(ctxEl(\"span\", \"ctx-file-size\", formatBytes(f.size)));\n\t\t\t\tsec.appendChild(row);\n\t\t\t});\n\t\t}\n\t} else {\n\t\tsec.appendChild(ctxEl(\"div\", \"ctx-empty\", \"No project bound to this session\"));\n\t}\n\tcard.appendChild(sec);\n}\n\nfunction renderContextToolsSection(card: HTMLElement, data: ContextData): void {\n\tconst tools = data.tools || [];\n\tconst sec = ctxSection(\"Tools\");\n\tif (data.supportsTools === false) {\n\t\tsec.appendChild(ctxEl(\"div\", \"ctx-disabled\", \"Tools disabled \\u2014 model doesn't support tool calling\"));\n\t} else if (tools.length > 0) {\n\t\tconst wrap = ctxEl(\"div\", \"ctx-tool-wrap\");\n\t\ttools.forEach((t) => {\n\t\t\tconst tag = ctxEl(\"span\", \"ctx-tag\");\n\t\t\ttag.appendChild(ctxEl(\"span\", \"ctx-tag-dot\"));\n\t\t\ttag.appendChild(document.createTextNode(t.name));\n\t\t\ttag.title = t.description || \"\";\n\t\t\twrap.appendChild(tag);\n\t\t});\n\t\tsec.appendChild(wrap);\n\t} else {\n\t\tsec.appendChild(ctxEl(\"div\", \"ctx-empty\", \"No tools registered\"));\n\t}\n\tcard.appendChild(sec);\n}\n\nfunction renderContextSkillsSection(card: HTMLElement, data: ContextData): void {\n\tconst skills = data.skills || [];\n\tconst sec = ctxSection(\"Skills & Plugins\");\n\tif (data.supportsTools === false) {\n\t\tsec.appendChild(ctxEl(\"div\", \"ctx-disabled\", \"Skills disabled \\u2014 model doesn't support tool calling\"));\n\t} else if (skills.length > 0) {\n\t\tconst wrap = ctxEl(\"div\", \"ctx-tool-wrap\");\n\t\tskills.forEach((s) => {\n\t\t\tconst tag = ctxEl(\"span\", \"ctx-tag\");\n\t\t\tconst dot = ctxEl(\"span\", \"ctx-tag-dot\");\n\t\t\tconst isPlugin = s.source === \"plugin\";\n\t\t\t(dot as HTMLElement).style.background = isPlugin ? \"var(--accent)\" : \"var(--success, #4a9)\";\n\t\t\ttag.appendChild(dot);\n\t\t\ttag.appendChild(document.createTextNode(s.name));\n\t\t\ttag.title = (isPlugin ? \"[Plugin] \" : \"[Skill] \") + (s.description || \"\");\n\t\t\twrap.appendChild(tag);\n\t\t});\n\t\tsec.appendChild(wrap);\n\t} else {\n\t\tsec.appendChild(ctxEl(\"div\", \"ctx-empty\", \"No skills or plugins enabled\"));\n\t}\n\tcard.appendChild(sec);\n}\n\nfunction renderContextMcpSection(card: HTMLElement, data: ContextData): void {\n\tconst servers = data.mcpServers || [];\n\tconst sec = ctxSection(\"MCP Tools\");\n\tif (data.supportsTools === false) {\n\t\tsec.appendChild(ctxEl(\"div\", \"ctx-disabled\", \"MCP tools disabled \\u2014 model doesn't support tool calling\"));\n\t} else if (data.mcpDisabled) {\n\t\tsec.appendChild(ctxEl(\"div\", \"ctx-disabled\", \"MCP tools disabled for this session\"));\n\t} else {\n\t\tconst running = servers.filter((s) => s.state === \"running\");\n\t\tif (running.length > 0) {\n\t\t\tconst wrap = ctxEl(\"div\", \"ctx-tool-wrap\");\n\t\t\trunning.forEach((s) => {\n\t\t\t\tconst tag = ctxEl(\"span\", \"ctx-tag\");\n\t\t\t\tconst dot = ctxEl(\"span\", \"ctx-tag-dot\");\n\t\t\t\t(dot as HTMLElement).style.background = \"var(--ok)\";\n\t\t\t\ttag.appendChild(dot);\n\t\t\t\ttag.appendChild(document.createTextNode(s.name));\n\t\t\t\ttag.title = `${s.tool_count} tool${s.tool_count !== 1 ? \"s\" : \"\"} \\u2014 ${s.state}`;\n\t\t\t\twrap.appendChild(tag);\n\t\t\t});\n\t\t\tsec.appendChild(wrap);\n\t\t} else {\n\t\t\tsec.appendChild(ctxEl(\"div\", \"ctx-empty\", \"No MCP tools running\"));\n\t\t}\n\t}\n\tcard.appendChild(sec);\n}\n\nfunction renderContextSandboxSection(card: HTMLElement, data: ContextData): void {\n\tconst sb: any = data.sandbox || {};\n\tconst exec: any = data.execution || {};\n\tconst sec = ctxSection(\"Sandbox\");\n\tsec.appendChild(ctxRow(\"Enabled\", sb.enabled ? \"yes\" : \"no\", true));\n\tlet execLabel = exec.mode ? (exec.mode === \"sandbox\" ? \"sandboxed\" : \"host\") : \"\";\n\tif (execLabel && exec.promptSymbol) execLabel += ` (${exec.promptSymbol})`;\n\tif (execLabel) sec.appendChild(ctxRow(\"Command route\", execLabel, true));\n\tfor (const [label, value, mono] of [\n\t\t[\"Backend\", sb.backend, false],\n\t\t[\"Mode\", sb.mode, false],\n\t\t[\"Scope\", sb.scope, false],\n\t\t[\"Workspace Mount\", sb.workspaceMount, false],\n\t\t[\"Image\", sb.image, true],\n\t\t[\"Container\", sb.containerName, false],\n\t] as [string, string, boolean][]) {\n\t\tif (value) sec.appendChild(ctxRow(label, value, mono));\n\t}\n\tcard.appendChild(sec);\n}\n\nfunction renderContextTokensSection(card: HTMLElement, data: ContextData): void {\n\tconst tu: any = data.tokenUsage || {};\n\tconst sessionInput = tu.inputTokens || 0;\n\tconst sessionOutput = tu.outputTokens || 0;\n\tconst sessionCacheRead = tu.cacheReadTokens || 0;\n\tconst sessionCacheWrite = tu.cacheWriteTokens || 0;\n\tconst sessionTotal = tu.total || 0;\n\tconst currentInput = tu.currentInputTokens || sessionInput;\n\tconst currentOutput = tu.currentOutputTokens || 0;\n\tconst currentCacheRead = tu.currentCacheReadTokens || 0;\n\tconst currentCacheWrite = tu.currentCacheWriteTokens || 0;\n\tconst currentTotal = tu.currentTotal || currentInput + currentOutput;\n\tconst estimatedNextInput = tu.estimatedNextInputTokens || currentInput;\n\tconst sec = ctxSection(\"Token Usage\");\n\tsec.appendChild(ctxRow(\"Session input\", formatTokens(sessionInput), true));\n\tsec.appendChild(ctxRow(\"Session output\", formatTokens(sessionOutput), true));\n\tif (sessionCacheRead > 0) sec.appendChild(ctxRow(\"Session cached input\", formatTokens(sessionCacheRead), true));\n\tif (sessionCacheWrite > 0) sec.appendChild(ctxRow(\"Session cache writes\", formatTokens(sessionCacheWrite), true));\n\tsec.appendChild(ctxRow(\"Session total\", formatTokens(sessionTotal), true));\n\tsec.appendChild(ctxRow(\"Current input\", formatTokens(currentInput), true));\n\tsec.appendChild(ctxRow(\"Current output\", formatTokens(currentOutput), true));\n\tif (currentCacheRead > 0) sec.appendChild(ctxRow(\"Current cached input\", formatTokens(currentCacheRead), true));\n\tif (currentCacheWrite > 0) sec.appendChild(ctxRow(\"Current cache writes\", formatTokens(currentCacheWrite), true));\n\tsec.appendChild(ctxRow(\"Current total\", formatTokens(currentTotal), true));\n\tsec.appendChild(ctxRow(\"Estimated next input\", formatTokens(estimatedNextInput), true));\n\tif (tu.contextWindow > 0) {\n\t\tconst pct = Math.max(0, 100 - Math.round((estimatedNextInput / tu.contextWindow) * 100));\n\t\tsec.appendChild(ctxRow(\"Context left\", `${pct}% of ${formatTokens(tu.contextWindow)}`, true));\n\t}\n\tcard.appendChild(sec);\n}\n\nfunction renderContextPromptMemorySection(card: HTMLElement, data: ContextData): void {\n\tconst pm = data.promptMemory || null;\n\tconst sec = ctxSection(\"Prompt Memory\");\n\tsec.appendChild(ctxRow(\"Status\", buildPromptMemorySummary(pm)));\n\tif (pm) {\n\t\tsec.appendChild(ctxRow(\"Mode\", formatPromptMemoryMode(pm.mode)));\n\t\tsec.appendChild(ctxRow(\"Present\", pm.present ? \"yes\" : \"no\"));\n\t\tsec.appendChild(ctxRow(\"Chars\", Number(pm.chars || 0).toLocaleString(), true));\n\t\tif (pm.fileSource) sec.appendChild(ctxRow(\"Source\", formatPromptMemorySource(pm.fileSource)));\n\t\tif (pm.path) sec.appendChild(ctxRow(\"Path\", pm.path, true));\n\t}\n\tcard.appendChild(sec);\n}\n\nfunction renderContextCard(data: ContextData): void {\n\tif (!S.chatMsgBox) return;\n\tslashInjectStyles();\n\tconst card = ctxEl(\"div\", \"ctx-card\");\n\tconst header = ctxEl(\"div\", \"ctx-header\");\n\tconst icon = document.createElement(\"span\");\n\ticon.className = \"icon icon-settings-gear\";\n\theader.appendChild(icon);\n\theader.appendChild(ctxEl(\"span\", \"ctx-header-title\", \"Context\"));\n\tcard.appendChild(header);\n\tif (data.supportsTools === false) {\n\t\tconst warning = ctxEl(\"div\", \"ctx-warning\");\n\t\tconst warnIcon = document.createElement(\"span\");\n\t\twarnIcon.className = \"icon icon-warn-triangle-light\";\n\t\twarning.appendChild(warnIcon);\n\t\twarning.appendChild(\n\t\t\tdocument.createTextNode(\n\t\t\t\t\"Tools disabled \\u2014 the current model doesn't support tool calling. Running in chat-only mode.\",\n\t\t\t),\n\t\t);\n\t\tcard.appendChild(warning);\n\t}\n\trenderContextSessionSection(card, data);\n\trenderContextProjectSection(card, data);\n\trenderContextSkillsSection(card, data);\n\trenderContextMcpSection(card, data);\n\trenderContextToolsSection(card, data);\n\trenderContextSandboxSection(card, data);\n\trenderContextPromptMemorySection(card, data);\n\trenderContextTokensSection(card, data);\n\tS.chatMsgBox.appendChild(card);\n\tS.chatMsgBox.scrollTop = S.chatMsgBox.scrollHeight;\n}\n\nconst COMPACTION_MODE_LABELS: Record<string, string> = {\n\tdeterministic: \"Deterministic\",\n\trecency_preserving: \"Recency preserving\",\n\tstructured: \"Structured\",\n\tllm_replace: \"LLM replace\",\n};\n\nfunction compactionModeLabel(mode: string | undefined): string {\n\tif (!mode) return \"Unknown\";\n\treturn COMPACTION_MODE_LABELS[mode] || mode;\n}\n\nexport function renderCompactCard(data: CompactCardData): void {\n\tif (!S.chatMsgBox) return;\n\tslashInjectStyles();\n\tconst card = ctxEl(\"div\", \"ctx-card\");\n\tconst header = ctxEl(\"div\", \"ctx-header\");\n\tconst icon = document.createElement(\"span\");\n\ticon.className = \"icon icon-compress\";\n\theader.appendChild(icon);\n\theader.appendChild(ctxEl(\"span\", \"ctx-header-title\", \"Conversation compacted\"));\n\tcard.appendChild(header);\n\tif (data.mode) {\n\t\tconst stratSec = ctxSection(\"Strategy\");\n\t\tstratSec.appendChild(ctxRow(\"Mode\", compactionModeLabel(data.mode)));\n\t\tconst totalTokens = Number(data.compactionTotalTokens || 0);\n\t\tif (totalTokens > 0) {\n\t\t\tconst inp = Number(data.compactionInputTokens || 0);\n\t\t\tconst outp = Number(data.compactionOutputTokens || 0);\n\t\t\tstratSec.appendChild(\n\t\t\t\tctxRow(\"Tokens used\", `${formatTokens(totalTokens)} (${formatTokens(inp)} in + ${formatTokens(outp)} out)`),\n\t\t\t);\n\t\t} else {\n\t\t\tstratSec.appendChild(ctxRow(\"Tokens used\", \"0 (no LLM call)\"));\n\t\t}\n\t\tcard.appendChild(stratSec);\n\t}\n\tconst statsSec = ctxSection(\"Before compact\");\n\tstatsSec.appendChild(ctxRow(\"Messages\", String(data.messageCount || 0)));\n\tif (data.totalTokens) statsSec.appendChild(ctxRow(\"Total tokens\", formatTokens(data.totalTokens || 0)));\n\tif (data.estimatedNextInputTokens)\n\t\tstatsSec.appendChild(ctxRow(\"Estimated next input\", formatTokens(data.estimatedNextInputTokens), true));\n\tif (data.contextWindow) {\n\t\tconst basis = data.estimatedNextInputTokens || data.totalTokens || 0;\n\t\tconst pctUsed = Math.round((basis / data.contextWindow) * 100);\n\t\tstatsSec.appendChild(ctxRow(\"Context usage\", `${pctUsed}% of ${formatTokens(data.contextWindow)}`));\n\t}\n\tcard.appendChild(statsSec);\n\tconst afterSec = ctxSection(\"After compact\");\n\tconst replacesAll = data.mode === \"deterministic\" || data.mode === \"llm_replace\" || !data.mode;\n\tif (replacesAll) {\n\t\tafterSec.appendChild(ctxRow(\"Messages\", \"1 (summary)\"));\n\t\tafterSec.appendChild(ctxRow(\"Status\", \"Conversation history replaced with a summary\"));\n\t} else {\n\t\tafterSec.appendChild(ctxRow(\"Status\", \"Head + tail preserved verbatim; middle summarised\"));\n\t}\n\tcard.appendChild(afterSec);\n\tif (data.settingsHint) {\n\t\tconst hintSec = ctxSection(\"Configure\");\n\t\tconst hintRow = ctxEl(\"div\", \"ctx-value\");\n\t\thintRow.textContent = data.settingsHint;\n\t\thintSec.appendChild(hintRow);\n\t\tcard.appendChild(hintSec);\n\t}\n\tS.chatMsgBox.appendChild(card);\n\tS.chatMsgBox.scrollTop = S.chatMsgBox.scrollHeight;\n}\n\n// ── Debug / full context panels ──────────────────────────\nfunction setDebugModalOpen(open: boolean): void {\n\tconst modal = S.$(\"debugModal\") as HTMLElement | null;\n\tif (!modal) return;\n\tmodal.classList.toggle(\"hidden\", !open);\n\tconst btn = S.$(\"debugPanelBtn\") as HTMLElement | null;\n\tif (btn) btn.style.color = open ? \"var(--accent)\" : \"var(--muted)\";\n}\n\nfunction setFullContextModalOpen(open: boolean): void {\n\tconst modal = S.$(\"fullContextModal\") as HTMLElement | null;\n\tif (!modal) return;\n\tmodal.classList.toggle(\"hidden\", !open);\n\tconst btn = S.$(\"fullContextBtn\") as HTMLElement | null;\n\tif (btn) btn.style.color = open ? \"var(--accent)\" : \"var(--muted)\";\n}\n\nfunction refreshDebugPanel(): void {\n\tconst panel = S.$(\"debugPanel\") as HTMLElement | null;\n\tif (!panel) return;\n\tpanel.textContent = \"\";\n\tpanel.appendChild(ctxEl(\"div\", \"text-xs text-[var(--muted)]\", \"Loading context\\u2026\"));\n\tsendRpc(\"chat.context\", {}).then((res: any) => {\n\t\tpanel.textContent = \"\";\n\t\tif (!(res?.ok && res.payload)) {\n\t\t\tpanel.appendChild(ctxEl(\"div\", \"text-xs text-[var(--error)]\", \"Failed to load context\"));\n\t\t\treturn;\n\t\t}\n\t\tslashInjectStyles();\n\t\trenderContextSessionSection(panel, res.payload);\n\t\trenderContextProjectSection(panel, res.payload);\n\t\trenderContextSkillsSection(panel, res.payload);\n\t\trenderContextMcpSection(panel, res.payload);\n\t\trenderContextToolsSection(panel, res.payload);\n\t\trenderContextSandboxSection(panel, res.payload);\n\t\trenderContextPromptMemorySection(panel, res.payload);\n\t\trenderContextTokensSection(panel, res.payload);\n\t\trefreshPromptMemoryToolbarFromPayload(res.payload.promptMemory || null);\n\t});\n}\n\nfunction toggleDebugPanel(): void {\n\tconst modal = S.$(\"debugModal\") as HTMLElement | null;\n\tif (!modal) return;\n\tconst opening = modal.classList.contains(\"hidden\");\n\tif (!opening) {\n\t\tsetDebugModalOpen(false);\n\t\treturn;\n\t}\n\tsetFullContextModalOpen(false);\n\tsetDebugModalOpen(true);\n\trefreshDebugPanel();\n}\n\n// ── Full context panel ───────────────────────────────────\nconst ROLE_COLORS: Record<string, string> = {\n\tsystem: \"var(--accent)\",\n\tuser: \"var(--ok, #22c55e)\",\n\tassistant: \"var(--info, #3b82f6)\",\n\ttool: \"var(--muted)\",\n};\n\nfunction ctxMsgBadge(role: string): HTMLElement {\n\tconst color = ROLE_COLORS[role] || \"var(--text)\";\n\tconst badge = ctxEl(\"span\", \"text-xs font-semibold uppercase px-1.5 py-0.5 rounded\");\n\tbadge.style.cssText = `color:${color};background:color-mix(in srgb, ${color} 15%, transparent)`;\n\tbadge.textContent = role;\n\treturn badge;\n}\n\nfunction ctxMsgMeta(msg: ContextMessage, contentStr: string): string {\n\tconst parts: string[] = [];\n\tconst chars = contentStr ? contentStr.length : 0;\n\tif (chars > 0) parts.push(`${chars.toLocaleString()} chars`);\n\tconst toolCalls = msg.tool_calls || [];\n\tif (toolCalls.length > 0) parts.push(`${toolCalls.length} tool call${toolCalls.length > 1 ? \"s\" : \"\"}`);\n\tif (msg.role === \"tool\" && msg.tool_call_id) parts.push(`id: ${msg.tool_call_id}`);\n\treturn parts.join(\" \\u00b7 \");\n}\n\nfunction ctxMsgToolCall(tc: NonNullable<ContextMessage[\"tool_calls\"]>[number]): HTMLElement {\n\tconst div = ctxEl(\"div\", \"mt-1 border border-[var(--border)] rounded-md p-2 bg-[var(--surface)]\");\n\tconst hdr = ctxEl(\"div\", \"text-xs font-semibold text-[var(--text)] mb-1\");\n\thdr.textContent = `\\ud83d\\udee0 ${tc.function?.name || \"unknown\"}`;\n\tif (tc.id) hdr.appendChild(ctxEl(\"span\", \"font-normal text-[var(--muted)] ml-2\", `id: ${tc.id}`));\n\tdiv.appendChild(hdr);\n\tif (tc.function?.arguments) {\n\t\tconst pre = ctxEl(\"pre\", \"text-xs font-mono whitespace-pre-wrap break-words text-[var(--text)]\");\n\t\ttry {\n\t\t\tpre.textContent = JSON.stringify(JSON.parse(tc.function.arguments), null, 2);\n\t\t} catch {\n\t\t\tpre.textContent = tc.function.arguments;\n\t\t}\n\t\tdiv.appendChild(pre);\n\t}\n\treturn div;\n}\n\nfunction renderContextMessage(msg: ContextMessage, index: number): HTMLElement {\n\tconst wrapper = ctxEl(\"div\", \"mb-2\");\n\tconst contentStr = typeof msg.content === \"string\" ? msg.content : JSON.stringify(msg.content, null, 2);\n\tconst hdr = ctxEl(\"div\", \"flex items-center gap-2 cursor-pointer select-none\");\n\thdr.appendChild(ctxMsgBadge(msg.role || \"unknown\"));\n\thdr.appendChild(ctxEl(\"span\", \"text-xs text-[var(--muted)]\", `#${index}`));\n\tconst meta = ctxMsgMeta(msg, contentStr);\n\tif (meta) hdr.appendChild(ctxEl(\"span\", \"text-xs text-[var(--muted)]\", meta));\n\tconst chevron = ctxEl(\"span\", \"text-xs text-[var(--muted)] ml-auto\");\n\tconst startOpen = index !== 0;\n\tchevron.textContent = startOpen ? \"\\u25bc\" : \"\\u25b6\";\n\thdr.appendChild(chevron);\n\twrapper.appendChild(hdr);\n\tconst body = ctxEl(\"div\", \"mt-1\");\n\tbody.style.display = startOpen ? \"block\" : \"none\";\n\thdr.addEventListener(\"click\", () => {\n\t\tconst open = body.style.display !== \"none\";\n\t\tbody.style.display = open ? \"none\" : \"block\";\n\t\tchevron.textContent = open ? \"\\u25b6\" : \"\\u25bc\";\n\t});\n\tif (contentStr) {\n\t\tconst pre = ctxEl(\n\t\t\t\"pre\",\n\t\t\t\"text-xs font-mono whitespace-pre-wrap break-words bg-[var(--surface)] border border-[var(--border)] rounded-md p-2 text-[var(--text)]\",\n\t\t);\n\t\tpre.textContent = contentStr;\n\t\tbody.appendChild(pre);\n\t}\n\tfor (const tc of msg.tool_calls || []) body.appendChild(ctxMsgToolCall(tc));\n\twrapper.appendChild(body);\n\treturn wrapper;\n}\n\nfunction buildFullContextPromptMemoryBox(pm: PromptMemoryData | null): HTMLElement | null {\n\tif (!pm) return null;\n\tconst box = ctxEl(\n\t\t\"div\",\n\t\t\"text-xs mb-3 rounded-md border border-[var(--border)] bg-[var(--surface)] p-2 text-[var(--text)]\",\n\t);\n\tconst summaryLine = ctxEl(\"div\", \"font-semibold\");\n\tsummaryLine.textContent = `Prompt memory: ${buildPromptMemorySummary(pm)}`;\n\tbox.appendChild(summaryLine);\n\tconst dp = promptMemoryDetailParts(pm);\n\tif (dp.length > 0) box.appendChild(ctxEl(\"div\", \"mt-1 text-[var(--muted)]\", dp.join(\" \\u00b7 \")));\n\treturn box;\n}\n\nfunction appendFullContextWorkspaceWarnings(panel: HTMLElement, payload: any): void {\n\tconst wf: any[] = Array.isArray(payload.workspaceFiles) ? payload.workspaceFiles : [];\n\tif (!payload.truncated || wf.length === 0) return;\n\tconst tf = wf.filter((f: any) => f?.truncated);\n\tif (tf.length === 0) return;\n\tconst warning = ctxEl(\n\t\t\"div\",\n\t\t\"text-xs mb-3 rounded-md border border-[var(--border)] bg-[var(--surface)] p-2 text-[var(--text)]\",\n\t);\n\twarning.textContent = tf\n\t\t.map((f: any) => {\n\t\t\tconst name = typeof f.name === \"string\" ? f.name : \"workspace file\";\n\t\t\treturn `${name}: ${Number(f.original_chars || 0).toLocaleString()} chars, limit ${Number(f.limit_chars || 0).toLocaleString()}, truncated by ${Number(f.truncated_chars || 0).toLocaleString()}`;\n\t\t})\n\t\t.join(\" | \");\n\tpanel.appendChild(warning);\n}\n\nfunction buildFullContextHeaderRow(\n\tpayload: any,\n\tonRefresh: (btn: HTMLButtonElement) => void,\n): { headerRow: HTMLElement; copyBtn: HTMLElement; downloadBtn: HTMLElement; llmOutputBtn: HTMLElement } {\n\tconst headerRow = ctxEl(\"div\", \"flex items-center gap-3 mb-3\");\n\tconst headerText = ctxEl(\"span\", \"text-xs text-[var(--muted)]\");\n\theaderText.textContent = `${payload.messageCount} messages \\u00b7 system prompt ${payload.systemPromptChars.toLocaleString()} chars \\u00b7 total ${payload.totalChars.toLocaleString()} chars`;\n\theaderRow.appendChild(headerText);\n\tconst copyBtn = ctxEl(\"button\", \"provider-btn provider-btn-secondary provider-btn-sm\");\n\tcopyBtn.textContent = \"Copy\";\n\tconst downloadBtn = ctxEl(\"button\", \"provider-btn provider-btn-secondary provider-btn-sm\");\n\tdownloadBtn.textContent = \"Download\";\n\tconst llmOutputBtn = ctxEl(\"button\", \"provider-btn provider-btn-secondary provider-btn-sm\");\n\tllmOutputBtn.textContent = \"LLM output\";\n\theaderRow.appendChild(copyBtn);\n\theaderRow.appendChild(downloadBtn);\n\theaderRow.appendChild(llmOutputBtn);\n\tconst pm = payload.promptMemory || null;\n\tif (pm?.mode === \"frozen-at-session-start\") {\n\t\tconst rb = ctxEl(\"button\", \"provider-btn provider-btn-secondary provider-btn-sm\") as HTMLButtonElement;\n\t\trb.textContent = \"Refresh memory\";\n\t\trb.addEventListener(\"click\", () => onRefresh(rb));\n\t\theaderRow.appendChild(rb);\n\t}\n\treturn { headerRow, copyBtn, downloadBtn, llmOutputBtn };\n}\n\nfunction wireFullContextCopyButton(\n\tcopyBtn: HTMLElement,\n\tmessages: ContextMessage[],\n\tllmOutputs: any[],\n\tllmOutputPanel: HTMLElement,\n): void {\n\tcopyBtn.addEventListener(\"click\", () => {\n\t\tconst lines = messages.map((m) => {\n\t\t\tconst content = typeof m.content === \"string\" ? m.content : JSON.stringify(m.content);\n\t\t\tconst parts = [content];\n\t\t\tfor (const tc of m.tool_calls || [])\n\t\t\t\tparts.push(`[tool_call: ${tc.function?.name || \"?\"} ${tc.function?.arguments || \"\"}]`);\n\t\t\treturn `[${m.role}] ${parts.join(\"\\n\")}`;\n\t\t});\n\t\tconst contextText = lines.join(\"\\n\");\n\t\tlet copyText = contextText;\n\t\tconst llmOutputVisible = llmOutputPanel && !llmOutputPanel.classList.contains(\"hidden\");\n\t\tif (llmOutputVisible) copyText = `LLM output:\\n${JSON.stringify(llmOutputs, null, 2)}\\n\\nContext:\\n${contextText}`;\n\t\tnavigator.clipboard.writeText(copyText).then(() => {\n\t\t\tcopyBtn.textContent = \"Copied!\";\n\t\t\tsetTimeout(() => {\n\t\t\t\tcopyBtn.textContent = \"Copy\";\n\t\t\t}, 1500);\n\t\t});\n\t});\n}\n\nfunction wireFullContextDownloadButton(downloadBtn: HTMLElement, messages: ContextMessage[]): void {\n\tdownloadBtn.addEventListener(\"click\", () => {\n\t\tconst lines = messages.map((m) => JSON.stringify(m));\n\t\tconst blob = new Blob([`${lines.join(\"\\n\")}\\n`], { type: \"application/x-jsonlines\" });\n\t\tconst url = URL.createObjectURL(blob);\n\t\tconst a = document.createElement(\"a\");\n\t\ta.href = url;\n\t\ta.download = `context-${new Date().toISOString().slice(0, 19).replace(/[T:]/g, \"-\")}.jsonl`;\n\t\ta.click();\n\t\tURL.revokeObjectURL(url);\n\t});\n}\n\nfunction buildFullContextLlmOutputPanel(llmOutputs: any[]): HTMLElement {\n\tconst panel = ctxEl(\"div\", \"hidden mb-3\");\n\tpanel.appendChild(\n\t\tctxEl(\n\t\t\t\"div\",\n\t\t\t\"text-xs text-[var(--muted)] mb-1\",\n\t\t\t`${llmOutputs.length} assistant output${llmOutputs.length === 1 ? \"\" : \"s\"}`,\n\t\t),\n\t);\n\tconst pre = ctxEl(\n\t\t\"pre\",\n\t\t\"text-xs font-mono whitespace-pre-wrap break-words bg-[var(--surface)] border border-[var(--border)] rounded-md p-2 text-[var(--text)]\",\n\t);\n\tpre.id = \"fullContextLlmOutput\";\n\tpre.textContent = JSON.stringify(llmOutputs, null, 2);\n\tpanel.appendChild(pre);\n\treturn panel;\n}\n\nfunction wireFullContextLlmOutputToggle(button: HTMLElement, panel: HTMLElement): void {\n\tbutton.addEventListener(\"click\", () => {\n\t\tconst hidden = panel.classList.contains(\"hidden\");\n\t\tpanel.classList.toggle(\"hidden\", !hidden);\n\t\tbutton.textContent = hidden ? \"Hide LLM output\" : \"LLM output\";\n\t});\n}\n\nfunction refreshFullContextMemory(refreshBtn: HTMLButtonElement): void {\n\trefreshBtn.disabled = true;\n\trefreshBtn.textContent = \"Refreshing\\u2026\";\n\trefreshPromptMemoryToolbarSnapshot().then(() => {\n\t\trefreshBtn.disabled = false;\n\t\trefreshBtn.textContent = \"Refresh memory\";\n\t});\n}\n\nfunction refreshFullContextPanel(): void {\n\tconst panel = S.$(\"fullContextPanel\") as HTMLElement | null;\n\tif (!panel) return;\n\tpanel.textContent = \"\";\n\tpanel.appendChild(ctxEl(\"div\", \"text-xs text-[var(--muted)]\", \"Building full context\\u2026\"));\n\tsendRpc(\"chat.full_context\", {}).then((res: any) => {\n\t\tpanel.textContent = \"\";\n\t\tif (!(res?.ok && res.payload)) {\n\t\t\tpanel.appendChild(ctxEl(\"div\", \"text-xs text-[var(--error)]\", \"Failed to build context\"));\n\t\t\treturn;\n\t\t}\n\t\tconst pm = res.payload.promptMemory || null;\n\t\trefreshPromptMemoryToolbarFromPayload(pm);\n\t\tconst pmBox = buildFullContextPromptMemoryBox(pm);\n\t\tif (pmBox) panel.appendChild(pmBox);\n\t\tappendFullContextWorkspaceWarnings(panel, res.payload);\n\t\tconst messages: ContextMessage[] = res.payload.messages || [];\n\t\tconst llmOutputs = res.payload.llmOutputs || [];\n\t\tconst llmOutputPanel = buildFullContextLlmOutputPanel(llmOutputs);\n\t\tconst header = buildFullContextHeaderRow(res.payload, refreshFullContextMemory);\n\t\twireFullContextCopyButton(header.copyBtn, messages, llmOutputs, llmOutputPanel);\n\t\twireFullContextDownloadButton(header.downloadBtn, messages);\n\t\twireFullContextLlmOutputToggle(header.llmOutputBtn, llmOutputPanel);\n\t\tpanel.appendChild(header.headerRow);\n\t\tpanel.appendChild(llmOutputPanel);\n\t\tfor (let i = 0; i < messages.length; i++) panel.appendChild(renderContextMessage(messages[i], i));\n\t});\n}\n\nfunction toggleFullContextPanel(): void {\n\tconst modal = S.$(\"fullContextModal\") as HTMLElement | null;\n\tif (!modal) return;\n\tconst opening = modal.classList.contains(\"hidden\");\n\tif (!opening) {\n\t\tsetFullContextModalOpen(false);\n\t\treturn;\n\t}\n\tsetDebugModalOpen(false);\n\tsetFullContextModalOpen(true);\n\trefreshFullContextPanel();\n}\n\nexport function maybeRefreshFullContext(): void {\n\tconst modal = S.$(\"fullContextModal\") as HTMLElement | null;\n\tif (modal && !modal.classList.contains(\"hidden\")) refreshFullContextPanel();\n}\n\n// ── MCP toggle ───────────────────────────────────────────\nexport function updateMcpToggleUI(enabled: boolean): void {\n\tconst btn = S.$(\"mcpToggleBtn\") as HTMLElement | null;\n\tconst label = S.$(\"mcpToggleLabel\") as HTMLElement | null;\n\tif (!btn) return;\n\tif (enabled) {\n\t\tbtn.style.color = \"var(--ok)\";\n\t\tbtn.style.borderColor = \"var(--ok)\";\n\t\tif (label) label.textContent = \"MCP\";\n\t\tbtn.title = \"MCP tools enabled \\u2014 click to disable for this session\";\n\t} else {\n\t\tbtn.style.color = \"var(--muted)\";\n\t\tbtn.style.borderColor = \"var(--border)\";\n\t\tif (label) label.textContent = \"MCP off\";\n\t\tbtn.title = \"MCP tools disabled \\u2014 click to enable for this session\";\n\t}\n}\n\nfunction toggleMcp(): void {\n\tconst label = S.$(\"mcpToggleLabel\") as HTMLElement | null;\n\tconst isEnabled = label && label.textContent === \"MCP\";\n\tconst newDisabled = isEnabled;\n\tsendRpc(\"sessions.patch\", { key: S.activeSessionKey, mcpDisabled: newDisabled }).then((res: any) => {\n\t\tif (res?.ok) updateMcpToggleUI(!newDisabled);\n\t});\n}\n\nexport function showModelNotice(model: ModelNotice): void {\n\tif (!S.chatMsgBox) return;\n\tif (model.supportsTools !== false) return;\n\tslashInjectStyles();\n\tconst tpl = document.getElementById(\"tpl-model-notice\") as HTMLTemplateElement | null;\n\tif (!tpl) return;\n\tconst card = (tpl.content.cloneNode(true) as DocumentFragment).firstElementChild as HTMLElement;\n\tconst nameEl = card.querySelector(\"[data-model-name]\");\n\tif (nameEl) nameEl.textContent = model.displayName || model.id;\n\tconst providerEl = card.querySelector(\"[data-provider]\");\n\tif (providerEl) providerEl.textContent = model.provider || \"local\";\n\tS.chatMsgBox.appendChild(card);\n\tS.chatMsgBox.scrollTop = S.chatMsgBox.scrollHeight;\n}\n\n// ── Slash command handlers ───────────────────────────────\nfunction handleSlashCommand(cmdName: string, cmdArgs: string): void {\n\tif (cmdName === \"clear\") {\n\t\tclearActiveSession();\n\t\treturn;\n\t}\n\tif (cmdName === \"compact\") {\n\t\tchatAddMsg(\"system\", \"Compacting conversation\\u2026\");\n\t\tsendRpc(\"chat.compact\", {}).then((res: any) => {\n\t\t\tif (res?.ok) switchSession(S.activeSessionKey);\n\t\t\telse chatAddMsg(\"error\", res?.error?.message || \"Compact failed\");\n\t\t});\n\t\treturn;\n\t}\n\tif (cmdName === \"context\") {\n\t\tchatAddMsg(\"system\", \"Loading context\\u2026\");\n\t\tsendRpc(\"chat.context\", {}).then((res: any) => {\n\t\t\tif (S.chatMsgBox?.lastChild) S.chatMsgBox.removeChild(S.chatMsgBox.lastChild);\n\t\t\tif (res?.ok && res.payload) {\n\t\t\t\ttry {\n\t\t\t\t\trenderContextCard(res.payload);\n\t\t\t\t} catch (err: any) {\n\t\t\t\t\tchatAddMsg(\"error\", `Render error: ${err.message}`);\n\t\t\t\t}\n\t\t\t} else chatAddMsg(\"error\", res?.error?.message || \"Context failed\");\n\t\t});\n\t\treturn;\n\t}\n\tif (cmdName === \"sh\") {\n\t\tconst normalized = (cmdArgs || \"\").toLowerCase();\n\t\tif (normalized === \"off\" || normalized === \"exit\") {\n\t\t\tsetCommandMode(false);\n\t\t\tchatAddMsg(\"system\", renderMarkdown(\"**Command:** mode disabled\"), true);\n\t\t\treturn;\n\t\t}\n\t\tsetCommandMode(true);\n\t\tchatAddMsg(\n\t\t\t\"system\",\n\t\t\trenderMarkdown(`**Command:** mode enabled (${commandModeSummary()}) \\u00b7 exit with /sh off or Esc`),\n\t\t\ttrue,\n\t\t);\n\t}\n}\n\nfunction tryHandleLocalSlashCommand(text: string, hasImages: boolean): boolean {\n\tif (text.charAt(0) !== \"/\" || hasImages) return false;\n\tconst slash = parseSlashCommand(text);\n\tif (!(slash && shouldHandleSlashLocally(slash.name, slash.args))) return false;\n\t(S.chatInput as HTMLTextAreaElement).value = \"\";\n\tchatAutoResize();\n\tslashHideMenu();\n\thandleSlashCommand(slash.name, slash.args);\n\treturn true;\n}\n\nfunction rememberChatHistory(text: string): void {\n\tif (!text) return;\n\tS.chatHistory.push(text);\n\tif (S.chatHistory.length > 200) S.setChatHistory(S.chatHistory.slice(-200));\n\tlocalStorage.setItem(\"moltis-chat-history\", JSON.stringify(S.chatHistory));\n}\n\nfunction resetComposerAfterSend(): void {\n\tS.setChatHistoryIdx(-1);\n\tS.setChatHistoryDraft(\"\");\n\t(S.chatInput as HTMLTextAreaElement).value = \"\";\n\tchatAutoResize();\n\tif (window.innerWidth < 768) S.chatInput!.blur();\n}\n\nfunction normalizeOutgoingText(text: string, hasImages: boolean): string {\n\tif (!(S.commandModeEnabled && text && !hasImages)) return text;\n\tconst parsed = parseSlashCommand(text);\n\tif (parsed && parsed.name === \"sh\") return text;\n\treturn `/sh ${text}`;\n}\n\nfunction applySelectedModelToChatParams(chatParams: Record<string, unknown>): void {\n\tconst effectiveId = modelStore.effectiveModelId.value;\n\tif (!effectiveId) return;\n\tchatParams.model = effectiveId;\n\tsetSessionModel(S.activeSessionKey, effectiveId);\n}\n\nfunction handleChatSendRpcResponse(res: any, userEl: HTMLElement | null): void {\n\tif (res?.ok && res.payload?.runId) setSessionActiveRunId(S.activeSessionKey, res.payload.runId);\n\tif (res?.payload?.queued) {\n\t\tmarkMessageQueued(userEl, S.activeSessionKey);\n\t\treturn;\n\t}\n\tif (res && !res.ok && res.error) chatAddMsg(\"error\", res.error.message || \"Request failed\");\n}\n\nfunction buildChatMessage(\n\ttext: string,\n\tseq: number,\n\tdisplayText?: string,\n): { params: Record<string, unknown>; el: HTMLElement | null } {\n\tconst userText = displayText !== undefined ? displayText : text;\n\tconst images = hasPendingImages() ? getPendingImages() : [];\n\tif (images.length > 0) {\n\t\tconst content: Array<Record<string, unknown>> = [];\n\t\tif (text) content.push({ type: \"text\", text });\n\t\tfor (const img of images) content.push({ type: \"image_url\", image_url: { url: (img as any).dataUrl } });\n\t\tconst params = { content, _seq: seq };\n\t\tconst el = chatAddMsgWithImages(\"user\", userText ? renderMarkdown(userText) : \"\", images);\n\t\tclearPendingImages();\n\t\treturn { params, el };\n\t}\n\treturn { params: { text, _seq: seq }, el: chatAddMsg(\"user\", renderMarkdown(userText), true) };\n}\n\nfunction sendChat(): void {\n\tconst text = (S.chatInput as HTMLTextAreaElement).value.trim();\n\tconst hasImages = hasPendingImages();\n\tif (!((text || hasImages) && S.connected)) return;\n\twarmAudioPlayback();\n\tif (tryHandleLocalSlashCommand(text, hasImages)) return;\n\trememberChatHistory(text);\n\tresetComposerAfterSend();\n\tconst outgoingText = normalizeOutgoingText(text, hasImages);\n\tS.setChatSeq(S.chatSeq + 1);\n\tconst msg = buildChatMessage(outgoingText, S.chatSeq, text);\n\tconst chatParams = msg.params;\n\tconst userEl = msg.el;\n\tif (userEl) highlightCodeBlocks(userEl);\n\tapplySelectedModelToChatParams(chatParams);\n\tbumpSessionCount(S.activeSessionKey, 1);\n\tcacheOutgoingUserMessage(S.activeSessionKey, chatParams);\n\tseedSessionPreviewFromUserText(S.activeSessionKey, text || outgoingText);\n\tsetSessionReplying(S.activeSessionKey, true);\n\tsendRpc(\"chat.send\", chatParams).then((res: any) => handleChatSendRpcResponse(res, userEl));\n\tmaybeRefreshFullContext();\n}\n\nfunction markMessageQueued(el: HTMLElement | null, sessionKey: string): void {\n\tif (!el) return;\n\tconst tray = document.getElementById(\"queuedMessages\");\n\tif (!tray) return;\n\tconsole.debug(\"[queued] marking user message as queued, moving to tray\", { sessionKey });\n\tel.classList.add(\"queued\");\n\tconst badge = document.createElement(\"div\");\n\tbadge.className = \"queued-badge\";\n\tconst label = document.createElement(\"span\");\n\tlabel.className = \"queued-label\";\n\tlabel.textContent = \"Queued\";\n\tconst btn = document.createElement(\"button\");\n\tbtn.className = \"queued-cancel\";\n\tbtn.title = \"Cancel all queued\";\n\tbtn.textContent = \"\\u2715\";\n\tbtn.addEventListener(\"click\", (e: MouseEvent) => {\n\t\te.stopPropagation();\n\t\tsendRpc(\"chat.cancel_queued\", { sessionKey });\n\t});\n\tbadge.appendChild(label);\n\tbadge.appendChild(btn);\n\tel.appendChild(badge);\n\ttray.appendChild(el);\n\ttray.classList.remove(\"hidden\");\n}\n\nfunction chatAutoResize(): void {\n\tif (!S.chatInput) return;\n\tS.chatInput.style.height = \"auto\";\n\tS.chatInput.style.height = `${Math.min(S.chatInput.scrollHeight, 120)}px`;\n}\n\nfunction handleHistoryUp(): void {\n\tif (S.chatHistory.length === 0) return;\n\tif (S.chatHistoryIdx === -1) {\n\t\tS.setChatHistoryDraft((S.chatInput as HTMLTextAreaElement).value);\n\t\tS.setChatHistoryIdx(S.chatHistory.length - 1);\n\t} else if (S.chatHistoryIdx > 0) S.setChatHistoryIdx(S.chatHistoryIdx - 1);\n\t(S.chatInput as HTMLTextAreaElement).value = S.chatHistory[S.chatHistoryIdx];\n\tchatAutoResize();\n}\n\nfunction handleHistoryDown(): void {\n\tif (S.chatHistoryIdx === -1) return;\n\tif (S.chatHistoryIdx < S.chatHistory.length - 1) {\n\t\tS.setChatHistoryIdx(S.chatHistoryIdx + 1);\n\t\t(S.chatInput as HTMLTextAreaElement).value = S.chatHistory[S.chatHistoryIdx];\n\t} else {\n\t\tS.setChatHistoryIdx(-1);\n\t\t(S.chatInput as HTMLTextAreaElement).value = S.chatHistoryDraft;\n\t}\n\tchatAutoResize();\n}\n\n// Safe: static hardcoded HTML template string — no user input is interpolated.\n// This is a compile-time constant defined in the original JS source.\nconst chatPageHTML =\n\t'<div style=\"position:absolute;inset:0;display:grid;grid-template-rows:auto auto 1fr auto auto auto;overflow:hidden\">' +\n\t'<div class=\"chat-toolbar h-12 px-4 border-b border-[var(--border)] bg-[var(--surface)] flex items-center gap-2\" style=\"grid-row:1;\">' +\n\t'<div id=\"modelCombo\" class=\"model-combo\"><button id=\"modelComboBtn\" class=\"model-combo-btn\" type=\"button\"><span id=\"modelComboLabel\">loading\\u2026</span><span class=\"icon icon-sm icon-chevron-down model-combo-chevron\"></span></button><div id=\"modelDropdown\" class=\"model-dropdown hidden\"><input id=\"modelSearchInput\" type=\"text\" placeholder=\"Search models\\u2026\" class=\"model-search-input\" autocomplete=\"off\" /><div id=\"modelDropdownList\" class=\"model-dropdown-list\"></div></div></div>' +\n\t'<div id=\"reasoningCombo\" class=\"model-combo hidden\"><button id=\"reasoningComboBtn\" class=\"model-combo-btn\" type=\"button\" title=\"Reasoning effort\"><span class=\"icon icon-sm icon-brain\" style=\"flex-shrink:0;\"></span><span id=\"reasoningComboLabel\">Off</span><span class=\"icon icon-sm icon-chevron-down model-combo-chevron\"></span></button><div id=\"reasoningDropdown\" class=\"model-dropdown hidden\"><div id=\"reasoningDropdownList\" class=\"model-dropdown-list\"></div></div></div>' +\n\t'<div id=\"nodeCombo\" class=\"model-combo hidden\"><button id=\"nodeComboBtn\" class=\"model-combo-btn\" type=\"button\"><span class=\"icon icon-sm icon-server\" style=\"flex-shrink:0;\"></span><span id=\"nodeComboLabel\">Local</span><span class=\"icon icon-sm icon-chevron-down model-combo-chevron\"></span></button><div id=\"nodeDropdown\" class=\"model-dropdown hidden\" tabindex=\"-1\"><div id=\"nodeDropdownList\" class=\"model-dropdown-list\"></div></div></div>' +\n\t'<div id=\"sessionHeaderToolbarMount\" class=\"ml-auto flex items-center gap-1.5\"></div>' +\n\t'<button id=\"chatMoreBtn\" type=\"button\" class=\"model-combo-btn\" title=\"More controls\" aria-label=\"More controls\"><span class=\"icon icon-lg icon-menu-dots-horizontal\"></span></button></div>' +\n\t'<div id=\"chatMoreModal\" class=\"provider-modal-backdrop hidden\"><div class=\"provider-modal\" style=\"width:560px;max-width:92vw;\"><div class=\"provider-modal-header\"><div class=\"flex items-center gap-2\"><button id=\"chatMoreDeleteAllBtn\" type=\"button\" class=\"provider-btn provider-btn-sm chat-session-btn-danger inline-flex items-center gap-1.5\" style=\"background:var(--error);border-color:var(--error);color:#fff;\"><span class=\"icon icon-sm icon-x-circle shrink-0\"></span><span id=\"chatMoreDeleteAllLabel\">Delete all sessions</span></button></div><div id=\"sessionHeaderModalTopMount\" class=\"flex items-center gap-2\"></div></div><div class=\"provider-modal-body flex flex-col gap-3\"><div class=\"flex flex-wrap items-center gap-2\"><button id=\"sandboxToggle\" class=\"sandbox-toggle text-xs border border-[var(--border)] px-2 py-1 rounded-md transition-colors cursor-pointer bg-transparent font-[var(--font-body)] inline-flex items-center gap-1\" title=\"Toggle sandbox mode\"><span class=\"icon icon-md icon-lock shrink-0\"></span><span id=\"sandboxLabel\">sandboxed</span></button><div style=\"position:relative;display:inline-block\"><button id=\"sandboxImageBtn\" class=\"text-xs border border-[var(--border)] px-2 py-1 rounded-md transition-colors cursor-pointer bg-transparent font-[var(--font-body)] inline-flex items-center gap-1 text-[var(--muted)]\" title=\"Sandbox image\"><span class=\"icon icon-md icon-cube shrink-0\"></span><span id=\"sandboxImageLabel\" class=\"max-w-[120px] truncate\">ubuntu:25.10</span></button><div id=\"sandboxImageDropdown\" class=\"hidden\" style=\"position:absolute;top:100%;left:0;z-index:50;margin-top:4px;min-width:200px;max-height:300px;overflow-y:auto;background:var(--surface);border:1px solid var(--border);border-radius:8px;box-shadow:0 4px 12px rgba(0,0,0,.15);\"></div></div><button id=\"mcpToggleBtn\" class=\"text-xs border border-[var(--border)] px-2 py-1 rounded-md transition-colors cursor-pointer bg-transparent font-[var(--font-body)] inline-flex items-center gap-1\" title=\"Toggle MCP tools for this session\"><span class=\"icon icon-md icon-link shrink-0\"></span><span id=\"mcpToggleLabel\">MCP</span></button><button id=\"debugPanelBtn\" class=\"text-xs border border-[var(--border)] px-2 py-1 rounded-md transition-colors cursor-pointer bg-transparent font-[var(--font-body)] inline-flex items-center gap-1 text-[var(--muted)]\" title=\"Show context debug info\"><span class=\"icon icon-md icon-wrench shrink-0\"></span><span id=\"debugPanelLabel\">Debug</span></button><button id=\"fullContextBtn\" class=\"text-xs border border-[var(--border)] px-2 py-1 rounded-md transition-colors cursor-pointer bg-transparent font-[var(--font-body)] inline-flex items-center gap-1 text-[var(--muted)]\" title=\"Show full LLM context (system prompt + history)\"><span class=\"icon icon-md icon-document shrink-0\"></span><span id=\"fullContextLabel\">Context</span></button></div><div id=\"sessionControlsSection\" class=\"border-t border-[var(--border)] pt-3\"><div id=\"sessionHeaderModalMount\" class=\"w-full\"></div></div></div></div></div>' +\n\t'<div id=\"debugModal\" class=\"provider-modal-backdrop hidden\"><div class=\"provider-modal\" style=\"width:min(980px,96vw);max-width:96vw;max-height:88vh;\"><div class=\"provider-modal-header\"><div class=\"provider-item-name\">Debug context</div><button id=\"debugModalCloseBtn\" type=\"button\" class=\"provider-btn provider-btn-secondary provider-btn-sm\">Close</button></div><div class=\"provider-modal-body\" style=\"padding:0;overflow:hidden;\"><div id=\"debugPanel\" class=\"px-4 py-3 overflow-y-auto\" style=\"max-height:72vh;\"></div></div></div></div>' +\n\t'<div id=\"fullContextModal\" class=\"provider-modal-backdrop hidden\"><div class=\"provider-modal\" style=\"width:min(1080px,96vw);max-width:96vw;max-height:88vh;\"><div class=\"provider-modal-header\"><div class=\"provider-item-name\">Full context</div><button id=\"fullContextModalCloseBtn\" type=\"button\" class=\"provider-btn provider-btn-secondary provider-btn-sm\">Close</button></div><div class=\"provider-modal-body\" style=\"padding:0;overflow:hidden;\"><div id=\"fullContextPanel\" class=\"px-4 py-3 overflow-y-auto\" style=\"max-height:72vh;\"></div></div></div></div>' +\n\t'<div class=\"p-4 flex flex-col gap-2\" id=\"messages\" style=\"grid-row:3;overflow-y:auto;min-height:0\"></div>' +\n\t'<div id=\"queuedMessages\" class=\"queued-tray hidden\" style=\"grid-row:4;\"></div>' +\n\t'<div id=\"tokenBar\" class=\"token-bar\" style=\"grid-row:5;\"></div>' +\n\t'<div class=\"chat-input-row px-4 py-3 border-t border-[var(--border)] bg-[var(--surface)] flex gap-2 items-end\" style=\"grid-row:6;\"><span id=\"chatCommandPrompt\" class=\"chat-command-prompt chat-command-prompt-hidden\" title=\"Command prompt symbol\" aria-hidden=\"true\">$</span><textarea id=\"chatInput\" placeholder=\"Type a message...\" rows=\"1\" enterkeyhint=\"send\" class=\"flex-1 bg-[var(--surface2)] border border-[var(--border)] text-[var(--text)] px-3 py-2 rounded-lg text-sm resize-none min-h-[40px] max-h-[120px] leading-relaxed focus:outline-none focus:border-[var(--border-strong)] focus:ring-1 focus:ring-[var(--accent-subtle)] transition-colors font-[var(--font-body)]\"></textarea><button id=\"micBtn\" disabled title=\"Click to start recording\" class=\"mic-btn min-h-[40px] px-3 bg-[var(--surface2)] border border-[var(--border)] rounded-lg text-[var(--muted)] cursor-pointer disabled:opacity-40 disabled:cursor-default transition-colors hover:border-[var(--border-strong)] hover:text-[var(--text)]\"><span class=\"icon icon-lg icon-microphone\"></span></button><button id=\"sendBtn\" disabled class=\"provider-btn min-h-[40px] disabled:opacity-40 disabled:cursor-default\">Send</button></div></div>';\n\nfunction msgRole(el: Element): string | null {\n\tif (el.classList.contains(\"user\")) return \"You\";\n\tif (el.classList.contains(\"assistant\")) return \"Assistant\";\n\treturn null;\n}\n\nfunction handleChatCopy(e: ClipboardEvent): void {\n\tconst sel = window.getSelection();\n\tif (!sel || sel.isCollapsed || !S.chatMsgBox) return;\n\tconst lines: string[] = [];\n\tfor (const msg of S.chatMsgBox.querySelectorAll(\".msg\")) {\n\t\tif (!sel.containsNode(msg, true)) continue;\n\t\tconst role = msgRole(msg);\n\t\tif (!role) continue;\n\t\tconst text = sel.containsNode(msg, false) ? (msg.textContent || \"\").trim() : sel.toString().trim();\n\t\tif (text) lines.push(`${role}:\\n${text}`);\n\t}\n\tif (lines.length > 1) {\n\t\te.preventDefault();\n\t\te.clipboardData?.setData(\"text/plain\", lines.join(\"\\n\\n\"));\n\t}\n}\n\nfunction mountSessionHeaderControls(closeChatMore: () => void): void {\n\tconst headerToolbarMount = S.$(\"sessionHeaderToolbarMount\");\n\tif (headerToolbarMount) {\n\t\trender(\n\t\t\t<SessionHeader\n\t\t\t\tshowName={false}\n\t\t\t\tshowShare={false}\n\t\t\t\tshowFork={false}\n\t\t\t\tshowClear={false}\n\t\t\t\tshowDelete={false}\n\t\t\t\tshowArchive={false}\n\t\t\t/>,\n\t\t\theaderToolbarMount,\n\t\t);\n\t}\n\tconst headerModalMount = S.$(\"sessionHeaderModalMount\");\n\tif (headerModalMount) {\n\t\trender(\n\t\t\t<SessionHeader\n\t\t\t\tshowSelectors={false}\n\t\t\t\tshowStop={false}\n\t\t\t\tshowFork={false}\n\t\t\t\tshowShare={false}\n\t\t\t\tshowDelete={false}\n\t\t\t\tshowArchive={false}\n\t\t\t\tnameOwnLine={true}\n\t\t\t\tshowRenameButton={true}\n\t\t\t/>,\n\t\t\theaderModalMount,\n\t\t);\n\t}\n\tconst headerModalTopMount = S.$(\"sessionHeaderModalTopMount\");\n\tif (headerModalTopMount) {\n\t\trender(\n\t\t\t<SessionHeader\n\t\t\t\tshowSelectors={false}\n\t\t\t\tshowName={false}\n\t\t\t\tshowStop={false}\n\t\t\t\tactionButtonClass={\"provider-btn provider-btn-secondary provider-btn-sm\"}\n\t\t\t\tonBeforeShare={() => closeChatMore?.()}\n\t\t\t\tonBeforeArchive={() => closeChatMore?.()}\n\t\t\t\tonBeforeDelete={() => closeChatMore?.()}\n\t\t\t/>,\n\t\t\theaderModalTopMount,\n\t\t);\n\t}\n}\n\nfunction bindSessionControlsVisibility(): void {\n\tconst sec = S.$(\"sessionControlsSection\") as HTMLElement | null;\n\tif (!sec) return;\n\tdisposeSessionControlsVisibility?.();\n\tdisposeSessionControlsVisibility = effect(() => {\n\t\tconst isMain = (sessionStore.activeSessionKey.value || \"main\") === \"main\";\n\t\tsec.classList.toggle(\"hidden\", isMain);\n\t});\n}\n\nfunction bindChatMoreModal(\n\tdebugModal: HTMLElement | null,\n\tfullContextModal: HTMLElement | null,\n\tcloseDebugModal: (() => void) | null,\n\tcloseFullContextModal: (() => void) | null,\n): (() => void) | null {\n\tconst chatMoreModal = S.$(\"chatMoreModal\") as HTMLElement | null;\n\tconst chatMoreBtn = S.$(\"chatMoreBtn\") as HTMLElement | null;\n\tif (!(chatMoreModal && chatMoreBtn)) return null;\n\tconst closeChatMore = (): void => {\n\t\tchatMoreModal.classList.add(\"hidden\");\n\t\tchatMoreBtn.classList.remove(\"active\");\n\t\tif (S.sandboxImageDropdown) S.sandboxImageDropdown.classList.add(\"hidden\");\n\t};\n\tconst openChatMore = (): void => {\n\t\tsetDebugModalOpen(false);\n\t\tsetFullContextModalOpen(false);\n\t\tchatMoreModal.classList.remove(\"hidden\");\n\t\tchatMoreBtn.classList.add(\"active\");\n\t};\n\tchatMoreBtn.addEventListener(\"click\", openChatMore);\n\tchatMoreModal.addEventListener(\"click\", (e: MouseEvent) => {\n\t\tif (e.target === chatMoreModal) closeChatMore();\n\t});\n\tfor (const id of [\"debugPanelBtn\", \"fullContextBtn\"]) {\n\t\tconst b = S.$(id);\n\t\tif (b) b.addEventListener(\"click\", closeChatMore);\n\t}\n\tchatMoreModalKeydownHandler = (e: KeyboardEvent): void => {\n\t\tif (e.key !== \"Escape\") return;\n\t\tif (fullContextModal && !fullContextModal.classList.contains(\"hidden\")) {\n\t\t\tcloseFullContextModal?.();\n\t\t\treturn;\n\t\t}\n\t\tif (debugModal && !debugModal.classList.contains(\"hidden\")) {\n\t\t\tcloseDebugModal?.();\n\t\t\treturn;\n\t\t}\n\t\tcloseChatMore();\n\t};\n\tdocument.addEventListener(\"keydown\", chatMoreModalKeydownHandler);\n\treturn closeChatMore;\n}\n\nfunction bindDeleteAllSessions(closeChatMore: (() => void) | null): void {\n\tconst btn = S.$(\"chatMoreDeleteAllBtn\") as HTMLButtonElement | null;\n\tif (!btn) return;\n\tconst label = S.$(\"chatMoreDeleteAllLabel\") as HTMLElement | null;\n\tlet inFlight = false;\n\tbtn.addEventListener(\"click\", () => {\n\t\tif (inFlight) return;\n\t\tinFlight = true;\n\t\tbtn.disabled = true;\n\t\tif (label) label.textContent = \"Deleting\\u2026\";\n\t\tcloseChatMore?.();\n\t\tclearAllSessions()\n\t\t\t.then((res: any) => {\n\t\t\t\tif (res?.ok && !res?.skipped) return;\n\t\t\t\tif (res?.cancelled || res?.skipped) return;\n\t\t\t\tchatAddMsg(\"error\", res?.error?.message || \"Failed to clear sessions\");\n\t\t\t})\n\t\t\t.finally(() => {\n\t\t\t\tinFlight = false;\n\t\t\t\tbtn.disabled = false;\n\t\t\t\tif (label) label.textContent = \"Delete all sessions\";\n\t\t\t});\n\t});\n}\n\nfunction bindChatComposer(): void {\n\tconst chatInput = S.chatInput as HTMLTextAreaElement;\n\tchatInput.addEventListener(\"input\", () => {\n\t\tchatAutoResize();\n\t\tslashHandleInput();\n\t});\n\tchatInput.addEventListener(\"keydown\", (e: KeyboardEvent) => {\n\t\tif (slashHandleKeydown(e)) return;\n\t\tif (e.key === \"Escape\" && S.commandModeEnabled && !chatInput.value.trim()) {\n\t\t\te.preventDefault();\n\t\t\tsetCommandMode(false);\n\t\t\treturn;\n\t\t}\n\t\tif (e.key === \"Enter\" && !e.shiftKey && !(e as any).isComposing) {\n\t\t\te.preventDefault();\n\t\t\tsendChat();\n\t\t\treturn;\n\t\t}\n\t\tif (e.key === \"ArrowUp\" && chatInput.selectionStart === 0 && !e.shiftKey) {\n\t\t\te.preventDefault();\n\t\t\thandleHistoryUp();\n\t\t\treturn;\n\t\t}\n\t\tif (e.key === \"ArrowDown\" && chatInput.selectionStart === chatInput.value.length && !e.shiftKey) {\n\t\t\te.preventDefault();\n\t\t\thandleHistoryDown();\n\t\t}\n\t});\n\tS.chatSendBtn!.addEventListener(\"click\", sendChat);\n}\n\nfunction initializeChatControls(): void {\n\tS.setModelCombo(S.$(\"modelCombo\"));\n\tS.setModelComboBtn(S.$(\"modelComboBtn\"));\n\tS.setModelComboLabel(S.$(\"modelComboLabel\"));\n\tS.setModelDropdown(S.$(\"modelDropdown\"));\n\tS.setModelSearchInput(S.$(\"modelSearchInput\"));\n\tS.setModelDropdownList(S.$(\"modelDropdownList\"));\n\tbindModelComboEvents();\n\tbindReasoningToggle();\n\tS.setNodeCombo(S.$(\"nodeCombo\"));\n\tS.setNodeComboBtn(S.$(\"nodeComboBtn\"));\n\tS.setNodeComboLabel(S.$(\"nodeComboLabel\"));\n\tS.setNodeDropdown(S.$(\"nodeDropdown\"));\n\tS.setNodeDropdownList(S.$(\"nodeDropdownList\"));\n\tbindNodeComboEvents();\n\tfetchNodes();\n\tS.setSandboxToggleBtn(S.$(\"sandboxToggle\"));\n\tS.setSandboxLabel(S.$(\"sandboxLabel\"));\n\tbindSandboxToggleEvents();\n\tupdateSandboxUI(true);\n\tS.setSandboxImageBtn(S.$(\"sandboxImageBtn\"));\n\tS.setSandboxImageLabel(S.$(\"sandboxImageLabel\"));\n\tS.setSandboxImageDropdown(S.$(\"sandboxImageDropdown\"));\n\tbindSandboxImageEvents();\n\tupdateSandboxImageUI(null);\n}\n\nfunction bindContextModals(): {\n\tdebugModal: HTMLElement | null;\n\tfullContextModal: HTMLElement | null;\n\tcloseDebugModal: (() => void) | null;\n\tcloseFullContextModal: (() => void) | null;\n} {\n\tconst debugModal = S.$(\"debugModal\") as HTMLElement | null;\n\tconst debugCloseBtn = S.$(\"debugModalCloseBtn\") as HTMLElement | null;\n\tlet closeDebugModal: (() => void) | null = null;\n\tif (debugModal) {\n\t\tcloseDebugModal = () => setDebugModalOpen(false);\n\t\tif (debugCloseBtn) debugCloseBtn.addEventListener(\"click\", closeDebugModal);\n\t\tdebugModal.addEventListener(\"click\", (e: MouseEvent) => {\n\t\t\tif (e.target === debugModal) closeDebugModal!();\n\t\t});\n\t}\n\tconst fullContextModal = S.$(\"fullContextModal\") as HTMLElement | null;\n\tconst fcCloseBtn = S.$(\"fullContextModalCloseBtn\") as HTMLElement | null;\n\tlet closeFullContextModal: (() => void) | null = null;\n\tif (fullContextModal) {\n\t\tcloseFullContextModal = () => setFullContextModalOpen(false);\n\t\tif (fcCloseBtn) fcCloseBtn.addEventListener(\"click\", closeFullContextModal);\n\t\tfullContextModal.addEventListener(\"click\", (e: MouseEvent) => {\n\t\t\tif (e.target === fullContextModal) closeFullContextModal!();\n\t\t});\n\t}\n\treturn { debugModal, fullContextModal, closeDebugModal, closeFullContextModal };\n}\n\nfunction syncModelComboLabel(): void {\n\tif (!(S.models.length > 0 && S.modelComboLabel)) return;\n\tconst models = S.models as Array<{ id: string; displayName?: string }>;\n\tconst found = models.find((m) => m.id === S.selectedModelId);\n\tif (found) {\n\t\tS.modelComboLabel.textContent = found.displayName || found.id;\n\t\treturn;\n\t}\n\tif (models[0]) S.modelComboLabel.textContent = models[0].displayName || models[0].id;\n}\n\nfunction resolveInitialSessionKey(sessionKeyFromUrl: string | null): string {\n\tif (sessionKeyFromUrl) return sessionKeyFromUrl;\n\tconst sk = localStorage.getItem(\"moltis-session\") || \"main\";\n\thistory.replaceState(null, \"\", sessionPath(sk));\n\treturn sk;\n}\n\nfunction startInitialChatSession(sessionKey: string): void {\n\tif (!S.connected) return;\n\t(S.chatSendBtn as HTMLButtonElement).disabled = false;\n\tswitchSession(sessionKey);\n}\n\nfunction initializeChatMediaDrop(): void {\n\tif (window.innerWidth < 768) return;\n\tconst inputArea = S.chatInput?.closest(\".px-4.py-3\");\n\tinitMediaDrop(S.chatMsgBox!, inputArea as HTMLElement);\n}\n\nregisterPrefix(\n\troutes.chats!,\n\tfunction initChat(container: HTMLElement, sessionKeyFromUrl?: string | null) {\n\t\tcontainer.style.cssText = \"position:relative\";\n\t\t// Safe: chatPageHTML is a static hardcoded template with no user input.\n\t\t// This is a compile-time constant defined above -- no dynamic or user data.\n\t\tcontainer.innerHTML = chatPageHTML;\n\n\t\tS.setChatMsgBox(S.$(\"messages\"));\n\t\tS.setChatInput(S.$(\"chatInput\"));\n\t\tS.setChatSendBtn(S.$(\"sendBtn\"));\n\t\tupdateCommandInputUI();\n\t\tinitializeChatControls();\n\n\t\tlet closeChatMore: (() => void) | null = null;\n\t\tmountSessionHeaderControls(() => closeChatMore?.());\n\t\tbindSessionControlsVisibility();\n\n\t\tconst mcpToggle = S.$(\"mcpToggleBtn\");\n\t\tif (mcpToggle) mcpToggle.addEventListener(\"click\", toggleMcp);\n\t\tupdateMcpToggleUI(true);\n\n\t\tconst mb = bindContextModals();\n\t\tcloseChatMore = bindChatMoreModal(mb.debugModal, mb.fullContextModal, mb.closeDebugModal, mb.closeFullContextModal);\n\t\tbindDeleteAllSessions(closeChatMore);\n\n\t\tconst debugBtn = S.$(\"debugPanelBtn\");\n\t\tif (debugBtn) debugBtn.addEventListener(\"click\", toggleDebugPanel);\n\t\tS.$(\"fullContextBtn\")?.addEventListener(\"click\", toggleFullContextPanel);\n\n\t\tsyncModelComboLabel();\n\t\tconst sessionKey = resolveInitialSessionKey(sessionKeyFromUrl ?? null);\n\t\tstartInitialChatSession(sessionKey);\n\t\tbindChatComposer();\n\t\tS.chatMsgBox!.addEventListener(\"copy\", handleChatCopy);\n\t\tinitVoiceInput(S.$(\"micBtn\") as HTMLButtonElement | null);\n\t\tinitializeChatMediaDrop();\n\t\tS.chatInput!.focus();\n\t},\n\tfunction teardownChat() {\n\t\tteardownVoiceInput();\n\t\tteardownMediaDrop();\n\t\tunbindReasoningToggle();\n\t\tunbindNodeEvents();\n\t\tslashHideMenu();\n\t\tif (chatMoreModalKeydownHandler) {\n\t\t\tdocument.removeEventListener(\"keydown\", chatMoreModalKeydownHandler);\n\t\t\tchatMoreModalKeydownHandler = null;\n\t\t}\n\t\tdisposeSessionControlsVisibility?.();\n\t\tdisposeSessionControlsVisibility = null;\n\t\tconst m1 = S.$(\"sessionHeaderToolbarMount\");\n\t\tif (m1) render(null, m1);\n\t\tconst m2 = S.$(\"sessionHeaderModalMount\");\n\t\tif (m2) render(null, m2);\n\t\tconst m3 = S.$(\"sessionHeaderModalTopMount\");\n\t\tif (m3) render(null, m3);\n\t\tS.setChatMsgBox(null);\n\t\tS.setChatInput(null);\n\t\tS.setChatSendBtn(null);\n\t\tS.setStreamEl(null);\n\t\tS.setStreamText(\"\");\n\t\tS.setModelCombo(null);\n\t\tS.setModelComboBtn(null);\n\t\tS.setModelComboLabel(null);\n\t\tS.setModelDropdown(null);\n\t\tS.setModelSearchInput(null);\n\t\tS.setModelDropdownList(null);\n\t\tS.setNodeCombo(null);\n\t\tS.setNodeComboBtn(null);\n\t\tS.setNodeComboLabel(null);\n\t\tS.setNodeDropdown(null);\n\t\tS.setNodeDropdownList(null);\n\t\tS.setSandboxToggleBtn(null);\n\t\tS.setSandboxLabel(null);\n\t},\n);\n","// ── Model selector ──────────────────────────────────────────\n\nimport { sendRpc } from \"./helpers\";\nimport { t } from \"./i18n\";\nimport { showModelNotice } from \"./pages/ChatPage\";\nimport * as S from \"./state\";\nimport { modelStore, REASONING_SEP } from \"./stores/model-store\";\nimport type { ModelInfo } from \"./types\";\n\nfunction setSessionModel(sessionKey: string, modelId: string): void {\n\tsendRpc(\"sessions.patch\", { key: sessionKey, model: modelId });\n}\n\nexport { setSessionModel };\n\nfunction updateModelComboLabel(model: ModelInfo): void {\n\tif (S.modelComboLabel) S.modelComboLabel.textContent = model.displayName || model.id;\n}\n\nexport function fetchModels(): Promise<void> {\n\treturn modelStore.fetch().then(() => {\n\t\t// Dual-write to state.js for backward compat\n\t\tS.setModels(modelStore.models.value);\n\t\tS.setSelectedModelId(modelStore.selectedModelId.value);\n\t\tconst model = modelStore.selectedModel.value;\n\t\tif (model) updateModelComboLabel(model);\n\n\t\t// If the dropdown is currently open, re-render to reflect updated flags\n\t\t// (for example when a model becomes unsupported via a WS event).\n\t\tif (S.modelDropdown && !S.modelDropdown.classList.contains(\"hidden\")) {\n\t\t\tconst query = S.modelSearchInput ? (S.modelSearchInput as HTMLInputElement).value.trim() : \"\";\n\t\t\trenderModelList(query);\n\t\t}\n\t});\n}\n\nexport function selectModel(m: ModelInfo): void {\n\tmodelStore.select(m.id);\n\t// Dual-write to state.js for backward compat\n\tS.setSelectedModelId(m.id);\n\tupdateModelComboLabel(m);\n\tlocalStorage.setItem(\"moltis-model\", m.id);\n\tsetSessionModel(S.activeSessionKey, m.id);\n\tcloseModelDropdown();\n\t// Show notice if model doesn't support tools\n\tshowModelNotice(m);\n}\n\nexport function openModelDropdown(): void {\n\tif (!S.modelDropdown) return;\n\tS.modelDropdown.classList.remove(\"hidden\");\n\t(S.modelSearchInput as HTMLInputElement).value = \"\";\n\tS.setModelIdx(-1);\n\trenderModelList(\"\");\n\trequestAnimationFrame(() => {\n\t\tif (S.modelSearchInput) S.modelSearchInput.focus();\n\t});\n}\n\nexport function closeModelDropdown(): void {\n\tif (!S.modelDropdown) return;\n\tS.modelDropdown.classList.add(\"hidden\");\n\tif (S.modelSearchInput) (S.modelSearchInput as HTMLInputElement).value = \"\";\n\tS.setModelIdx(-1);\n}\n\nfunction buildModelItem(m: ModelInfo, currentId: string): HTMLDivElement {\n\tconst el = document.createElement(\"div\");\n\tel.className = \"model-dropdown-item\";\n\tif (m.id === currentId) el.classList.add(\"selected\");\n\tif (m.unsupported) el.classList.add(\"model-dropdown-item-unsupported\");\n\n\tconst label = document.createElement(\"span\");\n\tlabel.className = \"model-item-label\";\n\tlabel.textContent = m.displayName || m.id;\n\tel.appendChild(label);\n\n\tconst meta = document.createElement(\"span\");\n\tmeta.className = \"model-item-meta\";\n\n\tif (m.provider) {\n\t\tconst prov = document.createElement(\"span\");\n\t\tprov.className = \"model-item-provider\";\n\t\tprov.textContent = m.provider;\n\t\tmeta.appendChild(prov);\n\t}\n\n\tif (m.supportsReasoning) {\n\t\tconst brainIcon = document.createElement(\"span\");\n\t\tbrainIcon.className = \"icon icon-xs icon-brain\";\n\t\tbrainIcon.title = \"Supports reasoning\";\n\t\tbrainIcon.style.cssText = \"opacity:0.5;flex-shrink:0;\";\n\t\tmeta.appendChild(brainIcon);\n\t}\n\n\tif (m.unsupported) {\n\t\tconst badge = document.createElement(\"span\");\n\t\tbadge.className = \"model-item-unsupported\";\n\t\tbadge.textContent = t(\"common:labels.unsupported\");\n\t\tif (m.unsupportedReason) badge.title = m.unsupportedReason;\n\t\tmeta.appendChild(badge);\n\t}\n\n\tif (meta.childNodes.length > 0) el.appendChild(meta);\n\tel.addEventListener(\"click\", () => selectModel(m));\n\treturn el;\n}\n\nexport function renderModelList(query: string): void {\n\tif (!S.modelDropdownList) return;\n\tS.modelDropdownList.textContent = \"\";\n\tconst q = query.toLowerCase();\n\tconst allModels = modelStore.models.value;\n\tconst filtered = allModels.filter((m) => {\n\t\t// Hide @reasoning-* virtual variants — the reasoning toggle handles these.\n\t\tif (m.id.indexOf(REASONING_SEP) !== -1) return false;\n\t\tconst label = (m.displayName || m.id).toLowerCase();\n\t\tconst provider = (m.provider || \"\").toLowerCase();\n\t\treturn !q || label.indexOf(q) !== -1 || provider.indexOf(q) !== -1 || m.id.toLowerCase().indexOf(q) !== -1;\n\t});\n\tif (filtered.length === 0) {\n\t\tconst empty = document.createElement(\"div\");\n\t\tempty.className = \"model-dropdown-empty\";\n\t\tempty.textContent = t(\"common:labels.noMatchingModels\");\n\t\tS.modelDropdownList.appendChild(empty);\n\t\treturn;\n\t}\n\tconst currentId = modelStore.selectedModelId.value;\n\tlet lastPreferredIdx = -1;\n\tfor (let i = filtered.length - 1; i >= 0; i--) {\n\t\tif (filtered[i].preferred) {\n\t\t\tlastPreferredIdx = i;\n\t\t\tbreak;\n\t\t}\n\t}\n\tfiltered.forEach((m, idx) => {\n\t\tS.modelDropdownList!.appendChild(buildModelItem(m, currentId));\n\n\t\tif (idx === lastPreferredIdx && lastPreferredIdx < filtered.length - 1) {\n\t\t\tconst divider = document.createElement(\"div\");\n\t\t\tdivider.className = \"model-dropdown-divider\";\n\t\t\tS.modelDropdownList!.appendChild(divider);\n\t\t}\n\t});\n}\n\nfunction updateModelActive(): void {\n\tif (!S.modelDropdownList) return;\n\tconst items = S.modelDropdownList.querySelectorAll<HTMLElement>(\".model-dropdown-item\");\n\titems.forEach((el, i) => {\n\t\tel.classList.toggle(\"kb-active\", i === S.modelIdx);\n\t});\n\tif (S.modelIdx >= 0 && items[S.modelIdx]) {\n\t\titems[S.modelIdx].scrollIntoView({ block: \"nearest\" });\n\t}\n}\n\nexport function bindModelComboEvents(): void {\n\tif (!(S.modelComboBtn && S.modelSearchInput && S.modelDropdownList && S.modelCombo)) return;\n\n\tS.modelComboBtn.addEventListener(\"click\", () => {\n\t\tif (S.modelDropdown!.classList.contains(\"hidden\")) {\n\t\t\topenModelDropdown();\n\t\t} else {\n\t\t\tcloseModelDropdown();\n\t\t}\n\t});\n\n\tS.modelSearchInput.addEventListener(\"input\", () => {\n\t\tS.setModelIdx(-1);\n\t\trenderModelList((S.modelSearchInput as HTMLInputElement).value.trim());\n\t});\n\n\tS.modelSearchInput.addEventListener(\"keydown\", (e: Event) => {\n\t\tconst ke = e as KeyboardEvent;\n\t\tconst items = S.modelDropdownList!.querySelectorAll<HTMLElement>(\".model-dropdown-item\");\n\t\tif (ke.key === \"ArrowDown\") {\n\t\t\tke.preventDefault();\n\t\t\tS.setModelIdx(Math.min(S.modelIdx + 1, items.length - 1));\n\t\t\tupdateModelActive();\n\t\t} else if (ke.key === \"ArrowUp\") {\n\t\t\tke.preventDefault();\n\t\t\tS.setModelIdx(Math.max(S.modelIdx - 1, 0));\n\t\t\tupdateModelActive();\n\t\t} else if (ke.key === \"Enter\") {\n\t\t\tke.preventDefault();\n\t\t\tif (S.modelIdx >= 0 && items[S.modelIdx]) {\n\t\t\t\t(items[S.modelIdx] as HTMLElement).click();\n\t\t\t} else if (items.length === 1) {\n\t\t\t\t(items[0] as HTMLElement).click();\n\t\t\t}\n\t\t} else if (ke.key === \"Escape\") {\n\t\t\tcloseModelDropdown();\n\t\t\tS.modelComboBtn!.focus();\n\t\t}\n\t});\n}\n\ndocument.addEventListener(\"click\", (e: MouseEvent) => {\n\tif (S.modelCombo && !S.modelCombo.contains(e.target as Node)) {\n\t\tcloseModelDropdown();\n\t}\n});\n\nwindow.addEventListener(\"moltis:locale-changed\", () => {\n\tif (S.modelDropdown && !S.modelDropdown.classList.contains(\"hidden\")) {\n\t\tconst query = S.modelSearchInput ? (S.modelSearchInput as HTMLInputElement).value.trim() : \"\";\n\t\trenderModelList(query);\n\t}\n});\n","// ── Nav sidebar count badges ────────────────────────────────\n//\n// Renders small count pills next to sidebar nav items.\n// Populated from gon.counts at page load and updated live\n// by individual page modules after data refreshes.\n\nimport * as gon from \"./gon\";\n\nconst ids: Record<string, string> = {\n\tskills: \"navCountSkills\",\n\tcrons: \"navCountCrons\",\n};\n\n/** Update a single nav badge. Pass 0 to hide it. */\nexport function updateNavCount(key: string, n: number): void {\n\tconst id = ids[key];\n\tif (!id) return;\n\tconst el = document.getElementById(id);\n\tif (!el) return;\n\tif (n > 0) {\n\t\tel.textContent = String(n);\n\t\tel.classList.add(\"visible\");\n\t} else {\n\t\tel.textContent = \"\";\n\t\tel.classList.remove(\"visible\");\n\t}\n}\n\n/** Apply all counts from a counts object. */\nexport function updateNavCounts(counts: Record<string, number> | null): void {\n\tif (!counts) return;\n\tfor (const key of Object.keys(ids)) {\n\t\tupdateNavCount(key, counts[key] || 0);\n\t}\n}\n\n// Apply server-injected counts synchronously at module load.\nupdateNavCounts(gon.get(\"counts\") as Record<string, number> | null);\ngon.onChange(\"counts\", updateNavCounts as (value: unknown) => void);\n","// ── Projects (sidebar filter) ────────────────────────────────\n\nimport { t } from \"./i18n\";\nimport { updateNavCount } from \"./nav-counts\";\nimport { renderSessionProjectSelect } from \"./project-combo\";\nimport * as S from \"./state\";\nimport { projectStore } from \"./stores/project-store\";\nimport type { ProjectInfo } from \"./types\";\n\nconst combo = S.$(\"projectFilterCombo\") as HTMLElement;\nconst btn = S.$(\"projectFilterBtn\") as HTMLElement;\nconst label = S.$(\"projectFilterLabel\") as HTMLElement;\nconst dropdown = S.$(\"projectFilterDropdown\") as HTMLElement;\nconst list = S.$(\"projectFilterList\") as HTMLElement;\nconst searchInput = S.$(\"projectFilterSearch\") as HTMLInputElement | null;\nlet kbIdx = -1;\n\nexport function fetchProjects(): void {\n\tprojectStore.fetch().then(() => {\n\t\tconst projects = projectStore.projects.value;\n\t\t// Dual-write to state.js for backward compat\n\t\tS.setProjects(projects);\n\t\trenderProjectSelect();\n\t\trenderSessionProjectSelect();\n\t\tupdateNavCount(\"projects\", projects.length);\n\t});\n}\n\nfunction selectFilter(id: string): void {\n\tprojectStore.setFilterId(id);\n\t// Dual-write to state.js for backward compat\n\tS.setProjectFilterId(id);\n\tconst p = projectStore.getById(id);\n\tlabel.textContent = p ? (p as ProjectInfo & { label?: string }).label || p.id : t(\"common:sessions.allSessions\");\n\tcloseDropdown();\n\tdocument.dispatchEvent(new CustomEvent(\"moltis:render-session-list\"));\n}\n\nfunction closeDropdown(): void {\n\tdropdown.classList.add(\"hidden\");\n\tif (searchInput) searchInput.value = \"\";\n\tkbIdx = -1;\n}\n\nfunction openDropdown(): void {\n\tdropdown.classList.remove(\"hidden\");\n\tkbIdx = -1;\n\trenderList(\"\");\n\trequestAnimationFrame(() => {\n\t\tif (searchInput) searchInput.focus();\n\t});\n}\n\nfunction renderList(query: string): void {\n\tlist.textContent = \"\";\n\tconst q = (query || \"\").toLowerCase();\n\tconst filterId = projectStore.projectFilterId.value;\n\tconst allProjects = projectStore.projects.value;\n\n\t// \"All sessions\" option -- always shown unless query excludes it\n\tconst allSessionsLabel = t(\"common:sessions.allSessions\");\n\tif (!q || allSessionsLabel.toLowerCase().indexOf(q) !== -1) {\n\t\tconst allEl = document.createElement(\"div\");\n\t\tallEl.className = \"model-dropdown-item\";\n\t\tif (!filterId) allEl.classList.add(\"selected\");\n\t\tconst allLabel = document.createElement(\"span\");\n\t\tallLabel.className = \"model-item-label\";\n\t\tallLabel.textContent = allSessionsLabel;\n\t\tallEl.appendChild(allLabel);\n\t\tallEl.addEventListener(\"click\", () => selectFilter(\"\"));\n\t\tlist.appendChild(allEl);\n\t}\n\n\tconst filtered = allProjects.filter((p) => {\n\t\tif (!q) return true;\n\t\tconst name = ((p as ProjectInfo & { label?: string }).label || p.id).toLowerCase();\n\t\treturn name.indexOf(q) !== -1 || p.id.toLowerCase().indexOf(q) !== -1;\n\t});\n\n\tfiltered.forEach((p) => {\n\t\tconst el = document.createElement(\"div\");\n\t\tel.className = \"model-dropdown-item\";\n\t\tif (p.id === filterId) el.classList.add(\"selected\");\n\t\tconst itemLabel = document.createElement(\"span\");\n\t\titemLabel.className = \"model-item-label\";\n\t\titemLabel.textContent = (p as ProjectInfo & { label?: string }).label || p.id;\n\t\tel.appendChild(itemLabel);\n\t\tel.addEventListener(\"click\", () => selectFilter(p.id));\n\t\tlist.appendChild(el);\n\t});\n\n\tif (list.children.length === 0) {\n\t\tconst empty = document.createElement(\"div\");\n\t\tempty.className = \"model-dropdown-empty\";\n\t\tempty.textContent = t(\"common:sessions.noMatchingProjects\");\n\t\tlist.appendChild(empty);\n\t}\n}\n\nfunction updateKbActive(): void {\n\tconst items = list.querySelectorAll<HTMLElement>(\".model-dropdown-item\");\n\titems.forEach((el, i) => {\n\t\tel.classList.toggle(\"kb-active\", i === kbIdx);\n\t});\n\tif (kbIdx >= 0 && items[kbIdx]) {\n\t\titems[kbIdx].scrollIntoView({ block: \"nearest\" });\n\t}\n}\n\nexport function renderProjectSelect(): void {\n\tconst wrapper = S.$(\"projectSelectWrapper\");\n\tconst allProjects = projectStore.projects.value;\n\tconst filterId = projectStore.projectFilterId.value;\n\tif (allProjects.length === 0) {\n\t\tif (wrapper) wrapper.classList.add(\"hidden\");\n\t\tif (filterId) {\n\t\t\tprojectStore.setFilterId(\"\");\n\t\t\tS.setProjectFilterId(\"\");\n\t\t}\n\t\tlabel.textContent = t(\"common:sessions.allSessions\");\n\t\treturn;\n\t}\n\tif (wrapper) wrapper.classList.remove(\"hidden\");\n\n\tconst p = projectStore.getById(filterId);\n\tlabel.textContent = p ? (p as ProjectInfo & { label?: string }).label || p.id : t(\"common:sessions.allSessions\");\n}\n\nbtn.addEventListener(\"click\", () => {\n\tif (dropdown.classList.contains(\"hidden\")) {\n\t\topenDropdown();\n\t} else {\n\t\tcloseDropdown();\n\t}\n});\n\nif (searchInput) {\n\tsearchInput.addEventListener(\"input\", () => {\n\t\tkbIdx = -1;\n\t\trenderList(searchInput.value.trim());\n\t});\n\n\tsearchInput.addEventListener(\"keydown\", (e: KeyboardEvent) => {\n\t\tconst items = list.querySelectorAll<HTMLElement>(\".model-dropdown-item\");\n\t\tif (e.key === \"ArrowDown\") {\n\t\t\te.preventDefault();\n\t\t\tkbIdx = Math.min(kbIdx + 1, items.length - 1);\n\t\t\tupdateKbActive();\n\t\t} else if (e.key === \"ArrowUp\") {\n\t\t\te.preventDefault();\n\t\t\tkbIdx = Math.max(kbIdx - 1, 0);\n\t\t\tupdateKbActive();\n\t\t} else if (e.key === \"Enter\") {\n\t\t\te.preventDefault();\n\t\t\tif (kbIdx >= 0 && items[kbIdx]) {\n\t\t\t\t(items[kbIdx] as HTMLElement).click();\n\t\t\t} else if (items.length === 1) {\n\t\t\t\t(items[0] as HTMLElement).click();\n\t\t\t}\n\t\t} else if (e.key === \"Escape\") {\n\t\t\tcloseDropdown();\n\t\t\tbtn.focus();\n\t\t}\n\t});\n}\n\ndocument.addEventListener(\"click\", (e: MouseEvent) => {\n\tif (combo && !combo.contains(e.target as Node)) {\n\t\tcloseDropdown();\n\t}\n});\n\nwindow.addEventListener(\"moltis:locale-changed\", () => {\n\trenderProjectSelect();\n\tif (!dropdown.classList.contains(\"hidden\")) {\n\t\tconst query = searchInput ? searchInput.value.trim() : \"\";\n\t\trenderList(query);\n\t}\n});\n","// PWA utilities - service worker registration and install prompt handling\n\n/** Extended Navigator interface for iOS standalone detection. */\ninterface NavigatorStandalone extends Navigator {\n\tstandalone?: boolean;\n}\n\n/** The beforeinstallprompt event fired by Chrome/Edge. */\ninterface BeforeInstallPromptEvent extends Event {\n\tprompt(): Promise<void>;\n\tuserChoice: Promise<{ outcome: \"accepted\" | \"dismissed\" }>;\n}\n\nlet deferredInstallPrompt: BeforeInstallPromptEvent | null = null;\nlet swRegistration: ServiceWorkerRegistration | null = null;\n\n// Check if running in standalone mode (installed PWA)\nexport function isStandalone(): boolean {\n\treturn (\n\t\twindow.matchMedia(\"(display-mode: standalone)\").matches ||\n\t\t(navigator as NavigatorStandalone).standalone === true ||\n\t\tdocument.referrer.includes(\"android-app://\")\n\t);\n}\n\n// Check if iOS device\nexport function isIOS(): boolean {\n\treturn /iPhone|iPad|iPod/.test(navigator.userAgent);\n}\n\n// Check if Android device\nexport function isAndroid(): boolean {\n\treturn /Android/.test(navigator.userAgent);\n}\n\nexport function syncStandaloneClass(): void {\n\tdocument.documentElement.classList.toggle(\"pwa-standalone\", isStandalone());\n}\n\n// Register service worker\nexport async function registerServiceWorker(): Promise<ServiceWorkerRegistration | null> {\n\tif (!(\"serviceWorker\" in navigator)) {\n\t\tconsole.log(\"Service workers not supported\");\n\t\treturn null;\n\t}\n\n\ttry {\n\t\tswRegistration = await navigator.serviceWorker.register(\"/sw.js\", {\n\t\t\tscope: \"/\",\n\t\t});\n\t\tconsole.log(\"Service worker registered:\", swRegistration.scope);\n\n\t\t// Handle updates\n\t\tswRegistration.addEventListener(\"updatefound\", () => {\n\t\t\tconst newWorker = swRegistration!.installing;\n\t\t\tif (newWorker) {\n\t\t\t\tnewWorker.addEventListener(\"statechange\", () => {\n\t\t\t\t\tif (newWorker.state === \"installed\" && navigator.serviceWorker.controller) {\n\t\t\t\t\t\t// New content is available, notify user\n\t\t\t\t\t\tdispatchUpdateAvailable();\n\t\t\t\t\t}\n\t\t\t\t});\n\t\t\t}\n\t\t});\n\n\t\treturn swRegistration;\n\t} catch (error) {\n\t\tconsole.error(\"Service worker registration failed:\", error);\n\t\treturn null;\n\t}\n}\n\n// Dispatch custom event when update is available\nfunction dispatchUpdateAvailable(): void {\n\twindow.dispatchEvent(new CustomEvent(\"sw-update-available\"));\n}\n\n// Skip waiting and activate new service worker\nexport function activateUpdate(): void {\n\tif (swRegistration?.waiting) {\n\t\tswRegistration.waiting.postMessage({ type: \"SKIP_WAITING\" });\n\t}\n}\n\n// Listen for beforeinstallprompt event (Android Chrome)\nexport function setupInstallPrompt(callback?: (e: BeforeInstallPromptEvent) => void): void {\n\twindow.addEventListener(\"beforeinstallprompt\", ((e: Event) => {\n\t\te.preventDefault();\n\t\tdeferredInstallPrompt = e as BeforeInstallPromptEvent;\n\t\tif (callback) callback(e as BeforeInstallPromptEvent);\n\t}) as EventListener);\n\n\t// Also listen for successful install\n\twindow.addEventListener(\"appinstalled\", () => {\n\t\tdeferredInstallPrompt = null;\n\t\tconsole.log(\"PWA installed\");\n\t});\n}\n\n// Trigger the install prompt (Android Chrome)\nexport async function promptInstall(): Promise<{ outcome: string }> {\n\tif (!deferredInstallPrompt) {\n\t\treturn { outcome: \"not-available\" };\n\t}\n\n\tdeferredInstallPrompt.prompt();\n\tconst result = await deferredInstallPrompt.userChoice;\n\tdeferredInstallPrompt = null;\n\treturn result;\n}\n\n// Check if install prompt is available\nexport function canPromptInstall(): boolean {\n\treturn deferredInstallPrompt !== null;\n}\n\n// Listen for notification clicks from service worker\nexport function setupNotificationHandler(callback?: (url: string) => void): void {\n\tnavigator.serviceWorker?.addEventListener(\"message\", (event: MessageEvent) => {\n\t\tif (event.data && event.data.type === \"notification-click\" && callback) callback(event.data.url);\n\t});\n}\n\n// Request notification permission\nexport async function requestNotificationPermission(): Promise<NotificationPermission> {\n\tif (!(\"Notification\" in window)) {\n\t\treturn \"denied\";\n\t}\n\n\tif (Notification.permission === \"granted\") {\n\t\treturn \"granted\";\n\t}\n\n\tif (Notification.permission === \"denied\") {\n\t\treturn \"denied\";\n\t}\n\n\treturn await Notification.requestPermission();\n}\n\n// Get current notification permission\nexport function getNotificationPermission(): NotificationPermission {\n\tif (!(\"Notification\" in window)) {\n\t\treturn \"denied\";\n\t}\n\treturn Notification.permission;\n}\n\n// Initialize PWA features\nexport function initPWA(): void {\n\tsyncStandaloneClass();\n\tconst hadControllerBeforeInit = Boolean(navigator.serviceWorker?.controller);\n\n\t// Register service worker\n\tregisterServiceWorker();\n\n\t// Handle notification clicks (navigate to URL)\n\tsetupNotificationHandler((url: string) => {\n\t\tif (url && url !== window.location.pathname) {\n\t\t\twindow.location.href = url;\n\t\t}\n\t});\n\n\t// Listen for controller change (new SW activated)\n\tnavigator.serviceWorker?.addEventListener(\"controllerchange\", () => {\n\t\t// First service worker install should not force a reload.\n\t\tif (!hadControllerBeforeInit) {\n\t\t\treturn;\n\t\t}\n\t\t// Avoid forced reload churn on onboarding; the app boot path will\n\t\t// fetch fresh assets on the next navigation to the main UI.\n\t\tif (window.location.pathname === \"/onboarding\") {\n\t\t\treturn;\n\t\t}\n\t\twindow.location.reload();\n\t});\n}\n","// PWA Install Banner - handles \"Add to Homescreen\" prompts\n\nimport { t } from \"./i18n\";\nimport { canPromptInstall, isAndroid, isIOS, isStandalone, promptInstall, setupInstallPrompt } from \"./pwa\";\n\nconst DISMISS_KEY = \"pwa-install-dismissed\";\nconst DISMISS_DAYS = 7;\n\n// Check if user dismissed the banner recently\nfunction isDismissed(): boolean {\n\tconst dismissed = localStorage.getItem(DISMISS_KEY);\n\tif (!dismissed) return false;\n\tconst ts = parseInt(dismissed, 10);\n\tconst days = (Date.now() - ts) / (1000 * 60 * 60 * 24);\n\treturn days < DISMISS_DAYS;\n}\n\n// Mark banner as dismissed\nfunction dismiss(): void {\n\tlocalStorage.setItem(DISMISS_KEY, Date.now().toString());\n\thideBanner();\n}\n\n// Get the banner element\nfunction getBanner(): HTMLElement | null {\n\treturn document.getElementById(\"installBanner\");\n}\n\n// Show the install banner\nfunction showBanner(): void {\n\tconst banner = getBanner();\n\tif (banner) {\n\t\tbanner.classList.remove(\"hidden\");\n\t\tbanner.classList.add(\"flex\");\n\t}\n}\n\n// Hide the install banner\nfunction hideBanner(): void {\n\tconst banner = getBanner();\n\tif (banner) {\n\t\tbanner.classList.add(\"hidden\");\n\t\tbanner.classList.remove(\"flex\");\n\t}\n}\n\n// Check if running in Safari on iOS\nfunction isIOSSafari(): boolean {\n\tconst ua = navigator.userAgent;\n\treturn isIOS() && /Safari/.test(ua) && !/CriOS|FxiOS|OPiOS|EdgiOS/.test(ua);\n}\n\n// Create share icon element\nfunction createShareIcon(): HTMLSpanElement {\n\tconst el = document.createElement(\"span\");\n\tel.className = \"icon icon-share inline-block text-[var(--accent)]\";\n\treturn el;\n}\n\n// Create menu icon element\nfunction createMenuIcon(): HTMLSpanElement {\n\tconst el = document.createElement(\"span\");\n\tel.className = \"icon icon-menu-dots inline-block text-[var(--accent)]\";\n\treturn el;\n}\n\n// Render iOS-specific instructions\nfunction renderIOSInstructions(container: HTMLElement): void {\n\twhile (container.firstChild) container.removeChild(container.firstChild);\n\n\tconst title = document.createElement(\"p\");\n\ttitle.className = \"text-sm font-medium text-[var(--text-strong)] mb-2\";\n\ttitle.textContent = t(\"pwa:install.title\");\n\tcontainer.appendChild(title);\n\n\tconst steps = document.createElement(\"ol\");\n\tsteps.className = \"text-xs text-[var(--text)] space-y-1.5 list-decimal list-inside\";\n\n\tconst step1 = document.createElement(\"li\");\n\tstep1.className = \"flex items-center gap-1.5\";\n\tstep1.appendChild(document.createTextNode(t(\"pwa:ios.step1\")));\n\tconst strong1 = document.createElement(\"strong\");\n\tstrong1.textContent = t(\"pwa:ios.step1Button\");\n\tstep1.appendChild(strong1);\n\tstep1.appendChild(document.createTextNode(t(\"pwa:ios.step1After\")));\n\tstep1.appendChild(createShareIcon());\n\tsteps.appendChild(step1);\n\n\tconst step2 = document.createElement(\"li\");\n\tstep2.textContent = t(\"pwa:ios.step2\");\n\tsteps.appendChild(step2);\n\n\tcontainer.appendChild(steps);\n\n\tif (!isIOSSafari()) {\n\t\tconst note = document.createElement(\"p\");\n\t\tnote.className = \"text-xs text-[var(--muted)] mt-2\";\n\t\tnote.textContent = t(\"pwa:ios.safariTip\");\n\t\tcontainer.appendChild(note);\n\t}\n}\n\n// Render Android-specific instructions (for non-Chrome browsers)\nfunction renderAndroidInstructions(container: HTMLElement): void {\n\twhile (container.firstChild) container.removeChild(container.firstChild);\n\n\tconst title = document.createElement(\"p\");\n\ttitle.className = \"text-sm font-medium text-[var(--text-strong)] mb-2\";\n\ttitle.textContent = t(\"pwa:install.title\");\n\tcontainer.appendChild(title);\n\n\tconst steps = document.createElement(\"ol\");\n\tsteps.className = \"text-xs text-[var(--text)] space-y-1.5 list-decimal list-inside\";\n\n\tconst step1 = document.createElement(\"li\");\n\tstep1.className = \"flex items-center gap-1.5\";\n\tstep1.appendChild(document.createTextNode(t(\"pwa:android.step1\")));\n\tstep1.appendChild(createMenuIcon());\n\tsteps.appendChild(step1);\n\n\tconst step2 = document.createElement(\"li\");\n\tstep2.textContent = t(\"pwa:android.step2\");\n\tsteps.appendChild(step2);\n\n\tcontainer.appendChild(steps);\n}\n\n// Render native install prompt (Android Chrome)\nfunction renderNativePrompt(container: HTMLElement): void {\n\twhile (container.firstChild) container.removeChild(container.firstChild);\n\n\tconst title = document.createElement(\"p\");\n\ttitle.className = \"text-sm font-medium text-[var(--text-strong)]\";\n\ttitle.textContent = t(\"pwa:install.quickAccessTitle\");\n\tcontainer.appendChild(title);\n\n\tconst desc = document.createElement(\"p\");\n\tdesc.className = \"text-xs text-[var(--muted)] mt-1\";\n\tdesc.textContent = t(\"pwa:install.quickAccessDesc\");\n\tcontainer.appendChild(desc);\n}\n\n// Handle install button click\nasync function handleInstall(): Promise<void> {\n\tconst result = await promptInstall();\n\tif (result.outcome === \"accepted\") {\n\t\thideBanner();\n\t}\n}\n\n// Initialize the install banner\nexport function initInstallBanner(): void {\n\t// Don't show if already installed or dismissed\n\tif (isStandalone() || isDismissed()) {\n\t\treturn;\n\t}\n\n\tconst banner = getBanner();\n\tif (!banner) return;\n\n\tconst instructions = banner.querySelector(\"[data-instructions]\") as HTMLElement | null;\n\tconst installBtn = banner.querySelector(\"[data-install-btn]\") as HTMLElement | null;\n\tconst dismissBtn = banner.querySelector(\"[data-dismiss-btn]\") as HTMLElement | null;\n\n\tif (!instructions) return;\n\n\t// Set up dismiss button\n\tif (dismissBtn) {\n\t\tdismissBtn.addEventListener(\"click\", dismiss);\n\t}\n\n\t// Platform-specific setup\n\tif (isIOS()) {\n\t\trenderIOSInstructions(instructions);\n\t\tif (installBtn) installBtn.style.display = \"none\";\n\t\tshowBanner();\n\t} else if (isAndroid()) {\n\t\t// Try to use native prompt first\n\t\tsetupInstallPrompt(() => {\n\t\t\trenderNativePrompt(instructions);\n\t\t\tif (installBtn) {\n\t\t\t\tinstallBtn.style.display = \"\";\n\t\t\t\tinstallBtn.addEventListener(\"click\", handleInstall);\n\t\t\t}\n\t\t\tshowBanner();\n\t\t});\n\n\t\t// If no native prompt after a delay, show manual instructions\n\t\tsetTimeout(() => {\n\t\t\tif (!(canPromptInstall() || isStandalone())) {\n\t\t\t\trenderAndroidInstructions(instructions);\n\t\t\t\tif (installBtn) installBtn.style.display = \"none\";\n\t\t\t\tshowBanner();\n\t\t\t}\n\t\t}, 3000);\n\t}\n}\n","// ── Shared channel RPC wrappers and validation ────────────────\n//\n// Used by page-channels.js and onboarding-view.js.\n\nimport { get as getGon } from \"./gon\";\nimport { sendRpc } from \"./helpers\";\n\nexport const MATRIX_DOCS_URL = \"https://docs.moltis.org/matrix.html\";\nexport const MATRIX_DEFAULT_HOMESERVER = \"https://matrix.org\";\nexport const MATRIX_ENCRYPTION_GUIDANCE =\n\t\"Encrypted Matrix chats require Password auth. Access token auth can connect for plain Matrix traffic, but it reuses an existing Matrix session without that device's private encryption keys, so Moltis cannot reliably decrypt encrypted chats. Use Password so Moltis creates and persists its own Matrix device keys, then finish Element verification in the same Matrix DM or room by sending `verify yes`, `verify no`, `verify show`, or `verify cancel` as normal chat messages.\";\n\nexport function matrixAuthModeGuidance(authMode: string | undefined): string {\n\treturn normalizeMatrixAuthMode(authMode) === \"password\"\n\t\t? \"Required for encrypted Matrix chats. Moltis logs in as its own Matrix device and stores the device's encryption keys locally.\"\n\t\t: \"Does not support encrypted Matrix chats. Access tokens authenticate an existing Matrix session, but they do not transfer that device's private encryption keys into Moltis.\";\n}\n\nexport function channelStorageNote(): string {\n\tconst dbPath = String(getGon(\"channel_storage_db_path\") || \"\").trim();\n\tif (dbPath) {\n\t\treturn `Channels added or edited in the web UI are stored in Moltis's internal database (${dbPath}). They are not written back to moltis.toml. The channel picker itself comes from [channels].offered in moltis.toml, so reload this page after editing that list.`;\n\t}\n\treturn \"Channels added or edited in the web UI are stored in Moltis's internal database (moltis.db). They are not written back to moltis.toml. The channel picker itself comes from [channels].offered in moltis.toml, so reload this page after editing that list.\";\n}\n\ninterface ValidationSuccess {\n\tvalid: true;\n}\n\ninterface ValidationFailure {\n\tvalid: false;\n\terror: string;\n}\n\ntype ValidationResult = ValidationSuccess | ValidationFailure;\n\ninterface ValidateChannelOptions {\n\tmatrixAuthMode?: string;\n\tmatrixUserId?: string;\n}\n\n/**\n * Validate required channel fields before submission.\n */\nexport function validateChannelFields(\n\ttype: string,\n\taccountId: string,\n\tcredential: string,\n\toptions: ValidateChannelOptions = {},\n): ValidationResult {\n\tif (!accountId.trim()) {\n\t\treturn { valid: false, error: \"Account ID is required.\" };\n\t}\n\tif (!credential.trim()) {\n\t\tif (type === \"matrix\") {\n\t\t\treturn { valid: false, error: matrixCredentialError(options.matrixAuthMode) };\n\t\t}\n\t\treturn {\n\t\t\tvalid: false,\n\t\t\terror: type === \"msteams\" ? \"App password is required.\" : \"Bot token is required.\",\n\t\t};\n\t}\n\tif (\n\t\ttype === \"matrix\" &&\n\t\tnormalizeMatrixAuthMode(options.matrixAuthMode) === \"password\" &&\n\t\t!String(options.matrixUserId || \"\").trim()\n\t) {\n\t\treturn { valid: false, error: \"Matrix user ID is required for password login.\" };\n\t}\n\treturn { valid: true };\n}\n\nexport function normalizeMatrixAuthMode(authMode: string | undefined): string {\n\treturn authMode === \"password\" ? \"password\" : \"access_token\";\n}\n\nexport function normalizeMatrixOwnershipMode(mode: string | undefined): string {\n\treturn mode === \"moltis_owned\" ? \"moltis_owned\" : \"user_managed\";\n}\n\nexport function matrixOwnershipModeGuidance(authMode: string | undefined, ownershipMode: string | undefined): string {\n\tif (normalizeMatrixAuthMode(authMode) !== \"password\") {\n\t\treturn \"Access token auth always stays user-managed because it reuses an existing Matrix session instead of giving Moltis full control of the account's encryption state.\";\n\t}\n\treturn normalizeMatrixOwnershipMode(ownershipMode) === \"moltis_owned\"\n\t\t? \"Recommended for dedicated bot accounts. Moltis bootstraps cross-signing and recovery for this account so it can verify its own Matrix device automatically.\"\n\t\t: \"Use this if you want to open the same bot account in Element or another Matrix client yourself. Moltis will not try to take over the account's cross-signing or recovery state.\";\n}\n\nexport function matrixCredentialLabel(authMode: string | undefined): string {\n\treturn normalizeMatrixAuthMode(authMode) === \"password\" ? \"Password\" : \"Access Token\";\n}\n\nexport function matrixCredentialPlaceholder(authMode: string | undefined): string {\n\treturn normalizeMatrixAuthMode(authMode) === \"password\" ? \"Account password\" : \"syt_...\";\n}\n\nexport function matrixCredentialError(authMode: string | undefined): string {\n\treturn normalizeMatrixAuthMode(authMode) === \"password\" ? \"Password is required.\" : \"Access token is required.\";\n}\n\nfunction randomSuffix(length: number): string {\n\tif (typeof window !== \"undefined\" && window.crypto?.getRandomValues) {\n\t\tconst bytes = new Uint8Array(length);\n\t\twindow.crypto.getRandomValues(bytes);\n\t\treturn Array.from(bytes, (byte) => (byte % 36).toString(36)).join(\"\");\n\t}\n\tlet value = \"\";\n\twhile (value.length < length) {\n\t\tvalue += Math.floor(Math.random() * 36).toString(36);\n\t}\n\treturn value.slice(0, length);\n}\n\nfunction slugifyMatrixAccountPart(value: string | undefined): string {\n\treturn String(value || \"\")\n\t\t.toLowerCase()\n\t\t.trim()\n\t\t.replace(/^@/, \"\")\n\t\t.replace(/[^a-z0-9]+/g, \"-\")\n\t\t.replace(/-+/g, \"-\")\n\t\t.replace(/^-|-$/g, \"\");\n}\n\nfunction matrixHomeserverHost(homeserver: string | undefined): string {\n\tlet raw = String(homeserver || \"\").trim();\n\tif (!raw) return \"\";\n\tif (!/^https?:\\/\\//i.test(raw)) raw = `https://${raw}`;\n\ttry {\n\t\treturn new URL(raw).hostname;\n\t} catch (_error) {\n\t\treturn \"\";\n\t}\n}\n\ninterface DeriveMatrixAccountIdOptions {\n\tuserId?: string;\n\thomeserver?: string;\n}\n\n/**\n * Generate a local Matrix account identifier for Moltis.\n * Prefer the Matrix user ID when present, otherwise derive from homeserver.\n */\nexport function deriveMatrixAccountId(options: DeriveMatrixAccountIdOptions = {}): string {\n\tconst userSlug = slugifyMatrixAccountPart(options.userId);\n\tif (userSlug) return userSlug.slice(0, 80);\n\n\tconst hostSlug = slugifyMatrixAccountPart(matrixHomeserverHost(options.homeserver));\n\tconst base = hostSlug || \"matrix\";\n\treturn `${base}-${randomSuffix(6)}`.slice(0, 80);\n}\n\n/**\n * Normalize Matrix OTP cooldown input to a positive integer.\n */\nexport function normalizeMatrixOtpCooldown(value: string | number | null | undefined, fallback: number = 300): number {\n\tconst parsed = Number.parseInt(String(value || \"\"), 10);\n\treturn Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;\n}\n\ninterface ParseOk {\n\tok: true;\n\tvalue: Record<string, unknown>;\n}\n\ninterface ParseError {\n\tok: false;\n\terror: string;\n}\n\ntype ParseResult = ParseOk | ParseError;\n\n/**\n * Parse an optional advanced channel config JSON object.\n */\nexport function parseChannelConfigPatch(text: string | null | undefined): ParseResult {\n\tconst raw = String(text || \"\").trim();\n\tif (!raw) return { ok: true, value: {} };\n\ttry {\n\t\tconst value: unknown = JSON.parse(raw);\n\t\tif (!(value && typeof value === \"object\" && !Array.isArray(value))) {\n\t\t\treturn { ok: false, error: \"Advanced config must be a JSON object.\" };\n\t\t}\n\t\treturn { ok: true, value: value as Record<string, unknown> };\n\t} catch (error) {\n\t\tconst message = error instanceof Error ? error.message : String(error || \"unknown error\");\n\t\treturn { ok: false, error: `Advanced config JSON is invalid: ${message}` };\n\t}\n}\n\n/**\n * Add a new channel (e.g. Telegram bot).\n */\nexport function addChannel(type: string, accountId: string, config: Record<string, unknown>): Promise<unknown> {\n\treturn sendRpc(\"channels.add\", { type, account_id: accountId, config });\n}\n\n/**\n * Fetch the current status of all configured channels.\n * Resolves with the RPC response; payload has `{ channels: [] }`.\n */\nexport function fetchChannelStatus(): Promise<unknown> {\n\treturn sendRpc(\"channels.status\", {});\n}\n\n/**\n * Default base URL for Teams webhook endpoints.\n * Prefer a discovered public URL when available, otherwise fall back to the\n * current page origin.\n */\nexport function defaultTeamsBaseUrl(preferredPublicUrl?: string): string {\n\tconst preferred = (preferredPublicUrl || \"\").trim();\n\tif (preferred) return preferred;\n\tif (typeof window === \"undefined\") return \"\";\n\treturn window.location?.origin || \"\";\n}\n\n/**\n * Normalise a user-provided base URL into `protocol://host`.\n */\nexport function normalizeBaseUrlForWebhook(baseUrl: string | undefined): string {\n\tlet raw = (baseUrl || \"\").trim();\n\tif (!raw) raw = defaultTeamsBaseUrl();\n\tif (!raw) return \"\";\n\tif (!/^https?:\\/\\//i.test(raw)) raw = `https://${raw}`;\n\ttry {\n\t\tconst parsed = new URL(raw);\n\t\treturn `${parsed.protocol}//${parsed.host}`;\n\t} catch (_e) {\n\t\treturn \"\";\n\t}\n}\n\n/**\n * Generate a random 48-hex-char webhook secret.\n */\nexport function generateWebhookSecretHex(): string {\n\tif (typeof window !== \"undefined\" && window.crypto?.getRandomValues) {\n\t\tconst bytes = new Uint8Array(24);\n\t\twindow.crypto.getRandomValues(bytes);\n\t\treturn Array.from(bytes, (b) => b.toString(16).padStart(2, \"0\")).join(\"\");\n\t}\n\tlet value = \"\";\n\twhile (value.length < 48) {\n\t\tvalue += Math.floor(Math.random() * 16).toString(16);\n\t}\n\treturn value.slice(0, 48);\n}\n\n/**\n * Build the full Teams messaging endpoint URL.\n */\nexport function buildTeamsEndpoint(\n\tbaseUrl: string | undefined,\n\taccountId: string | undefined,\n\twebhookSecret: string | undefined,\n): string {\n\tconst normalizedBase = normalizeBaseUrlForWebhook(baseUrl);\n\tconst account = (accountId || \"\").trim();\n\tconst secret = (webhookSecret || \"\").trim();\n\tif (!(normalizedBase && account && secret)) return \"\";\n\treturn `${normalizedBase}/api/channels/msteams/${encodeURIComponent(account)}/webhook?secret=${encodeURIComponent(secret)}`;\n}\n","// ── Channels page (Preact + Signals) ──────────────────────────\n\nimport type { Signal } from \"@preact/signals\";\nimport { signal, useSignal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect, useRef, useState } from \"preact/hooks\";\nimport {\n\taddChannel,\n\tbuildTeamsEndpoint,\n\tchannelStorageNote,\n\tdefaultTeamsBaseUrl,\n\tderiveMatrixAccountId,\n\tfetchChannelStatus,\n\tgenerateWebhookSecretHex,\n\tMATRIX_DEFAULT_HOMESERVER,\n\tMATRIX_DOCS_URL,\n\tMATRIX_ENCRYPTION_GUIDANCE,\n\tmatrixAuthModeGuidance,\n\tmatrixCredentialLabel,\n\tmatrixCredentialPlaceholder,\n\tmatrixOwnershipModeGuidance,\n\tnormalizeMatrixAuthMode,\n\tnormalizeMatrixOtpCooldown,\n\tnormalizeMatrixOwnershipMode,\n\tparseChannelConfigPatch,\n\tvalidateChannelFields,\n} from \"../channel-utils\";\nimport { onEvent } from \"../events\";\nimport { get as getGon } from \"../gon\";\nimport { sendRpc } from \"../helpers\";\nimport { updateNavCount } from \"../nav-counts\";\nimport { connected } from \"../signals\";\nimport * as S from \"../state\";\nimport { models as modelsSig } from \"../stores/model-store\";\nimport { ConfirmDialog, Modal, ModelSelect, requestConfirm, showToast } from \"../ui\";\n\n// ── Types ────────────────────────────────────────────────────\n\ninterface ChannelSession {\n\tkey: string;\n\tlabel?: string;\n\tactive?: boolean;\n\tmessageCount?: number;\n}\n\ninterface MatrixVerificationPrompt {\n\tother_user_id: string;\n}\n\ninterface MatrixStatus {\n\tuser_id?: string;\n\tdevice_id?: string;\n\tdevice_display_name?: string;\n\townership_mode?: string;\n\tauth_mode?: string;\n\trecovery_state?: string;\n\tdevice_verified_by_owner?: boolean;\n\townership_error?: string;\n\tcross_signing_complete?: boolean;\n\tverification_state?: string;\n\tpending_verifications?: MatrixVerificationPrompt[];\n}\n\ninterface ChannelExtra {\n\tmatrix?: MatrixStatus;\n\tqr_data?: string;\n\tqr_svg?: string;\n}\n\ninterface Channel {\n\ttype: string;\n\taccount_id: string;\n\tname?: string;\n\tdetails?: string;\n\tstatus?: string;\n\tconfig?: Record<string, unknown>;\n\tsessions?: ChannelSession[];\n\textra?: ChannelExtra;\n}\n\ninterface ChannelDescriptor {\n\tchannel_type: string;\n\tcapabilities: {\n\t\tinbound_mode: string;\n\t};\n}\n\ninterface TailscaleStatus {\n\tmode?: string;\n\turl?: string;\n\tinstalled?: boolean;\n\ttailscale_up?: boolean;\n}\n\ninterface SenderEntry {\n\tpeer_id: string;\n\tsender_name?: string;\n\tusername?: string;\n\tmessage_count: number;\n\tlast_seen?: number;\n\tallowed?: boolean;\n\totp_pending?: { code: string };\n}\n\ninterface ChannelEvent {\n\tkind: string;\n\taccount_id?: string;\n\tchannel_type?: string;\n\tqr_data?: string;\n\tqr_svg?: string;\n\treason?: string;\n}\n\n// ── Module-level signals ─────────────────────────────────────\n\nconst channels: Signal<Channel[]> = signal([]);\n\nexport function prefetchChannels(): Promise<void> {\n\treturn fetchChannelStatus().then((res: unknown) => {\n\t\tconst r = res as { ok?: boolean; payload?: { channels?: Channel[] } } | undefined;\n\t\tif (r?.ok) {\n\t\t\tconst ch = r.payload?.channels || [];\n\t\t\tchannels.value = ch;\n\t\t\tS.setCachedChannels(ch);\n\t\t}\n\t});\n}\n\nconst senders: Signal<SenderEntry[]> = signal([]);\nconst activeTab: Signal<string> = signal(\"channels\");\nconst showAddTelegram: Signal<boolean> = signal(false);\nconst showAddTeams: Signal<boolean> = signal(false);\nconst showAddDiscord: Signal<boolean> = signal(false);\nconst showAddWhatsApp: Signal<boolean> = signal(false);\nconst showAddSlack: Signal<boolean> = signal(false);\nconst showAddMatrix: Signal<boolean> = signal(false);\nconst showAddNostr: Signal<boolean> = signal(false);\nconst editingChannel: Signal<Channel | null> = signal(null);\nconst sendersAccount: Signal<string> = signal(\"\");\n\n// Track WhatsApp pairing state (updated by WebSocket events).\nconst waQrData: Signal<string | null> = signal(null);\nconst waQrSvg: Signal<string | null> = signal(null);\nconst waPairingAccountId: Signal<string | null> = signal(null);\nconst waPairingError: Signal<string | null> = signal(null);\n\n// ── Helpers ──────────────────────────────────────────────────\n\nfunction channelType(type: string | undefined): string {\n\treturn type || \"telegram\";\n}\n\nfunction channelLabel(type: string | undefined): string {\n\tconst t = channelType(type);\n\tif (t === \"msteams\") return \"Microsoft Teams\";\n\tif (t === \"discord\") return \"Discord\";\n\tif (t === \"whatsapp\") return \"WhatsApp\";\n\tif (t === \"slack\") return \"Slack\";\n\tif (t === \"matrix\") return \"Matrix\";\n\tif (t === \"nostr\") return \"Nostr\";\n\treturn \"Telegram\";\n}\n\nfunction channelDescriptor(type: string | undefined): ChannelDescriptor | null {\n\tconst descs = (getGon(\"channel_descriptors\") || []) as ChannelDescriptor[];\n\treturn descs.find((d) => d.channel_type === channelType(type)) || null;\n}\n\nconst MODE_LABELS: Record<string, string> = {\n\tnone: \"Send only\",\n\tpolling: \"Polling\",\n\tgateway_loop: \"Gateway\",\n\tsocket_mode: \"Socket Mode\",\n\twebhook: \"Webhook\",\n};\n\nconst MODE_HINTS: Record<string, string> = {\n\twebhook: \"Requires a publicly reachable URL. Configure your platform to send events to the endpoint shown below.\",\n\tpolling: \"Connects automatically via long-polling. No public URL needed.\",\n\tgateway_loop: \"Maintains a persistent connection. No public URL needed.\",\n\tsocket_mode: \"Connects via Socket Mode. No public URL needed.\",\n\tnone: \"This channel is send-only and cannot receive inbound messages.\",\n};\n\n// ── Small sub-components ─────────────────────────────────────\n\ninterface ConnectionModeHintProps {\n\ttype: string;\n}\n\nfunction ConnectionModeHint({ type }: ConnectionModeHintProps): VNode | null {\n\tconst desc = channelDescriptor(type);\n\tif (!desc) return null;\n\tconst hint = MODE_HINTS[desc.capabilities.inbound_mode];\n\tif (!hint) return null;\n\treturn (\n\t\t<div className=\"text-xs text-[var(--muted)] mt-1 flex items-center gap-1\">\n\t\t\t<span className=\"tier-badge\">{MODE_LABELS[desc.capabilities.inbound_mode]}</span>\n\t\t\t<span>{hint}</span>\n\t\t</div>\n\t);\n}\n\ninterface ChannelStorageNoticeProps {\n\tcompact?: boolean;\n}\n\nfunction ChannelStorageNotice({ compact = false }: ChannelStorageNoticeProps): VNode {\n\treturn (\n\t\t<div\n\t\t\tclassName={`rounded-md border border-[var(--border)] bg-[var(--surface2)] px-3 py-2 text-xs text-[var(--muted)] ${compact ? \"\" : \"max-w-3xl\"}`}\n\t\t>\n\t\t\t<span className=\"font-medium text-[var(--text-strong)]\">Storage note.</span> {channelStorageNote()}\n\t\t</div>\n\t);\n}\n\nfunction prettyConfigJson(value: unknown): string {\n\ttry {\n\t\treturn JSON.stringify(value || {}, null, 2);\n\t} catch (_error) {\n\t\treturn \"{}\";\n\t}\n}\n\nfunction copyToClipboard(value: unknown, successMessage: string): void {\n\tconst text = String(value || \"\").trim();\n\tif (!text) return;\n\tnavigator.clipboard.writeText(text).then(() => showToast(successMessage));\n}\n\n// ── Matrix info row ──────────────────────────────────────────\n\ninterface MatrixInfoRowProps {\n\tlabel: string;\n\tvalue: unknown;\n\tcopyLabel?: string | null;\n}\n\nfunction MatrixInfoRow({ label, value, copyLabel = null }: MatrixInfoRowProps): VNode {\n\tconst text = String(value || \"\").trim();\n\treturn (\n\t\t<div className=\"flex items-center justify-between gap-3\">\n\t\t\t<div className=\"min-w-0\">\n\t\t\t\t<div className=\"text-[11px] uppercase tracking-wide text-emerald-200/70\">{label}</div>\n\t\t\t\t<div className=\"truncate font-mono text-emerald-50\">{text || \"\\u2014\"}</div>\n\t\t\t</div>\n\t\t\t{text && (\n\t\t\t\t<button\n\t\t\t\t\ttype=\"button\"\n\t\t\t\t\tclassName=\"provider-btn provider-btn-sm provider-btn-secondary\"\n\t\t\t\t\tonClick={() => copyToClipboard(text, copyLabel || `${label} copied`)}\n\t\t\t\t>\n\t\t\t\t\tCopy\n\t\t\t\t</button>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\n// ── Matrix ownership card ────────────────────────────────────\n\ninterface MatrixOwnershipCardProps {\n\tchannel: Channel;\n\tmatrixStatus: MatrixStatus;\n}\n\nfunction MatrixOwnershipCard({ channel, matrixStatus }: MatrixOwnershipCardProps): VNode {\n\tconst retryingOwnership = useSignal(false);\n\tconst retryOwnershipError = useSignal(\"\");\n\tconst ownershipMode = normalizeMatrixOwnershipMode(matrixStatus?.ownership_mode);\n\tconst authMode = normalizeMatrixAuthMode(matrixStatus?.auth_mode);\n\tconst recoveryState = String(matrixStatus?.recovery_state || \"unknown\");\n\tconst deviceVerified = !!matrixStatus?.device_verified_by_owner;\n\tconst ownershipError = String(matrixStatus?.ownership_error || \"\").trim();\n\tconst approvalMatch = ownershipError.match(/https?:\\/\\/\\S+/);\n\tconst ownershipIssue =\n\t\townershipMode !== \"moltis_owned\" || ownershipError.length === 0\n\t\t\t? \"none\"\n\t\t\t: ownershipError.includes(\"requires browser approval to reset cross-signing\")\n\t\t\t\t? \"approval_required\"\n\t\t\t\t: ownershipError.includes(\"incomplete secret storage\")\n\t\t\t\t\t? \"incomplete_secret_storage\"\n\t\t\t\t\t: \"generic_blocked\";\n\tconst modeTitle =\n\t\townershipIssue === \"approval_required\"\n\t\t\t? \"Ownership approval required\"\n\t\t\t: ownershipIssue !== \"none\"\n\t\t\t\t? \"Moltis ownership blocked\"\n\t\t\t\t: ownershipMode === \"moltis_owned\"\n\t\t\t\t\t? \"Managed by Moltis\"\n\t\t\t\t\t: \"User-managed in Element\";\n\tconst modeText =\n\t\townershipIssue === \"approval_required\"\n\t\t\t? \"This existing Matrix account can already chat, but Matrix needs one browser approval before Moltis can take over encryption ownership. Open the approval page, approve the reset, then retry ownership setup.\"\n\t\t\t: ownershipIssue === \"incomplete_secret_storage\"\n\t\t\t\t? \"This account already has partial Matrix secure-backup state. Finish or repair it in Element, or switch this channel to user-managed mode.\"\n\t\t\t\t: ownershipIssue === \"generic_blocked\"\n\t\t\t\t\t? \"Moltis could not take ownership of this Matrix account automatically. Repair the account in Element or switch this channel to user-managed mode.\"\n\t\t\t\t\t: authMode === \"password\"\n\t\t\t\t\t\t? matrixOwnershipModeGuidance(authMode, ownershipMode)\n\t\t\t\t\t\t: \"Access token auth is always user-managed. If you want encrypted Matrix chats, reconnect this channel with password auth so Moltis can create its own device.\";\n\tconst detailTitle =\n\t\townershipIssue === \"approval_required\"\n\t\t\t? \"Browser approval pending\"\n\t\t\t: ownershipError\n\t\t\t\t? \"Ownership setup needs attention\"\n\t\t\t\t: \"\";\n\tconst detailText =\n\t\townershipIssue === \"approval_required\"\n\t\t\t? `Approve the reset while signed into ${matrixStatus?.user_id || \"this Matrix account\"} in the browser, then use the retry button here so Moltis can finish taking ownership.`\n\t\t\t: ownershipError;\n\tconst approvalUrl = approvalMatch ? approvalMatch[0].replace(/[;),.]+$/, \"\") : \"\";\n\tconst verificationText = deviceVerified ? \"Device verified by owner\" : \"Device not yet verified by owner\";\n\tconst hasAccountDetails =\n\t\t!!String(channel.config?.homeserver || \"\").trim() ||\n\t\t!!String(matrixStatus?.user_id || \"\").trim() ||\n\t\t!!String(matrixStatus?.device_id || \"\").trim() ||\n\t\t!!String(matrixStatus?.device_display_name || channel.config?.device_display_name || \"\").trim();\n\n\tfunction retryOwnershipSetup(): void {\n\t\tretryingOwnership.value = true;\n\t\tretryOwnershipError.value = \"\";\n\t\tsendRpc(\"channels.retry_ownership\", {\n\t\t\ttype: channelType(channel.type),\n\t\t\taccount_id: channel.account_id,\n\t\t}).then((res) => {\n\t\t\tretryingOwnership.value = false;\n\t\t\tif (res?.ok) {\n\t\t\t\tshowToast(\"Retrying Matrix ownership setup\");\n\t\t\t\tloadChannels();\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tretryOwnershipError.value =\n\t\t\t\t(res?.error as { message?: string; detail?: string })?.message ||\n\t\t\t\t(res?.error as { detail?: string })?.detail ||\n\t\t\t\t\"Failed to retry Matrix ownership setup.\";\n\t\t});\n\t}\n\n\treturn (\n\t\t<div className=\"rounded-md border border-sky-500/30 bg-sky-500/10 px-3 py-2 text-xs text-sky-100\">\n\t\t\t<div className=\"flex items-center gap-2\">\n\t\t\t\t<div className=\"font-medium text-sky-50\">{modeTitle}</div>\n\t\t\t\t<span className={`provider-item-badge ${deviceVerified ? \"configured\" : \"oauth\"}`}>{verificationText}</span>\n\t\t\t</div>\n\t\t\t<div className=\"mt-1 text-sky-100/90\">{modeText}</div>\n\t\t\t<div className=\"mt-2 text-sky-100/90\">\n\t\t\t\tCross-signing:{\" \"}\n\t\t\t\t<span className=\"font-medium\">{matrixStatus?.cross_signing_complete ? \"ready\" : \"not ready\"}</span>. Recovery:{\" \"}\n\t\t\t\t<span className=\"font-medium\">{recoveryState}</span>.\n\t\t\t</div>\n\t\t\t{hasAccountDetails && (\n\t\t\t\t<details className=\"mt-2 rounded-md border border-sky-500/20 bg-sky-500/5 px-3 py-2\">\n\t\t\t\t\t<summary className=\"cursor-pointer text-[11px] font-medium uppercase tracking-wide text-sky-100/80\">\n\t\t\t\t\t\tMatrix account details\n\t\t\t\t\t</summary>\n\t\t\t\t\t<div className=\"mt-2 grid gap-2\">\n\t\t\t\t\t\t<MatrixInfoRow label=\"Homeserver\" value={channel.config?.homeserver || \"\"} copyLabel=\"Homeserver copied\" />\n\t\t\t\t\t\t<MatrixInfoRow label=\"Matrix user\" value={matrixStatus?.user_id || \"\"} copyLabel=\"Matrix user ID copied\" />\n\t\t\t\t\t\t<MatrixInfoRow\n\t\t\t\t\t\t\tlabel=\"Device ID\"\n\t\t\t\t\t\t\tvalue={matrixStatus?.device_id || \"\"}\n\t\t\t\t\t\t\tcopyLabel=\"Matrix device ID copied\"\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<MatrixInfoRow\n\t\t\t\t\t\t\tlabel=\"Device name\"\n\t\t\t\t\t\t\tvalue={matrixStatus?.device_display_name || channel.config?.device_display_name || \"\"}\n\t\t\t\t\t\t\tcopyLabel=\"Matrix device name copied\"\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t</details>\n\t\t\t)}\n\t\t\t{ownershipIssue === \"approval_required\" && approvalUrl && (\n\t\t\t\t<div className=\"mt-2\">\n\t\t\t\t\t<div className=\"flex flex-wrap gap-2\">\n\t\t\t\t\t\t<a\n\t\t\t\t\t\t\thref={approvalUrl}\n\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\trel=\"noreferrer\"\n\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-sm\"\n\t\t\t\t\t\t\taria-label={`Open approval page for ${matrixStatus?.user_id || \"this Matrix account\"}`}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\tOpen approval page for {matrixStatus?.user_id || \"this account\"}\n\t\t\t\t\t\t</a>\n\t\t\t\t\t\t<button\n\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-sm\"\n\t\t\t\t\t\t\tonClick={retryOwnershipSetup}\n\t\t\t\t\t\t\tdisabled={retryingOwnership.value}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t{retryingOwnership.value ? \"Retrying ownership setup...\" : \"Click here once you reset the account\"}\n\t\t\t\t\t\t</button>\n\t\t\t\t\t</div>\n\t\t\t\t\t<div className=\"mt-2 text-[11px] text-sky-100/80\">\n\t\t\t\t\t\tMake sure the browser page is signed into{\" \"}\n\t\t\t\t\t\t<span className=\"font-mono text-sky-50\">{matrixStatus?.user_id || \"the Matrix bot account\"}</span>.\n\t\t\t\t\t</div>\n\t\t\t\t\t{retryOwnershipError.value && (\n\t\t\t\t\t\t<div className=\"mt-2 rounded-md border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-amber-100\">\n\t\t\t\t\t\t\t{retryOwnershipError.value}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t)}\n\t\t\t\t</div>\n\t\t\t)}\n\t\t\t{detailTitle && (\n\t\t\t\t<div className=\"mt-2 rounded-md border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-amber-100\">\n\t\t\t\t\t<div className=\"font-medium text-amber-50\">{detailTitle}</div>\n\t\t\t\t\t<div className=\"mt-1\">{detailText}</div>\n\t\t\t\t</div>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\n// ── Advanced config patch field ──────────────────────────────\n\ninterface AdvancedConfigPatchFieldProps {\n\tvalue: string;\n\tonInput: (value: string) => void;\n\tcurrentConfig?: Record<string, unknown> | null;\n}\n\nfunction AdvancedConfigPatchField({ value, onInput, currentConfig = null }: AdvancedConfigPatchFieldProps): VNode {\n\treturn (\n\t\t<details className=\"channel-card\">\n\t\t\t<summary className=\"cursor-pointer text-xs font-medium text-[var(--text-strong)]\">Advanced Config JSON</summary>\n\t\t\t<div className=\"mt-2 flex flex-col gap-3\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\tOptional JSON object merged on top of the form before save. Use this for channel-specific settings that do not\n\t\t\t\t\thave dedicated fields yet.\n\t\t\t\t</div>\n\t\t\t\t{currentConfig && (\n\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Current stored config (read-only)</label>\n\t\t\t\t\t\t<textarea\n\t\t\t\t\t\t\tclassName=\"channel-input min-h-[160px] font-mono text-xs\"\n\t\t\t\t\t\t\treadOnly\n\t\t\t\t\t\t\tvalue={prettyConfigJson(currentConfig)}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Advanced config JSON patch (optional)</label>\n\t\t\t\t\t<textarea\n\t\t\t\t\t\tdata-field=\"advancedConfigPatch\"\n\t\t\t\t\t\tclassName=\"channel-input min-h-[140px] font-mono text-xs\"\n\t\t\t\t\t\tvalue={value}\n\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\tonInput((e.target as HTMLTextAreaElement).value);\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tplaceholder='{\"reply_to_message\": true}'\n\t\t\t\t\t/>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t</details>\n\t);\n}\n\n// ── Sender selection helpers ─────────────────────────────────\n\nfunction senderSelectionKey(ch: Channel): string {\n\treturn `${channelType(ch.type)}::${ch.account_id}`;\n}\n\nfunction parseSenderSelectionKey(key: string): { type: string; account_id: string } {\n\tconst idx = key.indexOf(\"::\");\n\tif (idx < 0) return { type: \"telegram\", account_id: key };\n\treturn {\n\t\ttype: key.slice(0, idx) || \"telegram\",\n\t\taccount_id: key.slice(idx + 2),\n\t};\n}\n\n// ── Data loaders ─────────────────────────────────────────────\n\nfunction loadChannels(): void {\n\tfetchChannelStatus().then((res: unknown) => {\n\t\tconst r = res as { ok?: boolean; payload?: { channels?: Channel[] } } | undefined;\n\t\tif (r?.ok) {\n\t\t\tconst ch = r.payload?.channels || [];\n\t\t\tchannels.value = ch;\n\t\t\tS.setCachedChannels(ch);\n\t\t\tupdateNavCount(\"channels\", ch.length);\n\t\t}\n\t});\n}\n\nfunction loadSenders(): void {\n\tconst selected = sendersAccount.value;\n\tif (!selected) {\n\t\tsenders.value = [];\n\t\treturn;\n\t}\n\tconst parsed = parseSenderSelectionKey(selected);\n\tsendRpc<{ senders?: SenderEntry[] }>(\"channels.senders.list\", {\n\t\ttype: parsed.type,\n\t\taccount_id: parsed.account_id,\n\t}).then((res) => {\n\t\tif (res?.ok) senders.value = (res.payload?.senders || []) as SenderEntry[];\n\t});\n}\n\n// ── Channel icon ─────────────────────────────────────────────\n\ninterface ChannelIconProps {\n\ttype: string;\n}\n\nfunction ChannelIcon({ type }: ChannelIconProps): VNode {\n\tconst t = channelType(type);\n\tif (t === \"msteams\") return <span className=\"icon icon-msteams\" />;\n\tif (t === \"discord\") return <span className=\"icon icon-discord\" />;\n\tif (t === \"whatsapp\") return <span className=\"icon icon-whatsapp\" />;\n\tif (t === \"slack\") return <span className=\"icon icon-slack\" />;\n\tif (t === \"matrix\") return <span className=\"icon icon-matrix\" />;\n\treturn <span className=\"icon icon-telegram\" />;\n}\n\n// ── Channel card ─────────────────────────────────────────────\n\ninterface ChannelCardProps {\n\tchannel: Channel;\n}\n\nfunction ChannelCard({ channel: ch }: ChannelCardProps): VNode {\n\tfunction onRemove(): void {\n\t\trequestConfirm(`Remove ${ch.name || ch.account_id}?`).then((yes) => {\n\t\t\tif (!yes) return;\n\t\t\tsendRpc(\"channels.remove\", { type: channelType(ch.type), account_id: ch.account_id }).then((r) => {\n\t\t\t\tif (r?.ok) loadChannels();\n\t\t\t});\n\t\t});\n\t}\n\n\tconst statusClass = ch.status === \"connected\" ? \"configured\" : \"oauth\";\n\tlet sessionLine = \"\";\n\tif (ch.sessions && ch.sessions.length > 0) {\n\t\tconst active = ch.sessions.filter((s) => s.active);\n\t\tsessionLine =\n\t\t\tactive.length > 0\n\t\t\t\t? active.map((s) => `${s.label || s.key} (${s.messageCount} msgs)`).join(\", \")\n\t\t\t\t: \"No active session\";\n\t}\n\tconst desc = channelDescriptor(ch.type);\n\tconst modeLabel = desc ? MODE_LABELS[desc.capabilities.inbound_mode] || desc.capabilities.inbound_mode : null;\n\tconst matrixStatus = ch.extra?.matrix || null;\n\tconst pendingVerifications = Array.isArray(matrixStatus?.pending_verifications)\n\t\t? matrixStatus.pending_verifications\n\t\t: [];\n\tconst verificationStateLabel = matrixStatus?.verification_state || null;\n\tconst showOwnershipCard =\n\t\tchannelType(ch.type) === \"matrix\" &&\n\t\t!!(matrixStatus?.user_id || matrixStatus?.device_id || ch.config?.homeserver || matrixStatus?.ownership_error);\n\n\treturn (\n\t\t<div className=\"provider-card p-3 rounded-lg mb-2\">\n\t\t\t<div className=\"flex items-center gap-2.5\">\n\t\t\t\t<span className=\"inline-flex items-center justify-center w-7 h-7 rounded-md bg-[var(--surface2)]\">\n\t\t\t\t\t<ChannelIcon type={ch.type} />\n\t\t\t\t</span>\n\t\t\t\t<div className=\"flex flex-col gap-0.5\">\n\t\t\t\t\t<span className=\"text-sm text-[var(--text-strong)]\">{ch.name || ch.account_id || channelLabel(ch.type)}</span>\n\t\t\t\t\t{ch.details && <span className=\"text-xs text-[var(--muted)]\">{ch.details}</span>}\n\t\t\t\t\t{sessionLine && <span className=\"text-xs text-[var(--muted)]\">{sessionLine}</span>}\n\t\t\t\t\t{channelType(ch.type) === \"matrix\" && verificationStateLabel && (\n\t\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">Encryption device state: {verificationStateLabel}</span>\n\t\t\t\t\t)}\n\t\t\t\t\t{channelType(ch.type) === \"telegram\" && ch.account_id && (\n\t\t\t\t\t\t<a\n\t\t\t\t\t\t\thref={`https://t.me/${ch.account_id}`}\n\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\tclassName=\"text-xs text-[var(--accent)] underline\"\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\tt.me/{ch.account_id}\n\t\t\t\t\t\t</a>\n\t\t\t\t\t)}\n\t\t\t\t</div>\n\t\t\t\t<span className={`provider-item-badge ${statusClass}`}>{ch.status || \"unknown\"}</span>\n\t\t\t\t{modeLabel && <span className=\"tier-badge\">{modeLabel}</span>}\n\t\t\t</div>\n\t\t\t{channelType(ch.type) === \"matrix\" && pendingVerifications.length > 0 && (\n\t\t\t\t<div className=\"rounded-md border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-xs text-emerald-100\">\n\t\t\t\t\t<div className=\"font-medium text-emerald-50\">Verification pending</div>\n\t\t\t\t\t{pendingVerifications.map((prompt, i) => (\n\t\t\t\t\t\t<div key={i} className=\"mt-1\">\n\t\t\t\t\t\t\t<div>With {prompt.other_user_id}</div>\n\t\t\t\t\t\t\t<div className=\"text-emerald-200/90\">\n\t\t\t\t\t\t\t\tSend <span className=\"font-mono\">verify yes</span>, <span className=\"font-mono\">verify no</span>,{\" \"}\n\t\t\t\t\t\t\t\t<span className=\"font-mono\">verify show</span>, or <span className=\"font-mono\">verify cancel</span> as a\n\t\t\t\t\t\t\t\tnormal message in that same Matrix chat.\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t))}\n\t\t\t\t</div>\n\t\t\t)}\n\t\t\t{showOwnershipCard && matrixStatus && <MatrixOwnershipCard channel={ch} matrixStatus={matrixStatus} />}\n\t\t\t<div className=\"flex gap-2\">\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-sm provider-btn-secondary\"\n\t\t\t\t\ttitle={`Edit ${ch.account_id || \"channel\"}`}\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\teditingChannel.value = ch;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\tEdit\n\t\t\t\t</button>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-sm provider-btn-danger\"\n\t\t\t\t\ttitle={`Remove ${ch.account_id || \"channel\"}`}\n\t\t\t\t\tonClick={onRemove}\n\t\t\t\t>\n\t\t\t\t\tRemove\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// ── Connect channel buttons ──────────────────────────────────\n\nfunction ConnectButtons(): VNode {\n\tconst offered = new Set(\n\t\t(getGon(\"channels_offered\") || [\"telegram\", \"whatsapp\", \"discord\", \"slack\", \"matrix\"]) as string[],\n\t);\n\treturn (\n\t\t<div className=\"flex gap-2 flex-wrap\">\n\t\t\t{offered.has(\"telegram\") && (\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary inline-flex items-center gap-1.5\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tif (connected.value) showAddTelegram.value = true;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<span className=\"icon icon-telegram\" /> Connect Telegram\n\t\t\t\t</button>\n\t\t\t)}\n\t\t\t{offered.has(\"msteams\") && (\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary inline-flex items-center gap-1.5\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tif (connected.value) showAddTeams.value = true;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<span className=\"icon icon-msteams\" /> Connect Microsoft Teams\n\t\t\t\t</button>\n\t\t\t)}\n\t\t\t{offered.has(\"discord\") && (\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary inline-flex items-center gap-1.5\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tif (connected.value) showAddDiscord.value = true;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<span className=\"icon icon-discord\" /> Connect Discord\n\t\t\t\t</button>\n\t\t\t)}\n\t\t\t{offered.has(\"slack\") && (\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary inline-flex items-center gap-1.5\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tif (connected.value) showAddSlack.value = true;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<span className=\"icon icon-slack\" /> Connect Slack\n\t\t\t\t</button>\n\t\t\t)}\n\t\t\t{offered.has(\"matrix\") && (\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary inline-flex items-center gap-1.5\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tif (connected.value) showAddMatrix.value = true;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<span className=\"icon icon-matrix\" /> Connect Matrix\n\t\t\t\t</button>\n\t\t\t)}\n\t\t\t{offered.has(\"whatsapp\") && (\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary inline-flex items-center gap-1.5\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tif (connected.value) showAddWhatsApp.value = true;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<span className=\"icon icon-whatsapp\" /> Connect WhatsApp\n\t\t\t\t</button>\n\t\t\t)}\n\t\t\t{offered.has(\"nostr\") && (\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary inline-flex items-center gap-1.5\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tif (connected.value) showAddNostr.value = true;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<span className=\"icon icon-nostr\" /> Connect Nostr\n\t\t\t\t</button>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\n// ── Channels tab ─────────────────────────────────────────────\n\nfunction ChannelsTab(): VNode {\n\tif (channels.value.length === 0) {\n\t\treturn (\n\t\t\t<div className=\"text-center py-10\">\n\t\t\t\t<div className=\"text-sm text-[var(--muted)] mb-4\">No channels connected.</div>\n\t\t\t\t<div className=\"flex justify-center\">\n\t\t\t\t\t<ConnectButtons />\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t);\n\t}\n\treturn (\n\t\t<>\n\t\t\t{channels.value.map((ch) => (\n\t\t\t\t<ChannelCard key={senderSelectionKey(ch)} channel={ch} />\n\t\t\t))}\n\t\t</>\n\t);\n}\n\n// ── Sender row renderer ──────────────────────────────────────\n\nfunction renderSenderRow(s: SenderEntry, onAction: (identifier: string, action: string) => void): VNode {\n\tconst identifier = s.username || s.peer_id;\n\tconst lastSeenMs = s.last_seen ? s.last_seen * 1000 : 0;\n\tconst usernameLabel = s.username ? (String(s.username).startsWith(\"@\") ? s.username : `@${s.username}`) : \"\\u2014\";\n\tconst statusBadge = s.otp_pending ? (\n\t\t<span\n\t\t\tclassName=\"provider-item-badge cursor-pointer select-none\"\n\t\t\tstyle={{ background: \"var(--warning-bg, #fef3c7)\", color: \"var(--warning-text, #92400e)\" }}\n\t\t\tonClick={() => {\n\t\t\t\tnavigator.clipboard.writeText(s.otp_pending!.code).then(() => showToast(\"OTP code copied\"));\n\t\t\t}}\n\t\t>\n\t\t\tOTP: <code className=\"text-xs\">{s.otp_pending.code}</code>\n\t\t</span>\n\t) : (\n\t\t<span className={`provider-item-badge ${s.allowed ? \"configured\" : \"oauth\"}`}>\n\t\t\t{s.allowed ? \"Allowed\" : \"Denied\"}\n\t\t</span>\n\t);\n\tconst actionBtn = s.allowed ? (\n\t\t<button className=\"provider-btn provider-btn-sm provider-btn-danger\" onClick={() => onAction(identifier, \"deny\")}>\n\t\t\tDeny\n\t\t</button>\n\t) : (\n\t\t<button className=\"provider-btn provider-btn-sm\" onClick={() => onAction(identifier, \"approve\")}>\n\t\t\tApprove\n\t\t</button>\n\t);\n\treturn (\n\t\t<tr key={s.peer_id}>\n\t\t\t<td className=\"senders-td\">{s.sender_name || s.peer_id}</td>\n\t\t\t<td className=\"senders-td\" style={{ color: \"var(--muted)\" }}>\n\t\t\t\t{usernameLabel}\n\t\t\t</td>\n\t\t\t<td className=\"senders-td\">{s.message_count}</td>\n\t\t\t<td className=\"senders-td\" style={{ color: \"var(--muted)\", fontSize: \"12px\" }}>\n\t\t\t\t{lastSeenMs ? <time data-epoch-ms={String(lastSeenMs)}>{new Date(lastSeenMs).toISOString()}</time> : \"\\u2014\"}\n\t\t\t</td>\n\t\t\t<td className=\"senders-td\">{statusBadge}</td>\n\t\t\t<td className=\"senders-td\">{actionBtn}</td>\n\t\t</tr>\n\t);\n}\n\n// ── Senders tab ──────────────────────────────────────────────\n\nfunction SendersTab(): VNode {\n\tuseEffect(() => {\n\t\tif (channels.value.length > 0 && !sendersAccount.value) {\n\t\t\tsendersAccount.value = senderSelectionKey(channels.value[0]);\n\t\t}\n\t}, [channels.value]);\n\n\tuseEffect(() => {\n\t\tloadSenders();\n\t}, [sendersAccount.value]);\n\n\tif (channels.value.length === 0) {\n\t\treturn <div className=\"text-sm text-[var(--muted)]\">No channels configured.</div>;\n\t}\n\n\tfunction onAction(identifier: string, action: string): void {\n\t\tconst rpc = action === \"approve\" ? \"channels.senders.approve\" : \"channels.senders.deny\";\n\t\tconst parsed = parseSenderSelectionKey(sendersAccount.value);\n\t\tsendRpc(rpc, {\n\t\t\ttype: parsed.type,\n\t\t\taccount_id: parsed.account_id,\n\t\t\tidentifier,\n\t\t}).then(() => {\n\t\t\tloadSenders();\n\t\t\tloadChannels();\n\t\t});\n\t}\n\n\treturn (\n\t\t<div>\n\t\t\t<div style={{ marginBottom: \"12px\" }}>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\" style={{ marginRight: \"6px\" }}>\n\t\t\t\t\tAccount:\n\t\t\t\t</label>\n\t\t\t\t<select\n\t\t\t\t\tstyle={{\n\t\t\t\t\t\tbackground: \"var(--surface2)\",\n\t\t\t\t\t\tcolor: \"var(--text)\",\n\t\t\t\t\t\tborder: \"1px solid var(--border)\",\n\t\t\t\t\t\tborderRadius: \"4px\",\n\t\t\t\t\t\tpadding: \"4px 8px\",\n\t\t\t\t\t\tfontSize: \"12px\",\n\t\t\t\t\t}}\n\t\t\t\t\tvalue={sendersAccount.value}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\tsendersAccount.value = (e.target as HTMLSelectElement).value;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{channels.value.map((ch) => (\n\t\t\t\t\t\t<option key={senderSelectionKey(ch)} value={senderSelectionKey(ch)}>\n\t\t\t\t\t\t\t{ch.name || ch.account_id}\n\t\t\t\t\t\t</option>\n\t\t\t\t\t))}\n\t\t\t\t</select>\n\t\t\t</div>\n\t\t\t{senders.value.length === 0 && (\n\t\t\t\t<div className=\"text-sm text-[var(--muted)] senders-empty\">No messages received yet for this account.</div>\n\t\t\t)}\n\t\t\t{senders.value.length > 0 && (\n\t\t\t\t<table className=\"senders-table\">\n\t\t\t\t\t<thead>\n\t\t\t\t\t\t<tr>\n\t\t\t\t\t\t\t<th className=\"senders-th\">Sender</th>\n\t\t\t\t\t\t\t<th className=\"senders-th\">Username</th>\n\t\t\t\t\t\t\t<th className=\"senders-th\">Messages</th>\n\t\t\t\t\t\t\t<th className=\"senders-th\">Last Seen</th>\n\t\t\t\t\t\t\t<th className=\"senders-th\">Status</th>\n\t\t\t\t\t\t\t<th className=\"senders-th\">Action</th>\n\t\t\t\t\t\t</tr>\n\t\t\t\t\t</thead>\n\t\t\t\t\t<tbody>{senders.value.map((s) => renderSenderRow(s, onAction))}</tbody>\n\t\t\t\t</table>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\n// ── Tag-style allowlist input ────────────────────────────────\n\ninterface AllowlistInputProps {\n\tvalue: string[];\n\tonChange: (items: string[]) => void;\n\tpreserveAt?: boolean;\n}\n\nfunction AllowlistInput({ value, onChange, preserveAt }: AllowlistInputProps): VNode {\n\tconst input = useSignal(\"\");\n\n\tfunction addTag(raw: string): void {\n\t\tconst tag = preserveAt ? raw.trim() : raw.trim().replace(/^@/, \"\");\n\t\tif (tag && !value.includes(tag)) onChange([...value, tag]);\n\t\tinput.value = \"\";\n\t}\n\n\tfunction removeTag(tag: string): void {\n\t\tonChange(value.filter((t) => t !== tag));\n\t}\n\n\tfunction onKeyDown(e: KeyboardEvent): void {\n\t\tif ((e.key === \"Enter\" || e.key === \",\") && !e.isComposing) {\n\t\t\te.preventDefault();\n\t\t\tif (input.value.trim()) addTag(input.value);\n\t\t} else if (e.key === \"Backspace\" && !input.value && value.length > 0) {\n\t\t\tonChange(value.slice(0, -1));\n\t\t}\n\t}\n\n\treturn (\n\t\t<div\n\t\t\tclassName=\"flex flex-wrap items-center gap-1.5 rounded border border-[var(--border)] bg-[var(--surface2)] px-2 py-1.5\"\n\t\t\tstyle={{ minHeight: \"38px\", cursor: \"text\" }}\n\t\t\tonClick={(e) => (e.currentTarget as HTMLElement).querySelector(\"input\")?.focus()}\n\t\t>\n\t\t\t{value.map((tag) => (\n\t\t\t\t<span\n\t\t\t\t\tkey={tag}\n\t\t\t\t\tclassName=\"inline-flex items-center gap-1 rounded-full bg-[var(--accent)]/10 px-2 py-0.5 text-xs text-[var(--accent)]\"\n\t\t\t\t>\n\t\t\t\t\t{tag}\n\t\t\t\t\t<button\n\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\tclassName=\"inline-flex items-center text-[var(--muted)] hover:text-[var(--accent)]\"\n\t\t\t\t\t\tstyle={{\n\t\t\t\t\t\t\tlineHeight: 1,\n\t\t\t\t\t\t\tfontSize: \"14px\",\n\t\t\t\t\t\t\tpadding: 0,\n\t\t\t\t\t\t\tbackground: \"none\",\n\t\t\t\t\t\t\tborder: \"none\",\n\t\t\t\t\t\t\tcursor: \"pointer\",\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tonClick={(e) => {\n\t\t\t\t\t\t\te.stopPropagation();\n\t\t\t\t\t\t\tremoveTag(tag);\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\t{\"\\u00d7\"}\n\t\t\t\t\t</button>\n\t\t\t\t</span>\n\t\t\t))}\n\t\t\t<input\n\t\t\t\ttype=\"text\"\n\t\t\t\tvalue={input.value}\n\t\t\t\tonInput={(e) => {\n\t\t\t\t\tinput.value = (e.target as HTMLInputElement).value;\n\t\t\t\t}}\n\t\t\t\tonKeyDown={onKeyDown}\n\t\t\t\tplaceholder={value.length === 0 ? \"Type a username and press Enter\" : \"\"}\n\t\t\t\tclassName=\"flex-1 bg-transparent text-[var(--text)] text-sm outline-none border-none\"\n\t\t\t\tstyle={{ minWidth: \"80px\", padding: \"2px 0\", fontFamily: \"var(--font-body)\" }}\n\t\t\t/>\n\t\t</div>\n\t);\n}\n\n// ── Shared form fields ───────────────────────────────────────\n\ninterface SharedChannelFieldsProps {\n\taddModel: Signal<string>;\n\tallowlistItems: Signal<string[]>;\n}\n\nfunction SharedChannelFields({ addModel, allowlistItems }: SharedChannelFieldsProps): VNode {\n\tconst defaultPlaceholder =\n\t\tmodelsSig.value.length > 0\n\t\t\t? `(default: ${modelsSig.value[0].displayName || modelsSig.value[0].id})`\n\t\t\t: \"(server default)\";\n\n\treturn (\n\t\t<>\n\t\t\t<label className=\"text-xs text-[var(--muted)]\">DM Policy</label>\n\t\t\t<select data-field=\"dmPolicy\" className=\"channel-select\">\n\t\t\t\t<option value=\"allowlist\">Allowlist only</option>\n\t\t\t\t<option value=\"open\">Open (anyone)</option>\n\t\t\t\t<option value=\"disabled\">Disabled</option>\n\t\t\t</select>\n\t\t\t<label className=\"text-xs text-[var(--muted)]\">Group Mention Mode</label>\n\t\t\t<select data-field=\"mentionMode\" className=\"channel-select\">\n\t\t\t\t<option value=\"mention\">Must @mention bot</option>\n\t\t\t\t<option value=\"always\">Always respond</option>\n\t\t\t\t<option value=\"none\">Don't respond in groups</option>\n\t\t\t</select>\n\t\t\t<label className=\"text-xs text-[var(--muted)]\">Default Model</label>\n\t\t\t<ModelSelect\n\t\t\t\tmodels={modelsSig.value}\n\t\t\t\tvalue={addModel.value}\n\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\taddModel.value = v;\n\t\t\t\t}}\n\t\t\t\tplaceholder={defaultPlaceholder}\n\t\t\t/>\n\t\t\t<label className=\"text-xs text-[var(--muted)]\">DM Allowlist</label>\n\t\t\t<AllowlistInput\n\t\t\t\tvalue={allowlistItems.value}\n\t\t\t\tonChange={(v) => {\n\t\t\t\t\tallowlistItems.value = v;\n\t\t\t\t}}\n\t\t\t/>\n\t\t</>\n\t);\n}\n\n// ── Add Telegram modal ───────────────────────────────────────\n\nfunction AddTelegramModal(): VNode {\n\tconst error = useSignal(\"\");\n\tconst saving = useSignal(false);\n\tconst addModel = useSignal(\"\");\n\tconst allowlistItems = useSignal<string[]>([]);\n\tconst accountDraft = useSignal(\"\");\n\tconst advancedConfigPatch = useSignal(\"\");\n\n\tfunction onSubmit(e: Event): void {\n\t\te.preventDefault();\n\t\tconst form = (e.target as HTMLElement).closest(\".channel-form\") as HTMLElement;\n\t\tconst accountId = accountDraft.value.trim();\n\t\tconst credential = (form.querySelector(\"[data-field=credential]\") as HTMLInputElement).value.trim();\n\t\tconst v = validateChannelFields(\"telegram\", accountId, credential);\n\t\tif (!v.valid) {\n\t\t\terror.value = v.error;\n\t\t\treturn;\n\t\t}\n\t\tconst advancedPatch = parseChannelConfigPatch(advancedConfigPatch.value);\n\t\tif (!advancedPatch.ok) {\n\t\t\terror.value = advancedPatch.error;\n\t\t\treturn;\n\t\t}\n\t\terror.value = \"\";\n\t\tsaving.value = true;\n\t\tconst addConfig: Record<string, unknown> = {\n\t\t\ttoken: credential,\n\t\t\tdm_policy: (form.querySelector(\"[data-field=dmPolicy]\") as HTMLSelectElement).value,\n\t\t\tmention_mode: (form.querySelector(\"[data-field=mentionMode]\") as HTMLSelectElement).value,\n\t\t\tallowlist: allowlistItems.value,\n\t\t};\n\t\tif (addModel.value) {\n\t\t\taddConfig.model = addModel.value;\n\t\t\tconst found = modelsSig.value.find((x) => x.id === addModel.value);\n\t\t\tif (found?.provider) addConfig.model_provider = found.provider;\n\t\t}\n\t\tObject.assign(addConfig, advancedPatch.value);\n\t\taddChannel(\"telegram\", accountId, addConfig).then((res: unknown) => {\n\t\t\tsaving.value = false;\n\t\t\tconst r = res as { ok?: boolean; error?: { message?: string; detail?: string } } | undefined;\n\t\t\tif (r?.ok) {\n\t\t\t\tshowAddTelegram.value = false;\n\t\t\t\taddModel.value = \"\";\n\t\t\t\tallowlistItems.value = [];\n\t\t\t\taccountDraft.value = \"\";\n\t\t\t\tadvancedConfigPatch.value = \"\";\n\t\t\t\tloadChannels();\n\t\t\t} else {\n\t\t\t\terror.value = r?.error?.message || r?.error?.detail || \"Failed to connect channel.\";\n\t\t\t}\n\t\t});\n\t}\n\n\treturn (\n\t\t<Modal\n\t\t\tshow={showAddTelegram.value}\n\t\t\tonClose={() => {\n\t\t\t\tshowAddTelegram.value = false;\n\t\t\t}}\n\t\t\ttitle=\"Connect Telegram\"\n\t\t>\n\t\t\t<div className=\"channel-form\">\n\t\t\t\t<div className=\"channel-card\">\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<span className=\"text-xs font-medium text-[var(--text-strong)]\">How to create a Telegram bot</span>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] channel-help\">\n\t\t\t\t\t\t\t1. Open{\" \"}\n\t\t\t\t\t\t\t<a\n\t\t\t\t\t\t\t\thref=\"https://t.me/BotFather\"\n\t\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\t\tclassName=\"text-[var(--accent)] underline\"\n\t\t\t\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t@BotFather\n\t\t\t\t\t\t\t</a>{\" \"}\n\t\t\t\t\t\t\tin Telegram\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t2. Send /newbot and follow the prompts to choose a name and username\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">3. Copy the bot token and paste it below</div>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t<ConnectionModeHint type=\"telegram\" />\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Bot username</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"accountId\"\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tplaceholder=\"e.g. my_assistant_bot\"\n\t\t\t\t\tvalue={accountDraft.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\taccountDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Bot Token (from @BotFather)</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"credential\"\n\t\t\t\t\ttype=\"password\"\n\t\t\t\t\tplaceholder=\"123456:ABC-DEF...\"\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\tautoComplete=\"new-password\"\n\t\t\t\t\tautoCapitalize=\"none\"\n\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\tspellcheck={false}\n\t\t\t\t\tname=\"telegram_bot_token\"\n\t\t\t\t/>\n\t\t\t\t{accountDraft.value.trim() && (\n\t\t\t\t\t<div className=\"flex items-center gap-1.5 text-xs py-1\">\n\t\t\t\t\t\t<span className=\"text-[var(--muted)]\">Chat with your bot:</span>\n\t\t\t\t\t\t<a\n\t\t\t\t\t\t\thref={`https://t.me/${accountDraft.value.trim()}`}\n\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\tclassName=\"text-[var(--accent)] underline\"\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\tt.me/{accountDraft.value.trim()}\n\t\t\t\t\t\t</a>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t<SharedChannelFields addModel={addModel} allowlistItems={allowlistItems} />\n\t\t\t\t<AdvancedConfigPatchField\n\t\t\t\t\tvalue={advancedConfigPatch.value}\n\t\t\t\t\tonInput={(value) => {\n\t\t\t\t\t\tadvancedConfigPatch.value = value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t{error.value && <div className=\"text-xs text-[var(--error)] py-1\">{error.value}</div>}\n\t\t\t\t<button className=\"provider-btn\" onClick={onSubmit} disabled={saving.value}>\n\t\t\t\t\t{saving.value ? \"Connecting\\u2026\" : \"Connect Telegram\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</Modal>\n\t);\n}\n\n// ── Add Microsoft Teams modal ────────────────────────────────\n\nfunction AddTeamsModal(): VNode {\n\tconst error = useSignal(\"\");\n\tconst saving = useSignal(false);\n\tconst addModel = useSignal(\"\");\n\tconst allowlistItems = useSignal<string[]>([]);\n\tconst accountDraft = useSignal(\"\");\n\tconst webhookSecret = useSignal(\"\");\n\tconst baseUrlDraft = useSignal(defaultTeamsBaseUrl());\n\tconst bootstrapEndpoint = useSignal(\"\");\n\tconst tsStatus = useSignal<TailscaleStatus | null>(null);\n\tconst tsLoading = useSignal(true);\n\tconst enablingFunnel = useSignal(false);\n\tconst advancedConfigPatch = useSignal(\"\");\n\n\t// Fetch Tailscale status on mount.\n\tuseEffect(() => {\n\t\tfetch(\"/api/tailscale/status\")\n\t\t\t.then((r) => (r.ok ? r.json() : null))\n\t\t\t.then((data: TailscaleStatus | null) => {\n\t\t\t\ttsStatus.value = data;\n\t\t\t\ttsLoading.value = false;\n\t\t\t\tif (data?.mode === \"funnel\" && data?.url) {\n\t\t\t\t\tbaseUrlDraft.value = data.url.replace(/\\/$/, \"\");\n\t\t\t\t}\n\t\t\t})\n\t\t\t.catch(() => {\n\t\t\t\ttsLoading.value = false;\n\t\t\t});\n\t}, []);\n\n\tfunction onEnableFunnel(): void {\n\t\tenablingFunnel.value = true;\n\t\terror.value = \"\";\n\t\tfetch(\"/api/tailscale/configure\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ mode: \"funnel\" }),\n\t\t})\n\t\t\t.then((r) => r.json())\n\t\t\t.then((data: TailscaleStatus & { ok?: boolean; error?: string }) => {\n\t\t\t\tenablingFunnel.value = false;\n\t\t\t\tif (data?.ok !== false && data?.url) {\n\t\t\t\t\tbaseUrlDraft.value = data.url.replace(/\\/$/, \"\");\n\t\t\t\t\ttsStatus.value = data;\n\t\t\t\t\trefreshBootstrapEndpoint();\n\t\t\t\t} else {\n\t\t\t\t\terror.value = data?.error || \"Failed to enable Tailscale Funnel.\";\n\t\t\t\t}\n\t\t\t})\n\t\t\t.catch((e: Error) => {\n\t\t\t\tenablingFunnel.value = false;\n\t\t\t\terror.value = `Tailscale error: ${e.message}`;\n\t\t\t});\n\t}\n\n\tfunction refreshBootstrapEndpoint(): void {\n\t\tif (!bootstrapEndpoint.value) return;\n\t\tbootstrapEndpoint.value = buildTeamsEndpoint(baseUrlDraft.value, accountDraft.value, webhookSecret.value);\n\t}\n\n\tfunction onBootstrapTeams(): void {\n\t\tconst accountId = accountDraft.value.trim();\n\t\tif (!accountId) {\n\t\t\terror.value = \"Enter App ID / Account ID first.\";\n\t\t\treturn;\n\t\t}\n\t\tlet secret = webhookSecret.value.trim();\n\t\tif (!secret) {\n\t\t\tsecret = generateWebhookSecretHex();\n\t\t\twebhookSecret.value = secret;\n\t\t}\n\t\tconst endpoint = buildTeamsEndpoint(baseUrlDraft.value, accountId, secret);\n\t\tif (!endpoint) {\n\t\t\terror.value = \"Enter a valid public base URL (example: https://bot.example.com).\";\n\t\t\treturn;\n\t\t}\n\t\tbootstrapEndpoint.value = endpoint;\n\t\terror.value = \"\";\n\t\tshowToast(\"Teams endpoint generated\");\n\t}\n\n\tfunction copyBootstrapEndpoint(): void {\n\t\tif (!bootstrapEndpoint.value) return;\n\t\tif (typeof navigator === \"undefined\" || !navigator.clipboard?.writeText) {\n\t\t\tshowToast(\"Clipboard is unavailable\");\n\t\t\treturn;\n\t\t}\n\t\tnavigator.clipboard.writeText(bootstrapEndpoint.value).then(() => {\n\t\t\tshowToast(\"Messaging endpoint copied\");\n\t\t});\n\t}\n\n\tfunction onSubmit(e: Event): void {\n\t\te.preventDefault();\n\t\tconst form = (e.target as HTMLElement).closest(\".channel-form\") as HTMLElement;\n\t\tconst accountId = accountDraft.value.trim();\n\t\tconst credential = (form.querySelector(\"[data-field=credential]\") as HTMLInputElement).value.trim();\n\t\tconst v = validateChannelFields(\"msteams\", accountId, credential);\n\t\tif (!v.valid) {\n\t\t\terror.value = v.error;\n\t\t\treturn;\n\t\t}\n\t\tconst advancedPatch = parseChannelConfigPatch(advancedConfigPatch.value);\n\t\tif (!advancedPatch.ok) {\n\t\t\terror.value = advancedPatch.error;\n\t\t\treturn;\n\t\t}\n\t\terror.value = \"\";\n\t\tsaving.value = true;\n\t\tconst addConfig: Record<string, unknown> = {\n\t\t\tapp_id: accountId,\n\t\t\tapp_password: credential,\n\t\t\tdm_policy: (form.querySelector(\"[data-field=dmPolicy]\") as HTMLSelectElement).value,\n\t\t\tmention_mode: (form.querySelector(\"[data-field=mentionMode]\") as HTMLSelectElement).value,\n\t\t\tallowlist: allowlistItems.value,\n\t\t};\n\t\tif (webhookSecret.value.trim()) addConfig.webhook_secret = webhookSecret.value.trim();\n\t\tif (addModel.value) {\n\t\t\taddConfig.model = addModel.value;\n\t\t\tconst found = modelsSig.value.find((x) => x.id === addModel.value);\n\t\t\tif (found?.provider) addConfig.model_provider = found.provider;\n\t\t}\n\t\tObject.assign(addConfig, advancedPatch.value);\n\t\taddChannel(\"msteams\", accountId, addConfig).then((res: unknown) => {\n\t\t\tsaving.value = false;\n\t\t\tconst r = res as { ok?: boolean; error?: { message?: string; detail?: string } } | undefined;\n\t\t\tif (r?.ok) {\n\t\t\t\tshowAddTeams.value = false;\n\t\t\t\taddModel.value = \"\";\n\t\t\t\tallowlistItems.value = [];\n\t\t\t\taccountDraft.value = \"\";\n\t\t\t\twebhookSecret.value = \"\";\n\t\t\t\tbaseUrlDraft.value = defaultTeamsBaseUrl();\n\t\t\t\tbootstrapEndpoint.value = \"\";\n\t\t\t\tadvancedConfigPatch.value = \"\";\n\t\t\t\tloadChannels();\n\t\t\t} else {\n\t\t\t\terror.value = r?.error?.message || r?.error?.detail || \"Failed to connect channel.\";\n\t\t\t}\n\t\t});\n\t}\n\n\treturn (\n\t\t<Modal\n\t\t\tshow={showAddTeams.value}\n\t\t\tonClose={() => {\n\t\t\t\tshowAddTeams.value = false;\n\t\t\t}}\n\t\t\ttitle=\"Connect Microsoft Teams\"\n\t\t>\n\t\t\t<div className=\"channel-form\">\n\t\t\t\t{!(tsLoading.value || (tsStatus.value?.mode === \"funnel\" && tsStatus.value?.url)) && (\n\t\t\t\t\t<div className=\"rounded-md border border-amber-500/30 bg-amber-500/5 p-3 text-xs flex flex-col gap-2\">\n\t\t\t\t\t\t<span className=\"font-medium text-[var(--text-strong)]\">Public URL required</span>\n\t\t\t\t\t\t<span className=\"text-[var(--muted)]\">\n\t\t\t\t\t\t\tTeams sends messages to your server via webhook. Your Moltis instance must be reachable over HTTPS.\n\t\t\t\t\t\t</span>\n\t\t\t\t\t\t{tsStatus.value?.installed && tsStatus.value?.tailscale_up ? (\n\t\t\t\t\t\t\t<div className=\"flex flex-col gap-2\">\n\t\t\t\t\t\t\t\t<span className=\"text-[var(--muted)]\">\n\t\t\t\t\t\t\t\t\tTailscale is connected. Enable <strong>Funnel</strong> to make it publicly reachable:\n\t\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-sm\"\n\t\t\t\t\t\t\t\t\tonClick={onEnableFunnel}\n\t\t\t\t\t\t\t\t\tdisabled={enablingFunnel.value}\n\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t{enablingFunnel.value ? \"Enabling\\u2026\" : \"Enable Tailscale Funnel\"}\n\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t) : (\n\t\t\t\t\t\t\t<span className=\"text-[var(--muted)]\">\n\t\t\t\t\t\t\t\tEnable <strong>Tailscale Funnel</strong> in Settings, or use{\" \"}\n\t\t\t\t\t\t\t\t<a href=\"https://ngrok.com/\" target=\"_blank\" className=\"text-[var(--accent)] underline\" rel=\"noopener\">\n\t\t\t\t\t\t\t\t\tngrok\n\t\t\t\t\t\t\t\t</a>{\" \"}\n\t\t\t\t\t\t\t\t/{\" \"}\n\t\t\t\t\t\t\t\t<a\n\t\t\t\t\t\t\t\t\thref=\"https://developers.cloudflare.com/cloudflare-one/connections/connect-networks/\"\n\t\t\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\t\t\tclassName=\"text-[var(--accent)] underline\"\n\t\t\t\t\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\tCloudflare Tunnel\n\t\t\t\t\t\t\t\t</a>\n\t\t\t\t\t\t\t\t.\n\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t)}\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t{tsStatus.value?.mode === \"funnel\" && tsStatus.value?.url && (\n\t\t\t\t\t<div className=\"rounded-md border border-green-500/30 bg-green-500/5 p-3 text-xs flex items-center gap-2\">\n\t\t\t\t\t\t<span className=\"text-green-600\">{\"\\u2713\"}</span>\n\t\t\t\t\t\t<span className=\"text-[var(--muted)]\">\n\t\t\t\t\t\t\tTailscale Funnel active &mdash; publicly reachable at <strong>{tsStatus.value.url}</strong>\n\t\t\t\t\t\t</span>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t<div className=\"channel-card\">\n\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t<span className=\"text-xs font-medium text-[var(--text-strong)]\">How to create a Teams bot</span>\n\t\t\t\t\t\t<span className=\"text-xs font-medium text-[var(--text-strong)] opacity-70\" style={{ fontSize: \"10px\" }}>\n\t\t\t\t\t\t\tOption A: Teams Developer Portal (easiest)\n\t\t\t\t\t\t</span>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t1. Open{\" \"}\n\t\t\t\t\t\t\t<a\n\t\t\t\t\t\t\t\thref=\"https://dev.teams.microsoft.com/bots\"\n\t\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\t\tclassName=\"text-[var(--accent)] underline\"\n\t\t\t\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\tTeams Developer Portal &rarr; Bot Management\n\t\t\t\t\t\t\t</a>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t2. Click <strong>+ New Bot</strong>, give it a name, copy the <strong>Bot ID</strong> (App ID)\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t3. Under <strong>Client secrets</strong>, add a secret and copy the value (App Password)\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<span\n\t\t\t\t\t\t\tclassName=\"text-xs font-medium text-[var(--text-strong)] opacity-70\"\n\t\t\t\t\t\t\tstyle={{ fontSize: \"10px\", marginTop: \"4px\" }}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\tOption B: Azure Portal\n\t\t\t\t\t\t</span>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t1.{\" \"}\n\t\t\t\t\t\t\t<a\n\t\t\t\t\t\t\t\thref=\"https://portal.azure.com/#create/Microsoft.AzureBot\"\n\t\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\t\tclassName=\"text-[var(--accent)] underline\"\n\t\t\t\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\tCreate an Azure Bot\n\t\t\t\t\t\t\t</a>\n\t\t\t\t\t\t\t, then find App ID in Configuration\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t2. Click <strong>Manage Password</strong> &rarr; <strong>New client secret</strong> for the App Password\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginTop: \"4px\" }}>\n\t\t\t\t\t\t\tThen generate the endpoint below and paste it as the <strong>Messaging endpoint</strong> in your bot\n\t\t\t\t\t\t\tsettings.{\" \"}\n\t\t\t\t\t\t\t<a\n\t\t\t\t\t\t\t\thref=\"https://docs.moltis.org/teams.html\"\n\t\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\t\tclassName=\"text-[var(--accent)] underline\"\n\t\t\t\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\tFull guide &rarr;\n\t\t\t\t\t\t\t</a>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t<ConnectionModeHint type=\"msteams\" />\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">App ID (Bot ID from Azure)</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"accountId\"\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tplaceholder=\"e.g. 12345678-abcd-efgh-ijkl-000000000000\"\n\t\t\t\t\tvalue={accountDraft.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\taccountDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\trefreshBootstrapEndpoint();\n\t\t\t\t\t}}\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">App Password (client secret from Azure)</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"credential\"\n\t\t\t\t\ttype=\"password\"\n\t\t\t\t\tplaceholder=\"Client secret value\"\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\tautoComplete=\"new-password\"\n\t\t\t\t\tautoCapitalize=\"none\"\n\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\tspellcheck={false}\n\t\t\t\t\tname=\"teams_app_password\"\n\t\t\t\t/>\n\t\t\t\t<div>\n\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\tWebhook Secret <span className=\"opacity-60\">(optional &mdash; auto-generated if blank)</span>\n\t\t\t\t\t</label>\n\t\t\t\t\t<input\n\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\tplaceholder=\"Leave blank to auto-generate\"\n\t\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\t\tvalue={webhookSecret.value}\n\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\twebhookSecret.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\trefreshBootstrapEndpoint();\n\t\t\t\t\t\t}}\n\t\t\t\t\t/>\n\t\t\t\t\t<label className=\"text-xs text-[var(--muted)] mt-2\">\n\t\t\t\t\t\tPublic Base URL <span className=\"opacity-60\">(your server's HTTPS address)</span>\n\t\t\t\t\t</label>\n\t\t\t\t\t<input\n\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\tplaceholder=\"https://bot.example.com\"\n\t\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\t\tvalue={baseUrlDraft.value}\n\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\tbaseUrlDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\trefreshBootstrapEndpoint();\n\t\t\t\t\t\t}}\n\t\t\t\t\t/>\n\t\t\t\t\t<div className=\"flex gap-2 mt-2\">\n\t\t\t\t\t\t<button\n\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-sm provider-btn-secondary\"\n\t\t\t\t\t\t\tonClick={onBootstrapTeams}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\tBootstrap Teams\n\t\t\t\t\t\t</button>\n\t\t\t\t\t\t{bootstrapEndpoint.value && (\n\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-sm provider-btn-secondary\"\n\t\t\t\t\t\t\t\tonClick={copyBootstrapEndpoint}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\tCopy Endpoint\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t)}\n\t\t\t\t\t</div>\n\t\t\t\t\t{bootstrapEndpoint.value && (\n\t\t\t\t\t\t<div className=\"mt-2 rounded-md border border-[var(--border)] bg-[var(--surface2)] p-2\">\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mb-1\">\n\t\t\t\t\t\t\t\tMessaging endpoint &mdash; paste this into your bot's configuration:\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<code className=\"text-xs block break-all select-all\">{bootstrapEndpoint.value}</code>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t)}\n\t\t\t\t\t<div className=\"text-[10px] text-[var(--muted)] mt-1 opacity-70\">\n\t\t\t\t\t\tTeams requires HTTPS. For local dev, use{\" \"}\n\t\t\t\t\t\t<a href=\"https://ngrok.com/\" target=\"_blank\" className=\"text-[var(--accent)] underline\" rel=\"noopener\">\n\t\t\t\t\t\t\tngrok\n\t\t\t\t\t\t</a>{\" \"}\n\t\t\t\t\t\tor{\" \"}\n\t\t\t\t\t\t<a\n\t\t\t\t\t\t\thref=\"https://developers.cloudflare.com/cloudflare-one/connections/connect-networks/\"\n\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\tclassName=\"text-[var(--accent)] underline\"\n\t\t\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\tCloudflare Tunnel\n\t\t\t\t\t\t</a>\n\t\t\t\t\t\t.\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t<SharedChannelFields addModel={addModel} allowlistItems={allowlistItems} />\n\t\t\t\t<AdvancedConfigPatchField\n\t\t\t\t\tvalue={advancedConfigPatch.value}\n\t\t\t\t\tonInput={(value) => {\n\t\t\t\t\t\tadvancedConfigPatch.value = value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t{error.value && <div className=\"text-xs text-[var(--error)] py-1\">{error.value}</div>}\n\t\t\t\t<button className=\"provider-btn\" onClick={onSubmit} disabled={saving.value}>\n\t\t\t\t\t{saving.value ? \"Connecting\\u2026\" : \"Connect Microsoft Teams\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</Modal>\n\t);\n}\n\n// ── Discord invite URL helper ────────────────────────────────\n\nfunction discordInviteUrl(token: string): string {\n\tif (!token) return \"\";\n\tconst parts = token.split(\".\");\n\tif (parts.length < 3) return \"\";\n\ttry {\n\t\tconst id = atob(parts[0]);\n\t\tif (!/^\\d+$/.test(id)) return \"\";\n\t\treturn `https://discord.com/oauth2/authorize?client_id=${id}&scope=bot&permissions=100352`;\n\t} catch {\n\t\treturn \"\";\n\t}\n}\n\n// ── Add Discord modal ────────────────────────────────────────\n\nfunction AddDiscordModal(): VNode {\n\tconst error = useSignal(\"\");\n\tconst saving = useSignal(false);\n\tconst addModel = useSignal(\"\");\n\tconst allowlistItems = useSignal<string[]>([]);\n\tconst accountDraft = useSignal(\"\");\n\tconst tokenDraft = useSignal(\"\");\n\tconst advancedConfigPatch = useSignal(\"\");\n\n\tfunction onSubmit(e: Event): void {\n\t\te.preventDefault();\n\t\tconst form = (e.target as HTMLElement).closest(\".channel-form\") as HTMLElement;\n\t\tconst accountId = accountDraft.value.trim();\n\t\tconst credential = tokenDraft.value.trim();\n\t\tconst v = validateChannelFields(\"discord\", accountId, credential);\n\t\tif (!v.valid) {\n\t\t\terror.value = v.error;\n\t\t\treturn;\n\t\t}\n\t\tconst advancedPatch = parseChannelConfigPatch(advancedConfigPatch.value);\n\t\tif (!advancedPatch.ok) {\n\t\t\terror.value = advancedPatch.error;\n\t\t\treturn;\n\t\t}\n\t\terror.value = \"\";\n\t\tsaving.value = true;\n\t\tconst addConfig: Record<string, unknown> = {\n\t\t\ttoken: credential,\n\t\t\tdm_policy: (form.querySelector(\"[data-field=dmPolicy]\") as HTMLSelectElement).value,\n\t\t\tmention_mode: (form.querySelector(\"[data-field=mentionMode]\") as HTMLSelectElement).value,\n\t\t\tallowlist: allowlistItems.value,\n\t\t};\n\t\tif (addModel.value) {\n\t\t\taddConfig.model = addModel.value;\n\t\t\tconst found = modelsSig.value.find((x) => x.id === addModel.value);\n\t\t\tif (found?.provider) addConfig.model_provider = found.provider;\n\t\t}\n\t\tObject.assign(addConfig, advancedPatch.value);\n\t\taddChannel(\"discord\", accountId, addConfig).then((res: unknown) => {\n\t\t\tsaving.value = false;\n\t\t\tconst r = res as { ok?: boolean; error?: { message?: string; detail?: string } } | undefined;\n\t\t\tif (r?.ok) {\n\t\t\t\tshowAddDiscord.value = false;\n\t\t\t\taddModel.value = \"\";\n\t\t\t\tallowlistItems.value = [];\n\t\t\t\taccountDraft.value = \"\";\n\t\t\t\ttokenDraft.value = \"\";\n\t\t\t\tadvancedConfigPatch.value = \"\";\n\t\t\t\tloadChannels();\n\t\t\t} else {\n\t\t\t\terror.value = r?.error?.message || r?.error?.detail || \"Failed to connect channel.\";\n\t\t\t}\n\t\t});\n\t}\n\n\tconst inviteUrl = discordInviteUrl(tokenDraft.value);\n\n\treturn (\n\t\t<Modal\n\t\t\tshow={showAddDiscord.value}\n\t\t\tonClose={() => {\n\t\t\t\tshowAddDiscord.value = false;\n\t\t\t}}\n\t\t\ttitle=\"Connect Discord\"\n\t\t>\n\t\t\t<div className=\"channel-form\">\n\t\t\t\t<div className=\"channel-card\">\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<span className=\"text-xs font-medium text-[var(--text-strong)]\">How to set up a Discord bot</span>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] channel-help\">\n\t\t\t\t\t\t\t1. Go to the{\" \"}\n\t\t\t\t\t\t\t<a\n\t\t\t\t\t\t\t\thref=\"https://discord.com/developers/applications\"\n\t\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\t\tclassName=\"text-[var(--accent)] underline\"\n\t\t\t\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\tDiscord Developer Portal\n\t\t\t\t\t\t\t</a>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t2. Create a new Application &rarr; Bot tab &rarr; copy the bot token\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t3. Enable \"Message Content Intent\" under Privileged Gateway Intents\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t4. Paste the token below &mdash; an invite link will be generated automatically\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t5. You can also DM the bot directly without adding it to a server\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t<ConnectionModeHint type=\"discord\" />\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Account ID</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"accountId\"\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tplaceholder=\"e.g. my-discord-bot\"\n\t\t\t\t\tvalue={accountDraft.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\taccountDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Bot Token</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"credential\"\n\t\t\t\t\ttype=\"password\"\n\t\t\t\t\tplaceholder=\"Discord bot token\"\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\tvalue={tokenDraft.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\ttokenDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t\tautoComplete=\"new-password\"\n\t\t\t\t\tautoCapitalize=\"none\"\n\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\tspellcheck={false}\n\t\t\t\t\tname=\"discord_bot_token\"\n\t\t\t\t/>\n\t\t\t\t{inviteUrl && (\n\t\t\t\t\t<div className=\"rounded-md border border-[var(--border)] bg-[var(--surface2)] p-2.5 flex flex-col gap-1\">\n\t\t\t\t\t\t<span className=\"text-xs font-medium text-[var(--text-strong)]\">Invite bot to a server</span>\n\t\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\tOpen this link to add the bot (Send Messages, Attach Files, Read Message History):\n\t\t\t\t\t\t</span>\n\t\t\t\t\t\t<a href={inviteUrl} target=\"_blank\" className=\"text-xs text-[var(--accent)] underline break-all\">\n\t\t\t\t\t\t\t{inviteUrl}\n\t\t\t\t\t\t</a>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t<SharedChannelFields addModel={addModel} allowlistItems={allowlistItems} />\n\t\t\t\t<AdvancedConfigPatchField\n\t\t\t\t\tvalue={advancedConfigPatch.value}\n\t\t\t\t\tonInput={(value) => {\n\t\t\t\t\t\tadvancedConfigPatch.value = value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t{error.value && <div className=\"text-xs text-[var(--error)] py-1\">{error.value}</div>}\n\t\t\t\t<button className=\"provider-btn\" onClick={onSubmit} disabled={saving.value}>\n\t\t\t\t\t{saving.value ? \"Connecting\\u2026\" : \"Connect Discord\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</Modal>\n\t);\n}\n\n// ── Add Slack modal ──────────────────────────────────────────\n\nfunction AddSlackModal(): VNode {\n\tconst error = useSignal(\"\");\n\tconst saving = useSignal(false);\n\tconst addModel = useSignal(\"\");\n\tconst allowlistItems = useSignal<string[]>([]);\n\tconst channelAllowlistItems = useSignal<string[]>([]);\n\tconst accountDraft = useSignal(\"\");\n\tconst botTokenDraft = useSignal(\"\");\n\tconst appTokenDraft = useSignal(\"\");\n\tconst connectionMode = useSignal(\"socket_mode\");\n\tconst signingSecretDraft = useSignal(\"\");\n\tconst advancedConfigPatch = useSignal(\"\");\n\n\tfunction onSubmit(e: Event): void {\n\t\te.preventDefault();\n\t\tconst form = (e.target as HTMLElement).closest(\".channel-form\") as HTMLElement;\n\t\tconst accountId = accountDraft.value.trim();\n\t\tconst botToken = botTokenDraft.value.trim();\n\t\tif (!accountId) {\n\t\t\terror.value = \"Account ID is required.\";\n\t\t\treturn;\n\t\t}\n\t\tif (!botToken) {\n\t\t\terror.value = \"Bot Token is required.\";\n\t\t\treturn;\n\t\t}\n\t\tif (connectionMode.value === \"socket_mode\" && !appTokenDraft.value.trim()) {\n\t\t\terror.value = \"App Token is required for Socket Mode.\";\n\t\t\treturn;\n\t\t}\n\t\tif (connectionMode.value === \"events_api\" && !signingSecretDraft.value.trim()) {\n\t\t\terror.value = \"Signing Secret is required for Events API mode.\";\n\t\t\treturn;\n\t\t}\n\t\tconst advancedPatch = parseChannelConfigPatch(advancedConfigPatch.value);\n\t\tif (!advancedPatch.ok) {\n\t\t\terror.value = advancedPatch.error;\n\t\t\treturn;\n\t\t}\n\t\terror.value = \"\";\n\t\tsaving.value = true;\n\t\tconst addConfig: Record<string, unknown> = {\n\t\t\tbot_token: botToken,\n\t\t\tapp_token: appTokenDraft.value.trim(),\n\t\t\tconnection_mode: connectionMode.value,\n\t\t\tdm_policy: (form.querySelector(\"[data-field=dmPolicy]\") as HTMLSelectElement).value,\n\t\t\tgroup_policy: (form.querySelector(\"[data-field=groupPolicy]\") as HTMLSelectElement)?.value || \"open\",\n\t\t\tmention_mode: (form.querySelector(\"[data-field=mentionMode]\") as HTMLSelectElement).value,\n\t\t\tallowlist: allowlistItems.value,\n\t\t\tchannel_allowlist: channelAllowlistItems.value,\n\t\t};\n\t\tif (connectionMode.value === \"events_api\") {\n\t\t\taddConfig.signing_secret = signingSecretDraft.value.trim();\n\t\t}\n\t\tif (addModel.value) {\n\t\t\taddConfig.model = addModel.value;\n\t\t\tconst found = modelsSig.value.find((x) => x.id === addModel.value);\n\t\t\tif (found?.provider) addConfig.model_provider = found.provider;\n\t\t}\n\t\tObject.assign(addConfig, advancedPatch.value);\n\t\taddChannel(\"slack\", accountId, addConfig).then((res: unknown) => {\n\t\t\tsaving.value = false;\n\t\t\tconst r = res as { ok?: boolean; error?: { message?: string; detail?: string } } | undefined;\n\t\t\tif (r?.ok) {\n\t\t\t\tshowAddSlack.value = false;\n\t\t\t\taddModel.value = \"\";\n\t\t\t\tallowlistItems.value = [];\n\t\t\t\tchannelAllowlistItems.value = [];\n\t\t\t\taccountDraft.value = \"\";\n\t\t\t\tbotTokenDraft.value = \"\";\n\t\t\t\tappTokenDraft.value = \"\";\n\t\t\t\tsigningSecretDraft.value = \"\";\n\t\t\t\tconnectionMode.value = \"socket_mode\";\n\t\t\t\tadvancedConfigPatch.value = \"\";\n\t\t\t\tloadChannels();\n\t\t\t} else {\n\t\t\t\terror.value = r?.error?.message || r?.error?.detail || \"Failed to connect Slack.\";\n\t\t\t}\n\t\t});\n\t}\n\n\treturn (\n\t\t<Modal\n\t\t\tshow={showAddSlack.value}\n\t\t\tonClose={() => {\n\t\t\t\tshowAddSlack.value = false;\n\t\t\t}}\n\t\t\ttitle=\"Connect Slack\"\n\t\t>\n\t\t\t<div className=\"channel-form\">\n\t\t\t\t<div className=\"channel-card\">\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<span className=\"text-xs font-medium text-[var(--text-strong)]\">How to set up a Slack bot</span>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] channel-help\">\n\t\t\t\t\t\t\t1. Go to{\" \"}\n\t\t\t\t\t\t\t<a\n\t\t\t\t\t\t\t\thref=\"https://api.slack.com/apps\"\n\t\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\t\tclassName=\"text-[var(--accent)] underline\"\n\t\t\t\t\t\t\t\trel=\"noopener\"\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\tapi.slack.com/apps\n\t\t\t\t\t\t\t</a>{\" \"}\n\t\t\t\t\t\t\tand create a new app\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t2. Under OAuth & Permissions, add bot scopes: <code className=\"text-[var(--accent)]\">chat:write</code>,{\" \"}\n\t\t\t\t\t\t\t<code className=\"text-[var(--accent)]\">channels:history</code>,{\" \"}\n\t\t\t\t\t\t\t<code className=\"text-[var(--accent)]\">im:history</code>,{\" \"}\n\t\t\t\t\t\t\t<code className=\"text-[var(--accent)]\">app_mentions:read</code>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t3. Install the app to your workspace and copy the Bot User OAuth Token\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t4. For Socket Mode: enable Socket Mode and generate an App-Level Token with{\" \"}\n\t\t\t\t\t\t\t<code className=\"text-[var(--accent)]\">connections:write</code> scope\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t5. For Events API: set the Request URL to your server's webhook endpoint\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t<ConnectionModeHint type=\"slack\" />\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Account ID</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"accountId\"\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tplaceholder=\"e.g. my-slack-bot\"\n\t\t\t\t\tvalue={accountDraft.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\taccountDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Bot Token (xoxb-...)</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"botToken\"\n\t\t\t\t\ttype=\"password\"\n\t\t\t\t\tplaceholder=\"xoxb-...\"\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\tvalue={botTokenDraft.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\tbotTokenDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t\tautoComplete=\"new-password\"\n\t\t\t\t\tautoCapitalize=\"none\"\n\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\tspellcheck={false}\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Connection Mode</label>\n\t\t\t\t<select\n\t\t\t\t\tdata-field=\"connectionMode\"\n\t\t\t\t\tclassName=\"channel-select\"\n\t\t\t\t\tvalue={connectionMode.value}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\tconnectionMode.value = (e.target as HTMLSelectElement).value;\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<option value=\"socket_mode\">Socket Mode (recommended)</option>\n\t\t\t\t\t<option value=\"events_api\">Events API (HTTP webhook)</option>\n\t\t\t\t</select>\n\t\t\t\t{connectionMode.value === \"socket_mode\" && (\n\t\t\t\t\t<>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">App Token (xapp-...)</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tdata-field=\"appToken\"\n\t\t\t\t\t\t\ttype=\"password\"\n\t\t\t\t\t\t\tplaceholder=\"xapp-...\"\n\t\t\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\t\t\tvalue={appTokenDraft.value}\n\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\tappTokenDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\tautoComplete=\"new-password\"\n\t\t\t\t\t\t\tautoCapitalize=\"none\"\n\t\t\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\t\t\tspellcheck={false}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</>\n\t\t\t\t)}\n\t\t\t\t{connectionMode.value === \"events_api\" && (\n\t\t\t\t\t<>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Signing Secret</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tdata-field=\"signingSecret\"\n\t\t\t\t\t\t\ttype=\"password\"\n\t\t\t\t\t\t\tplaceholder=\"Signing secret from Basic Information\"\n\t\t\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\t\t\tvalue={signingSecretDraft.value}\n\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\tsigningSecretDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\tautoComplete=\"new-password\"\n\t\t\t\t\t\t\tautoCapitalize=\"none\"\n\t\t\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\t\t\tspellcheck={false}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</>\n\t\t\t\t)}\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Group/Channel Policy</label>\n\t\t\t\t<select data-field=\"groupPolicy\" className=\"channel-select\">\n\t\t\t\t\t<option value=\"open\">Open (respond in any channel)</option>\n\t\t\t\t\t<option value=\"allowlist\">Channel allowlist only</option>\n\t\t\t\t\t<option value=\"disabled\">Disabled (no channel messages)</option>\n\t\t\t\t</select>\n\t\t\t\t<SharedChannelFields addModel={addModel} allowlistItems={allowlistItems} />\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Channel Allowlist (Slack channel IDs)</label>\n\t\t\t\t<AllowlistInput\n\t\t\t\t\tvalue={channelAllowlistItems.value}\n\t\t\t\t\tonChange={(items) => {\n\t\t\t\t\t\tchannelAllowlistItems.value = items;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t<AdvancedConfigPatchField\n\t\t\t\t\tvalue={advancedConfigPatch.value}\n\t\t\t\t\tonInput={(value) => {\n\t\t\t\t\t\tadvancedConfigPatch.value = value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t{error.value && <div className=\"text-xs text-[var(--error)] py-1\">{error.value}</div>}\n\t\t\t\t<button className=\"provider-btn\" onClick={onSubmit} disabled={saving.value}>\n\t\t\t\t\t{saving.value ? \"Connecting\\u2026\" : \"Connect Slack\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</Modal>\n\t);\n}\n\n// ── Add Matrix modal ─────────────────────────────────────────\n\nfunction AddMatrixModal(): VNode {\n\tconst error = useSignal(\"\");\n\tconst saving = useSignal(false);\n\tconst addModel = useSignal(\"\");\n\tconst userAllowlistItems = useSignal<string[]>([]);\n\tconst roomAllowlistItems = useSignal<string[]>([]);\n\tconst homeserverDraft = useSignal(MATRIX_DEFAULT_HOMESERVER);\n\tconst authModeDraft = useSignal(\"password\");\n\tconst userIdDraft = useSignal(\"\");\n\tconst credentialDraft = useSignal(\"\");\n\tconst deviceDisplayNameDraft = useSignal(\"\");\n\tconst ownershipModeDraft = useSignal(\"moltis_owned\");\n\tconst otpSelfApprovalDraft = useSignal(true);\n\tconst otpCooldownDraft = useSignal(\"300\");\n\tconst advancedConfigPatch = useSignal(\"\");\n\n\tfunction onSubmit(e: Event): void {\n\t\te.preventDefault();\n\t\tconst form = (e.target as HTMLElement).closest(\".channel-form\") as HTMLElement;\n\t\tconst authMode = normalizeMatrixAuthMode(authModeDraft.value);\n\t\tconst credential = credentialDraft.value.trim();\n\t\tconst homeserver = homeserverDraft.value.trim();\n\t\tconst userId = userIdDraft.value.trim();\n\t\tconst accountId = deriveMatrixAccountId({ userId, homeserver });\n\t\tconst v = validateChannelFields(\"matrix\", accountId, credential, {\n\t\t\tmatrixAuthMode: authMode,\n\t\t\tmatrixUserId: userId,\n\t\t});\n\t\tif (!v.valid) {\n\t\t\terror.value = v.error;\n\t\t\treturn;\n\t\t}\n\t\tif (!homeserver) {\n\t\t\terror.value = \"Homeserver URL is required.\";\n\t\t\treturn;\n\t\t}\n\t\tconst advancedPatch = parseChannelConfigPatch(advancedConfigPatch.value);\n\t\tif (!advancedPatch.ok) {\n\t\t\terror.value = advancedPatch.error;\n\t\t\treturn;\n\t\t}\n\t\terror.value = \"\";\n\t\tsaving.value = true;\n\t\tconst addConfig: Record<string, unknown> = {\n\t\t\thomeserver,\n\t\t\townership_mode: authMode === \"password\" ? normalizeMatrixOwnershipMode(ownershipModeDraft.value) : \"user_managed\",\n\t\t\tdm_policy: (form.querySelector(\"[data-field=dmPolicy]\") as HTMLSelectElement).value,\n\t\t\troom_policy: (form.querySelector(\"[data-field=roomPolicy]\") as HTMLSelectElement).value,\n\t\t\tmention_mode: (form.querySelector(\"[data-field=mentionMode]\") as HTMLSelectElement).value,\n\t\t\tauto_join: (form.querySelector(\"[data-field=autoJoin]\") as HTMLSelectElement).value,\n\t\t\tuser_allowlist: userAllowlistItems.value,\n\t\t\troom_allowlist: roomAllowlistItems.value,\n\t\t\totp_self_approval: otpSelfApprovalDraft.value,\n\t\t\totp_cooldown_secs: normalizeMatrixOtpCooldown(otpCooldownDraft.value),\n\t\t};\n\t\tif (authMode === \"password\") {\n\t\t\taddConfig.password = credential;\n\t\t} else {\n\t\t\taddConfig.access_token = credential;\n\t\t}\n\t\tif (userId) addConfig.user_id = userId;\n\t\tif (deviceDisplayNameDraft.value.trim()) addConfig.device_display_name = deviceDisplayNameDraft.value.trim();\n\t\tif (addModel.value) {\n\t\t\taddConfig.model = addModel.value;\n\t\t\tconst found = modelsSig.value.find((x) => x.id === addModel.value);\n\t\t\tif (found?.provider) addConfig.model_provider = found.provider;\n\t\t}\n\t\tObject.assign(addConfig, advancedPatch.value);\n\t\taddChannel(\"matrix\", accountId, addConfig).then((res: unknown) => {\n\t\t\tsaving.value = false;\n\t\t\tconst r = res as { ok?: boolean; error?: { message?: string; detail?: string } } | undefined;\n\t\t\tif (r?.ok) {\n\t\t\t\tshowAddMatrix.value = false;\n\t\t\t\taddModel.value = \"\";\n\t\t\t\tuserAllowlistItems.value = [];\n\t\t\t\troomAllowlistItems.value = [];\n\t\t\t\thomeserverDraft.value = MATRIX_DEFAULT_HOMESERVER;\n\t\t\t\tauthModeDraft.value = \"password\";\n\t\t\t\tuserIdDraft.value = \"\";\n\t\t\t\tcredentialDraft.value = \"\";\n\t\t\t\tdeviceDisplayNameDraft.value = \"\";\n\t\t\t\townershipModeDraft.value = \"moltis_owned\";\n\t\t\t\totpSelfApprovalDraft.value = true;\n\t\t\t\totpCooldownDraft.value = \"300\";\n\t\t\t\tadvancedConfigPatch.value = \"\";\n\t\t\t\tloadChannels();\n\t\t\t} else {\n\t\t\t\terror.value = r?.error?.message || r?.error?.detail || \"Failed to connect Matrix.\";\n\t\t\t}\n\t\t});\n\t}\n\n\tconst defaultPlaceholder =\n\t\tmodelsSig.value.length > 0\n\t\t\t? `(default: ${modelsSig.value[0].displayName || modelsSig.value[0].id})`\n\t\t\t: \"(server default)\";\n\n\treturn (\n\t\t<Modal\n\t\t\tshow={showAddMatrix.value}\n\t\t\tonClose={() => {\n\t\t\t\tshowAddMatrix.value = false;\n\t\t\t}}\n\t\t\ttitle=\"Connect Matrix\"\n\t\t>\n\t\t\t<div className=\"channel-form\">\n\t\t\t\t<div className=\"channel-card\">\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<span className=\"text-xs font-medium text-[var(--text-strong)]\">Connect a Matrix bot user</span>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] channel-help\">\n\t\t\t\t\t\t\t1. Leave the homeserver as <span className=\"font-mono\">{MATRIX_DEFAULT_HOMESERVER}</span> for matrix.org\n\t\t\t\t\t\t\taccounts\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t2. Password is the default because it supports encrypted Matrix chats. Access token auth is only for plain\n\t\t\t\t\t\t\tMatrix traffic\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t3. Moltis generates the local account ID automatically from the Matrix user or homeserver\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t<div className=\"rounded-md border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-xs text-emerald-100\">\n\t\t\t\t\t<div className=\"font-medium text-emerald-50\">Encrypted chats require password auth</div>\n\t\t\t\t\t<div>{MATRIX_ENCRYPTION_GUIDANCE}</div>\n\t\t\t\t</div>\n\t\t\t\t<ConnectionModeHint type=\"matrix\" />\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Homeserver URL</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"homeserver\"\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tplaceholder={MATRIX_DEFAULT_HOMESERVER}\n\t\t\t\t\tvalue={homeserverDraft.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\thomeserverDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\tautoComplete=\"off\"\n\t\t\t\t\tautoCapitalize=\"none\"\n\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\tspellcheck={false}\n\t\t\t\t\tautoFocus\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Authentication</label>\n\t\t\t\t<select\n\t\t\t\t\tdata-field=\"authMode\"\n\t\t\t\t\tclassName=\"channel-select\"\n\t\t\t\t\tvalue={authModeDraft.value}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\tauthModeDraft.value = normalizeMatrixAuthMode((e.target as HTMLSelectElement).value);\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<option value=\"password\">Password</option>\n\t\t\t\t\t<option value=\"access_token\">Access token</option>\n\t\t\t\t</select>\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">{matrixAuthModeGuidance(authModeDraft.value)}</div>\n\t\t\t\t{authModeDraft.value === \"password\" ? (\n\t\t\t\t\t<label className=\"flex items-start gap-2 rounded-md border border-[var(--border)] bg-[var(--surface2)] px-3 py-2\">\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\ttype=\"checkbox\"\n\t\t\t\t\t\t\taria-label=\"Let Moltis own this Matrix account\"\n\t\t\t\t\t\t\tchecked={normalizeMatrixOwnershipMode(ownershipModeDraft.value) === \"moltis_owned\"}\n\t\t\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\t\t\townershipModeDraft.value = (e.target as HTMLInputElement).checked ? \"moltis_owned\" : \"user_managed\";\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<span className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t\t<span className=\"text-xs font-medium text-[var(--text-strong)]\">Let Moltis own this Matrix account</span>\n\t\t\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\t{matrixOwnershipModeGuidance(authModeDraft.value, ownershipModeDraft.value)}\n\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t</span>\n\t\t\t\t\t</label>\n\t\t\t\t) : (\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t{matrixOwnershipModeGuidance(authModeDraft.value, \"user_managed\")}\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\tMatrix User ID{authModeDraft.value === \"password\" ? \" (required)\" : \" (optional)\"}\n\t\t\t\t</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"userId\"\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tplaceholder=\"@bot:example.com\"\n\t\t\t\t\tvalue={userIdDraft.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\tuserIdDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">{matrixCredentialLabel(authModeDraft.value)}</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"credential\"\n\t\t\t\t\ttype=\"password\"\n\t\t\t\t\tplaceholder={matrixCredentialPlaceholder(authModeDraft.value)}\n\t\t\t\t\tvalue={credentialDraft.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\tcredentialDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\tautoComplete=\"new-password\"\n\t\t\t\t\tautoCapitalize=\"none\"\n\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\tspellcheck={false}\n\t\t\t\t/>\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t{authModeDraft.value === \"password\" ? (\n\t\t\t\t\t\t\"Use the password for the dedicated Matrix bot account. This is the required mode for encrypted Matrix chats because Moltis needs to create and persist its own Matrix device keys.\"\n\t\t\t\t\t) : (\n\t\t\t\t\t\t<>\n\t\t\t\t\t\t\tGet the access token in Element:{\" \"}\n\t\t\t\t\t\t\t<span className=\"font-mono\">Settings -&gt; Help & About -&gt; Advanced -&gt; Access Token</span>. Access\n\t\t\t\t\t\t\ttoken mode does <span className=\"font-medium\">not</span> support encrypted Matrix chats because Moltis\n\t\t\t\t\t\t\tcannot import that existing device's private encryption keys.\n\t\t\t\t\t\t</>\n\t\t\t\t\t)}{\" \"}\n\t\t\t\t\t<a href={MATRIX_DOCS_URL} target=\"_blank\" rel=\"noreferrer\" className=\"text-[var(--accent)] underline\">\n\t\t\t\t\t\tMatrix setup docs\n\t\t\t\t\t</a>\n\t\t\t\t</div>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Device Display Name (optional)</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"deviceDisplayName\"\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tplaceholder=\"Moltis Matrix Bot\"\n\t\t\t\t\tvalue={deviceDisplayNameDraft.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\tdeviceDisplayNameDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">DM Policy</label>\n\t\t\t\t<select data-field=\"dmPolicy\" className=\"channel-select\">\n\t\t\t\t\t<option value=\"allowlist\">Allowlist only</option>\n\t\t\t\t\t<option value=\"open\">Open (anyone)</option>\n\t\t\t\t\t<option value=\"disabled\">Disabled</option>\n\t\t\t\t</select>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Room Policy</label>\n\t\t\t\t<select data-field=\"roomPolicy\" className=\"channel-select\">\n\t\t\t\t\t<option value=\"allowlist\">Room allowlist only</option>\n\t\t\t\t\t<option value=\"open\">Open (any joined room)</option>\n\t\t\t\t\t<option value=\"disabled\">Disabled</option>\n\t\t\t\t</select>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Room Mention Mode</label>\n\t\t\t\t<select data-field=\"mentionMode\" className=\"channel-select\">\n\t\t\t\t\t<option value=\"mention\">Must mention bot</option>\n\t\t\t\t\t<option value=\"always\">Always respond</option>\n\t\t\t\t\t<option value=\"none\">Never respond in rooms</option>\n\t\t\t\t</select>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Invite Auto-Join</label>\n\t\t\t\t<select data-field=\"autoJoin\" className=\"channel-select\">\n\t\t\t\t\t<option value=\"always\">Always join invites</option>\n\t\t\t\t\t<option value=\"allowlist\">Only when inviter or room is allowlisted</option>\n\t\t\t\t\t<option value=\"off\">Do not auto-join</option>\n\t\t\t\t</select>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Unknown DM Approval</label>\n\t\t\t\t<select\n\t\t\t\t\tdata-field=\"otpSelfApproval\"\n\t\t\t\t\tclassName=\"channel-select\"\n\t\t\t\t\tvalue={otpSelfApprovalDraft.value ? \"on\" : \"off\"}\n\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\totpSelfApprovalDraft.value = (e.target as HTMLSelectElement).value !== \"off\";\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t<option value=\"on\">PIN challenge enabled (recommended)</option>\n\t\t\t\t\t<option value=\"off\">Reject unknown DMs without a PIN</option>\n\t\t\t\t</select>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">PIN Cooldown Seconds</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"otpCooldown\"\n\t\t\t\t\ttype=\"number\"\n\t\t\t\t\tmin={1}\n\t\t\t\t\tstep={1}\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\tvalue={otpCooldownDraft.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\totpCooldownDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\tWith DM policy on allowlist, unknown users get a 6-digit PIN challenge by default.\n\t\t\t\t</div>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Default Model</label>\n\t\t\t\t<ModelSelect\n\t\t\t\t\tmodels={modelsSig.value}\n\t\t\t\t\tvalue={addModel.value}\n\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\taddModel.value = v;\n\t\t\t\t\t}}\n\t\t\t\t\tplaceholder={defaultPlaceholder}\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">DM Allowlist (Matrix user IDs)</label>\n\t\t\t\t<AllowlistInput\n\t\t\t\t\tvalue={userAllowlistItems.value}\n\t\t\t\t\tpreserveAt={true}\n\t\t\t\t\tonChange={(items) => {\n\t\t\t\t\t\tuserAllowlistItems.value = items;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Room Allowlist (room IDs or aliases)</label>\n\t\t\t\t<AllowlistInput\n\t\t\t\t\tvalue={roomAllowlistItems.value}\n\t\t\t\t\tpreserveAt={true}\n\t\t\t\t\tonChange={(items) => {\n\t\t\t\t\t\troomAllowlistItems.value = items;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t<AdvancedConfigPatchField\n\t\t\t\t\tvalue={advancedConfigPatch.value}\n\t\t\t\t\tonInput={(value) => {\n\t\t\t\t\t\tadvancedConfigPatch.value = value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t{error.value && <div className=\"text-xs text-[var(--error)] py-1\">{error.value}</div>}\n\t\t\t\t<button className=\"provider-btn\" onClick={onSubmit} disabled={saving.value}>\n\t\t\t\t\t{saving.value ? \"Connecting\\u2026\" : \"Connect Matrix\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</Modal>\n\t);\n}\n\n// ── QR code display (WhatsApp pairing) ───────────────────────\n\nfunction qrSvgObjectUrl(svg: string | null): string | null {\n\tif (!svg) return null;\n\ttry {\n\t\treturn URL.createObjectURL(new Blob([svg], { type: \"image/svg+xml\" }));\n\t} catch (_err) {\n\t\treturn null;\n\t}\n}\n\ninterface QrCodeDisplayProps {\n\tdata: string | null;\n\tsvg: string | null;\n}\n\nfunction QrCodeDisplay({ data, svg }: QrCodeDisplayProps): VNode {\n\tconst [svgUrl, setSvgUrl] = useState<string | null>(null);\n\n\tuseEffect(() => {\n\t\tconst nextUrl = qrSvgObjectUrl(svg);\n\t\tsetSvgUrl(nextUrl);\n\t\treturn () => {\n\t\t\tif (nextUrl) URL.revokeObjectURL(nextUrl);\n\t\t};\n\t}, [svg]);\n\n\tif (!data)\n\t\treturn (\n\t\t\t<div className=\"flex items-center justify-center p-8 text-[var(--muted)] text-sm\">Waiting for QR code...</div>\n\t\t);\n\n\treturn (\n\t\t<div className=\"flex flex-col items-center gap-3 p-4\">\n\t\t\t<div\n\t\t\t\tclassName=\"rounded-lg bg-white p-3\"\n\t\t\t\tstyle={{ width: \"200px\", height: \"200px\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}\n\t\t\t>\n\t\t\t\t{svgUrl ? (\n\t\t\t\t\t<img\n\t\t\t\t\t\tsrc={svgUrl}\n\t\t\t\t\t\talt=\"WhatsApp pairing QR code\"\n\t\t\t\t\t\tstyle={{ width: \"100%\", height: \"100%\", display: \"block\" }}\n\t\t\t\t\t/>\n\t\t\t\t) : (\n\t\t\t\t\t<div className=\"text-center text-xs text-gray-600\">\n\t\t\t\t\t\t<div\n\t\t\t\t\t\t\tstyle={{\n\t\t\t\t\t\t\t\tfontFamily: \"monospace\",\n\t\t\t\t\t\t\t\tfontSize: \"9px\",\n\t\t\t\t\t\t\t\twordBreak: \"break-all\",\n\t\t\t\t\t\t\t\tmaxHeight: \"180px\",\n\t\t\t\t\t\t\t\toverflow: \"hidden\",\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t{data.substring(0, 200)}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t</div>\n\t\t\t<div className=\"text-xs text-[var(--muted)] text-center\">\n\t\t\t\tScan this QR code in your terminal output,\n\t\t\t\t<br />\n\t\t\t\tor open WhatsApp &gt; Settings &gt; Linked Devices &gt; Link a Device.\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// ── Add Nostr modal ──────────────────────────────────────────\n\nfunction AddNostrModal(): VNode {\n\tconst error = useSignal(\"\");\n\tconst saving = useSignal(false);\n\tconst addModel = useSignal(\"\");\n\tconst allowlistItems = useSignal<string[]>([]);\n\tconst accountDraft = useSignal(\"\");\n\tconst secretKeyDraft = useSignal(\"\");\n\tconst relaysDraft = useSignal(\"wss://relay.damus.io, wss://relay.nostr.band, wss://nos.lol\");\n\tconst advancedConfigPatch = useSignal(\"\");\n\n\tfunction onSubmit(e: Event): void {\n\t\te.preventDefault();\n\t\tconst form = (e.target as HTMLElement).closest(\".channel-form\") as HTMLElement;\n\t\tconst accountId = accountDraft.value.trim();\n\t\tconst secretKey = secretKeyDraft.value.trim();\n\t\tif (!accountId) {\n\t\t\terror.value = \"Account ID is required.\";\n\t\t\treturn;\n\t\t}\n\t\tif (!secretKey) {\n\t\t\terror.value = \"Secret key is required.\";\n\t\t\treturn;\n\t\t}\n\t\tconst advancedPatch = parseChannelConfigPatch(advancedConfigPatch.value);\n\t\tif (!advancedPatch.ok) {\n\t\t\terror.value = advancedPatch.error;\n\t\t\treturn;\n\t\t}\n\t\terror.value = \"\";\n\t\tsaving.value = true;\n\t\tconst relays = relaysDraft.value\n\t\t\t.split(\",\")\n\t\t\t.map((r) => r.trim())\n\t\t\t.filter(Boolean);\n\t\tconst addConfig: Record<string, unknown> = {\n\t\t\tsecret_key: secretKey,\n\t\t\trelays,\n\t\t\tdm_policy: (form.querySelector(\"[data-field=dmPolicy]\") as HTMLSelectElement).value,\n\t\t\tallowed_pubkeys: allowlistItems.value,\n\t\t};\n\t\tif (addModel.value) {\n\t\t\taddConfig.model = addModel.value;\n\t\t\tconst found = modelsSig.value.find((x) => x.id === addModel.value);\n\t\t\tif (found?.provider) addConfig.model_provider = found.provider;\n\t\t}\n\t\tObject.assign(addConfig, advancedPatch.value);\n\t\taddChannel(\"nostr\", accountId, addConfig).then((res: unknown) => {\n\t\t\tsaving.value = false;\n\t\t\tconst r = res as { ok?: boolean; error?: { message?: string; detail?: string } } | undefined;\n\t\t\tif (r?.ok) {\n\t\t\t\tshowAddNostr.value = false;\n\t\t\t\taddModel.value = \"\";\n\t\t\t\tallowlistItems.value = [];\n\t\t\t\taccountDraft.value = \"\";\n\t\t\t\tsecretKeyDraft.value = \"\";\n\t\t\t\trelaysDraft.value = \"wss://relay.damus.io, wss://relay.nostr.band, wss://nos.lol\";\n\t\t\t\tadvancedConfigPatch.value = \"\";\n\t\t\t\tloadChannels();\n\t\t\t} else {\n\t\t\t\terror.value = r?.error?.message || r?.error?.detail || \"Failed to connect channel.\";\n\t\t\t}\n\t\t});\n\t}\n\n\treturn (\n\t\t<Modal\n\t\t\tshow={showAddNostr.value}\n\t\t\tonClose={() => {\n\t\t\t\tshowAddNostr.value = false;\n\t\t\t}}\n\t\t\ttitle=\"Connect Nostr\"\n\t\t>\n\t\t\t<div className=\"channel-form\">\n\t\t\t\t<div className=\"channel-card\">\n\t\t\t\t\t<div>\n\t\t\t\t\t\t<span className=\"text-xs font-medium text-[var(--text-strong)]\">How to set up Nostr DMs</span>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] channel-help\">\n\t\t\t\t\t\t\t1. Generate or use an existing Nostr secret key (nsec1... or hex)\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">2. Configure relay URLs (defaults are provided)</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t3. Add allowed public keys (npub1... or hex) to the allowlist\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t4. Send a DM to the bot's public key from any Nostr client\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t<ConnectionModeHint type=\"nostr\" />\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Account ID</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"accountId\"\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tplaceholder=\"e.g. my-nostr-bot\"\n\t\t\t\t\tvalue={accountDraft.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\taccountDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Secret Key</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"credential\"\n\t\t\t\t\ttype=\"password\"\n\t\t\t\t\tplaceholder=\"nsec1... or 64-char hex\"\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\tvalue={secretKeyDraft.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\tsecretKeyDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t\tautoComplete=\"new-password\"\n\t\t\t\t\tautoCapitalize=\"none\"\n\t\t\t\t\tautoCorrect=\"off\"\n\t\t\t\t\tspellcheck={false}\n\t\t\t\t\tname=\"nostr_secret_key\"\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Relays (comma-separated)</label>\n\t\t\t\t<input\n\t\t\t\t\tdata-field=\"relays\"\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tplaceholder=\"wss://relay.damus.io, wss://nos.lol\"\n\t\t\t\t\tvalue={relaysDraft.value}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\trelaysDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">DM Policy</label>\n\t\t\t\t<select data-field=\"dmPolicy\" className=\"channel-select\">\n\t\t\t\t\t<option value=\"allowlist\">Allowlist only</option>\n\t\t\t\t\t<option value=\"open\">Open (anyone)</option>\n\t\t\t\t\t<option value=\"disabled\">Disabled</option>\n\t\t\t\t</select>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Default Model</label>\n\t\t\t\t<ModelSelect\n\t\t\t\t\tmodels={modelsSig.value}\n\t\t\t\t\tvalue={addModel.value}\n\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\taddModel.value = v;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Allowed Public Keys</label>\n\t\t\t\t<AllowlistInput\n\t\t\t\t\tvalue={allowlistItems.value}\n\t\t\t\t\tonChange={(v) => {\n\t\t\t\t\t\tallowlistItems.value = v;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t<AdvancedConfigPatchField\n\t\t\t\t\tvalue={advancedConfigPatch.value}\n\t\t\t\t\tonInput={(value) => {\n\t\t\t\t\t\tadvancedConfigPatch.value = value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t{error.value && <div className=\"text-xs text-[var(--error)] py-1\">{error.value}</div>}\n\t\t\t\t<button className=\"provider-btn\" onClick={onSubmit} disabled={saving.value}>\n\t\t\t\t\t{saving.value ? \"Connecting\\u2026\" : \"Connect Nostr\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</Modal>\n\t);\n}\n\n// ── Add WhatsApp modal ───────────────────────────────────────\n\nfunction AddWhatsAppModal(): VNode {\n\tconst error = useSignal(\"\");\n\tconst saving = useSignal(false);\n\tconst addModel = useSignal(\"\");\n\tconst pairingStarted = useSignal(false);\n\tconst allowlistItems = useSignal<string[]>([]);\n\tconst accountDraft = useSignal(\"\");\n\tconst advancedConfigPatch = useSignal(\"\");\n\tconst qrPollRef = useRef<ReturnType<typeof setInterval> | null>(null);\n\n\tfunction onStartPairing(e: Event): void {\n\t\te.preventDefault();\n\t\tconst accountId = accountDraft.value.trim() || \"main\";\n\t\tconst form = (e.target as HTMLElement).closest(\".channel-form\") as HTMLElement;\n\t\tconst advancedPatch = parseChannelConfigPatch(advancedConfigPatch.value);\n\t\tif (!advancedPatch.ok) {\n\t\t\terror.value = advancedPatch.error;\n\t\t\treturn;\n\t\t}\n\t\terror.value = \"\";\n\t\tsaving.value = true;\n\t\twaQrData.value = null;\n\t\twaQrSvg.value = null;\n\t\twaPairingError.value = null;\n\t\twaPairingAccountId.value = accountId;\n\n\t\tconst addConfig: Record<string, unknown> = {\n\t\t\tdm_policy: (form.querySelector(\"[data-field=dmPolicy]\") as HTMLSelectElement)?.value || \"open\",\n\t\t\tallowlist: allowlistItems.value,\n\t\t};\n\t\tif (addModel.value) {\n\t\t\taddConfig.model = addModel.value;\n\t\t\tconst found = modelsSig.value.find((x) => x.id === addModel.value);\n\t\t\tif (found?.provider) addConfig.model_provider = found.provider;\n\t\t}\n\t\tObject.assign(addConfig, advancedPatch.value);\n\t\taddChannel(\"whatsapp\", accountId, addConfig).then((res: unknown) => {\n\t\t\tsaving.value = false;\n\t\t\tconst r = res as { ok?: boolean; error?: { message?: string; detail?: string } } | undefined;\n\t\t\tif (r?.ok) {\n\t\t\t\tpairingStarted.value = true;\n\t\t\t\t// Poll channels.status as fallback for QR display and connection detection.\n\t\t\t\tif (qrPollRef.current) clearInterval(qrPollRef.current);\n\t\t\t\tqrPollRef.current = setInterval(async () => {\n\t\t\t\t\ttry {\n\t\t\t\t\t\tconst st = await sendRpc<{ channels?: Channel[] }>(\"channels.status\", {});\n\t\t\t\t\t\tif (!st?.ok) return;\n\t\t\t\t\t\tconst ch = (st.payload?.channels || []).find((c) => c.type === \"whatsapp\" && c.account_id === accountId);\n\t\t\t\t\t\tif (!ch) return;\n\t\t\t\t\t\tif (ch.status === \"connected\" || (waQrData.value && !ch.extra?.qr_data)) {\n\t\t\t\t\t\t\tclearInterval(qrPollRef.current!);\n\t\t\t\t\t\t\tqrPollRef.current = null;\n\t\t\t\t\t\t\tshowToast(\"WhatsApp connected!\");\n\t\t\t\t\t\t\tshowAddWhatsApp.value = false;\n\t\t\t\t\t\t\twaPairingAccountId.value = null;\n\t\t\t\t\t\t\twaQrData.value = null;\n\t\t\t\t\t\t\twaQrSvg.value = null;\n\t\t\t\t\t\t\tloadChannels();\n\t\t\t\t\t\t\treturn;\n\t\t\t\t\t\t}\n\t\t\t\t\t\tif (ch.extra?.qr_data) {\n\t\t\t\t\t\t\twaQrData.value = ch.extra.qr_data;\n\t\t\t\t\t\t\tif (ch.extra.qr_svg) waQrSvg.value = ch.extra.qr_svg;\n\t\t\t\t\t\t}\n\t\t\t\t\t} catch (_e) {\n\t\t\t\t\t\t/* ignore */\n\t\t\t\t\t}\n\t\t\t\t}, 2000);\n\t\t\t} else {\n\t\t\t\terror.value = r?.error?.message || r?.error?.detail || \"Failed to start pairing.\";\n\t\t\t}\n\t\t});\n\t}\n\n\tfunction onClose(): void {\n\t\tif (qrPollRef.current) {\n\t\t\tclearInterval(qrPollRef.current);\n\t\t\tqrPollRef.current = null;\n\t\t}\n\t\tshowAddWhatsApp.value = false;\n\t\tpairingStarted.value = false;\n\t\twaQrData.value = null;\n\t\twaQrSvg.value = null;\n\t\twaPairingError.value = null;\n\t\twaPairingAccountId.value = null;\n\t\tallowlistItems.value = [];\n\t\taccountDraft.value = \"\";\n\t\tadvancedConfigPatch.value = \"\";\n\t\tloadChannels();\n\t}\n\n\tconst defaultPlaceholder =\n\t\tmodelsSig.value.length > 0\n\t\t\t? `(default: ${modelsSig.value[0].displayName || modelsSig.value[0].id})`\n\t\t\t: \"(server default)\";\n\n\treturn (\n\t\t<Modal show={showAddWhatsApp.value} onClose={onClose} title=\"Connect WhatsApp\">\n\t\t\t<div className=\"channel-form\">\n\t\t\t\t{pairingStarted.value ? (\n\t\t\t\t\t<div className=\"flex flex-col items-center gap-4\">\n\t\t\t\t\t\t{waPairingError.value ? (\n\t\t\t\t\t\t\t<div className=\"text-sm text-[var(--error)]\">{waPairingError.value}</div>\n\t\t\t\t\t\t) : (\n\t\t\t\t\t\t\t<QrCodeDisplay data={waQrData.value} svg={waQrSvg.value} />\n\t\t\t\t\t\t)}\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\tQR code refreshes automatically. Keep this window open.\n\t\t\t\t\t\t\t<br />\n\t\t\t\t\t\t\tOnly new messages will be processed &mdash; past conversations are not synced.\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t) : (\n\t\t\t\t\t<>\n\t\t\t\t\t\t<div className=\"channel-card\">\n\t\t\t\t\t\t\t<div>\n\t\t\t\t\t\t\t\t<span className=\"text-xs font-medium text-[var(--text-strong)]\">Link your WhatsApp</span>\n\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] channel-help\">\n\t\t\t\t\t\t\t\t\t1. Choose an account ID below (any name you like)\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">2. Click \"Start Pairing\" to generate a QR code</div>\n\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\t\t3. Open WhatsApp on your phone &gt; Settings &gt; Linked Devices &gt; Link a Device\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">4. Scan the QR code to connect</div>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<ConnectionModeHint type=\"whatsapp\" />\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Account ID</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tdata-field=\"accountId\"\n\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\tplaceholder=\"main\"\n\t\t\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\t\t\tvalue={accountDraft.value}\n\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\taccountDraft.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">DM Policy</label>\n\t\t\t\t\t\t<select data-field=\"dmPolicy\" className=\"channel-select\">\n\t\t\t\t\t\t\t<option value=\"open\">Open (anyone)</option>\n\t\t\t\t\t\t\t<option value=\"allowlist\">Allowlist only</option>\n\t\t\t\t\t\t\t<option value=\"disabled\">Disabled</option>\n\t\t\t\t\t\t</select>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Default Model</label>\n\t\t\t\t\t\t<ModelSelect\n\t\t\t\t\t\t\tmodels={modelsSig.value}\n\t\t\t\t\t\t\tvalue={addModel.value}\n\t\t\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\t\t\taddModel.value = v;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\tplaceholder={defaultPlaceholder}\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">DM Allowlist</label>\n\t\t\t\t\t\t<AllowlistInput\n\t\t\t\t\t\t\tvalue={allowlistItems.value}\n\t\t\t\t\t\t\tonChange={(v) => {\n\t\t\t\t\t\t\t\tallowlistItems.value = v;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<AdvancedConfigPatchField\n\t\t\t\t\t\t\tvalue={advancedConfigPatch.value}\n\t\t\t\t\t\t\tonInput={(value) => {\n\t\t\t\t\t\t\t\tadvancedConfigPatch.value = value;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t{error.value && <div className=\"text-xs text-[var(--error)] py-1\">{error.value}</div>}\n\t\t\t\t\t\t<button className=\"provider-btn\" onClick={onStartPairing} disabled={saving.value}>\n\t\t\t\t\t\t\t{saving.value ? \"Starting\\u2026\" : \"Start Pairing\"}\n\t\t\t\t\t\t</button>\n\t\t\t\t\t</>\n\t\t\t\t)}\n\t\t\t</div>\n\t\t</Modal>\n\t);\n}\n\n// ── Edit channel modal ───────────────────────────────────────\n\nfunction EditChannelModal(): VNode | null {\n\tconst ch = editingChannel.value;\n\tconst error = useSignal(\"\");\n\tconst saving = useSignal(false);\n\tconst editModel = useSignal(\"\");\n\tconst allowlistItems = useSignal<string[]>([]);\n\tconst roomAllowlistItems = useSignal<string[]>([]);\n\tconst editCredential = useSignal(\"\");\n\tconst editWebhookSecret = useSignal(\"\");\n\tconst editStreamMode = useSignal(\"edit_in_place\");\n\tconst editReplyStyle = useSignal(\"top_level\");\n\tconst editWelcomeCard = useSignal(true);\n\tconst editBotName = useSignal(\"\");\n\tconst editMatrixAuthMode = useSignal(\"access_token\");\n\tconst editMatrixDeviceDisplayName = useSignal(\"\");\n\tconst editMatrixOwnershipMode = useSignal(\"user_managed\");\n\tconst editMatrixOtpSelfApproval = useSignal(true);\n\tconst editMatrixOtpCooldown = useSignal(\"300\");\n\tconst editAdvancedConfigPatch = useSignal(\"\");\n\n\tuseEffect(() => {\n\t\teditModel.value = (ch?.config?.model as string) || \"\";\n\t\tallowlistItems.value = (ch?.config?.allowlist ||\n\t\t\tch?.config?.user_allowlist ||\n\t\t\tch?.config?.allowed_pubkeys ||\n\t\t\t[]) as string[];\n\t\troomAllowlistItems.value = (ch?.config?.room_allowlist || []) as string[];\n\t\teditCredential.value = \"\";\n\t\teditWebhookSecret.value = (ch?.config?.webhook_secret as string) || \"\";\n\t\teditStreamMode.value = (ch?.config?.stream_mode as string) || \"edit_in_place\";\n\t\teditReplyStyle.value = (ch?.config?.reply_style as string) || \"top_level\";\n\t\teditWelcomeCard.value = ch?.config?.welcome_card !== false;\n\t\teditBotName.value = (ch?.config?.bot_name as string) || \"\";\n\t\teditMatrixAuthMode.value = ch?.config?.password ? \"password\" : \"access_token\";\n\t\teditMatrixDeviceDisplayName.value = (ch?.config?.device_display_name as string) || \"\";\n\t\teditMatrixOwnershipMode.value = normalizeMatrixOwnershipMode(\n\t\t\t(ch?.config?.ownership_mode as string) || (ch?.config?.password ? \"moltis_owned\" : \"user_managed\"),\n\t\t);\n\t\teditMatrixOtpSelfApproval.value = ch?.config?.otp_self_approval !== false;\n\t\teditMatrixOtpCooldown.value = String(ch?.config?.otp_cooldown_secs || 300);\n\t\teditAdvancedConfigPatch.value = \"\";\n\t}, [ch]);\n\n\tif (!ch) return null;\n\n\tconst cfg = ch.config || {};\n\tconst chType = channelType(ch.type);\n\tconst isTeams = chType === \"msteams\";\n\tconst isDiscord = chType === \"discord\";\n\tconst isWhatsApp = chType === \"whatsapp\";\n\tconst isTelegram = chType === \"telegram\";\n\tconst isMatrix = chType === \"matrix\";\n\tconst isNostr = chType === \"nostr\";\n\n\tfunction addModelToConfig(config: Record<string, unknown>): void {\n\t\tif (!editModel.value) return;\n\t\tconfig.model = editModel.value;\n\t\tconst found = modelsSig.value.find((x) => x.id === editModel.value);\n\t\tif (found?.provider) config.model_provider = found.provider;\n\t}\n\n\tfunction addChannelCredentials(config: Record<string, unknown>, form: HTMLElement): void {\n\t\tif (isTeams) {\n\t\t\tconfig.app_id = cfg.app_id || ch?.account_id;\n\t\t\tconfig.app_password = editCredential.value || cfg.app_password || \"\";\n\t\t\tif (editWebhookSecret.value.trim()) config.webhook_secret = editWebhookSecret.value.trim();\n\t\t} else if (isDiscord) {\n\t\t\tconfig.token = editCredential.value || cfg.token || \"\";\n\t\t} else if (isTelegram) {\n\t\t\tconfig.token = cfg.token || \"\";\n\t\t} else if (isNostr) {\n\t\t\tconfig.secret_key = editCredential.value || cfg.secret_key || \"\";\n\t\t\tconst relaysVal = (form.querySelector(\"[data-field=relays]\") as HTMLInputElement)?.value || \"\";\n\t\t\tconfig.relays = relaysVal\n\t\t\t\t.split(\",\")\n\t\t\t\t.map((r) => r.trim())\n\t\t\t\t.filter(Boolean);\n\t\t} else if (isMatrix) {\n\t\t\tconfig.homeserver =\n\t\t\t\t(form.querySelector(\"[data-field=homeserver]\") as HTMLInputElement)?.value || cfg.homeserver || \"\";\n\t\t\tconfig.user_id = (form.querySelector(\"[data-field=userId]\") as HTMLInputElement)?.value || cfg.user_id || \"\";\n\t\t\tconfig.device_id = cfg.device_id || undefined;\n\t\t\tconfig.device_display_name = editMatrixDeviceDisplayName.value.trim() || null;\n\t\t\tconfig.ownership_mode =\n\t\t\t\tnormalizeMatrixAuthMode(editMatrixAuthMode.value) === \"password\"\n\t\t\t\t\t? normalizeMatrixOwnershipMode(editMatrixOwnershipMode.value)\n\t\t\t\t\t: \"user_managed\";\n\t\t\tif (normalizeMatrixAuthMode(editMatrixAuthMode.value) === \"password\") {\n\t\t\t\tconfig.password = editCredential.value || cfg.password || \"\";\n\t\t\t\tconfig.access_token = \"\";\n\t\t\t} else {\n\t\t\t\tconfig.access_token = editCredential.value || cfg.access_token || \"\";\n\t\t\t\tconfig.password = null;\n\t\t\t}\n\t\t}\n\t}\n\n\tfunction buildUpdateConfig(form: HTMLElement): Record<string, unknown> {\n\t\tconst updateConfig: Record<string, unknown> = {};\n\t\tupdateConfig.dm_policy = (form.querySelector(\"[data-field=dmPolicy]\") as HTMLSelectElement)?.value || \"open\";\n\t\tupdateConfig.allowlist = allowlistItems.value;\n\t\tif (isMatrix) {\n\t\t\tupdateConfig.user_allowlist = allowlistItems.value;\n\t\t\tupdateConfig.room_policy =\n\t\t\t\t(form.querySelector(\"[data-field=roomPolicy]\") as HTMLSelectElement)?.value || cfg.room_policy || \"allowlist\";\n\t\t\tupdateConfig.auto_join =\n\t\t\t\t(form.querySelector(\"[data-field=autoJoin]\") as HTMLSelectElement)?.value || cfg.auto_join || \"always\";\n\t\t\tupdateConfig.room_allowlist = roomAllowlistItems.value;\n\t\t\tupdateConfig.otp_self_approval = editMatrixOtpSelfApproval.value;\n\t\t\tupdateConfig.otp_cooldown_secs = normalizeMatrixOtpCooldown(editMatrixOtpCooldown.value);\n\t\t}\n\t\tif (isNostr) {\n\t\t\tupdateConfig.allowed_pubkeys = allowlistItems.value;\n\t\t\t// Preserve OTP settings that have no dedicated UI fields yet.\n\t\t\tupdateConfig.otp_self_approval = cfg.otp_self_approval !== false;\n\t\t\tupdateConfig.otp_cooldown_secs = cfg.otp_cooldown_secs ?? 300;\n\t\t}\n\t\tif (!(isWhatsApp || isNostr)) {\n\t\t\tupdateConfig.mention_mode =\n\t\t\t\t(form.querySelector(\"[data-field=mentionMode]\") as HTMLSelectElement)?.value || \"mention\";\n\t\t}\n\t\taddChannelCredentials(updateConfig, form);\n\t\taddModelToConfig(updateConfig);\n\t\tif (isTeams) {\n\t\t\tupdateConfig.stream_mode = editStreamMode.value;\n\t\t\tupdateConfig.reply_style = editReplyStyle.value;\n\t\t\tupdateConfig.welcome_card = editWelcomeCard.value;\n\t\t\tif (editBotName.value.trim()) updateConfig.bot_name = editBotName.value.trim();\n\t\t}\n\t\treturn updateConfig;\n\t}\n\n\tfunction onSave(e: Event): void {\n\t\te.preventDefault();\n\t\tconst form = (e.target as HTMLElement).closest(\".channel-form\") as HTMLElement;\n\t\tconst advancedPatch = parseChannelConfigPatch(editAdvancedConfigPatch.value);\n\t\tif (!advancedPatch.ok) {\n\t\t\terror.value = advancedPatch.error;\n\t\t\treturn;\n\t\t}\n\t\terror.value = \"\";\n\t\tif (!ch) return;\n\t\tsaving.value = true;\n\t\tconst updateConfig = buildUpdateConfig(form);\n\t\tObject.assign(updateConfig, advancedPatch.value);\n\t\tsendRpc(\"channels.update\", {\n\t\t\ttype: channelType(ch.type),\n\t\t\taccount_id: ch.account_id,\n\t\t\tconfig: updateConfig,\n\t\t}).then((res) => {\n\t\t\tsaving.value = false;\n\t\t\tif (res?.ok) {\n\t\t\t\teditingChannel.value = null;\n\t\t\t\tloadChannels();\n\t\t\t} else {\n\t\t\t\terror.value =\n\t\t\t\t\t(res?.error as { message?: string; detail?: string })?.message ||\n\t\t\t\t\t(res?.error as { detail?: string })?.detail ||\n\t\t\t\t\t\"Failed to update channel.\";\n\t\t\t}\n\t\t});\n\t}\n\n\tconst defaultPlaceholder =\n\t\tmodelsSig.value.length > 0\n\t\t\t? `(default: ${modelsSig.value[0].displayName || modelsSig.value[0].id})`\n\t\t\t: \"(server default)\";\n\n\treturn (\n\t\t<Modal\n\t\t\tshow={true}\n\t\t\tonClose={() => {\n\t\t\t\teditingChannel.value = null;\n\t\t\t}}\n\t\t\ttitle={`Edit ${channelLabel(ch.type)} Channel`}\n\t\t>\n\t\t\t<div className=\"channel-form\">\n\t\t\t\t<div className=\"text-sm text-[var(--text-strong)]\">{ch.name || ch.account_id}</div>\n\t\t\t\t{isTelegram && ch.account_id && (\n\t\t\t\t\t<a href={`https://t.me/${ch.account_id}`} target=\"_blank\" className=\"text-xs text-[var(--accent)] underline\">\n\t\t\t\t\t\tt.me/{ch.account_id}\n\t\t\t\t\t</a>\n\t\t\t\t)}\n\t\t\t\t{isTeams && (\n\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">App Password (optional: leave blank to keep existing)</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\ttype=\"password\"\n\t\t\t\t\t\t\tclassName=\"channel-input w-full\"\n\t\t\t\t\t\t\tvalue={editCredential.value}\n\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\teditCredential.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t{isTeams && (\n\t\t\t\t\t<>\n\t\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Webhook Secret</label>\n\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\t\tclassName=\"channel-input w-full\"\n\t\t\t\t\t\t\t\tvalue={editWebhookSecret.value}\n\t\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\t\teditWebhookSecret.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"flex gap-3\">\n\t\t\t\t\t\t\t<div className=\"flex-1\">\n\t\t\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Streaming</label>\n\t\t\t\t\t\t\t\t<select\n\t\t\t\t\t\t\t\t\tclassName=\"channel-select\"\n\t\t\t\t\t\t\t\t\tvalue={editStreamMode.value}\n\t\t\t\t\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\t\t\t\t\teditStreamMode.value = (e.target as HTMLSelectElement).value;\n\t\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t<option value=\"edit_in_place\">Edit-in-place (live updates)</option>\n\t\t\t\t\t\t\t\t\t<option value=\"off\">Off (send once complete)</option>\n\t\t\t\t\t\t\t\t</select>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<div className=\"flex-1\">\n\t\t\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Reply Style</label>\n\t\t\t\t\t\t\t\t<select\n\t\t\t\t\t\t\t\t\tclassName=\"channel-select\"\n\t\t\t\t\t\t\t\t\tvalue={editReplyStyle.value}\n\t\t\t\t\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\t\t\t\t\teditReplyStyle.value = (e.target as HTMLSelectElement).value;\n\t\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t<option value=\"top_level\">Top-level message</option>\n\t\t\t\t\t\t\t\t\t<option value=\"thread\">Reply in thread</option>\n\t\t\t\t\t\t\t\t</select>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"flex gap-3 items-end\">\n\t\t\t\t\t\t\t<div className=\"flex-1\">\n\t\t\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Bot Name (for welcome card)</label>\n\t\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\t\t\t\t\tvalue={editBotName.value}\n\t\t\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\t\t\teditBotName.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\t\tplaceholder=\"Moltis\"\n\t\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<label className=\"flex items-center gap-2 text-xs text-[var(--muted)] pb-2 cursor-pointer\">\n\t\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\t\ttype=\"checkbox\"\n\t\t\t\t\t\t\t\t\tchecked={editWelcomeCard.value}\n\t\t\t\t\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\t\t\t\t\teditWelcomeCard.value = (e.target as HTMLInputElement).checked;\n\t\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t\tWelcome card\n\t\t\t\t\t\t\t</label>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</>\n\t\t\t\t)}\n\t\t\t\t{isDiscord && (\n\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Bot Token (optional: leave blank to keep existing)</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\ttype=\"password\"\n\t\t\t\t\t\t\tclassName=\"channel-input w-full\"\n\t\t\t\t\t\t\tvalue={editCredential.value}\n\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\teditCredential.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t{isNostr && (\n\t\t\t\t\t<>\n\t\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Secret Key (optional: leave blank to keep existing)</label>\n\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\ttype=\"password\"\n\t\t\t\t\t\t\t\tclassName=\"channel-input w-full\"\n\t\t\t\t\t\t\t\tvalue={editCredential.value}\n\t\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\t\teditCredential.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\tautoComplete=\"new-password\"\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Relays (comma-separated)</label>\n\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\tdata-field=\"relays\"\n\t\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\t\tclassName=\"channel-input w-full\"\n\t\t\t\t\t\t\t\tdefaultValue={((cfg.relays as string[]) || []).join(\", \")}\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</>\n\t\t\t\t)}\n\t\t\t\t{isMatrix && (\n\t\t\t\t\t<div className=\"rounded-md border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-xs text-emerald-100\">\n\t\t\t\t\t\t<div className=\"font-medium text-emerald-50\">Encrypted chats require password auth</div>\n\t\t\t\t\t\t<div>{MATRIX_ENCRYPTION_GUIDANCE}</div>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t{isMatrix && (\n\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Authentication</label>\n\t\t\t\t\t\t<select\n\t\t\t\t\t\t\tclassName=\"channel-select w-full\"\n\t\t\t\t\t\t\tvalue={editMatrixAuthMode.value}\n\t\t\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\t\t\teditMatrixAuthMode.value = normalizeMatrixAuthMode((e.target as HTMLSelectElement).value);\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t<option value=\"access_token\">Access token</option>\n\t\t\t\t\t\t\t<option value=\"password\">Password</option>\n\t\t\t\t\t\t</select>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">{matrixAuthModeGuidance(editMatrixAuthMode.value)}</div>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t{isMatrix && (\n\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t{editMatrixAuthMode.value === \"password\" ? (\n\t\t\t\t\t\t\t<label className=\"flex items-start gap-2 rounded-md border border-[var(--border)] bg-[var(--surface2)] px-3 py-2\">\n\t\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\t\ttype=\"checkbox\"\n\t\t\t\t\t\t\t\t\taria-label=\"Let Moltis own this Matrix account\"\n\t\t\t\t\t\t\t\t\tchecked={normalizeMatrixOwnershipMode(editMatrixOwnershipMode.value) === \"moltis_owned\"}\n\t\t\t\t\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\t\t\t\t\teditMatrixOwnershipMode.value = (e.target as HTMLInputElement).checked\n\t\t\t\t\t\t\t\t\t\t\t? \"moltis_owned\"\n\t\t\t\t\t\t\t\t\t\t\t: \"user_managed\";\n\t\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t\t\t<span className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t\t\t\t<span className=\"text-xs font-medium text-[var(--text-strong)]\">\n\t\t\t\t\t\t\t\t\t\tLet Moltis own this Matrix account\n\t\t\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\t\t\t{matrixOwnershipModeGuidance(editMatrixAuthMode.value, editMatrixOwnershipMode.value)}\n\t\t\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t</label>\n\t\t\t\t\t\t) : (\n\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t\t{matrixOwnershipModeGuidance(editMatrixAuthMode.value, \"user_managed\")}\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t)}\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t{isMatrix && (\n\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Homeserver URL</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tdata-field=\"homeserver\"\n\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\tclassName=\"channel-input w-full\"\n\t\t\t\t\t\t\tdefaultValue={(cfg.homeserver as string) || \"\"}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t{isMatrix && (\n\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\tMatrix User ID{editMatrixAuthMode.value === \"password\" ? \" (required)\" : \" (optional)\"}\n\t\t\t\t\t\t</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tdata-field=\"userId\"\n\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\tclassName=\"channel-input w-full\"\n\t\t\t\t\t\t\tdefaultValue={(cfg.user_id as string) || \"\"}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t{isMatrix && (\n\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t{matrixCredentialLabel(editMatrixAuthMode.value)} (optional: leave blank to keep existing)\n\t\t\t\t\t\t</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\ttype=\"password\"\n\t\t\t\t\t\t\tclassName=\"channel-input w-full\"\n\t\t\t\t\t\t\tvalue={editCredential.value}\n\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\teditCredential.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\tplaceholder={matrixCredentialPlaceholder(editMatrixAuthMode.value)}\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\t{editMatrixAuthMode.value === \"password\" ? (\n\t\t\t\t\t\t\t\t\"Password auth is required for encrypted Matrix chats because Moltis needs its own Matrix device keys.\"\n\t\t\t\t\t\t\t) : (\n\t\t\t\t\t\t\t\t<>\n\t\t\t\t\t\t\t\t\tAccess token mode does <span className=\"font-medium\">not</span> support encrypted Matrix chats because\n\t\t\t\t\t\t\t\t\tMoltis cannot import the existing device's private encryption keys.\n\t\t\t\t\t\t\t\t</>\n\t\t\t\t\t\t\t)}{\" \"}\n\t\t\t\t\t\t\t<a href={MATRIX_DOCS_URL} target=\"_blank\" rel=\"noreferrer\" className=\"text-[var(--accent)] underline\">\n\t\t\t\t\t\t\t\tMatrix setup docs\n\t\t\t\t\t\t\t</a>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t{isMatrix && (\n\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Device Display Name (optional)</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\tclassName=\"channel-input w-full\"\n\t\t\t\t\t\t\tvalue={editMatrixDeviceDisplayName.value}\n\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\teditMatrixDeviceDisplayName.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">DM Policy</label>\n\t\t\t\t<select\n\t\t\t\t\tdata-field=\"dmPolicy\"\n\t\t\t\t\tclassName=\"channel-select\"\n\t\t\t\t\tvalue={(cfg.dm_policy as string) || (isWhatsApp ? \"open\" : \"allowlist\")}\n\t\t\t\t>\n\t\t\t\t\t{isWhatsApp && <option value=\"open\">Open (anyone)</option>}\n\t\t\t\t\t<option value=\"allowlist\">Allowlist only</option>\n\t\t\t\t\t{!isWhatsApp && <option value=\"open\">Open (anyone)</option>}\n\t\t\t\t\t<option value=\"disabled\">Disabled</option>\n\t\t\t\t</select>\n\t\t\t\t{!isWhatsApp && (\n\t\t\t\t\t<>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Group Mention Mode</label>\n\t\t\t\t\t\t<select\n\t\t\t\t\t\t\tdata-field=\"mentionMode\"\n\t\t\t\t\t\t\tclassName=\"channel-select\"\n\t\t\t\t\t\t\tvalue={(cfg.mention_mode as string) || \"mention\"}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t<option value=\"mention\">Must @mention bot</option>\n\t\t\t\t\t\t\t<option value=\"always\">Always respond</option>\n\t\t\t\t\t\t\t<option value=\"none\">Don't respond in groups</option>\n\t\t\t\t\t\t</select>\n\t\t\t\t\t</>\n\t\t\t\t)}\n\t\t\t\t{isMatrix && (\n\t\t\t\t\t<>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Unknown DM Approval</label>\n\t\t\t\t\t\t<select\n\t\t\t\t\t\t\tclassName=\"channel-select\"\n\t\t\t\t\t\t\tvalue={editMatrixOtpSelfApproval.value ? \"on\" : \"off\"}\n\t\t\t\t\t\t\tonChange={(e) => {\n\t\t\t\t\t\t\t\teditMatrixOtpSelfApproval.value = (e.target as HTMLSelectElement).value !== \"off\";\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t<option value=\"on\">PIN challenge enabled (recommended)</option>\n\t\t\t\t\t\t\t<option value=\"off\">Reject unknown DMs without a PIN</option>\n\t\t\t\t\t\t</select>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">PIN Cooldown Seconds</label>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\ttype=\"number\"\n\t\t\t\t\t\t\tmin={1}\n\t\t\t\t\t\t\tstep={1}\n\t\t\t\t\t\t\tclassName=\"channel-input\"\n\t\t\t\t\t\t\tvalue={editMatrixOtpCooldown.value}\n\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\teditMatrixOtpCooldown.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\tWith DM policy on allowlist, unknown users get a 6-digit PIN challenge by default.\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Room Policy</label>\n\t\t\t\t\t\t<select\n\t\t\t\t\t\t\tdata-field=\"roomPolicy\"\n\t\t\t\t\t\t\tclassName=\"channel-select\"\n\t\t\t\t\t\t\tvalue={(cfg.room_policy as string) || \"allowlist\"}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t<option value=\"allowlist\">Room allowlist only</option>\n\t\t\t\t\t\t\t<option value=\"open\">Open (any joined room)</option>\n\t\t\t\t\t\t\t<option value=\"disabled\">Disabled</option>\n\t\t\t\t\t\t</select>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Invite Auto-Join</label>\n\t\t\t\t\t\t<select data-field=\"autoJoin\" className=\"channel-select\" value={(cfg.auto_join as string) || \"always\"}>\n\t\t\t\t\t\t\t<option value=\"always\">Always join invites</option>\n\t\t\t\t\t\t\t<option value=\"allowlist\">Only when inviter or room is allowlisted</option>\n\t\t\t\t\t\t\t<option value=\"off\">Do not auto-join</option>\n\t\t\t\t\t\t</select>\n\t\t\t\t\t</>\n\t\t\t\t)}\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Default Model</label>\n\t\t\t\t<ModelSelect\n\t\t\t\t\tmodels={modelsSig.value}\n\t\t\t\t\tvalue={editModel.value}\n\t\t\t\t\tonChange={(v: string) => {\n\t\t\t\t\t\teditModel.value = v;\n\t\t\t\t\t}}\n\t\t\t\t\tplaceholder={defaultPlaceholder}\n\t\t\t\t/>\n\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">DM Allowlist</label>\n\t\t\t\t<AllowlistInput\n\t\t\t\t\tvalue={allowlistItems.value}\n\t\t\t\t\tpreserveAt={isMatrix}\n\t\t\t\t\tonChange={(v) => {\n\t\t\t\t\t\tallowlistItems.value = v;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t{isMatrix && (\n\t\t\t\t\t<>\n\t\t\t\t\t\t<label className=\"text-xs text-[var(--muted)]\">Room Allowlist</label>\n\t\t\t\t\t\t<AllowlistInput\n\t\t\t\t\t\t\tvalue={roomAllowlistItems.value}\n\t\t\t\t\t\t\tpreserveAt={true}\n\t\t\t\t\t\t\tonChange={(v) => {\n\t\t\t\t\t\t\t\troomAllowlistItems.value = v;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</>\n\t\t\t\t)}\n\t\t\t\t<AdvancedConfigPatchField\n\t\t\t\t\tvalue={editAdvancedConfigPatch.value}\n\t\t\t\t\tonInput={(value) => {\n\t\t\t\t\t\teditAdvancedConfigPatch.value = value;\n\t\t\t\t\t}}\n\t\t\t\t\tcurrentConfig={cfg}\n\t\t\t\t/>\n\t\t\t\t{error.value && <div className=\"text-xs text-[var(--error)] py-1\">{error.value}</div>}\n\t\t\t\t<button className=\"provider-btn\" onClick={onSave} disabled={saving.value}>\n\t\t\t\t\t{saving.value ? \"Saving\\u2026\" : \"Save Changes\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</Modal>\n\t);\n}\n\n// ── Channel event handlers ───────────────────────────────────\n\nfunction handleWhatsAppPairingEvent(p: ChannelEvent): void {\n\tif (p.kind === \"pairing_qr_code\" && p.account_id === waPairingAccountId.value) {\n\t\twaQrData.value = p.qr_data || null;\n\t\twaQrSvg.value = p.qr_svg || null;\n\t}\n\tif (p.kind === \"pairing_complete\" && p.account_id === waPairingAccountId.value) {\n\t\tshowToast(\"WhatsApp connected!\");\n\t\tshowAddWhatsApp.value = false;\n\t\twaPairingAccountId.value = null;\n\t\twaQrData.value = null;\n\t\twaQrSvg.value = null;\n\t\tloadChannels();\n\t}\n\tif (p.kind === \"pairing_failed\" && p.account_id === waPairingAccountId.value) {\n\t\twaPairingError.value = p.reason || \"Pairing failed\";\n\t}\n}\n\nfunction handleChannelEvent(_payload: unknown): void {\n\tconst p = _payload as ChannelEvent;\n\tif (p.kind === \"otp_resolved\") {\n\t\tloadChannels();\n\t}\n\thandleWhatsAppPairingEvent(p);\n\tif (p.kind === \"pairing_complete\" || p.kind === \"account_disabled\") {\n\t\tloadChannels();\n\t}\n\tconst selected = parseSenderSelectionKey(sendersAccount.value || \"\");\n\tif (\n\t\tactiveTab.value === \"senders\" &&\n\t\tselected.account_id === p.account_id &&\n\t\tselected.type === channelType(p.channel_type) &&\n\t\t(p.kind === \"inbound_message\" || p.kind === \"otp_challenge\" || p.kind === \"otp_resolved\")\n\t) {\n\t\tloadSenders();\n\t}\n}\n\n// ── Main page component ──────────────────────────────────────\n\nfunction ChannelsPageComponent(): VNode {\n\tuseEffect(() => {\n\t\tS.setRefreshChannelsPage(loadChannels);\n\t\t// Use prefetched cache for instant render\n\t\tif (S.cachedChannels !== null) channels.value = S.cachedChannels as Channel[];\n\t\tif (connected.value) loadChannels();\n\n\t\tconst unsub = onEvent(\"channel\", handleChannelEvent);\n\t\tS.setChannelEventUnsub(unsub);\n\n\t\treturn () => {\n\t\t\tS.setRefreshChannelsPage(null);\n\t\t\tif (unsub) unsub();\n\t\t\tS.setChannelEventUnsub(null);\n\t\t};\n\t}, [connected.value]);\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<div className=\"flex items-center gap-3 flex-wrap\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Channels</h2>\n\t\t\t\t<div style={{ display: \"flex\", gap: \"4px\", marginLeft: \"12px\" }}>\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"session-action-btn\"\n\t\t\t\t\t\tstyle={activeTab.value === \"channels\" ? { fontWeight: 600 } : undefined}\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tactiveTab.value = \"channels\";\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\tChannels\n\t\t\t\t\t</button>\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"session-action-btn\"\n\t\t\t\t\t\tstyle={activeTab.value === \"senders\" ? { fontWeight: 600 } : undefined}\n\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\tactiveTab.value = \"senders\";\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\tSenders\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t\t{activeTab.value === \"channels\" && channels.value.length > 0 && <ConnectButtons />}\n\t\t\t</div>\n\t\t\t{activeTab.value === \"channels\" && <ChannelStorageNotice />}\n\t\t\t{activeTab.value === \"channels\" ? <ChannelsTab /> : <SendersTab />}\n\t\t\t<AddTelegramModal />\n\t\t\t<AddTeamsModal />\n\t\t\t<AddDiscordModal />\n\t\t\t<AddSlackModal />\n\t\t\t<AddMatrixModal />\n\t\t\t<AddNostrModal />\n\t\t\t<AddWhatsAppModal />\n\t\t\t<EditChannelModal />\n\t\t\t<ConfirmDialog />\n\t\t</div>\n\t);\n}\n\n// ── Mount / unmount exports ──────────────────────────────────\n\nlet _channelsContainer: HTMLElement | null = null;\n\nexport function initChannels(container: HTMLElement): void {\n\t_channelsContainer = container;\n\tcontainer.style.cssText = \"flex-direction:column;padding:0;overflow:hidden;\";\n\tactiveTab.value = \"channels\";\n\tshowAddTelegram.value = false;\n\tshowAddTeams.value = false;\n\tshowAddDiscord.value = false;\n\tshowAddSlack.value = false;\n\tshowAddMatrix.value = false;\n\tshowAddNostr.value = false;\n\tshowAddWhatsApp.value = false;\n\teditingChannel.value = null;\n\tsendersAccount.value = \"\";\n\tsenders.value = [];\n\trender(<ChannelsPageComponent />, container);\n}\n\nexport function teardownChannels(): void {\n\tS.setRefreshChannelsPage(null);\n\tif (S.channelEventUnsub) {\n\t\tS.channelEventUnsub();\n\t\tS.setChannelEventUnsub(null);\n\t}\n\tif (_channelsContainer) render(null, _channelsContainer);\n\t_channelsContainer = null;\n}\n","// ── WebSocket event types (discriminated union) ──────────────\n\n/** All WebSocket event names emitted by the moltis gateway. */\nexport enum WsEventName {\n\tChat = \"chat\",\n\tError = \"error\",\n\tAuthCredentialsChanged = \"auth.credentials_changed\",\n\tExecApprovalRequested = \"exec.approval.requested\",\n\tLogsEntry = \"logs.entry\",\n\tSandboxPrepare = \"sandbox.prepare\",\n\tSandboxImageBuild = \"sandbox.image.build\",\n\tSandboxImageProvision = \"sandbox.image.provision\",\n\tSandboxHostProvision = \"sandbox.host.provision\",\n\tBrowserImagePull = \"browser.image.pull\",\n\tLocalLlmDownload = \"local-llm.download\",\n\tModelsUpdated = \"models.updated\",\n\tLocationRequest = \"location.request\",\n\tNetworkAuditEntry = \"network.audit.entry\",\n\t// Additional onEvent() events\n\tTick = \"tick\",\n\tSession = \"session\",\n\tChannel = \"channel\",\n\tPresence = \"presence\",\n\tUpdateAvailable = \"update.available\",\n\tMcpStatus = \"mcp.status\",\n\tHooksStatus = \"hooks.status\",\n\tMetricsUpdate = \"metrics.update\",\n\tSkillsInstallProgress = \"skills.install.progress\",\n\tPushSubscriptions = \"push.subscriptions\",\n\tNodePairRequested = \"node.pair.requested\",\n\tNodePairResolved = \"node.pair.resolved\",\n\tDevicePairResolved = \"device.pair.resolved\",\n\tNodeTelemetry = \"node.telemetry\",\n}\n\n// ── Payload interfaces ───────────────────────────────────────\n\nexport interface ToolResult {\n\tstdout?: string;\n\tstderr?: string;\n\texit_code?: number;\n\tscreenshot?: string;\n\tscreenshot_scale?: number;\n\tdocument_ref?: string;\n\tfilename?: string;\n\tmime_type?: string;\n\tsize_bytes?: number;\n\tpoints?: MapPoint[];\n\tlabel?: string;\n\tmap_links?: MapLinks;\n}\n\nexport interface ToolError {\n\tdetail?: string;\n\tmessage?: string;\n\tretryAfterMs?: number;\n\ttype?: string;\n}\n\nexport interface MapLinks {\n\turl?: string;\n\tgoogle_maps?: string;\n\tapple_maps?: string;\n\topenstreetmap?: string;\n\t[key: string]: unknown;\n}\n\nexport interface MapPoint {\n\tlabel?: string;\n\tlatitude?: number;\n\tlongitude?: number;\n\tmap_links?: MapLinks;\n}\n\nexport interface ToolCallPayload {\n\trunId?: string;\n\ttoolCallId?: string;\n\ttoolName?: string;\n\targuments?: Record<string, unknown>;\n\texecutionMode?: string;\n\tmessageIndex?: number;\n\tsessionKey?: string;\n\tsuccess?: boolean;\n\tresult?: ToolResult;\n\terror?: ToolError;\n}\n\nexport interface ChatError {\n\ttitle?: string;\n\tdetail?: string;\n\tmessage?: string;\n\ttype?: string;\n\tretryAfterMs?: number;\n\tcanContinue?: boolean;\n}\n\nexport interface ChannelInfo {\n\taudio_filename?: string;\n\t[key: string]: unknown;\n}\n\nexport interface PartialMessage {\n\tcontent?: string;\n\treasoning?: string;\n\tmodel?: string;\n\tprovider?: string;\n\tinputTokens?: number;\n\toutputTokens?: number;\n\tdurationMs?: number;\n\trequestInputTokens?: number;\n\trequestOutputTokens?: number;\n\trequestCacheReadTokens?: number;\n\trequestCacheWriteTokens?: number;\n\taudio?: string;\n\trun_id?: string;\n\tcreated_at?: number;\n}\n\nexport interface ChatPayload {\n\tstate?: string;\n\tsessionKey?: string;\n\trunId?: string;\n\ttext?: string;\n\tmodel?: string;\n\tprovider?: string;\n\tinputTokens?: number;\n\toutputTokens?: number;\n\tcacheReadTokens?: number;\n\tcacheWriteTokens?: number;\n\tdurationMs?: number;\n\trequestInputTokens?: number;\n\trequestOutputTokens?: number;\n\trequestCacheReadTokens?: number;\n\trequestCacheWriteTokens?: number;\n\treasoning?: string;\n\taudio?: string;\n\taudioWarning?: string | null;\n\treplyMedium?: string;\n\tmessageIndex?: number;\n\ttoolCallId?: string;\n\ttoolName?: string;\n\targuments?: Record<string, unknown>;\n\texecutionMode?: string;\n\tsuccess?: boolean;\n\tresult?: ToolResult;\n\terror?: ChatError;\n\tmessage?: string;\n\tchannel?: ChannelInfo;\n\ttitle?: string;\n\tphase?: string;\n\tmode?: string;\n\tseq?: number;\n\tretryAfterMs?: number;\n\tpartialMessage?: PartialMessage;\n\tcanContinue?: boolean;\n}\n\nexport interface CompactPayload {\n\tsessionKey?: string;\n\tphase?: string;\n\terror?: string;\n\tmode?: string;\n\t[key: string]: unknown;\n}\n\nexport interface ApprovalPayload {\n\trequestId: string;\n\tcommand: string;\n}\n\nexport interface LogEntryPayload {\n\tlevel?: string;\n\t[key: string]: unknown;\n}\n\nexport interface SandboxPhasePayload {\n\tphase?: string;\n\terror?: string;\n\ttag?: string;\n\tbuilt?: boolean;\n\tcount?: number;\n\tinstalled?: number;\n\tskipped?: number;\n\timage?: string;\n}\n\nexport interface LocalLlmDownloadPayload {\n\tdisplayName?: string;\n\tmodelId?: string;\n\terror?: string;\n\tcomplete?: boolean;\n\tprogress?: number;\n\tdownloaded?: number;\n\ttotal?: number;\n}\n\nexport interface ModelsUpdatedPayload {\n\tphase?: string;\n\t[key: string]: unknown;\n}\n\nexport interface WsErrorPayload {\n\tmessage?: string;\n}\n\nexport interface LocationRequestPayload {\n\trequestId?: string;\n\tprecision?: string;\n}\n\nexport interface AuthCredentialsPayload {\n\treason?: string;\n}\n\nexport interface WsFrame {\n\ttype: string;\n\tevent?: string;\n\tpayload?: Record<string, unknown>;\n\tstream?: unknown;\n\tdone?: unknown;\n\tchannel?: unknown;\n}\n\nexport interface StreamMeta {\n\tstream: unknown;\n\tdone: unknown;\n\tchannel: unknown;\n}\n\nexport interface AbortedPartialState {\n\tpartial: PartialMessage | null;\n\tpartialText: string;\n\tpartialReasoning: string;\n\thasVisiblePartial: boolean;\n}\n\n/** Maps event names to their payload types. */\nexport interface WsEventPayloadMap {\n\t[WsEventName.Chat]: ChatPayload;\n\t[WsEventName.Error]: WsErrorPayload;\n\t[WsEventName.AuthCredentialsChanged]: AuthCredentialsPayload;\n\t[WsEventName.ExecApprovalRequested]: ApprovalPayload;\n\t[WsEventName.LogsEntry]: LogEntryPayload;\n\t[WsEventName.SandboxPrepare]: SandboxPhasePayload;\n\t[WsEventName.SandboxImageBuild]: SandboxPhasePayload;\n\t[WsEventName.SandboxImageProvision]: SandboxPhasePayload;\n\t[WsEventName.SandboxHostProvision]: SandboxPhasePayload;\n\t[WsEventName.BrowserImagePull]: SandboxPhasePayload;\n\t[WsEventName.LocalLlmDownload]: LocalLlmDownloadPayload;\n\t[WsEventName.ModelsUpdated]: ModelsUpdatedPayload;\n\t[WsEventName.LocationRequest]: LocationRequestPayload;\n\t[WsEventName.NetworkAuditEntry]: Record<string, unknown>;\n\t[WsEventName.Tick]: Record<string, unknown>;\n\t[WsEventName.Session]: Record<string, unknown>;\n\t[WsEventName.Channel]: Record<string, unknown>;\n\t[WsEventName.Presence]: Record<string, unknown>;\n\t[WsEventName.UpdateAvailable]: Record<string, unknown>;\n\t[WsEventName.McpStatus]: Record<string, unknown>;\n\t[WsEventName.HooksStatus]: Record<string, unknown>;\n\t[WsEventName.MetricsUpdate]: Record<string, unknown>;\n\t[WsEventName.SkillsInstallProgress]: Record<string, unknown>;\n\t[WsEventName.PushSubscriptions]: Record<string, unknown>;\n\t[WsEventName.NodePairRequested]: Record<string, unknown>;\n\t[WsEventName.NodePairResolved]: Record<string, unknown>;\n\t[WsEventName.DevicePairResolved]: Record<string, unknown>;\n\t[WsEventName.NodeTelemetry]: Record<string, unknown>;\n}\n","// ── WebSocket ─────────────────────────────────────────────────\n\nimport {\n\tappendChannelFooter,\n\tappendReasoningDisclosure,\n\tchatAddErrorCard,\n\tchatAddErrorMsg,\n\tchatAddMsg,\n\tremoveThinking,\n\trenderApprovalCard,\n\tstripChannelPrefix,\n\tupdateTokenBar,\n} from \"./chat-ui\";\nimport { highlightCodeBlocks } from \"./code-highlight\";\nimport { eventListeners } from \"./events\";\nimport {\n\tformatAssistantTokenUsage,\n\tformatTokenSpeed,\n\tlocalizeStructuredError,\n\trenderAudioPlayer,\n\trenderDocument,\n\trenderMapLinks,\n\trenderMapPointGroups,\n\trenderMarkdown,\n\trenderScreenshot,\n\tsendRpc,\n\ttokenSpeedTone,\n\ttoolCallSummary,\n} from \"./helpers\";\nimport { t } from \"./i18n\";\nimport { clearLogsAlert, updateLogsAlert } from \"./logs-alert\";\nimport { attachMessageVoiceControl } from \"./message-voice\";\nimport { fetchModels } from \"./models\";\nimport { prefetchChannels } from \"./pages/ChannelsPage\";\nimport { maybeRefreshFullContext, renderCompactCard } from \"./pages/ChatPage\";\nimport { fetchProjects } from \"./projects\";\nimport { currentPage, currentPrefix, mount, navigate } from \"./router\";\nimport {\n\tappendLastMessageTimestamp,\n\tbumpSessionCount,\n\tcacheSessionHistoryMessage,\n\tclearSessionHistoryCache,\n\tfetchSessions,\n\tmarkSessionLocallyCleared,\n\tsetSessionActiveRunId,\n\tsetSessionReplying,\n\tsetSessionUnread,\n} from \"./sessions\";\nimport * as S from \"./state\";\nimport { sessionStore } from \"./stores/session-store\";\nimport type {\n\tAbortedPartialState,\n\tApprovalPayload,\n\tAuthCredentialsPayload,\n\tChatPayload,\n\tCompactPayload,\n\tLocalLlmDownloadPayload,\n\tLocationRequestPayload,\n\tLogEntryPayload,\n\tModelsUpdatedPayload,\n\tSandboxPhasePayload,\n\tStreamMeta,\n\tToolCallPayload,\n\tToolResult,\n\tWsErrorPayload,\n\tWsFrame,\n} from \"./types/ws-events\";\nimport { WsEventName } from \"./types/ws-events\";\nimport type { ConnectOptions } from \"./ws-connect\";\nimport { connectWs, forceReconnect, subscribeEvents } from \"./ws-connect\";\n\ntype ChatHandler = (p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string) => void;\n\n// Extend Window for moltis-specific global\ndeclare global {\n\tinterface Window {\n\t\t__moltisSuppressNextPasswordChangedRedirect?: boolean;\n\t}\n}\n\n// ── Chat event handlers ──────────────────────────────────────\n\nconst pendingToolCallEnds: Map<string, ToolCallPayload> = new Map();\nlet hasConnectedOnce = false;\n\nfunction clearChatEmptyState(): void {\n\tif (!S.chatMsgBox) return;\n\tconst welcome = S.chatMsgBox.querySelector(\"#welcomeCard\");\n\tif (welcome) welcome.remove();\n\tconst noProviders = S.chatMsgBox.querySelector(\"#noProvidersCard\");\n\tif (noProviders) noProviders.remove();\n\tS.chatMsgBox.classList.remove(\"chat-messages-empty\");\n}\n\nfunction toolCallLogicalId(payload: ToolCallPayload | null | undefined): string {\n\tif (!payload) return \"\";\n\tif (payload.runId) return `${payload.runId}:${payload.toolCallId}`;\n\treturn String(payload.toolCallId || \"\");\n}\n\nfunction toolCallCardId(payload: ToolCallPayload | ChatPayload | null | undefined): string {\n\tif ((payload as ToolCallPayload)?.runId) {\n\t\treturn `tool-${(payload as ToolCallPayload).runId}-${(payload as ToolCallPayload).toolCallId}`;\n\t}\n\treturn `tool-${(payload as ToolCallPayload)?.toolCallId}`;\n}\n\nfunction toolCallEventKey(eventSession: string, payload: ToolCallPayload | ChatPayload | null | undefined): string {\n\treturn `${eventSession}:${toolCallLogicalId(payload as ToolCallPayload)}`;\n}\n\nfunction clearPendingToolCallEndsForSession(sessionKey: string): void {\n\tconst prefix = `${sessionKey}:`;\n\tfor (const key of pendingToolCallEnds.keys()) {\n\t\tif (key.startsWith(prefix)) {\n\t\t\tpendingToolCallEnds.delete(key);\n\t\t}\n\t}\n}\n\nfunction makeThinkingDots(): Element {\n\tconst tpl = document.getElementById(\"tpl-thinking-dots\") as HTMLTemplateElement;\n\treturn (tpl.content.cloneNode(true) as DocumentFragment).firstElementChild!;\n}\n\nfunction updateSessionRunId(sessionKey: string, runId: string | undefined): void {\n\tif (!runId) return;\n\tsetSessionActiveRunId(sessionKey, runId);\n}\n\nfunction updateSessionHistoryIndex(sessionKey: string, messageIndex: number | undefined): void {\n\tconst idx = Number(messageIndex);\n\tif (!Number.isInteger(idx) || idx < 0) return;\n\tconst session = sessionStore.getByKey(sessionKey);\n\tif (session && idx > session.lastHistoryIndex.value) {\n\t\tsession.lastHistoryIndex.value = idx;\n\t}\n\tif (sessionKey === sessionStore.activeSessionKey.value && idx > S.lastHistoryIndex) {\n\t\tS.setLastHistoryIndex(idx);\n\t}\n}\n\nfunction moveFirstQueuedToChat(): void {\n\tconst tray = document.getElementById(\"queuedMessages\");\n\tif (!tray) return;\n\tconst firstQueued = tray.querySelector(\".msg.user.queued\");\n\tif (!firstQueued) return;\n\tconsole.debug(\"[queued] moving queued message from tray to chat\", {\n\t\tremaining: tray.querySelectorAll(\".msg\").length - 1,\n\t});\n\tfirstQueued.classList.remove(\"queued\");\n\tconst badge = firstQueued.querySelector(\".queued-badge\");\n\tif (badge) badge.remove();\n\tclearChatEmptyState();\n\tS.chatMsgBox!.appendChild(firstQueued);\n\tif (!tray.querySelector(\".msg\")) tray.classList.add(\"hidden\");\n}\n\nfunction makeThinkingStopBtn(sessionKey: string): HTMLButtonElement {\n\tconst btn = document.createElement(\"button\");\n\tbtn.className = \"thinking-stop-btn\";\n\tbtn.type = \"button\";\n\tbtn.title = \"Stop generation\";\n\tbtn.textContent = \"Stop\";\n\tbtn.addEventListener(\"click\", () => {\n\t\tbtn.disabled = true;\n\t\tbtn.textContent = \"Stopping\\u2026\";\n\t\tsendRpc(\"chat.abort\", { sessionKey }).catch(() => undefined);\n\t});\n\treturn btn;\n}\n\nfunction handleChatThinking(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tupdateSessionRunId(eventSession, p.runId);\n\tsetSessionReplying(eventSession, true);\n\tif (!(isActive && isChatPage)) return;\n\tremoveThinking();\n\tclearChatEmptyState();\n\tconst thinkEl = document.createElement(\"div\");\n\tthinkEl.className = \"msg assistant thinking\";\n\tthinkEl.id = \"thinkingIndicator\";\n\tthinkEl.appendChild(makeThinkingDots());\n\tthinkEl.appendChild(makeThinkingStopBtn(eventSession));\n\tS.chatMsgBox!.appendChild(thinkEl);\n\tS.chatMsgBox!.scrollTop = S.chatMsgBox!.scrollHeight;\n}\n\nfunction handleChatThinkingText(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tupdateSessionRunId(eventSession, p.runId);\n\tsetSessionReplying(eventSession, true);\n\tif (!(isActive && isChatPage)) return;\n\tconst indicator = document.getElementById(\"thinkingIndicator\");\n\tif (indicator) {\n\t\tconst existingBtn = indicator.querySelector(\".thinking-stop-btn\");\n\t\twhile (indicator.firstChild) indicator.removeChild(indicator.firstChild);\n\t\tconst textEl = document.createElement(\"span\");\n\t\ttextEl.className = \"thinking-text\";\n\t\ttextEl.textContent = p.text || \"\";\n\t\tindicator.appendChild(textEl);\n\t\tindicator.appendChild(existingBtn || makeThinkingStopBtn(eventSession));\n\t\tS.chatMsgBox!.scrollTop = S.chatMsgBox!.scrollHeight;\n\t}\n}\n\nfunction handleChatThinkingDone(_p: ChatPayload, isActive: boolean, isChatPage: boolean): void {\n\t// Don't remove the thinking indicator here. It will be removed by either:\n\t// - handleChatDelta (when text starts streaming)\n\t// - handleChatToolCallStart (which preserves thinking text as a disclosure)\n\t// - handleChatFinal / handleChatError (cleanup)\n\t// This keeps the thinking text visible until we know whether to preserve it.\n\tvoid (isActive && isChatPage);\n}\n\nfunction handleChatVoicePending(_p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\t// Update per-session signal\n\tconst session = sessionStore.getByKey(eventSession);\n\tif (session) session.voicePending.value = true;\n\tif (!(isActive && isChatPage)) return;\n\t// Dual-write to global state for backward compat\n\tS.setVoicePending(true);\n\t// Keep the existing thinking dots visible — no separate voice indicator.\n}\n\n/** Check whether a reasoning disclosure with the given text already exists in\n * the chat box (from a previous preserveThinkingAsDisclosure call). */\nfunction isReasoningAlreadyShown(text: string | null | undefined): boolean {\n\tif (!(S.chatMsgBox && text)) return false;\n\tconst normalized = text.trim();\n\tfor (const el of S.chatMsgBox.querySelectorAll(\".msg-reasoning-body\")) {\n\t\tif (el.textContent?.trim() === normalized) return true;\n\t}\n\treturn false;\n}\n\n/** Extract thinking text from the indicator before it is removed. Returns the\n * trimmed text or null if the indicator has no thinking content. */\nfunction extractThinkingText(): string | null {\n\tconst indicator = document.getElementById(\"thinkingIndicator\");\n\tif (!indicator) return null;\n\tconst textEl = indicator.querySelector(\".thinking-text\");\n\tconst text = textEl?.textContent?.trim();\n\treturn text || null;\n}\n\nfunction handleChatToolCallStart(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tupdateSessionRunId(eventSession, p.runId);\n\t// Update per-session signal\n\tconst session = sessionStore.getByKey(eventSession);\n\tif (session) session.streamText.value = \"\";\n\tif (!(isActive && isChatPage)) return;\n\tconst thinkingText = extractThinkingText();\n\tremoveThinking();\n\t// Close the current streaming element so new text deltas after this tool\n\t// call will create a fresh element positioned after the tool card\n\tif (S.streamEl) {\n\t\t// Remove the element if it's empty (e.g. only whitespace from a\n\t\t// pre-tool-call delta) to avoid leaving an orphaned empty div.\n\t\tif (!S.streamEl.textContent?.trim()) {\n\t\t\tS.streamEl.remove();\n\t\t}\n\t\tS.setStreamEl(null);\n\t\tS.setStreamText(\"\");\n\t}\n\tconst cardId = toolCallCardId(p);\n\tif (document.getElementById(cardId)) return;\n\tconst tpl = document.getElementById(\"tpl-exec-card\") as HTMLTemplateElement;\n\tconst frag = tpl.content.cloneNode(true) as DocumentFragment;\n\tconst card = frag.firstElementChild as HTMLElement;\n\tcard.id = cardId;\n\tconst cmd = toolCallSummary(p.toolName, p.arguments, p.executionMode);\n\tconst cmdEl = card.querySelector(\"[data-cmd]\");\n\tif (cmdEl) cmdEl.textContent = ` ${cmd}`;\n\t// Preserve thinking text as a reasoning disclosure inside the tool card\n\tif (thinkingText) appendReasoningDisclosure(card, thinkingText);\n\tclearChatEmptyState();\n\tS.chatMsgBox!.appendChild(card);\n\tconst endKey = toolCallEventKey(eventSession, p);\n\tconst pendingEnd = pendingToolCallEnds.get(endKey);\n\tif (pendingEnd) {\n\t\tpendingToolCallEnds.delete(endKey);\n\t\tcompleteToolCard(card, pendingEnd as ChatPayload, eventSession);\n\t}\n\tS.chatMsgBox!.scrollTop = S.chatMsgBox!.scrollHeight;\n}\n\nfunction appendToolResult(toolCard: HTMLElement, result: ToolResult, eventSession: string): void {\n\tconst out = (result.stdout || \"\").replace(/\\n+$/, \"\");\n\t// Update per-session signal\n\tconst toolSession = sessionStore.getByKey(eventSession);\n\tif (toolSession) toolSession.lastToolOutput.value = out;\n\t// Dual-write to global state for backward compat\n\tS.setLastToolOutput(out);\n\tif (out) {\n\t\tconst outEl = document.createElement(\"pre\");\n\t\toutEl.className = \"exec-output\";\n\t\toutEl.textContent = out;\n\t\ttoolCard.appendChild(outEl);\n\t}\n\tconst stderrText = (result.stderr || \"\").replace(/\\n+$/, \"\");\n\tif (stderrText) {\n\t\tconst errEl = document.createElement(\"pre\");\n\t\terrEl.className = \"exec-output exec-stderr\";\n\t\terrEl.textContent = stderrText;\n\t\ttoolCard.appendChild(errEl);\n\t}\n\tif (result.exit_code !== undefined && result.exit_code !== 0) {\n\t\tconst codeEl = document.createElement(\"div\");\n\t\tcodeEl.className = \"exec-exit\";\n\t\tcodeEl.textContent = `exit ${result.exit_code}`;\n\t\ttoolCard.appendChild(codeEl);\n\t}\n\t// Browser screenshot support - display as thumbnail with lightbox and download\n\tif (result.screenshot) {\n\t\tconst imgSrc = result.screenshot.startsWith(\"data:\")\n\t\t\t? result.screenshot\n\t\t\t: `data:image/png;base64,${result.screenshot}`;\n\t\trenderScreenshot(toolCard, imgSrc, result.screenshot_scale || 1);\n\t}\n\t// Document card (send_document tool)\n\tif (result.document_ref) {\n\t\tconst docStoredName = result.document_ref.split(\"/\").pop() || \"\";\n\t\tconst docDisplayName = result.filename || docStoredName;\n\t\tconst docSessionKey = eventSession || S.activeSessionKey || \"main\";\n\t\tconst docMediaSrc = `/api/sessions/${encodeURIComponent(docSessionKey)}/media/${encodeURIComponent(docStoredName)}`;\n\t\trenderDocument(toolCard, docMediaSrc, docDisplayName, result.mime_type, result.size_bytes);\n\t}\n\t// Map link buttons (show_map tool)\n\tconst renderedPointGroups = renderMapPointGroups(toolCard, result.points, result.label);\n\tif (!renderedPointGroups && result.map_links) {\n\t\trenderMapLinks(toolCard, result.map_links, result.label);\n\t}\n}\n\nfunction isToolValidationErrorPayload(p: ChatPayload): boolean {\n\tif (!(p && !p.success && p.error && p.error.detail)) return false;\n\tconst errDetail = p.error.detail.toLowerCase();\n\treturn (\n\t\terrDetail.includes(\"missing field\") ||\n\t\terrDetail.includes(\"missing required\") ||\n\t\terrDetail.includes(\"missing 'action'\") ||\n\t\terrDetail.includes(\"missing 'url'\")\n\t);\n}\n\nfunction completeToolCard(toolCard: HTMLElement, p: ChatPayload, eventSession: string): void {\n\t// Use muted \"retry\" style for validation errors, normal styles otherwise.\n\tif (isToolValidationErrorPayload(p)) {\n\t\ttoolCard.className = \"msg exec-card exec-retry\";\n\t} else {\n\t\ttoolCard.className = `msg exec-card ${p.success ? \"exec-ok\" : \"exec-err\"}`;\n\t}\n\n\tconst toolSpin = toolCard.querySelector(\".exec-status\");\n\tif (toolSpin) toolSpin.remove();\n\n\tif (p.success && p.result) {\n\t\tappendToolResult(toolCard, p.result, eventSession);\n\t\treturn;\n\t}\n\tif (!p.success && p.error && p.error.detail) {\n\t\tconst errMsg = document.createElement(\"div\");\n\t\terrMsg.className = isToolValidationErrorPayload(p) ? \"exec-retry-detail\" : \"exec-error-detail\";\n\t\terrMsg.textContent = p.error.detail;\n\t\ttoolCard.appendChild(errMsg);\n\t}\n\t// Show a hint below the card when a skill is created or updated.\n\tif (p.success && (p.toolName === \"create_skill\" || p.toolName === \"update_skill\")) {\n\t\tconst hint = document.createElement(\"div\");\n\t\thint.className = \"skill-hint\";\n\t\tconst verb = p.toolName === \"create_skill\" ? \"created\" : \"updated\";\n\t\tconst link = document.createElement(\"a\");\n\t\tlink.href = \"/skills\";\n\t\tlink.textContent = \"personal skills\";\n\t\tlink.addEventListener(\"click\", (e: MouseEvent) => {\n\t\t\te.preventDefault();\n\t\t\tnavigate(\"/skills\");\n\t\t});\n\t\thint.append(`Skill ${verb} \\u2014 available in your `, link);\n\t\ttoolCard.appendChild(hint);\n\t}\n}\n\nfunction clearStaleRunningToolCards(): void {\n\tif (!S.chatMsgBox) return;\n\tconst statusEls = S.chatMsgBox.querySelectorAll(\".msg.exec-card .exec-status\");\n\tfor (const statusEl of statusEls) {\n\t\tconst card = statusEl.closest(\".msg.exec-card\") as HTMLElement | null;\n\t\tstatusEl.remove();\n\t\tif (!card) continue;\n\t\tif (!(card.classList.contains(\"exec-ok\") || card.classList.contains(\"exec-err\"))) {\n\t\t\tcard.className = \"msg exec-card exec-ok\";\n\t\t}\n\t}\n}\n\nfunction handleChatToolCallEnd(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tupdateSessionRunId(eventSession, p.runId);\n\t// Always bump badge — the server persists both the hidden assistant\n\t// tool-call frame and the visible tool_result for each completed call.\n\tbumpSessionCount(eventSession, 2);\n\tlet toolHistoryIndex: number | undefined | null = p.messageIndex;\n\tif (toolHistoryIndex === undefined || toolHistoryIndex === null) {\n\t\tconst toolSession = sessionStore.getByKey(eventSession);\n\t\tif (toolSession && typeof toolSession.messageCount === \"number\" && toolSession.messageCount > 0) {\n\t\t\ttoolHistoryIndex = toolSession.messageCount - 1;\n\t\t}\n\t}\n\tcacheSessionHistoryMessage(\n\t\teventSession,\n\t\t{\n\t\t\trole: \"tool_result\",\n\t\t\ttool_call_id: p.toolCallId || \"\",\n\t\t\ttool_name: p.toolName || \"\",\n\t\t\tsuccess: p.success === true,\n\t\t\tresult: p.result || null,\n\t\t\terror:\n\t\t\t\tp.error?.detail || p.error?.message || (typeof p.error === \"string\" ? (p.error as unknown as string) : null),\n\t\t\tcreated_at: Date.now(),\n\t\t},\n\t\ttoolHistoryIndex as number | undefined,\n\t);\n\tupdateSessionHistoryIndex(eventSession, toolHistoryIndex as number | undefined);\n\tif (!(isActive && isChatPage)) return;\n\tconst toolCard = document.getElementById(toolCallCardId(p));\n\tif (!toolCard) {\n\t\tpendingToolCallEnds.set(toolCallEventKey(eventSession, p), p as unknown as ToolCallPayload);\n\t\treturn;\n\t}\n\tcompleteToolCard(toolCard, p, eventSession);\n}\n\nfunction handleChatChannelUser(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\t// Always bump the badge so the total message count stays accurate,\n\t// even when the user is not on the chat page (e.g. Telegram messages).\n\tbumpSessionCount(eventSession, 1);\n\tconst cachedAudio = p.channel?.audio_filename\n\t\t? `media/${eventSession.replaceAll(\":\", \"_\")}/${p.channel.audio_filename}`\n\t\t: undefined;\n\tcacheSessionHistoryMessage(\n\t\teventSession,\n\t\t{\n\t\t\trole: \"user\",\n\t\t\tcontent: p.text || \"\",\n\t\t\tchannel: p.channel || null,\n\t\t\taudio: cachedAudio,\n\t\t\tcreated_at: Date.now(),\n\t\t},\n\t\tp.messageIndex,\n\t);\n\tif (!isActive) {\n\t\tsetSessionUnread(eventSession, true);\n\t}\n\tif (!(isChatPage && isActive)) {\n\t\tupdateSessionHistoryIndex(eventSession, p.messageIndex);\n\t\treturn;\n\t}\n\t// Compare against the per-session history index, not the global one,\n\t// to avoid skipping events when viewing a different session.\n\tconst chanSession = sessionStore.getByKey(p.sessionKey || S.activeSessionKey);\n\tconst chanLastIdx = chanSession ? chanSession.lastHistoryIndex.value : S.lastHistoryIndex;\n\tif (p.messageIndex !== undefined && p.messageIndex <= chanLastIdx) return;\n\tupdateSessionHistoryIndex(eventSession, p.messageIndex);\n\tconst cleanText = stripChannelPrefix(p.text || \"\");\n\tconst sessionKey = p.sessionKey || S.activeSessionKey;\n\tconst audioFilename = p.channel?.audio_filename;\n\tlet el: HTMLElement | null;\n\tif (audioFilename) {\n\t\tel = chatAddMsg(\"user\", \"\", true);\n\t\tif (el) {\n\t\t\tconst audioSrc = `/api/sessions/${encodeURIComponent(sessionKey)}/media/${encodeURIComponent(audioFilename)}`;\n\t\t\trenderAudioPlayer(el, audioSrc);\n\t\t\tif (cleanText) {\n\t\t\t\tconst textWrap = document.createElement(\"div\");\n\t\t\t\ttextWrap.className = \"mt-2\";\n\t\t\t\t// Safe: renderMarkdown calls esc() first — all user input is\n\t\t\t\t// HTML-escaped before formatting tags are applied.\n\t\t\t\ttextWrap.innerHTML = renderMarkdown(cleanText); // eslint-disable-line no-unsanitized/property\n\t\t\t\tel.appendChild(textWrap);\n\t\t\t}\n\t\t}\n\t} else {\n\t\tel = chatAddMsg(\"user\", renderMarkdown(cleanText), true);\n\t}\n\tif (el && p.channel) {\n\t\tappendChannelFooter(el, p.channel as unknown as Parameters<typeof appendChannelFooter>[1]);\n\t}\n}\n\n// Handle user messages broadcast by the backend after persisting a message\n// sent via the GraphQL API, mobile app, or any non-web-UI client.\n// The originating web client already rendered the message optimistically,\n// so we skip rendering when the broadcast's seq matches a seq this client\n// has already sent (seq <= S.chatSeq).\nfunction handleChatUserMessage(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\t// Suppress the echo for the originating client.\n\tif (p.seq !== undefined && p.seq !== null && p.seq <= S.chatSeq) return;\n\n\tbumpSessionCount(eventSession, 1);\n\tcacheSessionHistoryMessage(\n\t\teventSession,\n\t\t{\n\t\t\trole: \"user\",\n\t\t\tcontent: p.text || \"\",\n\t\t\tcreated_at: Date.now(),\n\t\t},\n\t\tp.messageIndex,\n\t);\n\tif (!isActive) {\n\t\tsetSessionUnread(eventSession, true);\n\t}\n\tif (!(isChatPage && isActive)) return;\n\t// Safe: renderMarkdown calls esc() first — all user input is\n\t// HTML-escaped before formatting tags are applied.\n\tchatAddMsg(\"user\", renderMarkdown(p.text || \"\"), true);\n}\n\n// Safe: renderMarkdown calls esc() first — all user input is HTML-escaped before\n// being passed to innerHTML. This is the standard rendering path for chat messages.\nfunction setSafeMarkdownHtml(el: HTMLElement, text: string): void {\n\tel.innerHTML = renderMarkdown(text); // eslint-disable-line no-unsanitized/property\n}\n\nfunction hasNonWhitespaceContent(text: string | null | undefined): boolean {\n\treturn String(text || \"\").trim().length > 0;\n}\n\nfunction handleChatDelta(p: ChatPayload, isActive: boolean, isChatPage: boolean, eventSession: string): void {\n\tupdateSessionRunId(eventSession, p.runId);\n\tif (!p.text) return;\n\t// Update per-session signal\n\tconst session = sessionStore.getByKey(eventSession);\n\tif (session) session.streamText.value += p.text;\n\tif (!(isActive && isChatPage)) return;\n\t// When voice is pending, accumulate text silently without rendering.\n\tif (S.voicePending) {\n\t\tS.setStreamText(S.streamText + p.text);\n\t\treturn;\n\t}\n\t// Skip leading whitespace before any real content has been streamed.\n\t// Some providers emit newlines between thinking and content; rendering\n\t// them would create an empty assistant div that lingers if a tool call\n\t// follows immediately.  We must check this BEFORE removeThinking() so\n\t// the thinking text is still available for handleChatToolCallStart to\n\t// extract into a reasoning disclosure on the tool card.\n\tif (!(S.streamEl || p.text.trim())) return;\n\tremoveThinking();\n\tif (!S.streamEl) {\n\t\tS.setStreamText(\"\");\n\t\tS.setStreamEl(document.createElement(\"div\"));\n\t\tS.streamEl!.className = \"msg assistant\";\n\t\tclearChatEmptyState();\n\t\tS.chatMsgBox!.appendChild(S.streamEl!);\n\t}\n\tS.setStreamText(S.streamText + p.text);\n\tsetSafeMarkdownHtml(S.streamEl!, S.streamText);\n\tS.chatMsgBox!.scrollTop = S.chatMsgBox!.scrollHeight;\n}\n\nfunction normalizeEchoComparable(text: string | null | undefined): string {\n\tif (!text) return \"\";\n\treturn text\n\t\t.replace(/```[a-zA-Z0-9_-]*\\n?/g, \"\")\n\t\t.replace(/```/g, \"\")\n\t\t.replace(/[`\\s]/g, \"\");\n}\n\nfunction isPureToolOutputEcho(finalText: string, toolOutput: string): boolean {\n\tconst finalComparable = normaliz