s ────────────────────────────────────────────────────\n\ninterface WindowInfo {\n\tid: string;\n\tindex: number;\n\tname: string;\n\tactive: boolean;\n}\n\ninterface ReadyPayload {\n\tavailable: boolean;\n\tpersistenceEnabled: boolean;\n\tpersistenceAvailable: boolean;\n\tactiveWindowId?: string;\n\ttmuxInstallCommand?: string;\n\tuser?: string;\n}\n\ninterface TerminalMessage {\n\ttype: string;\n\tdata?: string;\n\tencoding?: string;\n\ttext?: string;\n\tlevel?: string;\n\terror?: string;\n\twindowId?: string;\n\twindows?: unknown[];\n\tactiveWindowId?: string;\n\tavailable?: boolean;\n\tpersistenceEnabled?: boolean;\n\tpersistenceAvailable?: boolean;\n\ttmuxInstallCommand?: string;\n\tuser?: string;\n}\n\ninterface SocketMessage {\n\ttype: string;\n\t[key: string]: unknown;\n}\n\ninterface WindowsPayload {\n\twindows?: unknown[];\n\tactiveWindowId?: string;\n\tavailable?: boolean;\n\twindow?: { id?: string };\n\twindowId?: string;\n}\n\ntype TerminalCtorType = new (opts: Record<string, unknown>) => XtermInstance;\ntype FitAddonCtorType = new () => FitAddonInstance;\n\ninterface XtermInstance {\n\tcols: number;\n\trows: number;\n\toptions: Record<string, unknown>;\n\tbuffer: { active: { baseY: number; viewportY: number } };\n\tparser: { registerOscHandler: (code: number, handler: () => boolean) => { dispose: () => void } };\n\tloadAddon: (addon: FitAddonInstance) => void;\n\topen: (el: HTMLElement) => void;\n\tonData: (handler: (data: string) => void) => { dispose: () => void };\n\tonResize: (handler: (size: { cols: number; rows: number }) => void) => { dispose: () => void };\n\twrite: (data: string | Uint8Array, callback?: () => void) => void;\n\treset: () => void;\n\tfocus: () => void;\n\tscrollToBottom: () => void;\n\tdispose: () => void;\n}\n\ninterface FitAddonInstance {\n\tfit: () => void;\n}\n\n// ── Module state ─────────────────────────────────────────────\n\nlet _container: HTMLElement | null = null;\nlet resizeObserver: ResizeObserver | null = null;\nle