ationChanged = pagingBeforeHasMore !== pagingAfterHasMore || pagingBeforeCursor !== pagingAfterCursor;\n\n\t\t\tconst cacheHit = historyPayload.historyCacheHit === true;\n\t\t\tconst serverHistory = Array.isArray(historyPayload.history) ? historyPayload.history : [];\n\t\t\tlet appliedServerHistory = false;\n\t\t\tif (!cacheHit && shouldApplyServerHistory(key, serverHistory, cacheRevisionAtRequest)) {\n\t\t\t\treplaceSessionHistory(key, serverHistory);\n\t\t\t\tappliedServerHistory = true;\n\t\t\t}\n\t\t\tconst resolvedHistory = getSessionHistory(key) || serverHistory;\n\t\t\tif (stillActive) {\n\t\t\t\trestoreSessionState(entry, projectId);\n\t\t\t\tapplyReplyingStateFromSwitchPayload(key, switchPayload);\n\t\t\t\tconst thinkingText = switchPayload.replying ? switchPayload.thinkingText || null : null;\n\t\t\t\tconst totalCountHint = Number.isInteger(entry.messageCount)\n\t\t\t\t\t? entry.messageCount!\n\t\t\t\t\t: Number(historyPayload.totalMessages) || resolvedHistory.length;\n\t\t\t\tconst shouldRerender = !hasCache || Boolean(searchContext?.query) || appliedServerHistory || paginationChanged;\n\t\t\t\tif (shouldRerender) {\n\t\t\t\t\trenderHistory(key, resolvedHistory, searchContext || null, thinkingText, totalCountHint, false);\n\t\t\t\t} else {\n\t\t\t\t\tpostHistoryLoadActions(key, searchContext || null, [], thinkingText, false);\n\t\t\t\t}\n\t\t\t\tif (appliedServerHistory && historyPayload.historyTruncated === true) {\n\t\t\t\t\tconst dropped = Number(historyPayload.historyDroppedCount) || 0;\n\t\t\t\t\tchatAddMsg(\n\t\t\t\t\t\t\"system\",\n\t\t\t\t\t\t`Loaded the most recent messages for performance (${dropped} older message${dropped === 1 ? \"\" : \"s\"} omitted).`,\n\t\t\t\t\t);\n\t\t\t\t}\n\t\t\t\tif (appliedServerHistory && historyPayload.hasMore === true) {\n\t\t\t\t\tconst total = Number(historyPayload.totalMessages) || resolvedHistory.length;\n\t\t\t\t\tchatAddMsg(\n\t\t\t\t\t\t\"system\",\n\t\t\t\t\t\t`Loaded recent history (${resolvedHistory.length} of ${total} messages) for faster loading.`,\n\t\t\t\t\t);\n\t\t\t\t}\n\t\t\t\tif (S.chatInput) S.chatInput.focus();\n\t\t\t}\n\t\t\tfinishSessionRefresh(key);\n\t\t})\n\t\t.catch(() => {\n\t\t\tif (!isLatestSwitchRequest(key, switchReqId)) return;\n\t\t\tconst stillActive = sessionStore.activeSessionKey.value === key;\n\t\t\tif (stillActive && !hasCache) {\n\t\t\t\thideSessionLoadIndicator();\n\t\t\t\tchatAddMsg(\"error\", \"Failed to load session\");\n\t\t\t}\n\t\t\tfinishSessionRefresh(key);\n\t\t\tif (stillActive && S.chatInput) S.chatInput.focus();\n\t\t});\n}\n","// ── SessionList Preact component ─────���───────────────────────\n//\n// Replaces the imperative renderSessionList() with a reactive Preact\n// component that auto-rerenders from sessionStore signals.\n\nimport type { VNode } from \"preact\";\nimport { useEffect, useRef } from \"preact/hooks\";\nimport {\n\tmakeBranchIcon,\n\tmakeChatIcon,\n\tmakeCronIcon,\n\tmakeDiscordIcon,\n\tmakeMatrixIcon,\n\tmakeProjectIcon,\n\tmakeSlackIcon,\n\tmakeTeamsIcon,\n\tmakeTelegramIcon,\n} from \"../icons\";\nimport { currentPrefix, navigate, sessionPath } from \"../router\";\nimport { switchSession } from \"../sessions\";\nimport * as projectStore from \"../stores/project-store\";\nimport { type Session, sessionStore } from \"../stores/session-store\";\n\n// ── Braille spinner ───────────��─────────────────────────────\nconst spinnerFrames: string[] = [\n\t\"\\u280B\",\n\t\"\\u2819\",\n\t\"\\u2839\",\n\t\"\\u2838\",\n\t\"\\u283C\",\n\t\"\\u2834\",\n\t\"\\u2826\",\n\t\"\\u2827\",\n\t\"\\u2807\",\n\t\"\\u280F\",\n];\n\n// ── Helpers ─────────���────────────────────────────────────────\n\ntype ChannelType = \"telegram\" | \"msteams\" | \"discord\" | \"slack\" | \"matrix\" | null;\n\nfunction channelSessionType(s: Session): ChannelType {\n\tconst key = s.key || \"\";\n\tif (key.startsWith(\"telegram:\")) return \"telegram\";\n\tif (key.startsWith(\"msteams:\")) return \"msteams\";\n\tif (key.startsWith(\"discord:\")) return \"discord\";\n\tif (key.startsWith(\"slack:\")) return \"slack\";\n\tif (key.startsWith(\"matrix:\")) return \"matrix\";\n\tconst binding = s.channelBinding || null;\n\tif (!binding) return null;\n\ttry {\n\t\tconst parsed = typeof binding === \"string\" ? JSON.parse(binding) : binding;\n\t\treturn (parsed.channel_type as ChannelType) || null;\n\t} catch (_e) {\n\t\treturn null;\n\t}\n}\n\nfunction formatHHMM(epochMs: number): string {\n\treturn new Date(epochMs).toLocaleTimeString(undefined, { hour: \"2-digit\", minute: \"2-digit\" });\n}\n\n// ── Icon component (renders SVG icon into a ref) ────────────\n\ninterface SessionIconProps {\n\tsession: Session;\n\tisBranch: boolean;\n}\n\nfunction SessionIcon({ session, isBranch }: SessionIconProps): VNode {\n\tconst iconRef = useRef<HTMLSpanElement>(null);\n\tuseEffect(() => {\n\t\tif (!iconRef.current) return;\n\t\ticonRef.current.textContent = \"\";\n\t\tconst key = session.key || \"\";\n\t\tlet icon: SVGElement | HTMLElement;\n\t\tconst channelType = channelSessionType(session);\n\t\tif (isBranch) icon = makeBranchIcon();\n\t\telse if (key.startsWith(\"cron:\")) icon = makeCronIcon();\n\t\telse if (channelType === \"telegram\") icon = makeTelegramIcon();\n\t\telse if (channelType === \"msteams\") icon = makeTeamsIcon();\n\t\telse if (channelType === \"discord\") icon = makeDiscordIcon();\n\t\telse if (channelType === \"slack\") icon = makeSlackIcon();\n\t\telse if (channelType === \"matrix\") icon = makeMatrixIcon();\n\t\telse icon = makeChatIcon();\n\t\ticonRef.current.appendChild(icon);\n\t}, [session.key, isBranch]);\n\n\tconst channelType = channelSessionType(session);\n\tconst channelBound = Boolean(channelType);\n\tconst iconStyle: Record<string, string> = {};\n\tif (channelBound) {\n\t\ticonStyle.color = session.activeChannel ? \"var(--accent)\" : \"var(--muted)\";\n\t\ticonStyle.opacity = session.activeChannel ? \"1\" : \"0.5\";\n\t} else {\n\t\ticonStyle.color = \"var(--muted)\";\n\t}\n\tconst channelLabel =\n\t\tchannelType === \"msteams\"\n\t\t\t? \"Microsoft Teams\"\n\t\t\t: channelType === \"discord\"\n\t\t\t\t? \"Discord\"\n\t\t\t\t: channelType === \"slack\"\n\t\t\t\t\t? \"Slack\"\n\t\t\t\t\t: channelType === \"matrix\"\n\t\t\t\t\t\t? \"Matrix\"\n\t\t\t\t\t\t: \"Telegram\";\n\tconst title = channelBound\n\t\t? session.activeChannel\n\t\t\t? `Active ${channelLabel} session`\n\t\t\t: `${channelLabel} session (inactive)`\n\t\t: \"\";\n\n\t// Read the reactive signal — auto-subscribes for badge updates.\n\tconst count = session.badgeCount.value;\n\n\treturn (\n\t\t<span className=\"session-icon\" style={iconStyle} title={title}>\n\t\t\t<span ref={iconRef} />\n\t\t\t<span className=\"session-spinner\" />\n\t\t\t{count > 0 && (\n\t\t\t\t<span className=\"session-badge\" data-session-key={session.key}>\n\t\t\t\t\t{count > 99 ? \"99+\" : String(count)}\n\t\t\t\t</span>\n\t\t\t)}\n\t\t</span>\n\t);\n}\n\n// ── Session meta (fork, worktree, project) ──────────────────\n\ninterface SessionMetaProps {\n\tsession: Session;\n}\n\nfunction SessionMeta({ session }: SessionMetaProps): VNode {\n\tconst ref = useRef<HTMLDivElement>(null);\n\n\tuseEffect(() => {\n\t\tif (!ref.current) return;\n\t\tref.current.textContent = \"\";\n\n\t\tconst parts: string[] = [];\n\t\tif (session.forkPoint != null) parts.push(`fork@${session.forkPoint}`);\n\t\tconst branch = session.worktree_branch || \"\";\n\t\tif (branch) parts.push(`\\u2387 ${branch}`);\n\n\t\tconst projId = session.projectId || \"\";\n\t\tconst proj = projId ? projectStore.getById(projId) : null;\n\n\t\tif (parts.length === 0 && !proj) return;\n\n\t\tref.current.textContent = parts.join(\" \\u00b7 \");\n\t\tif (proj) {\n\t\t\tif (parts.length > 0) ref.current.appendChild(document.createTextNode(\" \\u00b7 \"));\n\t\t\tconst icon = makeProjectIcon();\n\t\t\ticon.style.display = \"inline\";\n\t\t\ticon.style.verticalAlign = \"-1px\";\n\t\t\ticon.style.marginRight = \"2px\";\n\t\t\ticon.style.opacity = \"0.7\";\n\t\t\tref.current.appendChild(icon);\n\t\t\tref.current.appendChild(document.createTextNode((proj.label as string) || proj.id));\n\t\t}\n\t}, [session.projectId, session.forkPoint, session.worktree_branch]);\n\n\treturn <div className=\"session-meta\" data-session-key={session.key} ref={ref} />;\n}\n\n// ── SessionItem component ───────────���───────────────────────\n\ninterface KeyMap {\n\t[key: string]: Session;\n}\n\ninterface SessionItemProps {\n\tsession: Session;\n\tactiveKey: string;\n\tdepth: number;\n\tkeyMap: KeyMap;\n\trefreshing: boolean;\n}\n\nfunction SessionItem({ session, activeKey, depth, keyMap, refreshing }: SessionItemProps): VNode {\n\tconst isBranch = depth > 0;\n\tconst active = session.key === activeKey;\n\t// Read per-session signals — auto-subscribes for re-render.\n\t// dataVersion triggers re-render when plain properties (preview,\n\t// updatedAt, label) change. Badge updates come from badgeCount\n\t// signal read inside SessionIcon.\n\tconst replying = session.replying.value;\n\tvoid session.dataVersion.value;\n\t// Unread tint: true when not viewing this session and there are messages\n\t// beyond what we last saw (badgeCount is reactive, triggers re-render).\n\tconst badge = session.badgeCount.value;\n\tconst unread = session.localUnread.value || (!active && badge > (session.lastSeenMessageCount || 0));\n\n\tlet className = \"session-item\";\n\tif (active) className += \" active\";\n\tif (unread) className += \" unread\";\n\tif (replying) className += \" replying\";\n\tif (refreshing) className += \" loading\";\n\n\tconst style = isBranch ? { paddingLeft: `${12 + depth * 16}px` } : {};\n\n\tconst rawPreview = session.preview || \"\";\n\tconst parentPreview =\n\t\tsession.parentSessionKey && keyMap[session.parentSessionKey] ? keyMap[session.parentSessionKey].preview || \"\" : \"\";\n\tconst preview = rawPreview && rawPreview === parentPreview ? \"\" : rawPreview;\n\tconst ts = session.updatedAt || 0;\n\tconst agentId = session.agent_id || \"main\";\n\tconst showAgentBadge = !!agentId && agentId !== \"main\";\n\n\tconst href = sessionPath(session.key);\n\n\tfunction onClick(event: MouseEvent): void {\n\t\tif (event.defaultPrevented) return;\n\t\tif (event.button !== 0) return;\n\t\tif (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;\n\t\tevent.preventDefault();\n\t\tif (currentPrefix !== \"/chats\") {\n\t\t\tnavigate(href);\n\t\t} else {\n\t\t\tswitchSession(session.key);\n\t\t}\n\t}\n\n\treturn (\n\t\t<a href={href} className={className} data-session-key={session.key} style={style} onClick={onClick}>\n\t\t\t<div className=\"session-info\">\n\t\t\t\t<div className=\"session-label\">\n\t\t\t\t\t<SessionIcon session={session} isBranch={isBranch} />\n\t\t\t\t\t<span data-label-text>{session.label || session.key}</span>\n\t\t\t\t\t{showAgentBadge && (\n\t\t\t\t\t\t<span\n\t\t\t\t\t\t\tclassName=\"text-[10px] text-[var(--muted)] border border-[var(--border)] rounded px-1 py-0 ml-1\"\n\t\t\t\t\t\t\ttitle={`Agent: ${agentId}`}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t@{agentId}\n\t\t\t\t\t\t</span>\n\t\t\t\t\t)}\n\t\t\t\t\t{ts > 0 && (\n\t\t\t\t\t\t<span className=\"session-time\" title={new Date(ts).toLocaleString()}>\n\t\t\t\t\t\t\t{formatHHMM(ts)}\n\t\t\t\t\t\t</span>\n\t\t\t\t\t)}\n\t\t\t\t</div>\n\t\t\t\t{preview && <div className=\"session-preview\">{preview}</div>}\n\t\t\t\t<SessionMeta session={session} />\n\t\t\t</div>\n\t\t</a>\n\t);\n}\n\n// ── SessionList component ──────────────────���────────────────\nexport function SessionList(): VNode {\n\tconst allSessions = sessionStore.sessions.value;\n\tconst activeKey = sessionStore.activeSessionKey.value;\n\tconst refreshingKey = sessionStore.refreshInProgressKey.value;\n\tconst filterId = projectStore.projectFilterId.value;\n\tconst tab = sessionStore.sessionListTab.value;\n\tconst showArchived = sessionStore.showArchivedSessions.value;\n\n\t// Spinner animation via setInterval\n\tconst spinnersRef = useRef<HTMLDivElement>(null);\n\tuseEffect(() => {\n\t\tlet idx = 0;\n\t\tconst timer = setInterval(() => {\n\t\t\tidx = (idx + 1) % spinnerFrames.length;\n\t\t\tif (!spinnersRef.current) return;\n\t\t\tconst els = spinnersRef.current.querySelectorAll(\n\t\t\t\t\".session-item.replying .session-spinner, .session-item.loading .session-spinner\",\n\t\t\t);\n\t\t\tfor (const el of els) el.textContent = spinnerFrames[idx];\n\t\t}, 80);\n\t\treturn () => clearInterval(timer);\n\t}, []);\n\n\tlet filtered = filterId ? allSessions.filter((s) => s.projectId === filterId) : allSessions;\n\tif (tab === \"sessions\") {\n\t\tfiltered = filtered.filter((s) => !(s.key || \"\").startsWith(\"cron:\") && (showArchived || !s.archived));\n\t} else if (tab === \"cron\") {\n\t\tfiltered = filtered.filter((s) => (s.key || \"\").startsWith(\"cron:\"));\n\t}\n\n\t// Build parent→children map for tree rendering\n\tconst childrenMap: Record<string, Session[]> = {};\n\tconst keyMap: KeyMap = {};\n\tfiltered.forEach((s) => {\n\t\tkeyMap[s.key] = s;\n\t\tif (s.parentSessionKey) {\n\t\t\tif (!childrenMap[s.parentSessionKey]) childrenMap[s.parentSessionKey] = [];\n\t\t\tchildrenMap[s.parentSessionKey].push(s);\n\t\t}\n\t});\n\tconst roots = filtered.filter((s) => !(s.parentSessionKey && keyMap[s.parentSessionKey]));\n\n\tfunction renderTree(session: Session, depth: number): VNode {\n\t\tconst children = childrenMap[session.key] || [];\n\t\treturn (\n\t\t\t<>\n\t\t\t\t<SessionItem\n\t\t\t\t\tkey={session.key}\n\t\t\t\t\tsession={session}\n\t\t\t\t\tactiveKey={activeKey}\n\t\t\t\t\tdepth={depth}\n\t\t\t\t\tkeyMap={keyMap}\n\t\t\t\t\trefreshing={session.key === refreshingKey}\n\t\t\t\t/>\n\t\t\t\t{children.map((child) => renderTree(child, depth + 1))}\n\t\t\t</>\n\t\t);\n\t}\n\n\treturn <div ref={spinnersRef}>{roots.map((s) => renderTree(s, 0))}</div>;\n}\n","// Mobile navigation and panel handling\n\nlet navPanel: HTMLElement | null = null;\nlet navOverlay: HTMLElement | null = null;\nlet sessionsPanel: HTMLElement | null = null;\nlet sessionsOverlay: HTMLElement | null = null;\nlet sessionsToggle: HTMLElement | null = null;\nlet burgerBtn: HTMLElement | null = null;\n\n// Check if we're in mobile view\nfunction isMobile(): boolean {\n\treturn window.innerWidth < 768;\n}\n\n// Open navigation panel\nfunction openNav(): void {\n\tif (!(navPanel && navOverlay)) return;\n\tnavPanel.classList.add(\"open\");\n\tnavOverlay.classList.add(\"visible\");\n\tdocument.body.style.overflow = \"hidden\";\n}\n\n// Close navigation panel\nfunction closeNav(): void {\n\tif (!(navPanel && navOverlay)) return;\n\tnavPanel.classList.remove(\"open\");\n\tnavOverlay.classList.remove(\"visible\");\n\tif (!sessionsPanel?.classList.contains(\"open\")) {\n\t\tdocument.body.style.overflow = \"\";\n\t}\n}\n\n// Toggle navigation panel\nfunction toggleNav(): void {\n\tif (navPanel?.classList.contains(\"open\")) {\n\t\tcloseNav();\n\t} else {\n\t\topenNav();\n\t}\n}\n\n// Open sessions panel\nfunction openSessions(): void {\n\tif (!(sessionsPanel && sessionsOverlay)) return;\n\tsessionsPanel.classList.add(\"open\");\n\tsessionsPanel.classList.remove(\"hidden\");\n\tsessionsOverlay.classList.add(\"visible\");\n\tif (sessionsToggle) sessionsToggle.classList.add(\"hidden\");\n\tdocument.body.style.overflow = \"hidden\";\n}\n\n// Close sessions panel\nfunction closeSessions(): void {\n\tif (!(sessionsPanel && sessionsOverlay)) return;\n\tsessionsPanel.classList.remove(\"open\");\n\tsessionsOverlay.classList.remove(\"visible\");\n\tif (sessionsToggle) sessionsToggle.classList.remove(\"hidden\");\n\tif (!navPanel?.classList.contains(\"open\")) {\n\t\tdocument.body.style.overflow = \"\";\n\t}\n\t// On mobile, also add hidden after transition\n\tif (isMobile()) {\n\t\tsetTimeout(() => {\n\t\t\tif (!sessionsPanel?.classList.contains(\"open\")) {\n\t\t\t\tsessionsPanel?.classList.add(\"hidden\");\n\t\t\t}\n\t\t}, 300);\n\t}\n}\n\n// Toggle sessions panel\nfunction toggleSessions(): void {\n\tif (sessionsPanel?.classList.contains(\"open\")) {\n\t\tcloseSessions();\n\t} else {\n\t\topenSessions();\n\t}\n}\n\n// Handle nav link clicks - close nav on mobile after navigation\nfunction handleNavClick(e: Event): void {\n\tif (isMobile() && (e.target as HTMLElement).closest(\".nav-link\")) {\n\t\tcloseNav();\n\t}\n}\n\n// Handle session item clicks - close sessions on mobile after selection\nfunction handleSessionClick(e: Event): void {\n\tif (isMobile() && (e.target as HTMLElement).closest(\".session-item\")) {\n\t\tsetTimeout(closeSessions, 100);\n\t}\n}\n\n// Handle resize - reset states when switching between mobile/desktop\nfunction handleResize(): void {\n\tif (isMobile()) {\n\t\t// Mobile view - show toggle button if sessions panel is not open\n\t\tif (!sessionsPanel?.classList.contains(\"open\")) {\n\t\t\tsessionsToggle?.classList.remove(\"hidden\");\n\t\t}\n\t} else {\n\t\t// Desktop view - reset mobile-specific states\n\t\tnavPanel?.classList.remove(\"open\");\n\t\tnavOverlay?.classList.remove(\"visible\");\n\t\tsessionsOverlay?.classList.remove(\"visible\");\n\t\tsessionsToggle?.classList.add(\"hidden\");\n\t\tdocument.body.style.overflow = \"\";\n\n\t\t// On desktop, sessions panel visibility is controlled differently\n\t\t// Remove open class but don't add hidden (let desktop CSS handle it)\n\t\tsessionsPanel?.classList.remove(\"open\");\n\t}\n}\n\n// Initialize mobile interactions\nexport function initMobile(): void {\n\tnavPanel = document.getElementById(\"navPanel\");\n\tnavOverlay = document.getElementById(\"navOverlay\");\n\tsessionsPanel = document.getElementById(\"sessionsPanel\");\n\tsessionsOverlay = document.getElementById(\"sessionsOverlay\");\n\tsessionsToggle = document.getElementById(\"sessionsToggle\");\n\tburgerBtn = document.getElementById(\"burgerBtn\");\n\n\t// Burger button toggles nav\n\tif (burgerBtn) {\n\t\tburgerBtn.addEventListener(\"click\", toggleNav);\n\t}\n\n\t// Overlay clicks close their respective panels\n\tif (navOverlay) {\n\t\tnavOverlay.addEventListener(\"click\", closeNav);\n\t}\n\n\tif (sessionsOverlay) {\n\t\tsessionsOverlay.addEventListener(\"click\", closeSessions);\n\t}\n\n\t// Sessions toggle FAB\n\tif (sessionsToggle) {\n\t\tsessionsToggle.addEventListener(\"click\", toggleSessions);\n\t\t// Initially hide on desktop\n\t\tif (!isMobile()) {\n\t\t\tsessionsToggle.classList.add(\"hidden\");\n\t\t}\n\t}\n\n\t// Close nav when clicking nav links on mobile\n\tif (navPanel) {\n\t\tnavPanel.addEventListener(\"click\", handleNavClick);\n\t}\n\n\t// Close sessions when clicking session items on mobile\n\tif (sessionsPanel) {\n\t\tsessionsPanel.addEventListener(\"click\", handleSessionClick);\n\t}\n\n\t// Handle resize events\n\twindow.addEventListener(\"resize\", handleResize);\n\n\t// Escape key closes panels\n\tdocument.addEventListener(\"keydown\", (e: KeyboardEvent) => {\n\t\tif (e.key === \"Escape\") {\n\t\t\tif (navPanel?.classList.contains(\"open\")) {\n\t\t\t\tcloseNav();\n\t\t\t}\n\t\t\tif (sessionsPanel?.classList.contains(\"open\") && isMobile()) {\n\t\t\t\tcloseSessions();\n\t\t\t}\n\t\t}\n\t});\n\n\t// Touch gestures for bottom sheet (sessions panel)\n\tif (sessionsPanel) {\n\t\tsetupBottomSheetGestures(sessionsPanel);\n\t}\n}\n\n// Simple swipe-down gesture to close bottom sheet\nfunction setupBottomSheetGestures(panel: HTMLElement): void {\n\tlet startY = 0;\n\tlet currentY = 0;\n\tlet isDragging = false;\n\n\tpanel.addEventListener(\n\t\t\"touchstart\",\n\t\t(e: TouchEvent) => {\n\t\t\t// Only initiate drag from the top area (drag handle region)\n\t\t\tconst touch = e.touches[0];\n\t\t\tconst panelRect = panel.getBoundingClientRect();\n\t\t\tif (touch.clientY - panelRect.top < 40) {\n\t\t\t\tstartY = touch.clientY;\n\t\t\t\tisDragging = true;\n\t\t\t}\n\t\t},\n\t\t{ passive: true },\n\t);\n\n\tpanel.addEventListener(\n\t\t\"touchmove\",\n\t\t(e: TouchEvent) => {\n\t\t\tif (!isDragging) return;\n\t\t\tcurrentY = e.touches[0].clientY;\n\t\t\tconst deltaY = currentY - startY;\n\n\t\t\t// Only allow dragging down\n\t\t\tif (deltaY > 0) {\n\t\t\t\tpanel.style.transform = `translateY(${deltaY}px)`;\n\t\t\t}\n\t\t},\n\t\t{ passive: true },\n\t);\n\n\tpanel.addEventListener(\n\t\t\"touchend\",\n\t\t() => {\n\t\t\tif (!isDragging) return;\n\t\t\tisDragging = false;\n\n\t\t\tconst deltaY = currentY - startY;\n\t\t\tpanel.style.transform = \"\";\n\n\t\t\t// Close if dragged more than 100px down\n\t\t\tif (deltaY > 100) {\n\t\t\t\tcloseSessions();\n\t\t\t}\n\t\t},\n\t\t{ passive: true },\n\t);\n}\n\n// Export functions for external use\nexport { closeNav, closeSessions, isMobile, openNav, openSessions, toggleNav, toggleSessions };\n","// ── SessionHeader Preact component ───────────────────────────\n//\n// Replaces the imperative updateChatSessionHeader() with a reactive\n// Preact component reading sessionStore.activeSession.\n\nimport type { VNode } from \"preact\";\nimport { useCallback, useEffect, useRef, useState } from \"preact/hooks\";\nimport { onEvent } from \"../events\";\nimport * as gon from \"../gon\";\nimport { parseAgentsListPayload, sendRpc } from \"../helpers\";\nimport {\n\tclearActiveSession,\n\tfetchSessions,\n\tisArchivableSession,\n\tremoveSessionFromClientState,\n\tsetSessionActiveRunId,\n\tsetSessionReplying,\n\tswitchSession,\n} from \"../sessions\";\nimport { sessionStore } from \"../stores/session-store\";\nimport type { SessionMeta } from \"../types\";\nimport { ComboSelect, confirmDialog, shareLinkDialog, shareVisibilityDialog, showToast } from \"../ui\";\n\n// ── Types ────────────────────────────────────────────────────\n\ninterface NodeInfo {\n\tnodeId: string;\n\tdisplayName?: string;\n\tplatform?: string;\n\t[key: string]: unknown;\n}\n\ninterface AgentOption {\n\tid: string;\n\tname: string;\n\temoji?: string;\n\tis_default?: boolean;\n\t[key: string]: unknown;\n}\n\ninterface SelectOption {\n\tvalue: string;\n\tlabel: string;\n}\n\ninterface SharePayload {\n\tpath?: string;\n\taccessKey?: string;\n}\n\nexport interface SessionHeaderProps {\n\tshowSelectors?: boolean;\n\tshowName?: boolean;\n\tshowShare?: boolean;\n\tshowFork?: boolean;\n\tshowStop?: boolean;\n\tshowClear?: boolean;\n\tshowDelete?: boolean;\n\tshowArchive?: boolean;\n\tnameOwnLine?: boolean;\n\tshowRenameButton?: boolean;\n\tactionButtonClass?: string;\n\tonBeforeShare?: (() => void) | null;\n\tonBeforeArchive?: (() => void) | null;\n\tonBeforeDelete?: (() => void) | null;\n}\n\n// ── Helpers ──────────────────────────────────────────────────\n\nfunction nextSessionKey(currentKey: string): string {\n\tconst allSessions = sessionStore.sessions.value;\n\tconst s = allSessions.find((x) => x.key === currentKey);\n\tif (s?.parentSessionKey) return s.parentSessionKey;\n\tconst idx = allSessions.findIndex((x) => x.key === currentKey);\n\tif (idx >= 0 && idx + 1 < allSessions.length) return allSessions[idx + 1].key;\n\tif (idx > 0) return allSessions[idx - 1].key;\n\treturn \"main\";\n}\n\nfunction buildShareUrl(payload: SharePayload): string {\n\tlet url = `${window.location.origin}${payload.path}`;\n\tif (payload.accessKey) {\n\t\turl += `?k=${encodeURIComponent(payload.accessKey)}`;\n\t}\n\treturn url;\n}\n\nfunction isSshTargetNode(node: NodeInfo | null): boolean {\n\treturn node?.platform === \"ssh\" || String(node?.nodeId || \"\").startsWith(\"ssh:\");\n}\n\nfunction nodeOptionLabel(node: NodeInfo | null): string {\n\tif (!node) return \"Local\";\n\tif (node.displayName) return node.displayName;\n\tif (isSshTargetNode(node)) {\n\t\tconst target = String(node.nodeId || \"\").replace(/^ssh:/, \"\");\n\t\treturn `SSH: ${target}`;\n\t}\n\treturn node.nodeId;\n}\n\nasync function copyShareUrl(url: string, visibility: string): Promise<void> {\n\ttry {\n\t\tif (navigator.clipboard?.writeText) {\n\t\t\tawait navigator.clipboard.writeText(url);\n\t\t\tshowToast(\"Share link copied\", \"success\");\n\t\t\treturn;\n\t\t}\n\t} catch (_err) {\n\t\t// Clipboard APIs can fail on some browsers/permissions.\n\t}\n\tawait shareLinkDialog(url, visibility);\n}\n\n// ── Component ────────────────────────────────────────────────\n\nexport function SessionHeader({\n\tshowSelectors = true,\n\tshowName = true,\n\tshowShare = true,\n\tshowFork = true,\n\tshowStop = true,\n\tshowClear = true,\n\tshowDelete = true,\n\tshowArchive = true,\n\tnameOwnLine = false,\n\tshowRenameButton = false,\n\tactionButtonClass = \"chat-session-btn\",\n\tonBeforeShare = null,\n\tonBeforeArchive = null,\n\tonBeforeDelete = null,\n}: SessionHeaderProps = {}): VNode {\n\tconst session = sessionStore.activeSession.value;\n\tconst sessionDataVersion = session?.dataVersion.value || 0;\n\tconst currentKey = sessionStore.activeSessionKey.value;\n\tconst gonAgentsPayload = parseAgentsListPayload(gon.get(\"agents\") as never);\n\tconst initialAgentOptions: AgentOption[] = Array.isArray(gonAgentsPayload?.agents)\n\t\t? (gonAgentsPayload.agents as AgentOption[])\n\t\t: [];\n\tconst initialDefaultAgentId = typeof gonAgentsPayload?.defaultId === \"string\" ? gonAgentsPayload.defaultId : \"main\";\n\n\tconst [renaming, setRenaming] = useState(false);\n\tconst [clearing, setClearing] = useState(false);\n\tconst [stopping, setStopping] = useState(false);\n\tconst [switchingAgent, setSwitchingAgent] = useState(false);\n\tconst [agentOptions, setAgentOptions] = useState<AgentOption[]>(initialAgentOptions);\n\tconst [defaultAgentId, setDefaultAgentId] = useState(initialDefaultAgentId);\n\tconst [agentOptionsLoaded, setAgentOptionsLoaded] = useState(initialAgentOptions.length > 0);\n\tconst [nodeOptions, setNodeOptions] = useState<NodeInfo[]>([]);\n\tconst [switchingNode, setSwitchingNode] = useState(false);\n\tconst inputRef = useRef<HTMLInputElement>(null);\n\n\tconst fullName = session ? session.label || session.key : currentKey;\n\tconst displayName = nameOwnLine ? fullName : fullName.length > 20 ? `${fullName.slice(0, 20)}\\u2026` : fullName;\n\tconst replying = session?.replying.value;\n\tconst activeRunId = session?.activeRunId.value || null;\n\n\tconst isMain =