.tsx","../../../ui/src/pages/ImagesPage.tsx","../../../ui/src/pages/LogsPage.tsx","../../../ui/src/pages/McpPage.tsx","../../../ui/src/pages/NetworkAuditPage.tsx","../../../ui/src/pages/NodesPage.tsx","../../../ui/src/modals.ts","../../../ui/src/providers.ts","../../../ui/src/pages/ProvidersPage.tsx","../../../ui/src/pages/TerminalPage.tsx","../../../ui/src/pages/WebhooksPage.tsx","../../../ui/src/pages/SettingsPage.tsx","../../../ui/src/session-search.ts","../../../ui/src/main.tsx"],"sourcesContent":["const BYTE_UNITS = [\n\t'B',\n\t'kB',\n\t'MB',\n\t'GB',\n\t'TB',\n\t'PB',\n\t'EB',\n\t'ZB',\n\t'YB',\n];\n\nconst BIBYTE_UNITS = [\n\t'B',\n\t'KiB',\n\t'MiB',\n\t'GiB',\n\t'TiB',\n\t'PiB',\n\t'EiB',\n\t'ZiB',\n\t'YiB',\n];\n\nconst BIT_UNITS = [\n\t'b',\n\t'kbit',\n\t'Mbit',\n\t'Gbit',\n\t'Tbit',\n\t'Pbit',\n\t'Ebit',\n\t'Zbit',\n\t'Ybit',\n];\n\nconst BIBIT_UNITS = [\n\t'b',\n\t'kibit',\n\t'Mibit',\n\t'Gibit',\n\t'Tibit',\n\t'Pibit',\n\t'Eibit',\n\t'Zibit',\n\t'Yibit',\n];\n\n/*\nFormats the given number using `Number#toLocaleString`.\n- If locale is a string, the value is expected to be a locale-key (for example: `de`).\n- If locale is true, the system default locale is used for translation.\n- If no value for locale is specified, the number is returned unmodified.\n*/\nconst toLocaleString = (number, locale, options) => {\n\tlet result = number;\n\tif (typeof locale === 'string' || Array.isArray(locale)) {\n\t\tresult = number.toLocaleString(locale, options);\n\t} else if (locale === true || options !== undefined) {\n\t\tresult = number.toLocaleString(undefined, options);\n\t}\n\n\treturn result;\n};\n\nexport default function prettyBytes(number, options) {\n\tif (!Number.isFinite(number)) {\n\t\tthrow new TypeError(`Expected a finite number, got ${typeof number}: ${number}`);\n\t}\n\n\toptions = {\n\t\tbits: false,\n\t\tbinary: false,\n\t\tspace: true,\n\t\t...options,\n\t};\n\n\tconst UNITS = options.bits\n\t\t? (options.binary ? BIBIT_UNITS : BIT_UNITS)\n\t\t: (options.binary ? BIBYTE_UNITS : BYTE_UNITS);\n\n\tconst separator = options.space ? ' ' : '';\n\n\tif (options.signed && number === 0) {\n\t\treturn ` 0${separator}${UNITS[0]}`;\n\t}\n\n\tconst isNegative = number < 0;\n\tconst prefix = isNegative ? '-' : (options.signed ? '+' : '');\n\n\tif (isNegative) {\n\t\tnumber = -number;\n\t}\n\n\tlet localeOptions;\n\n\tif (options.minimumFractionDigits !== undefined) {\n\t\tlocaleOptions = {minimumFractionDigits: options.minimumFractionDigits};\n\t}\n\n\tif (options.maximumFractionDigits !== undefined) {\n\t\tlocaleOptions = {maximumFractionDigits: options.maximumFractionDigits, ...localeOptions};\n\t}\n\n\tif (number < 1) {\n\t\tconst numberString = toLocaleString(number, options.locale, localeOptions);\n\t\treturn prefix + numberString + separator + UNITS[0];\n\t}\n\n\tconst exponent = Math.min(Math.floor(options.binary ? Math.log(number) / Math.log(1024) : Math.log10(number) / 3), UNITS.length - 1);\n\tnumber /= (options.binary ? 1024 : 1000) ** exponent;\n\n\tif (!localeOptions) {\n\t\tnumber = number.toPrecision(3);\n\t}\n\n\tconst numberString = toLocaleString(Number(number), options.locale, localeOptions);\n\n\tconst unit = UNITS[exponent];\n\n\treturn prefix + numberString + separator + unit;\n}\n","// ── Syntax highlighting (Shiki) ────────────────────────────\n//\n// Lazy-loads the Shiki highlighter on app startup. Code blocks\n// rendered during streaming show a language badge but no colors;\n// highlighting is applied after the stream completes or when\n// history messages are loaded.\n\nimport type { BundledLanguage, BundledTheme, HighlighterGeneric } from \"shiki\";\n\nlet highlighter: HighlighterGeneric<BundledLanguage, BundledTheme> | null = null;\nlet highlighterInitPromise: Promise<void> | null = null;\nconst languageLoadPromises: Map<string, Promise<void>> = new Map();\n\n/**\n * Initialize the Shiki highlighter. Call once at app startup (fire-and-forget).\n * Safe to call multiple times -- subsequent calls are no-ops.\n */\nexport async function initHighlighter(): Promise<HighlighterGeneric<BundledLanguage, BundledTheme> | null> {\n\tif (highlighter) return highlighter;\n\tif (highlighterInitPromise) {\n\t\tawait highlighterInitPromise;\n\t\treturn highlighter;\n\t}\n\thighlighterInitPromise = (async (): Promise<void> => {\n\t\ttry {\n\t\t\tconst shiki = await import(\"shiki\");\n\t\t\t// Load only themes at startup; grammars are loaded on demand per language.\n\t\t\thighlighter = await shiki.createHighlighter({\n\t\t\t\tthemes: [\"github-dark\", \"github-light\"],\n\t\t\t\tlangs: [],\n\t\t\t});\n\t\t} catch (err) {\n\t\t\tconsole.warn(\"[shiki] failed to initialize highlighter:\", err);\n\t\t}\n\t})();\n\tawait highlighterInitPromise;\n\treturn highlighter;\n}\n\n/** Returns whether the highlighter has finished loading. */\nexport function isReady(): boolean {\n\treturn highlighter !== null;\n}\n\nasync function ensureLanguageLoaded(lang: string): Promise<boolean> {\n\tif (!(highlighter && lang)) return false;\n\tconst loadedLangs = highlighter.getLoadedLanguages();\n\tif (loadedLangs.includes(lang)) return true;\n\tlet inFlight = languageLoadPromises.get(lang);\n\tif (!inFlight) {\n\t\tinFlight = highlighter\n\t\t\t.loadLanguage(lang as Parameters<typeof highlighter.loadLanguage>[0])\n\t\t\t.catch(() => {\n\t\t\t\t// Unknown/unsupported language -- leave code block unhighlighted.\n\t\t\t})\n\t\t\t.finally(() => {\n\t\t\t\tlanguageLoadPromises.delete(lang);\n\t\t\t});\n\t\tlanguageLoadPromises.set(lang, inFlight);\n\t}\n\tawait inFlight;\n\treturn highlighter.getLoadedLanguages().includes(lang);\n}\n\nfunction applyShikiStylesToPre(codeEl: HTMLElement, shikiPre: HTMLElement): void {\n\tconst parentPre = codeEl.parentElement;\n\tif (!(parentPre && parentPre.tagName === \"PRE\")) return;\n\t// Copy Shiki's style attribute to the parent <pre> for theming.\n\tparentPre.style.cssText = shikiPre.style.cssText;\n}\n\nfunction applyShikiMarkupToCode(codeEl: HTMLElement, shikiPre: HTMLElement): void {\n\tconst shikiCode = shikiPre.querySelector(\"code\");\n\tif (!shikiCode) return;\n\t// Safe: codeToHtml produces deterministic syntax-highlighted markup\n\t// from plain-text code content. Shiki does not pass through raw user HTML.\n\tcodeEl.textContent = \"\";\n\twhile (shikiCode.firstChild) {\n\t\tcodeEl.appendChild(shikiCode.firstChild);\n\t}\n\tcodeEl.classList.add(\"shiki\");\n\tfor (const cls of shikiPre.classList) {\n\t\tif (cls !== \"shiki\") codeEl.classList.add(cls);\n\t}\n}\n\nfunction parseShikiPre(highlightedHtml: string): HTMLElement | null {\n\tconst temp = document.createElement(\"div\");\n\t// Safe: codeToHtml produces deterministic syntax-highlighted markup\n\t// from plain-text code content. The input (codeEl.textContent) is\n\t// already HTML-escaped by renderMarkdown(). Shiki does not pass\n\t// through raw user HTML -- it tokenizes and wraps in <span> tags.\n\tconst range = document.createRange();\n\tconst fragment = range.createContextualFragment(highlightedHtml);\n\ttemp.appendChild(fragment);\n\treturn temp.querySelector(\"pre.shiki\") as HTMLElement | null;\n}\n\nasync function highlightCodeElement(codeEl: HTMLElement): Promise<void> {\n\tif (codeEl.querySelector(\".shiki\") || codeEl.classList.contains(\"shiki\")) return;\n\tconst lang = codeEl.getAttribute(\"data-lang\") || \"\";\n\tif (!(await ensureLanguageLoaded(lang))) return;\n\tconst raw = codeEl.textContent || \"\";\n\ttry {\n\t\tconst highlightedHtml = highlighter?.codeToHtml(raw, {\n\t\t\tlang: lang,\n\t\t\tthemes: {\n\t\t\t\tlight: \"github-light\",\n\t\t\t\tdark: \"github-dark\",\n\t\t\t},\n\t\t});\n\t\tconst shikiPre = parseShikiPre(highlightedHtml ?? \"\");\n\t\tif (!shikiPre) return;\n\t\tapplyShikiStylesToPre(codeEl, shikiPre);\n\t\tapplyShikiMarkupToCode(codeEl, shikiPre);\n\t} catch (_err) {\n\t\t// Highlighting failed for this block -- leave it as plain text.\n\t}\n}\n\nexport async function highlightCodeBlocks(containerEl: HTMLElement | null): Promise<void> {\n\tif (!containerEl) return;\n\tawait initHighlighter();\n\tif (!highlighter) return;\n\tconst codeEls = containerEl.querySelectorAll(\"pre code[data-lang]\");\n\tfor (const codeEl of codeEls) {\n\t\tawait highlightCodeElement(codeEl as HTMLElement);\n\t}\n}\n","// ── Shared icons (CSS mask-image) ────────────────────────\nexport function makeTelegramIcon(): HTMLSpanElement {\n\tconst el = document.createElement(\"span\");\n\tel.className = \"icon icon-telegram\";\n\treturn el;\n}\n\nexport function makeTeamsIcon(): HTMLSpanElement {\n\tconst el = document.createElement(\"span\");\n\tel.className = \"icon icon-msteams\";\n\treturn el;\n}\n\nexport function makeDiscordIcon(): HTMLSpanElement {\n\tconst el = document.createElement(\"span\");\n\tel.className = \"icon icon-discord\";\n\treturn el;\n}\n\nexport function makeSlackIcon(): HTMLSpanElement {\n\tconst el = document.createElement(\"span\");\n\tel.className = \"icon icon-slack\";\n\treturn el;\n}\n\nexport function makeMatrixIcon(): HTMLSpanElement {\n\tconst el = document.createElement(\"span\");\n\tel.className = \"icon icon-matrix\";\n\treturn el;\n}\n\nexport function makeNostrIcon(): HTMLSpanElement {\n\tconst el = document.createElement(\"span\");\n\tel.className = \"icon icon-nostr\";\n\treturn el;\n}\n\nexport function makeCronIcon(): HTMLSpanElement {\n\tconst el = document.createElement(\"span\");\n\tel.className = \"icon icon-cron\";\n\treturn el;\n}\n\nexport function makeBranchIcon(): HTMLSpanElement {\n\tconst el = document.createElement(\"span\");\n\tel.className = \"icon icon-branch\";\n\treturn el;\n}\n\nexport function makeProjectIcon(): HTMLSpanElement {\n\tconst el = document.createElement(\"span\");\n\tel.className = \"icon icon-xs icon-folder\";\n\treturn el;\n}\n\nexport function makeChatIcon(): HTMLSpanElement {\n\tconst el = document.createElement(\"span\");\n\tel.className = \"icon icon-chat\";\n\treturn el;\n}\n","// ── Logs alert dot ──────────────────────────────────────────\n\nimport { sendRpc } from \"./helpers\";\nimport * as S from \"./state\";\n\nconst logsAlertDot = document.getElementById(\"logsAlertDot\");\n\nexport function updateLogsAlert(): void {\n\tif (!logsAlertDot) return;\n\tif (S.unseenErrors > 0) {\n\t\tlogsAlertDot.style.display = \"\";\n\t\tlogsAlertDot.style.background = \"var(--error)\";\n\t} else if (S.unseenWarns > 0) {\n\t\tlogsAlertDot.style.display = \"\";\n\t\tlogsAlertDot.style.background = \"var(--warn)\";\n\t} else {\n\t\tlogsAlertDot.style.display = \"none\";\n\t}\n}\n\nexport function clearLogsAlert(): void {\n\tS.setUnseenErrors(0);\n\tS.setUnseenWarns(0);\n\tupdateLogsAlert();\n\tif (S.connected) sendRpc(\"logs.ack\", {});\n}\n","// ── Central route definitions ────────────────────────────────\n//\n// All SPA paths are defined once in Rust (SpaRoutes) and injected\n// via gon. This module re-exports them so JS never hardcodes paths.\n\nimport * as gon from \"./gon\";\nimport type { SpaRoutes } from \"./types/gon\";\n\nconst r: Partial<SpaRoutes> = gon.get(\"routes\") || {};\nexport const routes: Partial<SpaRoutes> = r;\n\nexport function settingsPath(id: string): string {\n\treturn `${r.settings}/${id}`;\n}\n","// ── Router ──────────────────────────────────────────────────\n\nimport { clearLogsAlert } from \"./logs-alert\";\nimport { routes } from \"./routes\";\nimport * as S from \"./state\";\n\ninterface PageEntry {\n\tinit: (container: HTMLElement, param?: string | null) => void;\n\tteardown: () => void;\n}\n\ninterface PrefixRoute {\n\tprefix: string;\n\tinit: (container: HTMLElement, param?: string | null) => void;\n\tteardown: () => void;\n}\n\ninterface RouteMatch {\n\tpage: PageEntry | null;\n\tmatchedPrefix: string | null;\n\tparam: string | null;\n}\n\nconst pages: Record<string, PageEntry> = {};\nconst prefixRoutes: PrefixRoute[] = [];\nexport let currentPage: string | null = null;\nexport let currentPrefix: string | null = null;\n\nexport function sessionPath(key: string): string {\n\treturn `/chats/${key.replace(/:/g, \"/\")}`;\n}\nconst pageContent = S.$(\"pageContent\")!;\nconst sessionsPanel = S.$(\"sessionsPanel\")!;\n\nexport function registerPage(\n\tpath: string,\n\tinit: (container: HTMLElement, param?: string | null) => void,\n\tteardown?: () => void,\n): void {\n\tpages[path] = {\n\t\tinit: init,\n\t\tteardown:\n\t\t\tteardown ||\n\t\t\t(() => {\n\t\t\t\t/* noop */\n\t\t\t}),\n\t};\n}\n\nexport function registerPrefix(\n\tprefix: string,\n\tinit: (container: HTMLElement, param?: string | null) => void,\n\tteardown?: () => void,\n): void {\n\tprefixRoutes.push({\n\t\tprefix: prefix,\n\t\tinit: init,\n\t\tteardown:\n\t\t\tteardown ||\n\t\t\t(() => {\n\t\t\t\t/* noop */\n\t\t\t}),\n\t});\n}\n\nexport function navigate(path: string): void {\n\tif (path === currentPage) return;\n\thistory.pushState(null, \"\", path);\n\tmount(path);\n}\n\nfunction teardownCurrentPage(): void {\n\tif (!currentPage) return;\n\tif (pages[currentPage]) {\n\t\tpages[currentPage].teardown();\n\t} else if (currentPrefix) {\n\t\tconst prevPR = prefixRoutes.find((r) => r.prefix === currentPrefix);\n\t\tif (prevPR) prevPR.teardown();\n\t}\n}\n\nfunction findPageRoute(path: string): RouteMatch {\n\tconst page = pages[path];\n\tif (page) return { page: page, matchedPrefix: null, param: null };\n\tfor (const pr of prefixRoutes) {\n\t\tif (path === pr.prefix || path.indexOf(`${pr.prefix}/`) === 0) {\n\t\t\tconst suffix = path.substring(pr.prefix.length + 1);\n\t\t\tconst param = suffix ? decodeURIComponent(suffix.replace(/\\//g, \":\")) : null;\n\t\t\treturn { page: pr, matchedPrefix: pr.prefix, param: param };\n\t\t}\n\t}\n\treturn { page: pages[\"/\"] || null, matchedPrefix: null, param: null };\n}\n\nfunction updateNavActiveState(path: string): void {\n\tconst links = document.querySelectorAll(\".nav-link\");\n\tlinks.forEach((a) => {\n\t\tconst href = a.getAttribute(\"href\");\n\t\tconst active = href === path || (href !== \"/\" && href != null && path.indexOf(href) === 0);\n\t\ta.classList.toggle(\"active\", active);\n\t});\n\n\tconst settingsBtn = document.getElementById(\"settingsBtn\");\n\tif (settingsBtn) {\n\t\tconst settingsActive =\n\t\t\tpath === routes.settings || (routes.settings != null && path.indexOf(`${routes.settings}/`) === 0);\n\t\tsettingsBtn.classList.toggle(\"active\", settingsActive);\n\t}\n}\n\nexport function mount(path: string): void {\n\tconst route = findPageRoute(path);\n\tconst page = route.page;\n\tconst samePrefixNav = route.matchedPrefix && route.matchedPrefix === currentPrefix;\n\n\tif (!samePrefixNav) {\n\t\tteardownCurrentPage();\n\t\tpageContent.textContent = \"\";\n\t\tpageContent.style.cssText = \"\";\n\t}\n\n\tcurrentPage = path;\n\tcurrentPrefix = route.matchedPrefix;\n\n\tupdateNavActiveState(path);\n\n\t// Show sessions panel on chat pages\n\tif (route.matchedPrefix === routes.chats || path === routes.chats) {\n\t\tsessionsPanel.classList.remove(\"hidden\");\n\t} else {\n\t\tsessionsPanel.classList.add(\"hidden\");\n\t}\n\n\t// Clear unseen logs alert when viewing the logs page\n\tif (path === \"/logs\" || path === routes.logs) clearLogsAlert();\n\n\tif (page) page.init(pageContent, route.param);\n}\n\nwindow.addEventListener(\"popstate\", () => {\n\tmount(location.pathname);\n});\n\n// ── Nav panel (burger toggle) ────────────────────────────────\nconst burgerBtn = S.$(\"burgerBtn\");\nconst navPanel = S.$(\"navPanel\");\n\nif (burgerBtn && navPanel) {\n\tburgerBtn.addEventListener(\"click\", () => {\n\t\tnavPanel.classList.toggle(\"hidden\");\n\t});\n}\n\nif (navPanel) {\n\tnavPanel.addEventListener(\"click\", (e: Event) => {\n\t\tconst link = (e.target as HTMLElement).closest(\"[data-nav]\");\n\t\tif (!link) return;\n\t\te.preventDefault();\n\t\tconst href = link.getAttribute(\"href\");\n\t\tif (href) navigate(href);\n\t});\n}\n\nconst titleLink = document.getElementById(\"titleLink\");\nif (titleLink) {\n\ttitleLink.addEventListener(\"click\", (e: Event) => {\n\t\te.preventDefault();\n\t\tnavigate(routes.chats || \"/chats\");\n\t});\n}\n","// ── Chat UI ─────────────────────────────────────────────────\n\nimport { formatTokens, parseErrorMessage, sendRpc, updateCountdown } from \"./helpers\";\nimport * as S from \"./state\";\n\ninterface ErrorCardData {\n\ticon?: string;\n\ttitle: string;\n\tdetail?: string;\n\tprovider?: string;\n\tresetsAt?: number | null;\n}\n\ninterface ImageAttachment {\n\tdataUrl: string;\n\tname: string;\n}\n\nfunction clearChatEmptyState(): void {\n\tif (!S.chatMsgBox) return;\n\tconst welcome = S.chatMsgBox.querySelector(\"#welcomeCard\");\n\tif (welcome) welcome.remove();\n\tconst noProviders = S.chatMsgBox.querySelector(\"#noProvidersCard\");\n\tif (noProviders) noProviders.remove();\n\tS.chatMsgBox.classList.remove(\"chat-messages-empty\");\n}\n\n// Scroll chat to bottom and keep it pinned until layout settles.\n// Uses a ResizeObserver to catch any late layout shifts (sidebar re-render,\n// font loading, async style recalc) and re-scrolls until stable.\nexport function scrollChatToBottom(): void {\n\tif (!S.chatMsgBox) return;\n\tS.chatMsgBox.scrollTop = S.chatMsgBox.scrollHeight;\n\tconst box = S.chatMsgBox;\n\tconst observer = new ResizeObserver(() => {\n\t\tbox.scrollTop = box.scrollHeight;\n\t});\n\tobserver.observe(box);\n\tsetTimeout(() => {\n\t\tobserver.disconnect();\n\t}, 500);\n}\n\nexport function chatAddMsg(cls: string, content: string, isHtml?: boolean): HTMLDivElement | null {\n\tif (!S.chatMsgBox) return null;\n\tclearChatEmptyState();\n\tconst el = document.createElement(\"div\");\n\tel.className = `msg ${cls}`;\n\tif (cls === \"system\") {\n\t\tel.classList.add(\"system-notice\");\n\t}\n\tif (isHtml) {\n\t\t// Safe: content is produced by renderMarkdown which escapes via esc() first,\n\t\t// then only adds our own formatting tags (pre, code, strong).\n\t\tel.innerHTML = content; // eslint-disable-line no-unsanitized/property\n\t} else {\n\t\tel.textContent = content;\n\t}\n\tS.chatMsgBox.appendChild(el);\n\tif (!S.chatBatchLoading) S.chatMsgBox.scrollTop = S.chatMsgBox.scrollHeight;\n\treturn el;\n}\n\n/**\n * Add a user message with image thumbnails below the text.\n */\nexport function chatAddMsgWithImages(\n\tcls: string,\n\thtmlContent: string,\n\timages: ImageAttachment[],\n): HTMLDivElement | null {\n\tif (!S.chatMsgBox) return null;\n\tclearChatEmptyState();\n\tconst el = document.createElement(\"div\");\n\tel.className = `msg ${cls}`;\n\tif (htmlContent) {\n\t\tconst textDiv = document.createElement(\"div\");\n\t\t// Safe: htmlContent is produced by renderMarkdown which escapes user\n\t\t// input via esc() first, then only adds our own formatting tags.\n\t\t// This is the same pattern used in chatAddMsg above.\n\t\ttextDiv.innerHTML = htmlContent; // eslint-disable-line no-unsanitized/property\n\t\tel.appendChild(textDiv);\n\t}\n\tif (images && images.length > 0) {\n\t\tconst thumbRow = document.createElement(\"div\");\n\t\tthumbRow.className = \"msg-image-row\";\n\t\tfor (const img of images) {\n\t\t\tconst thumb = document.createElement(\"img\");\n\t\t\tthumb.className = \"msg-image-thumb\";\n\t\t\tthumb.src = img.dataUrl;\n\t\t\tthumb.alt = img.name;\n\t\t\tthumbRow.appendChild(thumb);\n\t\t}\n\t\tel.appendChild(thumbRow);\n\t}\n\tS.chatMsgBox.appendChild(el);\n\tif (!S.chatBatchLoading) S.chatMsgBox.scrollTop = S.chatMsgBox.scrollHeight;\n\treturn el;\n}\n\nexport function stripChannelPrefix(text: string): string {\n\treturn text.replace(/^\\[Telegram(?:\\s+from\\s+[^\\]]+)?\\]\\s*/, \"\");\n}\n\ninterface ChannelFooterInfo {\n\tchannel_type?: string;\n\tusername?: string;\n\tsender_name?: string;\n\tmessage_kind?: string;\n}\n\nexport function appendChannelFooter(el: HTMLElement, channel: ChannelFooterInfo): void {\n\tconst ft = document.createElement(\"div\");\n\tft.className = \"msg-channel-footer\";\n\tlet label = channel.channel_type || \"channel\";\n\tconst who = channel.username ? `@${channel.username}` : channel.sender_name;\n\tif (who) label += ` \\u00b7 ${who}`;\n\tif (channel.message_kind === \"voice\") {\n\t\tconst icon = document.createElement(\"span\");\n\t\ticon.className = \"voice-icon\";\n\t\ticon.setAttribute(\"aria-hidden\", \"true\");\n\t\tft.appendChild(icon);\n\t}\n\n\tconst text = document.createElement(\"span\");\n\ttext.textContent = `via ${label}`;\n\tft.appendChild(text);\n\tel.appendChild(ft);\n}\n\nexport function removeThinking(): void {\n\tconst el = document.getElementById(\"thinkingIndicator\");\n\tif (el) el.remove();\n}\n\nexport function appendReasoningDisclosure(\n\tmessageEl: HTMLElement | null,\n\treasoningText: string | null | undefined,\n): HTMLDetailsElement | null {\n\tif (!messageEl) return null;\n\tconst normalized = String(reasoningText || \"\").trim();\n\tif (!normalized) return null;\n\tconst existing = messageEl.querySelector(\".msg-reasoning\");\n\tif (existing) existing.remove();\n\tconst details = document.createElement(\"details\");\n\tdetails.className = \"msg-reasoning\";\n\tconst summary = document.createElement(\"summary\");\n\tsummary.className = \"msg-reasoning-summary\";\n\tsummary.textContent = \"Reasoning\";\n\tdetails.appendChild(summary);\n\tconst body = document.createElement(\"div\");\n\tbody.className = \"msg-reasoning-body\";\n\tbody.textContent = normalized;\n\tdetails.appendChild(body);\n\tmessageEl.appendChild(details);\n\treturn details;\n}\n\nexport function chatAddErrorCard(err: ErrorCardData): void {\n\tif (!S.chatMsgBox) return;\n\tclearChatEmptyState();\n\tconst el = document.createElement(\"div\");\n\tel.className = \"msg error-card\";\n\n\tconst icon = document.createElement(\"div\");\n\ticon.className = \"error-icon\";\n\ticon.textContent = err.icon || \"\\u26A0\\uFE0F\";\n\tel.appendChild(icon);\n\n\tconst body = document.createElement(\"div\");\n\tbody.className = \"error-body\";\n\n\tconst title = document.createElement(\"div\");\n\ttitle.className = \"error-title\";\n\ttitle.textContent = err.title;\n\tbody.appendChild(title);\n\n\tif (err.detail) {\n\t\tconst detail = document.createElement(\"div\");\n\t\tdetail.className = \"error-detail\";\n\t\tdetail.textContent = err.detail;\n\t\tbody.appendChild(detail);\n\t}\n\n\tif (err.provider) {\n\t\tconst prov = document.createElement(\"div\");\n\t\tprov.className = \"error-detail\";\n\t\tprov.textContent = `Provider: ${err.provider}`;\n\t\tprov.style.marginTop = \"4px\";\n\t\tprov.style.opacity = \"0.6\";\n\t\tbody.appendChild(prov);\n\t}\n\n\tif (err.resetsAt) {\n\t\tconst countdown = document.createElement(\"div\");\n\t\tcountdown.className = \"error-countdown\";\n\t\tel.appendChild(body);\n\t\tel.appendChild(countdown);\n\t\tupdateCountdown(countdown, err.resetsAt);\n\t\tconst timer = setInterval(() => {\n\t\t\tif (updateCountdown(countdown, err.resetsAt!)) clearInterval(timer);\n\t\t}, 1000);\n\t} else {\n\t\tel.appendChild(body);\n\t}\n\n\tS.chatMsgBox.appendChild(el);\n\tS.chatMsgBox.scrollTop = S.chatMsgBox.scrollHeight;\n}\n\nexport function chatAddErrorMsg(message: string): void {\n\tchatAddErrorCard(parseErrorMessage(message));\n}\n\nexport function renderApprovalCard(requestId: string, command: string): void {\n\tif (!S.chatMsgBox) return;\n\tclearChatEmptyState();\n\tconst tpl = document.getElementById(\"tpl-approval-card\") as HTMLTemplateElement;\n\tconst frag = tpl.content.cloneNode(true) as DocumentFragment;\n\tconst card = frag.firstElementChild as HTMLElement;\n\tcard.id = `approval-${requestId}`;\n\n\t(card.querySelector(\".approval-cmd\") as HTMLElement).textContent = command;\n\n\tconst allowBtn = card.querySelector(\".approval-allow\") as HTMLButtonElement;\n\tconst denyBtn = card.querySelector(\".approval-deny\") as HTMLButtonElement;\n\tallowBtn.onclick = () => {\n\t\tresolveApproval(requestId, \"approved\", command, card);\n\t};\n\tdenyBtn.onclick = () => {\n\t\tresolveApproval(requestId, \"denied\", null, card);\n\t};\n\n\tconst countdown = card.querySelector(\".approval-countdown\") as HTMLElement;\n\tlet remaining = 120;\n\tconst timer = setInterval(() => {\n\t\tremaining--;\n\t\tcountdown.textContent = `${remaining}s`;\n\t\tif (remaining <= 0) {\n\t\t\tclearInterval(timer);\n\t\t\tcard.classList.add(\"approval-expired\");\n\t\t\tallowBtn.disabled = true;\n\t\t\tdenyBtn.disabled = true;\n\t\t\tcountdown.textContent = \"expired\";\n\t\t}\n\t}, 1000);\n\tcountdown.textContent = `${remaining}s`;\n\n\tS.chatMsgBox.appendChild(card);\n\tS.chatMsgBox.scrollTop = S.chatMsgBox.scrollHeight;\n}\n\nexport function resolveApproval(requestId: string, decision: string, command: string | null, card: HTMLElement): void {\n\tconst params: Record<string, string> = { requestId, decision };\n\tif (command) params.command = command;\n\tsendRpc(\"exec.approval.resolve\", params).then(() => {\n\t\tcard.classList.add(\"approval-resolved\");\n\t\tcard.querySelectorAll<HTMLButtonElement>(\".approval-btn\").forEach((b) => {\n\t\t\tb.disabled = true;\n\t\t});\n\t\tconst status = document.createElement(\"div\");\n\t\tstatus.className = \"approval-status\";\n\t\tstatus.textContent = decision === \"approved\" ? \"Allowed\" : \"Denied\";\n\t\tcard.appendChild(status);\n\t});\n}\n\nexport function highlightAndScroll(msgEls: (HTMLElement | null)[], messageIndex: number, query: string): void {\n\tlet target: HTMLElement | null = null;\n\tif (messageIndex >= 0 && messageIndex < msgEls.length && msgEls[messageIndex]) {\n\t\ttarget = msgEls[messageIndex];\n\t}\n\tconst lowerQ = query.toLowerCase();\n\tif (!target || (target.textContent || \"\").toLowerCase().indexOf(lowerQ) === -1) {\n\t\tfor (const candidate of msgEls) {\n\t\t\tif (candidate && (candidate.textContent || \"\").toLowerCase().indexOf(lowerQ) !== -1) {\n\t\t\t\ttarget = candidate;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t}\n\tif (!target) return;\n\tmsgEls.forEach((el) => {\n\t\tif (el) highlightTermInElement(el, query);\n\t});\n\ttarget.scrollIntoView({ behavior: \"smooth\", block: \"center\" });\n\ttarget.classList.add(\"search-highlight-msg\");\n\tsetTimeout(() => {\n\t\tif (!S.chatMsgBox) return;\n\t\tS.chatMsgBox.querySelectorAll(\"mark.search-term-highlight\").forEach((m) => {\n\t\t\tconst parent = m.parentNode!;\n\t\t\tparent.replaceChild(document.createTextNode(m.textContent || \"\"), m);\n\t\t\tparent.normalize();\n\t\t});\n\t\tS.chatMsgBox.querySelectorAll(\".search-highlight-msg\").forEach((el) => {\n\t\t\tel.classList.remove(\"search-highlight-msg\");\n\t\t});\n\t}, 5000);\n}\n\nexport function highlightTermInElement(el: HTMLElement, query: string): void {\n\tconst walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, null);\n\tconst nodes: Text[] = [];\n\twhile (walker.nextNode()) nodes.push(walker.currentNode as Text);\n\tconst lowerQ = query.toLowerCase();\n\tnodes.forEach((textNode) => {\n\t\tconst text = textNode.nodeValue || \"\";\n\t\tconst lowerText = text.toLowerCase();\n\t\tlet idx = lowerText.indexOf(lowerQ);\n\t\tif (idx === -1) return;\n\t\tconst frag = document.createDocumentFragment();\n\t\tlet pos = 0;\n\t\twhile (idx !== -1) {\n\t\t\tif (idx > pos) frag.appendChild(document.createTextNode(text.substring(pos, idx)));\n\t\t\tconst mark = document.createElement(\"mark\");\n\t\t\tmark.className = \"search-term-highlight\";\n\t\t\tmark.textContent = text.substring(idx, idx + query.length);\n\t\t\tfrag.appendChild(mark);\n\t\t\tpos = idx + query.length;\n\t\t\tidx = lowerText.indexOf(lowerQ, pos);\n\t\t}\n\t\tif (pos < text.length) frag.appendChild(document.createTextNode(text.substring(pos)));\n\t\ttextNode.parentNode?.replaceChild(frag, textNode);\n\t});\n}\n\nexport function chatAutoResize(): void {\n\tif (!S.chatInput) return;\n\tS.chatInput.style.height = \"auto\";\n\tS.chatInput.style.height = `${Math.min(S.chatInput.scrollHeight, 120)}px`;\n}\n\nexport function updateCommandInputUI(): void {\n\tif (!S.chatInput) return;\n\tconst row = S.chatInput.closest(\".chat-input-row\");\n\tif (row) {\n\t\trow.classList.toggle(\"command-mode\", S.commandModeEnabled);\n\t}\n\tconst prompt = S.$(\"chatCommandPrompt\");\n\tif (prompt) {\n\t\tprompt.textContent = S.sessionExecPromptSymbol || \"$\";\n\t\tprompt.classList.toggle(\"chat-command-prompt-hidden\", !S.commandModeEnabled);\n\t\tprompt.setAttribute(\"aria-hidden\", S.commandModeEnabled ? \"false\" : \"true\");\n\t}\n\tif (S.commandModeEnabled) {\n\t\t(S.chatInput as HTMLTextAreaElement).placeholder = \"Run shell command\\u2026\";\n\t\tS.chatInput.setAttribute(\"aria-label\", \"Command input\");\n\t} else {\n\t\t(S.chatInput as HTMLTextAreaElement).placeholder = \"Type a message...\";\n\t\tS.chatInput.setAttribute(\"aria-label\", \"Chat input\");\n\t}\n\tupdateTokenBar();\n}\n\nexport function updateTokenBar(): void {\n\tconst bar = S.$(\"tokenBar\");\n\tif (!bar) return;\n\tconst total = S.sessionTokens.input + S.sessionTokens.output;\n\tlet text =\n\t\tformatTokens(S.sessionTokens.input) +\n\t\t\" in / \" +\n\t\tformatTokens(S.sessionTokens.output) +\n\t\t\" out \\u00b7 \" +\n\t\tformatTokens(total) +\n\t\t\" tokens\";\n\tif (S.sessionContextWindow > 0) {\n\t\tconst currentInput = S.sessionCurrentInputTokens || 0;\n\t\tconst pct = Math.max(0, 100 - Math.round((currentInput / S.sessionContextWindow) * 100));\n\t\ttext += ` \\u00b7 Context left before auto-compact: ${pct}%`;\n\t}\n\tif (!S.sessionToolsEnabled) {\n\t\ttext += \" \\u00b7 Tools: disabled\";\n\t}\n\tconst execModeLabel = S.sessionExecMode === \"sandbox\" ? \"sandboxed\" : \"host\";\n\tconst promptSymbol = S.sessionExecPromptSymbol || \"$\";\n\ttext += ` \\u00b7 Execute: ${execModeLabel} (${promptSymbol})`;\n\tif (S.commandModeEnabled) {\n\t\ttext += \" \\u00b7 /sh mode\";\n\t}\n\tbar.textContent = text;\n}\n","import { renderAudioPlayer, sendRpc } from \"./helpers\";\n\nlet cachedTtsEnabled: boolean | null = null;\nlet pendingStatus: Promise<boolean> | null = null;\n\nasync function isTtsEnabled(): Promise<boolean> {\n\tif (cachedTtsEnabled !== null) return cachedTtsEnabled;\n\tif (!pendingStatus) {\n\t\tpendingStatus = sendRpc(\"tts.status\", {})\n\t\t\t.then((res) => {\n\t\t\t\tcachedTtsEnabled = !!(res?.ok && (res.payload as Record<string, unknown> | undefined)?.enabled === true);\n\t\t\t\treturn cachedTtsEnabled;\n\t\t\t})\n\t\t\t.catch(() => {\n\t\t\t\tcachedTtsEnabled = false;\n\t\t\t\treturn false;\n\t\t\t})\n\t\t\t.finally(() => {\n\t\t\t\tpendingStatus = null;\n\t\t\t});\n\t}\n\treturn pendingStatus;\n}\n\nfunction buildSessionMediaUrl(sessionKey: string | undefined, audioPath: string | undefined): string | null {\n\tif (!(sessionKey && audioPath)) return null;\n\tconst filename = String(audioPath).split(\"/\").pop();\n\tif (!filename) return null;\n\treturn `/api/sessions/${encodeURIComponent(sessionKey)}/media/${encodeURIComponent(filename)}`;\n}\n\nfunction upsertVoiceWarning(messageEl: HTMLElement | null, warningText: string | null): void {\n\tif (!messageEl) return;\n\tlet warningEl = messageEl.querySelector(\".msg-voice-warning\") as HTMLElement | null;\n\tif (!warningText) {\n\t\tif (warningEl) warningEl.remove();\n\t\treturn;\n\t}\n\tif (!warningEl) {\n\t\twarningEl = document.createElement(\"div\");\n\t\twarningEl.className = \"voice-error-result msg-voice-warning\";\n\t\tmessageEl.appendChild(warningEl);\n\t}\n\twarningEl.textContent = warningText;\n}\n\nfunction ensureVoicePlayerSlot(messageEl: HTMLElement | null): HTMLElement | null {\n\tif (!messageEl) return null;\n\tlet slot = messageEl.querySelector(\".msg-voice-player-slot\") as HTMLElement | null;\n\tif (slot) return slot;\n\tslot = document.createElement(\"div\");\n\tslot.className = \"msg-voice-player-slot\";\n\tmessageEl.insertBefore(slot, messageEl.firstChild);\n\treturn slot;\n}\n\nfunction renderPersistedAudio(\n\tmessageEl: HTMLElement,\n\tsessionKey: string | undefined,\n\taudioPath: string | undefined,\n\tautoplay: boolean,\n): boolean {\n\tconst src = buildSessionMediaUrl(sessionKey, audioPath);\n\tif (!src) return false;\n\tconst slot = ensureVoicePlayerSlot(messageEl);\n\tif (!slot) return false;\n\tslot.textContent = \"\";\n\trenderAudioPlayer(slot, src, autoplay === true);\n\treturn true;\n}\n\ninterface AttachMessageVoiceControlOptions {\n\tmessageEl?: HTMLElement | null;\n\tfooterEl?: HTMLElement | null;\n\tsessionKey?: string;\n\ttext?: string;\n\trunId?: string;\n\tmessageIndex?: number;\n\taudioPath?: string;\n\taudioWarning?: string;\n\tforceAction?: boolean;\n\tautoplayOnGenerate?: boolean;\n}\n\nexport async function attachMessageVoiceControl(options: AttachMessageVoiceControlOptions): Promise<void> {\n\tconst messageEl = options?.messageEl;\n\tconst footerEl = options?.footerEl;\n\tif (!(messageEl && footerEl)) return;\n\n\tconst sessionKey = options?.sessionKey;\n\tconst text = String(options?.text || \"\").trim();\n\tconst runId = options?.runId;\n\tconst messageIndex = options?.messageIndex;\n\tconst audioPath = options?.audioPath;\n\tconst audioWarning = options?.audioWarning;\n\tconst forceAction = options?.forceAction === true;\n\tconst autoplayOnGenerate = options?.autoplayOnGenerate === true;\n\n\tupsertVoiceWarning(messageEl, audioWarning || null);\n\tif (!text || audioPath) return;\n\n\tconst showAction = forceAction || (await isTtsEnabled());\n\tif (!showAction) return;\n\n\tlet actionBtn = footerEl.querySelector(\".msg-voice-action\") as HTMLButtonElement | null;\n\tif (!actionBtn) {\n\t\tactionBtn = document.createElement(\"button\");\n\t\tactionBtn.type = \"button\";\n\t\tactionBtn.className = \"msg-voice-action\";\n\t\tactionBtn.textContent = \"Voice it\";\n\t\tfooterEl.appendChild(actionBtn);\n\t}\n\n\tactionBtn.onclick = async (): Promise<void> => {\n\t\tif (!sessionKey) {\n\t\t\tupsertVoiceWarning(messageEl, \"Cannot generate voice: missing session key.\");\n\t\t\treturn;\n\t\t}\n\n\t\tconst params: Record<string, unknown> = { key: sessionKey };\n\t\tif (runId) params.runId = runId;\n\t\tif (Number.isInteger(messageIndex) && (messageIndex as number) >= 0) {\n\t\t\tparams.messageIndex = messageIndex;\n\t\t}\n\t\tif (!(params.runId || Number.isInteger(params.messageIndex))) {\n\t\t\tupsertVoiceWarning(messageEl, \"Cannot generate voice for this message.\");\n\t\t\treturn;\n\t\t}\n\n\t\tactionBtn!.disabled = true;\n\t\tactionBtn!.textContent = \"Voicing...\";\n\t\tconst result = (await sendRpc(\"sessions.voice.generate\", params)) as unknown as Record<string, unknown>;\n\t\tif (!(result?.ok && (result.payload as Record<string, unknown> | undefined)?.audio)) {\n\t\t\tactionBtn!.disabled = false;\n\t\t\tactionBtn!.textContent = \"Retry voice\";\n\t\t\tconst errorText =\n\t\t\t\t((result?.error as Record<string, unknown> | undefined)?.message as string) || \"Voice generation failed.\";\n\t\t\tupsertVoiceWarning(messageEl, errorText);\n\t\t\treturn;\n\t\t}\n\n\t\tif (\n\t\t\t!renderPersistedAudio(\n\t\t\t\tmessageEl,\n\t\t\t\tsessionKey,\n\t\t\t\t(result.payload as Record<string, unknown>).audio as string,\n\t\t\t\tautoplayOnGenerate,\n\t\t\t)\n\t\t) {\n\t\t\tactionBtn!.disabled = false;\n\t\t\tactionBtn!.textContent = \"Retry voice\";\n\t\t\tupsertVoiceWarning(messageEl, \"Voice audio generated but could not be rendered.\");\n\t\t\treturn;\n\t\t}\n\n\t\tupsertVoiceWarning(messageEl, null);\n\t\tactionBtn?.remove();\n\t};\n}\n","// ── Node store (signal-based) ──────────────────────────────\n//\n// Single source of truth for connected remote nodes.\n\nimport { computed, signal } from \"@preact/signals\";\nimport { sendRpc } from \"../helpers\";\nimport type { NodeInfo, RpcResponse } from \"../types\";\n\n// ── Signals ──────────────────────────────────────────────────\nexport const nodes = signal<NodeInfo[]>([]);\nexport const selectedNodeId = signal<string | null>(null);\n\nexport const selectedNode = computed<NodeInfo | null>(() => {\n\tconst id = selectedNodeId.value;\n\tif (!id) return null;\n\treturn nodes.value.find((n) => n.nodeId === id) || null;\n});\n\n// ── Methods ──────────────────────────────────────────────────\n\n/** Replace the full node list from an RPC fetch. */\nexport function setAll(arr: NodeInfo[]): void {\n\tnodes.value = arr || [];\n}\n\n/** Fetch connected nodes from the server via RPC. */\nexport function fetch(): Promise<void> {\n\treturn sendRpc(\"node.list\", {}).then((r) => {\n\t\tconst res = r as RpcResponse<NodeInfo[]>;\n\t\tif (!res?.ok) return;\n\t\tsetAll(res.payload || []);\n\t});\n}\n\n/** Select a node by id. Pass null to clear (local execution). */\nexport function select(id: string | null): void {\n\tselectedNodeId.value = id || null;\n}\n\n/** Look up a node by id. */\nexport function getById(id: string): NodeInfo | null {\n\treturn nodes.value.find((n) => n.nodeId === id) || null;\n}\n\nexport const nodeStore = { nodes, selectedNodeId, selectedNode, setAll, fetch, select, getById };\n","// ── Node selector (chat toolbar dropdown) ───────────────────\n\nimport { onEvent } from \"./events\";\nimport { sendRpc } from \"./helpers\";\nimport * as S from \"./state\";\nimport { nodeStore } from \"./stores/node-store\";\nimport type { NodeInfo } from \"./types\";\n\nlet nodeIdx = -1;\nlet eventUnsubs: Array<() => void> = [];\n\nfunction isSshTargetNode(node: Partial<NodeInfo> | null): boolean {\n\treturn node?.platform === \"ssh\" || String(node?.nodeId || \"\").startsWith(\"ssh:\");\n}\n\nfunction nodeDisplayLabel(node: Partial<NodeInfo> | null): string {\n\tif (!node) return \"Local\";\n\tif (node.displayName) return node.displayName;\n\tif (isSshTargetNode(node)) {\n\t\tconst target = String(node.nodeId || \"\").replace(/^ssh:/, \"\");\n\t\treturn `SSH: ${target}`;\n\t}\n\treturn node.nodeId || \"\";\n}\n\nfunction nodeMetaLabel(node: Partial<NodeInfo> | null): string {\n\tif (!node) return \"\";\n\treturn isSshTargetNode(node) ? \"OpenSSH target\" : node.platform || \"\";\n}\n\nfunction fallbackNodeFromId(nodeId: string | null): Partial<NodeInfo> | null {\n\tif (!nodeId) return null;\n\treturn isSshTargetNode({ nodeId: nodeId } as Partial<NodeInfo>)\n\t\t? { nodeId: nodeId, platform: \"ssh\" }\n\t\t: { nodeId: nodeId };\n}\n\nfunction getNodeByIdOrFallback(nodeId: string): Partial<NodeInfo> | null {\n\treturn nodeStore.getById(nodeId) || fallbackNodeFromId(nodeId);\n}\n\nfunction getSelectedNodeForDisplay(): Partial<NodeInfo> | null {\n\tconst selectedId = nodeStore.selectedNodeId.value;\n\tif (!selectedId) return null;\n\treturn nodeStore.selectedNode.value || fallbackNodeFromId(selectedId);\n}\n\nfunction setSessionNode(sessionKey: string, nodeId: string | null): void {\n\tsendRpc(\"nodes.set_session\", { session_key: sessionKey, node_id: nodeId || null });\n}\n\nfunction updateNodeComboLabel(node: Partial<NodeInfo> | null): void {\n\tif (S.nodeComboLabel) {\n\t\t(S.nodeComboLabel as HTMLElement).textContent = nodeDisplayLabel(node);\n\t}\n\tif (S.nodeComboBtn) {\n\t\t(S.nodeComboBtn as HTMLElement).title = node\n\t\t\t? isSshTargetNode(node)\n\t\t\t\t? `Execution target: ${nodeDisplayLabel(node)}`\n\t\t\t\t: `Execution target: ${nodeDisplayLabel(node)}`\n\t\t\t: \"Execution target: Local\";\n\t}\n}\n\nexport function fetchNodes(): Promise<void> {\n\treturn nodeStore.fetch().then(() => {\n\t\tconst allNodes = nodeStore.nodes.value;\n\t\tconst selectedId = nodeStore.selectedNodeId.value;\n\t\t// Show or hide the node selector depending on whether nodes are connected.\n\t\tif (S.nodeCombo) {\n\t\t\tif (allNodes.length > 0 || selectedId) {\n\t\t\t\t(S.nodeCombo as HTMLElement).classList.remove(\"hidden\");\n\t\t\t} else {\n\t\t\t\t(S.nodeCombo as HTMLElement).classList.add(\"hidden\");\n\t\t\t}\n\t\t}\n\t\tconst selected = getSelectedNodeForDisplay();\n\t\tupdateNodeComboLabel(selected);\n\t});\n}\n\nexport function selectNode(nodeId: string | null): void {\n\tnodeStore.select(nodeId);\n\tconst node = nodeId ? getNodeByIdOrFallback(nodeId) : null;\n\tupdateNodeComboLabel(node);\n\tsetSessionNode(S.activeSessionKey, nodeId);\n\tcloseNodeDropdown();\n}\n\nexport function openNodeDropdown(): void {\n\tif (!S.nodeDropdown) return;\n\t(S.nodeDropdown as HTMLElement).classList.remove(\"hidden\");\n\tnodeIdx = -1;\n\trenderNodeList();\n}\n\nexport function closeNodeDropdown(): void {\n\tif (!S.nodeDropdown) return;\n\t(S.nodeDropdown as HTMLElement).classList.add(\"hidden\");\n\tnodeIdx = -1;\n}\n\nfunction buildNodeItem(node: Partial<NodeInfo> | null, currentId: string | null): HTMLElement {\n\tconst el = document.createElement(\"div\");\n\tel.className = \"model-dropdown-item\";\n\tif (node && node.nodeId === currentId) el.classList.add(\"selected\");\n\tif (!(node || currentId)) {\n\t\t// \"Local\" entry\n\t\tel.classList.add(\"selected\");\n\t}\n\n\tconst label = document.createElement(\"span\");\n\tlabel.className = \"model-item-label\";\n\tlabel.textContent = nodeDisplayLabel(node);\n\tel.appendChild(label);\n\n\tif (node) {\n\t\tconst meta = document.createElement(\"span\");\n\t\tmeta.className = \"model-item-meta\";\n\t\tconst badge = document.createElement(\"span\");\n\t\tbadge.className = \"model-item-provider\";\n\t\tbadge.textContent = nodeMetaLabel(node);\n\t\tmeta.appendChild(badge);\n\t\tel.appendChild(meta);\n\t}\n\n\tel.addEventListener(\"click\", () => selectNode(node ? node.nodeId || null : null));\n\treturn el;\n}\n\nexport function renderNodeList(): void {\n\tif (!S.nodeDropdownList) return;\n\tconst dropdownList = S.nodeDropdownList as HTMLElement;\n\tdropdownList.textContent = \"\";\n\tconst currentId = nodeStore.selectedNodeId.value;\n\tconst allNodes = nodeStore.nodes.value;\n\tconst remoteEntries: Array<Partial<NodeInfo>> = [];\n\n\t// \"Local\" as first item\n\tdropdownList.appendChild(buildNodeItem(null, currentId));\n\n\tif (currentId && !allNodes.some((node) => node.nodeId === currentId)) {\n\t\tconst fallback = getNodeByIdOrFallback(currentId);\n\t\tif (fallback) remoteEntries.push(fallback);\n\t}\n\tfor (const n of allNodes) {\n\t\tremoteEntries.push(n);\n\t}\n\n\tif (remoteEntries.length > 0) {\n\t\tconst divider = document.createElement(\"div\");\n\t\tdivider.className = \"model-dropdown-divider\";\n\t\tdropdownList.appendChild(divider);\n\t}\n\n\tfor (const entry of remoteEntries) {\n\t\tdropdownList.appendChild(buildNodeItem(entry, currentId));\n\t}\n}\n\nfunction updateNodeActive(): void {\n\tif (!S.nodeDropdownList) return;\n\tconst items = (S.nodeDropdownList as HTMLElement).querySelectorAll(\".model-dropdown-item\");\n\titems.forEach((el, i) => {\n\t\tel.classList.toggle(\"kb-active\", i === nodeIdx);\n\t});\n\tif (nodeIdx >= 0 && items[nodeIdx]) {\n\t\t(items[nodeIdx] as HTMLElement).scrollIntoView({ block: \"nearest\" });\n\t}\n}\n\nexport function bindNodeComboEvents(): void {\n\tif (!(S.nodeComboBtn && S.nodeDropdownList && S.nodeCombo)) return;\n\n\t(S.nodeComboBtn as HTMLElement).addEventListener(\"click\", () => {\n\t\tif ((S.nodeDropdown as HTMLElement).classList.contains(\"hidden\")) {\n\t\t\topenNodeDropdown();\n\t\t} else {\n\t\t\tcloseNodeDropdown();\n\t\t}\n\t});\n\n\t(S.nodeDropdown as HTMLElement).addEventListener(\"keydown\", (e: KeyboardEvent) => {\n\t\tconst items = (S.nodeDropdownList as HTMLElement).querySelectorAll(\".model-dropdown-item\");\n\t\tif (e.key === \"ArrowDown\") {\n\t\t\te.preventDefault();\n\t\t\tnodeIdx = Math.min(nodeIdx + 1, items.length - 1);\n\t\t\tupdateNodeActive();\n\t\t} else if (e.key === \"ArrowUp\") {\n\t\t\te.preventDefault();\n\t\t\tnodeIdx = Math.max(nodeIdx - 1, 0);\n\t\t\tupdateNodeActive();\n\t\t} else if (e.key === \"Enter\") {\n\t\t\te.preventDefault();\n\t\t\tif (nodeIdx >= 0 && items[nodeIdx]) (items[nodeIdx] as HTMLElement).click();\n\t\t} else if (e.key === \"Escape\") {\n\t\t\tcloseNodeDropdown();\n\t\t\tif (S.nodeComboBtn) (S.nodeComboBtn as HTMLElement).focus();\n\t\t}\n\t});\n\n\t// Subscribe to presence and telemetry events for live updates.\n\teventUnsubs.push(onEvent(\"presence\", () => fetchNodes()));\n\teventUnsubs.push(onEvent(\"node.telemetry\", () => fetchNodes()));\n}\n\nexport function unbindNodeEvents(): void {\n\tfor (const unsub of eventUnsubs) unsub();\n\teventUnsubs = [];\n}\n\ndocument.addEventListener(\"click\", (e: MouseEvent) => {\n\tif (S.nodeCombo && !(S.nodeCombo as HTMLElement).contains(e.target as Node)) {\n\t\tcloseNodeDropdown();\n\t}\n});\n\n/** Restore node selection from session metadata (called on session switch). */\nexport function restoreNodeSelection(nodeId: string | null): void {\n\tnodeStore.select(nodeId || null);\n\tconst node = nodeId ? getNodeByIdOrFallback(nodeId) : null;\n\tupdateNodeComboLabel(node);\n}\n","// ── Session project combo (in chat header) ──────────────────\n\nimport { sendRpc } from \"./helpers\";\nimport { t } from \"./i18n\";\nimport * as S from \"./state\";\nimport type { ProjectInfo } from \"./types\";\n\nexport function openProjectDropdown(): void {\n\tif (!S.projectDropdown) return;\n\tS.projectDropdown.classList.remove(\"hidden\");\n\trenderProjectDropdownList();\n}\n\nexport function closeProjectDropdown(): void {\n\tif (!S.projectDropdown) return;\n\tS.projectDropdown.classList.add(\"hidden\");\n}\n\nexport function renderProjectDropdownList(): void {\n\tif (!S.projectDropdownList) return;\n\tS.projectDropdownList.textContent = \"\";\n\t// \"No project\" option\n\tconst none = document.createElement(\"div\");\n\tnone.className = `model-dropdown-item${S.activeProjectId ? \"\" : \" selected\"}`;\n\tconst noneLabel = document.createElement(\"span\");\n\tnoneLabel.className = \"model-item-label\";\n\tnoneLabel.textContent = t(\"common:sessions.noProject\");\n\tnone.appendChild(noneLabel);\n\tnone.addEventListener(\"click\", () => {\n\t\tselectProject(\"\", t(\"common:sessions.noProject\"));\n\t});\n\tS.projectDropdownList.appendChild(none);\n\t((S.projects as Array<ProjectInfo & { label?: string }>) || []).forEach((p) => {\n\t\tconst el = document.createElement(\"div\");\n\t\tel.className = `model-dropdown-item${p.id === S.activeProjectId ? \" selected\" : \"\"}`;\n\t\tconst lbl = document.createElement(\"span\");\n\t\tlbl.className = \"model-item-label\";\n\t\tlbl.textContent = p.label || p.id;\n\t\tel.appendChild(lbl);\n\t\tel.addEventListener(\"click\", () => {\n\t\t\tselectProject(p.id, p.label || p.id);\n\t\t});\n\t\tS.projectDropdownList?.appendChild(el);\n\t});\n}\n\nexport function selectProject(id: string, label: string): void {\n\tS.setActiveProjectId(id);\n\tlocalStorage.setItem(\"moltis-project\", S.activeProjectId);\n\tif (S.projectComboLabel) S.projectComboLabel.textContent = label;\n\tcloseProjectDropdown();\n\tif (S.connected && S.activeSessionKey) {\n\t\tsendRpc(\"sessions.patch\", { key: S.activeSessionKey, projectId: id });\n\t}\n}\n\nexport function updateSessionProjectSelect(projectId: string): void {\n\tif (!S.projectComboLabel) return;\n\tif (!projectId) {\n\t\tS.projectComboLabel.textContent = t(\"common:sessions.noProject\");\n\t\treturn;\n\t}\n\tconst proj = ((S.projects as Array<ProjectInfo & { label?: string }>) || []).find((p) => p.id === projectId);\n\tS.projectComboLabel.textContent = proj ? proj.label || proj.id : projectId;\n}\n\nexport function renderSessionProjectSelect(): void {\n\tupdateSessionProjectSelect(S.activeProjectId);\n}\n\nexport function bindProjectComboEvents(): void {\n\tif (!(S.projectComboBtn && S.projectCombo)) return;\n\tS.projectComboBtn.addEventListener(\"click\", () => {\n\t\tif (S.projectDropdown?.classList.contains(\"hidden\")) {\n\t\t\topenProjectDropdown();\n\t\t} else {\n\t\t\tcloseProjectDropdown();\n\t\t}\n\t});\n}\n\ndocument.addEventListener(\"click\", (e: MouseEvent) => {\n\tif (S.projectCombo && !S.projectCombo.contains(e.target as Node)) {\n\t\tcloseProjectDropdown();\n\t}\n});\n\nwindow.addEventListener(\"moltis:locale-changed\", () => {\n\tupdateSessionProjectSelect(S.activeProjectId);\n\tif (S.projectDropdown && !S.projectDropdown.classList.contains(\"hidden\")) {\n\t\trenderProjectDropdownList();\n\t}\n});\n","// ── Reasoning effort toggle ──────────────────────────────────\n//\n// Adds a \"brain\" combo next to the model selector that lets users\n// pick Low / Medium / High reasoning effort for models that support\n// extended thinking.  The selected effort is appended as a\n// `@reasoning-*` suffix on the model ID sent to the backend -- no\n// backend changes required.\n\nimport { effect } from \"@preact/signals\";\nimport { t } from \"./i18n\";\nimport { modelStore } from \"./stores/model-store\";\n\nconst EFFORT_VALUES: string[] = [\"\", \"low\", \"medium\", \"high\"];\n\nlet reasoningCombo: HTMLElement | null = null;\nlet reasoningComboBtn: HTMLElement | null = null;\nlet reasoningComboLabel: HTMLElement | null = null;\nlet reasoningDropdown: HTMLElement | null = null;\nlet reasoningDropdownList: HTMLElement | null = null;\nlet disposeVisibility: (() => void) | null = null;\n\nfunction effortLabel(effort: string): string {\n\tconst map: Record<string, string> = {\n\t\t\"\": t(\"chat:reasoningOff\"),\n\t\tlow: t(\"chat:reasoningLow\"),\n\t\tmedium: t(\"chat:reasoningMedium\"),\n\t\thigh: t(\"chat:reasoningHigh\"),\n\t};\n\treturn map[effort] ?? t(\"chat:reasoningOff\");\n}\n\nfunction renderOptions(): void {\n\tif (!reasoningDropdownList) return;\n\treasoningDropdownList.textContent = \"\";\n\tconst current = modelStore.reasoningEffort.value;\n\tfor (const value of EFFORT_VALUES) {\n\t\tconst el = document.createElement(\"div\");\n\t\tel.className = \"model-dropdown-item\";\n\t\tif (value === current) el.classList.add(\"selected\");\n\t\tconst label = document.createElement(\"span\");\n\t\tlabel.className = \"model-item-label\";\n\t\tlabel.textContent = effortLabel(value);\n\t\tel.appendChild(label);\n\t\tel.addEventListener(\"click\", selectEffort.bind(null, value));\n\t\treasoningDropdownList.appendChild(el);\n\t}\n}\n\nfunction selectEffort(effort: string): void {\n\tmodelStore.setReasoningEffort(effort);\n\tif (reasoningComboLabel) reasoningComboLabel.textContent = effortLabel(effort);\n\tcloseDropdown();\n}\n\nfunction openDropdown(): void {\n\tif (!reasoningDropdown) return;\n\trenderOptions();\n\treasoningDropdown.classList.remove(\"hidden\");\n}\n\nfunction closeDropdown(): void {\n\tif (!reasoningDropdown) return;\n\treasoningDropdown.classList.add(\"hidden\");\n}\n\nfunction handleOutsideClick(e: MouseEvent): void {\n\tif (reasoningCombo && !reasoningCombo.contains(e.target as Node)) {\n\t\tcloseDropdown();\n\t}\n}\n\nexport function bindReasoningToggle(): void {\n\treasoningCombo = document.getElementById(\"reasoningCombo\");\n\treasoningComboBtn = document.getElementById(\"reasoningComboBtn\");\n\treasoningComboLabel = document.getElementById(\"reasoningComboLabel\");\n\treasoningDropdown = document.getElementById(\"reasoningDropdown\");\n\treasoningDropdownList = document.getElementById(\"reasoningDropdownList\");\n\tif (!(reasoningCombo && reasoningComboBtn && reasoningDropdownList)) return;\n\n\treasoningComboBtn.addEventListener(\"click\", () => {\n\t\tif (reasoningDropdown?.classList.contains(\"hidden\")) {\n\t\t\topenDropdown();\n\t\t} else {\n\t\t\tcloseDropdown();\n\t\t}\n\t});\n\n\tdocument.addEventListener(\"click\", handleOutsideClick);\n\n\t// Reactively show/hide the combo based on model reasoning support\n\tdisposeVisibility = effect(() => {\n\t\tconst show = modelStore.supportsReasoning.value;\n\t\treasoningCombo?.classList.toggle(\"hidden\", !show);\n\t\t// Reset effort when switching to a non-reasoning model\n\t\tif (!show && modelStore.reasoningEffort.value) {\n\t\t\tmodelStore.setReasoningEffort(\"\");\n\t\t}\n\t\tif (reasoningComboLabel) {\n\t\t\treasoningComboLabel.textContent = effortLabel(modelStore.reasoningEffort.value);\n\t\t}\n\t});\n}\n\n/** Restore reasoning toggle state from a session's stored model ID. */\nexport function restoreReasoningFromModelId(modelId: string): string {\n\tconst parsed = modelStore.parseReasoningSuffix(modelId);\n\tmodelStore.setReasoningEffort(parsed.effort);\n\tif (reasoningComboLabel) {\n\t\treasoningComboLabel.textContent = effortLabel(modelStore.reasoningEffort.value);\n\t}\n\treturn parsed.baseId || modelId;\n}\n\nexport function unbindReasoningToggle(): void {\n\tdocument.removeEventListener(\"click\", handleOutsideClick);\n\tdisposeVisibility?.();\n\tdisposeVisibility = null;\n\treasoningCombo = null;\n\treasoningComboBtn = null;\n\treasoningComboLabel = null;\n\treasoningDropdown = null;\n\treasoningDropdownList = null;\n}\n","// ── Sandbox toggle + image selector ─────────────────────────\n\nimport { updateCommandInputUI, updateTokenBar } from \"./chat-ui\";\nimport { sendRpc } from \"./helpers\";\nimport { t } from \"./i18n\";\nimport * as S from \"./state\";\n\nconst SANDBOX_DISABLED_HINT = (): string => t(\"chat:sandboxDisabledHint\");\n\nfunction sandboxRuntimeAvailable(): boolean {\n\treturn ((S.sandboxInfo as Record<string, unknown> | null)?.backend || \"none\") !== \"none\";\n}\n\n/** Truncate long hash suffixes: \"repo:abcdef...uvwxyz\" */\nfunction truncateHash(str: string): string {\n\tconst idx = str.lastIndexOf(\":\");\n\tif (idx !== -1) {\n\t\tconst suffix = str.slice(idx + 1);\n\t\tif (suffix.length > 12) {\n\t\t\treturn `${str.slice(0, idx + 1) + suffix.slice(0, 6)}\\u2026${suffix.slice(-6)}`;\n\t\t}\n\t}\n\tif (str.length > 24 && str.indexOf(\":\") === -1) {\n\t\treturn `${str.slice(0, 6)}\\u2026${str.slice(-6)}`;\n\t}\n\treturn str;\n}\n\n// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: UI state management with multiple controls\nfunction applySandboxControlAvailability(): boolean {\n\tconst available = sandboxRuntimeAvailable();\n\tconst title = available ? null : SANDBOX_DISABLED_HINT();\n\n\tif (S.sandboxToggleBtn) {\n\t\t(S.sandboxToggleBtn as HTMLButtonElement).disabled = !available;\n\t\t(S.sandboxToggleBtn as HTMLElement).style.opacity = available ? \"\" : \"0.55\";\n\t\t(S.sandboxToggleBtn as HTMLElement).style.cursor = available ? \"pointer\" : \"not-allowed\";\n\t\tif (title) {\n\t\t\t(S.sandboxToggleBtn as HTMLElement).title = title;\n\t\t} else {\n\t\t\t(S.sandboxToggleBtn as HTMLElement).title = t(\"chat:sandboxToggleTooltip\");\n\t\t}\n\t}\n\n\tif (S.sandboxImageBtn) {\n\t\t(S.sandboxImageBtn as HTMLButtonElement).disabled = !available;\n\t\t(S.sandboxImageBtn as HTMLElement).style.opacity = available ? \"\" : \"0.55\";\n\t\t(S.sandboxImageBtn as HTMLElement).style.cursor = available ? \"pointer\" : \"not-allowed\";\n\t\tif (title) {\n\t\t\t(S.sandboxImageBtn as HTMLElement).title = title;\n\t\t} else {\n\t\t\t(S.sandboxImageBtn as HTMLElement).title = t(\"chat:sandboxImageTooltip\");\n\t\t}\n\t}\n\n\tif (!available && S.sandboxImageDropdown) {\n\t\t(S.sandboxImageDropdown as HTMLElement).classList.add(\"hidden\");\n\t}\n\n\treturn available;\n}\n\n// ── Sandbox enabled/disabled toggle ─────────────────────────\n\nexport function updateSandboxUI(enabled: boolean): void {\n\tS.setSessionSandboxEnabled(!!enabled);\n\tconst effectiveSandboxRoute = !!enabled && sandboxRuntimeAvailable();\n\tS.setSessionExecMode(effectiveSandboxRoute ? \"sandbox\" : \"host\");\n\tS.setSessionExecPromptSymbol(effectiveSandboxRoute || S.hostExecIsRoot ? \"#\" : \"$\");\n\tupdateCommandInputUI();\n\tupdateTokenBar();\n\tif (!(S.sandboxLabel && S.sandboxToggleBtn)) return;\n\tif (!applySandboxControlAvailability()) {\n\t\t(S.sandboxLabel as HTMLElement).textContent = t(\"chat:sandboxDisabled\");\n\t\t(S.sandboxToggleBtn as HTMLElement).style.borderColor = \"\";\n\t\t(S.sandboxToggleBtn as HTMLElement).style.color = \"var(--muted)\";\n\t\treturn;\n\t}\n\tif (S.sessionSandboxEnabled) {\n\t\t(S.sandboxLabel as HTMLElement).textContent = t(\"chat:sandboxed\");\n\t\t(S.sandboxToggleBtn as HTMLElement).style.borderColor = \"var(--accent, #f59e0b)\";\n\t\t(S.sandboxToggleBtn as HTMLElement).style.color = \"var(--accent, #f59e0b)\";\n\t} else {\n\t\t(S.sandboxLabel as HTMLElement).textContent = t(\"chat:sandboxDirect\");\n\t\t(S.sandboxToggleBtn as HTMLElement).style.borderColor = \"\";\n\t\t(S.sandboxToggleBtn as HTMLElement).style.color = \"var(--muted)\";\n\t}\n}\n\nexport function bindSandboxToggleEvents(): void {\n\tif (!S.sandboxToggleBtn) return;\n\t(S.sandboxToggleBtn as HTMLElement).addEventListener(\"click\", () => {\n\t\tif (!sandboxRuntimeAvailable()) return;\n\t\tconst newVal = !S.sessionSandboxEnabled;\n\t\tsendRpc(\"sessions.patch\", {\n\t\t\tkey: S.activeSessionKey,\n\t\t\tsandboxEnabled: newVal,\n\t\t}).then((res) => {\n\t\t\tconst payload = res as unknown as Record<string, unknown>;\n\t\t\tif (payload?.result) {\n\t\t\t\tupdateSandboxUI((payload.result as Record<string, unknown>).sandbox_enabled as boolean);\n\t\t\t} else {\n\t\t\t\tupdateSandboxUI(newVal);\n\t\t\t}\n\t\t});\n\t});\n}\n\n// ── Sandbox image selector ──────────────────────────────────\n\nconst DEFAULT_IMAGE = \"ubuntu:25.10\";\nlet sandboxImageBtnEl: HTMLElement | null = null;\nlet sandboxImageBtnClickHandler: ((e: MouseEvent) => void) | null = null;\nlet sandboxImageDocClickHandler: (() => void) | null = null;\nlet sandboxImageRepositionHandler: (() => void) | null = null;\n\nexport function updateSandboxImageUI(image: string | null): void {\n\tS.setSessionSandboxImage(image || null);\n\tif (!S.sandboxImageLabel) return;\n\tif (!applySandboxControlAvailability()) {\n\t\t(S.sandboxImageLabel as HTMLElement).textContent = t(\"chat:sandboxUnavailable\");\n\t\treturn;\n\t}\n\t(S.sandboxImageLabel as HTMLElement).textContent = truncateHash(image || DEFAULT_IMAGE);\n}\n\nexport function bindSandboxImageEvents(): void {\n\tif (!S.sandboxImageBtn) return;\n\tif (sandboxImageBtnEl && sandboxImageBtnClickHandler) {\n\t\tsandboxImageBtnEl.removeEventListener(\"click\", sandboxImageBtnClickHandler);\n\t}\n\tif (sandboxImageDocClickHandler) {\n\t\tdocument.removeEventListener(\"click\", sandboxImageDocClickHandler);\n\t}\n\tif (sandboxImageRepositionHandler) {\n\t\twindow.removeEventListener(\"resize\", sandboxImageRepositionHandler);\n\t\tdocument.removeEventListener(\"scroll\", sandboxImageRepositionHandler, true);\n\t}\n\n\tsandboxImageBtnClickHandler = (e: MouseEvent): void => {\n\t\tif (!sandboxRuntimeAvailable()) return;\n\t\te.stopPropagation();\n\t\ttoggleImageDropdown();\n\t};\n\tsandboxImageDocClickHandler = (): void => {\n\t\tif (S.sandboxImageDropdown) {\n\t\t\t(S.sandboxImageDropdown as HTMLElement).classList.add(\"hidden\");\n\t\t}\n\t};\n\tsandboxImageRepositionHandler = (): void => positionImageDropdown();\n\n\tsandboxImageBtnEl = S.sandboxImageBtn as HTMLElement;\n\tsandboxImageBtnEl.addEventListener(\"click\", sandboxImageBtnClickHandler);\n\tdocument.addEventListener(\"click\", sandboxImageDocClickHandler);\n\n\twindow.addEventListener(\"resize\", sandboxImageRepositionHandler);\n\tdocument.addEventListener(\"scroll\", sandboxImageRepositionHandler, true);\n}\n\nfunction toggleImageDropdown(): void {\n\tif (!(S.sandboxImageDropdown && S.sandboxImageBtn)) return;\n\tconst isHidden = (S.sandboxImageDropdown as HTMLElement).classList.contains(\"hidden\");\n\tif (isHidden) {\n\t\tpopulateImageDropdown();\n\t\t(S.sandboxImageDropdown as HTMLElement).classList.remove(\"hidden\");\n\t\trequestAnimationFrame(positionImageDropdown);\n\t} else {\n\t\t(S.sandboxImageDropdown as HTMLElement).classList.add(\"hidden\");\n\t}\n}\n\nfunction positionImageDropdown(): void {\n\tif (!(S.sandboxImageDropdown && S.sandboxImageBtn)) return;\n\tconst dropdown = S.sandboxImageDropdown as HTMLElement;\n\tconst btn = S.sandboxImageBtn as HTMLElement;\n\tif (dropdown.classList.contains(\"hidden\")) return;\n\n\tconst btnRect = btn.getBoundingClientRect();\n\tconst viewportWidth = window.innerWidth || document.documentElement.clientWidth || 0;\n\tconst viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0;\n\n\tdropdown.style.position = \"fixed\";\n\tdropdown.style.zIndex = \"70\";\n\tdropdown.style.marginTop = \"0\";\n\tdropdown.style.minWidth = `${Math.max(200, Math.round(btnRect.width))}px`;\n\tdropdown.style.maxWidth = `${Math.max(220, viewportWidth - 16)}px`;\n\n\tconst preferredTop = btnRect.bottom + 4;\n\tdropdown.style.top = `${preferredTop}px`;\n\tdropdown.style.left = `${Math.max(8, Math.round(btnRect.left))}px`;\n\n\t// Measure after placement so we can clamp to viewport and optionally open upward.\n\tlet dropdownRect = dropdown.getBoundingClientRect();\n\tconst spaceBelow = viewportHeight - btnRect.bottom - 8;\n\tconst spaceAbove = btnRect.top - 8;\n\tconst shouldOpenUp = spaceBelow < 180 && spaceAbove > spaceBelow;\n\tconst maxHeight = Math.max(120, shouldOpenUp ? spaceAbove : spaceBelow);\n\tdropdown.style.maxHeight = `${Math.floor(maxHeight)}px`;\n\n\tif (shouldOpenUp) {\n\t\tconst desiredTop = btnRect.top - Math.min(dropdownRect.height, maxHeight) - 4;\n\t\tdropdown.style.top = `${Math.max(8, Math.round(desiredTop))}px`;\n\t}\n\n\tdropdownRect = dropdown.getBoundingClientRect();\n\tconst clampedLeft = Math.max(\n\t\t8,\n\t\tMath.min(Math.round(btnRect.left), Math.round(viewportWidth - dropdownRect.width - 8)),\n\t);\n\tdropdown.style.left = `${clampedLeft}px`;\n}\n\nfunction populateImageDropdown(): void {\n\tif (!S.sandboxImageDropdown) return;\n\tconst dropdown = S.sandboxImageDropdown as HTMLElement;\n\tdropdown.textContent = \"\";\n\n\t// Default option\n\taddImageOption(DEFAULT_IMAGE, !S.sessionSandboxImage);\n\n\t// Fetch cached images\n\tfetch(\"/api/images/cached\")\n\t\t.then((r) => r.json())\n\t\t.then((data: Record<string, unknown>) => {\n\t\t\tconst images = (data.images || []) as Array<Record<string, unknown>>;\n\t\t\tfor (const img of images) {\n\t\t\t\tconst isCurrent = S.sessionSandboxImage === img.tag;\n\t\t\t\taddImageOption(img.tag as string, isCurrent, `${img.skill_name} (${img.size})`);\n\t\t\t}\n\t\t\trequestAnimationFrame(positionImageDropdown);\n\t\t})\n\t\t.catch(() => {\n\t\t\t// Silently ignore fetch errors for image list\n\t\t});\n}\n\nfunction addImageOption(tag: string, isActive: boolean, subtitle?: string): void {\n\tconst opt = document.createElement(\"div\");\n\topt.className = \"px-3 py-2 text-xs cursor-pointer hover:bg-[var(--surface2)] transition-colors\";\n\tif (isActive) {\n\t\topt.style.color = \"var(--accent, #f59e0b)\";\n\t\topt.style.fontWeight = \"600\";\n\t}\n\n\tconst label = document.createElement(\"div\");\n\tlabel.textContent = truncateHash(tag);\n\tlabel.title = tag;\n\topt.appendChild(label);\n\n\tif (subtitle) {\n\t\tconst sub = document.createElement(\"div\");\n\t\tsub.textContent = subtitle;\n\t\tsub.style.color = \"var(--muted)\";\n\t\tsub.style.fontSize = \"0.65rem\";\n\t\topt.appendChild(sub);\n\t}\n\n\topt.addEventListener(\"click\", (e: MouseEvent): void => {\n\t\te.stopPropagation();\n\t\tselectImage(tag === DEFAULT_IMAGE ? null : tag);\n\t});\n\n\t(S.sandboxImageDropdown as HTMLElement).appendChild(opt);\n}\n\nfunction selectImage(tag: string | null): void {\n\tconst value = tag || \"\";\n\tsendRpc(\"sessions.patch\", {\n\t\tkey: S.activeSessionKey,\n\t\tsandboxImage: value,\n\t}).then((res) => {\n\t\tconst payload = res as unknown as Record<string, unknown>;\n\t\tif (payload?.result) {\n\t\t\tupdateSandboxImageUI((payload.result as Record<string, unknown>).sandbox_image as string);\n\t\t} else {\n\t\t\tupdateSandboxImageUI(tag);\n\t\t}\n\t});\n\tif (S.sandboxImageDropdown) {\n\t\t(S.sandboxImageDropdown as HTMLElement).classList.add(\"hidden\");\n\t}\n}\n","// ── Session history cache (in-memory) ─────────────────────────\n//\n// Stores per-session chat history so re-selecting a session can render\n// immediately. Histories are patched incrementally from websocket events and\n// refreshed authoritatively from sessions.switch responses.\n\nimport type { HistoryMessage } from \"../types\";\n\nconst historyByKey = new Map<string, HistoryMessage[]>();\nconst revisionByKey = new Map<string, number>();\nconst bytesByKey = new Map<string, number>();\nconst lastAccessByKey = new Map<string, number>();\nlet totalBytes = 0;\nconst encoder: TextEncoder | null = typeof TextEncoder === \"function\" ? new TextEncoder() : null;\n\nconst MAX_TOTAL_HISTORY_BYTES = 12 * 1024 * 1024;\nconst MAX_SESSION_HISTORY_BYTES = 2 * 1024 * 1024;\nconst MIN_SESSION_HISTORY_MESSAGES = 80;\nconst TRIM_STEP_MESSAGES = 25;\n\nfunction deepClone<T>(value: T): T {\n\tif (value === undefined) return undefined as T;\n\tif (typeof structuredClone === \"function\") {\n\t\ttry {\n\t\t\treturn structuredClone(value);\n\t\t} catch (_e) {\n\t\t\t// Fall through to JSON clone.\n\t\t}\n\t}\n\treturn JSON.parse(JSON.stringify(value));\n}\n\nfunction toValidIndex(value: unknown): number | null {\n\tif (value === null || value === undefined) return null;\n\tconst parsed = Number(value);\n\tif (!Number.isInteger(parsed) || parsed < 0) return null;\n\treturn parsed;\n}\n\nfunction messageHistoryIndex(msg: HistoryMessage | null | undefined): number | null {\n\tif (!(msg && typeof msg === \"object\")) return null;\n\tconst direct = toValidIndex(msg.historyIndex);\n\tif (direct !== null) return direct;\n\treturn toValidIndex(msg.messageIndex);\n}\n\nfunction bumpRevision(key: string): void {\n\trevisionByKey.set(key, (revisionByKey.get(key) || 0) + 1);\n}\n\nfunction touchHistoryKey(key: string): void {\n\tlastAccessByKey.set(key, Date.now());\n}\n\nfunction estimateHistoryBytes(history: HistoryMessage[]): number {\n\ttry {\n\t\tconst serialized = JSON.stringify(history || []);\n\t\tif (!serialized) return 0;\n\t\tif (encoder) return encoder.encode(serialized).length;\n\t\treturn serialized.length;\n\t} catch (_e) {\n\t\treturn 0;\n\t}\n}\n\nfunction updateHistorySize(key: string, nextBytes: number): void {\n\tconst prev = bytesByKey.get(key) || 0;\n\tbytesByKey.set(key, nextBytes);\n\ttotalBytes += nextBytes - prev;\n\tif (totalBytes < 0) totalBytes = 0;\n}\n\nfunction dropHistoryKey(key: string): void {\n\tconst prev = bytesByKey.get(key) || 0;\n\thistoryByKey.delete(key);\n\trevisionByKey.delete(key);\n\tbytesByKey.delete(key);\n\tlastAccessByKey.delete(key);\n\ttotalBytes -= prev;\n\tif (totalBytes < 0) totalBytes = 0;\n}\n\nfunction trimSessionHistoryInPlace(list: HistoryMessage[]): number {\n\tlet bytes = estimateHistoryBytes(list);\n\twhile (list.length > MIN_SESSION_HISTORY_MESSAGES && list.length > 1 && bytes > MAX_SESSION_HISTORY_BYTES) {\n\t\tconst removable = list.length - MIN_SESSION_HISTORY_MESSAGES;\n\t\tconst trimCount = Math.min(TRIM_STEP_MESSAGES, removable);\n\t\tlist.splice(0, trimCount);\n\t\tbytes = estimateHistoryBytes(list);\n\t}\n\n\twhile (list.length > 1 && bytes > MAX_SESSION_HISTORY_BYTES) {\n\t\tlist.shift();\n\t\tbytes = estimateHistoryBytes(list);\n\t}\n\n\treturn bytes;\n}\n\nfunction evictGlobalHistoryBudget(preferredKey: string): void {\n\twhile (totalBytes > MAX_TOTAL_HISTORY_BYTES && historyByKey.size > 0) {\n\t\tlet victim: string | null = null;\n\t\tlet oldest = Number.POSITIVE_INFINITY;\n\t\tfor (const [key, ts] of lastAccessByKey.entries()) {\n\t\t\tif (key === preferredKey && historyByKey.size > 1) continue;\n\t\t\tif (ts < oldest) {\n\t\t\t\toldest = ts;\n\t\t\t\tvictim = key;\n\t\t\t}\n\t\t}\n\t\tif (!victim) {\n\t\t\tvictim = historyByKey.keys().next().value ?? null;\n\t\t}\n\t\tif (!victim) break;\n\t\tdropHistoryKey(victim);\n\t}\n}\n\nfunction enforceHistoryBudgets(key: string): void {\n\tconst list = historyByKey.get(key);\n\tif (!list) return;\n\tconst bytes = trimSessionHistoryInPlace(list);\n\tupdateHistorySize(key, bytes);\n\ttouchHistoryKey(key);\n\tevictGlobalHistoryBudget(key);\n}\n\nfunction normalizeMessage(message: unknown, fallbackIndex?: number | null): HistoryMessage {\n\tlet next: HistoryMessage = (deepClone(message) as HistoryMessage) || {};\n\tif (!(next && typeof next === \"object\")) {\n\t\tnext = { role: \"notice\", content: String(message || \"\") };\n\t}\n\tconst idx = toValidIndex(fallbackIndex);\n\tconst msgIdx = idx === null ? messageHistoryIndex(next) : idx;\n\tif (msgIdx !== null) next.historyIndex = msgIdx;\n\treturn next;\n}\n\nfunction upsertWithoutIndex(list: HistoryMessage[], next: HistoryMessage): void {\n\tif (next.role === \"tool_result\" && next.tool_call_id) {\n\t\tconst existingToolIdx = list.findIndex(\n\t\t\t(msg) => msg?.role === \"tool_result\" && msg?.tool_call_id && msg.tool_call_id === next.tool_call_id,\n\t\t);\n\t\tif (existingToolIdx >= 0) {\n\t\t\tlist[existingToolIdx] = next;\n\t\t\treturn;\n\t\t}\n\t}\n\tif (next.role === \"assistant\" && next.run_id) {\n\t\tconst existingRunIdx = list.findIndex(\n\t\t\t(msg) => msg?.role === \"assistant\" && msg?.run_id && msg.run_id === next.run_id,\n\t\t);\n\t\tif (existingRunIdx >= 0) {\n\t\t\tlist[existingRunIdx] = next;\n\t\t\treturn;\n\t\t}\n\t}\n\tlist.push(next);\n}\n\nfunction upsertByIndex(list: HistoryMessage[], next: HistoryMessage, historyIndex: number): void {\n\tconst existingIdx = list.findIndex((msg) => messageHistoryIndex(msg) === historyIndex);\n\tif (existingIdx >= 0) {\n\t\tlist[existingIdx] = next;\n\t\treturn;\n\t}\n\tconst insertAt = list.findIndex((msg) => {\n\t\tconst other = messageHistoryIndex(msg);\n\t\tif (other === null) return true;\n\t\treturn other > historyIndex;\n\t});\n\tif (insertAt === -1) {\n\t\tlist.push(next);\n\t\treturn;\n\t}\n\tlist.splice(insertAt, 0, next);\n}\n\nexport function getHistoryRevision(key: string): number {\n\treturn revisionByKey.get(key) || 0;\n}\n\nexport function hasSessionHistory(key: string): boolean {\n\treturn historyByKey.has(key);\n}\n\nexport function getSessionHistory(key: string): HistoryMessage[] | null {\n\tconst history = historyByKey.get(key) || null;\n\tif (history) touchHistoryKey(key);\n\treturn history;\n}\n\nexport function replaceSessionHistory(key: string, history: unknown[]): HistoryMessage[] {\n\tconst next = Array.isArray(history) ? history.map((msg) => normalizeMessage(msg)) : [];\n\thistoryByKey.set(key, next);\n\tbumpRevision(key);\n\tenforceHistoryBudgets(key);\n\treturn next;\n}\n\nexport function upsertSessionHistoryMessage(\n\tkey: string,\n\tmessage: unknown,\n\thistoryIndex?: number | null,\n): HistoryMessage {\n\tlet list = historyByKey.get(key);\n\tif (!list) {\n\t\tlist = [];\n\t\thistoryByKey.set(key, list);\n\t}\n\tconst next = normalizeMessage(message, historyIndex);\n\tconst idx = messageHistoryIndex(next);\n\tif (idx !== null) {\n\t\tupsertByIndex(list, next, idx);\n\t} else {\n\t\tupsertWithoutIndex(list, next);\n\t}\n\tbumpRevision(key);\n\tenforceHistoryBudgets(key);\n\treturn next;\n}\n\nexport function clearSessionHistory(key?: string): void {\n\tif (key === undefined) {\n\t\thistoryByKey.clear();\n\t\trevisionByKey.clear();\n\t\tbytesByKey.clear();\n\t\tlastAccessByKey.clear();\n\t\ttotalBytes = 0;\n\t\treturn;\n\t}\n\tdropHistoryKey(key);\n}\n","// ── Channel types ───────────────────────────────────────────────\n//\n// Mirrors the Rust types in `crates/channels/src/plugin.rs`.\n\n/**\n * Channel type identifier.\n * Serialised as lowercase via `#[serde(rename_all = \"lowercase\")]`.\n * MsTeams is serialised as `\"msteams\"`.\n */\nexport enum ChannelType {\n\tTelegram = \"telegram\",\n\tWhatsApp = \"whatsapp\",\n\tMsTeams = \"msteams\",\n\tDiscord = \"discord\",\n\tSlack = \"slack\",\n\tMatrix = \"matrix\",\n\tNostr = \"nostr\",\n}\n\n/**\n * How a channel receives inbound messages.\n * Serialised as snake_case via `#[serde(rename_all = \"snake_case\")]`.\n */\nexport type InboundMode = \"none\" | \"polling\" | \"gateway_loop\" | \"socket_mode\" | \"webhook\";\n\n/** Static capability flags for a channel type. */\nexport interface ChannelCapabilities {\n\tinbound_mode: InboundMode;\n\tsupports_outbound: boolean;\n\tsupports_streaming: boolean;\n\tsupports_interactive: boolean;\n\tsupports_threads: boolean;\n\tsupports_voice_ingest: boolean;\n\tsupports_pairing: boolean;\n\tsupports_otp: boolean;\n\tsupports_reactions: boolean;\n\tsupports_location: boolean;\n}\n\n/**\n * Full descriptor for a channel type, including capabilities.\n * Mirrors `ChannelDescriptor` in `crates/channels/src/plugin.rs`.\n * Injected in `gon.channel_descriptors`.\n */\nexport interface ChannelDescriptor {\n\tchannel_type: ChannelType;\n\tdisplay_name: string;\n\tcapabilities: ChannelCapabilities;\n}\n\n/**\n * Where to send the LLM response back.\n * Mirrors `ChannelReplyTarget` in `crates/channels/src/plugin.rs`.\n * Stored as JSON in `SessionMeta.channelBinding`.\n */\nexport interface ChannelReplyTarget {\n\tchannel_type: ChannelType;\n\taccount_id: string;\n\tchat_id: string;\n\tmessage_id?: string;\n\tthread_id?: string;\n}\n\n/**\n * Client-side channel binding attached to a session.\n * A looser shape than `ChannelReplyTarget`, used by the session store\n * when the exact target fields are not needed.\n */\nexport interface ChannelBinding {\n\ttype: string;\n\taccount_id?: string;\n\t[key: string]: unknown;\n}\n","// ── WebSocket event types (discriminated union) ──────────────\n\n/** All WebSocket event names emitted by the moltis gateway. */\nexport enum WsEventName {\n\tChat = \"chat\",\n\tError = \"error\",\n\tAuthCredentialsChanged = \"auth.credentials_changed\",\n\tExecApprovalRequested = \"exec.approval.requested\",\n\tLogsEntry = \"logs.entry\",\n\tSandboxPrepare = \"sandbox.prepare\",\n\tSandboxImageBuild = \"sandbox.image.build\",\n\tSandboxImageProvision = \"sandbox.image.provision\",\n\tSandboxHostProvision = \"sandbox.host.provision\",\n\tBrowserImagePull = \"browser.image.pull\",\n\tLocalLlmDownload = \"local-llm.download\",\n\tModelsUpdated = \"models.updated\",\n\tLocationRequest = \"location.request\",\n\tNetworkAuditEntry = \"network.audit.entry\",\n\t// Additional onEvent() events\n\tTick = \"tick\",\n\tSession = \"session\",\n\tChannel = \"channel\",\n\tPresence = \"presence\",\n\tUpdateAvailable = \"update.available\",\n\tMcpStatus = \"mcp.status\",\n\tHooksStatus = \"hooks.status\",\n\tMetricsUpdate = \"metrics.update\",\n\tSkillsInstallProgress = \"skills.install.progress\",\n\tPushSubscriptions = \"push.subscriptions\",\n\tNodePairRequested = \"node.pair.requested\",\n\tNodePairResolved = \"node.pair.resolved\",\n\tDevicePairResolved = \"device.pair.resolved\",\n\tNodeTelemetry = \"node.telemetry\",\n}\n\n// ── Payload interfaces ───────────────────────────────────────\n\nexport interface ToolResult {\n\tstdout?: string;\n\tstderr?: string;\n\texit_code?: number;\n\tscreenshot?: string;\n\tscreenshot_scale?: number;\n\tdocument_ref?: string;\n\tfilename?: string;\n\tmime_type?: string;\n\tsize_bytes?: number;\n\tpoints?: MapPoint[];\n\tlabel?: string;\n\tmap_links?: MapLinks;\n}\n\nexport interface ToolError {\n\tdetail?: string;\n\tmessage?: string;\n\tretryAfterMs?: number;\n\ttype?: string;\n}\n\nexport interface MapLinks {\n\turl?: string;\n\tgoogle_maps?: string;\n\tapple_maps?: string;\n\topenstreetmap?: string;\n\t[key: string]: unknown;\n}\n\nexport interface MapPoint {\n\tlabel?: string;\n\tlatitude?: number;\n\tlongitude?: number;\n\tmap_links?: MapLinks;\n}\n\nexport interface ToolCallPayload {\n\trunId?: string;\n\ttoolCallId?: string;\n\ttoolName?: string;\n\targuments?: Record<string, unknown>;\n\texecutionMode?: string;\n\tmessageIndex?: number;\n\tsessionKey?: string;\n\tsuccess?: boolean;\n\tresult?: ToolResult;\n\terror?: ToolError;\n}\n\nexport interface ChatError {\n\ttitle?: string;\n\tdetail?: string;\n\tmessage?: string;\n\ttype?: string;\n\tretryAfterMs?: number;\n\tcanContinue?: boolean;\n}\n\nexport interface ChannelInfo {\n\taudio_filename?: string;\n\t[key: string]: unknown;\n}\n\nexport interface PartialMessage {\n\tcontent?: string;\n\treasoning?: string;\n\tmodel?: string;\n\tprovider?: string;\n\tinputTokens?: number;\n\toutputTokens?: number;\n\tdurationMs?: number;\n\trequestInputTokens?: number;\n\trequestOutputTokens?: number;\n\trequestCacheReadTokens?: number;\n\trequestCacheWriteTokens?: number;\n\taudio?: string;\n\trun_id?: string;\n\tcreated_at?: number;\n}\n\nexport interface ChatPayload {\n\tstate?: string;\n\tsessionKey?: string;\n\trunId?: string;\n\ttext?: string;\n\tmodel?: string;\n\tprovider?: string;\n\tinputTokens?: number;\n\toutputTokens?: number;\n\tcacheReadTokens?: number;\n\tcacheWriteTokens?: number;\n\tdurationMs?: number;\n\trequestInputTokens?: number;\n\trequestOutputTokens?: number;\n\trequestCacheReadTokens?: number;\n\trequestCacheWriteTokens?: number;\n\treasoning?: string;\n\taudio?: string;\n\taudioWarning?: string | null;\n\treplyMedium?: string;\n\tmessageIndex?: number;\n\ttoolCallId?: string;\n\ttoolName?: string;\n\targuments?: Record<string, unknown>;\n\texecutionMode?: string;\n\tsuccess?: boolean;\n\tresult?: ToolResult;\n\terror?: ChatError;\n\tmessage?: string;\n\tchannel?: ChannelInfo;\n\ttitle?: string;\n\tphase?: string;\n\tmode?: string;\n\tseq?: number;\n\tretryAfterMs?: number;\n\tpartialMessage?: PartialMessage;\n\tcanContinue?: boolean;\n}\n\nexport interface CompactPayload {\n\tsessionKey?: string;\n\tphase?: string;\n\terror?: string;\n\tmode?: string;\n\t[key: string]: unknown;\n}\n\nexport interface ApprovalPayload {\n\trequestId: string;\n\tcommand: string;\n}\n\nexport interface LogEntryPayload {\n\tlevel?: string;\n\t[key: string]: unknown;\n}\n\nexport interface SandboxPhasePayload {\n\tphase?: string;\n\terror?: string;\n\ttag?: string;\n\tbuilt?: boolean;\n\tcount?: number;\n\tinstalled?: number;\n\tskipped?: number;\n\timage?: string;\n}\n\nexport interface LocalLlmDownloadPayload {\n\tdisplayName?: string;\n\tmodelId?: string;\n\terror?: string;\n\tcomplete?: boolean;\n\tprogress?: number;\n\tdownloaded?: number;\n\ttotal?: number;\n}\n\nexport interface ModelsUpdatedPayload {\n\tphase?: string;\n\t[key: string]: unknown;\n}\n\nexport interface WsErrorPayload {\n\tmessage?: string;\n}\n\nexport interface LocationRequestPayload {\n\trequestId?: string;\n\tprecision?: string;\n}\n\nexport interface AuthCredentialsPayload {\n\treason?: string;\n}\n\nexport interface WsFrame {\n\ttype: string;\n\tevent?: string;\n\tpayload?: Record<string, unknown>;\n\tstream?: unknown;\n\tdone?: unknown;\n\tchannel?: unknown;\n}\n\nexport interface StreamMeta {\n\tstream: unknown;\n\tdone: unknown;\n\tchannel: unknown;\n}\n\nexport interface AbortedPartialState {\n\tpartial: PartialMessage | null;\n\tpartialText: string;\n\tpartialReasoning: string;\n\thasVisiblePartial: boolean;\n}\n\n/** Maps event names to their payload types. */\nexport interface WsEventPayloadMap {\n\t[WsEventName.Chat]: ChatPayload;\n\t[WsEventName.Error]: WsErrorPayload;\n\t[WsEventName.AuthCredentialsChanged]: AuthCredentialsPayload;\n\t[WsEventName.ExecApprovalRequested]: ApprovalPayload;\n\t[WsEventName.LogsEntry]: LogEntryPayload;\n\t[WsEventName.SandboxPrepare]: SandboxPhasePayload;\n\t[WsEventName.SandboxImageBuild]: SandboxPhasePayload;\n\t[WsEventName.SandboxImageProvision]: SandboxPhasePayload;\n\t[WsEventName.SandboxHostProvision]: SandboxPhasePayload;\n\t[WsEventName.BrowserImagePull]: SandboxPhasePayload;\n\t[WsEventName.LocalLlmDownload]: LocalLlmDownloadPayload;\n\t[WsEventName.ModelsUpdated]: ModelsUpdatedPayload;\n\t[WsEventName.LocationRequest]: LocationRequestPayload;\n\t[WsEventName.NetworkAuditEntry]: Record<string, unknown>;\n\t[WsEventName.Tick]: Record<string, unknown>;\n\t[WsEventName.Session]: Record<string, unknown>;\n\t[WsEventName.Channel]: Record<string, unknown>;\n\t[WsEventName.Presence]: Record<string, unknown>;\n\t[WsEventName.UpdateAvailable]: Record<string, unknown>;\n\t[WsEventName.McpStatus]: Record<string, unknown>;\n\t[WsEventName.HooksStatus]: Record<string, unknown>;\n\t[WsEventName.MetricsUpdate]: Record<string, unknown>;\n\t[WsEventName.SkillsInstallProgress]: Record<string, unknown>;\n\t[WsEventName.PushSubscriptions]: Record<string, unknown>;\n\t[WsEventName.NodePairRequested]: Record<string, unknown>;\n\t[WsEventName.NodePairResolved]: Record<string, unknown>;\n\t[WsEventName.DevicePairResolved]: Record<string, unknown>;\n\t[WsEventName.NodeTelemetry]: Record<string, unknown>;\n}\n","// ── Shared Preact UI components ───────────────────────────────\n\nimport type { Signal } from \"@preact/signals\";\nimport { signal } from \"@preact/signals\";\nimport type { ComponentChildren, VNode } from \"preact\";\nimport { useEffect, useRef, useState } from \"preact/hooks\";\nimport { t } from \"./i18n\";\n\n// ── Toast notifications ──────────────────────────────────────\n\ninterface Toast {\n\tid: number;\n\tmessage: string;\n\ttype: string;\n}\n\nexport const toasts: Signal<Toast[]> = signal([]);\nlet toastId = 0;\n\nexport function showToast(message: string, type: string = \"info\"): void {\n\tconst id = ++toastId;\n\ttoasts.value = toasts.value.concat([{ id: id, message: message, type: type }]);\n\tsetTimeout(() => {\n\t\ttoasts.value = toasts.value.filter((toast) => toast.id !== id);\n\t}, 4000);\n}\n\nexport function Toasts(): VNode {\n\treturn (\n\t\t<div class=\"skills-toast-container\">\n\t\t\t{toasts.value.map((toast) => {\n\t\t\t\tconst bg = toast.type === \"error\" ? \"var(--error, #e55)\" : \"var(--accent)\";\n\t\t\t\treturn (\n\t\t\t\t\t<div\n\t\t\t\t\t\tkey={toast.id}\n\t\t\t\t\t\tstyle={{\n\t\t\t\t\t\t\tpointerEvents: \"auto\",\n\t\t\t\t\t\t\tmaxWidth: \"420px\",\n\t\t\t\t\t\t\tpadding: \"10px 16px\",\n\t\t\t\t\t\t\tborderRadius: \"6px\",\n\t\t\t\t\t\t\tfontSize: \".8rem\",\n\t\t\t\t\t\t\tfontWeight: 500,\n\t\t\t\t\t\t\tcolor: \"#fff\",\n\t\t\t\t\t\t\tbackground: bg,\n\t\t\t\t\t\t\tboxShadow: \"0 4px 12px rgba(0,0,0,.15)\",\n\t\t\t\t\t\t}}\n\t\t\t\t\t>\n\t\t\t\t\t\t{toast.message}\n\t\t\t\t\t</div>\n\t\t\t\t);\n\t\t\t})}\n\t\t</div>\n\t);\n}\n\n// ── Modal wrapper ────────────────────────────────────────────\n\ninterface ModalProps {\n\tshow: boolean;\n\tonClose?: () => void;\n\ttitle?: string;\n\tchildren?: ComponentChildren;\n}\n\nexport function Modal(props: ModalProps): VNode | null {\n\tconst show = props.show;\n\tconst onClose = props.onClose;\n\tconst title = props.title;\n\n\tfunction onBackdrop(e: Event): void {\n\t\tif (e.target === e.currentTarget && onClose) onClose();\n\t}\n\n\tuseEffect(() => {\n\t\tif (!show) return;\n\t\tfunction onKey(e: KeyboardEvent): void {\n\t\t\tif (e.key === \"Escape\" && onClose) onClose();\n\t\t}\n\t\tdocument.addEventListener(\"keydown\", onKey);\n\t\treturn () => document.removeEventListener(\"keydown\", onKey);\n\t}, [show, onClose]);\n\n\tif (!show) return null;\n\n\treturn (\n\t\t<div\n\t\t\tclass=\"modal-overlay\"\n\t\t\tonClick={onBackdrop}\n\t\t\tstyle=\"display:flex;position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:100;align-items:center;justify-content:center;\"\n\t\t>\n\t\t\t<div\n\t\t\t\tclass=\"modal-box\"\n\t\t\t\tstyle=\"background:var(--surface);border-radius:var(--radius);padding:20px;max-width:500px;width:90%;max-height:85vh;overflow-y:auto;box-shadow:0 8px 32px rgba(0,0,0,.25);border:1px solid var(--border);\"\n\t\t\t>\n\t\t\t\t<div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;\">\n\t\t\t\t\t<h3 style=\"margin:0;font-size:.95rem;font-weight:600;color:var(--text-strong)\">{title}</h3>\n\t\t\t\t\t<button\n\t\t\t\t\t\tonClick={onClose}\n\t\t\t\t\t\tstyle=\"background:none;border:none;color:var(--muted);font-size:1.1rem;cursor:pointer;padding:2px 6px\"\n\t\t\t\t\t>\n\t\t\t\t\t\t{\"\\u2715\"}\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t\t{props.children}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\n// ── Confirm dialog ───────────────────────────────────────────\n\ninterface ConfirmState {\n\tmessage: string;\n\tresolve: (value: boolean) => void;\n\topts: { confirmLabel?: string; danger?: boolean };\n}\n\nconst confirmState: Signal<ConfirmState | null> = signal(null);\n\nexport function requestConfirm(message: string, opts?: { confirmLabel?: string; danger?: boolean }): Promise<boolean> {\n\treturn new Promise((resolve) => {\n\t\tconfirmState.value = { message: message, resolve: resolve, opts: opts || {} };\n\t});\n}\n\nexport function ConfirmDialog(): VNode | null {\n\tconst s = confirmState.value;\n\tif (!s) return null;\n\n\tfunction yes(): void {\n\t\tif (s) s.resolve(true);\n\t\tconfirmState.value = null;\n\t}\n\tfunction no(): void {\n\t\tif (s) s.resolve(false);\n\t\tconfirmState.value = null;\n\t}\n\n\tconst label = s.opts.confirmLabel || t(\"common:actions.confirm\");\n\tconst danger = s.opts.danger;\n\tconst btnClass = danger ? \"provider-btn provider-btn-danger\" : \"provider-btn\";\n\n\treturn (\n\t\t<Modal show={true} onClose={no} title={t(\"common:actions.confirm\")}>\n\t\t\t<p style=\"font-size:.85rem;color:var(--text);margin:0 0 16px;\">{s.message}</p>\n\t\t\t<div style=\"display:flex;gap:8px;justify-content:flex-end;\">\n\t\t\t\t<button onClick={no} class=\"provider-btn provider-btn-secondary\">\n\t\t\t\t\t{t(\"common:actions.cancel\")}\n\t\t\t\t</button>\n\t\t\t\t<button onClick={yes} class={btnClass}>\n\t\t\t\t\t{label}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</Modal>\n\t);\n}\n\n/**\n * Vanilla-JS confirm dialog (no Preact needed).\n * Returns a Promise<boolean> -- true if confirmed, false if cancelled.\n * Safe: all content set via textContent, no user input in markup.\n */\nexport function confirmDialog(message: string): Promise<boolean> {\n\treturn new Promise((resolve) => {\n\t\tconst backdrop = document.createElement(\"div\");\n\t\tbackdrop.className = \"provider-modal-backdrop\";\n\n\t\tconst box = document.createElement(\"div\");\n\t\tbox.className = \"provider-modal\";\n\t\tbox.style.width = \"360px\";\n\n\t\tconst body = document.createElement(\"div\");\n\t\tbody.className = \"provider-modal-body\";\n\t\tbody.style.gap = \"16px\";\n\n\t\tconst msg = document.createElement(\"p\");\n\t\tmsg.style.cssText = \"font-size:.85rem;color:var(--text);margin:0\";\n\t\tmsg.textContent = message;\n\n\t\tconst btnRow = document.createElement(\"div\");\n\t\tbtnRow.style.cssText = \"display:flex;gap:8px;justify-content:flex-end\";\n\n\t\tconst cancelBtn = document.createElement(\"button\");\n\t\tcancelBtn.className = \"provider-btn provider-btn-secondary\";\n\t\tcancelBtn.textContent = t(\"common:actions.cancel\");\n\n\t\tconst deleteBtn = document.createElement(\"button\");\n\t\tdeleteBtn.className = \"provider-btn provider-btn-danger\";\n\t\tdeleteBtn.textContent = t(\"common:actions.delete\");\n\n\t\tfunction close(val: boolean): void {\n\t\t\tbackdrop.remove();\n\t\t\tresolve(val);\n\t\t}\n\t\tcancelBtn.addEventListener(\"click\", () => close(false));\n\t\tdeleteBtn.addEventListener(\"click\", () => close(true));\n\t\tbackdrop.addEventListener(\"click\", (e: Event) => {\n\t\t\tif (e.target === backdrop) close(false);\n\t\t});\n\n\t\tbtnRow.appendChild(cancelBtn);\n\t\tbtnRow.appendChild(deleteBtn);\n\t\tbody.appendChild(msg);\n\t\tbody.appendChild(btnRow);\n\t\tbox.appendChild(body);\n\t\tbackdrop.appendChild(box);\n\t\tdocument.body.appendChild(backdrop);\n\t\tdeleteBtn.focus();\n\t});\n}\n\n/**\n * Vanilla-JS share visibility picker using the standard provider modal style.\n * Returns \"public\", \"private\", or null when cancelled.\n */\nexport function shareVisibilityDialog(): Promise<string | null> {\n\treturn new Promise((resolve) => {\n\t\tconst backdrop = document.createElement(\"div\");\n\t\tbackdrop.className = \"provider-modal-backdrop\";\n\n\t\tconst box = document.createElement(\"div\");\n\t\tbox.className = \"provider-modal\";\n\t\tbox.style.width = \"460px\";\n\n\t\tconst header = document.createElement(\"div\");\n\t\theader.className = \"provider-modal-header\";\n\n\t\tconst title = document.createElement(\"div\");\n\t\ttitle.className = \"provider-item-name\";\n\t\ttitle.textContent = t(\"chat:share.title\");\n\n\t\tconst cancelTopBtn = document.createElement(\"button\");\n\t\tcancelTopBtn.className = \"provider-btn provider-btn-secondary provider-btn-sm\";\n\t\tcancelTopBtn.textContent = t(\"common:actions.cancel\");\n\n\t\tconst body = document.createElement(\"div\");\n\t\tbody.className = \"provider-modal-body\";\n\t\tbody.style.gap = \"10px\";\n\n\t\tconst hint = document.createElement(\"p\");\n\t\thint.style.cssText = \"font-size:.8rem;color:var(--muted);margin:0\";\n\t\thint.textContent = t(\"chat:share.hint\");\n\n\t\tconst warning = document.createElement(\"p\");\n\t\twarning.style.cssText =\n\t\t\t\"font-size:.8rem;color:var(--text);margin:0;padding:8px 10px;border:1px solid color-mix(in srgb,var(--warn) 55%,var(--border) 45%);background:color-mix(in srgb,var(--warn) 12%,var(--surface2) 88%);border-radius:var(--radius-sm);line-height:1.45\";\n\t\twarning.textContent = t(\"chat:share.redactionWarning\");\n\n\t\tconst publicBtn = document.createElement(\"button\");\n\t\tpublicBtn.className = \"provider-item\";\n\t\tpublicBtn.type = \"button\";\n\t\tpublicBtn.setAttribute(\"data-share-visibility\", \"public\");\n\t\tconst publicName = document.createElement(\"div\");\n\t\tpublicName.className = \"provider-item-name\";\n\t\tpublicName.textContent = t(\"chat:share.publicLink\");\n\t\tconst publicBadge = document.createElement(\"span\");\n\t\tpublicBadge.className = \"provider-item-badge configured\";\n\t\tpublicBadge.textContent = t(\"chat:share.publicBadge\");\n\t\tpublicBtn.appendChild(publicName);\n\t\tpublicBtn.appendChild(publicBadge);\n\n\t\tconst privateBtn = document.createElement(\"button\");\n\t\tprivateBtn.className = \"provider-item\";\n\t\tprivateBtn.type = \"button\";\n\t\tprivateBtn.setAttribute(\"data-share-visibility\", \"private\");\n\t\tconst privateName = document.createElement(\"div\");\n\t\tprivateName.className = \"provider-item-name\";\n\t\tprivateName.textContent = t(\"chat:share.privateLink\");\n\t\tconst privateBadge = document.createElement(\"span\");\n\t\tprivateBadge.className = \"provider-item-badge api-key\";\n\t\tprivateBadge.textContent = t(\"chat:share.privateBadge\");\n\t\tprivateBtn.appendChild(privateName);\n\t\tprivateBtn.appendChild(privateBadge);\n\n\t\tfunction close(value: string | null): void {\n\t\t\tdocument.removeEventListener(\"keydown\", onKeydown);\n\t\t\tbackdrop.remove();\n\t\t\tresolve(value);\n\t\t}\n\n\t\tfunction onKeydown(e: KeyboardEvent): void {\n\t\t\tif (e.key === \"Escape\") close(null);\n\t\t}\n\n\t\tpublicBtn.addEventListener(\"click\", () => close(\"public\"));\n\t\tprivateBtn.addEventListener(\"click\", () => close(\"private\"));\n\t\tcancelTopBtn.addEventListener(\"click\", () => close(null));\n\t\tbackdrop.addEventListener(\"click\", (e: Event) => {\n\t\t\tif (e.target === backdrop) close(null);\n\t\t});\n\t\tdocument.addEventListener(\"keydown\", onKeydown);\n\n\t\tbody.appendChild(hint);\n\t\tbody.appendChild(warning);\n\t\tbody.appendChild(publicBtn);\n\t\tbody.appendChild(privateBtn);\n\t\theader.appendChild(title);\n\t\theader.appendChild(cancelTopBtn);\n\t\tbox.appendChild(header);\n\t\tbox.appendChild(body);\n\t\tbackdrop.appendChild(box);\n\t\tdocument.body.appendChild(backdrop);\n\n\t\tpublicBtn.focus();\n\t});\n}\n\n/**\n * Styled share-link dialog used when auto-copy is unavailable.\n * Returns \"copied\" when copy succeeded, otherwise null on close/dismiss.\n */\nexport function shareLinkDialog(url: string, visibility: string): Promise<string | null> {\n\treturn new Promise((resolve) => {\n\t\tconst backdrop = document.createElement(\"div\");\n\t\tbackdrop.className = \"provider-modal-backdrop\";\n\t\tbackdrop.setAttribute(\"data-share-link-modal\", \"true\");\n\n\t\tconst box = document.createElement(\"div\");\n\t\tbox.className = \"provider-modal\";\n\t\tbox.style.width = \"560px\";\n\n\t\tconst header = document.createElement(\"div\");\n\t\theader.className = \"provider-modal-header\";\n\n\t\tconst title = document.createElement(\"div\");\n\t\ttitle.className = \"provider-item-name\";\n\t\ttitle.textContent = t(\"chat:share.linkReady\");\n\n\t\tconst closeTopBtn = document.createElement(\"button\");\n\t\tcloseTopBtn.className = \"provider-btn provider-btn-secondary\";\n\t\tcloseTopBtn.textContent = t(\"common:actions.close\");\n\t\tcloseTopBtn.setAttribute(\"data-share-link-close\", \"true\");\n\n\t\tconst body = document.createElement(\"div\");\n\t\tbody.className = \"provider-modal-body\";\n\t\tbody.style.gap = \"10px\";\n\n\t\tconst hint = document.createElement(\"p\");\n\t\thint.style.cssText = \"font-size:.8rem;color:var(--muted);margin:0\";\n\t\thint.textContent = visibility === \"private\" ? t(\"chat:share.privateHint\") : t(\"chat:share.publicHint\");\n\n\t\tconst input = document.createElement(\"input\");\n\t\tinput.className = \"provider-key-input\";\n\t\tinput.readOnly = true;\n\t\tinput.value = url;\n\t\tinput.setAttribute(\"data-share-link-input\", \"true\");\n\t\tinput.addEventListener(\"focus\", () => input.select());\n\t\tinput.addEventListener(\"click\", () => input.select());\n\n\t\tconst btnRow = document.createElement(\"div\");\n\t\tbtnRow.style.cssText = \"display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap\";\n\n\t\tconst openBtn = document.createElement(\"button\");\n\t\topenBtn.className = \"provider-btn provider-btn-secondary\";\n\t\topenBtn.textContent = t(\"common:actions.openLink\");\n\t\topenBtn.setAttribute(\"data-share-link-open\", \"true\");\n\n\t\tconst copyBtn = document.createElement(\"button\");\n\t\tcopyBtn.className = \"provider-btn\";\n\t\tcopyBtn.textContent = t(\"common:actions.copyLink\");\n\t\tcopyBtn.setAttribute(\"data-share-link-copy\", \"true\");\n\n\t\tfunction close(value: string | null): void {\n\t\t\tdocument.removeEventListener(\"keydown\", onKeydown);\n\t\t\tbackdrop.remove();\n\t\t\tresolve(value);\n\t\t}\n\n\t\tfunction onKeydown(e: KeyboardEvent): void {\n\t\t\tif (e.key === \"Escape\") close(null);\n\t\t}\n\n\t\tasync function copyLink(): Promise<void> {\n\t\t\ttry {\n\t\t\t\tif (navigator.clipboard?.writeText) {\n\t\t\t\t\tawait navigator.clipboard.writeText(url);\n\t\t\t\t\tshowToast(t(\"chat:share.linkCopied\"), \"success\");\n\t\t\t\t\tclose(\"copied\");\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t} catch (_err) {\n\t\t\t\t// Clipboard permissions can fail. Fall through to manual copy fallback.\n\t\t\t}\n\t\t\tinput.focus();\n\t\t\tinput.select();\n\t\t\tlet copied = false;\n\t\t\ttry {\n\t\t\t\tcopied = document.execCommand(\"copy\");\n\t\t\t} catch (_err) {\n\t\t\t\tcopied = false;\n\t\t\t}\n\t\t\tif (copied) {\n\t\t\t\tshowToast(t(\"chat:share.linkCopied\"), \"success\");\n\t\t\t\tclose(\"copied\");\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tshowToast(t(\"errors:copyFailed\"), \"error\");\n\t\t}\n\n\t\tcopyBtn.addEventListener(\"click\", () => {\n\t\t\tvoid copyLink();\n\t\t});\n\t\topenBtn.addEventListener(\"click\", () => {\n\t\t\twindow.open(url, \"_blank\", \"noopener,noreferrer\");\n\t\t});\n\t\tcloseTopBtn.addEventListener(\"click\", () => close(null));\n\t\tbackdrop.addEventListener(\"click\", (e: Event) => {\n\t\t\tif (e.target === backdrop) close(null);\n\t\t});\n\t\tdocument.addEventListener(\"keydown\", onKeydown);\n\n\t\tbtnRow.appendChild(openBtn);\n\t\tbtnRow.appendChild(copyBtn);\n\t\theader.appendChild(title);\n\t\theader.appendChild(closeTopBtn);\n\t\tbody.appendChild(hint);\n\t\tbody.appendChild(input);\n\t\tbody.appendChild(btnRow);\n\t\tbox.appendChild(header);\n\t\tbox.appendChild(body);\n\t\tbackdrop.appendChild(box);\n\t\tdocument.body.appendChild(backdrop);\n\t\tcopyBtn.focus();\n\t});\n}\n\n// ── Model select dropdown (Preact, reuses .model-combo CSS) ──\n\ninterface ModelSelectModel {\n\tid: string;\n\tdisplayName?: string;\n\tprovider?: string;\n}\n\ninterface ModelSelectProps {\n\tmodels: ModelSelectModel[];\n\tvalue: string;\n\tonChange: (id: string) => void;\n\tplaceholder?: string;\n}\n\nexport function ModelSelect({ models, value, onChange, placeholder }: ModelSelectProps): VNode {\n\tconst [open, setOpen] = useState(false);\n\tconst [query, setQuery] = useState(\"\");\n\tconst [kbIndex, setKbIndex] = useState(-1);\n\tconst ref = useRef<HTMLDivElement>(null);\n\tconst searchRef = useRef<HTMLInputElement>(null);\n\tconst listRef = useRef<HTMLDivElement>(null);\n\n\tconst selected = models.find((m) => m.id === value);\n\tconst label = selected ? selected.displayName || selected.id : placeholder || \"(none)\";\n\n\tconst filtered = models.filter((m) => {\n\t\tif (!query) return true;\n\t\tconst q = query.toLowerCase();\n\t\treturn (\n\t\t\t(m.displayName || \"\").toLowerCase().includes(q) ||\n\t\t\tm.id.