pdateTokenBar();\n\t});\n\tupdateTokenBar();\n\n\tif (!skipAutoScroll && searchContext?.query && S.chatMsgBox) {\n\t\thighlightAndScroll(msgEls, searchContext.messageIndex, searchContext.query);\n\t} else if (!skipAutoScroll) {\n\t\tscrollChatToBottom();\n\t}\n\n\tconst session = sessionStore.getByKey(key);\n\tif (session?.replying.value && S.chatMsgBox) {\n\t\tremoveThinking();\n\t\tconst thinkEl = document.createElement(\"div\");\n\t\tthinkEl.className = \"msg assistant thinking\";\n\t\tthinkEl.id = \"thinkingIndicator\";\n\t\tif (thinkingText) {\n\t\t\tconst textEl = document.createElement(\"span\");\n\t\t\ttextEl.className = \"thinking-text\";\n\t\t\ttextEl.textContent = thinkingText;\n\t\t\tthinkEl.appendChild(textEl);\n\t\t} else {\n\t\t\tthinkEl.appendChild(makeThinkingDots());\n\t\t}\n\t\tS.chatMsgBox.appendChild(thinkEl);\n\t\tif (!skipAutoScroll) scrollChatToBottom();\n\t}\n}\n\nfunction mergeHistoryPages(existingHistory: HistoryMessage[], olderHistory: HistoryMessage[]): HistoryMessage[] {\n\tconst older = Array.isArray(olderHistory) ? olderHistory : [];\n\tconst current = Array.isArray(existingHistory) ? existingHistory : [];\n\tif (older.length === 0) return current;\n\tif (current.length === 0) return older;\n\n\tconst byIndex = new Map<number, HistoryMessage>();\n\tconst ordered: HistoryMessage[] = [];\n\tconst pushMessage = (msg: HistoryMessage): void => {\n\t\tconst idx = historyIndexFromMessage(msg);\n\t\tif (idx === null) {\n\t\t\tordered.push(msg);\n\t\t\treturn;\n\t\t}\n\t\tif (!byIndex.has(idx)) {\n\t\t\tordered.push(msg);\n\t\t}\n\t\tbyIndex.set(idx, msg);\n\t};\n\n\tfor (const olderMsg of older) pushMessage(olderMsg);\n\tfor (const currentMsg of current) pushMessage(currentMsg);\n\n\treturn ordered.map((msg) => {\n\t\tconst idx = historyIndexFromMessage(msg);\n\t\tif (idx === null) return msg;\n\t\treturn byIndex.get(idx) || msg;\n\t});\n}\n\nfunction canLoadOlderHistory(key: string): boolean {\n\tconst paging = getHistoryPaginationState(key);\n\tif (!(paging?.hasMore && Number.isInteger(paging.nextCursor))) return false;\n\tif (paging.loadingOlder) return false;\n\treturn true;\n}\n\nfunction maybeLoadOlderHistoryFromScroll(): void {\n\tif (!S.chatMsgBox) return;\n\tif (S.chatMsgBox.scrollTop > HISTORY_AUTOLOAD_THRESHOLD_PX) return;\n\tconst key = sessionStore.activeSessionKey.value || S.activeSessionKey;\n\tif (!key) return;\n\tif (!canLoadOlderHistory(key)) return;\n\tvoid loadOlderHistoryPage(key);\n}\n\nfunction handleHistoryScroll(): void {\n\tif (historyScrollRaf) return;\n\thistoryScrollRaf = requestAnimationFrame(() => {\n\t\thistoryScrollRaf = 0;\n\t\tmaybeLoadOlderHistoryFromScroll();\n\t});\n}\n\nfunction ensureHistoryScrollBinding(): void {\n\tconst nextEl = S.chatMsgBox;\n\tif (historyScrollEl === nextEl) return;\n\tif (historyScrollEl) {\n\t\thistoryScrollEl.removeEventListener(\"scroll\", handleHistoryScroll);\n\t}\n\thistoryScrollEl = nextEl;\n\tif (!historyScrollEl) return;\n\thistoryScrollEl.addEventListener(\"scroll\", handleHistoryScroll, { passive: true });\n}\n\nasync function loadOlderHistoryPage(key: string): Promise<void> {\n\tif (!canLoadOlderHistory(key)) return;\n\tconst paging = getHistoryPaginationState(key);\n\tif (!paging) return;\n\tif (sessionStore.activeSessionKey.value !== key) return;\n\n\tconst nextState = { ...paging, loadingOlder: true };\n\tsessionHistoryPaging.set(key, nextState);\n\tconst loadedHistory = getSessionHistory(key) || [];\n\tconst totalBefore = Number.isInteger(nextState.totalMessages) ? nextState.totalMessages! : loadedHistory.length;\n\trenderHistory(key, loadedHistory, null, null, totalBefore, true);\n\n\tconst beforeHeight = S.chatMsgBox ? S.chatMsgBox.scrollHeight : 0;\n\tconst beforeTop = S.chatMsgBox ? S.chatMsgBox.scrollTop : 0;\n\n\ttry {\n\t\tconst payload = await fetchSessionHistoryViaHttp(key, {\n\t\t\tcursor: nextState.nextCursor as number,\n\t\t\tlimit: SESSION_HISTORY_PAGE_LIMIT,\n\t\t});\n\t\tif (sessionStore.activeSessionKey.value !== key) return;\n\n\t\tconst older = Array.isArray(payload.history) ? payload.history : [];\n\t\tconst current = getSessionHistory(key) || [];\n\t\tif (older.length > 0 && payload.historyCacheHit !== true) {\n\t\t\treplaceSessionHistory(key, mergeHistoryPages(current, older));\n\t\t}\n\t\tsetHistoryPaginationState(key, payload);\n\n\t\tconst merged = getSessionHistory(key) || [];\n\t\tconst sessionEntry = sessionStore.getByKey(key);\n\t\tconst totalCountHint = Number.isInteger(sessionEntry?.messageCount)\n\t\t\t? (sessionEntry!.messageCount as number)\n\t\t\t: Number(payload.totalMessages) || merged.length;\n\t\trenderHistory(key, merged, null, null, totalCountHint, true);\n\n\t\tif (S.chatMsgBox) {\n\t\t\tconst afterHeight = S.chatMsgBox.scrollHeight;\n\t\t\tS.chatMsgBox.scrollTop = Math.max(0, beforeTop + (afterHeight - beforeHeight));\n\t\t}\n\t} catch {\n\t\tif (sessionStore.activeSessionKey.value !== key) return;\n\t\tconst fallback = getSessionHistory(key) || [];\n\t\tconst fallbackTotal = Number.isInteger(nextState.totalMessages) ? nextState.totalMessages! : fallback.length;\n\t\tsessionHistoryPaging.set(key, { ...nextState, loadingOlder: false });\n\t\trenderHistory(key, fallback, null, null, fallbackTotal, true);\n\t\tchatAddMsg(\"error\", \"Failed to load older messages\");\n\t} finally {\n\t\tconst latest = getHistoryPaginationState(key);\n\t\tif (latest) sessionHistoryPaging.set(key, { ...latest, loadingOlder: false });\n\t\tif (sessionStore.activeSessionKey.value === key) {\n\t\t\tmaybeLoadOlderHistoryFromScroll();\n\t\t}\n\t}\n}\n\n/** No-op -- the Preact SessionHeader component auto-updates from signals. */\nexport function updateChatSessionHeader(): void {\n\t// Retained for backward compat call sites; Preact handles rendering.\n}\n\nfunction renderWelcomeAgentPicker(\n\tcard: HTMLElement,\n\tactiveAgentId: string,\n\tonActiveAgentResolved: (agent: AgentInfo | null) => void,\n): void {\n\tconst container = card.querySelector(\"[data-welcome-agents]\") as HTMLElement | null;\n\tif (!container) return;\n\n\tsendRpc(\"agents.list\", {}).then((res) => {\n\t\tif (!card.isConnected) return;\n\t\tif (!res?.ok) {\n\t\t\tcontainer.classList.add(\"hidden\");\n\t\t\treturn;\n\t\t}\n\t\tconst parsed = parseAgentsListPayload(res.payload as Parameters<typeof parseAgentsListPayload>[0]);\n\t\tconst agents = (parsed.agents || []) as AgentInfo[];\n\t\tconst defaultId = (parsed.defaultId || \"main\") as string;\n\t\tconst effectiveActive = activeAgentId || defaultId;\n\n\t\tcontainer.textContent = \"\";\n\t\tcontainer.classList.remove(\"hidden\");\n\t\tcontainer.classList.add(\"flex\");\n\n\t\tlet activeAgent: AgentInfo | null = null;\n\t\tfor (const agent of agents) {\n\t\t\tif (!agent?.id) continue;\n\t\t\tif (agent.id === effectiveActive) activeAgent = agent;\n\t\t\tconst chip = document.createElement(\"button\");\n\t\t\tchip.type = \"button\";\n\t\t\tchip.className = agent.id === effectiveActive ? \"provider-btn\" : \"provider-btn provider-btn-secondary\";\n\t\t\tchip.style.fontSize = \"0.7rem\";\n\t\t\tchip.style.padding = \"3px 8px\";\n\t\t\tconst labelPrefix = agent.emoji ? `${agent.emoji} ` : \"\";\n\t\t\tchip.textContent = `${labelPrefix}${agent.name || agent.id}`;\n\t\t\tchip.addEventListener(\"click\", () => {\n\t\t\t\tconst key = sessionStore.activeSessionKey.value || S.activeSessionKey || \"main\";\n\t\t\t\tsendRpc(\"agents.set_session\", { session_key: key, agent_id: agent.id }).then((setRes) => {\n\t\t\t\t\tif (!setRes?.ok) return;\n\t\t\t\t\tconst live = sessionStore.getByKey(key);\n\t\t\t\t\tif (live) {\n\t\t\t\t\t\tlive.agent_id = agent.id || \"\";\n\t\t\t\t\t\tlive.dataVersion.value++;\n\t\t\t\t\t}\n\t\t\t\t\tfetchSessions();\n\t\t\t\t\tconst welcome = S.chatMsgBox?.querySelector(\"#welcomeCard\");\n\t\t\t\t\tif (welcome) {\n\t\t\t\t\t\twelcome.remove();\n\t\t\t\t\t\tshowWelcomeCard();\n\t\t\t\t\t}\n\t\t\t\t});\n\t\t\t});\n\t\t\tcontainer.appendChild(chip);\n\t\t}\n\n\t\tconst hatchBtn = document.createElement(\"button\");\n\t\thatchBtn.type = \"button\";\n\t\thatchBtn.className = \"provider-btn provider-btn-secondary\";\n\t\thatchBtn.style.fontSize = \"0.7rem\";\n\t\thatchBtn.style.padding = \"3px 8px\";\n\t\thatchBtn.textContent = \"\\u{1F95A} Hatch a new agent\";\n\t\thatchBtn.addEventListener(\"click\", () => {\n\t\t\tnavigate(settingsPath(\"agents/new\"));\n\t\t});\n\t\tcontainer.appendChild(hatchBtn);\n\n\t\tonActiveAgentResolved(activeAgent);\n\t});\n}\n\nfunction showWelcomeCard(): void {\n\tif (!S.chatMsgBox) return;\n\tS.chatMsgBox.classList.add(\"chat-messages-empty\");\n\n\tif (modelStore.models.value.length === 0) {\n\t\tconst noProvTpl = document.getElementById(\"tpl-no-providers-card\") as HTMLTemplateElement | null;\n\t\tif (!noProvTpl) return;\n\t\tconst noProvCard = (noProvTpl.content.cloneNode(true) as DocumentFragment).firstElementChild as HTMLElement;\n\t\tS.chatMsgBox.appendChild(noProvCard);\n\t\treturn;\n\t}\n\n\tconst tpl = document.getElementById(\"tpl-welcome-card\") as HTMLTemplateElement | null;\n\tif (!tpl) return;\n\tconst card = (tpl.content.cloneNode(true) as DocumentFragment).firstElementChild as HTMLElement;\n\tconst identity = gon.get(\"identity\");\n\tconst userName = identity?.user_name;\n\tconst botName = identity?.name || \"moltis\";\n\tconst botEmoji = identity?.emoji || \"\";\n\n\tconst greetingEl = card.querySelector(\"[data-welcome-greeting]\") as HTMLElement | null;\n\tif (greetingEl) greetingEl.textContent = userName ? `Hello, ${userName}!` : \"Hello!\";\n\tconst emojiEl = card.querySelector(\"[data-welcome-emoji]\") as HTMLElement | null;\n\tif (emojiEl) emojiEl.textContent = botEmoji;\n\tconst nameEl = card.querySelector(\"[data-welcome-bot-name]\") as HTMLElement | null;\n\tif (nameEl) nameEl.textContent = botName;\n\tconst activeAgentId = (sessionStore.activeSession.value as unknown as SessionMeta)?.agent_id || \"main\";\n\trenderWelcomeAgentPicker(card, activeAgentId, (activeAgent) => {\n\t\tif (!activeAgent) return;\n\t\tif (emojiEl) emojiEl.textContent = activeAgent.emoji || \"\";\n\t\tif (nameEl) nameEl.textContent = activeAgent.name || botName;\n\t});\n\n\tS.chatMsgBox.appendChild(card);\n}\n\nexport function refreshWelcomeCardIfNeeded(): void {\n\tif (!S.chatMsgBox) return;\n\tconst welcomeCard = S.chatMsgBox.querySelector(\"#welcomeCard\");\n\tconst noProvCard = S.chatMsgBox.querySelector(\"#noProvidersCard\");\n\tconst hasModels = modelStore.models.value.length > 0;\n\n\t// Wrong variant showing -- swap it\n\tif (hasModels && noProvCard) {\n\t\tnoProvCard.remove();\n\t\tshowWelcomeCard();\n\t} else if (!hasModels && welcomeCard) {\n\t\twelcomeCard.remove();\n\t\tshowWelcomeCard();\n\t}\n}\n\nfunction ensureSessionInClientStore(key: string, entry: SessionMeta, projectId?: string): unknown {\n\tconst existing = sessionStore.getByKey(key);\n\tif (existing) return existing;\n\n\tconst created: SessionMeta = { ...entry, key };\n\tif (projectId && !created.projectId) created.projectId = projectId;\n\tconst createdSession = sessionStore.upsert(created);\n\n\t// Keep state.js mirror in sync for legacy call sites.\n\tconst inLegacy = (S.sessions as SessionMeta[]).some((s) => s.key === key);\n\tif (!inLegacy) {\n\t\tS.setSessions(insertSessionInOrder(S.sessions as Session[], new Session(created)));\n\t}\n\treturn createdSession;\n}\n\nfunction showSessionLoadIndicator(): void {\n\tif (!S.chatMsgBox) return;\n\thideSessionLoadIndicator();\n\tconst loading = document.createElement(\"div\");\n\tloading.id = \"sessionLoadIndicator\";\n\tloading.className = \"msg assistant thinking session-loading\";\n\tloading.appendChild(makeThinkingDots());\n\tconst label = document.createElement(\"span\");\n\tlabel.className = \"session-loading-label\";\n\tlabel.textContent = \"Loading session\\u2026\";\n\tloading.appendChild(label);\n\tS.chatMsgBox.appendChild(loading);\n}\n\nfunction hideSessionLoadIndicator(): void {\n\tconst loading = document.getElementById(\"sessionLoadIndicator\");\n\tif (loading) loading.remove();\n}\n\nfunction startSwitchRequest(key: string): number {\n\tswitchRequestSeq += 1;\n\tlatestSwitchRequestBySession.set(key, switchRequestSeq);\n\treturn switchRequestSeq;\n}\n\nfunction isLatestSwitchRequest(key: string, requestId: number): boolean {\n\treturn latestSwitchRequestBySession.get(key) === requestId;\n}\n\nfunction startSessionRefresh(key: string, blockRealtimeEvents: boolean): void {\n\tsessionStore.refreshInProgressKey.value = key;\n\tsessionStore.switchInProgress.value = !!blockRealtimeEvents;\n\tS.setSessionSwitchInProgress(!!blockRealtimeEvents);\n}\n\nfunction finishSessionRefresh(key: string): void {\n\tif (sessionStore.refreshInProgressKey.value !== key) return;\n\tsessionStore.refreshInProgressKey.value = \"\";\n\tsessionStore.switchInProgress.value = false;\n\tS.setSessionSwitchInProgress(false);\n}\n\nfunction resetSwitchViewState(): void {\n\thideSessionLoadIndicator();\n\tif (S.chatMsgBox) S.chatMsgBox.textContent = \"\";\n\tconst tray = document.getElementById(\"queuedMessages\");\n\tif (tray) {\n\t\twhile (tray.firstChild) tray.removeChild(tray.firstChild);\n\t\ttray.classList.add(\"hidden\");\n\t}\n\tS.setStreamEl(null);\n\tS.setStreamText(\"\");\n\tS.setLastToolOutput(\"\");\n\tS.setVoicePending(false);\n\tS.setLastHistoryIndex(-1);\n\tS.setSessionTokens({ input: 0, output: 0 });\n\tS.setSessionCurrentInputTokens(0);\n\tS.setSessionContextWindow(0);\n\tupdateTokenBar();\n}\n\nfunction syncHistoryState(\n\tkey: string,\n\thistory: HistoryMessage[],\n\thistoryTailIndex: number,\n\ttotalCountHint: number | null,\n): void {\n\tconst loadedCount = Array.isArray(history) ? history.length : 0;\n\tconst sessionEntry = sessionStore.getByKey(key);\n\tconst legacy = (S.sessions as SessionMeta[]).find((s) => s.key === key);\n\tconst existingCount = Number.isInteger(sessionEntry?.messageCount) ? (sessionEntry!.messageCount as number) : 0;\n\tconst legacyCount = Number.isInteger(legacy?.messageCount) ? (legacy!.messageCount as number) : 0;\n\tconst hintedCount = Number.isInteger(totalCountHint) ? totalCountHint! : 0;\n\tconst count = Math.max(loadedCount, existingCount, hintedCount, legacyCount);\n\tif (sessionEntry) {\n\t\tsessionEntry.syncCounts(count, count);\n\t\tsessionEntry.localUnread.value = false;\n\t\tsessionEntry.lastHistoryIndex.value = historyTailIndex;\n\t}\n\tif (legacy) {\n\t\tlegacy.messageCount = count;\n\t\tlegacy.lastSeenMessageCount = count;\n\t\tlegacy._localUnread = false;\n\t}\n\tS.setLastHistoryIndex(historyTailIndex);\n}\n\nfunction renderHistory(\n\tkey: string,\n\thistory: HistoryMessage[],\n\tsearchContext: SearchContext | null,\n\tthinkingText: string | null,\n\ttotalCountHint: number | null,\n\tskipAutoScroll: boolean,\n): void {\n\tensureHistoryScrollBinding();\n\thideSessionLoadIndicator();\n\tif (S.chatMsgBox) {\n\t\tS.chatMsgBox.classList.remove(\"chat-messages-empty\");\n\t\tS.chatMsgBox.textContent = \"\";\n\t}\n\tconst msgEls: (HTMLElement | null)[] = [];\n\tS.setSessionTokens({ input: 0, output: 0 });\n\tS.setSessionCurrentInputTokens(0);\n\tS.setChatBatchLoading(true);\n\thistory.forEach((msg) => {\n\t\tif (msg.role === \"user\") {\n\t\t\tmsgEls.push(renderHistoryUserMessage(msg as UserMsg));\n\t\t} else if (msg.role === \"assistant\") {\n\t\t\tmsgEls.push(renderHistoryAssistantMessage(msg as AssistantMsg));\n\t\t} else if (msg.role === \"notice\") {\n\t\t\tmsgEls.push(chatAddMsg(\"system\", renderMarkdown(msg.content || \"\"), true));\n\t\t} else if (msg.role === \"tool_result\") {\n\t\t\tmsgEls.push(renderHistoryToolResult(msg as ToolResultMsg));\n\t\t} else {\n\t\t\tmsgEls.push(null);\n\t\t}\n\t});\n\tS.setChatBatchLoading(false);\n\t// Syntax-highlight all code blocks in the rendered history.\n\tif (S.chatMsgBox) highlightCodeBlocks(S.chatMsgBox);\n\tconst historyTailIndex = computeHistoryTailIndex(history);\n\tsyncHistoryState(key, history, historyTailIndex, totalCountHint);\n\n\t// Resume chatSeq from the highest user message seq in history\n\t// so the counter continues from where it left off after reload.\n\tlet maxSeq = 0;\n\tfor (const hm of history) {\n\t\tif (hm.role === \"user\" && ((hm as Record<string, unknown>).seq as number) > maxSeq) {\n\t\t\tmaxSeq = (hm as Record<string, unknown>).seq as number;\n\t\t}\n\t}\n\tS.setChatSeq(maxSeq);\n\tif (history.length === 0) {\n\t\tshowWelcomeCard();\n\t} else {\n\t\tconst lastMsg = history[history.length - 1];\n\t\tconst ts = (lastMsg as Record<string, unknown>).created_at as number | undefined;\n\t\tif (ts) appendLastMessageTimestamp(ts);\n\t}\n\tpostHistoryLoadActions(key, searchContext, msgEls, thinkingText, skipAutoScroll === true);\n}\n\nfunction shouldApplyServerHistory(key: string, serverHistory: HistoryMessage[], requestRevision: number): boolean {\n\tconst current = getSessionHistory(key);\n\tif (!current) return true;\n\tconst serverTail = computeHistoryTailIndex(serverHistory);\n\tconst currentTail = computeHistoryTailIndex(current);\n\tif (serverTail > currentTail) return true;\n\tif (serverTail < currentTail) return false;\n\tconst currentRevision = getHistoryRevision(key);\n\tif (currentRevision === requestRevision) return true;\n\treturn !historyHasUnindexedMessages(current);\n}\n\nfunction applyReplyingStateFromSwitchPayload(key: string, payload: SwitchPayload): void {\n\tconst replying = payload.replying === true;\n\tsetSessionReplying(key, replying);\n\tconst voiceSession = sessionStore.getByKey(key);\n\tif (replying && payload.voicePending) {\n\t\tS.setVoicePending(true);\n\t\tif (voiceSession) voiceSession.voicePending.value = true;\n\t} else {\n\t\tS.setVoicePending(false);\n\t\tif (voiceSession) voiceSession.voicePending.value = false;\n\t}\n\tif (!replying && key === sessionStore.activeSessionKey.value) {\n\t\tremoveThinking();\n\t}\n}\n\nasync function fetchSessionHistoryViaHttp(\n\tkey: string,\n\toptions?: { cachedMessageCount?: number; cursor?: number; limit?: number },\n): Promise<HistoryPayload> {\n\tconst opts = options || {};\n\tconst query = new URLSearchParams();\n\tif (Number.isInteger(opts.cachedMessageCount) && (opts.cachedMessageCount as number) >= 0) {\n\t\tquery.set(\"cached_message_count\", String(opts.cachedMessageCount));\n\t}\n\tif (Number.isInteger(opts.cursor) && (opts.cursor as number) >= 0) {\n\t\tquery.set(\"cursor\", String(opts.cursor));\n\t}\n\tif (Number.isInteger(opts.limit) && (opts.limit as number) > 0) {\n\t\tquery.set(\"limit\", String(opts.limit));\n\t}\n\tlet url = `/api/sessions/${encodeURIComponent(key)}/history`;\n\tconst qs = query.toString();\n\tif (qs) url += `?${qs}`;\n\n\tconst response = await fetch(url, {\n\t\theaders: { Accept: \"application/json\" },\n\t});\n\tlet payload: HistoryPayload | null = null;\n\ttry {\n\t\tpayload = await response.json();\n\t} catch {\n\t\tpayload = null;\n\t}\n\tif (!response.ok) {\n\t\tconst errMsg =\n\t\t\t(payload as Record<string, unknown> | null)?.error || `Failed to load session history (${response.status})`;\n\t\tthrow new Error(errMsg as string);\n\t}\n\treturn payload || {};\n}\n\nexport function switchSession(key: string, searchContext?: SearchContext | null, projectId?: string): void {\n\tsessionStore.setActive(key);\n\t// Dual-write to state.js for backward compat\n\tS.setActiveSessionKey(key);\n\tlocalStorage.setItem(\"moltis-session\", key);\n\thistory.replaceState(null, \"\", sessionPath(key));\n\tresetSwitchViewState();\n\tconst cachedEntry = sessionStore.getByKey(key);\n\tif (cachedEntry) {\n\t\trestoreSessionState(cachedEntry as unknown as SessionMeta, projectId);\n\t}\n\t// Preact SessionList auto-rerenders active/unread from signals.\n\n\tconst switchReqId = startSwitchRequest(key);\n\tconst switchParams: Record<string, unknown> = { key };\n\tif (projectId) switchParams.project_id = projectId;\n\t// Keep WebSocket for live state only; history comes from HTTP (gzip-friendly).\n\tswitchParams.include_history = false;\n\tconst cachedHistory = getSessionHistory(key);\n\tconst hasCache = Array.isArray(cachedHistory);\n\tconst cacheRevisionAtRequest = getHistoryRevision(key);\n\tconst cacheComplete = hasCache && isHistoryCacheComplete(key);\n\tconst cachedHistoryCount = cacheComplete\n\t\t? Number.isInteger(cachedEntry?.messageCount)\n\t\t\t? (cachedEntry!.messageCount as number)\n\t\t\t: cachedHistory?.length\n\t\t: null;\n\tstartSessionRefresh(key, !hasCache);\n\tif (hasCache) {\n\t\trenderHistory(key, cachedHistory!, searchContext || null, null, cachedHistoryCount, false);\n\t} else {\n\t\tshowSessionLoadIndicator();\n\t}\n\n\tsendRpc(\"sessions.switch\", switchParams)\n\t\t.then(async (res) => {\n\t\t\tif (!isLatestSwitchRequest(key, switchReqId)) return;\n\t\t\tlet stillActive = sessionStore.activeSessionKey.value === key;\n\t\t\tif (!(res?.ok && res.payload)) {\n\t\t\t\tif (stillActive && !hasCache) {\n\t\t\t\t\thideSessionLoadIndicator();\n\t\t\t\t\tchatAddMsg(\"error\", res?.error?.message || \"Failed to load session\");\n\t\t\t\t}\n\t\t\t\tfinishSessionRefresh(key);\n\t\t\t\tif (stillActive && S.chatInput) S.chatInput.focus();\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tconst switchPayload = res.payload as SwitchPayload;\n\t\t\tconst entry = switchPayload.entry || ({} as SessionMeta);\n\t\t\tensureSessionInClientStore(key, entry, projectId);\n\t\t\tconst pagingBefore = getHistoryPaginationState(key);\n\t\t\tconst pagingBeforeHasMore = pagingBefore?.hasMore === true;\n\t\t\tconst pagingBeforeCursor = Number.isInteger(pagingBefore?.nextCursor) ? pagingBefore?.nextCursor : null;\n\t\t\tlet historyPayload: HistoryPayload = {\n\t\t\t\thistoryCacheHit: switchPayload.historyCacheHit === true,\n\t\t\t\thistory: Array.isArray(switchPayload.history) ? switchPayload.history : [],\n\t\t\t\thistoryTruncated: switchPayload.historyTruncated === true,\n\t\t\t\thistoryDroppedCount: Number(switchPayload.historyDroppedCount) || 0,\n\t\t\t};\n\t\t\tif (switchPayload.historyOmitted === true) {\n\t\t\t\ttry {\n\t\t\t\t\thistoryPayload = await fetchSessionHistoryViaHttp(key, {\n\t\t\t\t\t\tcachedMessageCount: cachedHistoryCount ?? undefined,\n\t\t\t\t\t\tlimit: SESSION_HISTORY_PAGE_LIMIT,\n\t\t\t\t\t});\n\t\t\t\t} catch (error) {\n\t\t\t\t\tif (!isLatestSwitchRequest(key, switchReqId)) return;\n\t\t\t\t\tstillActive = sessionStore.activeSessionKey.value === key;\n\t\t\t\t\tif (stillActive && !hasCache) {\n\t\t\t\t\t\thideSessionLoadIndicator();\n\t\t\t\t\t\tchatAddMsg(\"error\", (error as Error)?.message || \"Failed to load session history\");\n\t\t\t\t\t}\n\t\t\t\t\tfinishSessionRefresh(key);\n\t\t\t\t\tif (stillActive && S.chatInput) S.chatInput.focus();\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tif (!isLatestSwitchRequest(key, switchReqId)) return;\n\t\t\t\tstillActive = sessionStore.activeSessionKey.value === key;\n\t\t\t}\n\t\t\tsetHistoryPaginationState(key, historyPayload);\n\t\t\tconst pagingAfter = getHistoryPaginationState(key);\n\t\t\tconst pagingAfterHasMore = pagingAfter?.hasMore === true;\n\t\t\tconst pagingAfterCursor = Number.isInteger(pagingAfter?.nextCursor) ? pagingAfter?.nextCursor : null;\n\t\t\tconst paginationChanged = pagingBeforeHasMore !== pagingAfterHasMore || pagingBeforeCursor !== pagingAfterCursor;\n\n\t\t\tconst cacheHit = historyPayload.historyCacheHit === true;\n\t\t\tconst serverHistory = Array.isArray(historyPayload.history) ? historyPayload.history : [];\n\t\t\tlet appliedServerHistory = false;\n\t\t\tif (!cacheHit && shouldApplyServerHistory(key, serverHistory, cacheRevisionAtRequest)) {\n\t\t\t\treplaceSessionHistory(key, serverHistory);\n\t\t\t\tappliedServerHistory = true;\n\t\t\t}\n\t\t\tconst resolvedHistory = getSessionHistory(key) || serverHistory;\n\t\t\tif (stillActive) {\n\t\t\t\trestoreSessionState(entry, projectId);\n\t\t\t\tapplyReplyingStateFromSwitchPayload(key, switchPayload);\n\t\t\t\tconst thinkingText = switchPayload.replying ? switchPayload.thinkingText || null : null;\n\t\t\t\tconst totalCountHint = Number.isInteger(entry.messageCount)\n\t\t\t\t\t? entry.messageCount!\n\t\t\t\t\t: Number(historyPayload.totalMessages) || resolvedHistory.length;\n\t\t\t\tconst shouldRerender = !hasCache || Boolean(searchContext?.query) || appliedServerHistory || paginationChanged;\n\t\t\t\tif (shouldRerender) {\n\t\t\t\t\trenderHistory(key, resolvedHistory, searchContext || null, thinkingText, totalCountHint, false);\n\t\t\t\t} else {\n\t\t\t\t\tpostHistoryLoadActions(key, searchContext || null, [], thinkingText, false);\n\t\t\t\t}\n\t\t\t\tif (appliedServerHistory && historyPayload.historyTruncated === true) {\n\t\t\t\t\tconst dropped = Number(historyPayload.historyDroppedCount) || 0;\n\t\t\t\t\tchatAddMsg(\n\t\t\t\t\t\t\"system\",\n\t\t\t\t\t\t`Loaded the most recent messages for performance (${dropped} older message${dropped === 1 ? \"\" : \"s\"} omitted).`,\n\t\t\t\t\t);\n\t\t\t\t}\n\t\t\t\tif (appliedServerHistory && historyPayload.hasMore === true) {\n\t\t\t\t\tconst total = Number(historyPayload.totalMessages) || resolvedHistory.length;\n\t\t\t\t\tchatAddMsg(\n\t\t\t\t\t\t\"system\",\n\t\t\t\t\t\t`Loaded recent history (${resolvedHistory.length} of ${total} messages) for faster loading.`,\n\t\t\t\t\t);\n\t\t\t\t}\n\t\t\t\tif (S.chatInput) S.chatInput.focus();\n\t\t\t}\n\t\t\tfinishSessionRefresh(key);\n\t\t})\n\t\t.catch(() => {\n\t\t\tif (!isLatestSwitchRequest(key, switchReqId)) return;\n\t\t\tconst stillActive = sessionStore.activeSessionKey.value === key;\n\t\t\tif (stillActive && !hasCache) {\n\t\t\t\thideSessionLoadIndicator();\n\t\t\t\tchatAddMsg(\"error\", \"Failed to load session\");\n\t\t\t}\n\t\t\tfinishSessionRefresh(key);\n\t\t\tif (stillActive && S.chatInput) S.chatInput.focus();\n\t\t});\n}\n","// ── SessionList Preact component ─────���───────────────────────\n//\n// Replaces the imperative renderSessionList() with a reactive Preact\n// component that auto-rerenders from sessionStore signals.\n\nimport type { VNode } from \"preact\";\nimport { useEffect, useRef } from \"preact/hooks\";\nimport {\n\tmakeBranchIcon,\n\tmakeChatIcon,\n\tmakeCronIcon,\n\tmakeDiscordIcon,\n\tmakeMatrixIcon,\n\tmakeProjectIcon,\n\tmakeSlackIcon,\n\tmakeTeamsIcon,\n\tmakeTelegramIcon,\n} from \"../icons\";\nimport { currentPrefix, navigate, sessionPath } from \"../router\";\nimport { switchSession } from \"../sessions\";\nimport * as projectStore from \"../stores/project-store\";\nimport { type Session, sessionStore } from \"../stores/session-store\";\nimport { ChannelType } from \"../types\";\n\n// ── Braille spinner ───────────��─────────────────────────────\nconst spinnerFrames: string[] = [\n\t\"\\u280B\",\n\t\"\\u2819\",\n\t\"\\u2839\",\n\t\"\\u2838\",\n\t\"\\u283C\",\n\t\"\\u2834\",\n\t\"\\u2826\",\n\t\"\\u2827\",\n\t\"\\u2807\",\n\t\"\\u280F\",\n];\n\n// ── Helpers ─────────���────────────────────────────────────────\n\nfunction channelSessionType(s: Session): ChannelType | null {\n\tconst key = s.key || \"\";\n\tif (key.startsWith(`${ChannelType.Telegram}:`)) return ChannelType.Telegram;\n\tif (key.startsWith(`${ChannelType.MsTeams}:`)) return ChannelType.MsTeams;\n\tif (key.startsWith(`${ChannelType.Discord}:`)) return ChannelType.Discord;\n\tif (key.startsWith(`${ChannelType.Slack}:`)) return ChannelType.Slack;\n\tif (key.startsWith(`${ChannelType.Matrix}:`)) return ChannelType.Matrix;\n\tconst binding = s.channelBinding || null;\n\tif (!binding) return null;\n\ttry {\n\t\tconst parsed = typeof binding === \"string\" ? JSON.parse(binding) : binding;\n\t\treturn (parsed.channel_type as ChannelType) || null;\n\t} catch (_e) {\n\t\treturn null;\n\t}\n}\n\nfunction formatHHMM(epochMs: number): string {\n\treturn new Date(epochMs).toLocaleTimeString(undefined, { hour: \"2-digit\", minute: \"2-digit\" });\n}\n\n// ── Icon component (renders SVG icon into a ref) ────────────\n\ninterface SessionIconProps {\n\tsession: Session;\n\tisBranch: boolean;\n}\n\nfunction SessionIcon({ session, isBranch }: SessionIconProps): VNode {\n\tconst iconRef = useRef<HTMLSpanElement>(null);\n\tuseEffect(() => {\n\t\tif (!iconRef.current) return;\n\t\ticonRef.current.textContent = \"\";\n\t\tconst key = session.key || \"\";\n\t\tlet icon: SVGElement | HTMLElement;\n\t\tconst channelType = channelSessionType(session);\n\t\tif (isBranch) icon = makeBranchIcon();\n\t\telse if (key.startsWith(\"cron:\")) icon = makeCronIcon();\n\t\telse if (channelType === ChannelType.Telegram) icon = makeTelegramIcon();\n\t\telse if (channelType === ChannelType.MsTeams) icon = makeTeamsIcon();\n\t\telse if (channelType === ChannelType.Discord) icon = makeDiscordIcon();\n\t\telse if (channelType === ChannelType.Slack) icon = makeSlackIcon();\n\t\telse if (channelType === ChannelType.Matrix) icon = makeMatrixIcon();\n\t\telse icon = makeChatIcon();\n\t\ticonRef.current.appendChild(icon);\n\t}, [session.key, isBranch]);\n\n\tconst channelType = channelSessionType(session);\n\tconst channelBound = Boolean(channelType);\n\tconst iconStyle: Record<string, string> = {};\n\tif (channelBound) {\n\t\ticonStyle.color = session.activeChannel ? \"var(--accent)\" : \"var(--muted)\";\n\t\ticonStyle.opacity = session.activeChannel ? \"1\" : \"0.5\";\n\t} else {\n\t\ticonStyle.color = \"var(--muted)\";\n\t}\n\tconst channelLabel =\n\t\tchannelType === ChannelType.MsTeams\n\t\t\t? \"Microsoft Teams\"\n\t\t\t: channelType === ChannelType.Discord\n\t\t\t\t? \"Discord\"\n\t\t\t\t: channelType === ChannelType.Slack\n\t\t\t\t\t? \"Slack\"\n\t\t\t\t\t: channelType === ChannelType.Matrix\n\t\t\t\t\t\t? \"Matrix\"\n\t\t\t\t\t\t: \"Telegram\";\n\tconst title = channelBound\n\t\t? session.activeChannel\n\t\t\t? `Active ${channelLabel} session`\n\t\t\t: `${channelLabel} session (inactive)`\n\t\t: \"\";\n\n\t// Read the reactive signal — auto-subscribes for badge updates.\n\tconst count = session.badgeCount.value;\n\n\treturn (\n\t\t<span className=\"session-icon\" style={iconStyle} title={title}>\n\t\t\t<span ref={iconRef} />\n\t\t\t<span className=\"session-spinner\" />\n\t\t\t{count > 0 && (\n\t\t\t\t<span className=\"session-badge\" data-session-key={session.key}>\n\t\t\t\t\t{count > 99 ? \"99+\" : String(count)}\n\t\t\t\t</span>\n\t\t\t)}\n\t\t</span>\n\t);\n}\n\n// ── Session meta (fork, worktree, project) ──────────────────\n\ninterface SessionMetaProps {\n\tsession: Session;\n}\n\nfunction SessionMeta({ session }: SessionMetaProps): VNode {\n\tconst ref = useRef<HTMLDivElement>(null);\n\n\tuseEffect(() => {\n\t\tif (!ref.current) return;\n\t\tref.current.textContent = \"\";\n\n\t\tconst parts: string[] = [];\n\t\tif (session.forkPoint != null) parts.push(`fork@${session.forkPoint}`);\n\t\tconst branch = session.worktree_branch || \"\";\n\t\tif (branch) parts.push(`\\u2387 ${branch}`);\n\n\t\tconst projId = session.projectId || \"\";\n\t\tconst proj = projId ? projectStore.getById(projId) : null;\n\n\t\tif (parts.length === 0 && !proj) return;\n\n\t\tref.current.textContent = parts.join(\" \\u00b7 \");\n\t\tif (proj) {\n\t\t\tif (parts.length > 0) ref.current.appendChild(document.createTextNode(\" \\u00b7 \"));\n\t\t\tconst icon = makeProjectIcon();\n\t\t\ticon.style.display = \"inline\";\n\t\t\ticon.style.verticalAlign = \"-1px\";\n\t\t\ticon.style.marginRight = \"2px\";\n\t\t\ticon.style.opacity = \"0.7\";\n\t\t\tref.current.appendChild(icon);\n\t\t\tref.current.appendChild(document.createTextNode((proj.label as string) || proj.id));\n\t\t}\n\t}, [session.projectId, session.forkPoint, session.worktree_branch]);\n\n\treturn <div className=\"session-meta\" data-session-key={session.key} ref={ref} />;\n}\n\n// ── SessionItem component ───────────���───────────────────────\n\ninterface KeyMap {\n\t[key: string]: Session;\n}\n\ninterface SessionItemProps {\n\tsession: Session;\n\tactiveKey: string;\n\tdepth: number;\n\tkeyMap: KeyMap;\n\trefreshing: boolean;\n}\n\nfunction SessionItem({ session, activeKey, depth, keyMap, refreshing }: SessionItemProps): VNode {\n\tconst isBranch = depth > 0;\n\tconst active = session.key === activeKey;\n\t// Read per-session signals — auto-subscribes for re-render.\n\t// dataVersion triggers re-render when plain properties (preview,\n\t// updatedAt, label) change. Badge updates come from badgeCount\n\t// signal read inside SessionIcon.\n\tconst replying = session.replying.value;\n\tvoid session.dataVersion.value;\n\t// Unread tint: true when not viewing this session and there are messages\n\t// beyond what we last saw (badgeCount is reactive, triggers re-render).\n\tconst badge = session.badgeCount.value;\n\tconst unread = session.localUnread.value || (!active && badge > (session.lastSeenMessageCount || 0));\n\n\tlet className = \"session-item\";\n\tif (active) className += \" active\";\n\tif (unread) className += \" unread\";\n\tif (replying) className += \" replying\";\n\tif (refreshing) className += \" loading\";\n\n\tconst style = isBranch ? { paddingLeft: `${12 + depth * 16}px` } : {};\n\n\tconst rawPreview = session.preview || \"\";\n\tconst parentPreview =\n\t\tsession.parentSessionKey && keyMap[session.parentSessionKey] ? keyMap[session.parentSessionKey].preview || \"\" : \"\";\n\tconst preview = rawPreview && rawPreview === parentPreview ? \"\" : rawPreview;\n\tconst ts = session.updatedAt || 0;\n\tconst agentId = session.agent_id || \"main\";\n\tconst showAgentBadge = !!agentId && agentId !== \"main\";\n\n\tconst href = sessionPath(session.key);\n\n\tfunction onClick(event: MouseEvent): void {\n\t\tif (event.defaultPrevented) return;\n\t\tif (event.button !== 0) return;\n\t\tif (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;\n\t\tevent.preventDefault();\n\t\tif (currentPrefix !== \"/chats\") {\n\t\t\tnavigate(href);\n\t\t} else {\n\t\t\tswitchSession(session.key);\n\t\t}\n\t}\n\n\treturn (\n\t\t<a href={href} className={className} data-session-key={session.key} style={style} onClick={onClick}>\n\t\t\t<div className=\"session-info\">\n\t\t\t\t<div className=\"session-label\">\n\t\t\t\t\t<SessionIcon session={session} isBranch={isBranch} />\n\t\t\t\t\t<span data-label-text>{session.label || session.key}</span>\n\t\t\t\t\t{showAgentBadge && (\n\t\t\t\t\t\t<span\n\t\t\t\t\t\t\tclassName=\"text-[10px] text-[var(--muted)] border border-[var(--border)] rounded px-1 py-0 ml-1\"\n\t\t\t\t\t\t\ttitle={`Agent: ${agentId}`}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t@{agentId}\n\t\t\t\t\t\t</span>\n\t\t\t\t\t)}\n\t\t\t\t\t{ts > 0 && (\n\t\t\t\t\t\t<span className=\"session-time\" title={new Date(ts).toLocaleString()}>\n\t\t\t\t\t\t\t{formatHHMM(ts)}\n\t\t\t\t\t\t</span>\n\t\t\t\t\t)}\n\t\t\t\t</div>\n\t\t\t\t{preview && <div className=\"session-preview\">{preview}</div>}\n\t\t\t\t<SessionMeta session={session} />\n\t\t\t</div>\n\t\t</a>\n\t);\n}\n\n// ── SessionList component ──────────────────���────────────────\nexport function SessionList(): VNode {\n\tconst allSessions = sessionStore.sessions.value;\n\tconst activeKey = sessionStore.activeSessionKey.value;\n\tconst refreshingKey = sessionStore.refreshInProgressKey.value;\n\tconst filterId = projectStore.projectFilterId.value;\n\tconst tab = sessionStore.sessionListTab.value;\n\tconst showArchived = sessionStore.showArchivedSessions.value;\n\n\t// Spinner animation via setInterval\n\tconst spinnersRef = useRef<HTMLDivElement>(null);\n\tuseEffect(() => {\n\t\tlet idx = 0;\n\t\tconst timer = setInterval(() => {\n\t\t\tidx = (idx + 1) % spinnerFrames.length;\n\t\t\tif (!spinnersRef.current) return;\n\t\t\tconst els = spinnersRef.current.querySelectorAll(\n\t\t\t\t\".session-item.replying .session-spinner, .session-item.loading .session-spinner\",\n\t\t\t);\n\t\t\tfor (const el of els) el.textContent = spinnerFrames[idx];\n\t\t}, 80);\n\t\treturn () => clearInterval(timer);\n\t}, []);\n\n\tlet filtered = filterId ? allSessions.filter((s) => s.projectId === filterId) : allSessions;\n\tif (tab === \"sessions\") {\n\t\tfiltered = filtered.filter((s) => !(s.key || \"\").startsWith(\"cron:\") && (showArchived || !s.archived));\n\t} else if (tab === \"cron\") {\n\t\tfiltered = filtered.filter((s) => (s.key || \"\").startsWith(\"cron:\"));\n\t}\n\n\t// Build parent→children map for tree rendering\n\tconst childrenMap: Record<string, Session[]> = {};\n\tconst keyMap: KeyMap = {};\n\tfiltered.forEach((s) => {\n\t\tkeyMap[s.key] = s;\n\t\tif (s.parentSessionKey) {\n\t\t\tif (!childrenMap[s.parentSessionKey]) childrenMap[s.parentSessionKey] = [];\n\t\t\tchildrenMap[s.parentSessionKey].push(s);\n\t\t}\n\t});\n\tconst roots = filtered.filter((s) => !(s.parentSessionKey && keyMap[s.parentSessionKey]));\n\n\tfunction renderTree(session: Session, depth: number): VNode {\n\t\tconst children = childrenMap[session.key] || [];\n\t\treturn (\n\t\t\t<>\n\t\t\t\t<SessionItem\n\t\t\t\t\tkey={session.key}\n\t\t\t\t\tsession={session}\n\t\t\t\t\tactiveKey={activeKey}\n\t\t\t\t\tdepth={depth}\n\t\t\t\t\tkeyMap={keyMap}\n\t\t\t\t\trefreshing={session.key === refreshingKey}\n\t\t\t\t/>\n\t\t\t\t{children.map((child) => renderTree(child, depth + 1))}\n\t\t\t</>\n\t\t);\n\t}\n\n\treturn <div ref={spinnersRef}>{roots.map((s) => renderTree(s, 0))}</div>;\n}\n","// Mobile navigation and panel handling\n\nlet navPanel: HTMLElement | null = null;\nlet navOverlay: HTMLElement | null = null;\nlet sessionsPanel: HTMLElement | null = null;\nlet sessionsOverlay: HTMLElement | null = null;\nlet sessionsToggle: HTMLElement | null = null;\nlet burgerBtn: HTMLElement | null = null;\n\n// Check if we're in mobile view\nfunction isMobile(): boolean {\n\treturn window.innerWidth < 768;\n}\n\n// Open navigation panel\nfunction openNav(): void {\n\tif (!(navPanel && navOverlay)) return;\n\tnavPanel.classList.add(\"open\");\n\tnavOverlay.classList.add(\"visible\");\n\tdocument.body.style.overflow = \"hidden\";\n}\n\n// Close navigation panel\nfunction closeNav(): void {\n\tif (!(navPanel && navOverlay)) return;\n\tnavPanel.classList.remove(\"open\");\n\tnavOverlay.classList.remove(\"visible\");\n\tif (!sessionsPanel?.classList.contains(\"open\")) {\n\t\tdocument.body.style.overflow = \"\";\n\t}\n}\n\n// Toggle navigation panel\nfunction toggleNav(): void {\n\tif (navPanel?.classList.contains(\"open\")) {\n\t\tcloseNav();\n\t} else {\n\t\topenNav();\n\t}\n}\n\n// Open sessions panel\nfunction openSessions(): void {\n\tif (!(sessionsPanel && sessionsOverlay)) return;\n\tsessionsPanel.classList.add(\"open\");\n\tsessionsPanel.classList.remove(\"hidden\");\n\tsessionsOverlay.classList.add(\"visible\");\n\tif (sessionsToggle) sessionsToggle.classList.add(\"hidden\");\n\tdocument.body.style.overflow = \"hidden\";\n}\n\n// Close sessions panel\nfunction closeSessions(): void {\n\tif (!(sessionsPanel && sessionsOverlay)) return;\n\tsessionsPanel.classList.remove(\"open\");\n\tsessionsOverlay.classList.remove(\"visible\");\n\tif (sessionsToggle) sessionsToggle.classList.remove(\"hidden\");\n\tif (!navPanel?.classList.contains(\"open\")) {\n\t\tdocument.body.style.overflow = \"\";\n\t}\n\t// On mobile, also add hidden after transition\n\tif (isMobile()) {\n\t\tsetTimeout(() => {\n\t\t\tif (!sessionsPanel?.classList.contains(\"open\")) {\n\t\t\t\tsessionsPanel?.classList.add(\"hidden\");\n\t\t\t}\n\t\t}, 300);\n\t}\n}\n\n// Toggle sessions panel\nfunction toggleSessions(): void {\n\tif (sessionsPanel?.classList.contains(\"open\")) {\n\t\tcloseSessions();\n\t} else {\n\t\topenSessions();\n\t}\n}\n\n// Handle nav link clicks - close nav on mobile after navigation\nfunction handleNavClick(e: Event): void {\n\tif (isMobile() && (e.target as HTMLElement).closest(\".nav-link\")) {\n\t\tcloseNav();\n\t}\n}\n\n// Handle session item clicks - close sessions on mobile after selection\nfunction handleSessionClick(e: Event): void {\n\tif (isMobile() && (e.target as HTMLElement).closest(\".session-item\")) {\n\t\tsetTimeout(closeSessions, 100);\n\t}\n}\n\n// Handle resize - reset states when switching between mobile/desktop\nfunction handleResize(): void {\n\tif (isMobile()) {\n\t\t// Mobile view - show toggle button if sessions panel is not open\n\t\tif (!sessionsPanel?.classList.contains(\"open\")) {\n\t\t\tsessionsToggle?.classList.remove(\"hidden\");\n\t\t}\n\t} else {\n\t\t// Desktop view - reset mobile-specific states\n\t\tnavPanel?.classList.remove(\"open\");\n\t\tnavOverlay?.classList.remove(\"visible\");\n\t\tsessionsOverlay?.classList.remove(\"visible\");\n\t\tsessionsToggle?.classList.add(\"hidden\");\n\t\tdocument.body.style.overflow = \"\";\n\n\t\t// On desktop, sessions panel visibility is controlled differently\n\t\t// Remove open class but don't add hidden (let desktop CSS handle it)\n\t\tsessionsPanel?.classList.remove(\"open\");\n\t}\n}\n\n// Initialize mobile interactions\nexport function initMobile(): void {\n\tnavPanel = document.getElementById(\"navPanel\");\n\tnavOverlay = document.getElementById(\"navOverlay\");\n\tsessionsPanel = document.getElementById(\"sessionsPanel\");\n\tsessionsOverlay = document.getElementById(\"sessionsOverlay\");\n\tsessionsToggle = document.getElementById(\"sessionsToggle\");\n\tburgerBtn = document.getElementById(\"burgerBtn\");\n\n\t// Burger button toggles nav\n\tif (burgerBtn) {\n\t\tburgerBtn.addEventListener(\"click\", toggleNav);\n\t}\n\n\t// Overlay clicks close their respective panels\n\tif (navOverlay) {\n\t\tnavOverlay.addEventListener(\"click\", closeNav);\n\t}\n\n\tif (sessionsOverlay) {\n\t\tsessionsOverlay.addEventListener(\"click\", closeSessions);\n\t}\n\n\t// Sessions toggle FAB\n\tif (sessionsToggle) {\n\t\tsessionsToggle.addEventListener(\"click\", toggleSessions);\n\t\t// Initially hide on desktop\n\t\tif (!isMobile()) {\n\t\t\tsessionsToggle.classList.add(\"hidden\");\n\t\t}\n\t}\n\n\t// Close nav when clicking nav links on mobile\n\tif (navPanel) {\n\t\tnavPanel.addEventListener(\"click\", handleNavClick);\n\t}\n\n\t// Close sessions when clicking session items on mobile\n\tif (sessionsPanel) {\n\t\tsessionsPanel.addEventListener(\"click\", handleSessionClick);\n\t}\n\n\t// Handle resize events\n\twindow.addEventListener(\"resize\", handleResize);\n\n\t// Escape key closes panels\n\tdocument.addEventListener(\"keydown\", (e: KeyboardEvent) => {\n\t\tif (e.key === \"Escape\") {\n\t\t\tif (navPanel?.classList.contains(\"open\")) {\n\t\t\t\tcloseNav();\n\t\t\t}\n\t\t\tif (sessionsPanel?.classList.contains(\"open\") && isMobile()) {\n\t\t\t\tcloseSessions();\n\t\t\t}\n\t\t}\n\t});\n\n\t// Touch gestures for bottom sheet (sessions panel)\n\tif (sessionsPanel) {\n\t\tsetupBottomSheetGestures(sessionsPanel);\n\t}\n}\n\n// Simple swipe-down gesture to close bottom sheet\nfunction setupBottomSheetGestures(panel: HTMLElement): void {\n\tlet startY = 0;\n\tlet currentY = 0;\n\tlet isDragging = false;\n\n\tpanel.addEventListener(\n\t\t\"touchstart\",\n\t\t(e: TouchEvent) => {\n\t\t\t// Only initiate drag from the top area (drag handle region)\n\t\t\tconst touch = e.touches[0];\n\t\t\tconst panelRect = panel.getBoundingClientRect();\n\t\t\tif (touch.clientY - panelRect.top < 40) {\n\t\t\t\tstartY = touch.clientY;\n\t\t\t\tisDragging = true;\n\t\t\t}\n\t\t},\n\t\t{ passive: true },\n\t);\n\n\tpanel.addEventListener(\n\t\t\"touchmove\",\n\t\t(e: TouchEvent) => {\n\t\t\tif (!isDragging) return;\n\t\t\tcurrentY = e.touches[0].clientY;\n\t\t\tconst deltaY = currentY - startY;\n\n\t\t\t// Only allow dragging down\n\t\t\tif (deltaY > 0) {\n\t\t\t\tpanel.style.transform = `translateY(${deltaY}px)`;\n\t\t\t}\n\t\t},\n\t\t{ passive: true },\n\t);\n\n\tpanel.addEventListener(\n\t\t\"touchend\",\n\t\t() => {\n\t\t\tif (!isDragging) return;\n\t\t\tisDragging = false;\n\n\t\t\tconst deltaY = currentY - startY;\n\t\t\tpanel.style.transform = \"\";\n\n\t\t\t// Close if dragged more than 100px down\n\t\t\tif (deltaY > 100) {\n\t\t\t\tcloseSessions();\n\t\t\t}\n\t\t},\n\t\t{ passive: true },\n\t);\n}\n\n// Export functions for external use\nexport { closeNav, closeSessions, isMobile, openNav, openSessions, toggleNav, toggleSessions };\n","// ── SessionHeader Preact component ───────────────────────────\n//\n// Replaces the imperative updateChatSessionHeader() with a reactive\n// Preact component reading sessionStore.activeSession.\n\nimport type { VNode } from \"preact\";\nimport { useCallback, useEffect, useRef, useState } from \"preact/hooks\";\nimport { onEvent } from \"../events\";\nimport * as gon from \"../gon\";\nimport { parseAgentsListPayload, sendRpc } from \"../helpers\";\nimport {\n\tclearActiveSession,\n\tfetchSessions,\n\tisArchivableSession,\n\tremoveSessionFromClientState,\n\tsetSessionActiveRunId,\n\tsetSessionReplying,\n\tswitchSession,\n} from \"../sessions\";\nimport { sessionStore } from \"../stores/session-store\";\nimport type { SessionMeta } from \"../types\";\nimport { ComboSelect, confirmDialog, shareLinkDialog, shareVisibilityDialog, showToast } from \"../ui\";\n\n// ── Types ────────────────────────────────────────────────────\n\ninterface NodeInfo {\n\tnodeId: string;\n\tdisplayName?: string;\n\tplatform?: string;\n\t[key: string]: unknown;\n}\n\ninterface AgentOption {\n\tid: string;\n\tname: string;\n\temoji?: string;\n\tis_default?: boolean;\n\t[key: string]: unknown;\n}\n\ninterface SelectOption {\n\tvalue: string;\n\tlabel: string;\n}\n\ninterface SharePayload {\n\tpath?: string;\n\taccessKey?: string;\n}\n\nexport interface SessionHeaderProps {\n\tshowSelectors?: boolean;\n\tshowName?: boolean;\n\tshowShare?: boolean;\n\tshowFork?: boolean;\n\tshowStop?: boolean;\n\tshowClear?: boolean;\n\tshowDelete?: boolean;\n\tshowArchive?: boolean;\n\tnameOwnLine?: boolean;\n\tshowRenameButton?: boolean;\n\tactionButtonClass?: string;\n\tonBeforeShare?: (() => void) | null;\n\tonBeforeArchive?: (() => void) | null;\n\tonBeforeDelete?: (() => void) | null;\n}\n\n// ── Helpers ──────────────────────────────────────────────────\n\nfunction nextSessionKey(currentKey: string): string {\n\tconst allSessions = sessionStore.sessions.value;\n\tconst s = allSessions.find((x) => x.key === currentKey);\n\tif (s?.parentSessionKey) return s.parentSessionKey;\n\tconst idx = allSessions.findIndex((x) => x.key === currentKey);\n\tif (idx >= 0 && idx + 1 < allSessions.length) return allSessions[idx + 1].key;\n\tif (idx > 0) return allSessions[idx - 1].key;\n\treturn \"main\";\n}\n\nfunction buildShareUrl(payload: SharePayload): string {\n\tlet url = `${window.location.origin}${payload.path}`;\n\tif (payload.accessKey) {\n\t\turl += `?k=${encodeURIComponent(payload.accessKey)}`;\n\t}\n\treturn url;\n}\n\nfunction isSshTargetNode(node: NodeInfo | null): boolean {\n\treturn node?.platform === \"ssh\" || String(node?.nodeId || \"\").startsWith(\"ssh:\");\n}\n\nfunction nodeOptionLabel(node: NodeInfo | null): string {\n\tif (!node) return \"Local\";\n\tif (node.displayName) return node.displayName;\n\tif (isSshTargetNode(node)) {\n\t\tconst target = String(node.nodeId || \"\").replace(/^ssh:/, \"\");\n\t\treturn `SSH: ${target}`;\n\t}\n\treturn node.nodeId;\n}\n\nasync function copyShareUrl(url: string, visibility: string): Promise<void> {\n\ttry {\n\t\tif (navigator.clipboard?.writeText) {\n\t\t\tawait navigator.clipboard.writeText(url);\n\t\t\tshowToast(\"Share link copied\", \"success\");\n\t\t\treturn;\n\t\t}\n\t} catch (_err) {\n\t\t// Clipboard APIs can fail on some browsers/permissions.\n\t}\n\tawait shareLinkDialog(url, visibility);\n}\n\n// ── Component ────────────────────────────────────────────────\n\nexport function SessionHeader({\n\tshowSelectors = true,\n\tshowName = true,\n\tshowShare = true,\n\tshowFork = true,\n\tshowStop = true,\n\tshowClear = true,\n\tshowDelete = true,\n\tshowArchive = true,\n\tnameOwnLine = false,\n\tshowRenameButton = false,\n\tactionButtonClass = \"chat-session-btn\",\n\tonBeforeShare = null,\n\tonBeforeArchive = null,\n\tonBeforeDelete = null,\n}: SessionHeaderProps = {}): VNode {\n\tconst session = sessionStore.activeSession.value;\n\tconst sessionDataVersion = session?.dataVersion.value || 0;\n\tconst currentKey = sessionStore.activeSessionKey.value;\n\tconst gonAgentsPayload = parseAgentsListPayload(gon.get(\"agents\") as never);\n\tconst initialAgentOptions: AgentOption[] = Array.isArray(gonAgentsPayload?.agents)\n\t\t? (gonAgentsPayload.agents as AgentOption[])\n\t\t: [];\n\tconst initialDefaultAgentId = typeof gonAgentsPayload?.defaultId === \"string\" ? gonAgentsPayload.defaultId : \"main\";\n\n\tconst [renaming, setRenaming] = useState(false);\n\tconst [clearing, setClearing] = useState(false);\n\tconst [stopping, setStopping] = useState(false);\n\tconst [switchingAgent, setSwitchingAgent] = useState(false);\n\tconst [agentOptions, setAgentOptions] = useState<AgentOption[]>(initialAgentOptions);\n\tconst [defaultAgentId, setDefaultAgentId] = useState(initialDefaultAgentId);\n\tconst [agentOptionsLoaded, setAgentOptionsLoaded] = useState(initialAgentOptions.length > 0);\n\tconst [nodeOptions, setNodeOptions] = useState<NodeInfo[]>([]);\n\tconst [switchingNode, setSwitchingNode] = useState(false);\n\tconst inputRef = useRef<HTMLInputElement>(null);\n\n\tconst fullName = session ? session.label || session.key : currentKey;\n\tconst displayName = nameOwnLine ? fullName : fullName.length > 20 ? `${fullName.slice(0, 20)}\\u2026` : fullName;\n\tconst replying = session?.replying.value;\n\tconst activeRunId = session?.activeRunId.value || null;\n\n\tconst isMain = currentKey === \"main\";\n\tconst isCron = currentKey.startsWith(\"cron:\");\n\tconst canRename = !(isMain || isCron);\n\tconst canStop = !isCron && replying;\n\tconst canArchive = !!session && isArchivableSession(session as unknown as SessionMeta);\n\tconst showArchivedSessions = sessionStore.showArchivedSessions.value;\n\tconst currentAgentId = session?.agent_id || defaultAgentId || \"main\";\n\tconst currentNodeId = session?.node_id || \"\";\n\n\tuseEffect(() => {\n\t\tlet cancelled = false;\n\t\tsendRpc(\"agents.list\", {}).then((res) => {\n\t\t\tif (cancelled) return;\n\t\t\tif (!res?.ok) {\n\t\t\t\tsetAgentOptionsLoaded(true);\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tconst parsed = parseAgentsListPayload(res.payload as never);\n\t\t\tsetDefaultAgentId(parsed.defaultId);\n\t\t\tsetAgentOptions(parsed.agents as AgentOption[]);\n\t\t\tsetAgentOptionsLoaded(true);\n\t\t});\n\t\treturn () => {\n\t\t\tcancelled = true;\n\t\t};\n\t}, [currentKey]);\n\n\t// Fetch connected nodes and subscribe to presence updates.\n\tuseEffect(() => {\n\t\tlet cancelled = false;\n\t\tconst fetchNodes = (): void => {\n\t\t\tsendRpc<NodeInfo[]>(\"node.list\", {}).then((res) => {\n\t\t\t\tif (cancelled || !res?.ok) return;\n\t\t\t\tsetNodeOptions(Array.isArray(res.payload) ? res.payload : []);\n\t\t\t});\n\t\t};\n\t\tfetchNodes();\n\t\tconst unsub = onEvent(\"presence\", () => {\n\t\t\tif (!cancelled) fetchNodes();\n\t\t});\n\t\treturn () => {\n\t\t\tcancelled = true;\n\t\t\tunsub();\n\t\t};\n\t}, [currentKey]);\n\n\tconst startRename = useCallback(() => {\n\t\tif (!canRename) return;\n\t\tsetRenaming(true);\n\t\trequestAnimationFrame(() => {\n\t\t\tif (inputRef.current) {\n\t\t\t\tinputRef.current.value = fullName;\n\t\t\t\tinputRef.current.focus();\n\t\t\t\tinputRef.current.select();\n\t\t\t}\n\t\t});\n\t}, [canRename, fullName]);\n\n\tconst commitRename = useCallback(() => {\n\t\tconst val = inputRef.current?.value.trim() || \"\";\n\t\tsetRenaming(false);\n\t\tif (val && val !== fullName) {\n\t\t\tsendRpc(\"sessions.patch\", { key: currentKey, label: val }).then((res) => {\n\t\t\t\tif (res?.ok) fetchSessions();\n\t\t\t});\n\t\t}\n\t}, [currentKey, fullName]);\n\n\tconst onKeyDown = useCallback(\n\t\t(e: KeyboardEvent) => {\n\t\t\tif (e.key === \"Enter\" && !e.isComposing) {\n\t\t\t\te.preventDefault();\n\t\t\t\tcommitRename();\n\t\t\t}\n\t\t\tif (e.key === \"Escape\") {\n\t\t\t\tsetRenaming(false);\n\t\t\t}\n\t\t},\n\t\t[commitRename],\n\t);\n\n\tconst onFork = useCallback(() => {\n\t\tsendRpc<{ sessionKey?: string }>(\"sessions.fork\", { key: currentKey }).then((res) => {\n\t\t\tif (res?.ok && res.payload?.sessionKey) {\n\t\t\t\tfetchSessions();\n\t\t\t\tswitchSession(res.payload.sessionKey);\n\t\t\t}\n\t\t});\n\t}, [currentKey]);\n\n\tconst onDelete = useCallback(() => {\n\t\tif (typeof onBeforeDelete === \"function\") {\n\t\t\tonBeforeDelete();\n\t\t}\n\t\tconst currentSession = sessionStore.getByKey(currentKey);\n\t\tconst msgCount = currentSession ? currentSession.messageCount || 0 : 0;\n\t\tconst nextKey = nextSessionKey(currentKey);\n\t\tconst canOptimisticallyDelete = !currentSession?.worktree_branch;\n\t\tconst applyDeletedState = (): void => {\n\t\t\tremoveSessionFromClientState(currentKey, { nextKey });\n\t\t\tswitchSession(nextKey);\n\t\t};\n\t\tconst runDelete = (force: boolean): void => {\n\t\t\tconst request: Record<string, unknown> = { key: currentKey };\n\t\t\tif (force) request.force = true;\n\t\t\tlet optimisticApplied = false;\n\t\t\tif (canOptimisticallyDelete && !force) {\n\t\t\t\tapplyDeletedState();\n\t\t\t\toptimisticApplied = true;\n\t\t\t}\n\t\t\tsendRpc(\"sessions.delete\", request).then((res) => {\n\t\t\t\tconst err = (res?.error as { message?: string })?.message || (res?.error as unknown as string) || \"\";\n\t\t\t\tif (res && !res.ok && typeof err === \"string\" && err.indexOf(\"uncommitted changes\") !== -1) {\n\t\t\t\t\tfetchSessions();\n\t\t\t\t\tconfirmDialog(\"Worktree has uncommitted changes. Force delete?\").then((yes) => {\n\t\t\t\t\t\tif (!yes) return;\n\t\t\t\t\t\trunDelete(true);\n\t\t\t\t\t});\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tif (res && !res.ok) {\n\t\t\t\t\tshowToast(err || \"Failed to delete session\", \"error\");\n\t\t\t\t\tfetchSessions();\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tif (!optimisticApplied) {\n\t\t\t\t\tapplyDeletedState();\n\t\t\t\t}\n\t\t\t\tfetchSessions();\n\t\t\t});\n\t\t};\n\t\tconst isUnmodifiedFork = currentSession && currentSession.forkPoint != null && msgCount <= currentSession.forkPoint;\n\t\tif (msgCount > 0 && !isUnmodifiedFork) {\n\t\t\tconfirmDialog(\"Delete this session?\").then((yes) => {\n\t\t\t\tif (yes) runDelete(false);\n\t\t\t});\n\t\t} else {\n\t\t\trunDelete(false);\n\t\t}\n\t}, [currentKey, onBeforeDelete, sessionDataVersion]);\n\n\tconst onClear = useCallback(() => {\n\t\tif (clearing) return;\n\t\tsetClearing(true);\n\t\tclearActiveSession().finally(() => {\n\t\t\tsetClearing(false);\n\t\t});\n\t}, [clearing]);\n\n\tconst onStop = useCallback(() => {\n\t\tif (stopping) return;\n\t\tconst params: Record<string, unknown> = { sessionKey: currentKey };\n\t\tif (activeRunId) params.runId = activeRunId;\n\t\tsetStopping(true);\n\t\tsendRpc(\"chat.abort\", params)\n\t\t\t.then((res) => {\n\t\t\t\tif (!res?.ok) {\n\t\t\t\t\tshowToast((res?.error as { message?: string })?.message || \"Failed to stop response\", \"error\");\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tsetSessionActiveRunId(currentKey, null);\n\t\t\t\tsetSessionReplying(currentKey, false);\n\t\t\t})\n\t\t\t.finally(() => {\n\t\t\t\tsetStopping(false);\n\t\t\t});\n\t}, [activeRunId, currentKey, stopping]);\n\n\tconst shareSnapshot = useCallback(\n\t\tasync (visibility: string) => {\n\t\t\tconst res = await sendRpc<SharePayload>(\"sessions.share.create\", { key: currentKey, visibility });\n\t\t\tif (!(res?.ok && res.payload?.path)) {\n\t\t\t\tshowToast((res?.error as { message?: string })?.message || \"Failed to create share link\", \"error\");\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tconst url = buildShareUrl(res.payload);\n\t\t\tawait copyShareUrl(url, visibility);\n\n\t\t\tif (visibility === \"private\") {\n\t\t\t\tshowToast(\"Private link includes a key, share it only with trusted people\", \"success\");\n\t\t\t}\n\n\t\t\t// Reload the active session so the snapshot cutoff notice appears.\n\t\t\tswitchSession(currentKey);\n\t\t\tfetchSessions();\n\t\t},\n\t\t[currentKey],\n\t);\n\n\tconst onShare = useCallback(() => {\n\t\tif (typeof onBeforeShare === \"function\") {\n\t\t\tonBeforeShare();\n\t\t}\n\t\tshareVisibilityDialog().then((visibility) => {\n\t\t\tif (!visibility) return;\n\t\t\tvoid shareSnapshot(visibility);\n\t\t});\n\t}, [onBeforeShare, shareSnapshot]);\n\n\tconst onArchive = useCallback(() => {\n\t\tif (!(session && canArchive)) return;\n\t\tif (typeof onBeforeArc