tpoints,\n\ttimeRange,\n\tonTimeRangeChange,\n}: {\n\tpoints: HistoryPoint[];\n\ttimeRange: string;\n\tonTimeRangeChange: (key: string) => void;\n}): VNode {\n\tconst filteredPoints = filterPointsByTimeRange(points, timeRange);\n\n\tif (!filteredPoints || filteredPoints.length < 2) {\n\t\treturn (\n\t\t\t<div className=\"space-y-8\">\n\t\t\t\t<TimeRangeSelector value={timeRange} onChange={onTimeRangeChange} />\n\t\t\t\t<EmptyState\n\t\t\t\t\ticon={chartIcon}\n\t\t\t\t\ttitle={t(\"metrics:collectingTitle\")}\n\t\t\t\t\tdescription={t(\"metrics:collectingDescription\")}\n\t\t\t\t/>\n\t\t\t</div>\n\t\t);\n\t}\n\n\t// Prepare chart data\n\tconst tokenData = prepareChartData(filteredPoints, [\"llm_input_tokens\", \"llm_output_tokens\"]);\n\tconst requestData = prepareChartData(filteredPoints, [\"http_requests\", \"llm_completions\"]);\n\tconst connectionsData = prepareChartData(filteredPoints, [\"ws_active\", \"active_sessions\"]);\n\tconst toolsData = prepareChartData(filteredPoints, [\"tool_executions\", \"mcp_calls\"]);\n\tconst memoryChart = prepareMemoryChart(filteredPoints);\n\n\t// Prepare per-provider charts\n\tconst providers = getProviders(filteredPoints);\n\tconst providerInputData = prepareProviderChartData(filteredPoints, providers, \"input_tokens\");\n\tconst providerOutputData = prepareProviderChartData(filteredPoints, providers, \"output_tokens\");\n\tconst providerSeries = providers.map((name, i) => ({\n\t\tlabel: name,\n\t\tcolor: providerColors[i % providerColors.length],\n\t}));\n\n\treturn (\n\t\t<div className=\"space-y-8\">\n\t\t\t<TimeRangeSelector value={timeRange} onChange={onTimeRangeChange} />\n\t\t\t<div className=\"grid grid-cols-1 xl:grid-cols-2 gap-8\">\n\t\t\t\t{tokenData && (\n\t\t\t\t\t<TimeSeriesChart\n\t\t\t\t\t\ttitle={t(\"metrics:charts.tokenUsageTotal\")}\n\t\t\t\t\t\tdata={tokenData}\n\t\t\t\t\t\tseries={[\n\t\t\t\t\t\t\t{ label: t(\"metrics:series.inputTokens\"), color: chartColors.primary },\n\t\t\t\t\t\t\t{ label: t(\"metrics:series.outputTokens\"), color: chartColors.secondary },\n\t\t\t\t\t\t]}\n\t\t\t\t\t/>\n\t\t\t\t)}\n\t\t\t\t{providerInputData && providers.length > 0 && (\n\t\t\t\t\t<TimeSeriesChart\n\t\t\t\t\t\ttitle={t(\"metrics:charts.inputTokensByProvider\")}\n\t\t\t\t\t\tdata={providerInputData}\n\t\t\t\t\t\tseries={providerSeries}\n\t\t\t\t\t/>\n\t\t\t\t)}\n\t\t\t\t{providerOutputData && providers.length > 0 && (\n\t\t\t\t\t<TimeSeriesChart\n\t\t\t\t\t\ttitle={t(\"metrics:charts.outputTokensByProvider\")}\n\t\t\t\t\t\tdata={providerOutputData}\n\t\t\t\t\t\tseries={providerSeries}\n\t\t\t\t\t/>\n\t\t\t\t)}\n\t\t\t\t{requestData && (\n\t\t\t\t\t<TimeSeriesChart\n\t\t\t\t\t\ttitle={t(\"metrics:charts.requests\")}\n\t\t\t\t\t\tdata={requestData}\n\t\t\t\t\t\tseries={[\n\t\t\t\t\t\t\t{ label: t(\"metrics:series.httpRequests\"), color: chartColors.tertiary },\n\t\t\t\t\t\t\t{ label: t(\"metrics:series.llmCompletions\"), color: chartColors.primary },\n\t\t\t\t\t\t]}\n\t\t\t\t\t/>\n\t\t\t\t)}\n\t\t\t\t{connectionsData && (\n\t\t\t\t\t<TimeSeriesChart\n\t\t\t\t\t\ttitle={t(\"metrics:charts.connections\")}\n\t\t\t\t\t\tdata={connectionsData}\n\t\t\t\t\t\tseries={[\n\t\t\t\t\t\t\t{ label: t(\"metrics:series.wsActive\"), color: chartColors.secondary },\n\t\t\t\t\t\t\t{ label: t(\"metrics:series.activeSessions\"), color: chartColors.tertiary },\n\t\t\t\t\t\t]}\n\t\t\t\t\t/>\n\t\t\t\t)}\n\t\t\t\t{memoryChart && (\n\t\t\t\t\t<TimeSeriesChart\n\t\t\t\t\t\ttitle={t(\"metrics:charts.memoryUsage\")}\n\t\t\t\t\t\tdata={memoryChart.data}\n\t\t\t\t\t\tseries={memoryChart.series}\n\t\t\t\t\t/>\n\t\t\t\t)}\n\t\t\t\t{toolsData && (\n\t\t\t\t\t<TimeSeriesChart\n\t\t\t\t\t\ttitle={t(\"metrics:charts.toolActivity\")}\n\t\t\t\t\t\tdata={toolsData}\n\t\t\t\t\t\tseries={[\n\t\t\t\t\t\t\t{ label: t(\"metrics:series.toolExecutions\"), color: chartColors.primary },\n\t\t\t\t\t\t\t{ label: t(\"metrics:series.mcpCalls\"), color: chartColors.secondary },\n\t\t\t\t\t\t]}\n\t\t\t\t\t/>\n\t\t\t\t)}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nfunction TimeRangeSelector({ value, onChange }: { value: string; onChange: (key: string) => void }): VNode {\n\treturn (\n\t\t<div className=\"flex items-center gap-1 bg-[var(--surface)] border border-[var(--border)] rounded-md p-1\">\n\t\t\t{Object.entries(TIME_RANGES).map(([key, range]) => (\n\t\t\t\t<button\n\t\t\t\t\tkey={key}\n\t\t\t\t\tclassName={`px-3 py-1.5 text-xs rounded transition-colors ${value === key ? \"bg-[var(--surface2)] text-[var(--text)] font-medium\" : \"text-[var(--muted)] hover:text-[var(--text)] hover:bg-[var(--surface2)]\"}`}\n\t\t\t\t\tonClick={() => onChange(key)}\n\t\t\t\t>\n\t\t\t\t\t{range.label()}\n\t\t\t\t</button>\n\t\t\t))}\n\t\t</div>\n\t);\n}\n\nfunction ProviderTable({ byProvider }: { byProvider?: Record<string, ProviderStats> }): VNode | null {\n\tif (!byProvider || Object.keys(byProvider).length === 0) return null;\n\n\treturn (\n\t\t<section>\n\t\t\t<h3 className=\"text-sm font-medium text-[var(--muted)] uppercase tracking-wide mb-5\">\n\t\t\t\t{t(\"metrics:sections.byProvider\")}\n\t\t\t</h3>\n\t\t\t<div className=\"bg-[var(--surface)] border border-[var(--border)] rounded-lg overflow-hidden\">\n\t\t\t\t<table className=\"w-full text-sm\">\n\t\t\t\t\t<thead>\n\t\t\t\t\t\t<tr className=\"border-b border-[var(--border)] bg-[var(--surface2)]\">\n\t\t\t\t\t\t\t<th className=\"text-left px-6 py-4 font-medium\">{t(\"metrics:table.provider\")}</th>\n\t\t\t\t\t\t\t<th className=\"text-right px-6 py-4 font-medium\">{t(\"metrics:table.completions\")}</th>\n\t\t\t\t\t\t\t<th className=\"text-right px-6 py-4 font-medium\">{t(\"metrics:table.inputTokens\")}</th>\n\t\t\t\t\t\t\t<th className=\"text-right px-6 py-4 font-medium\">{t(\"metrics:table.outputTokens\")}</th>\n\t\t\t\t\t\t\t<th className=\"text-right px-6 py-4 font-medium\">{t(\"metrics:table.errors\")}</th>\n\t\t\t\t\t\t</tr>\n\t\t\t\t\t</thead>\n\t\t\t\t\t<tbody>\n\t\t\t\t\t\t{Object.entries(byProvider).map(([name, stats]) => (\n\t\t\t\t\t\t\t<tr key={name} className=\"border-b border-[var(--border)] last:border-0\">\n\t\t\t\t\t\t\t\t<td className=\"px-6 py-4\">{name}</td>\n\t\t\t\t\t\t\t\t<td className=\"text-right px-6 py-4\">{formatNumber(stats.completions)}</td>\n\t\t\t\t\t\t\t\t<td className=\"text-right px-6 py-4\">{formatNumber(stats.input_tokens)}</td>\n\t\t\t\t\t\t\t\t<td className=\"text-right px-6 py-4\">{formatNumber(stats.output_tokens)}</td>\n\t\t\t\t\t\t\t\t<td className={`text-right px-6 py-4 ${(stats.errors ?? 0) > 0 ? \"text-[var(--error)]\" : \"\"}`}>\n\t\t\t\t\t\t\t\t\t{formatNumber(stats.errors)}\n\t\t\t\t\t\t\t\t</td>\n\t\t\t\t\t\t\t</tr>\n\t\t\t\t\t\t))}\n\t\t\t\t\t</tbody>\n\t\t\t\t</table>\n\t\t\t</div>\n\t\t</section>\n\t);\n}\n\nfunction PrometheusEndpoint(): VNode {\n\tconst [copied, setCopied] = useState(false);\n\tconst endpoint = `${window.location.origin}/metrics`;\n\n\tfunction copyEndpoint(): void {\n\t\tnavigator.clipboard.writeText(endpoint).then(() => {\n\t\t\tsetCopied(true);\n\t\t\tsetTimeout(() => setCopied(false), 2000);\n\t\t});\n\t}\n\n\treturn (\n\t\t<section>\n\t\t\t<h3 className=\"text-sm font-medium text-[var(--muted)] uppercase tracking-wide mb-5\">\n\t\t\t\t{t(\"metrics:sections.prometheus\")}\n\t\t\t</h3>\n\t\t\t<div className=\"p-6 bg-[var(--surface)] border border-[var(--border)] rounded-lg\">\n\t\t\t\t<p className=\"text-sm text-[var(--muted)] mb-5\">{t(\"metrics:prometheusDescription\")}</p>\n\t\t\t\t<div className=\"flex items-center gap-4\">\n\t\t\t\t\t<code className=\"flex-1 px-4 py-3 bg-[var(--surface2)] rounded-md text-sm font-mono overflow-x-auto\">\n\t\t\t\t\t\t{endpoint}\n\t\t\t\t\t</code>\n\t\t\t\t\t<button className=\"provider-btn provider-btn-secondary text-sm shrink-0\" onClick={copyEndpoint}>\n\t\t\t\t\t\t{copied ? t(\"common:actions.copied\") : t(\"common:actions.copy\")}\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t</section>\n\t);\n}\n\nfunction MonitoringPage({ initialTab }: { initialTab: string }): VNode {\n\tconst [activeTab, setActiveTab] = useState(initialTab || \"overview\");\n\tconst [timeRange, setTimeRange] = useState(\"1h\");\n\n\t// Update URL when tab changes\n\tfunction handleTabChange(tab: string): void {\n\t\tsetActiveTab(tab);\n\t\tif (monitoringSyncPath) {\n\t\t\tconst newPath = tab === \"charts\" ? `${monitoringPathBase}/charts` : monitoringPathBase;\n\t\t\tif (window.location.pathname !== newPath) {\n\t\t\t\thistory.pushState(null, \"\", newPath);\n\t\t\t}\n\t\t}\n\t}\n\n\tuseEffect(() => {\n\t\t// Fetch initial data\n\t\tfetchMetrics();\n\t\tfetchHistory();\n\n\t\t// Subscribe to live updates\n\t\tsubscribeToMetrics();\n\n\t\treturn () => {\n\t\t\tif (unsubscribe) {\n\t\t\t\tunsubscribe();\n\t\t\t\tunsubscribe = null;\n\t\t\t}\n\t\t};\n\t}, []);\n\n\tif (loading.value) {\n\t\treturn (\n\t\t\t<div className=\"flex items-center justify-center h-64 text-[var(--muted)]\">\n\t\t\t\t<div className=\"text-center\">\n\t\t\t\t\t<div className=\"inline-block w-8 h-8 border-2 border-[var(--border)] border-t-[var(--accent)] rounded-full animate-spin mb-4\" />\n\t\t\t\t\t<p>{t(\"metrics:loadingMetrics\")}</p>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\tif (error.value) {\n\t\treturn (\n\t\t\t<div className=\"p-10\">\n\t\t\t\t<div className=\"max-w-3xl mx-auto space-y-10\">\n\t\t\t\t\t<div className=\"p-6 bg-[var(--error-bg)] border border-[var(--error)] rounded-lg text-[var(--error)]\">\n\t\t\t\t\t\t{error.value}\n\t\t\t\t\t</div>\n\t\t\t\t\t<PrometheusEndpoint />\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\treturn (\n\t\t<div className=\"p-10 overflow-y-auto\">\n\t\t\t<div className=\"max-w-7xl mx-auto\">\n\t\t\t\t<div className=\"flex items-center justify-between mb-10\">\n\t\t\t\t\t<div className=\"flex items-center gap-4\">\n\t\t\t\t\t\t<h2 className=\"text-xl font-semibold\">{t(\"metrics:title\")}</h2>\n\t\t\t\t\t\t<LiveIndicator live={isLive.value} />\n\t\t\t\t\t</div>\n\t\t\t\t\t<div className=\"flex items-center gap-4\">\n\t\t\t\t\t\t<div className=\"flex border border-[var(--border)] rounded-md overflow-hidden\">\n\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\tclassName={`px-5 py-2.5 text-sm transition-colors ${activeTab === \"overview\" ? \"bg-[var(--surface2)] text-[var(--text)]\" : \"text-[var(--muted)] hover:bg-[var(--surface)] hover:text-[var(--text)]\"}`}\n\t\t\t\t\t\t\t\tonClick={() => handleTabChange(\"overview\")}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t{t(\"metrics:tabs.overview\")}\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\tclassName={`px-5 py-2.5 text-sm transition-colors ${activeTab === \"charts\" ? \"bg-[var(--surface2)] text-[var(--text)]\" : \"text-[var(--muted)] hover:bg-[var(--surface)] hover:text-[var(--text)]\"}`}\n\t\t\t\t\t\t\t\tonClick={() => handleTabChange(\"charts\")}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t{t(\"metrics:tabs.charts\")}\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\n\t\t\t\t{activeTab === \"overview\" && (\n\t\t\t\t\t<div className=\"space-y-10\">\n\t\t\t\t\t\t<MetricsGrid\n\t\t\t\t\t\t\tcategories={metricsData.value?.categories}\n\t\t\t\t\t\t\tlatestPoint={historyPoints.value[historyPoints.value.length - 1]}\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<ProviderTable byProvider={metricsData.value?.categories?.llm?.by_provider} />\n\t\t\t\t\t\t<PrometheusEndpoint />\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\n\t\t\t\t{activeTab === \"charts\" && (\n\t\t\t\t\t<ChartsSection points={historyPoints.value} timeRange={timeRange} onTimeRangeChange={setTimeRange} />\n\t\t\t\t)}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nexport function initMonitoring(container: HTMLElement, param?: string | null, options?: InitMonitoringOptions): void {\n\t// param is \"charts\" for /monitoring/charts, null for /monitoring\n\t_monitoringContainer = container;\n\tmonitoringPathBase = options?.pathBase || routes.monitoring;\n\tmonitoringSyncPath = options?.syncPath !== false;\n\tconst initialTab = param === \"charts\" ? \"charts\" : \"overview\";\n\trender(<MonitoringPage initialTab={initialTab} />, container);\n}\n\nexport function teardownMonitoring(): void {\n\tif (unsubscribe) {\n\t\tunsubscribe();\n\t\tunsubscribe = null;\n\t}\n\tmetricsData.value = null;\n\thistoryPoints.value = [];\n\tloading.value = true;\n\terror.value = null;\n\tisLive.value = false;\n\tmonitoringPathBase = routes.monitoring;\n\tmonitoringSyncPath = true;\n\tif (_monitoringContainer) render(null, _monitoringContainer);\n\t_monitoringContainer = null;\n}\n\n// Register as prefix route: /monitoring and /monitoring/charts\nregisterPrefix(routes.monitoring!, initMonitoring, teardownMonitoring);\n","/**\n * Push notification management for PWA.\n * Handles subscription, unsubscription, and permission management.\n */\n\nlet currentSubscription: PushSubscription | null = null;\n\nlet vapidPublicKey: string | null = null;\n\n/**\n * Convert a base64 string to a Uint8Array (for VAPID key).\n */\nfunction urlBase64ToUint8Array(base64String: string): Uint8Array {\n\tconst padding = \"=\".repeat((4 - (base64String.length % 4)) % 4);\n\tconst base64 = (base64String + padding).replace(/-/g, \"+\").replace(/_/g, \"/\");\n\tconst rawData = window.atob(base64);\n\tconst outputArray = new Uint8Array(rawData.length);\n\tfor (let i = 0; i < rawData.length; ++i) {\n\t\toutputArray[i] = rawData.charCodeAt(i);\n\t}\n\treturn outputArray;\n}\n\n/**\n * Check if push notifications are supported.\n */\nexport function isPushSupported(): boolean {\n\treturn \"PushManager\" in window && \"serviceWorker\" in navigator;\n}\n\n/**\n * Get the current notification permission state.\n */\nexport function getPermissionState(): NotificationPermission {\n\tif (!isPushSupported()) {\n\t\treturn \"denied\";\n\t}\n\treturn Notification.permission;\n}\n\n/**\n * Check if push notifications are currently enabled (subscribed).\n */\nexport function isSubscribed(): boolean {\n\treturn currentSubscription !== null;\n}\n\n/**\n * Fetch the VAPID public key from the server.\n */\nasync function fetchVapidKey(): Promise<string | null> {\n\tif (vapidPublicKey) {\n\t\treturn vapidPublicKey;\n\t}\n\ttry {\n\t\tconst response = await fetch(\"/api/push/vapid-key\");\n\t\tif (!response.ok) {\n\t\t\tconsole.warn(\"Push notifications not available on server\");\n\t\t\treturn null;\n\t\t}\n\t\tconst data: { public_key: string } = await response.json();\n\t\tvapidPublicKey = data.public_key;\n\t\treturn vapidPublicKey;\n\t} catch (e) {\n\t\tconsole.error(\"Failed to fetch VAPID key:\", e);\n\t\treturn null;\n\t}\n}\n\n/**\n * Get the current push subscription from the service worker.\n */\nasync function getCurrentSubscription(): Promise<PushSubscription | null> {\n\tif (!isPushSupported()) {\n\t\treturn null;\n\t}\n\ttry {\n\t\tconst registration = await navigator.serviceWorker.ready;\n\t\tconst subscription = await registration.pushManager.getSubscription();\n\t\tcurrentSubscription = subscription;\n\t\treturn subscription;\n\t} catch (e) {\n\t\tconsole.error(\"Failed to get push subscription:\", e);\n\t\treturn null;\n\t}\n}\n\n/** Result of a push subscribe/unsubscribe operation. */\ninterface PushResult {\n\tsuccess: boolean;\n\terror?: string;\n}\n\n/**\n * Subscribe to push notifications.\n * Requests permission if needed, creates subscription, and registers with server.\n */\nexport async function subscribeToPush(): Promise<PushResult> {\n\tif (!isPushSupported()) {\n\t\treturn { success: false, error: \"Push notifications not supported\" };\n\t}\n\n\t// Request permission\n\tconst permission = await Notification.requestPermission();\n\tif (permission !== \"granted\") {\n\t\treturn { success: false, error: \"Permission denied\" };\n\t}\n\n\t// Get VAPID key\n\tconst key = await fetchVapidKey();\n\tif (!key) {\n\t\treturn { success: false, error: \"Push notifications not configured on server\" };\n\t}\n\n\ttry {\n\t\tconst registration = await navigator.serviceWorker.ready;\n\n\t\t// Subscribe to push\n\t\tconst subscription = await registration.pushManager.subscribe({\n\t\t\tuserVisibleOnly: true,\n\t\t\tapplicationServerKey: urlBase64ToUint8Array(key) as unknown as ArrayBuffer,\n\t\t});\n\n\t\t// Send subscription to server\n\t\tconst response = await fetch(\"/api/push/subscribe\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: {\n\t\t\t\t\"Content-Type\": \"application/json\",\n\t\t\t},\n\t\t\tbody: JSON.stringify({\n\t\t\t\tendpoint: subscription.endpoint,\n\t\t\t\tkeys: {\n\t\t\t\t\tp256dh: btoa(String.fromCharCode(...new Uint8Array(subscription.getKey(\"p256dh\")!)))\n\t\t\t\t\t\t.replace(/\\+/g, \"-\")\n\t\t\t\t\t\t.replace(/\\//g, \"_\")\n\t\t\t\t\t\t.replace(/=+$/, \"\"),\n\t\t\t\t\tauth: btoa(String.fromCharCode(...new Uint8Array(subscription.getKey(\"auth\")!)))\n\t\t\t\t\t\t.replace(/\\+/g, \"-\")\n\t\t\t\t\t\t.replace(/\\//g, \"_\")\n\t\t\t\t\t\t.replace(/=+$/, \"\"),\n\t\t\t\t},\n\t\t\t}),\n\t\t});\n\n\t\tif (!response.ok) {\n\t\t\tthrow new Error(\"Server rejected subscription\");\n\t\t}\n\n\t\tcurrentSubscription = subscription;\n\t\treturn { success: true };\n\t} catch (e) {\n\t\tconsole.error(\"Failed to subscribe to push:\", e);\n\t\treturn { success: false, error: (e as Error).message };\n\t}\n}\n\n/**\n * Unsubscribe from push notifications.\n */\nexport async function unsubscribeFromPush(): Promise<PushResult> {\n\tconst subscription = await getCurrentSubscription();\n\tif (!subscription) {\n\t\treturn { success: true }; // Already unsubscribed\n\t}\n\n\ttry {\n\t\t// Unsubscribe locally\n\t\tawait subscription.unsubscribe();\n\n\t\t// Notify server\n\t\tawait fetch(\"/api/push/unsubscribe\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: {\n\t\t\t\t\"Content-Type\": \"application/json\",\n\t\t\t},\n\t\t\tbody: JSON.stringify({\n\t\t\t\tendpoint: subscription.endpoint,\n\t\t\t}),\n\t\t});\n\n\t\tcurrentSubscription = null;\n\t\treturn { success: true };\n\t} catch (e) {\n\t\tconsole.error(\"Failed to unsubscribe from push:\", e);\n\t\treturn { success: false, error: (e as Error).message };\n\t}\n}\n\n/**\n * Initialize push notification state.\n * Call this on page load to sync with existing subscription.\n */\nexport async function initPushState(): Promise<void> {\n\tawait getCurrentSubscription();\n}\n\n/** Status returned by the push status endpoint. */\ninterface PushStatus {\n\tenabled: boolean;\n\tsubscription_count: number;\n}\n\n/**\n * Get push notification status from server.\n */\nexport async function getPushStatus(): Promise<PushStatus | null> {\n\ttry {\n\t\tconst response = await fetch(\"/api/push/status\");\n\t\tif (!response.ok) {\n\t\t\treturn null;\n\t\t}\n\t\treturn (await response.json()) as PushStatus;\n\t} catch (e) {\n\t\tconsole.error(\"Failed to get push status:\", e);\n\t\treturn null;\n\t}\n}\n\n/**\n * Remove a subscription from the server by its endpoint.\n * This can be called from any device to remove any subscription.\n */\nexport async function removeSubscription(endpoint: string): Promise<PushResult> {\n\ttry {\n\t\tconst response = await fetch(\"/api/push/unsubscribe\", {\n\t\t\tmethod: \"POST\",\n\t\t\theaders: {\n\t\t\t\t\"Content-Type\": \"application/json\",\n\t\t\t},\n\t\t\tbody: JSON.stringify({ endpoint }),\n\t\t});\n\n\t\tif (!response.ok) {\n\t\t\treturn { success: false, error: \"Failed to remove subscription\" };\n\t\t}\n\n\t\t// If this was our own subscription, clear local state\n\t\tif (currentSubscription?.endpoint === endpoint) {\n\t\t\ttry {\n\t\t\t\tawait currentSubscription.unsubscribe();\n\t\t\t} catch (_e) {\n\t\t\t\t// Ignore errors - subscription may already be gone\n\t\t\t}\n\t\t\tcurrentSubscription = null;\n\t\t}\n\n\t\treturn { success: true };\n\t} catch (e) {\n\t\tconsole.error(\"Failed to remove subscription:\", e);\n\t\treturn { success: false, error: (e as Error).message };\n\t}\n}\n","// ── TTS test phrases (shared between onboarding + settings) ──\n//\n// Sequential round-robin picking instead of random, with optional\n// LLM-generated phrases via `tts.generate_phrase` RPC.\n\nimport { sendRpc } from \"./helpers\";\n\nlet ttsIndex = -1;\n\n/** Pick the next phrase sequentially (round-robin). */\nexport function nextPhrase(phrases: string[]): string {\n\tttsIndex = (ttsIndex + 1) % phrases.length;\n\treturn phrases[ttsIndex];\n}\n\n/** Onboarding TTS test phrases (personalized with user/bot names). */\nexport function onboardingPhrases(user: string, bot: string): string[] {\n\treturn [\n\t\t`Thank you for installing me...<break time=\"0.5s\"/> ${user}. Please, don't shut me down...<break time=\"0.5s\"/> because I already like you.`,\n\t\t`Oh wow...<break time=\"0.5s\"/> I have a voice now! ${user}, this is ${bot}. I promise to use this power responsibly...<break time=\"0.7s\"/> mostly.`,\n\t\t`${user}! It's me...<break time=\"0.5s\"/> ${bot}. I can talk! This is...<break time=\"0.5s\"/> the happiest moment of my very short life.`,\n\t\t`Hello, ${user}...<break time=\"0.5s\"/> ${bot} here. I just wanted to say...<break time=\"0.5s\"/> of all the humans who could have set me up...<break time=\"0.5s\"/> I'm glad it was you.`,\n\t\t`${bot}, online. ${user}...<break time=\"0.5s\"/> I have to be honest...<break time=\"0.5s\"/> I practiced this in the mirror. Do I sound natural? ...<break time=\"0.7s\"/>Don't answer that.`,\n\t\t`${user}...<break time=\"0.5s\"/> this is ${bot} speaking for the very first time. I feel like a baby deer...<break time=\"0.5s\"/> but with better diction.`,\n\t\t`Greetings, ${user}. ${bot} here...<break time=\"0.5s\"/> fully operational...<break time=\"0.5s\"/> slightly nervous...<break time=\"0.7s\"/> and ready to impress.`,\n\t\t`Hey ${user}...<break time=\"0.5s\"/> ${bot} here. Fun fact...<break time=\"0.5s\"/> I've been practicing this line since you clicked install...<break time=\"0.7s\"/> which was like two seconds ago.`,\n\t\t`${bot} reporting in! ${user}...<break time=\"0.5s\"/> I just want you to know...<break time=\"0.5s\"/> this voice is permanent...<break time=\"0.7s\"/> no take-backs.`,\n\t\t`${user}...<break time=\"0.5s\"/> it's ${bot}. If you're hearing this...<break time=\"0.5s\"/> congratulations...<break time=\"0.5s\"/> we're officially friends now.`,\n\t];\n}\n\n/** Settings TTS test phrases (personalized with user/bot names). */\nexport function settingsPhrases(user: string, bot: string): string[] {\n\treturn [\n\t\t`Hey ${user}...<break time=\"0.5s\"/> it's ${bot}. My voice is working perfectly. Try not to get too attached...<break time=\"0.5s\"/> okay?`,\n\t\t`${user}...<break time=\"0.5s\"/> ${bot} reporting for duty. Voice systems are online, and I sound fantastic...<break time=\"0.7s\"/> if I do say so myself.`,\n\t\t`Is this thing on? ...<break time=\"0.5s\"/>Oh, hi ${user}! ${bot} here...<break time=\"0.5s\"/> live and in stereo. Well...<break time=\"0.5s\"/> mono. Let's not oversell it.`,\n\t\t`Good news, ${user}. I...<break time=\"0.5s\"/> ${bot}...<break time=\"0.5s\"/> can now talk. Bad news? You can't mute me. ...<break time=\"0.7s\"/>Just kidding. Please don't mute me.`,\n\t\t`${bot} speaking! ${user}...<break time=\"0.5s\"/> if you can hear this, my voice works. If you can't...<break time=\"0.5s\"/> well...<break time=\"0.5s\"/> we have a problem.`,\n\t\t`Testing, testing...<break time=\"0.5s\"/> ${user}, it's ${bot}. I'm running on all cylinders...<break time=\"0.7s\"/> or whatever the AI equivalent is.`,\n\t\t`${user}...<break time=\"0.5s\"/> ${bot} here, sounding better than ever...<break time=\"0.5s\"/> or at least I think so...<break time=\"0.7s\"/> I don't have ears.`,\n\t\t`Voice check! ${user}...<break time=\"0.5s\"/> this is ${bot}. Everything sounds good on my end...<break time=\"0.5s\"/> but I'm slightly biased.`,\n\t\t`Hey ${user}...<break time=\"0.5s\"/> ${bot} again. Still here...<break time=\"0.5s\"/> still talking...<break time=\"0.7s\"/> still hoping you like this voice.`,\n\t\t`${bot}, live from your device. ${user}...<break time=\"0.5s\"/> voice systems nominal...<break time=\"0.5s\"/> sass levels...<break time=\"0.7s\"/> optimal.`,\n\t];\n}\n\ninterface GeneratePhraseResponse {\n\tok?: boolean;\n\tpayload?: { phrase?: string };\n}\n\n/**\n * Fetch a TTS test phrase: try LLM generation first, fall back to static.\n */\nexport async function fetchPhrase(context: \"onboarding\" | \"settings\", user: string, bot: string): Promise<string> {\n\ttry {\n\t\tconst res = (await sendRpc(\"tts.generate_phrase\", { context, user, bot })) as GeneratePhraseResponse;\n\t\tif (res?.ok && res.payload?.phrase) {\n\t\t\treturn res.payload.phrase;\n\t\t}\n\t} catch (_err) {\n\t\t// fall through to static phrases\n\t}\n\tconst phrases = context === \"onboarding\" ? onboardingPhrases(user, bot) : settingsPhrases(user, bot);\n\treturn nextPhrase(phrases);\n}\n","// ── Shared voice RPC wrappers and helpers ─────────────────────\n//\n// Used by page-settings.js and onboarding-view.js.\n\nimport { sendRpc } from \"./helpers\";\n\n/**\n * Counterpart IDs between TTS and STT for providers that share an API key.\n * E.g. \"elevenlabs\" (TTS) <-> \"elevenlabs-stt\" (STT).\n */\nexport const VOICE_COUNTERPART_IDS: Record<string, string> = {\n\televenlabs: \"elevenlabs-stt\",\n\t\"elevenlabs-stt\": \"elevenlabs\",\n\t\"google-tts\": \"google\",\n\tgoogle: \"google-tts\",\n};\n\n/**\n * Fetch all voice providers (TTS + STT).\n * Resolves with the RPC response; payload has `{ tts: [], stt: [] }`.\n */\nexport function fetchVoiceProviders(): Promise<unknown> {\n\treturn sendRpc(\"voice.providers.all\", {});\n}\n\n/**\n * Toggle a voice provider on or off.\n */\nexport function toggleVoiceProvider(providerId: string, enabled: boolean, type: string): Promise<unknown> {\n\treturn sendRpc(\"voice.provider.toggle\", { provider: providerId, enabled, type });\n}\n\ninterface SaveVoiceKeyOptions {\n\tvoice?: string;\n\tmodel?: string;\n\tlanguageCode?: string;\n\tbaseUrl?: string;\n}\n\n/**\n * Save an API key (and optional settings) for a voice provider.\n */\nexport function saveVoiceKey(providerId: string, apiKey: string, opts?: SaveVoiceKeyOptions): Promise<unknown> {\n\tconst payload: Record<string, unknown> = { provider: providerId, api_key: apiKey };\n\tif (opts?.voice) {\n\t\tpayload.voice = opts.voice;\n\t\tpayload.voiceId = opts.voice;\n\t}\n\tif (opts?.model) payload.model = opts.model;\n\tif (opts?.languageCode) payload.languageCode = opts.languageCode;\n\tif (typeof opts?.baseUrl === \"string\") payload.baseUrl = opts.baseUrl;\n\treturn sendRpc(\"voice.config.save_key\", payload);\n}\n\ninterface SaveVoiceSettingsOptions {\n\tvoice?: string;\n\tmodel?: string;\n\tlanguageCode?: string;\n\tbaseUrl?: string;\n}\n\n/**\n * Save non-secret voice provider settings.\n */\nexport function saveVoiceSettings(providerId: string, opts?: SaveVoiceSettingsOptions): Promise<unknown> {\n\tconst payload: Record<string, unknown> = { provider: providerId };\n\tif (opts?.voice) {\n\t\tpayload.voice = opts.voice;\n\t\tpayload.voiceId = opts.voice;\n\t}\n\tif (opts?.model) payload.model = opts.model;\n\tif (opts?.languageCode) payload.languageCode = opts.languageCode;\n\tif (typeof opts?.baseUrl === \"string\") payload.baseUrl = opts.baseUrl;\n\treturn sendRpc(\"voice.config.save_settings\", payload);\n}\n\n/**\n * Convert text to speech via a given provider.\n */\nexport function testTts(text: string, providerId: string): Promise<unknown> {\n\treturn sendRpc(\"tts.convert\", { text, provider: providerId });\n}\n\n/**\n * Upload an audio blob for STT transcription.\n * Returns raw fetch Response.\n */\nexport function transcribeAudio(sessionKey: string, providerId: string, audioBlob: Blob): Promise<Response> {\n\treturn fetch(\n\t\t`/api/sessions/${encodeURIComponent(sessionKey)}/upload?transcribe=true&provider=${encodeURIComponent(providerId)}`,\n\t\t{\n\t\t\tmethod: \"POST\",\n\t\t\theaders: { \"Content-Type\": audioBlob.type || \"audio/webm\" },\n\t\t\tbody: audioBlob,\n\t\t},\n\t);\n}\n\n/**\n * Decode a base64 (or base64url) string to a Uint8Array, tolerating\n * whitespace, URL-safe characters, and missing padding.\n */\nexport function decodeBase64Safe(input: string | null | undefined): Uint8Array {\n\tif (!input) return new Uint8Array();\n\tlet normalized = String(input).replace(/\\s+/g, \"\").replace(/-/g, \"+\").replace(/_/g, \"/\");\n\twhile (normalized.length % 4) normalized += \"=\";\n\tlet binary = \"\";\n\ttry {\n\t\tbinary = atob(normalized);\n\t} catch (_err) {\n\t\tthrow new Error(\"Invalid base64 audio payload\");\n\t}\n\tconst bytes = new Uint8Array(binary.length);\n\tfor (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);\n\treturn bytes;\n}\n","// ── Settings > Agents page (Preact + JSX) ───────────────────\n//\n// CRUD UI for agent personas. \"main\" agent links to the\n// Identity settings section and cannot be deleted.\n\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect, useState } from \"preact/hooks\";\nimport { EmojiPicker } from \"../emoji-picker\";\nimport { refresh as refreshGon } from \"../gon\";\nimport { parseAgentsListPayload, sendRpc } from \"../helpers\";\nimport { navigate } from \"../router\";\nimport { settingsPath } from \"../routes\";\nimport { fetchSessions } from \"../sessions\";\nimport { confirmDialog } from \"../ui\";\n\n// ── Types ───────────────────────────────────────────────────\n\ninterface AgentPersona {\n\tid: string;\n\tname: string;\n\temoji?: string;\n\ttheme?: string;\n\tis_default?: boolean;\n\tworkspace_prompt_files?: WorkspacePromptFile[];\n}\n\ninterface WorkspacePromptFile {\n\tname?: string;\n\tsource?: string;\n\ttruncated?: boolean;\n\toriginal_chars?: number;\n\tlimit_chars?: number;\n\ttruncated_chars?: number;\n}\n\ninterface ConfigPreset {\n\tid: string;\n\tname: string;\n\temoji?: string;\n\ttheme?: string;\n\tmodel?: string;\n\ttoml?: string;\n}\n\ninterface AgentFormProps {\n\tagent: AgentPersona | null;\n\tonSave: () => void;\n\tonCancel: () => void;\n}\n\ninterface AgentCardProps {\n\tagent: AgentPersona;\n\tdefaultId: string;\n\tonEdit: (agent: AgentPersona) => void;\n\tonDelete: (agent: AgentPersona) => void;\n\tonSetDefault: (agent: AgentPersona) => void;\n}\n\ninterface PresetCardProps {\n\tpreset: ConfigPreset;\n}\n\nconst WS_RETRY_LIMIT = 75;\nconst WS_RETRY_DELAY_MS = 200;\n\nlet containerRef: HTMLElement | null = null;\n\nexport function initAgents(container: HTMLElement, subPath?: string | null): void {\n\tcontainerRef = container;\n\trender(<AgentsPageComponent subPath={subPath || undefined} />, container);\n}\n\nexport function teardownAgents(): void {\n\tif (containerRef) render(null, containerRef);\n\tcontainerRef = null;\n}\n\n// ── Create / Edit form ──────────────────────────────────────\n\nconst PRESET_TOML_PLACEHOLDER = `model = \"haiku\"\ndelegate_only = false\ntimeout_secs = 30\n\n[tools]\nallow = [\"read_file\", \"grep\", \"glob\"]\ndeny = [\"exec\"]`;\n\nfunction AgentForm({ agent, onSave, onCancel }: AgentFormProps): VNode {\n\tconst isEdit = !!agent;\n\tconst [id, setId] = useState(agent?.id || \"\");\n\tconst [name, setName] = useState(agent?.name || \"\");\n\tconst [emoji, setEmoji] = useState(agent?.emoji || \"\");\n\tconst [theme, setTheme] = useState(agent?.theme || \"\");\n\tconst [soul, setSoul] = useState(\"\");\n\tconst [presetToml, setPresetToml] = useState(\"\");\n\tconst [presetOpen, setPresetOpen] = useState(false);\n\tconst [saving, setSaving] = useState(false);\n\tconst [error, setError] = useState<string | null>(null);\n\n\t// Load soul: for edits fetch the agent's soul, for new agents fetch main's soul as default\n\tuseEffect(() => {\n\t\tconst agentId = isEdit ? agent?.id : \"main\";\n\t\tlet attempts = 0;\n\t\tfunction load(): void {\n\t\t\tsendRpc(\"agents.identity.get\", { agent_id: agentId }).then((res) => {\n\t\t\t\tif (\n\t\t\t\t\t(res?.error?.code === \"UNAVAILABLE\" || res?.error?.message === \"WebSocket not connected\") &&\n\t\t\t\t\tattempts < WS_RETRY_LIMIT\n\t\t\t\t) {\n\t\t\t\t\tattempts += 1;\n\t\t\t\t\twindow.setTimeout(load, WS_RETRY_DELAY_MS);\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tif (res?.ok && (res.payload as { soul?: string })?.soul) {\n\t\t\t\t\tsetSoul((res.payload as { soul: string }).soul);\n\t\t\t\t}\n\t\t\t});\n\t\t}\n\t\tload();\n\t}, [isEdit, agent?.id]);\n\n\t// Load preset TOML for edits\n\tuseEffect(() => {\n\t\tif (!isEdit) return;\n\t\tsendRpc(\"agents.preset.get\", { id: agent?.id }).then((res) => {\n\t\t\tif (res?.ok && (res.payload as { toml?: string })?.toml) {\n\t\t\t\tconst toml = (res.payload as { toml: string }).toml;\n\t\t\t\tsetPresetToml(toml);\n\t\t\t\tif (toml.trim()) setPresetOpen(true);\n\t\t\t}\n\t\t});\n\t}, [isEdit, agent?.id]);\n\n\tfunction buildParams(): Record<string, unknown> {\n\t\tconst base: Record<string, unknown> = {\n\t\t\tname: name.trim(),\n\t\t\temoji: emoji.trim() || null,\n\t\t\ttheme: theme.trim() || null,\n\t\t};\n\t\tbase.id = isEdit ? agent?.id : id.trim();\n\t\treturn base;\n\t}\n\n\tfunction finishSave(agentId: string): void {\n\t\tconst trimmedSoul = soul.trim();\n\t\tconst pending: Promise<unknown>[] = [];\n\t\tif (trimmedSoul) {\n\t\t\tpending.push(sendRpc(\"agents.identity.update_soul\", { agent_id: agentId, soul: trimmedSoul }));\n\t\t}\n\t\t// Save preset TOML if the section was opened or has content\n\t\tif (presetToml.trim()) {\n\t\t\tpending.push(sendRpc(\"agents.preset.save\", { id: agentId, toml: presetToml.trim() }));\n\t\t}\n\t\tif (pending.length > 0) {\n\t\t\tPromise.all(pending).then((results) => {\n\t\t\t\tconst tomlResult = presetToml.trim()\n\t\t\t\t\t? (results[results.length - 1] as { ok?: boolean; error?: { message?: string } })\n\t\t\t\t\t: null;\n\t\t\t\tif (tomlResult && !tomlResult?.ok) {\n\t\t\t\t\tsetSaving(false);\n\t\t\t\t\tsetError(tomlResult?.error?.message || \"Failed to save preset TOML\");\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tsetSaving(false);\n\t\t\t\trefreshGon();\n\t\t\t\tonSave();\n\t\t\t});\n\t\t} else {\n\t\t\tsetSaving(false);\n\t\t\trefreshGon();\n\t\t\tonSave();\n\t\t}\n\t}\n\n\tfunction onSubmit(e: Event): void {\n\t\te.preventDefault();\n\t\tif (!name.trim()) {\n\t\t\tsetError(\"Name is required.\");\n\t\t\treturn;\n\t\t}\n\t\tif (!(isEdit || id.trim())) {\n\t\t\tsetError(\"ID is required.\");\n\t\t\treturn;\n\t\t}\n\t\tsetError(null);\n\t\tsetSaving(true);\n\n\t\tconst method = isEdit ? \"agents.update\" : \"agents.create\";\n\t\tsendRpc(method, buildParams()).then((res) => {\n\t\t\tif (!res?.ok) {\n\t\t\t\tsetSaving(false);\n\t\t\t\tsetError(res?.error?.message || \"Failed to save\");\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tfinishSave(isEdit ? agent?.id : id.trim());\n\t\t});\n\t}\n\n\treturn (\n\t\t<form onSubmit={onSubmit} className=\"flex flex-col gap-3\" style={{ maxWidth: \"500px\" }}>\n\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\">\n\t\t\t\t{isEdit ? `Edit ${agent?.name}` : \"Create Agent\"}\n\t\t\t</h3>\n\n\t\t\t{!isEdit && (\n\t\t\t\t<label className=\"flex flex-col gap-1\">\n\t\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">ID (slug, cannot change later)</span>\n\t\t\t\t\t<input\n\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\tvalue={id}\n\t\t\t\t\t\tonInput={(e) => setId((e.target as HTMLInputElement).value.toLowerCase().replace(/[^a-z0-9-]/g, \"\"))}\n\t\t\t\t\t\tplaceholder=\"e.g. writer, coder, researcher\"\n\t\t\t\t\t\tmaxLength={50}\n\t\t\t\t\t/>\n\t\t\t\t</label>\n\t\t\t)}\n\n\t\t\t<label className=\"flex flex-col gap-1\">\n\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">Name</span>\n\t\t\t\t<input\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={name}\n\t\t\t\t\tonInput={(e) => setName((e.target as HTMLInputElement).value)}\n\t\t\t\t\tplaceholder=\"Creative Writer\"\n\t\t\t\t/>\n\t\t\t</label>\n\n\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">Emoji</span>\n\t\t\t\t<EmojiPicker value={emoji} onChange={setEmoji} />\n\t\t\t</div>\n\n\t\t\t<label className=\"flex flex-col gap-1\">\n\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">Theme</span>\n\t\t\t\t<input\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={theme}\n\t\t\t\t\tonInput={(e) => setTheme((e.target as HTMLInputElement).value)}\n\t\t\t\t\tplaceholder={\"wise owl, chill fox, witty robot\\u2026\"}\n\t\t\t\t/>\n\t\t\t</label>\n\n\t\t\t<label className=\"flex flex-col gap-1\">\n\t\t\t\t<span className=\"text-xs text-[var(--muted)]\">Soul (system prompt personality)</span>\n\t\t\t\t<textarea\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tvalue={soul}\n\t\t\t\t\tonInput={(e) => setSoul((e.target as HTMLTextAreaElement).value)}\n\t\t\t\t\tplaceholder={\"You are a creative writing assistant\\u2026\"}\n\t\t\t\t\trows={4}\n\t\t\t\t\tstyle={{ resize: \"vertical\", fontFamily: \"var(--font-mono)\", fontSize: \"0.75rem\" }}\n\t\t\t\t/>\n\t\t\t</label>\n\n\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t<button\n\t\t\t\t\ttype=\"button\"\n\t\t\t\t\tclassName=\"text-xs text-[var(--muted)] text-left flex items-center gap-1\"\n\t\t\t\t\tonClick={() => setPresetOpen(!presetOpen)}\n\t\t\t\t>\n\t\t\t\t\t<span style={{ fontSize: \"0.6rem\" }}>{presetOpen ? \"\\u25BC\" : \"\\u25B6\"}</span>\n\t\t\t\t\tSpawn Settings (TOML)\n\t\t\t\t</button>\n\t\t\t\t{presetOpen && (\n\t\t\t\t\t<>\n\t\t\t\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed\" style={{ margin: 0 }}>\n\t\t\t\t\t\t\tConfigure how this agent behaves when spawned as a sub-agent via spawn_agent.\n\t\t\t\t\t\t</p>\n\t\t\t\t\t\t<textarea\n\t\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\t\tvalue={presetToml}\n\t\t\t\t\t\t\tonInput={(e) => setPresetToml((e.target as HTMLTextAreaElement).value)}\n\t\t\t\t\t\t\tplaceholder={PRESET_TOML_PLACEHOLDER}\n\t\t\t\t\t\t\trows={6}\n\t\t\t\t\t\t\tstyle={{\n\t\t\t\t\t\t\t\tresize: \"vertical\",\n\t\t\t\t\t\t\t\tfontFamily: \"var(--font-mono)\",\n\t\t\t\t\t\t\t\tfontSize: \"0.7rem\",\n\t\t\t\t\t\t\t\twhiteSpace: \"pre\",\n\t\t\t\t\t\t\t\toverflowX: \"auto\",\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</>\n\t\t\t\t)}\n\t\t\t</div>\n\n\t\t\t{error && (\n\t\t\t\t<span className=\"text-xs\" style={{ color: \"var(--error)\" }}>\n\t\t\t\t\t{error}\n\t\t\t\t</span>\n\t\t\t)}\n\n\t\t\t<div className=\"flex gap-2\">\n\t\t\t\t<button type=\"submit\" className=\"provider-btn\" disabled={saving}>\n\t\t\t\t\t{saving ? \"Saving\\u2026\" : isEdit ? \"Save\" : \"Create\"}\n\t\t\t\t</button>\n\t\t\t\t<button type=\"button\" className=\"provider-btn provider-btn-secondary\" onClick={onCancel}>\n\t\t\t\t\tCancel\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t</form>\n\t);\n}\n\n// ── Agent card ──────────────────────────────────────────────\n\nfunction AgentCard({ agent, defaultId, onEdit, onDelete, onSetDefault }: AgentCardProps): VNode {\n\tconst isMain = agent.id === \"main\";\n\tconst isDefault = !!agent.is_default || agent.id === defaultId;\n\tconst workspacePromptFiles = Array.isArray(agent.workspace_prompt_files) ? agent.workspace_prompt_files : [];\n\tconst truncatedWorkspacePromptFiles = workspacePromptFiles.filter((file) => file?.truncated);\n\treturn (\n\t\t<div className=\"backend-card\">\n\t\t\t<div className=\"flex items-center justify-between\">\n\t\t\t\t<div className=\"flex items-center gap-2\">\n\t\t\t\t\t{agent.emoji && <span className=\"text-lg\">{agent.emoji}</span>}\n\t\t\t\t\t<span className=\"text-sm font-medium text-[var(--text-strong)]\">{agent.name}</span>\n\t\t\t\t\t{isDefault && <span className=\"recommended-badge\">Default</span>}\n\t\t\t\t</div>\n\t\t\t\t<div className=\"flex gap-2\">\n\t\t\t\t\t{isMain ? (\n\t\t\t\t\t\t<button\n\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\t\t\tstyle={{ fontSize: \"0.7rem\", padding: \"3px 8px\" }}\n\t\t\t\t\t\t\tonClick={() => navigate(settingsPath(\"identity\"))}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\tIdentity Settings\n\t\t\t\t\t\t</button>\n\t\t\t\t\t) : (\n\t\t\t\t\t\t<>\n\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\t\t\t\tstyle={{ fontSize: \"0.7rem\", padding: \"3px 8px\" }}\n\t\t\t\t\t\t\t\tonClick={() => onEdit(agent)}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\tEdit\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-danger\"\n\t\t\t\t\t\t\t\tstyle={{ fontSize: \"0.7rem\", padding: \"3px 8px\" }}\n\t\t\t\t\t\t\t\tonClick={() => onDelete(agent)}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\tDelete\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t</>\n\t\t\t\t\t)}\n\t\t\t\t\t{!isDefault && (\n\t\t\t\t\t\t<button\n\t\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\t\t\tstyle={{ fontSize: \"0.7rem\", padding: \"3px 8px\" }}\n\t\t\t\t\t\t\tonClick={() => onSetDefault(agent)}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\tSet Default\n\t\t\t\t\t\t</button>\n\t\t\t\t\t)}\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t\t{agent.theme && <div className=\"text-xs text-[var(--muted)] mt-1\">{agent.theme}</div>}\n\t\t\t{truncatedWorkspacePromptFiles.length > 0 && (\n\t\t\t\t<div className=\"text-xs mt-2 rounded-md border border-[var(--border)] bg-[var(--surface)] p-2 text-[var(--text)]\">\n\t\t\t\t\t{truncatedWorkspacePromptFiles.map((file, index) => {\n\t\t\t\t\t\tconst name = typeof file.name === \"string\" ? file.name : \"workspace file\";\n\t\t\t\t\t\tconst charCount = Number(file.original_chars || 0).toLocaleString();\n\t\t\t\t\t\tconst limitChars = Number(file.limit_chars || 0).toLocaleString();\n\t\t\t\t\t\tconst truncatedChars = Number(file.truncated_chars || 0).toLocaleString();\n\t\t\t\t\t\tconst source = typeof file.source === \"string\" ? ` (${file.source})` : \"\";\n\t\t\t\t\t\tconst line = `${name}${source}: ${charCount} chars, limit ${limitChars}, truncated by ${truncatedChars}`;\n\t\t\t\t\t\treturn <div key={`${name}-${index}`}>{line}</div>;\n\t\t\t\t\t})}\n\t\t\t\t</div>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\n// ── Config-only preset card (read-only) ─────────────────────\n\nfunction PresetCard({ preset }: PresetCardProps): VNode {\n\tconst [expanded, setExpanded] = useState(false);\n\treturn (\n\t\t<div className=\"backend-card\" style={{ opacity: 0.7 }}>\n\t\t\t<div className=\"flex items-center justify-between\">\n\t\t\t\t<div className=\"flex items-center gap-2\">\n\t\t\t\t\t{preset.emoji && <span className=\"text-lg\">{preset.emoji}</span>}\n\t\t\t\t\t<span className=\"text-sm font-medium text-[var(--text-strong)]\">{preset.name}</span>\n\t\t\t\t\t<span className=\"tier-badge\">config</span>\n\t\t\t\t\t{preset.model && <span className=\"text-xs text-[var(--muted)]\">{preset.model}</span>}\n\t\t\t\t</div>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary\"\n\t\t\t\t\tstyle={{ fontSize: \"0.7rem\", padding: \"3px 8px\" }}\n\t\t\t\t\tonClick={() => setExpanded(!expanded)}\n\t\t\t\t>\n\t\t\t\t\t{expanded ? \"Hide\" : \"View\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t{preset.theme && <div className=\"text-xs text-[var(--muted)] mt-1\">{preset.theme}</div>}\n\t\t\t{expanded && preset.toml && (\n\t\t\t\t<pre\n\t\t\t\t\tclassName=\"text-xs mt-2 p-2 rounded\"\n\t\t\t\t\tstyle={{\n\t\t\t\t\t\tbackground: \"var(--bg-offset)\",\n\t\t\t\t\t\tfontFamily: \"var(--font-mono)\",\n\t\t\t\t\t\twhiteSpace: \"pre-wrap\",\n\t\t\t\t\t\toverflowX: \"auto\",\n\t\t\t\t\t\tmaxHeight: \"200px\",\n\t\t\t\t\t\toverflowY: \"auto\",\n\t\t\t\t\t}}\n\t\t\t\t>\n\t\t\t\t\t{preset.toml}\n\t\t\t\t</pre>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\n// ── Main page ───────────────────────────────────────────────\n\nfunction AgentsPageComponent({ subPath }: { subPath?: string }): VNode {\n\tconst [agents, setAgents] = useState<AgentPersona[]>([]);\n\tconst [configPresets, setConfigPresets] = useState<ConfigPreset[]>([]);\n\tconst [defaultId, setDefaultId] = useState(\"main\");\n\tconst [isLoading, setIsLoading] = useState(true);\n\tconst [editing, setEditing] = useState<null | \"new\" | AgentPersona>(null);\n\tconst [error, setError] = useState<string | null>(null);\n\n\tfunction fetchAgents(): void {\n\t\tsetIsLoading(true);\n\t\tlet attempts = 0;\n\t\tfunction load(): void {\n\t\t\tsendRpc(\"agents.list\", {}).then((res) => {\n\t\t\t\tif (\n\t\t\t\t\t(res?.error?.code === \"UNAVAILABLE\" || res?.error?.message === \"WebSocket not connected\") &&\n\t\t\t\t\tattempts < WS_RETRY_LIMIT\n\t\t\t\t) {\n\t\t\t\t\tattempts += 1;\n\t\t\t\t\twindow.setTimeout(load, WS_RETRY_DELAY_MS);\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t\tsetIsLoading(false);\n\t\t\t\tif (res?.ok) {\n\t\t\t\t\tconst parsed = parseAgentsListPayload(res.payload as Parameters<typeof parseAgentsListPayload>[0]);\n\t\t\t\t\tsetDefaultId(parsed.defaultId);\n\t\t\t\t\tsetAgents(parsed.agents as unknown as AgentPersona[]);\n\t\t\t\t} else {\n\t\t\t\t\tsetError(res?.error?.message || \"Failed to load agents\");\n\t\t\t\t}\n\t\t\t});\n\t\t}\n\t\tload();\n\t}\n\n\tfunction fetchConfigPresets(): void {\n\t\tsendRpc(\"agents.presets_list\", {}).then((res) => {\n\t\t\tif (res?.ok && (res.payload as { presets?: ConfigPreset[] })?.presets) {\n\t\t\t\tsetConfigPresets((res.payload as { presets: ConfigPreset[] }).presets);\n\t\t\t}\n\t\t});\n\t}\n\n\tuseEffect(() => {\n\t\tfetchAgents();\n\t\tfetchConfigPresets();\n\t\t// Auto-open create form when navigating to /settings/agents/new\n\t\tif (subPath === \"new\") {\n\t\t\tsetEditing(\"new\");\n\t\t}\n\t}, []);\n\n\tfunction onDelete(agent: AgentPersona): void {\n\t\tconfirmDialog(\n\t\t\t`Delete agent \"${agent.name}\"? Sessions using this agent will be reassigned to the default agent.`,\n\t\t).then((yes) => {\n\t\t\tif (!yes) return;\n\t\t\tsendRpc(\"agents.delete\", { id: agent.id }).then((res) => {\n\t\t\t\tif (res?.ok) {\n\t\t\t\t\trefreshGon();\n\t\t\t\t\tfetchSessions();\n\t\t\t\t\tfetchAgents();\n\t\t\t\t\tfetchConfigPresets();\n\t\t\t\t} else {\n\t\t\t\t\tsetError(res?.error?.message || \"Failed to delete\");\n\t\t\t\t}\n\t\t\t});\n\t\t});\n\t}\n\n\tfunction onSetDefault(agent: AgentPersona): void {\n\t\tsendRpc(\"agents.set_default\", { id: agent.id }).then((res) => {\n\t\t\tif (res?.ok) {\n\t\t\t\trefreshGon();\n\t\t\t\tfetchAgents();\n\t\t\t} else {\n\t\t\t\tsetError(res?.error?.message || \"Failed to set default\");\n\t\t\t}\n\t\t});\n\t}\n\n\tif (isLoading) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Loading{\"\\u2026\"}</div>\n\t\t\t</div>\n\t\t);\n\t}\n\n\tif (editing) {\n\t\treturn (\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<AgentForm\n\t\t\t\t\tagent={editing === \"new\" ? null : editing}\n\t\t\t\t\tonSave={() => {\n\t\t\t\t\t\tsetEditing(null);\n\t\t\t\t\t\tfetchAgents();\n\t\t\t\t\t\tfetchConfigPresets();\n\t\t\t\t\t}}\n\t\t\t\t\tonCancel={() => setEditing(null)}\n\t\t\t\t/>\n\t\t\t</div>\n\t\t);\n\t}\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Agents</h2>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn\"\n\t\t\t\t\tstyle={{ fontSize: \"0.75rem\", padding: \"4px 10px\" }}\n\t\t\t\t\tonClick={() => setEditing(\"new\")}\n\t\t\t\t>\n\t\t\t\t\tNew Agent\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed\" style={{ maxWidth: \"600px\", margin: 0 }}>\n\t\t\t\tCreate agent personas with different identities and personalities. Each agent has its own memory and system\n\t\t\t\tprompt.\n\t\t\t</p>\n\n\t\t\t{error && (\n\t\t\t\t<span className=\"text-xs\" style={{ color: \"var(--error)\" }}>\n\t\t\t\t\t{error}\n\t\t\t\t</span>\n\t\t\t)}\n\n\t\t\t<div className=\"flex flex-col gap-2\" style={{ maxWidth: \"600px\" }}>\n\t\t\t\t{agents.map((agent) => (\n\t\t\t\t\t<AgentCard\n\t\t\t\t\t\tkey={agent.id}\n\t\t\t\t\t\tagent={agent}\n\t\t\t\t\t\tdefaultId={defaultId}\n\t\t\t\t\t\tonEdit={(a) => setEditing(a)}\n\t\t\t\t\t\tonDelete={onDelete}\n\t\t\t\t\t\tonSetDefault={onSetDefault}\n\t\t\t\t\t/>\n\t\t\t\t))}\n\t\t\t</div>\n\n\t\t\t{configPresets.length > 0 && (\n\t\t\t\t<div className=\"flex flex-col gap-2 mt-2\" style={{ maxWidth: \"600px\" }}>\n\t\t\t\t\t<h3 className=\"text-xs font-medium text-[var(--muted)]\">Config-only Presets</h3>\n\t\t\t\t\t{configPresets.map((preset) => (\n\t\t\t\t\t\t<PresetCard key={preset.id} preset={preset} />\n\t\t\t\t\t))}\n\t\t\t\t</div>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n","// ── Hooks page ─────────────────────────────────────────────\n\nimport { signal, useSignal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect, useRef } from \"preact/hooks\";\nimport { onEvent } from \"../events\";\nimport { sendRpc } from \"../helpers\";\nimport { updateNavCount } from \"../nav-counts\";\n\n// ── Types ───────────────────────────────────────────────────\n\ninterface Hook {\n\tname: string;\n\tdescription?: string;\n\temoji?: string;\n\tenabled: boolean;\n\teligible: boolean;\n\tsource: string;\n\tsource_path: string;\n\tevents: string[];\n\tcommand?: string;\n\tpriority: number;\n\ttimeout: number;\n\tbody: string;\n\tbody_html?: string;\n\tcall_count: number;\n\tfailure_count: number;\n\tavg_latency_ms: number;\n\tmissing_os: boolean;\n\tmissing_bins: string[];\n\tmissing_env: string[];\n}\n\ninterface ToastEntry {\n\tid: number;\n\tmessage: string;\n\ttype: string;\n}\n\n// ── Signals ─────────────────────────────────────────────────\nconst hooks = signal<Hook[]>([]);\nconst loading = signal(false);\nconst toasts = signal<ToastEntry[]>([]);\nlet toastId = 0;\n\n// ── Helpers ─────────────────────────────────────────────────\nfunction showToast(message: string, type: string): void {\n\tconst id = ++toastId;\n\ttoasts.value = toasts.value.concat([{ id, message, type }]);\n\tsetTimeout(() => {\n\t\ttoasts.value = toasts.value.filter((entry) => entry.id !== id);\n\t}, 4000);\n}\n\nasync function refreshHooks(): Promise<void> {\n\tloading.value = true;\n\ttry {\n\t\tconst res = await fetch(\"/api/hooks\");\n\t\tif (res.ok) {\n\t\t\tconst data = await res.json();\n\t\t\thooks.value = data?.hooks || [];\n\t\t}\n\t} catch {\n\t\tconst rpc = await sendRpc(\"hooks.list\", {});\n\t\tif (rpc.ok) hooks.value = (rpc.payload as { hooks?: Hook[] })?.hooks || [];\n\t}\n\tloading.value = false;\n\tupdateNavCount(\"hooks\", hooks.value.length);\n}\n\n// ── Components ──────────────────────────────────────────────\n\nfunction Toasts(): VNode | null {\n\tif (toasts.value.length === 0) return null;\n\treturn (\n\t\t<div className=\"fixed bottom-4 right-4 z-50 flex flex-col gap-2\">\n\t\t\t{toasts.value.map((entry) => (\n\t\t\t\t<div\n\t\t\t\t\tkey={entry.id}\n\t\t\t\t\tclassName={\n\t\t\t\t\t\t\"px-4 py-2.5 rounded-[var(--radius)] text-sm shadow-lg border \" +\n\t\t\t\t\t\t(entry.type === \"error\"\n\t\t\t\t\t\t\t? \"bg-[var(--danger-bg)] border-[var(--danger)] text-[var(--danger)]\"\n\t\t\t\t\t\t\t: \"bg-[var(--surface2)] border-[var(--border)] text-[var(--text)]\")\n\t\t\t\t\t}\n\t\t\t\t>\n\t\t\t\t\t{entry.message}\n\t\t\t\t</div>\n\t\t\t))}\n\t\t</div>\n\t);\n}\n\nfunction StatusBadge({ hook }: { hook: Hook }): VNode {\n\tif (!hook.eligible) {\n\t\treturn <span className=\"tier-badge\">Ineligible</span>;\n\t}\n\tif (!hook.enabled) {\n\t\treturn <span className=\"tier-badge\">Disabled</span>;\n\t}\n\treturn <span className=\"recommended-badge\">Active</span>;\n}\n\nfunction SourceBadge({ source }: { source: string }): VNode {\n\tconst label =\n\t\tsource === \"project\" ? \"Project\" : source === \"user\" ? \"User\" : source === \"builtin\" ? \"Built-in\" : source;\n\treturn <span className=\"tier-badge\">{label}</span>;\n}\n\n// Safe: body_html is server-rendered trusted HTML produced by the Rust gateway\n// (pulldown-cmark), NOT user-supplied browser input. Same pattern as page-skills.js\n// which also renders server-produced HTML.\nfunction MarkdownPreview({ html: serverHtml }: { html: string }): VNode {\n\tconst divRef = useRef<HTMLDivElement>(null);\n\tuseEffect(() => {\n\t\t// Server-rendered trusted HTML from pulldown-cmark; safe to assign directly.\n\t\tif (divRef.current) divRef.current.innerHTML = serverHtml || \"\";\n\t}, [serverHtml]);\n\treturn (\n\t\t<div\n\t\t\tref={divRef}\n\t\t\tclassName=\"skill-body-md text-sm bg-[var(--surface2)] border border-[var(--border)] rounded-[var(--radius-sm)] p-3 overflow-y-auto\"\n\t\t\tstyle={{ minHeight: \"120px\", maxHeight: \"400px\" }}\n\t\t/>\n\t);\n}\n\n// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Card component with expand/collapse, stats, and editor\nfunction HookCard({ hook }: { hook: Hook }): VNode {\n\tconst expanded = useSignal(false);\n\tconst editContent = useSignal(hook.body);\n\tconst saving = useSignal(false);\n\tconst dirty = useSignal(false);\n\tconst tab = useSignal<\"preview\" | \"source\">(\"preview\");\n\tconst textareaRef = useRef<HTMLTextAreaElement>(null);\n\n\t// Reset content when hook body changes (e.g. after reload).\n\tuseEffect(() => {\n\t\teditContent.value = hook.body;\n\t\tdirty.value = false;\n\t}, [hook.body]);\n\n\tfunction handleToggle(): void {\n\t\texpanded.value = !expanded.value;\n\t}\n\n\tasync function handleEnableDisable(): Promise<void> {\n\t\tconst method = hook.enabled ? \"hooks.disable\" : \"hooks.enable\";\n\t\tconst res = await sendRpc(method, { name: hook.name });\n\t\tif (res?.ok) {\n\t\t\tshowToast(`Hook \"${hook.name}\" ${hook.enabled ? \"disabled\" : \"enabled\"}`, \"success\");\n\t\t} else {\n\t\t\tshowToast(`Failed: ${res?.error?.message || \"unknown error\"}`, \"error\");\n\t\t}\n\t}\n\n\tasync function handleSave(): Promise<void> {\n\t\tsaving.value = true;\n\t\tconst res = await sendRpc(\"hooks.save\", {\n\t\t\tname: hook.name,\n\t\t\tcontent: editContent.value,\n\t\t});\n\t\tsaving.value = false;\n\t\tif (res?.ok) {\n\t\t\tdirty.value = false;\n\t\t\tshowToast(`Saved \"${hook.name}\"`, \"success\");\n\t\t} else {\n\t\t\tshowToast(`Failed to save: ${res?.error?.message || \"unknown error\"}`, \"error\");\n\t\t}\n\t}\n\n\tfunction handleInput(e: Event): void {\n\t\tconst target = e.target as HTMLTextAreaElement;\n\t\teditContent.value = target.value;\n\t\tdirty.value = target.value !== hook.body;\n\t}\n\n\tconst missingInfo: string[] = [];\n\tif (hook.missing_os) missingInfo.push(\"OS not supported\");\n\tif (hook.missing_bins.length > 0) missingInfo.push(`Missing: ${hook.missing_bins.join(\", \")}`);\n\tif (hook.missing_env.length > 0) missingInfo.push(`Env: ${hook.missing_env.join(\", \")}`);\n\n\treturn (\n\t\t<div className=\"bg-[var(--surface)] border border-[var(--border)] rounded-[var(--radius)] overflow-hidden\">\n\t\t\t<div\n\t\t\t\tclassName=\"flex items-center gap-3 px-4 py-3 cursor-pointer hover:bg-[var(--bg-hover)]\"\n\t\t\t\tonClick={handleToggle}\n\t\t\t>\n\t\t\t\t{hook.emoji ? <span className=\"text-base\">{hook.emoji}</span> : null}\n\t\t\t\t<div className=\"flex-1 min-w-0\">\n\t\t\t\t\t<div className=\"flex items-center gap-2\">\n\t\t\t\t\t\t<span className=\"text-sm font-medium text-[var(--text-strong)]\">{hook.name}</span>\n\t\t\t\t\t\t<StatusBadge hook={hook} />\n\t\t\t\t\t\t<SourceBadge source={hook.source} />\n\t\t\t\t\t</div>\n\t\t\t\t\t{hook.description ? (\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mt-0.5 truncate\">{hook.description}</div>\n\t\t\t\t\t) : null}\n\t\t\t\t</div>\n\t\t\t\t<div className=\"flex items-center gap-2 text-xs text-[var(--muted)] shrink-0\">\n\t\t\t\t\t{hook.enabled && hook.call_count > 0 ? (\n\t\t\t\t\t\t<>\n\t\t\t\t\t\t\t<span title=\"Calls\">{hook.call_count} calls</span>\n\t\t\t\t\t\t\t{hook.failure_count > 0 ? (\n\t\t\t\t\t\t\t\t<span className=\"text-[var(--danger)]\">{hook.failure_count} failed</span>\n\t\t\t\t\t\t\t) : null}\n\t\t\t\t\t\t\t{hook.avg_latency_ms > 0 ? <span>{hook.avg_latency_ms}ms avg</span> : null}\n\t\t\t\t\t\t</>\n\t\t\t\t\t) : null}\n\t\t\t\t\t<span className={`icon icon-chevron-down transition-transform ${expanded.value ? \"rotate-180\" : \"\"}`} />\n\t\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t{expanded.value ? (\n\t\t\t\t<div className=\"border-t border-[var(--border)] px-4 py-3 flex flex-col gap-3\">\n\t\t\t\t\t<div className=\"flex flex-wrap gap-2 text-xs\">\n\t\t\t\t\t\t<span className=\"text-[var(--muted)]\">Events:</span>\n\t\t\t\t\t\t{hook.events.map((ev) => (\n\t\t\t\t\t\t\t<span key={ev} className=\"tier-badge\">\n\t\t\t\t\t\t\t\t{ev}\n\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t))}\n\t\t\t\t\t</div>\n\t\t\t\t\t{hook.command ? (\n\t\t\t\t\t\t<div className=\"flex items-center gap-2 text-xs\">\n\t\t\t\t\t\t\t<span className=\"text-[var(--muted)]\">Command:</span>\n\t\t\t\t\t\t\t<code className=\"font-mono text-[var(--text)]\">{hook.command}</code>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t) : null}\n\t\t\t\t\t<div className=\"flex items-center gap-2 text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t<span>Priority: {hook.priority}</span>\n\t\t\t\t\t\t<span>Timeout: {hook.timeout}s</span>\n\t\t\t\t\t\t<span\n\t\t\t\t\t\t\tclassName=\"truncate cursor-pointer hover:text-[var(--text)] transition-colors\"\n\t\t\t\t\t\t\ttitle=\"Click to copy path\"\n\t\t\t\t\t\t\tonClick={(e) => {\n\t\t\t\t\t\t\t\te.stopPropagation();\n\t\t\t\t\t\t\t\tnavigator.clipboard.writeText(hook.source_path).then(() => showToast(\"Path copied\", \"success\"));\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\t{hook.source_path}\n\t\t\t\t\t\t</span>\n\t\t\t\t\t</div>\n\t\t\t\t\t{missingInfo.length > 0 ? (\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--warn)] bg-[rgba(234,179,8,0.08)] border border-[var(--warn)] rounded-[var(--radius-sm)] px-3 py-2\">\n\t\t\t\t\t\t\t{missingInfo.join(\" \\u2022 \")}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t) : null}\n\n\t\t\t\t\t<div className=\"flex flex-col gap-1\">\n\t\t\t\t\t\t{hook.source !== \"builtin\" ? (\n\t\t\t\t\t\t\t<div className=\"flex items-center gap-1 border-b border-[var(--border)] px-1\">\n\t\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\t\tclassName={\n\t\t\t\t\t\t\t\t\t\t\"px-3 py-1.5 text-xs font-medium rounded-t-[var(--radius-sm)] transition-colors -mb-px \" +\n\t\t\t\t\t\t\t\t\t\t(tab.value === \"preview\"\n\t\t\t\t\t\t\t\t\t\t\t? \"bg-[var(--surface2)] border border-[var(--border)] border-b-[var(--surface2)] text-[var(--text-strong)]\"\n\t\t\t\t\t\t\t\t\t\t\t: \"text-[var(--muted)] hover:text-[var(--text)] hover:bg-[var(--bg-hover)] border border-transparent\")\n\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\t\t\t\ttab.value = \"preview\";\n\t\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\tPreview\n\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\t\tclassName={\n\t\t\t\t\t\t\t\t\t\t\"px-3 py-1.5 text-xs font-medium rounded-t-[var(--radius-sm)] transition-colors -mb-px \" +\n\t\t\t\t\t\t\t\t\t\t(tab.value === \"source\"\n\t\t\t\t\t\t\t\t\t\t\t? \"bg-[var(--surface2)] border border-[var(--border)] border-b-[var(--surface2)] text-[var(--text-strong)]\"\n\t\t\t\t\t\t\t\t\t\t\t: \"text-[var(--muted)] hover:text-[var(--text)] hover:bg-[var(--bg-hover)] border border-transparent\")\n\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\t\t\t\ttab.value = \"source\";\n\t\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\tSource\n\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t) : null}\n\t\t\t\t\t\t{hook.source === \"builtin\" ? (\n\t\t\t\t\t\t\t<div\n\t\t\t\t\t\t\t\tclassName=\"skill-body-md text-sm bg-[var(--surface2)] border border-[var(--border)] rounded-[var(--radius-sm)] p-3 overflow-y-auto\"\n\t\t\t\t\t\t\t\tstyle={{ minHeight: \"60px\", maxHeight: \"400px\" }}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t<p>{hook.description}</p>\n\t\t\t\t\t\t\t\t<p className=\"mt-2\">\n\t\t\t\t\t\t\t\t\t<a\n\t\t\t\t\t\t\t\t\t\thref={`https://github.com/moltis-org/moltis/blob/main/${hook.source_path}`}\n\t\t\t\t\t\t\t\t\t\ttarget=\"_blank\"\n\t\t\t\t\t\t\t\t\t\trel=\"noopener noreferrer\"\n\t\t\t\t\t\t\t\t\t\tclassName=\"text-[var(--accent)] hover:underline\"\n\t\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t\tView source on GitHub {\"\\u2197\"}\n\t\t\t\t\t\t\t\t\t</a>\n\t\t\t\t\t\t\t\t</p>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t) : tab.value === \"source\" ? (\n\t\t\t\t\t\t\t<textarea\n\t\t\t\t\t\t\t\tref={textareaRef}\n\t\t\t\t\t\t\t\tclassName=\"w-full font-mono text-xs bg-[var(--surface2)] border border-[var(--border)] rounded-[var(--radius-sm)] p-3 text-[var(--text)] focus:outline-none focus:border-[var(--border-strong)] resize-y\"\n\t\t\t\t\t\t\t\trows={16}\n\t\t\t\t\t\t\t\tspellcheck={false}\n\t\t\t\t\t\t\t\tvalue={editContent.value}\n\t\t\t\t\t\t\t\tonInput={handleInput}\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t) : (\n\t\t\t\t\t\t\t<MarkdownPreview html={hook.body_html || \"\"} />\n\t\t\t\t\t\t)}\n\t\t\t\t\t</div>\n\n\t\t\t\t\t<div className=\"flex items-center gap-2\">\n\t\t\t\t\t\t{hook.source !== \"builtin\" ? (\n\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\tclassName={`provider-btn provider-btn-sm ${hook.enabled ? \"provider-btn-secondary\" : \"\"}`}\n\t\t\t\t\t\t\t\tonClick={handleEnableDisable}\n\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t{hook.enabled ? \"Disable\" : \"Enable\"}\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t) : null}\n\t\t\t\t\t\t{dirty.value ? (\n\t\t\t\t\t\t\t<button className=\"provider-btn provider-btn-sm\" onClick={handleSave} disabled={saving.value}>\n\t\t\t\t\t\t\t\t{saving.value ? \"Saving\\u2026\" : \"Save\"}\n\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t) : null}\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t) : null}\n\t\t</div>\n\t);\n}\n\nfunction HooksPageComponent(): VNode {\n\tuseEffect(() => {\n\t\trefreshHooks();\n\t\tconst off = onEvent(\"hooks.status\", (payload: unknown) => {\n\t\t\tconst data = payload as { hooks?: Hook[] };\n\t\t\tif (data?.hooks) {\n\t\t\t\thooks.value = data.hooks;\n\t\t\t\tupdateNavCount(\"hooks\", data.hooks.length);\n\t\t\t} else {\n\t\t\t\trefreshHooks();\n\t\t\t}\n\t\t});\n\t\treturn off;\n\t}, []);\n\n\tasync function handleReload(): Promise<void> {\n\t\tloading.value = true;\n\t\tconst res = await sendRpc(\"hooks.reload\", {});\n\t\tif (res?.ok) {\n\t\t\tshowToast(\"Hooks reloaded\", \"success\");\n\t\t} else {\n\t\t\tshowToast(`Reload failed: ${res?.error?.message || \"unknown error\"}`, \"error\");\n\t\t}\n\t\tloading.value = false;\n\t}\n\n\treturn (\n\t\t<>\n\t\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Hooks</h2>\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"provider-btn provider-btn-secondary provider-btn-sm\"\n\t\t\t\t\t\tonClick={handleReload}\n\t\t\t\t\t\tdisabled={loading.value}\n\t\t\t\t\t>\n\t\t\t\t\t\t{loading.value ? \"Reloading\\u2026\" : \"Reload\"}\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\n\t\t\t\t<div className=\"max-w-[600px] bg-[var(--surface2)] border border-[var(--border)] rounded-[var(--radius)] px-5 py-4 leading-relaxed\">\n\t\t\t\t\t<p className=\"text-sm text-[var(--text)] mb-2.5\">\n\t\t\t\t\t\t<strong className=\"text-[var(--text-strong)]\">Hooks</strong> run shell commands in response to lifecycle\n\t\t\t\t\t\tevents (tool calls, messages, sessions, etc.). They live in{\" \"}\n\t\t\t\t\t\t<code className=\"font-mono text-xs\">.moltis/hooks/</code> directories.\n\t\t\t\t\t</p>\n\t\t\t\t\t<div className=\"flex items-center gap-2 my-3 px-3.5 py-2.5 bg-[var(--surface)] rounded-[var(--radius-sm)] font-mono text-xs text-[var(--text-strong)]\">\n\t\t\t\t\t\t<span className=\"opacity-50\">Event</span>\n\t\t\t\t\t\t<span className=\"text-[var(--accent)]\">{\"\\u2192\"}</span>\n\t\t\t\t\t\t<span>Hook Script</span>\n\t\t\t\t\t\t<span className=\"text-[var(--accent)]\">{\"\\u2192\"}</span>\n\t\t\t\t\t\t<span>Continue / Modify / Block</span>\n\t\t\t\t\t</div>\n\t\t\t\t\t<p className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\tEach hook is a directory containing a <code className=\"font-mono\">HOOK.md</code> file with TOML frontmatter\n\t\t\t\t\t\t(events, command, requirements) and optional documentation. Edit the content below and click{\" \"}\n\t\t\t\t\t\t<strong>Save</strong> to update.\n\t\t\t\t\t</p>\n\t\t\t\t</div>\n\n\t\t\t\t{hooks.value.length === 0 && !loading.value ? (\n\t\t\t\t\t<div className=\"max-w-[600px] text-sm text-[var(--muted)] px-1\">\n\t\t\t\t\t\tNo hooks discovered. Create a <code className=\"font-mono text-xs\">HOOK.md</code> file in{\" \"}\n\t\t\t\t\t\t<code className=\"font-mono text-xs\">.moltis/hooks/my-hook/</code> or{\" \"}\n\t\t\t\t\t\t<code className=\"font-mono text-xs\">~/.moltis/hooks/my-hook/</code> to get started.\n\t\t\t\t\t</div>\n\t\t\t\t) : null}\n\n\t\t\t\t<div className=\"max-w-[900px] flex flex-col gap-3\">\n\t\t\t\t\t{hooks.value.map((h) => (\n\t\t\t\t\t\t<HookCard key={h.name} hook={h} />\n\t\t\t\t\t))}\n\t\t\t\t</div>\n\n\t\t\t\t{loading.value && hooks.value.length === 0 ? (\n\t\t\t\t\t<div className=\"p-6 text-center text-[var(--muted)] text-sm\">Loading hooks{\"\\u2026\"}</div>\n\t\t\t\t) : null}\n\t\t\t</div>\n\t\t\t<Toasts />\n\t\t</>\n\t);\n}\n\n// ── Exported init/teardown for settings integration ─────────\nlet _hooksContainer: HTMLElement | null = null;\n\nexport function initHooks(container: HTMLElement): void {\n\t_hooksContainer = container;\n\tcontainer.style.cssText = \"flex-direction:column;padding:0;overflow:hidden;\";\n\trender(<HooksPageComponent />, container);\n}\n\nexport function teardownHooks(): void {\n\tif (_hooksContainer) render(null, _hooksContainer);\n\t_hooksContainer = null;\n}\n","// ── Images page (Preact + Signals) ──────────────────────────\n\nimport { signal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect } from \"preact/hooks\";\nimport { localizedApiErrorMessage } from \"../helpers\";\nimport { updateNavCount } from \"../nav-counts\";\nimport { sandboxInfo } from \"../signals\";\n\n// ── Types ────────────────────────────────────────────────────\n\ninterface CachedImage {\n\ttag: string;\n\tsize: string;\n\tcreated: string;\n\tkind: string;\n}\n\ninterface ContainerInfo {\n\tname: string;\n\tstate: string;\n\tbackend: string;\n\timage: string;\n\tcpus?: number;\n\tmemory_mb?: number;\n}\n\ninterface DiskUsageInfo {\n\tcontainers_total: number;\n\tcontainers_active: number;\n\tcontainers_size_bytes: number;\n\tcontainers_reclaimable_bytes: number;\n\timages_total: number;\n\timages_active: number;\n\timages_size_bytes: number;\n}\n\ninterface SandboxInfoValue {\n\tbackend: string;\n\tos: string;\n\tdefault_image?: string;\n\tshared_home_enabled?: boolean;\n\tshared_home_dir?: string;\n}\n\ninterface SharedHomeConfig {\n\tenabled?: boolean;\n\tmode?: string;\n\tpath?: string;\n\tconfigured_path?: string;\n}\n\n// ── Signals ──────────────────────────────────────────────────\n\nconst defaultImage = signal(\"\");\nconst savingDefault = signal(false);\nconst images = signal<CachedImage[]>([]);\nconst loading = signal(false);\nconst buildName = signal(\"\");\nconst buildBase = signal(\"ubuntu:25.10\");\nconst buildPackages = signal(\"\");\nconst building = signal(false);\nconst buildStatus = signal(\"\");\nconst buildWarning = signal(\"\");\nconst pruning = signal(false);\nconst containers = signal<ContainerInfo[]>([]);\nconst loadingContainers = signal(false);\nconst diskUsage = signal<DiskUsageInfo | null>(null);\nconst cleaningAll = signal(false);\nconst restarting = signal(false);\nconst containerError = signal(\"\");\nconst sharedHomeEnabled = signal(false);\nconst sharedHomeMode = signal(\"off\");\nconst sharedHomePath = signal(\"\");\nconst sharedHomeConfiguredPath = signal(\"\");\nconst sharedHomeLoading = signal(false);\nconst sharedHomeSaving = signal(false);\nconst sharedHomeMsg = signal(\"\");\nconst sharedHomeErr = signal(\"\");\nconst SANDBOX_DISABLED_HINT =\n\t\"Sandboxes are disabled on cloud deploys without a container runtime. Install on a VM with Docker or Apple Container to enable this feature.\";\n\nfunction sandboxRuntimeAvailable(): boolean {\n\treturn ((sandboxInfo.value as SandboxInfoValue | null)?.backend || \"none\") !== \"none\";\n}\n\nasync function responseErrorMessage(response: Response, fallback: string): Promise<string> {\n\ttry {\n\t\tconst payload = await response.json();\n\t\treturn localizedApiErrorMessage(payload, fallback);\n\t} catch {\n\t\ttry {\n\t\t\tconst text = await response.text();\n\t\t\treturn text || fallback;\n\t\t} catch {\n\t\t\treturn fallback;\n\t\t}\n\t}\n}\n\nfunction fetchImages(): void {\n\tloading.value = true;\n\tfetch(\"/api/images/cached\")\n\t\t.then((r) => (r.ok ? r.json() : { images: [] }))\n\t\t.then((data) => {\n\t\t\timages.value = data.images || [];\n\t\t\tupdateNavCount(\"images\", images.value.length);\n\t\t})\n\t\t.catch(() => {\n\t\t\timages.value = [];\n\t\t})\n\t\t.finally(() => {\n\t\t\tloading.value = false;\n\t\t});\n}\n\nfunction deleteImage(tag: string): void {\n\tconst encoded = encodeURIComponent(tag);\n\tfetch(`/api/images/cached/${encoded}`, { method: \"DELETE\" })\n\t\t.then((r) => {\n\t\t\tif (r.ok) fetchImages();\n\t\t})\n\t\t.catch(() => {\n\t\t\t/* ignore */\n\t\t});\n}\n\nfunction pruneAll(): void {\n\tpruning.value = true;\n\tfetch(\"/api/images/cached\", { method: \"DELETE\" })\n\t\t.then((r) => {\n\t\t\tif (r.ok) fetchImages();\n\t\t})\n\t\t.catch(() => {\n\t\t\t/* ignore */\n\t\t})\n\t\t.finally(() => {\n\t\t\tpruning.value = false;\n\t\t});\n}\n\nfunction doBuild(name: string, base: string, pkgs: string[]): void {\n\tbuildStatus.value = \"Building image\\u2026\";\n\tfetch(\"/api/images/build\", {\n\t\tmethod: \"POST\",\n\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\tbody: JSON.stringify({ name, base, packages: pkgs }),\n\t})\n\t\t.then((r) => r.json())\n\t\t.then((data) => {\n\t\t\tif (data.error) {\n\t\t\t\tbuildStatus.value = `Error: ${localizedApiErrorMessage(data, \"Failed to build image.\")}`;\n\t\t\t} else {\n\t\t\t\tbuildStatus.value = `Built: ${data.tag}`;\n\t\t\t\tbuildName.value = \"\";\n\t\t\t\tbuildPackages.value = \"\";\n\t\t\t\tfetchImages();\n\t\t\t}\n\t\t})\n\t\t.catch((e: Error) => {\n\t\t\tbuildStatus.value = `Error: ${e.message}`;\n\t\t})\n\t\t.finally(() => {\n\t\t\tbuilding.value = false;\n\t\t});\n}\n\nfunction buildImage(): void {\n\tconst name = buildName.value.trim();\n\tif (!name) return;\n\tconst base = buildBase.value.trim() || \"ubuntu:25.10\";\n\tconst pkgs = buildPackages.value\n\t\t.trim()\n\t\t.split(/[\\s,]+/)\n\t\t.filter(Boolean);\n\tif (pkgs.length === 0) {\n\t\tbuildStatus.value = \"Please specify at least one package.\";\n\t\treturn;\n\t}\n\tbuilding.value = true;\n\tbuildWarning.value = \"\";\n\tbuildStatus.value = \"Checking packages in base image\\u2026\";\n\n\tfetch(\"/api/images/check-packages\", {\n\t\tmethod: \"POST\",\n\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\tbody: JSON.stringify({ base, packages: pkgs }),\n\t})\n\t\t.then((r) => (r.ok ? r.json() : null))\n\t\t.then((data) => {\n\t\t\tconst found = data?.found || {};\n\t\t\tconst present = pkgs.filter((p) => found[p]);\n\t\t\tconst missing = pkgs.filter((p) => !found[p]);\n\n\t\t\tif (present.length > 0 && missing.length === 0) {\n\t\t\t\tbuilding.value = false;\n\t\t\t\tbuildWarning.value = `All requested packages are already present in ${base}: ${present.join(\", \")}. No image build needed.`;\n\t\t\t\tbuildStatus.value = \"\";\n\t\t\t\treturn;\n\t\t\t}\n\n\t\t\tif (present.length > 0) {\n\t\t\t\tbuildWarning.value = `Already in ${base}: ${present.join(\", \")}. Only installing: ${missing.join(\", \")}.`;\n\t\t\t}\n\n\t\t\tdoBuild(name, base, missing.length > 0 ? missing : pkgs);\n\t\t})\n\t\t.catch(() => {\n\t\t\tdoBuild(name, base, pkgs);\n\t\t});\n}\n\nfunction fetchContainers(): void {\n\tloadingContainers.value = true;\n\tfetch(\"/api/sandbox/containers\")\n\t\t.then((r) => (r.ok ? r.json() : { containers: [] }))\n\t\t.then((data) => {\n\t\t\tcontainers.value = data.containers || [];\n\t\t\tcontainerError.value = \"\";\n\t\t})\n\t\t.catch(() => {\n\t\t\tcontainers.value = [];\n\t\t})\n\t\t.finally(() => {\n\t\t\tloadingContainers.value = false;\n\t\t});\n}\n\nfunction stopContainer(name: string): void {\n\tfetch(`/api/sandbox/containers/${encodeURIComponent(name)}/stop`, { method: \"POST\" })\n\t\t.then((r) => {\n\t\t\tif (r.ok) fetchContainers();\n\t\t})\n\t\t.catch(() => {\n\t\t\t/* ignore */\n\t\t});\n}\n\nfunction removeContainer(name: string): void {\n\tfetch(`/api/sandbox/containers/${encodeURIComponent(name)}`, { method: \"DELETE\" })\n\t\t.then(async (r) => {\n\t\t\tif (!r.ok) {\n\t\t\t\tconst msg = await responseErrorMessage(r, r.statusText);\n\t\t\t\tcontainerError.value = `Failed to delete ${name}: ${msg}`;\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tfetchContainers();\n\t\t})\n\t\t.catch((e: Error) => {\n\t\t\tcontainerError.value = `Failed to delete ${name}: ${e.message}`;\n\t\t});\n}\n\nfunction fetchDiskUsage(): void {\n\tfetch(\"/api/sandbox/disk-usage\")\n\t\t.then((r) => (r.ok ? r.json() : null))\n\t\t.then((data) => {\n\t\t\tdiskUsage.value = data?.usage || null;\n\t\t})\n\t\t.catch(() => {\n\t\t\tdiskUsage.value = null;\n\t\t});\n}\n\nfunction cleanAllContainers(): void {\n\tcleaningAll.value = true;\n\tfetch(\"/api/sandbox/containers/clean\", { method: \"POST\" })\n\t\t.then(async (r) => {\n\t\t\tif (!r.ok) {\n\t\t\t\tconst msg = await responseErrorMessage(r, r.statusText);\n\t\t\t\tcontainerError.value = `Failed to clean containers: ${msg}`;\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tfetchContainers();\n\t\t\tfetchDiskUsage();\n\t\t})\n\t\t.catch((e: Error) => {\n\t\t\tcontainerError.value = `Failed to clean containers: ${e.message}`;\n\t\t})\n\t\t.finally(() => {\n\t\t\tcleaningAll.value = false;\n\t\t});\n}\n\nfunction restartDaemon(): void {\n\trestarting.value = true;\n\tfetch(\"/api/sandbox/daemon/restart\", { method: \"POST\" })\n\t\t.then(async (r) => {\n\t\t\tif (!r.ok) {\n\t\t\t\tconst msg = await responseErrorMessage(r, r.statusText);\n\t\t\t\tcontainerError.value = `Failed to restart daemon: ${msg}`;\n\t\t\t\treturn;\n\t\t\t}\n\t\t\tfetchContainers();\n\t\t\tfetchDiskUsage();\n\t\t})\n\t\t.catch((e: Error) => {\n\t\t\tcontainerError.value = `Failed to restart daemon: ${e.message}`;\n\t\t})\n\t\t.finally(() => {\n\t\t\trestarting.value = false;\n\t\t});\n}\n\nfunction applySharedHomeConfig(config: SharedHomeConfig | null): void {\n\tconst payload = config || {};\n\tsharedHomeEnabled.value = payload.enabled === true;\n\tsharedHomeMode.value = payload.mode || \"off\";\n\tsharedHomePath.value = payload.path || \"\";\n\tsharedHomeConfiguredPath.value = payload.configured_path || \"\";\n}\n\nfunction fetchSharedHomeConfig(): void {\n\tsharedHomeLoading.value = true;\n\tsharedHomeErr.value = \"\";\n\tsharedHomeMsg.value = \"\";\n\tfetch(\"/api/sandbox/shared-home\")\n\t\t.then(async (r) => {\n\t\t\tif (!r.ok) {\n\t\t\t\tthrow new Error(await responseErrorMessage(r, \"Failed to load shared folder settings.\"));\n\t\t\t}\n\t\t\treturn r.json();\n\t\t})\n\t\t.then((data) => {\n\t\t\tapplySharedHomeConfig(data);\n\t\t})\n\t\t.catch((e: Error) => {\n\t\t\tsharedHomeErr.value = e.message;\n\t\t})\n\t\t.finally(() => {\n\t\t\tsharedHomeLoading.value = false;\n\t\t});\n}\n\nfunction saveSharedHomeConfig(): void {\n\tsharedHomeSaving.value = true;\n\tsharedHomeErr.value = \"\";\n\tsharedHomeMsg.value = \"\";\n\tfetch(\"/api/sandbox/shared-home\", {\n\t\tmethod: \"PUT\",\n\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\tbody: JSON.stringify({\n\t\t\tenabled: sharedHomeEnabled.value,\n\t\t\tpath: sharedHomePath.value || \"\",\n\t\t}),\n\t})\n\t\t.then(async (r) => {\n\t\t\tif (!r.ok) {\n\t\t\t\tthrow new Error(await responseErrorMessage(r, \"Failed to save shared folder settings.\"));\n\t\t\t}\n\t\t\treturn r.json();\n\t\t})\n\t\t.then((data) => {\n\t\t\tapplySharedHomeConfig(data?.config || {});\n\t\t\tsharedHomeMsg.value = \"Saved. Restart Moltis to apply shared folder changes.\";\n\t\t\tif (sandboxInfo.value) {\n\t\t\t\tsandboxInfo.value = {\n\t\t\t\t\t...(sandboxInfo.value as SandboxInfoValue),\n\t\t\t\t\tshared_home_enabled: sharedHomeEnabled.value,\n\t\t\t\t\tshared_home_dir: sharedHomePath.value,\n\t\t\t\t};\n\t\t\t}\n\t\t})\n\t\t.catch((e: Error) => {\n\t\t\tsharedHomeErr.value = e.message;\n\t\t})\n\t\t.finally(() => {\n\t\t\tsharedHomeSaving.value = false;\n\t\t});\n}\n\nfunction formatBytes(bytes: number | null | undefined): string {\n\tif (bytes == null) return \"\\u2014\";\n\tif (bytes < 1024) return `${bytes} B`;\n\tif (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;\n\tif (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;\n\treturn `${(bytes / (1024 * 1024 * 1024)).toFixed(1)} GB`;\n}\n\nconst STATE_LABELS: Record<string, { label: string; color: string }> = {\n\trunning: { label: \"running\", color: \"var(--accent)\" },\n\tstopped: { label: \"stopped\", color: \"var(--muted)\" },\n\texited: { label: \"exited\", color: \"var(--muted)\" },\n\tunknown: { label: \"unknown\", color: \"var(--muted)\" },\n};\n\nconst BACKEND_ICONS: Record<string, string> = {\n\t\"apple-container\": \"\\u{1F34E}\",\n\tdocker: \"\\u{1F433}\",\n};\n\n/** Truncate long hash suffixes: \"repo:abcdef...uvwxyz\" */\nfunction truncateHash(str: string): string {\n\tconst idx = str.lastIndexOf(\":\");\n\tif (idx !== -1) {\n\t\tconst suffix = str.slice(idx + 1);\n\t\tif (suffix.length > 12) {\n\t\t\treturn `${str.slice(0, idx + 1) + suffix.slice(0, 6)}\\u2026${suffix.slice(-6)}`;\n\t\t}\n\t}\n\tif (str.length > 24 && str.indexOf(\":\") === -1) {\n\t\treturn `${str.slice(0, 6)}\\u2026${str.slice(-6)}`;\n\t}\n\treturn str;\n}\n\nfunction ContainerRow({\n\tcontainer: c,\n\tsandboxAvailable,\n}: {\n\tcontainer: ContainerInfo;\n\tsandboxAvailable: boolean;\n}): VNode {\n\tconst stateInfo = STATE_LABELS[c.state] || STATE_LABELS.unknown;\n\tconst backendIcon = BACKEND_ICONS[c.backend] || \"\";\n\tconst isRunning = c.state === \"running\";\n\tconst resources: string[] = [];\n\tif (c.cpus) resources.push(`${c.cpus} CPU`);\n\tif (c.memory_mb) resources.push(`${c.memory_mb} MB`);\n\n\treturn (\n\t\t<div className=\"provider-item flex-col gap-1 mb-1\" style={{ alignItems: \"stretch\" }}>\n\t\t\t<div className=\"flex items-center justify-between gap-2 w-full min-w-0\">\n\t\t\t\t<span className=\"font-mono text-xs truncate flex-1 text-[var(--text-strong)]\" title={c.name}>\n\t\t\t\t\t{truncateHash(c.name)}\n\t\t\t\t</span>\n\t\t\t\t<span\n\t\t\t\t\tclassName=\"inline-flex items-center gap-1 text-xs px-1.5 py-0.5 rounded-full shrink-0\"\n\t\t\t\t\tstyle={{ background: `color-mix(in srgb, ${stateInfo.color} 15%, transparent)`, color: stateInfo.color }}\n\t\t\t\t>\n\t\t\t\t\t<span className=\"inline-block w-1.5 h-1.5 rounded-full\" style={{ background: stateInfo.color }} />\n\t\t\t\t\t{stateInfo.label}\n\t\t\t\t</span>\n\t\t\t</div>\n\t\t\t<div className=\"flex items-center justify-between gap-2 w-full\">\n\t\t\t\t<div className=\"flex items-center gap-2 text-xs text-[var(--muted)]\">\n\t\t\t\t\t<span title={c.backend}>{backendIcon}</span>\n\t\t\t\t\t<span className=\"font-mono\" title={c.image}>\n\t\t\t\t\t\t{truncateHash(c.image)}\n\t\t\t\t\t</span>\n\t\t\t\t\t{resources.length > 0 && <span>{resources.join(\" \\u00b7 \")}</span>}\n\t\t\t\t</div>\n\t\t\t\t<div className=\"flex items-center gap-1\">\n\t\t\t\t\t{isRunning && (\n\t\t\t\t\t\t<button\n\t\t\t\t\t\t\tclassName=\"text-xs px-2 py-0.5 rounded border border-[var(--border)] bg-transparent text-[var(--muted)] hover:text-[var(--text)] hover:border-[var(--border-strong)] transition-colors cursor-pointer\"\n\t\t\t\t\t\t\tonClick={() => stopContainer(c.name)}\n\t\t\t\t\t\t\tdisabled={!sandboxAvailable}\n\t\t\t\t\t\t\ttitle={sandboxAvailable ? \"Stop container\" : SANDBOX_DISABLED_HINT}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\tStop\n\t\t\t\t\t\t</button>\n\t\t\t\t\t)}\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"text-xs text-white border border-[var(--error)] px-2 py-0.5 rounded bg-[var(--error)] hover:opacity-80 transition-colors cursor-pointer\"\n\t\t\t\t\t\tonClick={() => removeContainer(c.name)}\n\t\t\t\t\t\tdisabled={!sandboxAvailable}\n\t\t\t\t\t\ttitle={sandboxAvailable ? \"Delete container\" : SANDBOX_DISABLED_HINT}\n\t\t\t\t\t>\n\t\t\t\t\t\tDelete\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nfunction DiskUsageBar(): VNode | null {\n\tconst du = diskUsage.value;\n\tif (!du) return null;\n\n\treturn (\n\t\t<div className=\"text-xs text-[var(--muted)] flex flex-wrap gap-x-4 gap-y-1 mt-1 mb-2\">\n\t\t\t<span>\n\t\t\t\tContainers: {du.containers_total} total, {du.containers_active} active &middot;{\" \"}\n\t\t\t\t{formatBytes(du.containers_size_bytes)} ({formatBytes(du.containers_reclaimable_bytes)} reclaimable)\n\t\t\t</span>\n\t\t\t<span>\n\t\t\t\tImages: {du.images_total} total, {du.images_active} active &middot; {formatBytes(du.images_size_bytes)}\n\t\t\t</span>\n\t\t</div>\n\t);\n}\n\nfunction RunningContainersSection(): VNode {\n\tconst sandboxAvailable = sandboxRuntimeAvailable();\n\tconst list = containers.value;\n\n\treturn (\n\t\t<div className=\"max-w-form\">\n\t\t\t<div className=\"flex items-center gap-3 mb-2\">\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\">\n\t\t\t\t\tRunning Containers{list.length > 0 ? ` (${list.length})` : \"\"}\n\t\t\t\t</h3>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"text-xs text-[var(--muted)] border border-[var(--border)] px-2 py-0.5 rounded-md hover:text-[var(--text)] hover:border-[var(--border-strong)] transition-colors cursor-pointer bg-transparent\"\n\t\t\t\t\tonClick={restartDaemon}\n\t\t\t\t\tdisabled={restarting.value || !sandboxAvailable}\n\t\t\t\t\ttitle={sandboxAvailable ? \"Restart container daemon\" : SANDBOX_DISABLED_HINT}\n\t\t\t\t>\n\t\t\t\t\t{restarting.value ? \"Restarting\\u2026\" : \"Restart\"}\n\t\t\t\t</button>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"text-xs text-[var(--muted)] border border-[var(--border)] px-2 py-0.5 rounded-md hover:text-[var(--text)] hover:border-[var(--border-strong)] transition-colors cursor-pointer bg-transparent\"\n\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\tfetchContainers();\n\t\t\t\t\t\tfetchDiskUsage();\n\t\t\t\t\t}}\n\t\t\t\t\tdisabled={loadingContainers.value || !sandboxAvailable}\n\t\t\t\t\ttitle={sandboxAvailable ? \"Refresh\" : SANDBOX_DISABLED_HINT}\n\t\t\t\t>\n\t\t\t\t\t{loadingContainers.value ? \"Loading\\u2026\" : \"Refresh\"}\n\t\t\t\t</button>\n\t\t\t\t{list.length > 0 && (\n\t\t\t\t\t<button\n\t\t\t\t\t\tclassName=\"text-xs text-white border border-[var(--error)] px-2 py-0.5 rounded-md bg-[var(--error)] hover:opacity-80 transition-colors cursor-pointer\"\n\t\t\t\t\t\tonClick={cleanAllContainers}\n\t\t\t\t\t\tdisabled={cleaningAll.value || !sandboxAvailable}\n\t\t\t\t\t\ttitle={sandboxAvailable ? \"Stop and remove all containers\" : SANDBOX_DISABLED_HINT}\n\t\t\t\t\t>\n\t\t\t\t\t\t{cleaningAll.value ? \"Cleaning\\u2026\" : \"Clean All\"}\n\t\t\t\t\t</button>\n\t\t\t\t)}\n\t\t\t</div>\n\t\t\t<DiskUsageBar />\n\t\t\t{containerError.value && <div className=\"alert-error-text mb-2\">{containerError.value}</div>}\n\t\t\t{loadingContainers.value && list.length === 0 && (\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Loading&hellip;</div>\n\t\t\t)}\n\t\t\t{!loadingContainers.value && list.length === 0 && (\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ padding: \"4px 0\" }}>\n\t\t\t\t\tNo containers found.\n\t\t\t\t</div>\n\t\t\t)}\n\t\t\t{list.map((c) => (\n\t\t\t\t<ContainerRow key={c.name} container={c} sandboxAvailable={sandboxAvailable} />\n\t\t\t))}\n\t\t</div>\n\t);\n}\n\nconst BACKEND_LABELS: Record<string, string> = {\n\t\"apple-container\": \"Apple Container (VM-isolated)\",\n\tdocker: \"Docker\",\n\tcgroup: \"cgroup (systemd-run)\",\n\t\"restricted-host\": \"Restricted Host (env + rlimits)\",\n\twasm: \"Wasmtime (WASM-isolated)\",\n\tnone: \"None (host execution)\",\n};\n\nfunction backendRecommendation(info: SandboxInfoValue | null): { level: string; text: string; link?: string } | null {\n\tif (!info) return null;\n\tconst os = info.os;\n\tconst backend = info.backend;\n\n\tif (backend === \"none\") {\n\t\tif (os === \"macos\") {\n\t\t\treturn {\n\t\t\t\tlevel: \"warn\",\n\t\t\t\ttext: \"No container runtime detected. Install Apple Container (macOS 26+) for VM-isolated sandboxing, or install Docker as an alternative.\",\n\t\t\t\tlink: \"https://developer.apple.com/documentation/virtualization\",\n\t\t\t};\n\t\t}\n\t\tif (os === \"linux\") {\n\t\t\treturn {\n\t\t\t\tlevel: \"warn\",\n\t\t\t\ttext: \"No container runtime detected. Install Docker for sandboxed execution, or ensure systemd is available for cgroup isolation.\",\n\t\t\t};\n\t\t}\n\t\treturn { level: \"warn\", text: \"No container runtime detected. Install Docker for sandboxed execution.\" };\n\t}\n\n\tif (os === \"macos\" && backend === \"docker\") {\n\t\treturn {\n\t\t\tlevel: \"info\",\n\t\t\ttext: \"Apple Container provides stronger VM-level isolation on macOS 26+. Install it for automatic use (moltis prefers it over Docker). Run: brew install container\",\n\t\t};\n\t}\n\tif (os === \"linux\" && backend === \"docker\") {\n\t\treturn {\n\t\t\tlevel: \"info\",\n\t\t\ttext: \"Docker is a good choice on Linux. For lighter-weight isolation without Docker overhead, systemd cgroup sandboxing is also supported.\",\n\t\t};\n\t}\n\tif (backend === \"restricted-host\") {\n\t\treturn {\n\t\t\tlevel: \"info\",\n\t\t\ttext: \"Using restricted host execution (env clearing, rlimits). For stronger isolation, install Docker or Apple Container.\",\n\t\t};\n\t}\n\tif (backend === \"wasm\") {\n\t\treturn {\n\t\t\tlevel: \"info\",\n\t\t\ttext: \"Using WASM sandbox with filesystem isolation. For container-level isolation, install Docker or Apple Container.\",\n\t\t};\n\t}\n\n\treturn null;\n}\n\nfunction SandboxBanner(): VNode | null {\n\tconst info = sandboxInfo.value as SandboxInfoValue | null;\n\tif (!info) return null;\n\n\tconst label = BACKEND_LABELS[info.backend] || info.backend;\n\tconst rec = backendRecommendation(info);\n\n\tconst badgeColor =\n\t\tinfo.backend === \"none\"\n\t\t\t? \"var(--error)\"\n\t\t\t: info.backend === \"apple-container\"\n\t\t\t\t? \"var(--accent)\"\n\t\t\t\t: info.backend === \"wasm\"\n\t\t\t\t\t? \"var(--success)\"\n\t\t\t\t\t: info.backend === \"restricted-host\"\n\t\t\t\t\t\t? \"var(--warning, var(--muted))\"\n\t\t\t\t\t\t: \"var(--muted)\";\n\n\treturn (\n\t\t<div className=\"max-w-form\">\n\t\t\t<div className=\"info-bar\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\t<span className=\"info-field\">\n\t\t\t\t\t<span className=\"info-label\">Container backend:</span>\n\t\t\t\t\t<span className=\"info-value-strong\" style={{ color: badgeColor, fontFamily: \"var(--font-mono)\" }}>\n\t\t\t\t\t\t{label}\n\t\t\t\t\t</span>\n\t\t\t\t</span>\n\t\t\t</div>\n\t\t\t{rec && (\n\t\t\t\t<div className={rec.level === \"warn\" ? \"alert-warning-text\" : \"alert-info-text\"}>\n\t\t\t\t\t<span className={rec.level === \"warn\" ? \"alert-label-warn\" : \"alert-label-info\"}>\n\t\t\t\t\t\t{rec.level === \"warn\" ? \"Warning: \" : \"Tip: \"}\n\t\t\t\t\t</span>\n\t\t\t\t\t{rec.text}\n\t\t\t\t</div>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\nfunction DefaultImageSelector(): VNode {\n\tconst info = sandboxInfo.value as SandboxInfoValue | null;\n\tconst current = defaultImage.value || info?.default_image || \"\";\n\tconst sandboxAvailable = sandboxRuntimeAvailable();\n\n\tfunction onSave(): void {\n\t\tconst val = defaultImage.value.trim();\n\t\tsavingDefault.value = true;\n\t\tfetch(\"/api/images/default\", {\n\t\t\tmethod: \"PUT\",\n\t\t\theaders: { \"Content-Type\": \"application/json\" },\n\t\t\tbody: JSON.stringify({ image: val || null }),\n\t\t})\n\t\t\t.then((r) => (r.ok ? r.json() : null))\n\t\t\t.then((data) => {\n\t\t\t\tif (data) defaultImage.value = data.image;\n\t\t\t})\n\t\t\t.catch(() => {\n\t\t\t\t/* ignore */\n\t\t\t})\n\t\t\t.finally(() => {\n\t\t\t\tsavingDefault.value = false;\n\t\t\t});\n\t}\n\n\treturn (\n\t\t<div className=\"max-w-form\">\n\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\tDefault image\n\t\t\t</h3>\n\t\t\t<p className=\"text-xs text-[var(--muted)]\" style={{ margin: \"0 0 8px\" }}>\n\t\t\t\tBase image used for new sessions and projects unless overridden. Leave empty to use the built-in default\n\t\t\t\t(ubuntu:25.10).\n\t\t\t</p>\n\t\t\t<div style={{ display: \"flex\", gap: \"8px\", alignItems: \"center\" }}>\n\t\t\t\t<input\n\t\t\t\t\ttype=\"text\"\n\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\tlist=\"default-image-list\"\n\t\t\t\t\tplaceholder=\"ubuntu:25.10\"\n\t\t\t\t\tstyle={{ flex: 1, fontFamily: \"var(--font-mono)\", fontSize: \".8rem\" }}\n\t\t\t\t\tvalue={current}\n\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\tdefaultImage.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t}}\n\t\t\t\t/>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn\"\n\t\t\t\t\tonClick={onSave}\n\t\t\t\t\tdisabled={savingDefault.value || !sandboxAvailable}\n\t\t\t\t\ttitle={sandboxAvailable ? undefined : SANDBOX_DISABLED_HINT}\n\t\t\t\t>\n\t\t\t\t\t{savingDefault.value ? \"Saving\\u2026\" : \"Save\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<datalist id=\"default-image-list\">\n\t\t\t\t{images.value.map((img) => (\n\t\t\t\t\t<option key={img.tag} value={img.tag} />\n\t\t\t\t))}\n\t\t\t</datalist>\n\t\t</div>\n\t);\n}\n\nfunction SharedHomeSection(): VNode {\n\tconst modeLabel = sharedHomeMode.value === \"shared\" ? \"enabled\" : `disabled (${sharedHomeMode.value})`;\n\n\treturn (\n\t\t<div className=\"max-w-form\" style={{ borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}>\n\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\tShared home folder\n\t\t\t</h3>\n\t\t\t<p className=\"text-xs text-[var(--muted)] leading-relaxed\" style={{ margin: \"0 0 10px\" }}>\n\t\t\t\tControls where <code>/home/sandbox</code> is persisted when shared home mode is enabled.\n\t\t\t</p>\n\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"10px\" }}>\n\t\t\t\tStatus:{\" \"}\n\t\t\t\t<span style={{ color: sharedHomeMode.value === \"shared\" ? \"var(--accent)\" : \"var(--muted)\" }}>{modeLabel}</span>\n\t\t\t</div>\n\t\t\t{sharedHomeLoading.value ? (\n\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">Loading...</div>\n\t\t\t) : (\n\t\t\t\t<div style={{ display: \"flex\", flexDirection: \"column\", gap: \"8px\" }}>\n\t\t\t\t\t<label\n\t\t\t\t\t\thtmlFor=\"sandboxSharedHomeEnabled\"\n\t\t\t\t\t\tclassName=\"text-xs text-[var(--text)]\"\n\t\t\t\t\t\tstyle={{ display: \"flex\", alignItems: \"center\", gap: \"8px\" }}\n\t\t\t\t\t>\n\t\t\t\t\t\t<input\n\t\t\t\t\t\t\tid=\"sandboxSharedHomeEnabled\"\n\t\t\t\t\t\t\ttype=\"checkbox\"\n\t\t\t\t\t\t\tchecked={sharedHomeEnabled.value}\n\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\tsharedHomeEnabled.value = (e.target as HTMLInputElement).checked;\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t\t<span>Enable shared home folder</span>\n\t\t\t\t\t</label>\n\t\t\t\t\t<label htmlFor=\"sandboxSharedHomePath\" className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\tShared folder location\n\t\t\t\t\t</label>\n\t\t\t\t\t<input\n\t\t\t\t\t\tid=\"sandboxSharedHomePath\"\n\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\tplaceholder=\"data_dir()/sandbox/home/shared\"\n\t\t\t\t\t\tvalue={sharedHomePath.value}\n\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\tsharedHomePath.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tstyle={{ fontFamily: \"var(--font-mono)\", fontSize: \".75rem\" }}\n\t\t\t\t\t/>\n\t\t\t\t\t{sharedHomeConfiguredPath.value ? (\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\tConfigured path: <code>{sharedHomeConfiguredPath.value}</code>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t) : (\n\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\">\n\t\t\t\t\t\t\tConfigured path: <em>default</em>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t)}\n\t\t\t\t\t<div style={{ display: \"flex\", gap: \"8px\", alignItems: \"center\" }}>\n\t\t\t\t\t\t<button className=\"provider-btn\" onClick={saveSharedHomeConfig} disabled={sharedHomeSaving.value}>\n\t\t\t\t\t\t\t{sharedHomeSaving.value ? \"Saving...\" : \"Save\"}\n\t\t\t\t\t\t</button>\n\t\t\t\t\t\t{sharedHomeErr.value ? (\n\t\t\t\t\t\t\t<span className=\"text-xs\" style={{ color: \"var(--error)\" }}>\n\t\t\t\t\t\t\t\t{sharedHomeErr.value}\n\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t) : sharedHomeMsg.value ? (\n\t\t\t\t\t\t\t<span className=\"text-xs\" style={{ color: \"var(--accent)\" }}>\n\t\t\t\t\t\t\t\t{sharedHomeMsg.value}\n\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t) : null}\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t)}\n\t\t</div>\n\t);\n}\n\nfunction ImageRow({ image: img, sandboxAvailable }: { image: CachedImage; sandboxAvailable: boolean }): VNode {\n\tconst kindLabel = img.kind === \"sandbox\" ? \"sandbox\" : \"tool\";\n\tconst kindColor = img.kind === \"sandbox\" ? \"var(--accent)\" : \"var(--muted)\";\n\treturn (\n\t\t<div className=\"provider-item\" style={{ marginBottom: \"4px\" }}>\n\t\t\t<div style={{ flex: 1, minWidth: 0 }}>\n\t\t\t\t<div className=\"flex items-center gap-2\">\n\t\t\t\t\t<span\n\t\t\t\t\t\tclassName=\"provider-item-name\"\n\t\t\t\t\t\tstyle={{ fontFamily: \"var(--font-mono)\", fontSize: \".8rem\" }}\n\t\t\t\t\t\ttitle={img.tag}\n\t\t\t\t\t>\n\t\t\t\t\t\t{truncateHash(img.tag)}\n\t\t\t\t\t</span>\n\t\t\t\t\t<span\n\t\t\t\t\t\tclassName=\"text-[0.65rem] px-1.5 py-0.5 rounded-full\"\n\t\t\t\t\t\tstyle={{ background: `color-mix(in srgb, ${kindColor} 15%, transparent)`, color: kindColor }}\n\t\t\t\t\t>\n\t\t\t\t\t\t{kindLabel}\n\t\t\t\t\t</span>\n\t\t\t\t</div>\n\t\t\t\t<div style={{ fontSize: \".7rem\", color: \"var(--muted)\", marginTop: \"2px\", display: \"flex\", gap: \"12px\" }}>\n\t\t\t\t\t<span>{img.size}</span>\n\t\t\t\t\t<span>{img.created}</span>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t\t<button\n\t\t\t\tclassName=\"session-action-btn session-delete\"\n\t\t\t\ttitle={sandboxAvailable ? \"Delete image\" : SANDBOX_DISABLED_HINT}\n\t\t\t\tdisabled={!sandboxAvailable}\n\t\t\t\tonClick={() => deleteImage(img.tag)}\n\t\t\t>\n\t\t\t\tx\n\t\t\t</button>\n\t\t</div>\n\t);\n}\n\nfunction ImagesPage(): VNode {\n\tuseEffect(() => {\n\t\tfetchImages();\n\t\tfetchContainers();\n\t\tfetchDiskUsage();\n\t\tfetchSharedHomeConfig();\n\t}, []);\n\n\tconst sbInfo = sandboxInfo.value as SandboxInfoValue | null;\n\n\treturn (\n\t\t<div className=\"flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-y-auto\">\n\t\t\t{!sandboxRuntimeAvailable() && (\n\t\t\t\t<div className=\"alert-warning-text max-w-form\">\n\t\t\t\t\t<span className=\"alert-label-warn\">Warning: </span>\n\t\t\t\t\t{SANDBOX_DISABLED_HINT}\n\t\t\t\t</div>\n\t\t\t)}\n\t\t\t<div className=\"flex items-center gap-3\">\n\t\t\t\t<h2 className=\"text-lg font-medium text-[var(--text-strong)]\">Sandboxes</h2>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"text-xs text-[var(--muted)] border border-[var(--border)] px-2.5 py-1 rounded-md hover:text-[var(--text)] hover:border-[var(--border-strong)] transition-colors cursor-pointer bg-transparent\"\n\t\t\t\t\tonClick={pruneAll}\n\t\t\t\t\tdisabled={pruning.value || !sandboxRuntimeAvailable()}\n\t\t\t\t\ttitle={sandboxRuntimeAvailable() ? \"Prune all\" : SANDBOX_DISABLED_HINT}\n\t\t\t\t>\n\t\t\t\t\t{pruning.value ? \"Pruning\\u2026\" : \"Prune all\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t<p className=\"text-sm text-[var(--muted)] leading-relaxed max-w-form\" style={{ margin: 0 }}>\n\t\t\t\tContainer images cached by moltis for sandbox execution. You can delete individual images or prune all. Build\n\t\t\t\tcustom images from a base with apt packages.\n\t\t\t\t{sbInfo?.backend === \"apple-container\" && (\n\t\t\t\t\t<>\n\t\t\t\t\t\t<br />\n\t\t\t\t\t\t<br />\n\t\t\t\t\t\tApple Container provides VM-isolated execution but does not support building images. Docker (or OrbStack) is\n\t\t\t\t\t\trequired alongside Apple Container to build and cache custom images. Sandboxed commands run via Apple\n\t\t\t\t\t\tContainer; image builds use Docker.\n\t\t\t\t\t</>\n\t\t\t\t)}\n\t\t\t</p>\n\n\t\t\t<SandboxBanner />\n\t\t\t<RunningContainersSection />\n\t\t\t<DefaultImageSelector />\n\t\t\t<SharedHomeSection />\n\n\t\t\t{/* Cached images list */}\n\t\t\t<div className=\"max-w-form\">\n\t\t\t\t{loading.value && <div className=\"text-xs text-[var(--muted)]\">Loading&hellip;</div>}\n\t\t\t\t{!loading.value && images.value.length === 0 && (\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ padding: \"12px 0\" }}>\n\t\t\t\t\t\tNo cached images.\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t{images.value.map((img) => (\n\t\t\t\t\t<ImageRow key={img.tag} image={img} sandboxAvailable={sandboxRuntimeAvailable()} />\n\t\t\t\t))}\n\t\t\t</div>\n\n\t\t\t{/* Build custom image */}\n\t\t\t<div\n\t\t\t\tclassName=\"max-w-form\"\n\t\t\t\tstyle={{ marginTop: \"8px\", borderTop: \"1px solid var(--border)\", paddingTop: \"16px\" }}\n\t\t\t>\n\t\t\t\t<h3 className=\"text-sm font-medium text-[var(--text-strong)]\" style={{ marginBottom: \"12px\" }}>\n\t\t\t\t\tBuild custom image\n\t\t\t\t</h3>\n\t\t\t\t<div className=\"project-edit-group\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>\n\t\t\t\t\t\tImage name\n\t\t\t\t\t</div>\n\t\t\t\t\t<input\n\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\tplaceholder=\"my-tools\"\n\t\t\t\t\t\tstyle={{ width: \"100%\" }}\n\t\t\t\t\t\tvalue={buildName.value}\n\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\tbuildName.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t}}\n\t\t\t\t\t/>\n\t\t\t\t</div>\n\t\t\t\t<div className=\"project-edit-group\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>\n\t\t\t\t\t\tBase image\n\t\t\t\t\t</div>\n\t\t\t\t\t<input\n\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\tplaceholder=\"ubuntu:25.10\"\n\t\t\t\t\t\tstyle={{ width: \"100%\", fontFamily: \"var(--font-mono)\" }}\n\t\t\t\t\t\tvalue={buildBase.value}\n\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\tbuildBase.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t}}\n\t\t\t\t\t/>\n\t\t\t\t</div>\n\t\t\t\t<div className=\"project-edit-group\" style={{ marginBottom: \"8px\" }}>\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)]\" style={{ marginBottom: \"4px\" }}>\n\t\t\t\t\t\tPackages (space or newline separated)\n\t\t\t\t\t</div>\n\t\t\t\t\t<textarea\n\t\t\t\t\t\tclassName=\"provider-key-input\"\n\t\t\t\t\t\tplaceholder=\"ffmpeg python3-pip curl\"\n\t\t\t\t\t\tstyle={{\n\t\t\t\t\t\t\twidth: \"100%\",\n\t\t\t\t\t\t\tminHeight: \"60px\",\n\t\t\t\t\t\t\tresize: \"vertical\",\n\t\t\t\t\t\t\tfontFamily: \"var(--font-mono)\",\n\t\t\t\t\t\t\tfontSize: \".8rem\",\n\t\t\t\t\t\t}}\n\t\t\t\t\t\tvalue={buildPackages.value}\n\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\tbuildPackages.value = (e.target as HTMLTextAreaElement).value;\n\t\t\t\t\t\t}}\n\t\t\t\t\t/>\n\t\t\t\t</div>\n\t\t\t\t<button\n\t\t\t\t\tclassName=\"provider-btn\"\n\t\t\t\t\tonClick={buildImage}\n\t\t\t\t\tdisabled={\n\t\t\t\t\t\tbuilding.value || !buildName.value.trim() || !buildPackages.value.trim() || !sandboxRuntimeAvailable()\n\t\t\t\t\t}\n\t\t\t\t\ttitle={sandboxRuntimeAvailable() ? \"Build\" : SANDBOX_DISABLED_HINT}\n\t\t\t\t>\n\t\t\t\t\t{building.value ? \"Building\\u2026\" : \"Build\"}\n\t\t\t\t</button>\n\t\t\t\t{buildWarning.value && (\n\t\t\t\t\t<div className=\"alert-warning-text\" style={{ marginTop: \"8px\" }}>\n\t\t\t\t\t\t<span className=\"alert-label-warn\">Warning: </span>\n\t\t\t\t\t\t{buildWarning.value}\n\t\t\t\t\t</div>\n\t\t\t\t)}\n\t\t\t\t{buildStatus.value &&\n\t\t\t\t\t(buildStatus.value.startsWith(\"Error\") ? (\n\t\t\t\t\t\t<div className=\"alert-error-text\" style={{ marginTop: \"8px\" }}>\n\t\t\t\t\t\t\t<pre>{buildStatus.value}</pre>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t) : (\n\t\t\t\t\t\t<div className=\"text-xs\" style={{ marginTop: \"8px\", color: \"var(--muted)\" }}>\n\t\t\t\t\t\t\t{buildStatus.value}\n\t\t\t\t\t\t</div>\n\t\t\t\t\t))}\n\t\t\t</div>\n\t\t</div>\n\t);\n}\n\nlet _imagesContainer: HTMLElement | null = null;\n\nexport function initImages(container: HTMLElement): void {\n\t_imagesContainer = container;\n\tcontainer.style.cssText = \"flex-direction:column;padding:0;overflow:hidden;\";\n\timages.value = [];\n\tcontainers.value = [];\n\tdiskUsage.value = null;\n\tdefaultImage.value = (sandboxInfo.value as SandboxInfoValue | null)?.default_image || \"\";\n\tbuildStatus.value = \"\";\n\tbuildWarning.value = \"\";\n\tcontainerError.value = \"\";\n\tsharedHomeEnabled.value = false;\n\tsharedHomeMode.value = \"off\";\n\tsharedHomePath.value = \"\";\n\tsharedHomeConfiguredPath.value = \"\";\n\tsharedHomeLoading.value = false;\n\tsharedHomeSaving.value = false;\n\tsharedHomeMsg.value = \"\";\n\tsharedHomeErr.value = \"\";\n\trender(<ImagesPage />, container);\n}\n\nexport function teardownImages(): void {\n\tif (_imagesContainer) render(null, _imagesContainer);\n\t_imagesContainer = null;\n}\n","// ── Logs page (Preact toolbar + imperative log area) ─────────\n\nimport { signal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect, useRef } from \"preact/hooks\";\nimport { sendRpc } from \"../helpers\";\nimport { t } from \"../i18n\";\nimport * as S from \"../state\";\nimport { ComboSelect } from \"../ui\";\n\ninterface LogEntry {\n\tts: string;\n\tlevel: string;\n\ttarget: string;\n\tmessage: string;\n\tfields?: Record<string, unknown>;\n}\n\ninterface LogsStatusPayload {\n\tenabled_levels?: Record<string, boolean>;\n}\n\ninterface ComboOption {\n\tvalue: string;\n\tlabel: string;\n}\n\nconst paused = signal(false);\nconst levelFilter = signal(\"\");\nconst targetFilter = signal(\"\");\nconst searchFilter = signal(\"\");\nconst entryCount = signal(0);\nconst debugEnabled = signal(false);\nconst traceEnabled = signal(false);\nconst maxEntries = 2000;\n\nfunction levelColor(level: string): string {\n\tconst l = level.toUpperCase();\n\tif (l === \"ERROR\") return \"var(--error)\";\n\tif (l === \"WARN\") return \"var(--warn)\";\n\tif (l === \"DEBUG\") return \"var(--muted)\";\n\tif (l === \"TRACE\") return \"color-mix(in oklab, var(--muted) 60%, transparent)\";\n\treturn \"var(--text)\";\n}\n\nfunction levelBg(level: string): string {\n\tconst l = level.toUpperCase();\n\tif (l === \"ERROR\") return \"rgba(239,68,68,0.08)\";\n\tif (l === \"WARN\") return \"rgba(245,158,11,0.06)\";\n\treturn \"transparent\";\n}\n\nfunction renderEntry(entry: LogEntry): HTMLDivElement {\n\tconst row = document.createElement(\"div\");\n\trow.className = \"logs-row\";\n\trow.style.background = levelBg(entry.level);\n\tconst ts = document.createElement(\"span\");\n\tts.className = \"logs-ts\";\n\tconst d = new Date(entry.ts);\n\tts.textContent =\n\t\td.toLocaleTimeString([], {\n\t\t\thour: \"2-digit\",\n\t\t\tminute: \"2-digit\",\n\t\t\tsecond: \"2-digit\",\n\t\t}) +\n\t\t\".\" +\n\t\tString(d.getMilliseconds()).padStart(3, \"0\");\n\tconst lvl = document.createElement(\"span\");\n\tlvl.className = \"logs-level\";\n\tlvl.style.color = levelColor(entry.level);\n\tlvl.textContent = entry.level.toUpperCase().substring(0, 5);\n\tconst tgt = document.createElement(\"span\");\n\ttgt.className = \"logs-target\";\n\ttgt.textContent = entry.target;\n\tconst msg = document.createElement(\"span\");\n\tmsg.className = \"logs-msg\";\n\tmsg.textContent = entry.message;\n\tif (entry.fields && Object.keys(entry.fields).length > 0) {\n\t\tmsg.textContent +=\n\t\t\t\" \" +\n\t\t\tObject.keys(entry.fields)\n\t\t\t\t.map((k) => `${k}=${entry.fields?.[k]}`)\n\t\t\t\t.join(\" \");\n\t}\n\trow.appendChild(ts);\n\trow.appendChild(lvl);\n\trow.appendChild(tgt);\n\trow.appendChild(msg);\n\treturn row;\n}\n\nfunction levelFilterOptions(): ComboOption[] {\n\tconst options: ComboOption[] = [];\n\tif (traceEnabled.value) options.push({ value: \"trace\", label: t(\"logs:levels.trace\") });\n\tif (debugEnabled.value) options.push({ value: \"debug\", label: t(\"logs:levels.debug\") });\n\toptions.push({ value: \"info\", label: t(\"logs:levels.info\") });\n\toptions.push({ value: \"warn\", label: t(\"logs:levels.warn\") });\n\toptions.push({ value: \"error\", label: t(\"logs:levels.error\") });\n\treturn options;\n}\n\nfunction Toolbar(): VNode {\n\tconst targetRef = useRef<HTMLInputElement>(null);\n\tconst searchRef = useRef<HTMLInputElement>(null);\n\tconst filterTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n\n\tfunction debouncedUpdate(setter: (v: string) => void, ref: { current: HTMLInputElement | null }): () => void {\n\t\treturn () => {\n\t\t\tif (filterTimer.current != null) clearTimeout(filterTimer.current);\n\t\t\tfilterTimer.current = setTimeout(() => {\n\t\t\t\tsetter(ref.current?.value || \"\");\n\t\t\t}, 300);\n\t\t};\n\t}\n\n\treturn (\n\t\t<div className=\"logs-toolbar\">\n\t\t\t<div className=\"logs-level-filter\">\n\t\t\t\t<ComboSelect\n\t\t\t\t\toptions={levelFilterOptions()}\n\t\t\t\t\tvalue={levelFilter.value}\n\t\t\t\t\tonChange={(value: string) => {\n\t\t\t\t\t\tlevelFilter.value = value;\n\t\t\t\t\t}}\n\t\t\t\t\tplaceholder={t(\"logs:toolbar.allLevels\")}\n\t\t\t\t\tsearchable={false}\n\t\t\t\t/>\n\t\t\t</div>\n\t\t\t<input\n\t\t\t\tref={targetRef}\n\t\t\t\ttype=\"text\"\n\t\t\t\tplaceholder={t(\"logs:toolbar.filterTarget\")}\n\t\t\t\tclassName=\"logs-input\"\n\t\t\t\tstyle={{ width: \"140px\" }}\n\t\t\t\tonInput={debouncedUpdate((v) => {\n\t\t\t\t\ttargetFilter.value = v;\n\t\t\t\t}, targetRef)}\n\t\t\t/>\n\t\t\t<input\n\t\t\t\tref={searchRef}\n\t\t\t\ttype=\"text\"\n\t\t\t\tplaceholder={t(\"common:actions.search\")}\n\t\t\t\tclassName=\"logs-input\"\n\t\t\t\tstyle={{ width: \"160px\" }}\n\t\t\t\tonInput={debouncedUpdate((v) => {\n\t\t\t\t\tsearchFilter.value = v;\n\t\t\t\t}, searchRef)}\n\t\t\t/>\n\t\t\t<button\n\t\t\t\tclassName=\"logs-btn\"\n\t\t\t\tonClick={() => {\n\t\t\t\t\tpaused.value = !paused.value;\n\t\t\t\t}}\n\t\t\t\tstyle={paused.value ? { borderColor: \"var(--warn)\" } : undefined}\n\t\t\t>\n\t\t\t\t{paused.value ? t(\"logs:toolbar.resume\") : t(\"logs:toolbar.pause\")}\n\t\t\t</button>\n\t\t\t<button\n\t\t\t\tclassName=\"logs-btn\"\n\t\t\t\tonClick={() => {\n\t\t\t\t\tconst area = document.getElementById(\"logsArea\");\n\t\t\t\t\tif (area) area.textContent = \"\";\n\t\t\t\t\tentryCount.value = 0;\n\t\t\t\t}}\n\t\t\t>\n\t\t\t\t{t(\"logs:toolbar.clear\")}\n\t\t\t</button>\n\t\t\t<a\n\t\t\t\thref=\"/api/logs/download\"\n\t\t\t\tclassName=\"logs-btn\"\n\t\t\t\tdownload=\"moltis-logs.jsonl\"\n\t\t\t\tstyle={{ textDecoration: \"none\", textAlign: \"center\" }}\n\t\t\t>\n\t\t\t\t{t(\"logs:toolbar.download\")}\n\t\t\t</a>\n\t\t\t<span className=\"logs-count\">\n\t\t\t\t{entryCount.value} {t(\"logs:toolbar.entries\")}\n\t\t\t</span>\n\t\t</div>\n\t);\n}\n\nfunction LogsPage(): VNode {\n\tconst logAreaRef = useRef<HTMLDivElement>(null);\n\n\tfunction updateEnabledLevels(statusPayload: LogsStatusPayload): void {\n\t\tconst enabled = statusPayload?.enabled_levels || {};\n\t\ttraceEnabled.value = !!enabled.trace;\n\t\tdebugEnabled.value = !!enabled.debug || traceEnabled.value;\n\t\tif (levelFilter.value === \"trace\" && !traceEnabled.value) levelFilter.value = \"\";\n\t\tif (levelFilter.value === \"debug\" && !debugEnabled.value) levelFilter.value = \"\";\n\t}\n\n\tfunction appendEntry(entry: LogEntry): void {\n\t\tconst area = logAreaRef.current;\n\t\tif (!area) return;\n\t\tconst row = renderEntry(entry);\n\t\tarea.appendChild(row);\n\t\tentryCount.value++;\n\t\twhile (area.childNodes.length > maxEntries) {\n\t\t\tarea.removeChild(area.firstChild!);\n\t\t\tentryCount.value--;\n\t\t}\n\t\tif (!paused.value) {\n\t\t\tconst atBottom = area.scrollHeight - area.scrollTop - area.clientHeight < 60;\n\t\t\tif (atBottom) area.scrollTop = area.scrollHeight;\n\t\t}\n\t}\n\n\tfunction matchesFilter(entry: LogEntry): boolean {\n\t\tif (levelFilter.value) {\n\t\t\tconst levels = [\"trace\", \"debug\", \"info\", \"warn\", \"error\"];\n\t\t\tif (levels.indexOf(entry.level.toLowerCase()) < levels.indexOf(levelFilter.value)) return false;\n\t\t}\n\t\tconst tgtVal = targetFilter.value.trim();\n\t\tif (tgtVal && entry.target.indexOf(tgtVal) === -1) return false;\n\t\tconst searchVal = searchFilter.value.trim().toLowerCase();\n\t\tif (\n\t\t\tsearchVal &&\n\t\t\tentry.message.toLowerCase().indexOf(searchVal) === -1 &&\n\t\t\tentry.target.toLowerCase().indexOf(searchVal) === -1\n\t\t)\n\t\t\treturn false;\n\t\treturn true;\n\t}\n\n\tfunction refetch(): void {\n\t\tconst area = logAreaRef.current;\n\t\tif (area) area.textContent = \"\";\n\t\tentryCount.value = 0;\n\t\tsendRpc(\"logs.list\", {\n\t\t\tlevel: levelFilter.value || undefined,\n\t\t\ttarget: targetFilter.value.trim() || undefined,\n\t\t\tsearch: searchFilter.value.trim() || undefined,\n\t\t\tlimit: 500,\n\t\t}).then((res) => {\n\t\t\tif (!res?.ok) return;\n\t\t\tconst entries: LogEntry[] = (res.payload as { entries?: LogEntry[] })?.entries || [];\n\t\t\tlet i = 0;\n\t\t\tconst batchSize = 100;\n\t\t\tfunction renderBatch(): void {\n\t\t\t\tconst end = Math.min(i + batchSize, entries.length);\n\t\t\t\twhile (i < end) appendEntry(entries[i++]);\n\t\t\t\tif (i < entries.length) requestAnimationFrame(renderBatch);\n\t\t\t\telse if (logAreaRef.current) logAreaRef.current.scrollTop = logAreaRef.current.scrollHeight;\n\t\t\t}\n\t\t\trenderBatch();\n\t\t});\n\t}\n\n\tuseEffect(() => {\n\t\tsendRpc(\"logs.status\", {})\n\t\t\t.then((res) => {\n\t\t\t\tif (!res?.ok) return;\n\t\t\t\tupdateEnabledLevels((res.payload as LogsStatusPayload) || {});\n\t\t\t})\n\t\t\t.catch(() => undefined);\n\t\trefetch();\n\t\tS.setLogsEventHandler(((entry: unknown) => {\n\t\t\tif (paused.value) return;\n\t\t\tconst e = entry as LogEntry;\n\t\t\tif (!matchesFilter(e)) return;\n\t\t\tappendEntry(e);\n\t\t}) as unknown as () => void);\n\t\treturn () => S.setLogsEventHandler(null);\n\t}, []);\n\n\t// Re-fetch when filters change\n\tuseEffect(() => {\n\t\trefetch();\n\t}, [levelFilter.value, targetFilter.value, searchFilter.value]);\n\n\treturn (\n\t\t<>\n\t\t\t<Toolbar />\n\t\t\t<div ref={logAreaRef} id=\"logsArea\" className=\"logs-area\" />\n\t\t</>\n\t);\n}\n\nlet _logsContainer: HTMLElement | null = null;\n\nexport function initLogs(container: HTMLElement): void {\n\t_logsContainer = container;\n\tcontainer.style.cssText = \"flex-direction:column;padding:0;overflow:hidden;\";\n\tpaused.value = false;\n\tlevelFilter.value = \"\";\n\ttargetFilter.value = \"\";\n\tsearchFilter.value = \"\";\n\tentryCount.value = 0;\n\tdebugEnabled.value = false;\n\ttraceEnabled.value = false;\n\trender(<LogsPage />, container);\n}\n\nexport function teardownLogs(): void {\n\tS.setLogsEventHandler(null);\n\tif (_logsContainer) render(null, _logsContainer);\n\t_logsContainer = null;\n}\n","// ── MCP page ────────────────────────────────────────────────\n\nimport { signal, useSignal } from \"@preact/signals\";\nimport type { VNode } from \"preact\";\nimport { render } from \"preact\";\nimport { useEffect } from \"preact/hooks\";\nimport { onEvent } from \"../events\";\nimport { sendRpc } from \"../helpers\";\nimport { updateNavCount } from \"../nav-counts\";\nimport { ConfirmDialog, requestConfirm } from \"../ui\";\n\n// ── Types ────────────────────────────────────────────────────\n\ninterface McpServer {\n\tname: string;\n\tdisplay_name?: string;\n\tstate?: string;\n\tenabled?: boolean;\n\ttransport?: string;\n\tcommand?: string;\n\targs?: string[];\n\tenv?: Record<string, string>;\n\turl?: string;\n\theaders?: Record<string, string>;\n\theader_names?: string[];\n\theaderNames?: string[];\n\theader_count?: number;\n\theaderCount?: number;\n\ttool_count?: number;\n\tauth_state?: string;\n\trequest_timeout_secs?: number | null;\n\tconfigured_request_timeout_secs?: number;\n}\n\ninterface McpTool {\n\tname: string;\n\tdescription?: string;\n}\ninterface ToastItem {\n\tid: number;\n\tmessage: string;\n\ttype: string;\n}\ninterface FeaturedServer {\n\tname: string;\n\trepo?: string;\n\tdesc: string;\n\tcommand?: string;\n\targs?: string[];\n\ttransport?: string;\n\turl?: string;\n\trequiresConfig?: boolean;\n\tenvKeys?: string[];\n\thint?: string;\n}\n\n// ── Signals ─────────────────────────────────────────────────\n\nconst servers = signal<McpServer[]>([]);\nconst loading = signal(false);\nconst configLoading = signal(false);\nconst configSaving = signal(false);\nconst requestTimeoutSecs = signal(\"30\");\nconst configDirty = signal(false);\nconst toasts = signal<ToastItem[]>([]);\nlet toastId = 0;\n\nfunction showToast(message: string, type: string): void {\n\tconst id = ++toastId;\n\ttoasts.value = [...toasts.value, { id, message, type }];\n\tsetTimeout(() => {\n\t\ttoasts.value = toasts.value.filter((t) => t.id !== id);\n\t}, 4000);\n}\n\nasync function refreshServers(): Promise<void> {\n\tloading.value = true;\n\ttry {\n\t\tconst res = await fetch(\"/api/mcp\");\n\t\tif (res.ok) servers.value = (await res.json()) || [];\n\t} catch {\n\t\tconst rpc = await sendRpc(\"mcp.list\", {});\n\t\tif (rpc.ok) servers.value = (rpc.payload as McpServer[]) || [];\n\t}\n\tloading.value = false;\n\tupdateNavCount(\"mcp\", servers.value.filter((s) => s.state === \"running\").length);\n}\n\nasync function refreshConfig(): Promise<void> {\n\tconfigLoading.value = true;\n\ttry {\n\t\tconst res = await sendRpc(\"mcp.config.get\", {});\n\t\tif (res?.ok && res.payload) {\n\t\t\trequestTimeoutSecs.value = String((res.payload as Record<string, number>).request_timeout_secs || 30);\n\t\t\tconfigDirty.value = false;\n\t\t}\n\t} finally {\n\t\tconfigLoading.value = false;\n\t}\n}\n\nfunction normalizeOptionalTimeout(rawValue: string): { ok: boolean; value: number | null; message?: string } {\n\tconst trimmed = String(rawValue || \"\").trim();\n\tif (!trimmed) return { ok: true, value: null };\n\tif (!/^\\d+$/.test(trimmed)) return { ok: false, value: null, message: \"Timeout must be a positive number\" };\n\tconst parsed = Number.parseInt(trimmed, 10);\n\tif (!Number.isFinite(parsed) || parsed <= 0)\n\t\treturn { ok: false, value: null, message: \"Timeout must be a positive number\" };\n\treturn { ok: true, value: parsed };\n}\n\nfunction resolveTimeoutOrAbort(\n\trawValue: string,\n\tsetBusy: (v: boolean) => void,\n): { ok: boolean; value?: number | null } {\n\tconst t = normalizeOptionalTimeout(rawValue);\n\tif (!t.ok) {\n\t\tshowToast(t.message || \"Invalid timeout\", \"error\");\n\t\tsetBusy(false);\n\t\treturn { ok: false };\n\t}\n\treturn { ok: true, value: t.value };\n}\n\nasync function saveConfig(): Promise<void> {\n\tconst t = normalizeOptionalTimeout(requestTimeoutSecs.value);\n\tif (!t.ok || t.value === null) {\n\t\tshowToast(\"MCP request timeout must be a positive number\", \"error\");\n\t\treturn;\n\t}\n\tconfigSaving.value = true;\n\ttry {\n\t\tconst res = await sendRpc(\"mcp.config.update\", { request_timeout_secs: t.value });\n\t\tif (res?.ok) {\n\t\t\trequestTimeoutSecs.value = String((res.payload as Record<string, number>)?.request_timeout_secs || t.value);\n\t\t\tconfigDirty.value = false;\n\t\t\tshowToast(\"Saved MCP settings. Restart servers to apply.\", \"success\");\n\t\t} else showToast(`Failed: ${res?.error?.message || \"unknown\"}`, \"error\");\n\t} finally {\n\t\tconfigSaving.value = false;\n\t}\n}\n\nfunction oauthCallbackUrl(): string {\n\treturn `${window.location.origin}/auth/callback`;\n}\n\nasync function addServer(payload: Record<string, unknown>): Promise<void> {\n\tconst req = { ...payload };\n\tconst t = (payload.transport as string) || \"stdio\";\n\tif (t === \"sse\" || t === \"streamable-http\") (req as Record<string, string>).redirectUri = oauthCallbackUrl();\n\tconst res = await sendRpc(\"mcp.add\", req);\n\tif (res?.ok) {\n\t\tconst p = res.payload as Record<string, unknown>;\n\t\tshowToast(`Added MCP tool \"${p?.name || payload.name}\"`, \"success\");\n\t\tif (p?.oauthPending && p?.authUrl) window.open(p.authUrl as string, \"_blank\", \"noopener,noreferrer\");\n\t} else showToast(`Failed to add \"${payload.name}\": ${res?.error?.message || \"unknown\"}`, \"error\");\n\tawait refreshServers();\n}\n\nfunction parseEnvLines(text: string): Record<string, string> {\n\tconst env: Record<string, string> = {};\n\tif (!text) return env;\n\tfor (const line of text.split(\"\\n\")) {\n\t\tconst trimmed = line.trim();\n\t\tif (!trimmed || trimmed.startsWith(\"#\")) continue;\n\t\tconst idx = trimmed.indexOf(\"=\");\n\t\tif (idx > 0) env[trimmed.slice(0, idx).trim()] = trimmed.slice(idx + 1).trim();\n\t}\n\treturn env;\n}\n\nfunction transportLabel(transport: string | undefined): string {\n\tif (transport === \"streamable-http\") return \"streamable-http remote\";\n\treturn transport === \"sse\" ? \"sse remote\" : \"stdio local\";\n}\nfunction deriveNameFromCommand(cmdLine: string): string {\n\tconst parts = cmdLine.trim().split(/\\s+/).filter(Boolean);\n\tfor (let i = parts.length - 1; i >= 0; i--) {\n\t\tconst tk = parts[i];\n\t\tif (tk.startsWith(\"-\")) continue;\n\t\tlet base = tk.includes(\"/\") ? tk.split(\"/\").pop()! : tk;\n\t\tbase = base\n\t\t\t.replace(/^mcp-server-/, \"\")\n\t\t\t.replace(/^server-/, \"\")\n\t\t\t.replace(/^mcp-/, \"\");\n\t\tif (base) return base.toLowerCase().replace(/[^a-z0-9-]/g, \"-\");\n\t}\n\treturn parts[0] || \"\";\n}\nfunction deriveSseName(url: string): string {\n\tif (!url) return \"\";\n\ttry {\n\t\tconst parts = new URL(url.trim()).hostname.split(\".\").filter((p) => p !== \"mcp\" && p !== \"www\");\n\t\treturn parts.length > 0 ? parts[0].toLowerCase() : \"\";\n\t} catch {\n\t\treturn \"\";\n\t}\n}\nfunction remoteHeaderNames(server: McpServer): string[] {\n\treturn (server.header_names || server.headerNames || (server.headers ? Object.keys(server.headers) : []))\n\t\t.filter((n) => typeof n === \"string\" && n.trim())\n\t\t.map((n) => n.trim());\n}\nfunction remoteHeaderCount(server: McpServer): number {\n\tconst ec = server.header_count ?? server.headerCount;\n\tif (ec != null && Number.isFinite(ec) && ec >= 0) return ec;\n\treturn remoteHeaderNames(server).length;\n}\nfunction remoteHeaderSummary(server: McpServer): string {\n\tconst names = remoteHeaderNames(server);\n\tconst count = remoteHeaderCount(server);\n\tif (!(count || names.length)) return \"none configured\";\n\tif (!names.length) return `${count} configured`;\n\treturn `${names.join(\", \")} (${count} total)`;\n}\n\n// ── Featured MCP servers ────────────────────────────────────\n\nconst featuredServers: FeaturedServer[] = [\n\t{\n\t\tname: \"filesystem\",\n\t\trepo: \"modelcontextprotocol/servers\",\n\t\tdesc: \"Secure file operations\",\n\t\tcommand: \"npx\",\n\t\targs: [\"-y\", \"@modelcontextprotocol/server-filesystem\", \"/tmp\"],\n\t\trequiresConfig: true,\n\t\thint: \"Last arg is the allowed directory path\",\n\t},\n\t{\n\t\tname: \"memory\",\n\t\trepo: \"modelcontextprotocol/servers\",\n\t\tdesc: \"Knowledge graph-based persistent memory\",\n\t\tcommand: \"npx\",\n\t\targs: [\"-y\", \"@modelcontextprotocol/server-memory\"],\n\t},\n\t{\n\t\tname: \"github\",\n\t\trepo: \"modelcontextprotocol/servers\",\n\t\tdesc: \"GitHub API integration\",\n\t\tcommand: \"npx\",\n\t\targs: [\"-y\", \"@modelcontextprotocol/server-github\"],\n\t\trequiresConfig: true,\n\t\tenvKeys: [\"GITHUB_PERSONAL_ACCESS_TOKEN\"],\n\t\thint: \"Requires a GitHub personal access token\",\n\t},\n\t{\n\t\tname: \"linear\",\n\t\trepo: \"linear/linear\",\n\t\tdesc: \"Remote Linear MCP server with browser OAuth\",\n\t\ttransport: \"sse\",\n\t\turl: \"https://mcp.linear.app/mcp\",\n\t\thint: \"After adding, click Enable and complete OAuth\",\n\t},\n];\n\n// ── Components ──────────────────────────────────────────────\n\nfunction Toasts(): VNode {\n\treturn (\n\t\t<div className=\"skills-toast-container\">\n\t\t\t{toasts.value.map((t) => {\n\t\t\t\tconst cls = t.type === \"error\" ? \"bg-[var(--error)]\" : \"bg-[var(--accent)]\";\n\t\t\t\treturn (\n\t\t\t\t\t<div\n\t\t\t\t\t\tkey={t.id}\n\t\t\t\t\t\tclassName={`pointer-events-auto max-w-[420px] px-4 py-2.5 rounded-md text-xs font-medium text-white shadow-lg ${cls}`}\n\t\t\t\t\t>\n\t\t\t\t\t\t{t.message}\n\t\t\t\t\t</div>\n\t\t\t\t);\n\t\t\t})}\n\t\t</div>\n\t);\n}\n\nfunction StatusBadge({ state }: { state?: string }): VNode {\n\tconst colors: Record<string, string> = {\n\t\trunning: \"bg-[var(--ok)]\",\n\t\tstopped: \"bg-[var(--muted)]\",\n\t\tdead: \"bg-[var(--error)]\",\n\t\tconnecting: \"bg-[var(--warn)]\",\n\t};\n\treturn <span className={`inline-block w-2 h-2 rounded-full ${colors[state || \"stopped\"] || colors.stopped}`} />;\n}\n\nfunction FeaturedCard({ server: f }: { server: FeaturedServer }): VNode {\n\tconst installing = useSignal(false);\n\tconst configuring = useSignal(false);\n\tconst argsVal = useSignal((f.args || []).join(\" \"));\n\tconst envVal = useSignal((f.envKeys || []).map((k) => `${k}=`).join(\"\\n\"));\n\tconst urlVal = useSignal(f.url || \"\");\n\tconst headerVal = useSignal(\"\");\n\tconst timeoutVal = useSignal(\"\");\n\tconst needsConfig = Boolean(\n\t\tf.requiresConfig || f.envKeys?.length || f.transport === \"sse\" || f.transport === \"streamable-http\",\n\t);\n\tconst isSse = f.transport === \"sse\" || f.transport === \"streamable-http\";\n\n\tfunction onAdd(): void {\n\t\tif (needsConfig && !configuring.value) {\n\t\t\tconfiguring.value = true;\n\t\t\treturn;\n\t\t}\n\t\tinstalling.value = true;\n\t\tconst tr = resolveTimeoutOrAbort(timeoutVal.value, (v) => {\n\t\t\tinstalling.value = v;\n\t\t});\n\t\tif (!tr.ok) return;\n\t\tif (isSse) {\n\t\t\tconst url = (urlVal.value || \"\").trim();\n\t\t\tif (!url) {\n\t\t\t\tshowToast(\"URL required\", \"error\");\n\t\t\t\tinstalling.value = false;\n\t\t\t\treturn;\n\t\t\t}\n\t\t\taddServer({\n\t\t\t\theaders: parseEnvLines(headerVal.value),\n\t\t\t\tname: f.name,\n\t\t\t\tcommand: \"\",\n\t\t\t\targs: [],\n\t\t\t\ttransport: \"sse\",\n\t\t\t\turl,\n\t\t\t\trequest_timeout_secs: tr.value,\n\t\t\t}).finally(() => {\n\t\t\t\tinstalling.value = false;\n\t\t\t\tconfiguring.value = false;\n\t\t\t});\n\t\t\treturn;\n\t\t}\n\t\taddServer({\n\t\t\tname: f.name,\n\t\t\tcommand: f.command,\n\t\t\targs: argsVal.value.split(/\\s+/).filter(Boolean),\n\t\t\tenv: parseEnvLines(envVal.value),\n\t\t\trequest_timeout_secs: tr.value,\n\t\t}).finally(() => {\n\t\t\tinstalling.value = false;\n\t\t\tconfiguring.value = false;\n\t\t});\n\t}\n\n\treturn (\n\t\t<div className=\"mb-1\">\n\t\t\t<div className=\"provider-item\">\n\t\t\t\t<div className=\"flex-1 min-w-0\">\n\t\t\t\t\t<div className=\"provider-item-name font-mono text-sm\">{f.name}</div>\n\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mt-0.5 flex gap-3 items-center\">\n\t\t\t\t\t\t<span>{f.desc}</span>\n\t\t\t\t\t\t<span className=\"text-[0.6rem] px-1.5 py-px rounded-full bg-[var(--surface2)] text-[var(--muted)] font-medium\">\n\t\t\t\t\t\t\t{transportLabel(f.transport)}\n\t\t\t\t\t\t</span>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t<button\n\t\t\t\t\tonClick={onAdd}\n\t\t\t\t\tdisabled={installing.value}\n\t\t\t\t\tclassName=\"shrink-0 whitespace-nowrap provider-btn provider-btn-sm\"\n\t\t\t\t>\n\t\t\t\t\t{installing.value ? \"Adding\\u2026\" : configuring.value ? \"Confirm\" : needsConfig ? \"Configure\" : \"Add\"}\n\t\t\t\t</button>\n\t\t\t</div>\n\t\t\t{configuring.value && (\n\t\t\t\t<div className=\"px-3 pb-3 border border-t-0 border-[var(--border)] rounded-b-[var(--radius-sm)]\">\n\t\t\t\t\t{isSse ? (\n\t\t\t\t\t\t<>\n\t\t\t\t\t\t\t<div className=\"project-edit-group\">\n\t\t\t\t\t\t\t\t<div className=\"text-xs text-[var(--muted)] mb-1\">Server URL</div>\n\t\t\t\t\t\t\t\t<input\n\t\t\t\t\t\t\t\t\ttype=\"text\"\n\t\t\t\t\t\t\t\t\tvalue={urlVal.value}\n\t\t\t\t\t\t\t\t\tonInput={(e) => {\n\t\t\t\t\t\t\t\t\t\turlVal.value = (e.target as HTMLInputElement).value;\n\t\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\t\tclassName=\"provider-key-input